```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three.js Cat</title>
<style>*{margin:0;padding:0;box-sizing:border-box}</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Fog(0x1a1a2e, 10, 25);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2.5, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;

// ── Lights ─────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x6666aa, 0.8));

const dir = new THREE.DirectionalLight(0xffeedd, 1.5);
dir.position.set(4, 8, 4);
dir.castShadow = true;
dir.shadow.mapSize.set(1024, 1024);
dir.shadow.camera.near = 1;
dir.shadow.camera.far = 20;
dir.shadow.camera.left = -4;
dir.shadow.camera.right = 4;
dir.shadow.camera.top = 4;
dir.shadow.camera.bottom = -4;
scene.add(dir);

const rim = new THREE.DirectionalLight(0x4488ff, 0.6);
rim.position.set(-3, 4, -4);
scene.add(rim);

// ── Materials ──────────────────────────────────────────
const fur      = new THREE.MeshStandardMaterial({ color: 0x4a4a4a, roughness: 0.85 });
const furLight = new THREE.MeshStandardMaterial({ color: 0x6a6a6a, roughness: 0.85 });
const pink     = new THREE.MeshStandardMaterial({ color: 0xff8899, roughness: 0.5 });
const eyeMat   = new THREE.MeshStandardMaterial({ color: 0x33cc44, roughness: 0.2, metalness: 0.3 });
const pupilMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.3 });
const noseMat  = new THREE.MeshStandardMaterial({ color: 0xff6688, roughness: 0.4 });
const whiteMat = new THREE.MeshStandardMaterial({ color: 0xeeeeee, roughness: 0.7 });

// ── Cat Group ──────────────────────────────────────────
const cat = new THREE.Group();

// Body
const body = new THREE.Mesh(new THREE.SphereGeometry(0.7, 24, 24), fur);
body.scale.set(1, 0.8, 1.3);
body.position.set(0, 1.1, 0);
body.castShadow = true;
cat.add(body);

// Chest (lighter fur)
const chest = new THREE.Mesh(new THREE.SphereGeometry(0.45, 24, 24), furLight);
chest.scale.set(1, 0.9, 0.8);
chest.position.set(0, 1.15, 0.55);
cat.add(chest);

// Head
const head = new THREE.Mesh(new THREE.SphereGeometry(0.5, 24, 24), fur);
head.position.set(0, 1.95, 0.65);
head.castShadow = true;
cat.add(head);

// Muzzle (lighter area)
const muzzle = new THREE.Mesh(new THREE.SphereGeometry(0.22, 16, 16), furLight);
muzzle.scale.set(1.1, 0.7, 1);
muzzle.position.set(0, 1.8, 1.05);
cat.add(muzzle);

// Ears
function makeEar(side) {
  const g = new THREE.Group();
  const outer = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.35, 4), fur);
  outer.position.set(side * 0.28, 2.45, 0.55);
  outer.rotation.z = side * -0.3;
  outer.rotation.x = -0.15;
  outer.castShadow = true;
  g.add(outer);
  const inner = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.22, 4), pink);
  inner.position.set(side * 0.28, 2.42, 0.58);
  inner.rotation.z = side * -0.3;
  inner.rotation.x = -0.15;
  g.add(inner);
  return g;
}
cat.add(makeEar(-1));
cat.add(makeEar(1));

// Eyes
function makeEye(side) {
  const g = new THREE.Group();
  const eye = new THREE.Mesh(new THREE.SphereGeometry(0.09, 16, 16), eyeMat);
  eye.position.set(side * 0.2, 2.02, 1.08);
  g.add(eye);
  const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.05, 16, 16), pupilMat);
  pupil.position.set(side * 0.2, 2.02, 1.15);
  g.add(pupil);
  // Eye shine
  const shine = new THREE.Mesh(new THREE.SphereGeometry(0.025, 8, 8), whiteMat);
  shine.position.set(side * 0.24, 2.06, 1.17);
  g.add(shine);
  return g;
}
cat.add(makeEye(-1));
cat.add(makeEye(1));

// Nose
const nose = new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 8), noseMat);
nose.scale.set(1.3, 1, 1);
nose.position.set(0, 1.87, 1.15);
cat.add(nose);

// Mouth (simple line using thin tube)
const mouthCurve = new THREE.QuadraticBezierCurve3(
  new THREE.Vector3(-0.08, 1.82, 1.13),
  new THREE.Vector3(0, 1.79, 1.16),
  new THREE.Vector3(0.08, 1.82, 1.13)
);
const mouth = new THREE.Mesh(
  new THREE.TubeGeometry(mouthCurve, 8, 0.008, 4, false),
  new THREE.MeshStandardMaterial({ color: 0x333333 })
);
cat.add(mouth);

// Whiskers
function makeWhisker(x, y, z, angleY, angleX, angleZ) {
  const curve = new THREE.LineCurve3(
    new THREE.Vector3(x, y, z),
    new THREE.Vector3(x + Math.cos(angleY) * 0.5, y + Math.sin(angleX) * 0.15, z + Math.sin(angleZ) * 0.1)
  );
  return new THREE.Mesh(
    new THREE.TubeGeometry(curve, 4, 0.004, 4, false),
    new THREE.MeshStandardMaterial({ color: 0xcccccc })
  );
}
const whiskerAngles = [
  [0.3, 0.1, 1.1, 0.4, 0.1, -0.1],
  [0.3, 0.08, 1.1, 0.0, 0.1, 0.0],
  [0.3, 0.06, 1.1, -0.4, 0.1, 0.1],
  [-0.3, 0.1, 1.1, -0.4, 0.1, 0.1],
  [-0.3, 0.08, 1.1, 0.0, 0.1, 0.0],
  [-0.3, 0.06, 1.1, 0.4, 0.1, -0.1],
];
whiskerAngles.forEach(a => cat.add(makeWhisker(...a)));

// Legs
function makeLeg(x, z, scaleY) {
  const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.11, 0.6, 12), fur);
  leg.position.set(x, scaleY, z);
  leg.castShadow = true;
  // Paw
  const paw = new THREE.Mesh(new THREE.SphereGeometry(0.11, 12, 12), furLight);
  paw.scale.set(1, 0.6, 1.2);
  paw.position.set(x, 0.05, z);
  cat.add(paw);
  return leg;
}
cat.add(makeLeg(-0.3, 0.4, 0.6));   // front L
cat.add(makeLeg(0.3, 0.4, 0.6));    // front R
cat.add(makeLeg(-0.3, -0.3, 0.55)); // back L
cat.add(makeLeg(0.3, -0.3, 0.55));  // back R

// Tail
const tailCurve = new THREE.CubicBezierCurve3(
  new THREE.Vector3(0, 1.2, -0.7),
  new THREE.Vector3(0, 1.6, -1.4),
  new THREE.Vector3(0.3, 2.0, -1.6),
  new THREE.Vector3(0.4, 2.3, -1.3)
);
const tail = new THREE.Mesh(
  new THREE.TubeGeometry(tailCurve, 20, 0.07, 8, false),
  fur
);
tail.castShadow = true;
cat.add(tail);

// Belly stripe (lighter patch)
const belly = new THREE.Mesh(new THREE.SphereGeometry(0.35, 16, 16), furLight);
belly.scale.set(0.8, 0.6, 1.2);
belly.position.set(0, 0.7, 0.3);
cat.add(belly);

scene.add(cat);

// ── Ground ─────────────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(8, 48),
  new THREE.MeshStandardMaterial({ color: 0x222244, roughness: 0.9 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ── Floating particles ────────────────────────────────
const particleCount = 60;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3]     = (Math.random() - 0.5) * 12;
  positions[i * 3 + 1] = Math.random() * 6;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 12;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particles = new THREE.Points(
  particleGeo,
  new THREE.PointsMaterial({ color: 0x8888cc, size: 0.04, transparent: true, opacity: 0.6 })
);
scene.add(particles);

// ── Animation ──────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle idle breathing
  cat.position.y = Math.sin(t * 1.5) * 0.03;

  // Tail wag
  tail.rotation.y = Math.sin(t * 2) * 0.15;

  // Head slight tilt
  head.rotation.z = Math.sin(t * 0.8) * 0.05;
  head.rotation.y = Math.sin(t * 0.5) * 0.08;

  // Floating particles
  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    pos[i * 3 + 1] += 0.003;
    if (pos[i * 3 + 1] > 6) pos[i * 3 + 1] = 0;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ─────────────────────────────────────────────
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What's inside

| Feature | Details |
|---|---|
| **Cat model** | Built entirely from Three.js primitives — spheres, cones, cylinders, and tube geometries |
| **Body parts** | Body, chest, head, muzzle, 2 ears (inner + outer), 2 eyes with pupils & shine, nose, mouth curve, 6 whiskers, 4 legs with paws, tail, belly stripe |
| **Materials** | Dark grey fur (`#4a4a4a`), lighter under-fur, pink inner ears, green eyes, pink nose |
| **Lighting** | Ambient + directional (with soft shadows) + blue rim light |
| **Animation** | Gentle breathing bob, tail wag, subtle head tilt, floating particles |
| **Controls** | `OrbitControls` — click-drag to rotate, scroll to zoom |
| **Ground** | Dark circle plane receiving shadows |

Save it as `index.html` and open in any modern browser — no build step needed.

