<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Dog Demo</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: white;
            font-family: sans-serif;
            pointer-events: none;
            text-shadow: 1px 1px 2px black;
        }
    </style>
</head>
<body>
    <div id="info">🐕 Drag to orbit - Scroll to zoom</div>

    <!-- Import Three.js as an ES module from a CDN -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue background
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        // 2. Camera
        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 3, 6);

        // 3. Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // 4. Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 1, 0);

        // 5. Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // 6. Ground
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x4caf50 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // 7. Build the Dog (Procedural Geometry)
        const dogGroup = new THREE.Group();
        const furColor = 0x8B4513; // SaddleBrown
        const darkFurColor = 0x5D4037;
        const noseColor = 0x111111;
        const eyeColor = 0x000000;
        const eyeWhiteColor = 0xFFFFFF;

        const furMaterial = new THREE.MeshStandardMaterial({ color: furColor });
        const darkFurMaterial = new THREE.MeshStandardMaterial({ color: darkFurColor });
        const noseMaterial = new THREE.MeshStandardMaterial({ color: noseColor });
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: eyeColor });
        const eyeWhiteMaterial = new THREE.MeshStandardMaterial({ color: eyeWhiteColor });

        // Body
        const bodyGeo = new THREE.BoxGeometry(1.5, 1, 0.8);
        const body = new THREE.Mesh(bodyGeo, furMaterial);
        body.position.set(0, 1, 0);
        body.castShadow = true;
        dogGroup.add(body);

        // Head
        const headGeo = new THREE.BoxGeometry(0.7, 0.7, 0.7);
        const head = new THREE.Mesh(headGeo, furMaterial);
        head.position.set(0.9, 1.6, 0);
        head.castShadow = true;
        dogGroup.add(head);

        // Snout
        const snoutGeo = new THREE.BoxGeometry(0.4, 0.3, 0.4);
        const snout = new THREE.Mesh(snoutGeo, darkFurMaterial);
        snout.position.set(1.3, 1.45, 0);
        snout.castShadow = true;
        dogGroup.add(snout);

        // Nose
        const noseGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const nose = new THREE.Mesh(noseGeo, noseMaterial);
        nose.position.set(1.5, 1.5, 0);
        dogGroup.add(nose);

        // Ears
        const earGeo = new THREE.ConeGeometry(0.15, 0.4, 4);
        const earL = new THREE.Mesh(earGeo, darkFurMaterial);
        earL.position.set(0.7, 2.1, 0.25);
        earL.rotation.z = -0.2;
        earL.rotation.x = 0.2;
        dogGroup.add(earL);

        const earR = new THREE.Mesh(earGeo, darkFurMaterial);
        earR.position.set(0.7, 2.1, -0.25);
        earR.rotation.z = -0.2;
        earR.rotation.x = -0.2;
        dogGroup.add(earR);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const eyeWhiteGeo = new THREE.SphereGeometry(0.12, 16, 16);

        const eyeLWhite = new THREE.Mesh(eyeWhiteGeo, eyeWhiteMaterial);
        eyeLWhite.position.set(1.1, 1.7, 0.2);
        dogGroup.add(eyeLWhite);
        const eyeL = new THREE.Mesh(eyeGeo, eyeMaterial);
        eyeL.position.set(1.15, 1.7, 0.2);
        dogGroup.add(eyeL);

        const eyeRWhite = new THREE.Mesh(eyeWhiteGeo, eyeWhiteMaterial);
        eyeRWhite.position.set(1.1, 1.7, -0.2);
        dogGroup.add(eyeRWhite);
        const eyeR = new THREE.Mesh(eyeGeo, eyeMaterial);
        eyeR.position.set(1.15, 1.7, -0.2);
        dogGroup.add(eyeR);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.15, 0.15, 1, 16);
        const legPositions = [
            { x: 0.5, z: 0.3 }, { x: 0.5, z: -0.3 },
            { x: -0.5, z: 0.3 }, { x: -0.5, z: -0.3 }
        ];

        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, furMaterial);
            leg.position.set(pos.x, 0.5, pos.z);
            leg.castShadow = true;
            dogGroup.add(leg);
        });

        // Tail
        const tailGeo = new THREE.CylinderGeometry(0.05, 0.1, 0.6, 8);
        const tail = new THREE.Mesh(tailGeo, furMaterial);
        tail.position.set(-0.9, 1.3, 0);
        tail.rotation.z = Math.PI / 4;
        tail.castShadow = true;
        dogGroup.add(tail);

        scene.add(dogGroup);

        // 8. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Simple idle animation
            const time = Date.now() * 0.002;
            tail.rotation.z = (Math.PI / 4) + Math.sin(time) * 0.2;
            body.position.y = 1 + Math.sin(time * 2) * 0.05; // Breathing

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
