  <title>Three.js Chair</title>
  <style>body{margin:0;overflow:hidden;background:#f0f0f0}</style>
</head>
<body>
  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf0f0f0);
    const camera = new THREE.PerspectiveCamera(50, window.innerWidth/window.innerHeight, 0.1, 100);
    camera.position.set(3, 2, 4);
    camera.lookAt(0, 0.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xffffff, 0.6));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 8, 5);
    dirLight.castShadow = true;
    scene.add(dirLight);

    const chair = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color: 0x8B4513 });

    // Seat
    const seat = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.1, 1.2), mat);
    seat.position.y = 0.6;
    seat.castShadow = true;
    chair.add(seat);

    // Backrest
    const back = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1, 0.1), mat);
    back.position.set(0, 1.15, -0.55);
    back.castShadow = true;
    chair.add(back);

    // Legs
    const legGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.6);
    [[-0.5,0.3,-0.5],[0.5,0.3,-0.5],[-0.5,0.3,0.5],[0.5,0.3,0.5]].forEach(p => {
      const leg = new THREE.Mesh(legGeo, mat);
      leg.position.set(...p);
      leg.castShadow = true;
      chair.add(leg);
    });

    scene.add(chair);

    // Ground
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshStandardMaterial({ color: 0xdddddd }));
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    function animate() {
      requestAnimationFrame(animate);
      chair.rotation.y += 0.005;
      renderer.render(scene, camera);
    }
    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
