canvas { display: block; }
#info {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  color: #fff;
  font-family: system-ui, sans-serif;
  font-size: 14px;
  background: rgba(0,0,0,0.45);
  padding: 8px 18px;
  border-radius: 20px;
  pointer-events: none;
  user-select: none;
}
</style>
</head>
<body>
<div id="info">🌳 Drag to orbit · Scroll to zoom</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ── Scene, Camera, Renderer ── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.FogExp2(0x87CEEB, 0.012);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
camera.position.set(12, 8, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 4, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI / 2.05;
controls.minDistance = 5;
controls.maxDistance = 40;
controls.update();

/* ── Lighting ── */
const ambientLight = new THREE.AmbientLight(0x6688aa, 0.6);
scene.add(ambientLight);

const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x445522, 0.5);
scene.add(hemiLight);

const sunLight = new THREE.DirectionalLight(0xffeedd, 2.5);
sunLight.position.set(10, 20, 8);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.left = -15;
sunLight.shadow.camera.right = 15;
sunLight.shadow.camera.top = 15;
sunLight.shadow.camera.bottom = -15;
sunLight.shadow.camera.near = 1;
sunLight.shadow.camera.far = 50;
sunLight.shadow.bias = -0.001;
scene.add(sunLight);

const fillLight = new THREE.DirectionalLight(0x8899bb, 0.6);
fillLight.position.set(-8, 10, -6);
scene.add(fillLight);

/* ── Ground ── */
const groundGeo = new THREE.CircleGeometry(60, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x4a7c3f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

/* ── Tree Materials ── */
const trunkMaterial = new THREE.MeshStandardMaterial({
  color: 0x5c3a1e,
  roughness: 0.9,
  metalness: 0.0,
});

const branchMaterial = new THREE.MeshStandardMaterial({
  color: 0x6b4423,
  roughness: 0.85,
  metalness: 0.0,
});

const leafMaterials = [
  new THREE.MeshStandardMaterial({ color: 0x2d6e1e, roughness: 0.8 }),
  new THREE.MeshStandardMaterial({ color: 0x3a8a2a, roughness: 0.8 }),
  new THREE.MeshStandardMaterial({ color: 0x4a9e35, roughness: 0.8 }),
  new THREE.MeshStandardMaterial({ color: 0x357a25, roughness: 0.8 }),
  new THREE.MeshStandardMaterial({ color: 0x55a840, roughness: 0.8 }),
];

/* ── Shared Geometries ── */
const leafGeom = new THREE.IcosahedronGeometry(1, 1);
const leafGeomSmall = new THREE.IcosahedronGeometry(1, 0);

/* ── Tree Generation ── */
const treeGroup = new THREE.Group();
scene.add(treeGroup);

function createBranch(parent, origin, direction, length, radius, depth, maxDepth) {
  if (depth > maxDepth || radius < 0.02) return;

  // Cylinder geometry
  const segments = Math.max(6, Math.floor(12 - depth * 1.2));
  const geo = new THREE.CylinderGeometry(
    radius * 0.75, radius, length, segments
  );
  geo.translate(0, length / 2, 0);

  const mat = depth < 2 ? trunkMaterial : branchMaterial;
  const mesh = new THREE.Mesh(geo, mat);

  // Orient branch
  const up = new THREE.Vector3(0, 1, 0);
  const quat = new THREE.Quaternion().setFromUnitVectors(up, direction.clone().normalize());
  mesh.quaternion.copy(quat);
  mesh.position.copy(origin);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);

  // End of branch
  const end = origin.clone().add(direction.clone().multiplyScalar(length));

  if (depth >= maxDepth - 1) {
    // Add leaf clusters
    const clusterCount = 3 + Math.floor(Math.random() * 4);
    for (let i = 0; i < clusterCount; i++) {
      const size = 0.4 + Math.random() * 0.8;
      const geom = Math.random() > 0.5 ? leafGeom : leafGeomSmall;
      const leafMesh = new THREE.Mesh(geom, leafMaterials[Math.floor(Math.random() * leafMaterials.length)]);
      leafMesh.position.copy(end);
      leafMesh.position.x += (Math.random() - 0.5) * 1.5;
      leafMesh.position.y += (Math.random() - 0.5) * 1.2;
      leafMesh.position.z += (Math.random() - 0.5) * 1.5;
      leafMesh.scale.setScalar(size);
      leafMesh.castShadow = true;
      leafMesh.receiveShadow = true;
      parent.add(leafMesh);
    }
    return;
  }

  // Sub-branches
  const numBranches = depth < 2 ? 3 : 2 + (Math.random() > 0.6 ? 1 : 0);
  const spreadAngle = depth < 2 ? 0.55 : 0.4 + Math.random() * 0.25;
  const lengthFactor = 0.62 + Math.random() * 0.12;
  const radiusFactor = 0.55 + Math.random() * 0.1;

  for (let i = 0; i < numBranches; i++) {
    const angle = (Math.PI * 2 / numBranches) * i + (Math.random() - 0.5) * 0.8;
    const tiltX = (Math.random() - 0.5) * spreadAngle;
    const tiltZ = (Math.random() - 0.5) * spreadAngle;

    const newDir = direction.clone().normalize();
    newDir.applyAxisAngle(new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle)).normalize(), spreadAngle * (0.5 + Math.random() * 0.5));
    newDir.y += 0.15 + Math.random() * 0.15;
    newDir.normalize();

    const newLength = length * lengthFactor;
    const newRadius = radius * radiusFactor;

    createBranch(parent, end, newDir, newLength, newRadius, depth + 1, maxDepth);
  }
}

// Build the tree
const maxDepth = 7;
const trunkLength = 3.5;
const trunkRadius = 0.45;

createBranch(
  treeGroup,
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(0, 1, 0),
  trunkLength,
  trunkRadius,
  0,
  maxDepth
);

/* ── Small decorative bushes ── */
function createBush(x, z, size) {
  const bushGroup = new THREE.Group();
  const count = 3 + Math.floor(Math.random() * 3);
  for (let i = 0; i < count; i++) {
    const s = size * (0.6 + Math.random() * 0.6);
    const mesh = new THREE.Mesh(leafGeom, leafMaterials[Math.floor(Math.random() * leafMaterials.length)]);
    mesh.position.set(
      (Math.random() - 0.5) * size,
      s * 0.5,
      (Math.random() - 0.5) * size
    );
    mesh.scale.setScalar(s);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    bushGroup.add(mesh);
  }
  bushGroup.position.set(x, 0, z);
  scene.add(bushGroup);
}

createBush(4, 3, 0.6);
createBush(-3.5, 4, 0.5);
createBush(5, -2, 0.7);
createBush(-4, -3, 0.55);
createBush(2, -5, 0.65);

/* ── Grass patches ── */
const grassGeo = new THREE.ConeGeometry(0.08, 0.4, 4);
const grassMat = new THREE.MeshStandardMaterial({ color: 0x3d8b37, roughness: 1 });
const grassInstanced = new THREE.InstancedMesh(grassGeo, grassMat, 3000);
const dummy = new THREE.Object3D();
let grassIdx = 0;
for (let i = 0; i < 3000; i++) {
  const angle = Math.random() * Math.PI * 2;
  const dist = 1.5 + Math.random() * 25;
  dummy.position.set(Math.cos(angle) * dist, 0.2, Math.sin(angle) * dist);
  dummy.scale.set(0.8 + Math.random() * 0.6, 0.5 + Math.random() * 1.2, 0.8 + Math.random() * 0.6);
  dummy.rotation.set((Math.random() - 0.5) * 0.3, Math.random() * Math.PI * 2, (Math.random() - 0.5) * 0.3);
  dummy.updateMatrix();
  grassInstanced.setMatrixAt(grassIdx++, dummy.matrix);
}
grassInstanced.castShadow = false;
grassInstanced.receiveShadow = true;
scene.add(grassInstanced);

/* ── Wind Animation ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Subtle sway on leaf meshes
  treeGroup.children.forEach(child => {
    if (child.geometry && child.geometry.type === 'IcosahedronGeometry') {
      child.position.x += Math.sin(t * 1.2 + child.position.y * 0.5) * 0.0008;
      child.position.z += Math.cos(t * 1.0 + child.position.x * 0.5) * 0.0006;
    }
  });

  // Grass sway
  for (let i = 0; i < grassIdx; i++) {
    grassInstanced.getMatrixAt(i, dummy.matrix);
    dummy.matrix.decompose(dummy.position, dummy.rotation, dummy.scale);
    dummy.rotation.z = Math.sin(t * 1.5 + dummy.position.x * 0.8 + dummy.position.z * 0.6) * 0.15;
    dummy.rotation.x = Math.cos(t * 1.3 + dummy.position.z * 0.7) * 0.08;
    dummy.updateMatrix();
    grassInstanced.setMatrixAt(i, dummy.matrix);
  }
  grassInstanced.instanceMatrix.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

/* ── Resize ── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
