        beak.castShadow = true;
        birdGroup.add(beak);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.05, 16, 16);
        const eyeLeft = new THREE.Mesh(eyeGeo, eyeMaterial);
        eyeLeft.position.set(0.55, 0.4, 0.2);
        birdGroup.add(eyeLeft);

        const eyeRight = new THREE.Mesh(eyeGeo, eyeMaterial);
        eyeRight.position.set(0.55, 0.4, -0.2);
        birdGroup.add(eyeRight);

        // Wings
        const wingGeo = new THREE.BoxGeometry(0.8, 0.1, 0.4);

        const wingLeft = new THREE.Mesh(wingGeo, wingMaterial);
        wingLeft.position.set(0, 0, 0.5);
        wingLeft.rotation.x = 0.2;
        wingLeft.castShadow = true;
        birdGroup.add(wingLeft);

        const wingRight = new THREE.Mesh(wingGeo, wingMaterial);
        wingRight.position.set(0, 0, -0.5);
        wingRight.rotation.x = 0.2;
        wingRight.castShadow = true;
        birdGroup.add(wingRight);

        // Tail
        const tailGeo = new THREE.ConeGeometry(0.2, 0.6, 32);
        const tail = new THREE.Mesh(tailGeo, wingMaterial);
        tail.rotation.z = Math.PI / 2;
        tail.position.set(-0.6, 0, 0);
        tail.castShadow = true;
        birdGroup.add(tail);

        // Legs
