        const legRight = new THREE.Mesh(legGeo, legMat);
        legRight.position.set(0.1, -0.6, -0.15);
        birdGroup.add(legRight);

        scene.add(birdGroup);

        // 7. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Simple floating animation
            const time = Date.now() * 0.001;
            birdGroup.position.y = Math.sin(time) * 0.2;
            birdGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

