```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three.js Book</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a2e; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

// ── Camera ─────────────────────────────────────────────
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 5);

// ── Renderer ───────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// ── Lights ─────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0xffffff, 0.6));
const dir = new THREE.DirectionalLight(0xffffff, 1.5);
dir.position.set(4, 6, 4);
dir.castShadow = true;
scene.add(dir);
scene.add(new THREE.HemisphereLight(0xffeeb1, 0x080820, 0.4));

// ── Book cover texture ─────────────────────────────────
function makeCoverTexture(title, color) {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 700;
  const x = c.getContext('2d');
  x.fillStyle = color;
  x.fillRect(0, 0, 512, 700);
  // subtle border
  x.strokeStyle = 'rgba(255,255,255,0.15)';
  x.lineWidth = 6;
  x.strokeRect(20, 20, 472, 660);
  // title
  x.fillStyle = '#fff';
  x.font = 'bold 42px Georgia, serif';
  x.textAlign = 'center';
  x.fillText(title, 256, 320);
  // subtitle line
  x.font = '20px Georgia, serif';
  x.fillStyle = 'rgba(255,255,255,0.6)';
  x.fillText('— a story —', 256, 370);
  // decorative line
  x.strokeStyle = 'rgba(255,255,255,0.25)';
  x.lineWidth = 2;
  x.beginPath(); x.moveTo(156, 395); x.lineTo(356, 395); x.stroke();
  // author
  x.font = 'italic 22px Georgia, serif';
  x.fillStyle = 'rgba(255,255,255,0.5)';
  x.fillText('by Anonymous', 256, 450);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// ── Materials ──────────────────────────────────────────
const pageMat = new THREE.MeshStandardMaterial({ color: 0xf5f0e8, roughness: 0.8 });
const spineMat = new THREE.MeshStandardMaterial({ color: 0x8b0000, roughness: 0.5 });
const coverMat = new THREE.MeshStandardMaterial({
  map: makeCoverTexture('The Three.js Book', '#8b0000'),
  roughness: 0.4,
  metalness: 0.05,
});
const backMat = new THREE.MeshStandardMaterial({
  map: makeCoverTexture('', '#7a0000'),
  roughness: 0.5,
});

// ── Book geometry ──────────────────────────────────────
// Order: +X(right), -X(left/spine), +Y(top), -Y(bottom), +Z(front), -Z(back)
const book = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 0.12, 1.8),
  [pageMat, spineMat, pageMat, pageMat, coverMat, backMat]
);
book.castShadow = true;
book.receiveShadow = true;
scene.add(book);

// ── Page lines (thin planes on the page edge) ──────────
for (let i = 0; i < 12; i++) {
  const line = new THREE.Mesh(
    new THREE.PlaneGeometry(1.18, 0.004),
    new THREE.MeshStandardMaterial({ color: 0xd4cfc5 })
  );
  line.position.set(0.601, -0.055 + i * 0.01, 0);
  line.rotation.y = Math.PI / 2;
  book.add(line);
}

// ── Ground plane ───────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 20),
  new THREE.MeshStandardMaterial({ color: 0x1a1a2e, roughness: 1 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.2;
ground.receiveShadow = true;
scene.add(ground);

// ── Controls ───────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0, 0);

// ── Animate ────────────────────────────────────────────
function loop() {
  requestAnimationFrame(loop);
  book.rotation.y += 0.005;
  book.position.y = Math.sin(Date.now() * 0.001) * 0.15;
  controls.update();
  renderer.render(scene, camera);
}
loop();

// ── Resize ─────────────────────────────────────────────
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What this gives you:**

- **A 3D book** with a red cover, white page edges, and a spine — all from a single `BoxGeometry` with 6 different face materials
- **Canvas-generated cover texture** with title, author, and decorative elements (no external assets needed)
- **Page-edge detail lines** to simulate individual pages
- **Soft shadow** on a ground plane
- **Gentle floating + slow rotation** animation
- **OrbitControls** — drag to rotate, scroll to zoom
- **Fully responsive** to window resizing

