    const baseGeo = new THREE.CylinderGeometry(0.6, 0.65, 0.12, 48);
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.y = 0.06;
    base.castShadow = true;
    base.receiveShadow = true;
    lamp.add(base);

    // Base ring accent
    const ringGeo = new THREE.TorusGeometry(0.62, 0.015, 8, 48);
    const ringMat = new THREE.MeshStandardMaterial({ color: 0x666666, metalness: 1, roughness: 0.2 });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.12;
    lamp.add(ring);

    // Stem / Pole
    const stemGeo = new THREE.CylinderGeometry(0.035, 0.04, 2.2, 16);
    const stem = new THREE.Mesh(stemGeo, stemMat);
    stem.position.y = 1.22;
    stem.castShadow = true;
    lamp.add(stem);

    // Articulated arm (angled)
    const armGroup = new THREE.Group();
    armGroup.position.set(0, 2.32, 0);
    armGroup.rotation.z = -Math.PI / 6;

    const armGeo = new THREE.CylinderGeometry(0.025, 0.025, 1.2, 12);
    const arm = new THREE.Mesh(armGeo, stemMat);
    arm.position.y = 0.6;
    arm.castShadow = true;
    armGroup.add(arm);

    // Joint sphere
    const jointGeo = new THREE.SphereGeometry(0.055, 16, 16);
    const joint = new THREE.Mesh(jointGeo, jointMat);
    joint.position.y = 1.2;
    armGroup.add(joint);

    lamp.add(armGroup);

    // Shade group (positioned at end of arm)
    const shadeGroup = new THREE.Group();
    shadeGroup.position.set(0, 1.2, 0);
    shadeGroup.rotation.z = Math.PI / 6;

    // Lamp shade (inverted truncated cone)
    const shadeGeo = new THREE.CylinderGeometry(0.15, 0.45, 0.5, 32, 1, true);
    const shade = new THREE.Mesh(shadeGeo, shadeMat);
    shade.position.y = -0.25;
    shade.castShadow = true;
    shadeGroup.add(shade);

    // Shade top cap
    const capGeo = new THREE.CircleGeometry(0.15, 32);
    const cap = new THREE.Mesh(capGeo, shadeMat);
    cap.rotation.x = -Math.PI / 2;
    cap.position.y = -0.01;
    shadeGroup.add(cap);

    // Bulb
    const bulbGeo = new THREE.SphereGeometry(0.07, 16, 16);
    const bulb = new THREE.Mesh(bulbGeo, bulbMat);
    bulb.position.y = -0.05;
    shadeGroup.add(bulb);

    // Bulb filament ring
    const filamentGeo = new THREE.TorusGeometry(0.03, 0.005, 8, 16);
    const filamentMat = new THREE.MeshStandardMaterial({ color: 0xffdd88, emissive: 0xffcc66, emissiveIntensity: 1.5 });
    const filament = new THREE.Mesh(filamentGeo, filamentMat);
    filament.rotation.x = Math.PI / 2;
    filament.position.y = -0.05;
    shadeGroup.add(filament);

    armGroup.add(shadeGroup);

    // --- Point Light (the lamp's glow) ---
    const pointLight = new THREE.PointLight(0xffeebb, 40, 12, 1.5);
    pointLight.position.set(0, -0.1, 0);
    pointLight.castShadow = true;
    pointLight.shadow.mapSize.set(1024, 1024);
    shadeGroup.add(pointLight);

    // Small spotlight for more directional feel
    const spotLight = new THREE.SpotLight(0xffeedd, 30, 10, Math.PI / 4, 0.6, 1.5);
    spotLight.position.set(0, -0.05, 0);
    spotLight.target.position.set(0, -4, 0);
    spotLight.castShadow = true;
    shadeGroup.add(spotLight);
    shadeGroup.add(spotLight.target);

    scene.add(lamp);

    // --- Floor ---
    const floorGeo = new THREE.PlaneGeometry(20, 20);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a1a22, metalness: 0.3, roughness: 0.8 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // --- Ambient & Hemisphere Light ---
    scene.add(new THREE.AmbientLight(0x222233, 0.5));
    const hemi = new THREE.HemisphereLight(0x334466, 0x111111, 0.4);
    scene.add(hemi);

    // --- Glow sprite around bulb ---
    const spriteMat = new THREE.SpriteMaterial({
      map: (() => {
        const c = document.createElement('canvas');
        c.width = c.height = 64;
        const ctx = c.getContext('2d');
        const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        g.addColorStop(0, 'rgba(255,238,180,0.6)');
        g.addColorStop(1, 'rgba(255,238,180,0)');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 64, 64);
        const tex = new THREE.CanvasTexture(c);
        return tex;
      })(),
      blending: THREE.AdditiveBlending,
      transparent: true,
      depthWrite: false,
    });
    const glow = new THREE.Sprite(spriteMat);
    glow.scale.set(0.8, 0.8, 1);
    glow.position.set(0, -0.1, 0);
    shadeGroup.add(glow);

    // --- Animation ---
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      // Gentle glow pulsing
      pointLight.intensity = 40 + Math.sin(t * 2) * 2;
      spotLight.intensity = 30 + Math.sin(t * 2) * 1.5;
      bulbMat.emissiveIntensity = 2 + Math.sin(t * 2) * 0.2;
      glow.scale.setScalar(0.4 + Math.sin(t * 2) * 0.03);

      controls.update();
      renderer.render(scene, camera);
    }
    animate();

    // --- Resize ---
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
