    <div id="info">🌹 Drag to orbit · Scroll to zoom</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 2, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Flower Group
        const flowerGroup = new THREE.Group();
        scene.add(flowerGroup);

        // Materials
        const stemMaterial = new THREE.MeshStandardMaterial({ color: 0x2d5a27, roughness: 0.8 });
        const petalMaterial = new THREE.MeshStandardMaterial({ color: 0xff3366, roughness: 0.4, side: THREE.DoubleSide });
        const centerMaterial = new THREE.MeshStandardMaterial({ color: 0xffcc00, roughness: 0.5 });
        const leafMaterial = new THREE.MeshStandardMaterial({ color: 0x3a7a33, roughness: 0.6, side: THREE.DoubleSide });

        // Stem
        const stemGeometry = new THREE.CylinderGeometry(0.1, 0.15, 6, 8);
        const stem = new THREE.Mesh(stemGeometry, stemMaterial);
        stem.position.y = 3;
        stem.castShadow = true;
        flowerGroup.add(stem);

        // Leaves
        function createLeaf(x, y, z, rotZ, rotY) {
            const leafGeo = new THREE.ConeGeometry(0.4, 1.5, 3);
            const leaf = new THREE.Mesh(leafGeo, leafMaterial);
            leaf.position.set(x, y, z);
            leaf.rotation.z = rotZ;
            leaf.rotation.y = rotY;
            leaf.castShadow = true;
            return leaf;
        }

        flowerGroup.add(createLeaf(0.5, 2, 0, -Math.PI / 4, 0));
        flowerGroup.add(createLeaf(-0.5, 3, 0, Math.PI / 4, Math.PI));

        // Flower Head Group
        const headGroup = new THREE.Group();
        headGroup.position.y = 6;
        flowerGroup.add(headGroup);

        // Center of flower
        const centerGeo = new THREE.SphereGeometry(0.6, 16, 16);
        const center = new THREE.Mesh(centerGeo, centerMaterial);
        center.castShadow = true;
        headGroup.add(center);

        // Petals
        const petalCount = 12;
        const petalGeo = new THREE.ConeGeometry(0.4, 1.5, 4);

        for (let i = 0; i < petalCount; i++) {
            const petal = new THREE.Mesh(petalGeo, petalMaterial);
            const angle = (i / petalCount) * Math.PI * 2;

            // Position petals in a circle
            petal.position.x = Math.cos(angle) * 0.8;
            petal.position.z = Math.sin(angle) * 0.8;

            // Tilt petals outward
            petal.rotation.x = Math.PI / 3; // Tilt up
            petal.rotation.y = -angle; // Face outward

            petal.castShadow = true;
            headGroup.add(petal);
        }

        // Second layer of petals (inner)
        for (let i = 0; i < 8; i++) {
            const petal = new THREE.Mesh(petalGeo, petalMaterial);
            const angle = (i / 8) * Math.PI * 2 + (Math.PI / 8); // Offset

            petal.position.x = Math.cos(angle) * 0.4;
            petal.position.z = Math.sin(angle) * 0.4;
            petal.position.y = 0.2;

            petal.rotation.x = Math.PI / 4; 
            petal.rotation.y = -angle;
            petal.scale.set(0.7, 0.7, 0.7);

            petal.castShadow = true;
            headGroup.add(petal);
        }

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle sway
            const time = Date.now() * 0.001;
            flowerGroup.rotation.z = Math.sin(time) * 0.05;
            flowerGroup.rotation.x = Math.cos(time * 0.8) * 0.02;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
