        camera.position.set(0, 2, 6);
        camera.lookAt(0, 0.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // Materials
        const frameMaterial = new THREE.MeshStandardMaterial({ color: 0xe74c3c, roughness: 0.3, metalness: 0.5 });
        const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const metalMaterial = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.2, metalness: 0.8 });
        const seatMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // Helper to create a tube between two points
        function createTube(start, end, radius, material) {
            const path = new THREE.LineCurve3(start, end);
            const geometry = new THREE.TubeGeometry(path, 1, radius, 8, false);
            const mesh = new THREE.Mesh(geometry, material);
            mesh.castShadow = true;
            return mesh;
        }

        const bicycle = new THREE.Group();

        // Wheels
        const wheelRadius = 0.7;
        const wheelTube = 0.05;
        const wheelGeo = new THREE.TorusGeometry(wheelRadius, wheelTube, 16, 32);

        const rearWheel = new THREE.Mesh(wheelGeo, wheelMaterial);
        rearWheel.position.set(-1.2, wheelRadius, 0);
        rearWheel.castShadow = true;
        bicycle.add(rearWheel);

        const frontWheel = new THREE.Mesh(wheelGeo, wheelMaterial);
        frontWheel.position.set(1.2, wheelRadius, 0);
        frontWheel.castShadow = true;
        bicycle.add(frontWheel);

        // Frame Points (approximate geometry)
        const pRearAxle = new THREE.Vector3(-1.2, wheelRadius, 0);
        const pBottomBracket = new THREE.Vector3(0, 0.2, 0);
        const pSeatCluster = new THREE.Vector3(-0.4, 0.9, 0);
        const pHeadTube = new THREE.Vector3(1.0, 0.9, 0);
        const pFrontAxle = new THREE.Vector3(1.2, wheelRadius, 0);

        // Frame Tubes
        bicycle.add(createTube(pRearAxle, pBottomBracket, 0.03, frameMaterial)); // Seat stay (lower)
        bicycle.add(createTube(pRearAxle, pSeatCluster, 0.03, frameMaterial));   // Seat stay (upper)
        bicycle.add(createTube(pBottomBracket, pSeatCluster, 0.04, frameMaterial)); // Seat tube
        bicycle.add(createTube(pSeatCluster, pHeadTube, 0.03, frameMaterial));   // Top tube
        bicycle.add(createTube(pHeadTube, pBottomBracket, 0.03, frameMaterial)); // Down tube
        bicycle.add(createTube(pHeadTube, pFrontAxle, 0.025, metalMaterial));    // Fork

        // Handlebars
        const handleBarGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.6, 8);
        const handleBar = new THREE.Mesh(handleBarGeo, metalMaterial);
        handleBar.rotation.z = Math.PI / 2;
        handleBar.position.set(1.0, 1.05, 0);
        bicycle.add(handleBar);

        // Seat
        const seatGeo = new THREE.BoxGeometry(0.3, 0.05, 0.2);
        const seat = new THREE.Mesh(seatGeo, seatMaterial);
        seat.position.set(-0.4, 0.95, 0);
        bicycle.add(seat);

        // Pedals (simplified)
        const pedalGeo = new THREE.BoxGeometry(0.1, 0.05, 0.15);
        const pedal1 = new THREE.Mesh(pedalGeo, metalMaterial);
        pedal1.position.set(0.1, 0.1, 0.1);
        bicycle.add(pedal1);

        const pedal2 = new THREE.Mesh(pedalGeo, metalMaterial);
        pedal2.position.set(-0.1, 0.1, -0.1);
        bicycle.add(pedal2);

        scene.add(bicycle);

        // Animation
        function animate() {
            requestAnimationFrame(animate);
            bicycle.rotation.y += 0.01;
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
