    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 5, 5);
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffffff, 0.5);
        backLight.position.set(-5, -5, -5);
        scene.add(backLight);

        // Guitar Construction
        const guitarGroup = new THREE.Group();
        scene.add(guitarGroup);

        // Materials
        const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.3, metalness: 0.1 }); // Wood
        const neckMaterial = new THREE.MeshStandardMaterial({ color: 0x3d2817, roughness: 0.5 }); // Dark wood
        const fretboardMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.8 }); // Fretboard
        const hardwareMaterial = new THREE.MeshStandardMaterial({ color: 0xcccccc, metalness: 0.8, roughness: 0.2 }); // Chrome
        const stringMaterial = new THREE.LineBasicMaterial({ color: 0xeeeeee });

        // 1. Guitar Body (Acoustic shape approximation)
        const bodyShape = new THREE.Shape();
        // Simple figure-8-ish shape for acoustic body
        bodyShape.moveTo(0, 2.5);
        bodyShape.bezierCurveTo(1.5, 2.5, 2.2, 1.5, 2.2, 0.5); // Top right curve
        bodyShape.bezierCurveTo(2.2, -0.5, 1.5, -1.5, 0, -2.5); // Bottom right curve
        bodyShape.bezierCurveTo(-1.5, -1.5, -2.2, -0.5, -2.2, 0.5); // Bottom left curve
        bodyShape.bezierCurveTo(-2.2, 1.5, -1.5, 2.5, 0, 2.5); // Top left curve

        const extrudeSettings = { depth: 0.8, bevelEnabled: true, bevelSegments: 2, steps: 2, bevelSize: 0.1, bevelThickness: 0.1 };
        const bodyGeometry = new THREE.ExtrudeGeometry(bodyShape, extrudeSettings);
        bodyGeometry.center(); // Center the geometry
        const bodyMesh = new THREE.Mesh(bodyGeometry, bodyMaterial);
        bodyMesh.rotation.x = Math.PI / 2; // Lay flat
        bodyMesh.position.y = -1; // Move down slightly
        guitarGroup.add(bodyMesh);

        // Sound hole
        const holeGeometry = new THREE.CircleGeometry(0.6, 32);
        const holeMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const holeMesh = new THREE.Mesh(holeGeometry, holeMaterial);
        holeMesh.position.set(0, -0.5, 0.41); // Slightly in front of body
        guitarGroup.add(holeMesh);

        // 2. Neck
        const neckGeometry = new THREE.BoxGeometry(0.6, 5, 0.3);
        const neckMesh = new THREE.Mesh(neckGeometry, neckMaterial);
        neckMesh.position.set(0, 2.5, 0);
        guitarGroup.add(neckMesh);

        // Fretboard
        const fretboardGeometry = new THREE.BoxGeometry(0.62, 4.8, 0.05);
        const fretboardMesh = new THREE.Mesh(fretboardGeometry, fretboardMaterial);
        fretboardMesh.position.set(0, 2.5, 0.16);
        guitarGroup.add(fretboardMesh);

        // Frets (simple lines)
        for(let i=0; i<12; i++) {
            const fretGeo = new THREE.BoxGeometry(0.64, 0.02, 0.06);
            const fretMesh = new THREE.Mesh(fretGeo, hardwareMaterial);
            fretMesh.position.set(0, 0.5 + (i * 0.35), 0.16);
            guitarGroup.add(fretMesh);
        }

        // 3. Headstock
        const headstockGeometry = new THREE.BoxGeometry(0.8, 1.2, 0.2);
        const headstockMesh = new THREE.Mesh(headstockGeometry, neckMaterial);
        headstockMesh.position.set(0, 5.6, 0);
        headstockMesh.rotation.z = 0.2; // Slight tilt
        guitarGroup.add(headstockMesh);

        // Tuning Pegs
        for(let i=0; i<3; i++) {
            const pegGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.4, 8);
            const pegMesh = new THREE.Mesh(pegGeo, hardwareMaterial);
            pegMesh.rotation.z = Math.PI / 2;
            pegMesh.position.set(0.5, 5.2 + (i * 0.3), 0);
            guitarGroup.add(pegMesh);

            const pegMesh2 = new THREE.Mesh(pegGeo, hardwareMaterial);
            pegMesh2.rotation.z = Math.PI / 2;
            pegMesh2.position.set(-0.5, 5.2 + (i * 0.3), 0);
            guitarGroup.add(pegMesh2);
        }

        // 4. Strings
        const stringPoints = [];
        const stringStart = new THREE.Vector3(0, -1.5, 0.45); // Bridge area
        const stringEnd = new THREE.Vector3(0, 5.5, 0.2); // Headstock area

        // Create 6 strings
        for(let i=0; i<6; i++) {
            const offset = (i - 2.5) * 0.08;
            const start = new THREE.Vector3(offset, -1.5, 0.45);
            const end = new THREE.Vector3(offset, 5.5, 0.2);
            const geometry = new THREE.BufferGeometry().setFromPoints([start, end]);
            const line = new THREE.Line(geometry, stringMaterial);
            guitarGroup.add(line);
        }

        // Bridge
        const bridgeGeo = new THREE.BoxGeometry(0.8, 0.2, 0.1);
        const bridgeMesh = new THREE.Mesh(bridgeGeo, hardwareMaterial);
        bridgeMesh.position.set(0, -1.5, 0.45);
        guitarGroup.add(bridgeMesh);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            guitarGroup.rotation.y += 0.005;
            guitarGroup.rotation.z = Math.sin(Date.now() * 0.001) * 0.05;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
