</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.035);

// ── Camera ─────────────────────────────────────────────
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3.5, 5);

// ── Renderer ───────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Controls ───────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 3;
controls.maxDistance = 12;
controls.maxPolarAngle = Math.PI / 2 + 0.2;
controls.update();

// ── Lights ─────────────────────────────────────────────
const ambient = new THREE.AmbientLight(0x404060, 0.8);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffeedd, 2.5);
keyLight.position.set(5, 8, 4);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 20;
keyLight.shadow.camera.left = -5;
keyLight.shadow.camera.right = 5;
keyLight.shadow.camera.top = 5;
keyLight.shadow.camera.bottom = -5;
keyLight.shadow.bias = -0.001;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888cc, 0.6);
fillLight.position.set(-4, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff9944, 1.5, 15);
rimLight.position.set(-3, 4, -4);
scene.add(rimLight);

// ── Materials ──────────────────────────────────────────
const feltMat = new THREE.MeshStandardMaterial({
  color: 0x1c1c1c,
  roughness: 0.92,
  metalness: 0.0,
});

const brimMat = new THREE.MeshStandardMaterial({
  color: 0x222222,
  roughness: 0.85,
  metalness: 0.05,
});

const bandMat = new THREE.MeshStandardMaterial({
  color: 0x8b0000,
  roughness: 0.4,
  metalness: 0.3,
});

const goldMat = new THREE.MeshStandardMaterial({
  color: 0xdaa520,
  roughness: 0.25,
  metalness: 0.85,
});

const bowMat = new THREE.MeshStandardMaterial({
  color: 0x8b0000,
  roughness: 0.5,
  metalness: 0.1,
});

// ── Hat Group ──────────────────────────────────────────
const hat = new THREE.Group();

// ── Crown ──────────────────────────────────────────────
const crownGeo = new THREE.CylinderGeometry(0.72, 0.78, 1.6, 48, 1, false);
const crown = new THREE.Mesh(crownGeo, feltMat);
crown.position.y = 1.8;
crown.castShadow = true;
crown.receiveShadow = true;
hat.add(crown);

// Crown top dome (subtle cap)
const domeGeo = new THREE.SphereGeometry(0.72, 48, 24, 0, Math.PI * 2, 0, Math.PI / 2);
const dome = new THREE.Mesh(domeGeo, feltMat);
dome.position.y = 2.6;
dome.castShadow = true;
hat.add(dome);

// Crown indent (fedora pinch)
const pinchGeo = new THREE.CylinderGeometry(0.35, 0.72, 0.15, 48, 1, false);
const pinch = new THREE.Mesh(pinchGeo, feltMat);
pinch.position.set(0.25, 2.05, 0);
pinch.rotation.z = Math.PI / 2;
pinch.scale.set(1, 1, 1.4);
pinch.castShadow = true;
hat.add(pinch);

// ── Brim ───────────────────────────────────────────────
const brimShape = new THREE.Shape();
brimShape.absarc(0, 0, 1.5, 0, Math.PI * 2, false);
const brimHole = new THREE.Path();
brimHole.absarc(0, 0, 0.78, 0, Math.PI * 2, true);
brimShape.holes.push(brimHole);

const brimExtrudeSettings = { depth: 0.08, bevelEnabled: true, bevelThickness: 0.03, bevelSize: 0.03, bevelSegments: 4 };
const brimGeo = new THREE.ExtrudeGeometry(brimShape, brimExtrudeSettings);
const brim = new THREE.Mesh(brimGeo, brimMat);
brim.rotation.x = -Math.PI / 2;
brim.position.y = 1.0;
brim.castShadow = true;
brim.receiveShadow = true;
hat.add(brim);

// Brim curl (upward curve on edges)
const curlGeo = new THREE.TorusGeometry(1.45, 0.04, 8, 64);
const curl = new THREE.Mesh(curlGeo, brimMat);
curl.rotation.x = Math.PI / 2;
curl.position.y = 1.08;
curl.scale.set(1, 1, 1);
// Slight upward curl effect via rotation
curl.rotation.y = 0.3;
curl.castShadow = true;
hat.add(curl);

// ── Hat Band ───────────────────────────────────────────
const bandGeo = new THREE.CylinderGeometry(0.79, 0.80, 0.28, 48, 1, true);
const band = new THREE.Mesh(bandGeo, bandMat);
band.position.y = 1.25;
band.castShadow = true;
hat.add(band);

// ── Bow Tie ────────────────────────────────────────────
const bowGroup = new THREE.Group();
bowGroup.position.set(0, 1.25, 0.78);

// Left loop
const loopGeo = new THREE.SphereGeometry(0.12, 16, 16);
const loopL = new THREE.Mesh(loopGeo, bowMat);
loopL.scale.set(1.3, 0.7, 0.6);
loopL.position.x = -0.12;
bowGroup.add(loopL);

const loopR = new THREE.Mesh(loopGeo, bowMat);
loopR.scale.set(1.3, 0.7, 0.6);
loopR.position.x = 0.12;
bowGroup.add(loopR);

// Center knot
const knotGeo = new THREE.SphereGeometry(0.06, 12, 12);
const knot = new THREE.Mesh(knotGeo, bowMat);
bowGroup.add(knot);

// Tails
const tailGeo = new THREE.BoxGeometry(0.04, 0.18, 0.04);
const tailL = new THREE.Mesh(tailGeo, bowMat);
tailL.position.set(-0.03, -0.12, 0);
tailL.rotation.z = 0.15;
bowGroup.add(tailL);

const tailR = new THREE.Mesh(tailGeo, bowMat);
tailR.position.set(0.03, -0.12, 0);
tailR.rotation.z = -0.15;
bowGroup.add(tailR);

hat.add(bowGroup);

// ── Hat Pin ────────────────────────────────────────────
const pinGeo = new THREE.CylinderGeometry(0.012, 0.012, 0.35, 8);
const pin = new THREE.Mesh(pinGeo, goldMat);
pin.position.set(0.55, 1.15, 0.5);
pin.rotation.z = -0.4;
pin.rotation.x = 0.3;
hat.add(pin);

const pinHeadGeo = new THREE.SphereGeometry(0.035, 12, 12);
const pinHead = new THREE.Mesh(pinHeadGeo, goldMat);
pinHead.position.set(0.62, 1.30, 0.53);
hat.add(pinHead);

// ── Feather ────────────────────────────────────────────
const featherGroup = new THREE.Group();

const featherShape = new THREE.Shape();
featherShape.moveTo(0, 0);
featherShape.quadraticCurveTo(0.15, 0.5, 0.02, 1.2);
featherShape.quadraticCurveTo(-0.05, 0.5, 0, 0);

const featherGeo = new THREE.ExtrudeGeometry(featherShape, {
  depth: 0.015,
  bevelEnabled: true,
  bevelThickness: 0.005,
  bevelSize: 0.005,
  bevelSegments: 2,
});

const featherMat = new THREE.MeshStandardMaterial({
  color: 0x1a0a2e,
  roughness: 0.7,
  metalness: 0.1,
  side: THREE.DoubleSide,
});

const feather = new THREE.Mesh(featherGeo, featherMat);
featherGroup.add(feather);

// Feather spine
const spineGeo = new THREE.CylinderGeometry(0.006, 0.003, 1.2, 6);
const spine = new THREE.Mesh(spineGeo, goldMat);
spine.position.y = 0.6;
featherGroup.add(spine);

featherGroup.position.set(0.6, 2.6, -0.2);
featherGroup.rotation.z = 0.6;
featherGroup.rotation.x = -0.3;
hat.add(featherGroup);

// ── Position Hat ───────────────────────────────────────
hat.position.y = 0;
scene.add(hat);

// ── Ground ─────────────────────────────────────────────
const groundGeo = new THREE.CircleGeometry(8, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x2a2a3e,
  roughness: 0.8,
  metalness: 0.2,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ── Floating Particles ─────────────────────────────────
const particleCount = 120;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 16;
  positions[i * 3 + 1] = Math.random() * 8;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 16;
  sizes[i] = Math.random() * 2 + 1;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xffeedd,
  size: 0.03,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle hat bob
  hat.position.y = Math.sin(t * 0.8) * 0.08;
  hat.rotation.y = Math.sin(t * 0.3) * 0.15;

  // Feather sway
  featherGroup.rotation.z = 0.6 + Math.sin(t * 1.5) * 0.08;
  featherGroup.rotation.x = -0.3 + Math.sin(t * 1.2 + 1) * 0.05;

  // Particle drift
  const pos = particles.geometry.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    pos.array[i * 3 + 1] += Math.sin(t + i) * 0.001;
    if (pos.array[i * 3 + 1] > 8) pos.array[i * 3 + 1] = 0;
  }
  pos.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ─────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
