  <script type="importmap">
    {
      "imports": {
        "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
        "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
      }
    }
  </script>
  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    /* ─── renderer ─── */
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    /* ─── scene & camera ─── */
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x1a1a2e);
    scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2, 8);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.target.set(0, 0, 0);

    /* ─── lighting ─── */
    const ambientLight = new THREE.AmbientLight(0x405040, 0.8);
    scene.add(ambientLight);

    const sunLight = new THREE.DirectionalLight(0xffeedd, 3);
    sunLight.position.set(5, 8, 5);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(1024, 1024);
    sunLight.shadow.camera.near = 1;
    sunLight.shadow.camera.far = 20;
    sunLight.shadow.camera.left = -5;
    sunLight.shadow.camera.right = 5;
    sunLight.shadow.camera.top = 5;
    sunLight.shadow.camera.bottom = -5;
    scene.add(sunLight);

    const rimLight = new THREE.DirectionalLight(0x88ccff, 1.5);
    rimLight.position.set(-3, 2, -5);
    scene.add(rimLight);

    const pointLight = new THREE.PointLight(0xffaa44, 2, 15);
    pointLight.position.set(2, 4, 3);
    scene.add(pointLight);

    /* ─── leaf shape ─── */
    function createLeafShape() {
      const shape = new THREE.Shape();
      const w = 1.2;
      const h = 2.4;

      shape.moveTo(0, -h * 0.45);

      // right side — broad middle, tapering tip
      shape.bezierCurveTo(w * 0.9, -h * 0.35, w * 0.95, h * 0.1, w * 0.15, h * 0.85);
      shape.bezierCurveTo(w * 0.08, h * 0.95, 0, h, 0, h);

      // left side — mirror
      shape.bezierCurveTo(-w * 0.08, h * 0.95, -w * 0.15, h * 0.85, -w * 0.95, h * 0.1);
      shape.bezierCurveTo(-w * 0.9, -h * 0.35, -w * 0.1, -h * 0.5, 0, -h * 0.45);

      return shape;
    }

    /* ─── leaf mesh ─── */
    const leafShape = createLeafShape();
    const extrudeSettings = {
      depth: 0.04,
      bevelEnabled: true,
      bevelThickness: 0.02,
      bevelSize: 0.02,
      bevelSegments: 4
    };

    const leafGeometry = new THREE.ExtrudeGeometry(leafShape, extrudeSettings);
    leafGeometry.center();

    // Perturb vertices for organic waviness
    const pos = leafGeometry.attributes.position;
    const tempVec = new THREE.Vector3();
    for (let i = 0; i < pos.count; i++) {
      tempVec.fromBufferAttribute(pos, i);
      const xFactor = Math.exp(-tempVec.y * tempVec.y * 0.3);
      tempVec.z += Math.sin(tempVec.y * 3.0) * 0.06 * xFactor
                  + Math.sin(tempVec.x * 2.5) * 0.03;
      tempVec.x += Math.sin(tempVec.y * 1.8) * 0.02;
      pos.setXYZ(i, tempVec.x, tempVec.y, tempVec.z);
    }
    pos.needsUpdate = true;
    leafGeometry.computeVertexNormals();

    const leafMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x2d8a4e,
      roughness: 0.55,
      metalness: 0.0,
      clearcoat: 0.3,
      clearcoatRoughness: 0.4,
      side: THREE.DoubleSide,
      flatShading: false,
    });

    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.castShadow = true;
    leaf.receiveShadow = true;
    leaf.rotation.x = -Math.PI * 0.1;

    /* ─── veins ─── */
    function createVein(points, radius, color) {
      const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)));
      const tubeGeo = new THREE.TubeGeometry(curve, 32, radius, 8, false);
      const mat = new THREE.MeshStandardMaterial({
        color, roughness: 0.7, metalness: 0.0
      });
      return new THREE.Mesh(tubeGeo, mat);
    }

    const veinGroup = new THREE.Group();

    // Central vein (midrib)
    const midrib = createVein(
      [
        [0, -1.08, 0.03],
        [0.01, -0.5, 0.035],
        [-0.01, 0.0, 0.04],
        [0.005, 0.5, 0.04],
        [0, 0.95, 0.035]
      ], 0.022, 0x1a6b35
    );
    veinGroup.add(midrib);

    // Secondary veins — right side
    const rightVeins = [
      [[0, -0.6, 0.035], [0.3, -0.45, 0.04], [0.55, -0.2, 0.04], [0.7, 0.1, 0.035], [0.75, 0.35, 0.03]],
      [[0, -0.1, 0.035], [0.35, 0.0, 0.04], [0.6, 0.15, 0.038], [0.72, 0.35, 0.035], [0.73, 0.55, 0.03]],
      [[0, 0.35, 0.038], [0.25, 0.45, 0.04], [0.45, 0.55, 0.038], [0.55, 0.7, 0.035], [0.58, 0.85, 0.03]],
      [[0, 0.7, 0.038], [0.15, 0.78, 0.038], [0.25, 0.87, 0.035], [0.3, 0.95, 0.03]],
    ];

    rightVeins.forEach(pts => veinGroup.add(createVein(pts, 0.01, 0x1a6b35)));

    // Secondary veins — left side (mirrored)
    rightVeins.forEach(pts => {
      const mirrored = pts.map(p => [-p[0], p[1], p[2]]);
      veinGroup.add(createVein(mirrored, 0.01, 0x1a6b35));
    });

    // Tertiary veins (finer)
    const tertiaryRight = [
      [[0.3, -0.3, 0.038], [0.5, -0.15, 0.04], [0.65, 0.0, 0.038]],
      [[0.2, 0.15, 0.038], [0.45, 0.25, 0.04], [0.6, 0.35, 0.038]],
      [[0.35, 0.55, 0.038], [0.5, 0.62, 0.04], [0.6, 0.72, 0.038]],
    ];
    tertiaryRight.forEach(pts => veinGroup.add(createVein(pts, 0.005, 0x157a3a)));
    tertiaryRight.forEach(pts => {
      const mirrored = pts.map(p => [-p[0], p[1], p[2]]);
      veinGroup.add(createVein(mirrored, 0.005, 0x157a3a));
    });

    leaf.add(veinGroup);
    scene.add(leaf);

    /* ─── stem (petiole) ─── */
    const stemCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0, -1.12, 0.03),
      new THREE.Vector3(0, -1.5, 0.01),
      new THREE.Vector3(0.05, -2.0, -0.02),
      new THREE.Vector3(0.1, -2.5, -0.05),
    ]);
    const stemGeo = new THREE.TubeGeometry(stemCurve, 20, 0.035, 8, false);
    const stemMat = new THREE.MeshStandardMaterial({ color: 0x3a7d44, roughness: 0.6 });
    const stem = new THREE.Mesh(stemGeo, stemMat);
    stem.castShadow = true;
    leaf.add(stem);

    /* ─── ground plane ─── */
    const groundGeo = new THREE.PlaneGeometry(30, 30);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x1a2e1a, roughness: 0.9, metalness: 0.0
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -3;
    ground.receiveShadow = true;
    scene.add(ground);

    /* ─── floating particles (pollen / dust) ─── */
    const particleCount = 200;
    const particleGeo = new THREE.BufferGeometry();
    const particlePositions = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      particlePositions[i * 3]     = (Math.random() - 0.5) * 12;
      particlePositions[i * 3 + 1] = (Math.random() - 0.5) * 8;
      particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 12;
    }
    particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0xaaddaa, size: 0.03, transparent: true, opacity: 0.6, sizeAttenuation: true
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    /* ─── animation ─── */
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      // Gentle leaf sway
      leaf.rotation.z = Math.sin(t * 0.8) * 0.06;
      leaf.rotation.x = -Math.PI * 0.1 + Math.sin(t * 0.5) * 0.03;

      // Vertex waviness animation
      const wave = leafGeometry.attributes.position;
      const temp = new THREE.Vector3();
      for (let i = 0; i < wave.count; i++) {
        temp.fromBufferAttribute(wave, i);
        const originalY = temp.y;
        const xFactor = Math.exp(-originalY * originalY * 0.3);
        const zOffset = Math.sin(originalY * 3.0 + t * 1.5) * 0.06 * xFactor
                      + Math.sin(temp.x * 2.5 + t * 1.2) * 0.03;
        const xOffset = Math.sin(originalY * 1.8 + t * 1.0) * 0.02;
        wave.setXYZ(i, temp.x + xOffset, temp.y, zOffset);
      }
      wave.needsUpdate = true;
      leafGeometry.computeVertexNormals();

      // Particle drift
      const pPos = particles.geometry.attributes.position;
      for (let i = 0; i < particleCount; i++) {
        let y = pPos.getY(i);
        y += Math.sin(t * 0.5 + i) * 0.002;
        if (y > 4) y = -4;
        pPos.setY(i, y);
        pPos.setX(i, pPos.getX(i) + Math.sin(t * 0.3 + i * 0.5) * 0.001);
      }
      pPos.needsUpdate = true;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    /* ─── resize ─── */
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
