  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    // ── Scene ──────────────────────────────────────────────
    const scene = new THREE.Scene();

    // ── Camera ─────────────────────────────────────────────
    const camera = new THREE.PerspectiveCamera(
      45, innerWidth / innerHeight, 0.1, 1000
    );
    camera.position.set(0, 0, 3.5);

    // ── Renderer ───────────────────────────────────────────
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // ── Controls ───────────────────────────────────────────
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 1.8;
    controls.maxDistance = 10;

    // ── Starfield ──────────────────────────────────────────
    const starCount = 6000;
    const starGeo = new THREE.BufferGeometry();
    const starPos = new Float32Array(starCount * 3);
    const starSizes = new Float32Array(starCount);
    for (let i = 0; i < starCount; i++) {
      const r = 80 + Math.random() * 120;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      starPos[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
      starPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
      starPos[i * 3 + 2] = r * Math.cos(phi);
      starSizes[i] = 0.3 + Math.random() * 1.2;
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    starGeo.setAttribute('size', new THREE.BufferAttribute(starSizes, 1));

    const starMat = new THREE.ShaderMaterial({
      uniforms: { time: { value: 0 } },
      vertexShader: `
        attribute float size;
        varying float vBrightness;
        uniform float time;
        void main() {
          vBrightness = 0.6 + 0.4 * sin(time * 0.5 + position.x * 0.01);
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (200.0 / -mv.z);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        varying float vBrightness;
        void main() {
          float d = length(gl_PointCoord - 0.5) * 2.0;
          float alpha = 1.0 - smoothstep(0.0, 1.0, d);
          gl_FragColor = vec4(vec3(0.9, 0.92, 1.0) * vBrightness, alpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    scene.add(new THREE.Points(starGeo, starMat));

    // ── Procedural Moon Texture ────────────────────────────
    function createMoonTexture(size) {
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = size;
      const ctx = canvas.getContext('2d');

      // Base fill
      ctx.fillStyle = '#8a8a8a';
      ctx.fillRect(0, 0, size, size);

      // Simplex-like noise via layered radial gradients
      for (let i = 0; i < 3000; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        const r = Math.random() * 20 + 2;
        const bright = Math.random() * 40 - 20;
        const gray = 136 + bright;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fillStyle = `rgb(${gray},${gray},${gray})`;
        ctx.fill();
      }

      // Craters
      for (let i = 0; i < 80; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        const r = Math.random() * 30 + 5;
        const g = (v) => {
          const edge = 1 - Math.abs(v) / r;
          return Math.max(0, Math.min(255, 136 + (edge > 0.7 ? 25 : -15) * (1 - edge)));
        };
        const grad = ctx.createRadialGradient(x, y, r * 0.2, x, y, r);
        grad.addColorStop(0, 'rgba(100,100,100,0.5)');
        grad.addColorStop(0.6, 'rgba(120,120,120,0.3)');
        grad.addColorStop(0.85, 'rgba(160,160,160,0.4)');
        grad.addColorStop(1, 'rgba(136,136,136,0)');
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.fill();
      }

      // Dark maria (seas)
      for (let i = 0; i < 12; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        const rx = Math.random() * 100 + 40;
        const ry = Math.random() * 100 + 40;
        const grad = ctx.createRadialGradient(x, y, 0, x, y, Math.max(rx, ry));
        grad.addColorStop(0, 'rgba(80,80,85,0.35)');
        grad.addColorStop(1, 'rgba(136,136,136,0)');
        ctx.beginPath();
        ctx.ellipse(x, y, rx, ry, Math.random() * Math.PI, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.fill();
      }

      return new THREE.CanvasTexture(canvas);
    }

    function createBumpTexture(size) {
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = size;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#808080';
      ctx.fillRect(0, 0, size, size);

      for (let i = 0; i < 80; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        const r = Math.random() * 30 + 5;
        const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
        grad.addColorStop(0, '#555');
        grad.addColorStop(0.7, '#666');
        grad.addColorStop(0.9, '#aaa');
        grad.addColorStop(1, '#808080');
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.fill();
      }
      return new THREE.CanvasTexture(canvas);
    }

    // ── Moon ───────────────────────────────────────────────
    const moonGeo = new THREE.SphereGeometry(1, 128, 128);
    const moonMat = new THREE.MeshStandardMaterial({
      map: createMoonTexture(2048),
      bumpMap: createBumpTexture(2048),
      bumpScale: 0.04,
      roughness: 0.95,
      metalness: 0.0,
    });
    const moon = new THREE.Mesh(moonGeo, moonMat);
    scene.add(moon);

    // ── Atmosphere glow (subtle rim) ──────────────────────
    const glowMat = new THREE.ShaderMaterial({
      uniforms: {},
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vViewPos;
        void main() {
          vNormal = normalize(normalMatrix * normal);
          vViewPos = (modelViewMatrix * vec4(position, 1.0)).xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vNormal;
        varying vec3 vViewPos;
        void main() {
          vec3 viewDir = normalize(-vViewPos);
          float rim = 1.0 - max(0.0, dot(viewDir, vNormal));
          rim = pow(rim, 4.0) * 0.15;
          gl_FragColor = vec4(0.7, 0.75, 0.9, rim);
        }
      `,
      transparent: true,
      depthWrite: false,
      side: THREE.BackSide,
      blending: THREE.AdditiveBlending,
    });
    const glowMesh = new THREE.Mesh(
      new THREE.SphereGeometry(1.06, 64, 64),
      glowMat
    );
    scene.add(glowMesh);

    // ── Lighting ───────────────────────────────────────────
    const sun = new THREE.DirectionalLight(0xfff5e6, 3.5);
    sun.position.set(5, 2, 4);
    scene.add(sun);

    const ambient = new THREE.AmbientLight(0x222233, 0.15);
    scene.add(ambient);

    // Subtle blue fill from the opposite side
    const fill = new THREE.DirectionalLight(0x4466aa, 0.08);
    fill.position.set(-4, -1, -3);
    scene.add(fill);

    // ── Animation ──────────────────────────────────────────
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const elapsed = clock.getElapsedTime();

      moon.rotation.y = elapsed * 0.02;
      starMat.uniforms.time.value = elapsed;

      controls.update();
      renderer.render(scene, camera);
    }
    animate();

    // ── Resize ─────────────────────────────────────────────
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
```

## What's in here

| Feature | Detail |
|---|---|
| **Moon sphere** | 128-segment `SphereGeometry` with a **procedural 2048×2048 canvas texture** — craters, maria (dark seas), and surface noise all drawn with Canvas 2D |
| **Bump mapping** | A second procedural canvas gives crater depth via `bumpMap` + `bumpScale` |
| **Starfield** | 6 000 points with a custom shader that adds a gentle twinkling pulsation (`sin` over time) and additive blending |
| **Rim glow** | A slightly larger back-face sphere with a Fresnel-like rim shader gives a subtle atmospheric halo |
| **Lighting** | Warm directional "sun" light, a faint cool fill light, and minimal ambient — mimicking space illumination |
| **Controls** | `OrbitControls` with damping — drag to rotate, scroll to zoom (clamped 1.8–10 units) |
| **Responsive** | Handles window resize; caps pixel ratio at 2 for performance |

Just save it as `index.html` and open in any modern browser — no build step or server needed.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Mountain</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// — Scene —
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.008);

// — Camera —
const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 1000);
camera.position.set(0, 30, 60);

// — Renderer —
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// — Controls —
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 8, 0);

// — Noise (simple fractal value noise) —
function hash(x, y) {
  let h = x * 374761393 + y * 668265263;
  h = (h ^ (h >> 13)) * 1274126177;
  return ((h ^ (h >> 16)) & 0x7fffffff) / 0x7fffffff;
}

function noise(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = x - ix, fy = y - iy;
  const sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
  const n00 = hash(ix, iy), n10 = hash(ix + 1, iy);
  const n01 = hash(ix, iy + 1), n11 = hash(ix + 1, iy + 1);
  return (n00 * (1 - sx) + n10 * sx) * (1 - sy) + (n01 * (1 - sx) + n11 * sx) * sy;
}

function fbm(x, y, octaves = 6) {
  let val = 0, amp = 0.5, freq = 1;
  for (let i = 0; i < octaves; i++) {
    val += amp * noise(x * freq, y * freq);
    amp *= 0.5; freq *= 2.0;
  }
  return val;
}

// — Mountain geometry —
const size = 80, segments = 256;
const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
geometry.rotateX(-Math.PI / 2);

const pos = geometry.attributes.position;
const colors = new Float32Array(pos.count * 3);

for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), z = pos.getZ(i);

  // Radial falloff so edges blend to flat ground
  const dist = Math.sqrt(x * x + z * z) / (size * 0.5);
  const falloff = Math.max(0, 1 - dist * dist);

  // Height from fractal noise, shaped into a mountain peak
  const h = fbm(x * 0.05 + 5, z * 0.05 + 5, 6) * 40 * falloff * falloff;

  pos.setY(i, h);

  // Vertex colors: snow on top, rock in middle, grass at bottom
  const t = h / 35;
  let r, g, b;
  if (t > 0.75) {
    const s = (t - 0.75) / 0.25;
    r = 0.55 + s * 0.45; g = 0.50 + s * 0.50; b = 0.45 + s * 0.55;
  } else if (t > 0.35) {
    const s = (t - 0.35) / 0.4;
    r = 0.35 + s * 0.20; g = 0.30 + s * 0.20; b = 0.25 + s * 0.20;
  } else {
    r = 0.18 + t * 0.45; g = 0.32 + t * 0.15; b = 0.12 + t * 0.15;
  }
  colors[i * 3] = r;
  colors[i * 3 + 1] = g;
  colors[i * 3 + 2] = b;
}

geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
geometry.computeVertexNormals();

const mountain = new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({
  vertexColors: true,
  flatShading: true,
  roughness: 0.9,
  metalness: 0.0,
}));
mountain.receiveShadow = true;
mountain.castShadow = true;
scene.add(mountain);

// — Water plane —
const water = new THREE.Mesh(
  new THREE.PlaneGeometry(200, 200),
  new THREE.MeshStandardMaterial({ color: 0x1a3a4a, roughness: 0.2, metalness: 0.8 })
);
water.rotation.x = -Math.PI / 2;
water.position.y = -0.5;
water.receiveShadow = true;
scene.add(water);

// — Lighting —
scene.add(new THREE.AmbientLight(0x405070, 1.5));

const sun = new THREE.DirectionalLight(0xffeedd, 3);
sun.position.set(30, 50, 20);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 150;
sun.shadow.camera.left = -60;
sun.shadow.camera.right = 60;
sun.shadow.camera.top = 60;
sun.shadow.camera.bottom = -60;
scene.add(sun);

// — Animation —
function animate(t) {
  requestAnimationFrame(animate);
  water.position.y = -0.5 + Math.sin(t * 0.001) * 0.15;
  controls.update();
  renderer.render(scene, camera);
}
animate(0);

// — Resize —
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in there:**

- **Procedural mountain** — fractal Brownian motion (fBm) noise displaces a subdivided plane, with radial falloff so the edges flatten into ground level
- **Vertex colors** — snow caps (white), rocky mid-slopes (gray-brown), and grassy base (green), all computed per-vertex
- **Flat shading** — gives the faceted, stylized low-poly look
- **Water plane** — subtly animated reflective surface below the mountain
- **Shadow-casting sunlight** + ambient fill + fog for depth
- **OrbitControls** — drag to rotate, scroll to zoom
- **Responsive** — handles window resize

