        cameraModule.position.set(-0.4, 1.2, -bodyDepth/2 - 0.05);
        phoneGroup.add(cameraModule);

        // Lenses
        const lensGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.05, 32);
        const lensMat = new THREE.MeshStandardMaterial({ color: 0x000000, metalness: 1, roughness: 0 });

        const lens1 = new THREE.Mesh(lensGeo, lensMat);
        lens1.rotation.x = Math.PI / 2;
        lens1.position.set(-0.4, 1.5, -bodyDepth/2 - 0.12);
        phoneGroup.add(lens1);

        const lens2 = new THREE.Mesh(lensGeo, lensMat);
        lens2.rotation.x = Math.PI / 2;
        lens2.position.set(-0.4, 0.9, -bodyDepth/2 - 0.12);
        phoneGroup.add(lens2);

        // Side Buttons
        const buttonGeo = new RoundedBoxGeometry(0.05, 0.4, 0.1, 2, 0.02);

        const powerBtn = new THREE.Mesh(buttonGeo, buttonMaterial);
        powerBtn.position.set(bodyWidth/2 + 0.025, 0.5, 0);
        phoneGroup.add(powerBtn);

        const volUpBtn = new THREE.Mesh(buttonGeo, buttonMaterial);
        volUpBtn.position.set(-bodyWidth/2 - 0.025, 0.8, 0);
        phoneGroup.add(volUpBtn);

        const volDownBtn = new THREE.Mesh(buttonGeo, buttonMaterial);
        volDownBtn.position.set(-bodyWidth/2 - 0.025, 0.3, 0);
        phoneGroup.add(volDownBtn);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            phoneGroup.position.y = Math.sin(Date.now() * 0.001) * 0.1;
            phoneGroup.rotation.z = Math.sin(Date.now() * 0.0005) * 0.02;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
