  new THREE.MeshBasicMaterial({ color: 0xffffaa, transparent: true, opacity: 0.95 })
);
flameCore.position.y = -2.1;
flameCore.rotation.x = Math.PI;
rocket.add(flameCore);

// Flame light
const flameLight = new THREE.PointLight(0xff6600, 3, 8);
flameLight.position.y = -2.5;
rocket.add(flameLight);

scene.add(rocket);

// --- Exhaust particles ---
const pCount = 300;
const pGeo = new THREE.BufferGeometry();
const pPositions = new Float32Array(pCount * 3);
const pVelocities = [];
const pLifetimes = new Float32Array(pCount);

function resetParticle(i) {
  const angle = Math.random() * Math.PI * 2;
  const r = Math.random() * 0.2;
  pPositions[i * 3]     = Math.cos(angle) * r;
  pPositions[i * 3 + 1] = -2.4;
  pPositions[i * 3 + 2] = Math.sin(angle) * r;
  pVelocities[i] = {
    x: (Math.random() - 0.5) * 0.04,
    y: -(0.05 + Math.random() * 0.08),
    z: (Math.random() - 0.5) * 0.04
  };
  pLifetimes[i] = Math.random();
}
for (let i = 0; i < pCount; i++) resetParticle(i);

pGeo.setAttribute('position', new THREE.BufferAttribute(pPositions, 3));
const pMat = new THREE.PointsMaterial({ color: 0xff8833, size: 0.12, transparent: true, opacity: 0.7, sizeAttenuation: true });
const particles = new THREE.Points(pGeo, pMat);
rocket.add(particles);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Hover
  rocket.position.y = Math.sin(t * 1.5) * 0.2;
  rocket.rotation.z = Math.sin(t * 0.8) * 0.03;

  // Flicker flame
  flame.scale.set(1 + Math.sin(t * 20) * 0.15, 0.9 + Math.sin(t * 25) * 0.15, 1 + Math.cos(t * 22) * 0.15);
  flameCore.scale.y = 0.9 + Math.sin(t * 30) * 0.2;
  flameLight.intensity = 2.5 + Math.sin(t * 25) * 1.0;

  // Update particles
  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < pCount; i++) {
    pos[i * 3]     += pVelocities[i].x;
    pos[i * 3 + 1] += pVelocities[i].y;
    pos[i * 3 + 2] += pVelocities[i].z;
    pLifetimes[i] -= 0.015;
    if (pLifetimes[i] <= 0) resetParticle(i);
  }
  particles.geometry.attributes.position.needsUpdate = true;
  pMat.opacity = 0.5 + Math.sin(t * 15) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in it:**

- **Rocket** built from primitives — body cylinder, red nose cone, blue stripes, glass window, 4 fins, and a metal nozzle
- **Animated flame** — dual-layer cone (orange outer + yellow core) with flickering scale and a pulsing point light
- **Exhaust particles** — 300 particles streaming downward with random spread and lifetime recycling
- **Starfield** — 2000 random points for a space backdrop
- **Hover animation** — gentle bobbing + slight tilt
- **OrbitControls** — drag to rotate, scroll to zoom
- **ACES tone mapping** for richer lighting

