Here's a complete, self-contained `index.html` that creates a minimal Three.js scene with a rotating 3D star. It uses modern ES modules and imports Three.js directly from a CDN.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Three.js Star</title>
  <style>
    body { margin: 0; overflow: hidden; background: #111; }
    canvas { display: block; }
  </style>
</head>
<body>
  <script type="importmap">
    {
      "imports": {
        "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from 'three';

    // 1. Setup scene, camera, renderer
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.z = 5;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // 2. Create star shape & geometry
    const starShape = new THREE.Shape();
    const outerR = 2, innerR = 0.8, points = 5;
    const step = Math.PI / points;

    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const angle = (i * step) - Math.PI / 2;
      const x = r * Math.cos(angle);
      const y = r * Math.sin(angle);
      i === 0 ? starShape.moveTo(x, y) : starShape.lineTo(x, y);
    }
    starShape.closePath();

    const starGeo = new THREE.ExtrudeGeometry(starShape, {
      depth: 0.4, bevelEnabled: true, bevelThickness: 0.1, bevelSize: 0.1
    });
    const starMat = new THREE.MeshStandardMaterial({ color: 0xffd700, metalness: 0.4, roughness: 0.3 });
    const star = new THREE.Mesh(starGeo, starMat);
    scene.add(star);

    // 3. Lighting
    scene.add(new THREE.AmbientLight(0xffffff, 0.4));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(4, 4, 4);
    scene.add(dirLight);

    // 4. Animation & Resize
    function animate() {
      requestAnimationFrame(animate);
      star.rotation.z += 0.01;
      star.rotation.x = Math.sin(Date.now() * 0.001) * 0.2;
      renderer.render(scene, camera);
    }
    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
