```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three.js Sun</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 1000);
camera.position.z = 4;

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ReinhardToneMapping;
document.body.appendChild(renderer.domElement);

// ── Post-processing (bloom) ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.8, 0.6, 0.2
);
composer.addPass(bloom);

// ── Starfield background ──
const starGeo = new THREE.BufferGeometry();
const starCount = 3000;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++) starPos[i] = (Math.random() - 0.5) * 400;
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
scene.add(new THREE.Points(starGeo, new THREE.PointsMaterial({
  color: 0xffffff, size: 0.3, sizeAttenuation: true
})));

// ── Sun Shader ──
const sunVert = `
  // Simplex 3D noise
  vec4 permute(vec4 x){ return mod(((x*34.0)+1.0)*x, 289.0); }
  vec4 taylorInvSqrt(vec4 r){ return 1.79284291400159 - 0.85373472095314 * r; }
  float snoise(vec3 v){
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i  = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g  = step(x0.yzx, x0.xyz);
    vec3 l  = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod(i, 289.0);
    vec4 p = permute(permute(permute(
      i.z + vec4(0.0, i1.z, i2.z, 1.0))
      + i.y + vec4(0.0, i1.y, i2.y, 1.0))
      + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    float n_ = 1.0/7.0;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j  = p - 49.0 * floor(p * ns.z * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);
    vec4 x  = x_ * ns.x + ns.yyyy;
    vec4 y  = y_ * ns.x + ns.yyyy;
    vec4 h  = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
  }

  uniform float uTime;
  varying vec2 vUv;
  varying float vNoise;
  varying vec3 vNormal;
  varying vec3 vWorldPos;

  void main() {
    vUv = uv;
    vNormal = normalMatrix * normal;
    vec3 pos = position;

    // Multi-octave noise displacement
    float n = snoise(pos * 1.5 + uTime * 0.3) * 0.12;
    n += snoise(pos * 3.0 - uTime * 0.5) * 0.06;
    n += snoise(pos * 6.0 + uTime * 0.2) * 0.03;
    pos += normal * n;

    vNoise = n;
    vec4 worldPos = modelMatrix * vec4(pos, 1.0);
    vWorldPos = worldPos.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const sunFrag = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vNoise;
  varying vec3 vNormal;
  varying vec3 vWorldPos;

  // Hash-based pseudo-random
  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
  }

  void main() {
    // Base color gradient from noise
    float t = vNoise * 3.0 + 0.5;

    // Hot core colors
    vec3 hot   = vec3(1.0, 0.95, 0.6);
    vec3 mid   = vec3(1.0, 0.55, 0.05);
    vec3 cool  = vec3(0.85, 0.15, 0.0);

    vec3 col = mix(cool, mid, smoothstep(0.0, 0.5, t));
    col = mix(col, hot, smoothstep(0.4, 1.0, t));

    // Dark sunspot-like patches
    float spots = smoothstep(0.75, 0.85, vNoise);
    col = mix(col, col * 0.3, spots * 0.7);

    // Fresnel rim brightening
    vec3 viewDir = normalize(cameraPosition - vWorldPos);
    float rim = 1.0 - max(dot(normalize(vNormal), viewDir), 0.0);
    col += vec3(1.0, 0.4, 0.05) * pow(rim, 2.5) * 1.5;

    // Subtle animated bright patches
    float flicker = sin(uTime * 2.0 + vUv.x * 20.0) * 0.5 + 0.5;
    col += vec3(0.15, 0.1, 0.02) * flicker * smoothstep(0.3, 0.7, vNoise);

    gl_FragColor = vec4(col, 1.0);
  }
`;

const sun = new THREE.Mesh(
  new THREE.SphereGeometry(1, 128, 128),
  new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 } },
    vertexShader: sunVert,
    fragmentShader: sunFrag,
  })
);
scene.add(sun);

// ── Corona (outer glow shell) ──
const coronaGeo = new THREE.SphereGeometry(1.35, 64, 64);
const coronaMat = new THREE.ShaderMaterial({
  uniforms: { uTime: { value: 0 } },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    void main() {
      vNormal = normalize(normalMatrix * normal);
      vWorldPos = (modelMatrix * vec4(position, 1.0)).xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    void main() {
      vec3 viewDir = normalize(cameraPosition - vWorldPos);
      float rim = 1.0 - max(dot(vNormal, viewDir), 0.0);
      float glow = pow(rim, 3.0) * 1.8;

      // Subtle pulsing
      glow *= 0.85 + 0.15 * sin(uTime * 1.5);

      vec3 col = mix(vec3(1.0, 0.5, 0.05), vec3(1.0, 0.2, 0.0), rim);
      gl_FragColor = vec4(col, glow);
    }
  `,
  transparent: true,
  blending: THREE.AdditiveBlending,
  side: THREE.BackSide,
  depthWrite: false,
});
scene.add(new THREE.Mesh(coronaGeo, coronaMat));

// ── Corona particles ──
const particleCount = 2000;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(particleCount * 3);
const pVel = [];
for (let i = 0; i < particleCount; i++) {
  const r = 1.0 + Math.random() * 1.5;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  pPos[i*3]   = r * Math.sin(phi) * Math.cos(theta);
  pPos[i*3+1] = r * Math.sin(phi) * Math.sin(theta);
  pPos[i*3+2] = r * Math.cos(phi);
  pVel.push({ r, theta, phi, speed: 0.001 + Math.random() * 0.003 });
}
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
scene.add(new THREE.Points(pGeo, new THREE.PointsMaterial({
  color: 0xffaa33, size: 0.03, transparent: true, opacity: 0.6,
  blending: THREE.AdditiveBlending, depthWrite: false,
})));

// ── Animation ──
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  sun.material.uniforms.uTime.value = t;
  coronaMat.uniforms.uTime.value = t;

  // Slow rotation
  sun.rotation.y = t * 0.05;

  // Animate particles outward
  const positions = pGeo.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    const v = pVel[i];
    v.r += v.speed;
    v.theta += v.speed * 0.5;
    if (v.r > 2.8) { v.r = 1.0 + Math.random() * 0.3; }
    positions[i*3]   = v.r * Math.sin(v.phi) * Math.cos(v.theta);
    positions[i*3+1] = v.r * Math.sin(v.phi) * Math.sin(v.theta);
    positions[i*3+2] = v.r * Math.cos(v.phi);
  }
  pGeo.attributes.position.needsUpdate = true;

  // Gentle camera sway
  camera.position.x = Math.sin(t * 0.15) * 0.3;
  camera.position.y = Math.cos(t * 0.1) * 0.2;
  camera.lookAt(0, 0, 0);

  composer.render();
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in here:**

| Layer | Technique |
|---|---|
| **Sun surface** | 128-segment sphere with GLSL simplex noise displacement (3 octaves) + color mapping from dark spots → orange → white-hot |
| **Fresnel rim** | Rim brightening simulates limb darkening/brightening |
| **Corona shell** | Back-face rendered sphere with additive blending and cubic rim falloff |
| **Corona particles** | 2,000 points streaming outward with radial velocity, additive blended |
| **Bloom** | `UnrealBloomPass` post-processing for that characteristic solar glow |
| **Starfield** | 3,000 random points for a space backdrop |
| **Camera** | Gentle sinusoidal sway for a cinematic feel |

