<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Three.js Tent Demo</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { overflow: hidden; background: #000; }
    canvas { display: block; }
    #info {
      position: absolute; top: 12px; left: 50%; transform: translateX(-50%);
      color: #fff; font-family: system-ui, sans-serif; font-size: 14px;
      background: rgba(0,0,0,.55); padding: 6px 16px; border-radius: 20px;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div id="info">🏕️ Click &amp; drag to orbit · Scroll to zoom</div>

  <script type="importmap">
  {
    "imports": {
      "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
      "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
    }
  }
  </script>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    // ── Scene ──────────────────────────────────────────────
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87ceeb);
    scene.fog = new THREE.FogExp2(0x87ceeb, 0.012);

    // ── Camera ─────────────────────────────────────────────
    const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
    camera.position.set(6, 4, 8);

    // ── Renderer ───────────────────────────────────────────
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // ── Controls ───────────────────────────────────────────
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 1.5, 0);
    controls.enableDamping = true;
    controls.dampingFactor = 0.08;

    // ── Lights ─────────────────────────────────────────────
    scene.add(new THREE.AmbientLight(0x9395a7, 1.2));
    scene.add(new THREE.HemisphereLight(0x87ceeb, 0x556b2f, 0.6));

    const sun = new THREE.DirectionalLight(0xfff4e0, 2.5);
    sun.position.set(5, 12, 6);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.near = 0.5;
    sun.shadow.camera.far = 40;
    sun.shadow.camera.left = -10;
    sun.shadow.camera.right = 10;
    sun.shadow.camera.top = 10;
    sun.shadow.camera.bottom = -10;
    scene.add(sun);

    // ── Ground ─────────────────────────────────────────────
    const groundGeo = new THREE.CircleGeometry(30, 64);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a7c3f, roughness: 1 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // ── Tent Geometry ──────────────────────────────────────
    const W = 3, H = 3.2, D = 4, DH = 1.4;
    // Vertices: 0=peak, 1=frontLeft, 2=frontRight, 3=backLeft, 4=backRight, 5=doorTop
    const v = [
      [ 0,   H, 0 ],          // 0 peak
      [ -W/2, 0,  D/2 ],      // 1 front-left
      [  W/2, 0,  D/2 ],      // 2 front-right
      [ -W/2, 0, -D/2 ],      // 3 back-left
      [  W/2, 0, -D/2 ],      // 4 back-right
      [ 0,   DH, D/2 ],       // 5 door-top
    ];

    // Index groups: [face vertices], [double-sided]
    const faces = [
      // Front left triangle
      { idx: [0, 1, 5], two: true },
      // Front right triangle
      { idx: [0, 5, 2], two: true },
      // Back triangle
      { idx: [0, 3, 4], two: false },
      // Left slope
      { idx: [0, 1, 3], two: false },
      // Right slope
      { idx: [0, 2, 4], two: false },
      // Floor
      { idx: [1, 3, 4], two: false },
      { idx: [1, 4, 2], two: false },
    ];

    const positions = [], normals = [], colors = [];
    const tentColor = new THREE.Color(0xf5f0e8);
    const doorColor = new THREE.Color(0x2a1f14);
    const floorColor = new THREE.Color(0x8b7355);

    function tri(i, j, k, color, twoSided) {
      const a = v[i], b = v[j], c = v[k];
      const ax = positions.length / 3;
      const ab = new THREE.Vector3().subVectors(b, a);
      const ac = new THREE.Vector3().subVectors(c, a);
      const n = new THREE.Vector3().crossVectors(ab, ac).normalize();

      for (const [p, normal] of [[a, n], [b, n], [c, n]]) {
        positions.push(...p);
        normals.push(...normal);
        colors.push(...color);
      }
      if (twoSided) {
        for (const [p] of [[c, n], [b, n], [a, n]]) {
          positions.push(...p);
          normals.push(...n);
          colors.push(...color);
        }
      }
    }

    for (const f of faces) {
      const col = (f.idx.includes(5)) ? doorColor : floorColor;
      tri(f.idx[0], f.idx[1], f.idx[2], col, f.two);
    }

    const tentGeo = new THREE.BufferGeometry();
    tentGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    tentGeo.setAttribute('normal',   new THREE.Float32BufferAttribute(normals, 3));
    tentGeo.setAttribute('color',    new THREE.Float32BufferAttribute(colors, 3));

    const tentMat = new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.85,
      side: THREE.DoubleSide,
    });
    const tent = new THREE.Mesh(tentGeo, tentMat);
    tent.castShadow = true;
    tent.receiveShadow = true;
    scene.add(tent);

    // ── Ridge pole ─────────────────────────────────────────
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x8b6f47, roughness: 0.7 });
    const ridgeGeo = new THREE.CylinderGeometry(0.04, 0.04, D + 0.6, 8);
    const ridge = new THREE.Mesh(ridgeGeo, poleMat);
    ridge.rotation.x = Math.PI / 2;
    ridge.position.set(0, H, 0);
    ridge.castShadow = true;
    scene.add(ridge);

    // ── Guy lines (ropes from peak to ground stakes) ───────
    const ropeMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.9 });
    const stakePositions = [
      [ -2.8, 0.01,  3.2 ],
      [  2.8, 0.01,  3.2 ],
      [ -2.8, 0.01, -3.0 ],
      [  2.8, 0.01, -3.0 ],
    ];
    for (const sp of stakePositions) {
      const dir = new THREE.Vector3(...sp).sub(new THREE.Vector3(0, H, 0));
      const len = dir.length();
      const ropeGeo = new THREE.CylinderGeometry(0.012, 0.012, len, 6);
      const rope = new THREE.Mesh(ropeGeo, ropeMat);
      const mid = new THREE.Vector3(...sp).add(new THREE.Vector3(0, H, 0)).multiplyScalar(0.5);
      rope.position.copy(mid);
      rope.lookAt(new THREE.Vector3(0, H, 0));
      rope.rotateX(Math.PI / 2);
      scene.add(rope);

      // Stake
      const stakeGeo = new THREE.CylinderGeometry(0.025, 0.035, 0.35, 6);
      const stake = new THREE.Mesh(stakeGeo, poleMat);
      stake.position.set(sp[0], 0.175, sp[2]);
      stake.castShadow = true;
      scene.add(stake);
    }

    // ── Door flap (slightly open) ──────────────────────────
    const flapShape = new THREE.Shape();
    flapShape.moveTo(0, 0);
    flapShape.lineTo(0.75, 0);
    flapShape.lineTo(0, DH);
    flapShape.lineTo(-0.75, 0);
    flapShape.closePath();

    const flapGeo = new THREE.ShapeGeometry(flapShape, 6);
    const flapMat = new THREE.MeshStandardMaterial({
      color: 0xf5f0e8, roughness: 0.85, side: THREE.DoubleSide
    });
    const flap = new THREE.Mesh(flapGeo, flapMat);
    flap.position.set(0, 0, D / 2 + 0.01);
    flap.rotation.y = -0.45;          // swing open
    flap.castShadow = true;
    scene.add(flap);

    // ── Scattered rocks & small bushes ─────────────────────
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x777777, roughness: 1 });
    const bushMat = new THREE.MeshStandardMaterial({ color: 0x3a6b35, roughness: 1 });

    for (let i = 0; i < 20; i++) {
      const angle = Math.random() * Math.PI * 2;
      const dist  = 3 + Math.random() * 12;
      const s = 0.08 + Math.random() * 0.18;
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(s, 0),
        rockMat
      );
      rock.position.set(Math.cos(angle) * dist, s * 0.4, Math.sin(angle) * dist);
      rock.rotation.set(Math.random(), Math.random(), Math.random());
      rock.castShadow = true;
      rock.receiveShadow = true;
      scene.add(rock);
    }

    for (let i = 0; i < 10; i++) {
      const angle = Math.random() * Math.PI * 2;
      const dist  = 4 + Math.random() * 10;
      const s = 0.25 + Math.random() * 0.35;
      const bush = new THREE.Mesh(
        new THREE.SphereGeometry(s, 8, 6),
        bushMat
      );
      bush.position.set(Math.cos(angle) * dist, s * 0.6, Math.sin(angle) * dist);
      bush.scale.y = 0.7 + Math.random() * 0.3;
      bush.castShadow = true;
      bush.receiveShadow = true;
      scene.add(bush);
    }

    // ── Resize ─────────────────────────────────────────────
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });

    // ── Animate ────────────────────────────────────────────
    function loop() {
      requestAnimationFrame(loop);
      controls.update();
      renderer.render(scene, camera);
    }
    loop();
  </script>
</body>
</html>
