const stackTop = new THREE.Mesh(
  new THREE.CylinderGeometry(0.38, 0.25, 0.15, 12),
  new THREE.MeshLambertMaterial({ color: 0x444444 })
);
stackTop.position.set(2.1, 2.85, 0);
loco.add(stackTop);

// Cowcatcher
const cow = new THREE.Mesh(
  new THREE.ConeGeometry(1.0, 0.8, 4),
  new THREE.MeshLambertMaterial({ color: 0x333333 })
);
cow.rotation.z = -Math.PI / 2;
cow.rotation.y = Math.PI / 4;
cow.position.set(2.6, 0.4, 0);
loco.add(cow);

// Headlight
const light = new THREE.Mesh(
  new THREE.SphereGeometry(0.15, 8, 8),
  new THREE.MeshBasicMaterial({ color: 0xffffaa })
);
light.position.set(2.3, 1.8, 0.9);
loco.add(light);

// Loco wheels
const locoWheels = [];
for (let x of [-1.5, -0.3, 0.9]) {
  for (let side of [-1, 1]) {
    const w = makeWheel();
    w.position.set(x, 0.45, side * 0.7);
    loco.add(w);
    locoWheels.push(w);
  }
}

// Connecting rod
const rod = new THREE.Mesh(
  new THREE.BoxGeometry(2.8, 0.06, 0.06),
  new THREE.MeshLambertMaterial({ color: 0xcc8800 })
);
rod.position.set(0, 0.45, 0.9);
loco.add(rod);

loco.position.set(0, 0.4, 0);
scene.add(loco);

// --- CARS ---
const cars = [];
const carColors = [0x2255aa, 0xaa4422, 0x22aa44, 0x886622, 0x662288];
const carWheels = [];

for (let i = 0; i < 5; i++) {
  const car = new THREE.Group();

  // Body
  const body = makeCarBody(1.6, 1.4, 3.5, carColors[i], 1.1);
  car.add(body);

  // Roof
  const carRoof = new THREE.Mesh(
    new THREE.BoxGeometry(1.7, 0.06, 3.6),
    new THREE.MeshLambertMaterial({ color: 0xdddddd })
  );
  carRoof.position.y = 1.83;
  car.add(carRoof);

  // Windows
  for (let side of [-1, 1]) {
    for (let wz = -1.2; wz <= 1.2; wz += 0.8) {
      const win = new THREE.Mesh(
        new THREE.PlaneGeometry(0.35, 0.35),
        new THREE.MeshLambertMaterial({ color: 0x88ccff })
      );
      win.position.set(0, 1.2, side * 0.81);
      win.position.z = wz;
      win.rotation.y = side > 0 ? 0 : Math.PI;
      car.add(win);
    }
  }

  // Wheels
  for (let x of [-1.2, 1.2]) {
    for (let side of [-1, 1]) {
      const w = makeWheel();
      w.position.set(x, 0.45, side * 0.7);
      car.add(w);
      carWheels.push(w);
    }
  }

  // Coupling
  const coupler = new THREE.Mesh(
    new THREE.CylinderGeometry(0.05, 0.05, 0.5, 8),
    new THREE.MeshLambertMaterial({ color: 0x666666 })
  );
  coupler.rotation.x = Math.PI / 2;
  coupler.position.set(0, 0.6, -1.95);
  car.add(coupler);

  car.position.set(0, 0, -10 - i * 5);
  scene.add(car);
  cars.push(car);
}

// --- TREES ---
function makeTree(x, z) {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(
    new THREE.CylinderGeometry(0.15, 0.2, 2, 6),
    new THREE.MeshLambertMaterial({ color: 0x8B4513 })
  );
  trunk.position.y = 1;
  trunk.castShadow = true;
  g.add(trunk);
  const leaves = new THREE.Mesh(
    new THREE.ConeGeometry(1.2, 3, 8),
    new THREE.MeshLambertMaterial({ color: 0x2d6b30 })
  );
  leaves.position.y = 3;
  leaves.castShadow = true;
  g.add(leaves);
  g.position.set(x, 0, z);
  scene.add(g);
}

for (let z = -50; z < 55; z += 4) {
  makeTree(-6 - Math.random() * 8, z + Math.random() * 2);
  makeTree(6 + Math.random() * 8, z + Math.random() * 2);
}

// --- SMOKE PARTICLES ---
const smokeParticles = [];
const smokeMat = new THREE.MeshBasicMaterial({ color: 0xaaaaaa, transparent: true, opacity: 0.6 });

function spawnSmoke() {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.2 + Math.random() * 0.15, 6, 6), smokeMat.clone());
  s.position.set(loco.position.x + 2.1, 3.2, loco.position.z);
  s.userData = { vel: new THREE.Vector3(0.02, 0.04 + Math.random() * 0.03, (Math.random() - 0.5) * 0.02), life: 1 };
  scene.add(s);
  smokeParticles.push(s);
}

// --- ANIMATION ---
let time = 0;
const speed = 0.04;

function animate() {
  requestAnimationFrame(animate);
  time += speed;

  // Move train forward
  const totalLength = 35;
  const trainZ = ((time * 15) % (totalLength + 20)) - 10;

  loco.position.z = trainZ;
  cars.forEach((car, i) => {
    car.position.z = trainZ - 10 - i * 5;
  });

  // Rotate wheels
  const wheelAngle = time * 3;
  [...locoWheels, ...carWheels].forEach(w => {
    w.children[0].rotation.x = wheelAngle;
    w.children[1].rotation.x = wheelAngle;
  });

  // Smoke
  if (Math.random() < 0.3) spawnSmoke();
  for (let i = smokeParticles.length - 1; i >= 0; i--) {
    const p = smokeParticles[i];
    p.position.add(p.userData.vel);
    p.userData.life -= 0.008;
    p.material.opacity = p.userData.life * 0.5;
    p.scale.multiplyScalar(1.01);
    if (p.userData.life <= 0) {
      scene.remove(p);
      smokeParticles.splice(i, 1);
    }
  }

  // Camera follows
  controls.target.set(loco.position.x, 2, loco.position.z);
  controls.update();
  renderer.render(scene, camera);
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's included:**

- **Locomotive** — boiler with gold bands, red cabin with windows, smokestack, cowcatcher, headlight, and a connecting rod
- **5 colored passenger cars** — each with roofs, side windows, and couplers
- **Track** — dual rails with wooden ties stretching across the scene
- **Trees** — randomly placed along both sides of the track
- **Smoke particles** — puffing from the smokestack with fade-out and expansion
- **Animation** — train moves along the track, wheels rotate, camera follows via OrbitControls
- **Lighting & shadows** — directional sun with shadow mapping + ambient fill
- **Fog & sky** — sky-blue background with distance fog for depth

