```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three.js Truck</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a2e; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene, Camera, Renderer ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 60, 120);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
camera.position.set(12, 8, 14);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Controls ---
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2, 0);
controls.enableDamping = true;
controls.maxPolarAngle = Math.PI / 2.05;
controls.update();

// --- Lights ---
scene.add(new THREE.HemisphereLight(0xffeedd, 0x444466, 0.8));

const sun = new THREE.DirectionalLight(0xfff4e0, 1.8);
sun.position.set(10, 20, 8);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -15;
sun.shadow.camera.right = 15;
sun.shadow.camera.top = 15;
sun.shadow.camera.bottom = -15;
scene.add(sun);

// --- Materials ---
const cabMat = new THREE.MeshStandardMaterial({ color: 0xcc2200, metalness: 0.5, roughness: 0.3 });
const chromeMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, metalness: 0.9, roughness: 0.1 });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x88ccff, metalness: 0.1, roughness: 0.05, transparent: true, opacity: 0.5 });
const tireMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 });
const rimMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.7, roughness: 0.3 });
const cargoMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, metalness: 0.3, roughness: 0.5 });
const bumperMat = new THREE.MeshStandardMaterial({ color: 0x999999, metalness: 0.8, roughness: 0.2 });
const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffcc, emissive: 0xffffaa, emissiveIntensity: 0.5 });
const tailLightMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.4 });
const chassisMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.4, roughness: 0.6 });

// --- Truck Group ---
const truck = new THREE.Group();

// Chassis frame
const chassis = new THREE.Mesh(new THREE.BoxGeometry(10, 0.3, 2.6), chassisMat);
chassis.position.set(0, 1.2, 0);
chassis.castShadow = true;
truck.add(chassis);

// Cargo bed
const cargo = new THREE.Mesh(new THREE.BoxGeometry(5.5, 2.8, 2.8), cargoMat);
cargo.position.set(-1.8, 2.9, 0);
cargo.castShadow = true;
cargo.receiveShadow = true;
truck.add(cargo);

// Cargo bed rails (top)
const railGeo = new THREE.BoxGeometry(5.5, 0.1, 0.1);
for (const z of [-1.35, 1.35]) {
  const rail = new THREE.Mesh(railGeo, chromeMat);
  rail.position.set(-1.8, 4.35, z);
  truck.add(rail);
}
const railGeoSide = new THREE.BoxGeometry(0.1, 0.1, 2.8);
for (const x of [-4.55, 0.95]) {
  const rail = new THREE.Mesh(railGeoSide, chromeMat);
  rail.position.set(x, 4.35, 0);
  truck.add(rail);
}

// Cab
const cab = new THREE.Mesh(new THREE.BoxGeometry(3.2, 3, 2.8), cabMat);
cab.position.set(2.8, 3.1, 0);
cab.castShadow = true;
cab.receiveShadow = true;
truck.add(cab);

// Cab roof (slightly overhanging)
const roof = new THREE.Mesh(new THREE.BoxGeometry(3.0, 0.15, 2.9), cabMat);
roof.position.set(2.8, 4.65, 0);
roof.castShadow = true;
truck.add(roof);

// Windshield
const windshieldGeo = new THREE.BoxGeometry(0.1, 1.6, 2.4);
const windshield = new THREE.Mesh(windshieldGeo, glassMat);
windshield.position.set(4.41, 3.6, 0);
windshield.rotation.z = -0.15;
truck.add(windshield);

// Side windows
for (const side of [-1, 1]) {
  const sideWin = new THREE.Mesh(new THREE.BoxGeometry(2.0, 1.2, 0.05), glassMat);
  sideWin.position.set(2.8, 3.5, side * 1.42);
  truck.add(sideWin);
}

// Front grille
const grille = new THREE.Mesh(new THREE.BoxGeometry(0.15, 1.2, 2.0), chromeMat);
grille.position.set(4.45, 2.8, 0);
truck.add(grille);

// Grille slats
for (let i = -2; i <= 2; i++) {
  const slat = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.08, 1.8), bumperMat);
  slat.position.set(4.53, 2.8 + i * 0.22, 0);
  truck.add(slat);
}

// Headlights
for (const z of [-0.8, 0.8]) {
  const hl = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.1, 16), lightMat);
  hl.rotation.x = Math.PI / 2;
  hl.position.set(4.53, 2.2, z);
  truck.add(hl);
}

// Tail lights
for (const z of [-1.0, 1.0]) {
  const tl = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.3, 0.2), tailLightMat);
  tl.position.set(-4.55, 3.5, z);
  truck.add(tl);
}

// Bumpers
const frontBumper = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.25, 2.6), bumperMat);
frontBumper.position.set(4.65, 1.7, 0);
truck.add(frontBumper);

const rearBumper = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.25, 2.6), bumperMat);
rearBumper.position.set(-4.65, 1.7, 0);
truck.add(rearBumper);

// Exhaust stack
const exhaust = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 2.5, 12), chromeMat);
exhaust.position.set(1.5, 5.5, -0.9);
exhaust.castShadow = true;
truck.add(exhaust);

// Exhaust tip
const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.1, 0.2, 12), chromeMat);
tip.position.set(1.5, 6.8, -0.9);
truck.add(tip);

// Mirror arms & mirrors
for (const side of [-1, 1]) {
  const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.8, 8), chromeMat);
  arm.rotation.z = Math.PI / 2;
  arm.position.set(3.8, 4.0, side * 1.6);
  truck.add(arm);

  const mirror = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.5, 0.1), cabMat);
  mirror.position.set(4.2, 4.0, side * 2.0);
  truck.add(mirror);
}

// Steps
for (const x of [1.8, 2.5]) {
  const step = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.08, 0.4), bumperMat);
  step.position.set(x, 1.5, -1.4);
  truck.add(step);
}

// --- Wheels ---
function createWheel() {
  const group = new THREE.Group();
  const tire = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.25, 12, 24), tireMat);
  tire.castShadow = true;
  group.add(tire);

  // Rim
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.4, 0.35, 16), rimMat);
  rim.rotation.x = Math.PI / 2;
  group.add(rim);

  // Hub
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.4, 12), chromeMat);
  hub.rotation.x = Math.PI / 2;
  group.add(hub);

  // Spokes
  for (let i = 0; i < 6; i++) {
    const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.35, 0.06), rimMat);
    spoke.rotation.z = (i / 6) * Math.PI;
    spoke.rotation.x = Math.PI / 2;
    group.add(spoke);
  }

  return group;
}

const wheelPositions = [
  { x: 3.5, y: 0.85, z: 1.5 },
  { x: 3.5, y: 0.85, z: -1.5 },
  { x: -3.2, y: 0.85, z: 1.5 },
  { x: -3.2, y: 0.85, z: -1.5 },
  { x: -3.8, y: 0.85, z: 1.5 },
  { x: -3.8, y: 0.85, z: -1.5 },
];

const wheels = [];
wheelPositions.forEach(pos => {
  const wheel = createWheel();
  wheel.position.set(pos.x, pos.y, pos.z);
  truck.add(wheel);
  wheels.push(wheel);
});

scene.add(truck);

// --- Ground ---
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(200, 200),
  new THREE.MeshStandardMaterial({ color: 0x558833, roughness: 0.9 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Road
const road = new THREE.Mesh(
  new THREE.PlaneGeometry(200, 12),
  new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.8 })
);
road.rotation.x = -Math.PI / 2;
road.position.y = 0.01;
road.receiveShadow = true;
scene.add(road);

// Road lines
for (let i = -90; i <= 90; i += 6) {
  const line = new THREE.Mesh(
    new THREE.PlaneGeometry(3, 0.2),
    new THREE.MeshStandardMaterial({ color: 0xffff44 })
  );
  line.rotation.x = -Math.PI / 2;
  line.position.set(i, 0.02, 0);
  scene.add(line);
}

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle truck bob
  truck.position.y = Math.sin(t * 1.5) * 0.05;

  // Wheel spin
  wheels.forEach(w => {
    w.children[0].rotation.z = t * 2; // tire
    w.children[1].rotation.y = t * 2; // rim
    w.children[2].rotation.y = t * 2; // hub
    for (let i = 3; i < w.children.length; i++) {
      w.children[i].rotation.y = t * 2; // spokes
    }
  });

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
