            side: THREE.DoubleSide,
            roughness: 0.4
        });
        const canopy = new THREE.Mesh(canopyGeo, canopyMat);
        canopy.scale.y = 0.6; // Flatten it
        canopy.position.y = 0;
        canopy.castShadow = true;
        canopy.receiveShadow = true;
        umbrella.add(canopy);

