        const ribCount = 8;
        const ribMat = new THREE.MeshStandardMaterial({ color: 0x8B4513 });

        for (let i = 0; i < ribCount; i++) {
            const angle = (i / ribCount) * Math.PI * 2;
            const x = Math.cos(angle) * canopyRadius;
            const z = Math.sin(angle) * canopyRadius;

            // Create a line geometry for the rib
            const points = [];
            points.push(new THREE.Vector3(0, canopyRadius * 0.6, 0)); // Top center
            points.push(new THREE.Vector3(x, 0, z)); // Bottom edge

            const ribGeo = new THREE.BufferGeometry().setFromPoints(points);
            const rib = new THREE.Line(ribGeo, new THREE.LineBasicMaterial({ color: 0x333333, linewidth: 2 }));
            umbrella.add(rib);
        }

        // 3. Shaft
