        const shaftMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const shaft = new THREE.Mesh(shaftGeo, shaftMat);
        shaft.position.y = -shaftHeight / 2;
        shaft.castShadow = true;
        umbrella.add(shaft);

        // 4. Handle (Hook)
        const handleCurve = new THREE.CubicBezierCurve3(
            new THREE.Vector3(0, -shaftHeight, 0),
            new THREE.Vector3(0, -shaftHeight - 0.5, 0),
            new THREE.Vector3(0.5, -shaftHeight - 1, 0),
            new THREE.Vector3(0, -shaftHeight - 1.2, 0)
        );
        const handleGeo = new THREE.TubeGeometry(handleCurve, 20, 0.08, 8, false);
        const handle = new THREE.Mesh(handleGeo, shaftMat);
        handle.castShadow = true;
        umbrella.add(handle);

        // Position umbrella
        umbrella.position.y = 4;

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
