<body>
  <script type="importmap">
  {
    "imports": {
      "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
      "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
    }
  }
  </script>
  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    // ── Scene, Camera, Renderer ─────────────────────────────
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a1628);
    scene.fog = new THREE.FogExp2(0x0a1628, 0.018);

    const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 200);
    camera.position.set(0, 4, 14);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 0, 0);

    // ── Lighting ────────────────────────────────────────────
    scene.add(new THREE.AmbientLight(0x334466, 1.5));

    const sunLight = new THREE.DirectionalLight(0x88aacc, 3);
    sunLight.position.set(5, 15, 8);
    scene.add(sunLight);

    const rimLight = new THREE.DirectionalLight(0x4466aa, 1.5);
    rimLight.position.set(-5, -3, -8);
    scene.add(rimLight);

    // ── Whale Builder ───────────────────────────────────────
    const whaleGroup = new THREE.Group();

    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x3a5a7c,
      roughness: 0.45,
      metalness: 0.1,
    });
    const bellyMat = new THREE.MeshStandardMaterial({
      color: 0x8ab4cc,
      roughness: 0.5,
      metalness: 0.05,
    });
    const darkMat = new THREE.MeshStandardMaterial({
      color: 0x2a3a4c,
      roughness: 0.5,
    });

    // Body — stretched sphere
    const body = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 24), bodyMat);
    body.scale.set(2.8, 1, 1.3);
    whaleGroup.add(body);

    // Belly patch
    const belly = new THREE.Mesh(new THREE.SphereGeometry(0.95, 32, 16), bellyMat);
    belly.scale.set(2.4, 0.55, 1.1);
    belly.position.set(0, -0.35, 0);
    whaleGroup.add(belly);

    // Head
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.9, 32, 24), bodyMat);
    head.scale.set(1, 0.95, 1.1);
    head.position.set(2.6, 0.1, 0);
    whaleGroup.add(head);

    // Blowhole ridge
    const blowhole = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 0.2, 12), darkMat);
    blowhole.position.set(2.9, 0.75, 0);
    whaleGroup.add(blowhole);

    // Eyes
    const eyeGeo = new THREE.SphereGeometry(0.06, 12, 12);
    const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.2 });
    for (const side of [-1, 1]) {
      const eye = new THREE.Mesh(eyeGeo, eyeMat);
      eye.position.set(3.0, 0.25, side * 0.75);
      whaleGroup.add(eye);
    }

    // Mouth line (torus fragment)
    const mouth = new THREE.Mesh(
      new THREE.TorusGeometry(0.5, 0.03, 8, 24, Math.PI * 0.6),
      darkMat
    );
    mouth.position.set(3.35, -0.15, 0);
    mouth.rotation.y = Math.PI / 2;
    mouth.rotation.z = Math.PI * 0.2;
    whaleGroup.add(mouth);

    // Tail stock (tapering cylinder)
    const tailStock = new THREE.Mesh(
      new THREE.CylinderGeometry(0.35, 0.15, 2.2, 16),
      bodyMat
    );
    tailStock.rotation.z = Math.PI / 2;
    tailStock.position.set(-3.4, 0, 0);
    whaleGroup.add(tailStock);

    // Tail flukes (two half-disks)
    const tailPivot = new THREE.Group();
    tailPivot.position.set(-4.5, 0, 0);

    const flukeShape = new THREE.Shape();
    flukeShape.moveTo(0, 0);
    flukeShape.quadraticCurveTo(0.8, 0.6, 1.4, 1.4);
    flukeShape.quadraticCurveTo(0.6, 1.0, 0, 0.2);

    const flukeGeo = new THREE.ShapeGeometry(flukeShape);

    for (const side of [-1, 1]) {
      const fluke = new THREE.Mesh(flukeGeo, bodyMat);
      fluke.rotation.y = side * Math.PI / 2;
      fluke.rotation.x = side * 0.3;
      fluke.position.set(0, side * 0.05, 0);
      if (side === -1) fluke.scale.z = -1;
      tailPivot.add(fluke);
    }
    whaleGroup.add(tailPivot);

    // Pectoral fins
    const finShape = new THREE.Shape();
    finShape.moveTo(0, 0);
    finShape.quadraticCurveTo(0.5, -0.1, 1.2, -0.5);
    finShape.quadraticCurveTo(0.6, -0.2, 0, 0);

    const finGeo = new THREE.ShapeGeometry(finShape);

    for (const side of [-1, 1]) {
      const fin = new THREE.Mesh(finGeo, bodyMat);
      fin.position.set(1.2, -0.3, side * 1.1);
      fin.rotation.x = side * 0.8;
      fin.rotation.y = side * 0.5;
      fin.userData.side = side;
      fin.userData.baseRotX = fin.rotation.x;
      whaleGroup.add(fin);
    }

    // Dorsal fin
    const dorsalShape = new THREE.Shape();
    dorsalShape.moveTo(0, 0);
    dorsalShape.quadraticCurveTo(0.3, 0.4, 0.1, 0.6);
    dorsalShape.lineTo(-0.1, 0);

    const dorsal = new THREE.Mesh(new THREE.ShapeGeometry(dorsalShape), bodyMat);
    dorsal.position.set(-0.5, 0.9, 0);
    dorsal.rotation.x = -0.3;
    whaleGroup.add(dorsal);

    // Belly ridges
    for (let i = 0; i < 5; i++) {
      const ridge = new THREE.Mesh(
        new THREE.BoxGeometry(0.03, 0.35, 1.15),
        darkMat
      );
      ridge.position.set(1.5 - i * 0.5, -0.55, 0);
      whaleGroup.add(ridge);
    }

    scene.add(whaleGroup);

    // ── Bubbles ─────────────────────────────────────────────
    const bubbleCount = 120;
    const bubbleGeo = new THREE.SphereGeometry(0.04, 8, 8);
    const bubbleMat = new THREE.MeshBasicMaterial({
      color: 0x88bbdd,
      transparent: true,
      opacity: 0.35,
    });
    const bubbles = new THREE.InstancedMesh(bubbleGeo, bubbleMat, bubbleCount);
    const bubbleData = [];
    const dummy = new THREE.Object3D();

    for (let i = 0; i < bubbleCount; i++) {
      const pos = new THREE.Vector3(
        (Math.random() - 0.5) * 40,
        (Math.random() - 0.5) * 30,
        (Math.random() - 0.5) * 40
      );
      dummy.position.copy(pos);
      dummy.scale.setScalar(0.5 + Math.random() * 2);
      dummy.updateMatrix();
      bubbles.setMatrixAt(i, dummy.matrix);
      bubbleData.push({
        pos: pos.clone(),
        speed: 0.2 + Math.random() * 0.5,
        wobble: Math.random() * Math.PI * 2,
        wobbleSpeed: 0.5 + Math.random() * 1.5,
        wobbleAmp: 0.3 + Math.random() * 0.7,
      });
    }
    scene.add(bubbles);

    // ── Light rays from above ───────────────────────────────
    const rayGeo = new THREE.CylinderGeometry(0.01, 1.5, 30, 8, 1, true);
    const rayMat = new THREE.MeshBasicMaterial({
      color: 0x6699bb,
      transparent: true,
      opacity: 0.04,
      side: THREE.DoubleSide,
    });
    for (let i = 0; i < 6; i++) {
      const ray = new THREE.Mesh(rayGeo, rayMat);
      ray.position.set(
        (Math.random() - 0.5) * 20,
        10,
        (Math.random() - 0.5) * 20
      );
      ray.rotation.z = (Math.random() - 0.5) * 0.3;
      ray.rotation.x = (Math.random() - 0.5) * 0.3;
      scene.add(ray);
    }

    // ── Floating particles (plankton) ───────────────────────
    const planktonCount = 600;
    const planktonGeo = new THREE.BufferGeometry();
    const planktonPos = new Float32Array(planktonCount * 3);
    for (let i = 0; i < planktonCount; i++) {
      planktonPos[i * 3] = (Math.random() - 0.5) * 60;
      planktonPos[i * 3 + 1] = (Math.random() - 0.5) * 40;
      planktonPos[i * 3 + 2] = (Math.random() - 0.5) * 60;
    }
    planktonGeo.setAttribute('position', new THREE.BufferAttribute(planktonPos, 3));
    const planktonMat = new THREE.PointsMaterial({
      color: 0x88ccee,
      size: 0.06,
      transparent: true,
      opacity: 0.5,
    });
    const plankton = new THREE.Points(planktonGeo, planktonMat);
    scene.add(plankton);

    // ── Animation ───────────────────────────────────────────
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      // Whale swimming motion
      whaleGroup.position.y = Math.sin(t * 0.6) * 0.6;
      whaleGroup.rotation.z = Math.sin(t * 0.8) * 0.05;
      whaleGroup.rotation.x = Math.sin(t * 0.5) * 0.03;

      // Tail wag
      tailPivot.rotation.y = Math.sin(t * 2.5) * 0.4;

      // Pectoral fin flutter
      whaleGroup.children.forEach((child) => {
        if (child.userData?.side) {
          child.rotation.x = child.userData.baseRotX + Math.sin(t * 1.5 + child.userData.side) * 0.15;
        }
      });

      // Blow water spout
      if (Math.floor(t * 2) % 4 === 0) {
        // subtle spout particles handled by bubbles
      }

      // Update bubbles
      for (let i = 0; i < bubbleCount; i++) {
        const b = bubbleData[i];
        b.pos.y += b.speed * 0.016;
        b.pos.x += Math.sin(t * b.wobbleSpeed + b.wobble) * 0.003;
        if (b.pos.y > 20) {
          b.pos.y = -15;
          b.pos.x = (Math.random() - 0.5) * 40;
          b.pos.z = (Math.random() - 0.5) * 40;
        }
        dummy.position.copy(b.pos);
        dummy.scale.setScalar(0.5 + Math.sin(t + i) * 0.3);
        dummy.updateMatrix();
        bubbles.setMatrixAt(i, dummy.matrix);
      }
      bubbles.instanceMatrix.needsUpdate = true;

      // Slowly drift plankton
      plankton.rotation.y = t * 0.01;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // ── Resize ──────────────────────────────────────────────
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
