  <script type="importmap">
    {
      "imports": {
        "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from 'three';

    // Scene & Camera
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0f0f13);
    const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
    camera.position.set(0, 0, 6);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // Lighting
    scene.add(new THREE.AmbientLight(0xffffff, 0.4));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(4, 5, 6);
    scene.add(dirLight);

    // Window Group
    const windowGroup = new THREE.Group();

    const W = 2.4, H = 3.0, D = 0.12;
    const t = D / 2;
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x8B5A2B, roughness: 0.6 });

    // Frame pieces
    const topBotGeo = new THREE.BoxGeometry(W, D, D);
    const leftRightGeo = new THREE.BoxGeometry(D, H, D);

    const top = new THREE.Mesh(topBotGeo, frameMat);
    top.position.y = H / 2 - t;
    const bottom = new THREE.Mesh(topBotGeo, frameMat);
    bottom.position.y = -(H / 2 - t);
    const left = new THREE.Mesh(leftRightGeo, frameMat);
    left.position.x = -(W / 2 - t);
    const right = new THREE.Mesh(leftRightGeo, frameMat);
    right.position.x = W / 2 - t;

    // Cross bars
    const crossH = new THREE.Mesh(new THREE.BoxGeometry(W - 2 * D, D * 0.6, D), frameMat);
    const crossV = new THREE.Mesh(new THREE.BoxGeometry(D * 0.6, H - 2 * D, D), frameMat);

    // Glass
    const glassGeo = new THREE.PlaneGeometry(W - 2 * D, H - 2 * D);
    const glassMat = new THREE.MeshStandardMaterial({
      color: 0x88ccff,
      transparent: true,
      opacity: 0.35,
      roughness: 0.05,
      side: THREE.DoubleSide
    });
    const glass = new THREE.Mesh(glassGeo, glassMat);
    glass.position.z = -0.02; // Slight offset to prevent z-fighting

    windowGroup.add(top, bottom, left, right, crossH, crossV, glass);
    scene.add(windowGroup);

    // Animation
    function animate(time) {
      requestAnimationFrame(animate);
      // Gentle idle rotation to show 3D depth
      windowGroup.rotation.y = Math.sin(time * 0.0008) * 0.15;
      windowGroup.rotation.x = Math.sin(time * 0.0005) * 0.05;
      renderer.render(scene, camera);
    }
    animate(0);

    // Resize handler
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
```

