neck.rotation.z = -0.35;
neck.castShadow = true;
zebra.add(neck);

// Head
const head = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.65, 0.65, 2, 2, 2), zebraMat);
head.position.set(2.25, 4.05, 0);
head.castShadow = true;
zebra.add(head);

// Snout
const snout = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.45, 0.5, 2, 2, 2), zebraMat);
snout.position.set(2.75, 3.9, 0);
snout.castShadow = true;
zebra.add(snout);

// Nose pad
const nose = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.25, 0.45), noseMat);
nose.position.set(3.0, 3.85, 0);
zebra.add(nose);

// Eyes
[-1, 1].forEach(s => {
  const eye = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8), eyeMat);
  eye.position.set(2.35, 4.15, s * 0.35);
  zebra.add(eye);
  // Eyelash hint
  const lash = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.02, 0.02), maneMat);
  lash.position.set(2.38, 4.2, s * 0.35);
  zebra.add(lash);
});

// Ears
[-1, 1].forEach(s => {
  const ear = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.45, 4), maneMat);
  ear.position.set(2.1, 4.5, s * 0.28);
  ear.rotation.z = s * 0.2;
  ear.rotation.x = -0.15;
  zebra.add(ear);
});

// Legs
const legPositions = [
  [0.8, 0.8],   // front right
  [0.8, -0.8],  // front left
  [-0.7, 0.8],  // back right
  [-0.7, -0.8]  // back left
];
const legs = [];
legPositions.forEach(([x, z]) => {
  const legGroup = new THREE.Group();
  // Upper leg
  const upper = new THREE.Mesh(new THREE.BoxGeometry(0.35, 1.0, 0.35), zebraMat);
  upper.position.y = -0.5;
  upper.castShadow = true;
  legGroup.add(upper);
  // Lower leg
  const lower = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.8, 0.28), zebraMat);
  lower.position.y = -1.3;
  lower.castShadow = true;
  legGroup.add(lower);
  // Hoof
  const hoof = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.18, 0.32), hoofMat);
  hoof.position.y = -1.75;
  legGroup.add(hoof);

  legGroup.position.set(x, 1.55, z);
  zebra.add(legGroup);
  legs.push(legGroup);
});

// Tail
const tailGroup = new THREE.Group();
const tailStem = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.06, 0.8, 6), maneMat);
tailStem.position.y = -0.4;
tailGroup.add(tailStem);
const tailTuft = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.4, 6), maneMat);
tailTuft.position.y = -0.9;
tailGroup.add(tailTuft);
tailGroup.position.set(-1.35, 2.8, 0);
tailGroup.rotation.z = 0.5;
zebra.add(tailGroup);

// Mane
for (let i = 0; i < 8; i++) {
  const m = new THREE.Mesh(
    new THREE.BoxGeometry(0.08, 0.35, 0.55),
    maneMat
  );
  const t = i / 7;
  m.position.set(
    1.3 + t * 0.8,
    3.5 + t * 0.85,
    0
  );
  m.rotation.z = -0.35 + t * 0.1;
  zebra.add(m);
}

// Belly (slightly lighter)
const belly = new THREE.Mesh(
  new THREE.BoxGeometry(2.5, 0.4, 1.2),
  new THREE.MeshStandardMaterial({ color: 0xf5f0e0, roughness: 0.8 })
);
belly.position.set(0, 1.6, 0);
zebra.add(belly);

scene.add(zebra);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle idle breathing
  body.scale.y = 1 + Math.sin(t * 2) * 0.015;
  body.position.y = 2.2 + Math.sin(t * 2) * 0.02;

  // Subtle head bob
  head.position.y = 4.05 + Math.sin(t * 1.5) * 0.03;
  snout.position.y = 3.9 + Math.sin(t * 1.5) * 0.03;
  neck.position.y = 3.3 + Math.sin(t * 2) * 0.02;

  // Tail swish
  tailGroup.rotation.z = 0.5 + Math.sin(t * 3) * 0.25;
  tailGroup.rotation.x = Math.sin(t * 2.5) * 0.15;

  // Leg micro-shift
  legs[0].rotation.z = Math.sin(t * 1.2) * 0.03;
  legs[1].rotation.z = -Math.sin(t * 1.2) * 0.03;
  legs[2].rotation.z = -Math.sin(t * 1.2) * 0.02;
  legs[3].rotation.z = Math.sin(t * 1.2) * 0.02;

  renderer.render(scene, camera);
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
