    // ── Apple Group ────────────────────────────────────────
    const apple = new THREE.Group();

    // Main body (squashed sphere)
    const bodyGeo = new THREE.SphereGeometry(1, 64, 64);
    bodyGeo.scale(1, 0.85, 1);

    // Slight indent at the top
    const posAttr = bodyGeo.attributes.position;
    for (let i = 0; i < posAttr.count; i++) {
      const y = posAttr.getY(i);
      if (y > 0.6) {
        const indent = 1.0 - 0.15 * Math.pow((y - 0.6) / 0.35, 2);
        posAttr.setX(i, posAttr.getX(i) * indent);
        posAttr.setZ(i, posAttr.getZ(i) * indent);
      }
      // Slight bottom indentation
      if (y < -0.7) {
        const factor = 1.0 - 0.08 * Math.pow((-y - 0.7) / 0.3, 2);
        posAttr.setX(i, posAttr.getX(i) * factor);
        posAttr.setZ(i, posAttr.getZ(i) * factor);
      }
