    const leafShape = new THREE.Shape();
    leafShape.moveTo(0, 0);
    leafShape.bezierCurveTo(0.15, 0.15, 0.3, 0.35, 0.25, 0.55);
    leafShape.bezierCurveTo(0.15, 0.65, 0.05, 0.6, 0, 0.55);
