            roughness: 0.4,
            metalness: 0.1
        });

        const banana = new THREE.Mesh(geometry, material);
        scene.add(banana);

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);
            banana.rotation.y += 0.01; // Slow rotation
            renderer.render(scene, camera);
