    new THREE.CylinderGeometry(0.2, 0.3, 2, 8),
    new THREE.MeshStandardMaterial({ color: 0x5C4033 })
  );
  trunk.position.y = 1;
  trunk.castShadow = true;
  g.add(trunk);
  const leaves = new THREE.Mesh(
    new THREE.ConeGeometry(1.2, 3, 8),
    new THREE.MeshStandardMaterial({ color: 0x2d6b1e })
  );
  leaves.position.y = 3;
  leaves.castShadow = true;
  g.add(leaves);
  g.position.set(x, 0, z);
  scene.add(g);
}
makeTree(-6, -4);
makeTree(7, -3);
makeTree(-5, 5);
makeTree(6, 4);

// Animation
const clock = new THREE.Clock();
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  bear.rotation.y = Math.sin(t * 0.5) * 0.3;
  bear.position.y = Math.sin(t * 1.2) * 0.1;
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
```

This creates a **cute 3D bear** built entirely from geometric primitives:

- **Body & head** — scaled spheres in warm brown fur tones
- **Belly & snout** — lighter tan patches
- **Eyes** — dark spheres with white shine highlights
- **Ears** — brown outer with tan inner circles
- **Arms & legs** — elongated spheres with flat paws
- **Nose & mouth** — dark nose + thin torus for a smile
- **Tail** — small sphere behind the body

The scene also includes a **green ground plane**, **rocks**, **pine trees**, **directional sunlight with shadows**, and a gentle **idle bob/sway animation**. Just open it in a browser — no build tools needed.

