const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 2, 0);

/* ───────────── Lights ───────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.6));

const sun = new THREE.DirectionalLight(0xfff4e0, 1.8);
sun.position.set(8, 15, 6);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 50;
sun.shadow.camera.left = sun.shadow.camera.bottom = -15;
sun.shadow.camera.right = sun.shadow.camera.top = 15;
scene.add(sun);

const rim = new THREE.DirectionalLight(0x8ec5fc, 0.5);
rim.position.set(-5, 3, -8);
scene.add(rim);

/* ───────────── Ground ───────────── */
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(80, 80),
  new THREE.MeshStandardMaterial({ color: 0x4a8c3f, roughness: 0.9 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.5;
ground.receiveShadow = true;
scene.add(ground);

/* ───────────── Flowers (tiny ground detail) ───────────── */
function makeFlower(x, z, hue) {
  const g = new THREE.Group();
  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.03, 0.03, 0.4, 6),
    new THREE.MeshStandardMaterial({ color: 0x2d6b1e })
  );
  stem.position.y = 0.2;
  g.add(stem);

  const petalGeo = new THREE.SphereGeometry(0.12, 8, 6);
  const petalMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(`hsl(${hue},80%,65%)`) });
  for (let i = 0; i < 5; i++) {
    const p = new THREE.Mesh(petalGeo, petalMat);
    const a = (i / 5) * Math.PI * 2;
    p.position.set(Math.cos(a) * 0.15, 0.45, Math.sin(a) * 0.15);
    p.scale.set(1, 0.5, 1);
    g.add(p);
  }
  const center = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0xffd700 })
  );
  center.position.y = 0.45;
  g.add(center);

  g.position.set(x, -0.5, z);
  return g;
}

for (let i = 0; i < 30; i++) {
  const angle = Math.random() * Math.PI * 2;
  const rad = 3 + Math.random() * 12;
  scene.add(makeFlower(Math.cos(angle) * rad, Math.sin(angle) * rad, Math.random() * 360));
}

/* ───────────── Build the Bee ───────────── */
const bee = new THREE.Group();

const yellow = new THREE.MeshStandardMaterial({ color: 0xffcc00, roughness: 0.35 });
const black  = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.4 });
const wingMat = new THREE.MeshStandardMaterial({
  color: 0xffffff, transparent: true, opacity: 0.35,
  roughness: 0.1, side: THREE.DoubleSide
});
const eyeMat  = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.2 });

/* Body (abdomen) — elongated sphere */
const body = new THREE.Mesh(new THREE.SphereGeometry(0.45, 24, 16), yellow);
body.scale.set(1, 0.85, 1.4);
body.castShadow = true;
bee.add(body);

/* Black stripes on abdomen */
for (let i = 0; i < 3; i++) {
  const stripe = new THREE.Mesh(
    new THREE.TorusGeometry(0.44 - i * 0.01, 0.06, 8, 24),
    black
  );
  stripe.rotation.x = Math.PI / 2;
  stripe.position.z = -0.15 - i * 0.22;
  stripe.scale.set(1, 0.85, 1);
  stripe.castShadow = true;
  bee.add(stripe);
}

/* Thorax (middle segment) */
const thorax = new THREE.Mesh(
  new THREE.SphereGeometry(0.38, 20, 14),
  yellow
);
thorax.position.set(0, 0, 0.55);
thorax.scale.set(1.05, 1, 0.8);
thorax.castShadow = true;
bee.add(thorax);

/* Thorax stripe */
const thStripe = new THREE.Mesh(
  new THREE.TorusGeometry(0.37, 0.05, 8, 20),
  black
);
thStripe.rotation.x = Math.PI / 2;
thStripe.position.set(0, 0, 0.55);
thStripe.scale.set(1.05, 1, 0.8);
bee.add(thStripe);

/* Head */
const head = new THREE.Mesh(
  new THREE.SphereGeometry(0.3, 20, 14),
  black
);
head.position.set(0, 0.05, 0.95);
head.castShadow = true;
bee.add(head);

/* Eyes */
[-1, 1].forEach(side => {
  const eye = new THREE.Mesh(
    new THREE.SphereGeometry(0.1, 12, 8),
    eyeMat
  );
  eye.position.set(side * 0.2, 0.15, 1.15);
  eye.scale.set(1, 1.3, 0.8);
  bee.add(eye);

  /* Eye highlight */
  const highlight = new THREE.Mesh(
    new THREE.SphereGeometry(0.03, 6, 4),
    new THREE.MeshBasicMaterial({ color: 0xffffff })
  );
  highlight.position.set(side * 0.24, 0.19, 1.22);
  bee.add(highlight);
});

/* Antennae */
[-1, 1].forEach(side => {
  const antenna = new THREE.Mesh(
    new THREE.CylinderGeometry(0.012, 0.015, 0.35, 6),
    black
  );
  antenna.position.set(side * 0.15, 0.35, 1.05);
  antenna.rotation.z = side * 0.5;
  antenna.rotation.x = -0.3;
  bee.add(antenna);

  const tip = new THREE.Mesh(
    new THREE.SphereGeometry(0.025, 6, 4),
    black
  );
  tip.position.set(side * 0.32, 0.48, 1.02);
  bee.add(tip);
});

/* Wings */
const wings = [];
[-1, 1].forEach(side => {
  const wingGroup = new THREE.Group();

  const wingShape = new THREE.SphereGeometry(0.55, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2);
  const wing = new THREE.Mesh(wingShape, wingMat);
  wing.scale.set(0.15, 1, 0.7);
  wing.rotation.y = Math.PI / 2;
  wingGroup.add(wing);

  /* Wing vein lines */
  const veinMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, transparent: true, opacity: 0.2 });
  for (let v = -1; v <= 1; v += 0.5) {
    const vein = new THREE.Mesh(
      new THREE.CylinderGeometry(0.003, 0.003, 0.8, 4),
      veinMat
    );
    vein.rotation.z = Math.PI / 2;
    vein.position.set(0, 0.01, v * 0.25);
    wingGroup.add(vein);
  }

  wingGroup.position.set(side * 0.42, 0.25, 0.5);
  wingGroup.rotation.z = side * 0.3;
  bee.add(wingGroup);
  wings.push(wingGroup);
});

/* Legs */
[-1, 1].forEach(side => {
  for (let i = 0; i < 3; i++) {
    const leg = new THREE.Mesh(
      new THREE.CylinderGeometry(0.02, 0.015, 0.45, 6),
      black
    );
    leg.position.set(side * 0.42, -0.25, 0.15 + i * 0.25);
    leg.rotation.z = side * 0.8;
    leg.rotation.x = 0.3;
    leg.castShadow = true;
    bee.add(leg);

    /* Foot */
    const foot = new THREE.Mesh(
      new THREE.SphereGeometry(0.025, 6, 4),
      black
    );
    foot.position.copy(leg.position);
    foot.y -= 0.22;
    bee.add(foot);
  }
});

/* Stinger */
const stinger = new THREE.Mesh(
  new THREE.ConeGeometry(0.06, 0.25, 8),
  black
);
stinger.rotation.x = -Math.PI / 2;
stinger.position.set(0, 0, -0.85);
bee.add(stinger);

bee.position.set(0, 3, 0);
scene.add(bee);

/* ───────────── Flower-pollen particles ───────────── */
const particleCount = 60;
const particlesGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3]     = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = Math.random() * 8 + 0.5;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
  sizes[i] = Math.random() * 3 + 1;
}
particlesGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particlesGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xffee44,
  size: 0.08,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true
});
const particles = new THREE.Points(particlesGeo, particleMat);
scene.add(particles);

/* ───────────── Animation ───────────── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const speed = 1.2;

  /* Figure-8 flight path */
  const x = Math.sin(t * speed) * 4;
  const z = Math.sin(t * speed * 2) * 2;
  const y = 3 + Math.sin(t * speed * 1.5) * 1.2;

  bee.position.set(x, y, z);

  /* Face direction of travel */
  const lookTarget = new THREE.Vector3(
    x + Math.cos(t * speed) * 4,
    y + Math.cos(t * speed * 1.5) * 1.2 * 0.5,
    z + Math.cos(t * speed * 2) * 4
  );
  bee.lookAt(lookTarget);

  /* Tilt into turns */
  bee.rotation.z += Math.sin(t * speed * 2) * 0.15;

  /* Wing flap */
  const flapAngle = Math.sin(t * 40) * 0.6;
  wings[0].rotation.z = -0.3 + flapAngle;
  wings[1].rotation.z = 0.3 - flapAngle;

  /* Subtle body bob */
  bee.position.y += Math.sin(t * 25) * 0.01;

  /* Animate particles (floating pollen) */
  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    pos[i * 3 + 1] += Math.sin(t * 0.5 + i) * 0.002;
    pos[i * 3]     += Math.cos(t * 0.3 + i * 0.5) * 0.001;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

/* ───────────── Resize ───────────── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
