controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.update();

// --- Bell profile for LatheGeometry ---
function bellProfile() {
  const pts = [];
  // Loop at top
  pts.push(new THREE.Vector2(0.02, 2.5));
  pts.push(new THREE.Vector2(0.12, 2.55));
  pts.push(new THREE.Vector2(0.18, 2.5));
  pts.push(new THREE.Vector2(0.15, 2.4));
  // Crown (top rounded cap)
  pts.push(new THREE.Vector2(0.12, 2.32));
  pts.push(new THREE.Vector2(0.18, 2.2));
  pts.push(new THREE.Vector2(0.28, 2.08));
  pts.push(new THREE.Vector2(0.35, 1.95));
  // Upper body
  pts.push(new THREE.Vector2(0.40, 1.80));
  pts.push(new THREE.Vector2(0.42, 1.65));
  pts.push(new THREE.Vector2(0.43, 1.50));
  // Waist (narrowest)
  pts.push(new THREE.Vector2(0.40, 1.30));
  pts.push(new THREE.Vector2(0.35, 1.10));
  // Bowl flare
  pts.push(new THREE.Vector2(0.33, 0.95));
  pts.push(new THREE.Vector2(0.38, 0.80));
  pts.push(new THREE.Vector2(0.50, 0.65));
  pts.push(new THREE.Vector2(0.65, 0.50));
  pts.push(new THREE.Vector2(0.80, 0.38));
  pts.push(new THREE.Vector2(0.92, 0.28));
  pts.push(new THREE.Vector2(1.00, 0.20));
  // Rim
  pts.push(new THREE.Vector2(1.06, 0.15));
  pts.push(new THREE.Vector2(1.10, 0.10));
  pts.push(new THREE.Vector2(1.12, 0.04));
  pts.push(new THREE.Vector2(1.10, 0.00));
  pts.push(new THREE.Vector2(1.08, -0.02));
  pts.push(new THREE.Vector2(0.98, -0.02));
  pts.push(new THREE.Vector2(0.95, 0.00));
  // Inner bottom
  pts.push(new THREE.Vector2(0.90, 0.06));
  pts.push(new THREE.Vector2(0.80, 0.15));
  pts.push(new THREE.Vector2(0.65, 0.28));
  pts.push(new THREE.Vector2(0.50, 0.42));
  pts.push(new THREE.Vector2(0.38, 0.58));
  pts.push(new THREE.Vector2(0.30, 0.75));
  pts.push(new THREE.Vector2(0.25, 0.90));
  pts.push(new THREE.Vector2(0.22, 1.05));
  pts.push(new THREE.Vector2(0.20, 1.20));
  // Inner waist
  pts.push(new THREE.Vector2(0.18, 1.35));
  pts.push(new THREE.Vector2(0.17, 1.50));
  pts.push(new THREE.Vector2(0.18, 1.65));
  pts.push(new THREE.Vector2(0.20, 1.80));
  pts.push(new THREE.Vector2(0.24, 1.95));
  pts.push(new THREE.Vector2(0.28, 2.08));
  pts.push(new THREE.Vector2(0.25, 2.18));
  pts.push(new THREE.Vector2(0.20, 2.28));
  pts.push(new THREE.Vector2(0.14, 2.35));
  // Close to center top
  pts.push(new THREE.Vector2(0.02, 2.40));
