const bobGeo = new THREE.SphereGeometry(0.12, 24, 24);
const bobMat = new THREE.MeshStandardMaterial({ color: 0x664422, metalness: 0.3, roughness: 0.7 });
const bob = new THREE.Mesh(bobGeo, bobMat);
bob.position.set(0, -0.2, 0);
bob.castShadow = true;
rod.add(bob);

// --- Yoke / crown support ---
const yokeMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.7, roughness: 0.3 });

const yokeBeamGeo = new THREE.BoxGeometry(0.8, 0.06, 0.06);
