const axle = new THREE.Mesh(axleGeo, yokeMat);
axle.position.set(0, 2.3, 0);
scene.add(axle);

// --- Ground ---
const groundGeo = new THREE.CircleGeometry(8, 48);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3e, roughness: 0.9 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.05;
ground.receiveShadow = true;
scene.add(ground);

// --- Lighting ---
scene.add(new THREE.AmbientLight(0x404060, 0.8));

const dirLight = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight.position.set(4, 6, 3);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 20;
dirLight.shadow.camera.left = -4;
dirLight.shadow.camera.right = 4;
dirLight.shadow.camera.top = 4;
dirLight.shadow.camera.bottom = -2;
scene.add(dirLight);

const rimLight = new THREE.PointLight(0x4488ff, 1.5, 10);
rimLight.position.set(-3, 3, -2);
scene.add(rimLight);

const warmFill = new THREE.PointLight(0xff8844, 0.8, 8);
warmFill.position.set(2, 1, 3);
scene.add(warmFill);

// --- Animate ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle sway
  bell.rotation.z = Math.sin(t * 1.2) * 0.04;
  rod.rotation.z = Math.sin(t * 1.2) * 0.04;

  // Bob swings slightly more (pendulum effect)
  bob.position.x = Math.sin(t * 2.0) * 0.06;

