            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        // Camera
        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(5, 3, 5);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Water
        const waterGeometry = new THREE.PlaneGeometry(100, 100);
        const waterMaterial = new THREE.MeshPhongMaterial({ 
            color: 0x006994, 
            transparent: true, 
            opacity: 0.8,
            shininess: 80
        });
        const water = new THREE.Mesh(waterGeometry, waterMaterial);
        water.rotation.x = -Math.PI / 2;
        water.position.y = -0.5;
        water.receiveShadow = true;
        scene.add(water);

        // Boat Group
        const boat = new THREE.Group();

        // Hull
        const hullGeometry = new THREE.BoxGeometry(1.5, 0.5, 3);
        const hullMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513 }); // SaddleBrown
        const hull = new THREE.Mesh(hullGeometry, hullMaterial);
        hull.castShadow = true;
        hull.receiveShadow = true;
        boat.add(hull);

        // Mast
        const mastGeometry = new THREE.CylinderGeometry(0.05, 0.05, 2.5, 8);
        const mastMaterial = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const mast = new THREE.Mesh(mastGeometry, mastMaterial);
        mast.position.y = 1.25;
        mast.castShadow = true;
        boat.add(mast);

        // Sail
        const sailGeometry = new THREE.BufferGeometry();
        const vertices = new Float32Array([
            0, 2.4, 0,   // Top
            0, 0.2, 0,   // Bottom center
            1.2, 0.2, 0  // Bottom right
        ]);
        sailGeometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
        sailGeometry.computeVertexNormals();
        const sailMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            side: THREE.DoubleSide 
        });
        const sail = new THREE.Mesh(sailGeometry, sailMaterial);
        sail.castShadow = true;
        boat.add(sail);

        scene.add(boat);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle bobbing motion
            const time = Date.now() * 0.001;
            boat.position.y = Math.sin(time) * 0.1;
            boat.rotation.z = Math.sin(time * 0.5) * 0.05;
            boat.rotation.x = Math.sin(time * 0.3) * 0.02;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
