    <div id="info">Suspension Bridge — drag to orbit · scroll to zoom</div>

    <!-- Import Three.js and OrbitControls from CDN -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 15, 40);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // 2. Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.maxPolarAngle = Math.PI / 2 - 0.05; // Prevent going below ground

        // 3. Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 50, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // 4. Materials
        const concreteMat = new THREE.MeshStandardMaterial({ color: 0x999999 });
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const cableMat = new THREE.LineBasicMaterial({ color: 0x222222, linewidth: 2 });
        const waterMat = new THREE.MeshStandardMaterial({ color: 0x1E90FF, transparent: true, opacity: 0.8 });

        // 5. Bridge Construction
        const bridgeGroup = new THREE.Group();
        scene.add(bridgeGroup);

        // Deck
        const deckGeo = new THREE.BoxGeometry(60, 1, 8);
        const deck = new THREE.Mesh(deckGeo, roadMat);
        deck.position.y = 10;
        deck.castShadow = true;
        deck.receiveShadow = true;
        bridgeGroup.add(deck);

        // Towers
        const towerGeo = new THREE.BoxGeometry(2, 20, 4);

        const tower1 = new THREE.Mesh(towerGeo, concreteMat);
        tower1.position.set(-15, 10, 0);
        tower1.castShadow = true;
        tower1.receiveShadow = true;
        bridgeGroup.add(tower1);

        const tower2 = new THREE.Mesh(towerGeo, concreteMat);
        tower2.position.set(15, 10, 0);
        tower2.castShadow = true;
        tower2.receiveShadow = true;
        bridgeGroup.add(tower2);

        // Main Cables (Parabolic curve approximation)
        function createCable(startX, endX, height) {
            const points = [];
            const segments = 50;
            for (let i = 0; i <= segments; i++) {
                const t = i / segments;
                const x = startX + (endX - startX) * t;
                // Simple parabola: y = a(x-h)^2 + k
                // Vertex at (0, 10), passing through towers at x=±15, y=25
                // 25 = a(15)^2 + 10 => 15 = 225a => a = 15/225 = 1/15
                const y = (1/15) * (x * x) + 10;
                points.push(new THREE.Vector3(x, y, 3)); // Right side cable
                points.push(new THREE.Vector3(x, y, -3)); // Left side cable
            }

            // Create geometry for lines
            const rightPoints = points.filter((_, i) => i % 2 === 0);
            const leftPoints = points.filter((_, i) => i % 2 !== 0);

            const rightGeo = new THREE.BufferGeometry().setFromPoints(rightPoints);
            const leftGeo = new THREE.BufferGeometry().setFromPoints(leftPoints);

            const rightLine = new THREE.Line(rightGeo, cableMat);
            const leftLine = new THREE.Line(leftGeo, cableMat);

            bridgeGroup.add(rightLine);
            bridgeGroup.add(leftLine);
        }

        createCable(-30, 30, 25);

        // Vertical Suspenders (simplified)
        for(let x = -28; x <= 28; x += 4) {
            const yTop = (1/15) * (x * x) + 10;
            const yBottom = 10.5; // Just above deck
            const height = yTop - yBottom;

            if (height > 0) {
                const suspenderGeo = new THREE.CylinderGeometry(0.05, 0.05, height);
                const suspender = new THREE.Mesh(suspenderGeo, cableMat);
                suspender.position.set(x, yBottom + height/2, 0);
                bridgeGroup.add(suspender);
            }
        }

        // 6. Environment (Water/Ground)
        const waterGeo = new THREE.PlaneGeometry(200, 200);
        const water = new THREE.Mesh(waterGeo, waterMat);
        water.rotation.x = -Math.PI / 2;
        water.position.y = -2;
        water.receiveShadow = true;
        scene.add(water);

        // 7. Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // 8. Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
