    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffaa00, 0.5);
        backLight.position.set(-5, 5, -5);
        scene.add(backLight);

        // Butterfly Construction
        const butterflyGroup = new THREE.Group();
        scene.add(butterflyGroup);

        // Materials
        const wingMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xff6600, 
            side: THREE.DoubleSide,
            roughness: 0.4,
            metalness: 0.1
        });

        const wingPatternMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x331100, 
            side: THREE.DoubleSide 
        });

        const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const antennaMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // Helper to create a wing shape
        function createWing(isLeft) {
            const wingGroup = new THREE.Group();

            // Main wing shape (using a scaled sphere for a simple organic look)
            const wingGeo = new THREE.SphereGeometry(1, 32, 32);
            const wing = new THREE.Mesh(wingGeo, wingMaterial);
            wing.scale.set(1.5, 2.5, 0.1); // Flatten and stretch
            wing.position.x = isLeft ? -1.5 : 1.5;
            wingGroup.add(wing);

            // Wing pattern (spots)
            const spotGeo = new THREE.CircleGeometry(0.4, 32);
            const spot = new THREE.Mesh(spotGeo, wingPatternMaterial);
            spot.position.set(isLeft ? -1.5 : 1.5, 0.5, 0.11);
            spot.rotation.y = isLeft ? Math.PI / 2 : -Math.PI / 2;
            wingGroup.add(spot);

            const spot2 = new THREE.Mesh(spotGeo, wingPatternMaterial);
            spot2.position.set(isLeft ? -1.5 : 1.5, -0.5, 0.11);
            spot2.rotation.y = isLeft ? Math.PI / 2 : -Math.PI / 2;
            wingGroup.add(spot2);

            return wingGroup;
        }

        const leftWing = createWing(true);
        const rightWing = createWing(false);
        butterflyGroup.add(leftWing);
        butterflyGroup.add(rightWing);

        // Body
        const bodyGeo = new THREE.CylinderGeometry(0.1, 0.1, 3, 16);
        const body = new THREE.Mesh(bodyGeo, bodyMaterial);
        body.rotation.x = Math.PI / 2;
        butterflyGroup.add(body);

        // Head
        const headGeo = new THREE.SphereGeometry(0.2, 16, 16);
        const head = new THREE.Mesh(headGeo, bodyMaterial);
        head.position.z = 1.5;
        butterflyGroup.add(head);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.5, 8);

        const antennaL = new THREE.Mesh(antennaGeo, antennaMaterial);
        antennaL.position.set(-0.2, 0, 2.2);
        antennaL.rotation.z = Math.PI / 4;
        antennaL.rotation.x = Math.PI / 6;
        butterflyGroup.add(antennaL);

        const antennaR = new THREE.Mesh(antennaGeo, antennaMaterial);
        antennaR.position.set(0.2, 0, 2.2);
        antennaR.rotation.z = -Math.PI / 4;
        antennaR.rotation.x = Math.PI / 6;
        butterflyGroup.add(antennaR);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Flapping animation
            const flapSpeed = 10;
            const flapAngle = Math.sin(time * flapSpeed) * 0.5;

            leftWing.rotation.z = flapAngle;
            rightWing.rotation.z = -flapAngle;

            // Gentle floating
            butterflyGroup.position.y = Math.sin(time * 2) * 0.5;
            butterflyGroup.rotation.y = Math.sin(time * 0.5) * 0.2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
