<body>
<div id="info">
  <strong>🎥 Camera Visualizer</strong><br>
  Drag to orbit · Scroll to zoom<br>
  Green wireframe = view frustum<br>
  Red dot = camera position
</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x111118);
scene.fog = new THREE.Fog(0x111118, 40, 80);

// ── Renderer ───────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
document.body.appendChild(renderer.domElement);

// ── Camera ─────────────────────────────────────────────
const camera = new THREE.PerspectiveCamera(
  60, innerWidth / innerHeight, 0.1, 200
);
camera.position.set(4, 3, 5);

// ── Controls ───────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;

// ── Grid + Axes ────────────────────────────────────────
scene.add(new THREE.GridHelper(40, 40, 0x333355, 0x222233));
scene.add(new THREE.AxesHelper(6));

// ── Sample objects ─────────────────────────────────────
const geo = new THREE.IcosahedronGeometry(0.5, 0);
const mat = new THREE.MeshStandardMaterial({
  color: 0x4488ff, roughness: 0.3, metalness: 0.6,
  wireframe: true
});
const shapes = [];
for (let i = 0; i < 20; i++) {
  const mesh = new THREE.Mesh(geo, mat.clone());
  mesh.material.color.setHSL(Math.random(), 0.7, 0.5);
  mesh.position.set(
    (Math.random() - 0.5) * 20,
    Math.random() * 4 + 0.5,
    (Math.random() - 0.5) * 20
  );
  mesh.scale.setScalar(0.3 + Math.random() * 0.8);
  mesh.userData.speed = 0.2 + Math.random() * 0.5;
  scene.add(mesh);
  shapes.push(mesh);
}

// ── Frustum visualizer ─────────────────────────────────
const frustumMat = new THREE.LineBasicMaterial({
  color: 0x00ff66, transparent: true, opacity: 0.55
});
const frustumEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.ConeGeometry(1, 1, 4)),
  frustumMat
);
scene.add(frustumEdges);

// Camera position dot
const dotGeo = new THREE.SphereGeometry(0.12, 8, 8);
const dotMat = new THREE.MeshBasicMaterial({ color: 0xff3333 });
const camDot = new THREE.Mesh(dotGeo, dotMat);
scene.add(camDot);

// ── Lighting ───────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x404060, 1.5));
const dir = new THREE.DirectionalLight(0xffffff, 2);
dir.position.set(5, 8, 4);
scene.add(dir);

// ── Update frustum geometry ────────────────────────────
function updateFrustum() {
  const fov = camera.fov * (Math.PI / 180);
  const aspect = camera.aspect;
  const near = camera.near;
  const far = camera.far;

  const nh = Math.tan(fov / 2) * near;
  const nw = nh * aspect;
  const fh = Math.tan(fov / 2) * far;
  const fw = fh * aspect;

  const verts = [
    // Near rect
    new THREE.Vector3(-nw, -nh, -near),
    new THREE.Vector3( nw, -nh, -near),
    new THREE.Vector3( nw,  nh, -near),
    new THREE.Vector3(-nw,  nh, -near),
    // Far rect
    new THREE.Vector3(-fw, -fh, -far),
    new THREE.Vector3( fw, -fh, -far),
    new THREE.Vector3( fw,  fh, -far),
    new THREE.Vector3(-fw,  fh, -far),
  ];

  const edges = [
    [0,1],[1,2],[2,3],[3,0],  // near
    [4,5],[5,6],[6,7],[7,4],  // far
    [0,4],[1,5],[2,6],[3,7],  // sides
  ];

  const lineVerts = [];
  for (const [a, b] of edges) {
    lineVerts.push(verts[a].x, verts[a].y, verts[a].z);
    lineVerts.push(verts[b].x, verts[b].y, verts[b].z);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position',
    new THREE.Float32BufferAttribute(lineVerts, 3));

  // Replace geometry in place
  frustumEdges.geometry.dispose();
  frustumEdges.geometry = geometry;
  frustumEdges.position.copy(camera.position);
  frustumEdges.quaternion.copy(camera.quaternion);

  camDot.position.copy(camera.position);
}

// ── Animate ────────────────────────────────────────────
function animate() {
  requestAnimationFrame(animate);
  controls.update();

  // Gentle rotation of shapes
  const t = performance.now() * 0.001;
  for (const s of shapes) {
    s.rotation.x += 0.005 * s.userData.speed;
    s.rotation.y += 0.008 * s.userData.speed;
    s.position.y += Math.sin(t * s.userData.speed) * 0.003;
  }

  updateFrustum();
  renderer.render(scene, camera);
}
animate();

// ── Resize ─────────────────────────────────────────────
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What you get

| Element | Description |
|---|---|
| **Green wireframe** | The camera's view frustum — updates live as you orbit |
| **Red sphere** | Camera's current position |
| **Colored icosahedrons** | Floating objects to give spatial context |
| **Grid + axes** | Ground plane reference and axis indicators |

**Controls:** drag to orbit, scroll to zoom, right-drag to pan. The green frustum quad always shows exactly what the camera sees and where it's pointed.

