    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 15, 30);
        camera.lookAt(0, 5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 50, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // Materials
        const stoneMat = new THREE.MeshStandardMaterial({ color: 0x808080, roughness: 0.9 });
        const darkStoneMat = new THREE.MeshStandardMaterial({ color: 0x505050, roughness: 0.9 });
        const roofMat = new THREE.MeshStandardMaterial({ color: 0x8B0000, roughness: 0.6 }); // Dark red
        const grassMat = new THREE.MeshStandardMaterial({ color: 0x228B22, roughness: 1 });

        // Castle Group
        const castle = new THREE.Group();

        // Helper to create box
        function createBox(w, h, d, x, y, z, mat) {
            const geo = new THREE.BoxGeometry(w, h, d);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Helper to create cylinder (towers)
        function createCylinder(rTop, rBottom, h, x, y, z, mat) {
            const geo = new THREE.CylinderGeometry(rTop, rBottom, h, 16);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Helper to create cone (roofs)
        function createCone(r, h, x, y, z, mat) {
            const geo = new THREE.ConeGeometry(r, h, 16);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            return mesh;
        }

        // --- Build Castle ---

        // Main Keep
        castle.add(createBox(10, 12, 10, 0, 6, 0, stoneMat));
        // Keep Roof
        castle.add(createCone(8, 6, 0, 15, 0, roofMat));

        // Towers
        const towerPositions = [
            [-12, 0, -12], [12, 0, -12], [-12, 0, 12], [12, 0, 12]
        ];

        towerPositions.forEach(pos => {
            // Tower Body
            castle.add(createCylinder(3, 3, 16, pos[0], 8, pos[2], stoneMat));
            // Tower Roof
            castle.add(createCone(4, 5, pos[0], 20.5, pos[2], roofMat));
            // Battlements (simple boxes on top)
            for(let i=0; i<8; i++) {
                const angle = (i / 8) * Math.PI * 2;
                const bx = pos[0] + Math.cos(angle) * 3;
                const bz = pos[2] + Math.sin(angle) * 3;
                castle.add(createBox(1, 2, 1, bx, 17, bz, darkStoneMat));
            }
        });

        // Walls connecting towers
        // Front Wall
        castle.add(createBox(24, 8, 2, 0, 4, 12, stoneMat));
        // Back Wall
        castle.add(createBox(24, 8, 2, 0, 4, -12, stoneMat));
        // Left Wall
        castle.add(createBox(2, 8, 24, -12, 4, 0, stoneMat));
        // Right Wall
        castle.add(createBox(2, 8, 24, 12, 4, 0, stoneMat));

        // Gate
        castle.add(createBox(6, 7, 3, 0, 3.5, 12, darkStoneMat));
        // Gate Arch (negative space simulation or just a dark box)
        castle.add(createBox(4, 5, 3.1, 0, 2.5, 12, new THREE.MeshStandardMaterial({color: 0x111111})));

        scene.add(castle);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 200);
        const ground = new THREE.Mesh(groundGeo, grassMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Slow rotation for visualization
            castle.rotation.y += 0.002;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
