```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Three.js Clock</title>
<style>body{margin:0;overflow:hidden;background:#111}</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

const scene  = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, .1, 100);
camera.position.set(0, 0, 6);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

// ── Materials ──────────────────────────────────────────
const faceMat  = new THREE.MeshStandardMaterial({ color: 0xf5f0e8, roughness: .3 });
const rimMat   = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: .8, roughness: .2 });
const handMat  = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: .5 });
const secMat   = new THREE.MeshStandardMaterial({ color: 0xcc3333 });
const tickMat  = new THREE.MeshStandardMaterial({ color: 0x333333 });

// ── Clock face ─────────────────────────────────────────
const face = new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.3, .15, 64), faceMat);
face.rotation.x = Math.PI / 2;
scene.add(face);

const rim = new THREE.Mesh(new THREE.TorusGeometry(1.3, .06, 16, 64), rimMat);
scene.add(rim);

// ── Tick marks ─────────────────────────────────────────
const tickGeo = new THREE.BoxGeometry(.04, .18, .02);
const hourTickGeo = new THREE.BoxGeometry(.06, .28, .02);
for (let i = 0; i < 12; i++) {
  const a = (i / 12) * Math.PI * 2 - Math.PI / 2;
  const tick = new THREE.Mesh(i % 3 === 0 ? hourTickGeo : tickGeo, tickMat);
  tick.position.set(Math.cos(a) * 1.18, Math.sin(a) * 1.18, .08);
  tick.rotation.z = a + Math.PI / 2;
  scene.add(tick);
}

// ── Hands ──────────────────────────────────────────────
function makeHand(w, h, mat) {
  const g = new THREE.BoxGeometry(w, h, .03);
  g.translate(0, h / 2, 0);
  const m = new THREE.Mesh(g, mat);
  m.position.z = .12;
  scene.add(m);
  return m;
}
const hourHand   = makeHand(.12, .7,  handMat);
const minuteHand = makeHand(.08, 1.0, handMat);
const secondHand = makeHand(.03, 1.2, secMat);

// ── Center cap ─────────────────────────────────────────
scene.add(new THREE.Mesh(
  new THREE.CylinderGeometry(.08, .08, .06, 32),
  rimMat
)).position.z = .14;

// ── Lights ─────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0xffffff, .6));
const dir = new THREE.DirectionalLight(0xffffff, 1.2);
dir.position.set(3, 4, 5);
scene.add(dir);

// ── Animate ────────────────────────────────────────────
(function tick() {
  requestAnimationFrame(tick);
  const d = new Date();
  const s = d.getSeconds() + d.getMilliseconds() / 1000;
  const m = d.getMinutes() + s / 60;
  const h = (d.getHours() % 12) + m / 60;

  secondHand.rotation.z = -(s / 60)  * Math.PI * 2;
  minuteHand.rotation.z = -(m / 60)  * Math.PI * 2;
  hourHand.rotation.z   = -(h / 12)  * Math.PI * 2;

  renderer.render(scene, camera);
})();

// ── Resize ─────────────────────────────────────────────
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What you get:**

- **Analog clock** with a cream-colored face and dark metallic rim
- **12 tick marks** (thicker at the 3-hour positions)
- **Three hands** — dark hour/minute, red second — that move in **real-time** (the second hand sweeps smoothly using milliseconds)
- **Subtle lighting** with ambient + directional light for a slight 3D feel
- **Responsive** — resizes with the browser window

Just save it as `index.html` and open in any modern browser.

