        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 0.5);
        pointLight.position.set(-2, 4, 2);
        scene.add(pointLight);

        // Coffee Cup Group
        const coffeeGroup = new THREE.Group();

        // Materials
        const ceramicMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 0.2, 
            metalness: 0.1 
        });
        const coffeeLiquidMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3b2f2f, 
            roughness: 0.1, 
            metalness: 0.0 
        });
        const saucerMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 0.2, 
            metalness: 0.1 
        });

        // Cup Body
        const cupGeometry = new THREE.CylinderGeometry(1, 0.8, 2, 32, 1, true);
        const cup = new THREE.Mesh(cupGeometry, ceramicMaterial);
        cup.position.y = 1;
        cup.castShadow = true;
        cup.receiveShadow = true;
        coffeeGroup.add(cup);

        // Cup Bottom
        const cupBottomGeometry = new THREE.CircleGeometry(0.8, 32);
        const cupBottom = new THREE.Mesh(cupBottomGeometry, ceramicMaterial);
        cupBottom.rotation.x = -Math.PI / 2;
        cupBottom.position.y = 0.01;
        cupBottom.receiveShadow = true;
