renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Brilliant-cut diamond profile via LatheGeometry
const points = [];
// Table (top flat)
points.push(new THREE.Vector2(0, 1.4));
points.push(new THREE.Vector2(0.3, 1.4));
points.push(new THREE.Vector2(0.55, 1.35));
// Crown
points.push(new THREE.Vector2(1.0, 0.9));
// Girdle
points.push(new THREE.Vector2(1.1, 0.8));
points.push(new THREE.Vector2(1.12, 0.75));
points.push(new THREE.Vector2(1.1, 0.7));
// Pavilion
points.push(new THREE.Vector2(0.6, 0.1));
points.push(new THREE.Vector2(0.15, -0.3));
// Culet (bottom point)
points.push(new THREE.Vector2(0.02, -0.55));
points.push(new THREE.Vector2(0, -0.58));

const diamondGeo = new THREE.LatheGeometry(points, 64);
diamondGeo.computeVertexNormals();

const diamondMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.0,
  roughness: 0.0,
  transmission: 0.95,
  thickness: 2.0,
  ior: 2.42,           // real diamond IOR
  clearcoat: 1.0,
  clearcoatRoughness: 0.0,
  envMapIntensity: 2.0,
  attenuationColor: new THREE.Color(0.95, 0.95, 1.0),
  attenuationDistance: 3,
  side: THREE.DoubleSide,
});

// Generate a simple env map for reflections
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x111122);
const envLight1 = new THREE.PointLight(0xffeedd, 100, 20);
envLight1.position.set(3, 5, 4);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0xddeeff, 60, 20);
envLight2.position.set(-4, 2, -3);
envScene.add(envLight2);
const envLight3 = new THREE.PointLight(0xffddee, 40, 20);
envLight3.position.set(0, -3, 5);
envScene.add(envLight3);
diamondMat.envMap = pmrem.fromScene(envScene, 0.04).texture;
pmrem.dispose();

const diamond = new THREE.Mesh(diamondGeo, diamondMat);
scene.add(diamond);

// Sparkle lights
const light1 = new THREE.PointLight(0xffeedd, 30, 15);
const light2 = new THREE.PointLight(0xddeeff, 20, 15);
const light3 = new THREE.PointLight(0xffddee, 15, 15);
scene.add(light1, light2, light3);

// Subtle ambient
scene.add(new THREE.AmbientLight(0x222244, 0.5));

function animate() {
