  const t = performance.now() * 0.001;

  diamond.rotation.y = t * 0.3;
  diamond.position.y = Math.sin(t * 0.5) * 0.15;

  light1.position.set(Math.cos(t) * 4, 3 + Math.sin(t) * 1, Math.sin(t) * 4);
  light2.position.set(Math.cos(t + 2) * 3, 1, Math.sin(t + 2) * 3);
  light3.position.set(Math.sin(t + 4) * 3, -1, Math.cos(t + 4) * 3);

