        // 3. Tail Stock (Tapering part)
        const tailStockGeo = new THREE.CylinderGeometry(0.6, 0.2, 1.5, 32);
        const tailStock = new THREE.Mesh(tailStockGeo, bodyMaterial);
        tailStock.rotation.z = Math.PI / 2;
        tailStock.position.set(-2.5, 0, 0);
        tailStock.castShadow = true;
        dolphin.add(tailStock);

        // 4. Tail Flukes (Fins)
        const flukeGeo = new THREE.ConeGeometry(0.8, 1.2, 32);

        const leftFluke = new THREE.Mesh(flukeGeo, bodyMaterial);
        leftFluke.rotation.z = Math.PI / 4;
        leftFluke.rotation.y = Math.PI / 2;
        leftFluke.position.set(-3.2, 0.4, 0);
        leftFluke.scale.set(1, 0.2, 1); // Flatten
        leftFluke.castShadow = true;
        dolphin.add(leftFluke);

        const rightFluke = new THREE.Mesh(flukeGeo, bodyMaterial);
        rightFluke.rotation.z = -Math.PI / 4;
        rightFluke.rotation.y = Math.PI / 2;
        rightFluke.position.set(-3.2, -0.4, 0);
        rightFluke.scale.set(1, 0.2, 1); // Flatten
        rightFluke.castShadow = true;
        dolphin.add(rightFluke);

        // 5. Dorsal Fin (Back)
        const dorsalGeo = new THREE.ConeGeometry(0.4, 1.2, 32);
        const dorsalFin = new THREE.Mesh(dorsalGeo, bodyMaterial);
        dorsalFin.rotation.z = Math.PI / 6; // Lean back slightly
        dorsalFin.position.set(0, 0.8, 0);
        dorsalFin.scale.set(1, 1, 0.2); // Flatten
        dorsalFin.castShadow = true;
        dolphin.add(dorsalFin);

        // 6. Pectoral Fins (Side arms)
        const pectoralGeo = new THREE.ConeGeometry(0.3, 1.2, 32);

        const leftPectoral = new THREE.Mesh(pectoralGeo, bodyMaterial);
        leftPectoral.rotation.z = -Math.PI / 3;
        leftPectoral.rotation.x = Math.PI / 2;
        leftPectoral.position.set(0.5, -0.5, 0.6);
        leftPectoral.scale.set(1, 0.2, 1);
        leftPectoral.castShadow = true;
        dolphin.add(leftPectoral);

        const rightPectoral = new THREE.Mesh(pectoralGeo, bodyMaterial);
        rightPectoral.rotation.z = -Math.PI / 3;
        rightPectoral.rotation.x = -Math.PI / 2;
        rightPectoral.position.set(0.5, -0.5, -0.6);
        rightPectoral.scale.set(1, 0.2, 1);
        rightPectoral.castShadow = true;
        dolphin.add(rightPectoral);

        // Add Eye
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(1.8, 0.3, 0.4);
        dolphin.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(1.8, 0.3, -0.4);
        dolphin.add(rightEye);

        scene.add(dolphin);

        // Add some bubbles for atmosphere
        const bubbles = [];
        const bubbleGeo = new THREE.SphereGeometry(0.05, 8, 8);
        const bubbleMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6 });

        for(let i=0; i<20; i++) {
            const bubble = new THREE.Mesh(bubbleGeo, bubbleMat);
            bubble.position.set(
                (Math.random() - 0.5) * 10,
                (Math.random() - 0.5) * 10,
                (Math.random() - 0.5) * 10
            );
            bubble.userData = { speed: 0.02 + Math.random() * 0.05 };
            scene.add(bubble);
            bubbles.push(bubble);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Swim motion
            dolphin.position.y = Math.sin(time * 2) * 0.5;
            dolphin.rotation.z = Math.sin(time * 1.5) * 0.1; // Bank slightly
            dolphin.rotation.x = Math.sin(time * 2) * 0.05; // Pitch slightly

            // Tail wag
            leftFluke.rotation.y = Math.PI / 2 + Math.sin(time * 10) * 0.2;
            rightFluke.rotation.y = Math.PI / 2 - Math.sin(time * 10) * 0.2;

            // Animate bubbles
            bubbles.forEach(b => {
                b.position.y += b.userData.speed;
                if(b.position.y > 5) b.position.y = -5;
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
