<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

// ── Camera ──
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 5, 10);

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 4;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI * 0.85;
controls.update();

// ── Lights ──
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 2.5);
keyLight.position.set(5, 8, 5);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 20;
keyLight.shadow.camera.left = -5;
keyLight.shadow.camera.right = 5;
keyLight.shadow.camera.top = 5;
keyLight.shadow.camera.bottom = -5;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.6);
fillLight.position.set(-4, 4, -3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff6633, 1.5, 15);
rimLight.position.set(-3, 6, -4);
scene.add(rimLight);

// ── Materials ──
const shellMat = new THREE.MeshStandardMaterial({
  color: 0x8B4513, roughness: 0.45, metalness: 0.05,
});

const headMat = new THREE.MeshStandardMaterial({
  color: 0xf5f0e8, roughness: 0.6, metalness: 0.0,
  transparent: true, opacity: 0.92,
});

const chromeMat = new THREE.MeshStandardMaterial({
  color: 0xcccccc, roughness: 0.1, metalness: 0.95,
});

const darkChromeMat = new THREE.MeshStandardMaterial({
  color: 0x888888, roughness: 0.15, metalness: 0.9,
});

const floorMat = new THREE.MeshStandardMaterial({
  color: 0x111122, roughness: 0.8, metalness: 0.2,
});

// ── Drum Group ──
const drum = new THREE.Group();
scene.add(drum);

const RADIUS = 2;
const HEIGHT = 2.4;
const HEAD_THICKNESS = 0.12;

// Shell (body)
const shellGeo = new THREE.CylinderGeometry(RADIUS, RADIUS, HEIGHT, 64);
const shell = new THREE.Mesh(shellGeo, shellMat);
shell.position.y = HEIGHT / 2;
shell.castShadow = true;
shell.receiveShadow = true;
drum.add(shell);

// Wood grain ring detail
const ringGeo = new THREE.TorusGeometry(RADIUS + 0.02, 0.04, 8, 64);
for (let i = 0; i < 3; i++) {
  const ring = new THREE.Mesh(ringGeo, new THREE.MeshStandardMaterial({
    color: 0x6B3410, roughness: 0.5, metalness: 0.0,
  }));
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 0.6 + i * 0.6;
  drum.add(ring);
}

// ── Drum Heads ──
function makeDrumHead(y, isTop) {
  const group = new THREE.Group();

  // Head surface
  const headGeo = new THREE.CylinderGeometry(RADIUS - 0.05, RADIUS - 0.05, HEAD_THICKNESS, 64);
  const head = new THREE.Mesh(headGeo, headMat);
  head.castShadow = true;
  head.receiveShadow = true;
  group.add(head);

  // Center dot (for top head)
  if (isTop) {
    const dotGeo = new THREE.CircleGeometry(0.15, 32);
    const dotMat = new THREE.MeshStandardMaterial({
      color: 0x333333, roughness: 0.5, metalness: 0.1,
    });
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.rotation.x = -Math.PI / 2;
    dot.position.y = HEAD_THICKNESS / 2 + 0.001;
    group.add(dot);
  }

  // Chrome rim
  const rimGeo = new THREE.TorusGeometry(RADIUS - 0.05, 0.08, 12, 64);
  const rim = new THREE.Mesh(rimGeo, chromeMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = HEAD_THICKNESS / 2 + 0.01;
  rim.castShadow = true;
  group.add(rim);

  // Outer rim lip
  const outerRimGeo = new THREE.TorusGeometry(RADIUS + 0.05, 0.04, 8, 64);
  const outerRim = new THREE.Mesh(outerRimGeo, chromeMat);
  outerRim.rotation.x = Math.PI / 2;
  outerRim.position.y = HEAD_THICKNESS / 2 + 0.01;
  group.add(outerRim);

  group.position.y = y;
  return { group, head };
}

const topHead = makeDrumHead(HEIGHT, true);
const bottomHead = makeDrumHead(0, false);
drum.add(topHead.group);
drum.add(bottomHead.group);

// ── Tension Rods & Lugs ──
const ROD_COUNT = 12;
for (let i = 0; i < ROD_COUNT; i++) {
  const angle = (i / ROD_COUNT) * Math.PI * 2;

  // Lug (on shell)
  const lugGeo = new THREE.BoxGeometry(0.18, 0.3, 0.15);
  const lug = new THREE.Mesh(lugGeo, darkChromeMat);
  lug.position.set(
    Math.cos(angle) * RADIUS,
    HEIGHT - 0.15,
    Math.sin(angle) * RADIUS
  );
  lug.lookAt(0, HEIGHT - 0.15, 0);
  lug.castShadow = true;
  drum.add(lug);

  // Tension rod (screw)
  const rodGeo = new THREE.CylinderGeometry(0.035, 0.035, 0.5, 8);
  const rod = new THREE.Mesh(rodGeo, chromeMat);
  rod.position.set(
    Math.cos(angle) * (RADIUS + 0.06),
    HEIGHT + 0.15,
    Math.sin(angle) * (RADIUS + 0.06)
  );
  rod.castShadow = true;
  drum.add(rod);

  // Rod tip (knob)
  const tipGeo = new THREE.SphereGeometry(0.055, 8, 8);
  const tip = new THREE.Mesh(tipGeo, chromeMat);
  tip.position.set(
    Math.cos(angle) * (RADIUS + 0.06),
    HEIGHT + 0.42,
    Math.sin(angle) * (RADIUS + 0.06)
  );
  drum.add(tip);
}

// ── Drum Pedestal / Stand ──
const standMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.3, metalness: 0.8 });

// Base plate
const baseGeo = new THREE.CylinderGeometry(1.5, 1.6, 0.15, 32);
const base = new THREE.Mesh(baseGeo, standMat);
base.position.y = -0.075;
base.receiveShadow = true;
drum.add(base);

// Spoke legs
for (let i = 0; i < 3; i++) {
  const angle = (i / 3) * Math.PI * 2 + Math.PI / 6;
  const legGroup = new THREE.Group();

  const legGeo = new THREE.CylinderGeometry(0.06, 0.06, 0.8, 8);
  const leg = new THREE.Mesh(legGeo, standMat);
  leg.position.y = -0.4;
  legGroup.add(leg);

  const footGeo = new THREE.SphereGeometry(0.1, 8, 8);
  const foot = new THREE.Mesh(footGeo, new THREE.MeshStandardMaterial({
    color: 0x222222, roughness: 0.9, metalness: 0.1,
  }));
  foot.position.y = -0.8;
  foot.scale.y = 0.5;
  legGroup.add(foot);

  legGroup.position.set(
    Math.cos(angle) * 1.2,
    -0.075,
    Math.sin(angle) * 1.2
  );
  legGroup.lookAt(0, -0.075, 0);
  legGroup.rotateX(Math.PI / 2);
  drum.add(legGroup);
}

// ── Floor ──
const floorGeo = new THREE.CircleGeometry(15, 64);
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// ── Hit Animation ──
let hitTime = 0;
const hitDuration = 0.3;
const topHeadOriginalY = topHead.head.position.y;

function hitDrum() {
  hitTime = 0;
  const flash = document.getElementById('hit-flash');
  flash.style.opacity = '0.08';
  setTimeout(() => flash.style.opacity = '0', 60);

  // Play a synthetic drum sound
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.6, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.4);

    // Add noise burst
    const bufferSize = ctx.sampleRate * 0.1;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.3;
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.4, ctx.currentTime);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
    noise.connect(noiseGain);
    noiseGain.connect(ctx.destination);
    noise.start();
  } catch (e) {}
}

// Raycaster for click detection
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

renderer.domElement.addEventListener('click', (e) => {
  mouse.x = (e.clientX / innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const intersects = raycaster.intersectObjects(drum.children, true);
  if (intersects.length > 0) hitDrum();
});

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ── Animate ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();

  // Gentle idle bob
  drum.position.y = Math.sin(clock.elapsedTime * 0.5) * 0.02;

  // Hit animation
  if (hitTime < hitDuration) {
    hitTime += dt;
    const t = hitTime / hitDuration;
    const bounce = Math.sin(t * Math.PI * 3) * (1 - t) * 0.15;
    topHead.head.position.y = bounce;
    topHead.head.scale.set(1 + bounce * 2, 1, 1 + bounce * 2);
  } else {
    topHead.head.position.y = topHeadOriginalY;
    topHead.head.scale.set(1, 1, 1);
  }

  controls.update();
  renderer.render(scene, camera);
}

animate();
</script>
