        head.castShadow = true;
        elephantGroup.add(head);

        // Trunk
        const trunkGeo = new THREE.CylinderGeometry(0.2, 0.1, 2, 12);
        const trunk = new THREE.Mesh(trunkGeo, material);
        trunk.position.set(0, 1.5, 2.8);
        trunk.rotation.x = -Math.PI / 4;
        trunk.castShadow = true;
        elephantGroup.add(trunk);

        // Ears
        const earGeo = new THREE.ConeGeometry(0.8, 1.5, 3);

        const leftEar = new THREE.Mesh(earGeo, material);
        leftEar.position.set(-0.9, 3, 2);
        leftEar.rotation.z = Math.PI / 2;
        leftEar.rotation.y = -Math.PI / 4;
        leftEar.castShadow = true;
        elephantGroup.add(leftEar);

        const rightEar = new THREE.Mesh(earGeo, material);
        rightEar.position.set(0.9, 3, 2);
        rightEar.rotation.z = -Math.PI / 2;
        rightEar.rotation.y = Math.PI / 4;
        rightEar.castShadow = true;
        elephantGroup.add(rightEar);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.3, 0.3, 2, 12);
        const legPositions = [
            { x: -0.7, z: 1 },
            { x: 0.7, z: 1 },
            { x: -0.7, z: -1 },
            { x: 0.7, z: -1 }
        ];

        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, material);
            leg.position.set(pos.x, 1, pos.z);
            leg.castShadow = true;
            elephantGroup.add(leg);
        });

        // Tail
        const tailGeo = new THREE.CylinderGeometry(0.05, 0.02, 1, 8);
        const tail = new THREE.Mesh(tailGeo, material);
        tail.position.set(0, 2.5, -1.8);
        tail.rotation.x = Math.PI / 4;
        elephantGroup.add(tail);

        // Tusks
        const tuskGeo = new THREE.ConeGeometry(0.1, 0.8, 8);

        const leftTusk = new THREE.Mesh(tuskGeo, whiteMaterial);
        leftTusk.position.set(-0.4, 2, 2.8);
        leftTusk.rotation.x = Math.PI / 2;
        leftTusk.rotation.z = -Math.PI / 6;
        elephantGroup.add(leftTusk);

        const rightTusk = new THREE.Mesh(tuskGeo, whiteMaterial);
        rightTusk.position.set(0.4, 2, 2.8);
        rightTusk.rotation.x = Math.PI / 2;
        rightTusk.rotation.z = Math.PI / 6;
        elephantGroup.add(rightTusk);

        scene.add(elephantGroup);

        // Ground Plane
        const planeGeo = new THREE.PlaneGeometry(50, 50);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x16213e });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // 7. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle idle animation
            const time = Date.now() * 0.001;
            elephantGroup.position.y = Math.sin(time) * 0.1;
            elephantGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
