    <div id="info">🔧 V8 Engine — Drag to orbit · Scroll to zoom</div>

    <!-- Import Three.js as an ES module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        // Camera
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(5, 4, 6);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 0.5);
        pointLight.position.set(-2, 3, 2);
        scene.add(pointLight);

        // Materials
        const blockMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.4, metalness: 0.6 });
        const headMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.3, metalness: 0.7 });
        const pistonMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.2, metalness: 0.8 });
        const crankMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.5, metalness: 0.9 });
        const manifoldMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.7 });

        // Engine Group
        const engineGroup = new THREE.Group();
        scene.add(engineGroup);

        // Main Engine Block
        const blockGeo = new THREE.BoxGeometry(2, 1.5, 2.5);
        const block = new THREE.Mesh(blockGeo, blockMat);
        block.castShadow = true;
        block.receiveShadow = true;
        engineGroup.add(block);

        // Crankshaft
        const crankGeo = new THREE.CylinderGeometry(0.2, 0.2, 2.6, 16);
        const crankshaft = new THREE.Mesh(crankGeo, crankMat);
        crankshaft.rotation.z = Math.PI / 2;
        crankshaft.position.y = -0.5;
        crankshaft.castShadow = true;
        engineGroup.add(crankshaft);

        // Cylinder Banks (V8 configuration)
        const bankAngle = Math.PI / 6; // 30 degrees
        const bankWidth = 0.8;
        const bankLength = 2.2;
        const bankHeight = 1.2;

        function createBank(side) {
            const bankGroup = new THREE.Group();

            // Cylinder Head
            const headGeo = new THREE.BoxGeometry(bankWidth, bankHeight, bankLength);
            const head = new THREE.Mesh(headGeo, headMat);
            head.castShadow = true;
            head.receiveShadow = true;
            bankGroup.add(head);

            // Pistons (simplified)
            for(let i=0; i<4; i++) {
                const pistonGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.8, 16);
                const piston = new THREE.Mesh(pistonGeo, pistonMat);
                piston.position.set(0, 0.2, -0.8 + i * 0.55);
                piston.castShadow = true;
                bankGroup.add(piston);
            }

            // Intake Manifold runners
            for(let i=0; i<4; i++) {
                const runnerGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.6, 8);
                const runner = new THREE.Mesh(runnerGeo, manifoldMat);
                runner.position.set(side * 0.4, 0.6, -0.8 + i * 0.55);
                runner.rotation.x = side * 0.5;
                bankGroup.add(runner);
            }

            // Position and Rotate Bank
            bankGroup.position.set(side * 0.6, 0.5, 0);
            bankGroup.rotation.z = side * bankAngle;

            return bankGroup;
        }

        const leftBank = createBank(-1);
        const rightBank = createBank(1);
        engineGroup.add(leftBank);
        engineGroup.add(rightBank);

        // Oil Pan
        const panGeo = new THREE.BoxGeometry(1.8, 0.4, 2.3);
        const pan = new THREE.Mesh(panGeo, new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 }));
        pan.position.y = -1.0;
        pan.castShadow = true;
        engineGroup.add(pan);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate crankshaft
            crankshaft.rotation.x = time * 5;

            // Simple piston animation (visual only)
            const pistonOffset = Math.sin(time * 5) * 0.1;

            // Update pistons in left bank
            leftBank.children.forEach((child, index) => {
                if (child.geometry.type === 'CylinderGeometry' && child.material === pistonMat) {
                    child.position.y = 0.2 + pistonOffset;
                }
            });

            // Update pistons in right bank (offset phase)
            rightBank.children.forEach((child, index) => {
                if (child.geometry.type === 'CylinderGeometry' && child.material === pistonMat) {
                    child.position.y = 0.2 - pistonOffset;
                }
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
