    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.z = 6;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const mainLight = new THREE.DirectionalLight(0xffffff, 1.5);
        mainLight.position.set(5, 5, 5);
        mainLight.castShadow = true;
        mainLight.shadow.mapSize.width = 1024;
        mainLight.shadow.mapSize.height = 1024;
        scene.add(mainLight);

        const rimLight = new THREE.PointLight(0x4444ff, 0.5);
        rimLight.position.set(-5, 2, 2);
        scene.add(rimLight);

        // Eye Group
        const eyeGroup = new THREE.Group();
        scene.add(eyeGroup);

        // Sclera (The white part of the eye)
        const scleraGeometry = new THREE.SphereGeometry(2, 64, 64);
        const scleraMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xeeeeee, 
            roughness: 0.4,
            metalness: 0.0
        });
        const sclera = new THREE.Mesh(scleraGeometry, scleraMaterial);
        sclera.castShadow = true;
        sclera.receiveShadow = true;
        eyeGroup.add(sclera);

        // Iris Group (Moves with gaze)
        const irisGroup = new THREE.Group();
        // Position slightly in front of the sphere surface
        irisGroup.position.z = 1.95; 
        eyeGroup.add(irisGroup);

        // Iris (The colored part)
        const irisGeometry = new THREE.CircleGeometry(1.1, 64);
        const irisMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x0055aa, 
            roughness: 0.2,
            metalness: 0.1
        });
        const iris = new THREE.Mesh(irisGeometry, irisMaterial);
        irisGroup.add(iris);

        // Pupil
        const pupilGeometry = new THREE.CircleGeometry(0.4, 32);
        const pupilMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x000000, 
            roughness: 0.1 
        });
        const pupil = new THREE.Mesh(pupilGeometry, pupilMaterial);
        pupil.position.z = 0.01; // Slightly in front of iris
        irisGroup.add(pupil);

        // Specular Highlight (The white reflection)
        const highlightGeometry = new THREE.SphereGeometry(0.2, 16, 16);
        const highlightMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const highlight = new THREE.Mesh(highlightGeometry, highlightMaterial);
        highlight.position.set(0.4, 0.4, 0.1);
        irisGroup.add(highlight);

        // Mouse Interaction
        const mouse = new THREE.Vector2();
        const target = new THREE.Vector2();
        const windowHalfX = window.innerWidth / 2;
        const windowHalfY = window.innerHeight / 2;

        document.addEventListener('mousemove', (event) => {
            mouse.x = (event.clientX - windowHalfX) / windowHalfX;
            mouse.y = (event.clientY - windowHalfY) / windowHalfY;
        });

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Smoothly interpolate iris position towards mouse
            // Limit the movement range so the iris stays inside the sclera
            const maxMove = 0.8;
            target.x = Math.max(-1, Math.min(1, mouse.x)) * maxMove;
            target.y = Math.max(-1, Math.min(1, mouse.y)) * maxMove;

            irisGroup.position.x += (target.x - irisGroup.position.x) * 0.1;
            irisGroup.position.y += (target.y - irisGroup.position.y) * 0.1;

            // Slight rotation of the whole eye to follow gaze (optional, adds realism)
            eyeGroup.rotation.y = mouse.x * 0.1;
            eyeGroup.rotation.x = -mouse.y * 0.1;

            renderer.render(scene, camera);
        }

        animate();

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
