<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0, 0);

// --- Lighting ---
const ambient = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambient);

const sun = new THREE.DirectionalLight(0xfff4e6, 2.5);
sun.position.set(5, 10, 7);
sun.castShadow = true;
scene.add(sun);

const rim = new THREE.DirectionalLight(0x8ec5fc, 1.2);
rim.position.set(-5, 3, -5);
scene.add(rim);

// --- Flag texture (French tricolor via canvas) ---
function createFlagTexture() {
  const c = document.createElement('canvas');
  c.width = 900;
  c.height = 600;
  const ctx = c.getContext('2d');

  // Blue
  ctx.fillStyle = '#002395';
  ctx.fillRect(0, 0, 300, 600);
  // White
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(300, 0, 300, 600);
  // Red
  ctx.fillStyle = '#ED2939';
  ctx.fillRect(600, 0, 300, 600);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// --- Flag geometry & material ---
const segmentsX = 80;
const segmentsY = 40;
const width = 9;
const height = 6;

const geometry = new THREE.PlaneGeometry(width, height, segmentsX, segmentsY);
const material = new THREE.MeshStandardMaterial({
  map: createFlagTexture(),
  side: THREE.DoubleSide,
  roughness: 0.8,
  metalness: 0.0,
});

const flag = new THREE.Mesh(geometry, material);
flag.castShadow = true;
scene.add(flag);

// --- Pole ---
const poleGeo = new THREE.CylinderGeometry(0.08, 0.08, height + 2, 16);
const poleMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.3, metalness: 0.8 });
const pole = new THREE.Mesh(poleGeo, poleMat);
pole.position.set(-width / 2 - 0.1, 0, 0);
pole.castShadow = true;
scene.add(pole);

// Finial (ball on top)
const ballGeo = new THREE.SphereGeometry(0.15, 16, 16);
const ball = new THREE.Mesh(ballGeo, poleMat);
ball.position.set(-width / 2 - 0.1, height / 2 + 1.1, 0);
scene.add(ball);

// --- Waving animation ---
const originalPositions = geometry.attributes.position.array.slice();

function wave(time) {
  const pos = geometry.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const ox = originalPositions[i * 3];
    const oy = originalPositions[i * 3 + 1];

    // Distance from pole (left edge)
    const dist = (ox + width / 2) / width;

    // Multiple sine waves for natural flutter
    const z = Math.sin(ox * 1.8 + time * 3.0) * 0.35 * dist
            + Math.sin(ox * 3.2 + time * 5.0) * 0.12 * dist
            + Math.cos(oy * 2.0 + time * 2.0) * 0.08 * dist;

    pos.setZ(i, z);
  }
  pos.needsUpdate = true;
  geometry.computeVertexNormals();
}

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// --- Render loop ---
const clock = new THREE.Clock();

(function animate() {
  requestAnimationFrame(animate);
  wave(clock.getElapsedTime());
  controls.update();
  renderer.render(scene, camera);
})();
</script>
</body>
</html>
```

## What this does

| Feature | Detail |
|---|---|
| **Flag design** | French tricolor (blue 🟦 white ⬜ red 🟥) drawn on a `<canvas>` and used as a texture — no external images needed |
| **Waving animation** | Vertex displacement using layered sine waves, pinned at the pole edge and fluttering freely at the trailing edge |
| **Pole + finial** | Metallic cylinder with a sphere on top for realism |
| **Lighting** | Warm directional "sun", cool rim light, and ambient fill with soft shadows |
| **Interactivity** | `OrbitControls` — drag to rotate, scroll to zoom |
| **Responsive** | Handles window resizing automatically |

Open the file in any modern browser and you'll see a French flag rippling in the wind. Swap the canvas drawing code to render any flag design you like.

