        foxGroup.add(tailTip);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.6, 8);

        const legFL = new THREE.Mesh(legGeo, darkMat);
        legFL.position.set(0.4, 0.3, 0.2);
        foxGroup.add(legFL);

        const legFR = new THREE.Mesh(legGeo, darkMat);
        legFR.position.set(0.4, 0.3, -0.2);
        foxGroup.add(legFR);

        const legBL = new THREE.Mesh(legGeo, darkMat);
        legBL.position.set(-0.4, 0.3, 0.2);
        foxGroup.add(legBL);

        const legBR = new THREE.Mesh(legGeo, darkMat);
        legBR.position.set(-0.4, 0.3, -0.2);
        foxGroup.add(legBR);

        // Chest fluff
        const chestGeo = new THREE.SphereGeometry(0.35, 16, 16);
        const chest = new THREE.Mesh(chestGeo, whiteMat);
        chest.position.set(0.6, 0.6, 0);
        chest.scale.set(1, 1.2, 0.8);
        foxGroup.add(chest);

        scene.add(foxGroup);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(20, 20);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x16213e });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Animation
        function animate() {
            requestAnimationFrame(animate);
            foxGroup.rotation.y += 0.01;
            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
