<body>
    <div id="instructions">🐸 Click & drag to orbit · Scroll to zoom</div>
    <div id="ui-container">
        <button id="btn-blink">👁️ Blink</button>
        <button id="btn-jump">🦘 Jump</button>
        <button id="btn-tongue">👅 Tongue</button>
    </div>

    <!-- Import Three.js as a module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.maxPolarAngle = Math.PI / 2 - 0.1; // Prevent going below ground

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(100, 100);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x2d3436 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Frog Construction
        const frogGroup = new THREE.Group();
        scene.add(frogGroup);

        const frogMaterial = new THREE.MeshStandardMaterial({ color: 0x4caf50, roughness: 0.8 });
        const bellyMaterial = new THREE.MeshStandardMaterial({ color: 0xc8e6c9, roughness: 0.8 });
        const eyeWhiteMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const pupilMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const tongueMaterial = new THREE.MeshStandardMaterial({ color: 0xff6b6b });

        // Body
        const bodyGeo = new THREE.SphereGeometry(1.5, 32, 32);
        const body = new THREE.Mesh(bodyGeo, frogMaterial);
        body.scale.set(1, 0.8, 1.2);
        body.position.y = 1.2;
        body.castShadow = true;
        frogGroup.add(body);

        // Belly
        const bellyGeo = new THREE.SphereGeometry(1.2, 32, 32);
        const belly = new THREE.Mesh(bellyGeo, bellyMaterial);
        belly.scale.set(1, 0.6, 1.1);
        belly.position.set(0, 0.8, 0.2);
        frogGroup.add(belly);

        // Head
        const headGeo = new THREE.SphereGeometry(1.1, 32, 32);
        const head = new THREE.Mesh(headGeo, frogMaterial);
        head.position.set(0, 1.8, 1.2);
        head.castShadow = true;
        frogGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.4, 32, 32);
        const pupilGeo = new THREE.SphereGeometry(0.15, 16, 16);

        const leftEyeGroup = new THREE.Group();
        leftEyeGroup.position.set(-0.6, 2.4, 1.2);
        const leftEyeWhite = new THREE.Mesh(eyeGeo, eyeWhiteMaterial);
        const leftPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        leftPupil.position.z = 0.3;
        leftEyeGroup.add(leftEyeWhite);
        leftEyeGroup.add(leftPupil);
        frogGroup.add(leftEyeGroup);

        const rightEyeGroup = new THREE.Group();
        rightEyeGroup.position.set(0.6, 2.4, 1.2);
        const rightEyeWhite = new THREE.Mesh(eyeGeo, eyeWhiteMaterial);
        const rightPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        rightPupil.position.z = 0.3;
        rightEyeGroup.add(rightEyeWhite);
        rightEyeGroup.add(rightPupil);
        frogGroup.add(rightEyeGroup);

        // Legs
        function createLeg(x, y, z, rotZ, rotX, isBack) {
            const legGroup = new THREE.Group();
            const upperLegGeo = new THREE.CapsuleGeometry(0.3, 0.8, 4, 8);
            const lowerLegGeo = new THREE.CapsuleGeometry(0.25, 0.6, 4, 8);

            const upperLeg = new THREE.Mesh(upperLegGeo, frogMaterial);
            const lowerLeg = new THREE.Mesh(lowerLegGeo, frogMaterial);

            if (isBack) {
                upperLeg.position.set(0, 0.4, 0);
                lowerLeg.position.set(0, -0.4, 0.2);
                lowerLeg.rotation.x = -0.5;
            } else {
                upperLeg.position.set(0, 0.3, 0);
                lowerLeg.position.set(0, -0.3, 0.1);
                lowerLeg.rotation.x = -0.2;
            }

            legGroup.add(upperLeg);
            legGroup.add(lowerLeg);

            legGroup.position.set(x, y, z);
            legGroup.rotation.z = rotZ;
            legGroup.rotation.x = rotX;
            legGroup.castShadow = true;

            return legGroup;
        }

        const backLeftLeg = createLeg(-1.2, 0.8, -0.5, 0.5, 0.2, true);
        const backRightLeg = createLeg(1.2, 0.8, -0.5, -0.5, 0.2, true);
        const frontLeftLeg = createLeg(-0.8, 0.5, 1.5, 0.2, 0.5, false);
        const frontRightLeg = createLeg(0.8, 0.5, 1.5, -0.2, 0.5, false);

        frogGroup.add(backLeftLeg);
        frogGroup.add(backRightLeg);
        frogGroup.add(frontLeftLeg);
        frogGroup.add(frontRightLeg);

        // Tongue
        const tongueGeo = new THREE.CylinderGeometry(0.05, 0.05, 1, 8);
        const tongue = new THREE.Mesh(tongueGeo, tongueMaterial);
        tongue.rotation.x = Math.PI / 2;
        tongue.position.set(0, 1.8, 2.5); // Start hidden inside mouth area
        tongue.scale.z = 0; // Retracted
        frogGroup.add(tongue);

        // Animation State
        let isJumping = false;
        let jumpTime = 0;
        let isBlinking = false;
        let blinkTime = 0;
        let isTongueOut = false;
        let tongueTargetScale = 0;

        // UI Event Listeners
        document.getElementById('btn-blink').addEventListener('click', () => {
            if (!isBlinking) {
                isBlinking = true;
                blinkTime = 0;
            }
        });

        document.getElementById('btn-jump').addEventListener('click', () => {
            if (!isJumping) {
                isJumping = true;
                jumpTime = 0;
            }
        });

        document.getElementById('btn-tongue').addEventListener('click', () => {
            isTongueOut = !isTongueOut;
            tongueTargetScale = isTongueOut ? 3 : 0;
        });

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            // Idle breathing animation
            if (!isJumping) {
                frogGroup.position.y = Math.sin(time * 2) * 0.05;
                body.scale.y = 0.8 + Math.sin(time * 2) * 0.02;
            }

            // Jump Animation
            if (isJumping) {
                jumpTime += delta * 3;
                // Parabolic arc
                const jumpHeight = Math.sin(jumpTime * Math.PI) * 3;
                frogGroup.position.y = jumpHeight;

                // Rotate slightly during jump
                frogGroup.rotation.x = -jumpTime * 0.5;

                if (jumpTime >= 1) {
                    isJumping = false;
                    frogGroup.position.y = 0;
                    frogGroup.rotation.x = 0;
                }
            }

            // Blink Animation
            if (isBlinking) {
                blinkTime += delta * 10;
                const scaleY = Math.abs(Math.sin(blinkTime * Math.PI));
                leftEyeGroup.scale.y = scaleY;
                rightEyeGroup.scale.y = scaleY;

                if (blinkTime >= 1) {
                    isBlinking = false;
                    leftEyeGroup.scale.y = 1;
                    rightEyeGroup.scale.y = 1;
                }
            }

            // Tongue Animation
            tongue.scale.z += (tongueTargetScale - tongue.scale.z) * 0.1;
            tongue.position.z = 1.8 + (tongue.scale.z * 0.5);

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
