<body>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js" } }
</script>
<script type="module">
import * as THREE from 'three';

// — Scene, camera, renderer —
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.035);

const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.appendChild(renderer.domElement);

// — Lights —
scene.add(new THREE.AmbientLight(0x334466, 1.5));
const dirLight = new THREE.DirectionalLight(0xffffff, 2);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);
const rimLight = new THREE.PointLight(0x6688ff, 3, 15);
rimLight.position.set(-3, 2, -2);
scene.add(rimLight);

// — Ghost body via LatheGeometry (profile → revolve) —
const profile = [];
const steps = 20;
for (let i = 0; i <= steps; i++) {
  const t = i / steps;
  const r = Math.sin(t * Math.PI) * (1.0 + 0.3 * Math.sin(t * Math.PI * 3));
  profile.push(new THREE.Vector2(r, t * 2.5 - 1.25));
}
const ghostGeo = new THREE.LatheGeometry(profile, 32);
const ghostMat = new THREE.MeshStandardMaterial({
  color: 0xeeeeff,
  transparent: true,
  opacity: 0.85,
  roughness: 0.3,
  metalness: 0.0,
  side: THREE.DoubleSide,
});
const ghost = new THREE.Mesh(ghostGeo, ghostMat);
scene.add(ghost);

// — Eyes —
const eyeGeo = new THREE.SphereGeometry(0.1, 16, 16);
const eyeMat = new THREE.MeshBasicMaterial({ color: 0x111122 });
const leftEye  = new THREE.Mesh(eyeGeo, eyeMat);
const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
leftEye.position.set(-0.25, 0.35, 0.78);
rightEye.position.set( 0.25, 0.35, 0.78);
ghost.add(leftEye);
ghost.add(rightEye);

// — Glowing pupils —
const pupilGeo = new THREE.SphereGeometry(0.04, 8, 8);
const pupilMat = new THREE.MeshBasicMaterial({ color: 0x88aaff });
[leftEye, rightEye].forEach(eye => {
  const pupil = new THREE.Mesh(pupilGeo, pupilMat);
  pupil.position.z = 0.08;
  eye.add(pupil);
});

// — Floating particles —
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3]     = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 14;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0x8899cc,
  size: 0.05,
  transparent: true,
  opacity: 0.6,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// — Animation —
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Float
  ghost.position.y = Math.sin(t * 1.2) * 0.4;
  ghost.rotation.y = Math.sin(t * 0.5) * 0.15;

  // Wobble vertices for a breathing effect
  const pos = ghostGeo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const z = pos.getZ(i);
    const wave = Math.sin(y * 3 + t * 2) * 0.03 * Math.max(0, -y);
    pos.setXYZ(i, x + wave, y, z);
  }
  pos.needsUpdate = true;
  ghostGeo.computeVertexNormals();

  // Particles drift
  particles.rotation.y = t * 0.02;

  renderer.render(scene, camera);
}
animate();

// — Resize —
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What you get

| Feature | Detail |
|---|---|
| **Ghost body** | `LatheGeometry` from a hand-crafted profile curve, giving a smooth, bulbous ghost shape |
| **Material** | Semi-transparent white (`opacity: 0.85`) with `MeshStandardMaterial` for soft lighting |
| **Eyes** | Two dark spheres with small blue-glowing pupils |
| **Breathing animation** | Bottom vertices undulate sinusoidally each frame |
| **Floating** | Smooth sine-wave vertical bob + gentle yaw rotation |
| **Atmosphere** | Dark fog, ambient + directional + blue rim light, 200 drifting particles |
| **Responsive** | Handles window resize automatically |

Open the file in any browser — no build step needed.

