renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.8, 0);
controls.update();

// ——— Lighting ———
scene.add(new THREE.AmbientLight(0x404060, 0.8));

const dirLight = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight.position.set(4, 6, 3);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 15;
dirLight.shadow.camera.left = -4;
dirLight.shadow.camera.right = 4;
dirLight.shadow.camera.top = 4;
dirLight.shadow.camera.bottom = -4;
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.6);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

// ——— Ground ———
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 20),
  new THREE.MeshStandardMaterial({ color: 0x16213e, roughness: 0.85, metalness: 0.1 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ——— Materials ———
const woodMat = new THREE.MeshStandardMaterial({
  color: 0x8B5E3C, roughness: 0.7, metalness: 0.05
});
const darkWoodMat = new THREE.MeshStandardMaterial({
  color: 0x6B3F1F, roughness: 0.75, metalness: 0.05
});
const metalMat = new THREE.MeshStandardMaterial({
  color: 0xaaaaaa, roughness: 0.25, metalness: 0.9
});
const darkMetalMat = new THREE.MeshStandardMaterial({
  color: 0x777777, roughness: 0.35, metalness: 0.85
});

// ——— Hammer Group ———
const hammer = new THREE.Group();

// Handle
const handle = new THREE.Mesh(
  new THREE.CylinderGeometry(0.055, 0.065, 1.6, 12),
  woodMat
);
handle.position.y = 0.8;
handle.castShadow = true;
hammer.add(handle);

// Handle grip (textured rings)
for (let i = 0; i < 8; i++) {
  const ring = new THREE.Mesh(
    new THREE.CylinderGeometry(0.068, 0.068, 0.015, 12),
    darkWoodMat
  );
  ring.position.y = 0.2 + i * 0.07;
  ring.castShadow = true;
  hammer.add(ring);
}

// Handle cap (bottom)
const cap = new THREE.Mesh(
  new THREE.SphereGeometry(0.065, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2),
  darkMetalMat
);
cap.position.y = 0.0;
cap.rotation.x = Math.PI;
cap.castShadow = true;
hammer.add(cap);

// Head body
const head = new THREE.Mesh(
  new THREE.BoxGeometry(0.5, 0.12, 0.3),
  metalMat
);
head.position.y = 1.62;
head.castShadow = true;
hammer.add(head);

// Striking face (front, slightly rounded)
const face = new THREE.Mesh(
  new THREE.CylinderGeometry(0.14, 0.14, 0.04, 16),
  darkMetalMat
);
face.rotation.z = Math.PI / 2;
face.position.set(0.27, 1.62, 0);
face.castShadow = true;
hammer.add(face);

// Claw (curved back) — built from a torus segment
const clawGeo = new THREE.TorusGeometry(0.18, 0.04, 8, 16, Math.PI);
const claw = new THREE.Mesh(clawGeo, metalMat);
claw.position.set(-0.1, 1.62, 0);
claw.rotation.y = Math.PI / 2;
claw.castShadow = true;
hammer.add(claw);

// Claw tips (pointy ends)
for (const side of [-1, 1]) {
  const tip = new THREE.Mesh(
    new THREE.ConeGeometry(0.035, 0.1, 8),
    darkMetalMat
  );
  tip.position.set(-0.28, 1.62, side * 0.15);
  tip.rotation.z = Math.PI / 2;
  tip.castShadow = true;
