}

// Tilt the hammer for a nice display pose
hammer.rotation.z = -0.15;
hammer.rotation.x = 0.1;
scene.add(hammer);

// ——— Animation ———
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating / breathing
  hammer.position.y = Math.sin(t * 0.8) * 0.05;
  hammer.rotation.y = Math.sin(t * 0.5) * 0.15;

