```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Three.js Heart</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { overflow: hidden; background: #000; }
    canvas { display: block; }
  </style>
</head>
<body>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
  <script>
    // ── Scene Setup ──────────────────────────────────────
    const scene    = new THREE.Scene();
    scene.fog      = new THREE.FogExp2(0x0a0a1a, 0.012);

    const camera   = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 1000);
    camera.position.z = 30;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // ── Heart Shape ──────────────────────────────────────
    function createHeartShape() {
      const s = new THREE.Shape();
      s.moveTo(0, 0);
      s.bezierCurveTo(0, -10, -16, -10, -16, 0);
      s.bezierCurveTo(-16, 12, 0, 22, 0, 30);
      s.bezierCurveTo(0, 22, 16, 12, 16, 0);
      s.bezierCurveTo(16, -10, 0, -10, 0, 0);
      return s;
    }

    const heartGeo = new THREE.ExtrudeGeometry(createHeartShape(), {
      depth: 8,
      bevelEnabled: true,
      bevelThickness: 2,
      bevelSize: 2,
      bevelSegments: 12,
      curveSegments: 32
    });
    heartGeo.center();

    // ── Materials ────────────────────────────────────────
    const heartMat = new THREE.MeshStandardMaterial({
      color: 0xff2255,
      emissive: 0x440011,
      metalness: 0.3,
      roughness: 0.35,
    });

    const heart = new THREE.Mesh(heartGeo, heartMat);
    heart.rotation.z = Math.PI;          // point upright
    scene.add(heart);

    // ── Wireframe overlay (subtle glow) ──────────────────
    const wireMat = new THREE.MeshBasicMaterial({
      color: 0xff6699,
      wireframe: true,
      transparent: true,
      opacity: 0.06,
    });
    const wireHeart = new THREE.Mesh(heartGeo, wireMat);
    wireHeart.rotation.z = Math.PI;
    wireHeart.scale.setScalar(1.02);
    scene.add(wireHeart);

    // ── Particles ────────────────────────────────────────
    const pCount = 1200;
    const pGeo   = new THREE.BufferGeometry();
    const positions = new Float32Array(pCount * 3);
    const colors    = new Float32Array(pCount * 3);

    for (let i = 0; i < pCount; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi   = Math.acos(2 * Math.random() - 1);
      const r     = 18 + Math.random() * 40;
      positions[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
      positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
      positions[i * 3 + 2] = r * Math.cos(phi);

      const c = new THREE.Color().setHSL(0.95 + Math.random() * 0.08, 0.8, 0.5 + Math.random() * 0.4);
      colors[i * 3]     = c.r;
      colors[i * 3 + 1] = c.g;
      colors[i * 3 + 2] = c.b;
    }

    pGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    pGeo.setAttribute('color',    new THREE.BufferAttribute(colors, 3));

    const pMat = new THREE.PointsMaterial({
      size: 0.25,
      vertexColors: true,
      transparent: true,
      opacity: 0.8,
      sizeAttenuation: true,
    });
    const particles = new THREE.Points(pGeo, pMat);
    scene.add(particles);

    // ── Floating mini-hearts ─────────────────────────────
    const miniHearts = [];
    const miniGeo = new THREE.ExtrudeGeometry(createHeartShape(), {
      depth: 1.5, bevelEnabled: true, bevelThickness: 0.4, bevelSize: 0.4, bevelSegments: 4, curveSegments: 16
    });
    miniGeo.center();

    for (let i = 0; i < 18; i++) {
      const mat = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(0.96 + Math.random() * 0.06, 0.9, 0.5 + Math.random() * 0.3),
        emissive: 0x330011,
        metalness: 0.5,
        roughness: 0.3,
      });
      const mesh = new THREE.Mesh(miniGeo, mat);
      mesh.rotation.z = Math.PI;
      const scale = 0.2 + Math.random() * 0.4;
      mesh.scale.setScalar(scale);
      mesh.position.set(
        (Math.random() - 0.5) * 40,
        (Math.random() - 0.5) * 40,
        (Math.random() - 0.5) * 20
      );
      mesh.userData = {
        speed: 0.2 + Math.random() * 0.4,
        offset: Math.random() * Math.PI * 2,
        rotSpeed: (Math.random() - 0.5) * 2,
      };
      scene.add(mesh);
      miniHearts.push(mesh);
    }

    // ── Lighting ─────────────────────────────────────────
    scene.add(new THREE.AmbientLight(0x332244, 0.8));

    const dirLight = new THREE.DirectionalLight(0xffaacc, 1.0);
    dirLight.position.set(10, 15, 20);
    scene.add(dirLight);

    const pointLight1 = new THREE.PointLight(0xff4488, 2.5, 60);
    pointLight1.position.set(-12, 8, 10);
    scene.add(pointLight1);

    const pointLight2 = new THREE.PointLight(0xff88aa, 1.8, 50);
    pointLight2.position.set(12, -6, 12);
    scene.add(pointLight2);

    const rimLight = new THREE.PointLight(0x8844ff, 1.0, 50);
    rimLight.position.set(0, -15, -10);
    scene.add(rimLight);

    // ── Animation ────────────────────────────────────────
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      // Heart beat
      const beat = 1 + 0.06 * Math.sin(t * 4) * Math.sin(t * 8);
      heart.scale.setScalar(beat);
      wireHeart.scale.setScalar(beat * 1.02);

      // Gentle rotation
      heart.rotation.y = Math.sin(t * 0.5) * 0.3;
      wireHeart.rotation.y = heart.rotation.y;

      // Floating particles
      particles.rotation.y = t * 0.05;
      particles.rotation.x = Math.sin(t * 0.03) * 0.1;

      // Mini-hearts float
      miniHearts.forEach(m => {
        m.position.y += m.userData.speed * 0.02;
        m.rotation.y += m.userData.rotSpeed * 0.01;
        if (m.position.y > 25) m.position.y = -25;
      });

      // Orbiting lights
      pointLight1.position.x = Math.cos(t * 0.7) * 15;
      pointLight1.position.z = Math.sin(t * 0.7) * 15;
      pointLight2.position.x = Math.cos(t * 0.5 + 2) * 12;
      pointLight2.position.z = Math.sin(t * 0.5 + 2) * 12;

      renderer.render(scene, camera);
    }

    animate();

    // ── Resize ───────────────────────────────────────────
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
