<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ── Scene ── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.FogExp2(0x87CEEB, 0.008);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 500);
camera.position.set(12, 8, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2, 0);
controls.enableDamping = true;
controls.update();

/* ── Lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.6));
const sun = new THREE.DirectionalLight(0xffffff, 1.8);
sun.position.set(15, 25, 10);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 60;
sun.shadow.camera.left = sun.shadow.camera.bottom = -20;
sun.shadow.camera.right = sun.shadow.camera.top = 20;
scene.add(sun);
scene.add(new THREE.HemisphereLight(0x87CEEB, 0x556B2F, 0.4));

/* ── Materials ── */
const bodyMat   = new THREE.MeshStandardMaterial({ color: 0xCC3333, metalness: 0.3, roughness: 0.4 });
const darkMat    = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.5, roughness: 0.3 });
const glassMat   = new THREE.MeshStandardMaterial({ color: 0x88CCFF, metalness: 0.1, roughness: 0.05, transparent: true, opacity: 0.5 });
const rotorMat   = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.6, roughness: 0.2, side: THREE.DoubleSide });
const skidMat    = new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.7, roughness: 0.3 });
const yellowMat  = new THREE.MeshStandardMaterial({ color: 0xFFCC00, metalness: 0.2, roughness: 0.5 });

/* ── Helicopter Group ── */
const heli = new THREE.Group();

/* ── Fuselage ── */
const fuselageGeo = new THREE.BoxGeometry(2.2, 2, 5.5, 2, 2, 2);
// Round the fuselage by modifying vertices
const pos = fuselageGeo.attributes.position;
const tempV = new THREE.Vector3();
for (let i = 0; i < pos.count; i++) {
  tempV.fromBufferAttribute(pos, i);
  const frontBack = 1 - Math.abs(tempV.z) / 2.75;
  const factor = 0.3 + 0.7 * frontBack;
  tempV.x *= factor;
  tempV.y *= factor;
  pos.setXYZ(i, tempV.x, tempV.y, tempV.z);
}
fuselageGeo.computeVertexNormals();
const fuselage = new THREE.Mesh(fuselageGeo, bodyMat);
fuselage.position.y = 3.2;
fuselage.castShadow = true;
heli.add(fuselage);

/* ── Cockpit canopy ── */
const cockpitGeo = new THREE.SphereGeometry(1.1, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.5);
const cockpit = new THREE.Mesh(cockpitGeo, glassMat);
cockpit.position.set(0, 3.8, 1.8);
cockpit.scale.set(1, 0.7, 1.3);
heli.add(cockpit);

/* ── Nose cone ── */
const noseGeo = new THREE.ConeGeometry(1.0, 2, 16);
const nose = new THREE.Mesh(noseGeo, bodyMat);
nose.rotation.x = Math.PI / 2;
nose.position.set(0, 3.2, 3.5);
nose.castShadow = true;
heli.add(nose);

/* ── Tail boom ── */
const tailBoomGeo = new THREE.CylinderGeometry(0.35, 0.55, 7, 8);
const tailBoom = new THREE.Mesh(tailBoomGeo, bodyMat);
tailBoom.rotation.x = Math.PI / 2;
tailBoom.position.set(0, 3.4, -5.5);
tailBoom.castShadow = true;
heli.add(tailBoom);

/* ── Tail fin (vertical stabilizer) ── */
const finGeo = new THREE.BoxGeometry(0.12, 2.2, 1.2);
const fin = new THREE.Mesh(finGeo, bodyMat);
fin.position.set(0, 4.2, -8.8);
fin.castShadow = true;
heli.add(fin);

// Fin top cap
const finTopGeo = new THREE.BoxGeometry(0.12, 0.12, 1.4);
const finTop = new THREE.Mesh(finTopGeo, yellowMat);
finTop.position.set(0, 5.35, -8.8);
heli.add(finTop);

/* ── Tail rotor ── */
const tailRotorGroup = new THREE.Group();
tailRotorGroup.position.set(0.6, 4.4, -8.8);

const tailRotorHub = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.2, 8), darkMat);
tailRotorGroup.add(tailRotorHub);

for (let i = 0; i < 2; i++) {
  const blade = new THREE.Mesh(new THREE.BoxGeometry(0.06, 1.6, 0.15), rotorMat);
  blade.rotation.z = i * Math.PI / 2;
  blade.castShadow = true;
  tailRotorGroup.add(blade);
}
heli.add(tailRotorGroup);

/* ── Main rotor mast ── */
const mastGeo = new THREE.CylinderGeometry(0.15, 0.2, 0.6, 8);
const mast = new THREE.Mesh(mastGeo, darkMat);
mast.position.set(0, 4.5, 0);
heli.add(mast);

/* ── Main rotor blades ── */
const mainRotorGroup = new THREE.Group();
mainRotorGroup.position.set(0, 4.8, 0);

const rotorHub = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.2, 12), darkMat);
mainRotorGroup.add(rotorHub);

for (let i = 0; i < 4; i++) {
  const bladeGeo = new THREE.BoxGeometry(0.25, 0.06, 7, 1, 1, 4);
  // Slight twist along blade
  const bPos = bladeGeo.attributes.position;
  for (let j = 0; j < bPos.count; j++) {
    const z = bPos.getZ(j);
    const twist = z * 0.04;
    const x = bPos.getX(j);
    const y = bPos.getY(j);
    const cos = Math.cos(twist), sin = Math.sin(twist);
    bPos.setXYZ(j, x * cos - y * sin, x * sin + y * cos, z);
  }
  bladeGeo.computeVertexNormals();

  const blade = new THREE.Mesh(bladeGeo, rotorMat);
  blade.rotation.y = i * Math.PI / 2;
  blade.castShadow = true;
  mainRotorGroup.add(blade);
}
heli.add(mainRotorGroup);

/* ── Landing skids ── */
function makeSkid(x) {
  const group = new THREE.Group();
  // Horizontal bar
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 4, 8), skidMat);
  bar.rotation.x = Math.PI / 2;
  bar.position.set(x, 1.2, 0.5);
  bar.castShadow = true;
  group.add(bar);
  // Vertical strut
  const strut = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 1.8, 6), skidMat);
  strut.position.set(x, 2.1, 0.5);
  strut.castShadow = true;
  group.add(strut);
  // Skid pad
  const pad = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.1, 4.2), darkMat);
  pad.position.set(x, 1.1, 0.5);
  pad.castShadow = true;
  group.add(pad);
  return group;
}
heli.add(makeSkid(1.1));
heli.add(makeSkid(-1.1));

/* ── Windows ── */
for (let side of [-1, 1]) {
  for (let i = 0; i < 3; i++) {
    const winGeo = new THREE.BoxGeometry(0.05, 0.5, 0.6);
    const win = new THREE.Mesh(winGeo, glassMat);
    win.position.set(side * 1.05, 3.4, 0.5 - i * 1.1);
    heli.add(win);
  }
}

/* ── Door line ── */
for (let side of [-1, 1]) {
  const doorGeo = new THREE.BoxGeometry(0.03, 1.6, 3);
  const door = new THREE.Mesh(doorGeo, darkMat);
  door.position.set(side * 1.08, 3.2, 0.2);
  heli.add(door);
}

/* ── Navigation lights ── */
const navLightGeo = new THREE.SphereGeometry(0.08, 8, 8);
const redMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 2 });
const greenMat = new THREE.MeshStandardMaterial({ color: 0x00ff00, emissive: 0x00ff00, emissiveIntensity: 2 });
const redLight = new THREE.Mesh(navLightGeo, redMat);
redLight.position.set(1.3, 4.6, -2.8);
heli.add(redLight);
const greenLight = new THREE.Mesh(navLightGeo, greenMat);
greenLight.position.set(-1.3, 4.6, -2.8);
heli.add(greenLight);

scene.add(heli);

/* ── Ground ── */
const groundGeo = new THREE.CircleGeometry(80, 64);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x4A7C3F, roughness: 0.9 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Runway
const runwayGeo = new THREE.PlaneGeometry(8, 40);
const runwayMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
const runway = new THREE.Mesh(runwayGeo, runwayMat);
runway.rotation.x = -Math.PI / 2;
runway.position.y = 0.01;
runway.receiveShadow = true;
scene.add(runway);

// Runway markings
for (let i = -16; i <= 16; i += 4) {
  const markGeo = new THREE.PlaneGeometry(0.3, 2);
  const markMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
  const mark = new THREE.Mesh(markGeo, markMat);
  mark.rotation.x = -Math.PI / 2;
  mark.position.set(0, 0.02, i);
  scene.add(mark);
}

/* ── Clouds ── */
const cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, roughness: 1 });
function makeCloud(x, y, z) {
  const g = new THREE.Group();
  for (let i = 0; i < 6; i++) {
    const s = 1 + Math.random() * 3;
    const m = new THREE.Mesh(new THREE.SphereGeometry(s, 8, 6), cloudMat);
    m.position.set((Math.random() - 0.5) * 5, (Math.random() - 0.5) * 1.5, (Math.random() - 0.5) * 3);
    m.scale.y = 0.5;
    g.add(m);
  }
  g.position.set(x, y, z);
  return g;
}
scene.add(makeCloud(25, 18, -30));
scene.add(makeCloud(-30, 22, -20));
scene.add(makeCloud(35, 15, 20));
scene.add(makeCloud(-20, 20, 30));

/* ── Animation ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Rotor spin
  mainRotorGroup.rotation.y = t * 18;
  tailRotorGroup.rotation.y = t * 35;

  // Gentle hover
  heli.position.y = Math.sin(t * 1.5) * 0.3;
  heli.rotation.z = Math.sin(t * 0.8) * 0.015;
  heli.rotation.x = Math.sin(t * 1.1) * 0.01;

  // Blink nav lights
  const blink = Math.sin(t * 4) > 0 ? 2 : 0.2;
  redMat.emissiveIntensity = blink;
  greenMat.emissiveIntensity = Math.sin(t * 4 + 1) > 0 ? 2 : 0.2;

  controls.update();
  renderer.render(scene, camera);
}
animate();

/* ── Resize ── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
