```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three.js Igloo</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene, Camera, Renderer ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.025);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(5, 3.5, 7);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;

// ── Lighting ──
const ambient = new THREE.AmbientLight(0x8899bb, 0.6);
scene.add(ambient);

const moon = new THREE.DirectionalLight(0xc8d8ff, 1.8);
moon.position.set(5, 10, 5);
moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024);
scene.add(moon);

const fill = new THREE.PointLight(0xffeedd, 0.5, 15);
fill.position.set(-3, 2, -2);
scene.add(fill);

// ── Materials ──
const snowMat = new THREE.MeshStandardMaterial({
  color: 0xeef4ff, roughness: 0.85, metalness: 0.0
});
const blockMat = new THREE.MeshStandardMaterial({
  color: 0xdce8f5, roughness: 0.9, metalness: 0.0
});
const groundMat = new THREE.MeshStandardMaterial({
  color: 0xc8daf0, roughness: 1.0, metalness: 0.0
});

// ── Ground ──
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(30, 64), groundMat
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ── Igloo Dome (built from individual snow blocks) ──
const iglooGroup = new THREE.Group();
scene.add(iglooGroup);

const blocks = [];
const R = 2.5;            // igloo radius
const layers = 8;         // vertical rings
const blocksPerRow = [];

for (let row = 0; row < layers; row++) {
  const phi = (Math.PI / 2) * (row + 0.5) / layers;
  const r = R * Math.cos(phi);
  const y = R * Math.sin(phi);
  const circumference = 2 * Math.PI * r;
  const n = Math.max(3, Math.round(circumference / (R * 0.45)));
  blocksPerRow.push(n);

  for (let i = 0; i < n; i++) {
    const theta = (2 * Math.PI * i) / n;
    const x = r * Math.cos(theta);
    const z = r * Math.sin(theta);

    const size = R * 0.22;
    const block = new THREE.Mesh(
      new THREE.BoxGeometry(size, size * 0.55, size),
      blockMat
    );
    block.position.set(x, y, z);
    block.lookAt(0, y, 0);
    block.rotateY(Math.PI / 2);
    block.castShadow = true;
    block.receiveShadow = true;
    iglooGroup.add(block);
    blocks.push(block);
  }
}

// ── Entrance Tunnel ──
const tunnelGroup = new THREE.Group();
iglooGroup.add(tunnelGroup);

const tunnelR = 0.35;
const tunnelLen = 1.2;
const tunnelSegs = 6;

for (let i = 0; i < tunnelSegs; i++) {
  const z = i * (tunnelLen / tunnelSegs);
  const ringR = tunnelR * (1 - i / tunnelSegs * 0.15);

  for (let j = 0; j < 8; j++) {
    const angle = (2 * Math.PI * j) / 8;
    if (angle > Math.PI * 0.25 && angle < Math.PI * 0.75) continue; // opening

    const bx = ringR * Math.cos(angle);
    const by = ringR * Math.sin(angle) + 0.15;

    const block = new THREE.Mesh(
      new THREE.BoxGeometry(0.25, 0.2, 0.2),
      blockMat
    );
    block.position.set(bx, by, z + 0.1);
    block.castShadow = true;
    tunnelGroup.add(block);
  }
}

// ── Snow drifts around base ──
for (let i = 0; i < 40; i++) {
  const a = Math.random() * Math.PI * 2;
  const d = R * Math.cos((Math.PI / 2) / layers) + 0.3 + Math.random() * 1.5;
  const drift = new THREE.Mesh(
    new THREE.SphereGeometry(0.15 + Math.random() * 0.2, 6, 4),
    snowMat
  );
  drift.position.set(
    d * Math.cos(a),
    0.05,
    d * Math.sin(a)
  );
  drift.scale.y = 0.3 + Math.random() * 0.3;
  drift.receiveShadow = true;
  scene.add(drift);
}

// ── Stars ──
const starGeo = new THREE.BufferGeometry();
const starVerts = [];
for (let i = 0; i < 600; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI * 0.45;
  const r = 25 + Math.random() * 15;
  starVerts.push(
    r * Math.sin(phi) * Math.cos(theta),
    r * Math.cos(phi) + 5,
    r * Math.sin(phi) * Math.sin(theta)
  );
}
starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starVerts, 3));
const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
  color: 0xffffff, size: 0.08, sizeAttenuation: true
}));
scene.add(stars);

// ── Animation ──
function animate(time) {
  requestAnimationFrame(animate);
  controls.update();

  // Gentle block shimmer
  blocks.forEach((b, i) => {
    const shimmer = Math.sin(time * 0.001 + i * 0.5) * 0.02;
    b.position.y += shimmer * 0.01;
  });

  renderer.render(scene, camera);
}
animate(0);

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
