        const grassGeometry = new THREE.CylinderGeometry(2.8, 3.8, 0.5, 8);
        const grassMaterial = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Green grass
        const grass = new THREE.Mesh(grassGeometry, grassMaterial);
        grass.position.y = 1;
        grass.receiveShadow = true;
        grass.castShadow = true;
        scene.add(grass);

        // Simple Tree Function
        function createTree(x, z) {
            const treeGroup = new THREE.Group();

            // Trunk
            const trunkGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.8, 6);
            const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5C4033 });
            const trunk = new THREE.Mesh(trunkGeo, trunkMat);
            trunk.position.y = 0.4;
            trunk.castShadow = true;
            treeGroup.add(trunk);

            // Leaves
            const leavesGeo = new THREE.ConeGeometry(0.6, 1.5, 8);
            const leavesMat = new THREE.MeshStandardMaterial({ color: 0x006400 });
            const leaves = new THREE.Mesh(leavesGeo, leavesMat);
            leaves.position.y = 1.2;
            leaves.castShadow = true;
            treeGroup.add(leaves);

            treeGroup.position.set(x, 1.25, z);
            return treeGroup;
        }

        // Add some trees
        scene.add(createTree(0, 0));
        scene.add(createTree(1.5, 1));
        scene.add(createTree(-1.2, 1.5));
        scene.add(createTree(-1.5, -1));

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle water movement
            water.position.y = -0.5 + Math.sin(Date.now() * 0.001) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
