<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x000510);
        scene.fog = new THREE.FogExp2(0x000510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x00ffff, 5, 20);
        pointLight.position.set(0, 0, 2);
        scene.add(pointLight);

        // Jellyfish Group
        const jellyfish = new THREE.Group();
        scene.add(jellyfish);

        // Materials
        const bellMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xff00ff,
            emissive: 0x440044,
            emissiveIntensity: 0.5,
            roughness: 0.1,
            metalness: 0.1,
            transmission: 0.6, // Glass-like
            thickness: 1.0,
            transparent: true,
            opacity: 0.9,
            side: THREE.DoubleSide
        });

        const tentacleMaterial = new THREE.MeshStandardMaterial({
            color: 0xff88ff,
            emissive: 0x220022,
            emissiveIntensity: 0.2,
            roughness: 0.4,
            transparent: true,
            opacity: 0.8
        });

        // Create Bell (Head)
        // Using LatheGeometry for a nice bell shape
        const bellPoints = [];
        for (let i = 0; i <= 10; i++) {
            const t = i / 10;
            // Create a curve that looks like a jellyfish bell
            const x = Math.sin(t * Math.PI) * 1.5; 
            const y = Math.cos(t * Math.PI) * 0.8 + 0.5; // Shift up
            bellPoints.push(new THREE.Vector2(x, y));
        }
        const bellGeometry = new THREE.LatheGeometry(bellPoints, 32);
        const bell = new THREE.Mesh(bellGeometry, bellMaterial);
        jellyfish.add(bell);

        // Create Tentacles
        const tentacles = [];
        const numTentacles = 12;
        const tentacleLength = 4;
        const segments = 20;

        for (let i = 0; i < numTentacles; i++) {
            const angle = (i / numTentacles) * Math.PI * 2;
            const radius = 1.2; // Radius where tentacles attach

            // Initial curve points
            const points = [];
            for (let j = 0; j <= segments; j++) {
                const t = j / segments;
                points.push(new THREE.Vector3(
                    Math.cos(angle) * radius * (1 - t * 0.5), // Taper slightly
                    Math.sin(angle) * radius * (1 - t * 0.5),
                    -t * tentacleLength
                ));
            }

            const curve = new THREE.CatmullRomCurve3(points);
            const tubeGeometry = new THREE.TubeGeometry(curve, segments, 0.05, 8, false);
            const tentacle = new THREE.Mesh(tubeGeometry, tentacleMaterial);

            // Store data for animation
            tentacle.userData = {
                originalPoints: points.map(p => p.clone()),
                angle: angle,
                phase: Math.random() * Math.PI * 2
            };

            jellyfish.add(tentacle);
            tentacles.push(tentacle);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Bobbing motion for the whole jellyfish
            jellyfish.position.y = Math.sin(time * 0.5) * 0.5;
            jellyfish.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Animate Tentacles
            tentacles.forEach((tentacle, index) => {
                const curve = tentacle.geometry.parameters.path;
                const positions = tentacle.geometry.attributes.position;
                const originalPoints = tentacle.userData.originalPoints;
                const phase = tentacle.userData.phase;

                // We need to update the geometry vertices directly or regenerate the curve
                // Regenerating curve is easier for TubeGeometry
                const newPoints = [];

                for (let j = 0; j <= segments; j++) {
                    const t = j / segments;
                    const original = originalPoints[j];

                    // Waving motion
                    const waveX = Math.sin(time * 2 + t * 3 + phase) * 0.2 * t;
                    const waveZ = Math.cos(time * 1.5 + t * 2 + phase) * 0.2 * t;

                    newPoints.push(new THREE.Vector3(
                        original.x + waveX,
                        original.y,
                        original.z + waveZ
                    ));
                }

                const newCurve = new THREE.CatmullRomCurve3(newPoints);
                tentacle.geometry.dispose(); // Clean up old geometry
                tentacle.geometry = new THREE.TubeGeometry(newCurve, segments, 0.05, 8, false);
            });

            // Pulse the bell slightly
            const scale = 1 + Math.sin(time * 2) * 0.05;
            bell.scale.set(scale, 1 / scale, scale);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
