    }
  </style>
</head>
<body>
  <div id="info">🦘 Three.js Kangaroo — drag to orbit, scroll to zoom</div>

  <script type="importmap">
  {
    "imports": {
      "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
      "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
    }
  }
  </script>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    /* ── scene, camera, renderer ── */
    const scene    = new THREE.Scene();
    scene.background = new THREE.Color(0x87ceeb);
    scene.fog = new THREE.FogExp2(0x87ceeb, 0.012);

    const camera   = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
    camera.position.set(6, 4, 8);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    /* ── controls ── */
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 1.5, 0);
    controls.enableDamping = true;

    /* ── lights ── */
    const ambient = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambient);

    const sun = new THREE.DirectionalLight(0xfff4e0, 1.4);
    sun.position.set(5, 10, 6);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far  = 30;
    sun.shadow.camera.left = sun.shadow.camera.bottom = -8;
    sun.shadow.camera.right = sun.shadow.camera.top   =  8;
    scene.add(sun);

    const rim = new THREE.DirectionalLight(0x8ec5fc, 0.6);
    rim.position.set(-4, 3, -5);
    scene.add(rim);

    /* ── ground ── */
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshStandardMaterial({ color: 0x4a7c3f, roughness: 0.95 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    /* ── materials ── */
    const fur      = new THREE.MeshStandardMaterial({ color: 0xb87333, roughness: 0.85 });
    const furDark  = new THREE.MeshStandardMaterial({ color: 0x8b5e3c, roughness: 0.85 });
    const furLight = new THREE.MeshStandardMaterial({ color: 0xd4a574, roughness: 0.85 });
    const noseMat  = new THREE.MeshStandardMaterial({ color: 0x4a3728, roughness: 0.6 });
    const eyeWhite = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });
    const eyePupil = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.2 });
    const earInner = new THREE.MeshStandardMaterial({ color: 0xd4956b, roughness: 0.7 });
    const padMat   = new THREE.MeshStandardMaterial({ color: 0x6b4226, roughness: 0.9 });

    /* ── kangaroo group ── */
    const kanga = new THREE.Group();
    scene.add(kanga);

    /* body */
    const body = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 20), fur);
    body.scale.set(1, 1.15, 0.8);
    body.position.set(0, 1.8, 0);
    body.castShadow = true;
    kanga.add(body);

    /* chest / belly (lighter patch) */
    const belly = new THREE.Mesh(new THREE.SphereGeometry(0.65, 20, 16), furLight);
    belly.scale.set(0.9, 1.1, 0.5);
    belly.position.set(0, 1.45, 0.45);
    kanga.add(belly);

    /* head */
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.52, 20, 18), fur);
    head.scale.set(1, 0.9, 0.85);
    head.position.set(0, 2.9, 0.35);
    head.castShadow = true;
    kanga.add(head);

    /* snout */
    const snout = new THREE.Mesh(new THREE.SphereGeometry(0.3, 16, 14), furDark);
    snout.scale.set(0.85, 0.65, 0.9);
    snout.position.set(0, 2.72, 0.72);
    kanga.add(snout);

    /* nose */
    const nose = new THREE.Mesh(new THREE.SphereGeometry(0.09, 12, 10), noseMat);
    nose.scale.set(1.3, 0.8, 1);
    nose.position.set(0, 2.78, 0.96);
    kanga.add(nose);

    /* eyes */
    [-1, 1].forEach(side => {
      const white = new THREE.Mesh(new THREE.SphereGeometry(0.1, 12, 10), eyeWhite);
      white.position.set(side * 0.28, 3.05, 0.68);
      kanga.add(white);

      const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.06, 10, 8), eyePupil);
      pupil.position.set(side * 0.28, 3.05, 0.76);
      kanga.add(pupil);
    });

    /* ears */
    [-1, 1].forEach(side => {
      const earGroup = new THREE.Group();

      const earOuter = new THREE.Mesh(
        new THREE.CapsuleGeometry(0.09, 0.35, 8, 12), fur
      );
      earOuter.position.set(0, 0.18, 0);
      earGroup.add(earOuter);

      const earIn = new THREE.Mesh(
        new THREE.CapsuleGeometry(0.055, 0.28, 6, 10), earInner
      );
      earIn.position.set(0, 0.16, 0.02);
      earGroup.add(earIn);

      earGroup.position.set(side * 0.32, 3.35, 0.2);
      earGroup.rotation.z = side * -0.25;
      earGroup.rotation.x = -0.15;
      earGroup.castShadow = true;
      kanga.add(earGroup);
    });

    /* tail */
    const tailGroup = new THREE.Group();
    const tailSegs = 7;
    const tailParts = [];

    for (let i = 0; i < tailSegs; i++) {
      const t = i / (tailSegs - 1);
      const r = 0.22 * (1 - t * 0.6);
      const seg = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 10), i % 2 === 0 ? fur : furDark);
      seg.scale.set(1, 1, 1.15);
      seg.position.set(0, -t * 0.55, -t * 1.6);
      seg.castShadow = true;
      tailGroup.add(seg);
      tailParts.push(seg);
    }
    tailGroup.position.set(0, 1.3, -0.6);
    tailGroup.rotation.x = 0.6;
    kanga.add(tailGroup);

    /* hind legs */
    [-1, 1].forEach(side => {
      const legGroup = new THREE.Group();

      /* thigh */
      const thigh = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 0.55, 10, 14), fur);
      thigh.position.set(0, 0, 0);
      legGroup.add(thigh);

      /* lower leg */
      const shin = new THREE.Mesh(new THREE.CapsuleGeometry(0.2, 0.5, 8, 12), furDark);
      shin.position.set(0, -0.6, 0.1);
      legGroup.add(shin);

      /* foot */
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.12, 0.55), padMat);
      foot.position.set(0, -0.95, 0.25);
      legGroup.add(foot);

      /* toe pads */
      const toePad = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 6), noseMat);
      toePad.position.set(0, -0.9, 0.45);
      legGroup.add(toePad);

      legGroup.position.set(side * 0.55, 0.95, 0.15);
      legGroup.rotation.x = -0.35;
      legGroup.rotation.z = side * 0.1;
      legGroup.castShadow = true;
      kanga.add(legGroup);
    });

    /* front arms */
    [-1, 1].forEach(side => {
      const armGroup = new THREE.Group();

      const upperArm = new THREE.Mesh(new THREE.CapsuleGeometry(0.1, 0.35, 8, 10), furDark);
      upperArm.position.set(0, 0, 0);
      armGroup.add(upperArm);

      const forearm = new THREE.Mesh(new THREE.CapsuleGeometry(0.08, 0.3, 6, 8), fur);
      forearm.position.set(0, -0.38, 0.05);
      armGroup.add(forearm);

      const paw = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 8), noseMat);
      paw.position.set(0, -0.62, 0.08);
      armGroup.add(paw);

      armGroup.position.set(side * 0.7, 2.05, 0.55);
      armGroup.rotation.x = -0.8;
      armGroup.rotation.z = side * -0.15;
      armGroup.castShadow = true;
      kanga.add(armGroup);
    });

    /* ── simple grass tufts ── */
    for (let i = 0; i < 60; i++) {
      const angle = Math.random() * Math.PI * 2;
      const rad   = 3 + Math.random() * 12;
      const x = Math.cos(angle) * rad;
      const z = Math.sin(angle) * rad;

      const tuft = new THREE.Mesh(
        new THREE.ConeGeometry(0.06 + Math.random() * 0.06, 0.25 + Math.random() * 0.2, 5),
        new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(0.28 + Math.random() * 0.06, 0.55, 0.28 + Math.random() * 0.12), roughness: 1 })
      );
      tuft.position.set(x, 0.12, z);
      tuft.castShadow = true;
      scene.add(tuft);
    }

    /* ── animation ── */
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      /* gentle hop */
      const hop = Math.abs(Math.sin(t * 1.8)) * 0.18;
      kanga.position.y = hop;

      /* slight body tilt */
      kanga.rotation.z = Math.sin(t * 1.8) * 0.03;

      /* tail sway */
      tailGroup.rotation.z = Math.sin(t * 1.8 + 1) * 0.08;

      /* ear twitch */
      kanga.children.forEach(c => {
        if (c.isGroup && c.children.length === 2 && c.children[0].geometry?.type === 'CapsuleGeometry') {
          c.rotation.z += Math.sin(t * 4 + c.position.x * 10) * 0.001;
        }
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    /* ── resize ── */
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
