  kite.position.y = Math.sin(time * 1.2) * 1.5;
  kite.position.x = Math.sin(time * .7) * .8;
  kite.rotation.z = Math.sin(time * 1.5) * .08;
  kite.rotation.x = Math.sin(time * .9) * .05;

  // Tail wave
  tailSegments.forEach((seg, i) => {
    seg.rotation.z = Math.sin(time * 3 + i * .5) * .25;
    seg.position.x = Math.sin(time * 2 + i * .4) * .3 * (i / tailSegments.length);
  });

  // Clouds drift
  clouds.forEach((c, i) => {
    c.position.x += .003 * (i % 2 === 0 ? 1 : -1);
    if (c.position.x > 40) c.position.x = -40;
    if (c.position.x < -40) c.position.x = 40;
  });

  renderer.render(scene, camera);
}
animate();

// Resize
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in the scene:**

- **Diamond kite sail** — semi-transparent red with a teal accent triangle
- **Cross spars** — gold-colored horizontal & vertical poles
- **12-segment tail** — yellow flags that wave independently
- **String** — a white curved line dropping from the kite
- **Clouds** — 4 clusters of spheres drifting slowly
- **Green ground** plane with fog fading into the sky

