        scene.add(dirLight);

        // Ladder Construction
        const ladderGroup = new THREE.Group();
        const woodMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.8 });

        // Dimensions
        const railHeight = 5;
        const railWidth = 0.2;
        const railDepth = 0.2;
        const rungWidth = 2.4;
        const rungHeight = 0.15;
        const rungDepth = 0.15;
        const spacing = 0.8;
        const numRungs = 6;

        // Rails
        const railGeo = new THREE.BoxGeometry(railWidth, railHeight, railDepth);

        const leftRail = new THREE.Mesh(railGeo, woodMaterial);
        leftRail.position.set(-1, 0, 0);
        leftRail.castShadow = true;
        ladderGroup.add(leftRail);

        const rightRail = new THREE.Mesh(railGeo, woodMaterial);
        rightRail.position.set(1, 0, 0);
        rightRail.castShadow = true;
        ladderGroup.add(rightRail);

        // Rungs
        const rungGeo = new THREE.BoxGeometry(rungWidth, rungHeight, rungDepth);
        const startY = -(numRungs - 1) * spacing / 2;

        for (let i = 0; i < numRungs; i++) {
            const rung = new THREE.Mesh(rungGeo, woodMaterial);
            rung.position.set(0, startY + i * spacing, 0);
            rung.castShadow = true;
            ladderGroup.add(rung);
