<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000000, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Materials ──
const metalMat = new THREE.MeshStandardMaterial({
  color: 0x2a1a0a, metalness: 0.9, roughness: 0.3
});
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffeedd, transparent: true, opacity: 0.15,
  roughness: 0.05, transmission: 0.9, thickness: 0.5
});
const glowMat = new THREE.MeshStandardMaterial({
  color: 0xff6600, emissive: 0xff4400, emissiveIntensity: 3
});
const flameMat = new THREE.MeshStandardMaterial({
  color: 0xffaa00, emissive: 0xff8800, emissiveIntensity: 5,
  transparent: true, opacity: 0.9
});

// ── Lantern Group ──
const lantern = new THREE.Group();

// Handle
const handleCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 3.6, 0),
  new THREE.Vector3(-0.8, 4.4, 0),
  new THREE.Vector3(0, 4.7, 0),
  new THREE.Vector3(0.8, 4.4, 0),
  new THREE.Vector3(0, 3.6, 0),
]);
const handleGeo = new THREE.TubeGeometry(handleCurve, 24, 0.04, 8, false);
lantern.add(new THREE.Mesh(handleGeo, metalMat));

// Top cap
const topGeo = new THREE.ConeGeometry(1.2, 0.8, 8, 1, true);
const top = new THREE.Mesh(topGeo, metalMat);
top.position.y = 2.8;
lantern.add(top);

// Top ring
const ringGeo = new THREE.TorusGeometry(1.2, 0.05, 8, 16);
lantern.add(new THREE.Mesh(ringGeo, metalMat).translateY(2.4));

// Glass panels (octagonal)
const glassGeo = new THREE.CylinderGeometry(1.15, 1.15, 2.4, 8, 1, true);
lantern.add(new THREE.Mesh(glassGeo, glassMat).translateY(1.2));

// Vertical frame bars
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const barGeo = new THREE.BoxGeometry(0.04, 2.4, 0.04);
  const bar = new THREE.Mesh(barGeo, metalMat);
  bar.position.set(Math.cos(angle) * 1.15, 1.2, Math.sin(angle) * 1.15);
  bar.rotation.y = angle;
  lantern.add(bar);
}

// Bottom base
const baseGeo = new THREE.CylinderGeometry(1.1, 1.3, 0.2, 8);
lantern.add(new THREE.Mesh(baseGeo, metalMat).translateY(0.1));

// Bottom plate
const plateGeo = new THREE.CylinderGeometry(1.2, 1.2, 0.05, 8);
lantern.add(new THREE.Mesh(plateGeo, metalMat).translateY(-0.05));

// Inner glow sphere
const glowGeo = new THREE.SphereGeometry(0.3, 16, 16);
const glow = new THREE.Mesh(glowGeo, glowMat);
glow.position.y = 1.2;
lantern.add(glow);

// Flame
const flameGeo = new THREE.SphereGeometry(0.12, 8, 8);
flameGeo.scale(1, 2.5, 1);
const flame = new THREE.Mesh(flameGeo, flameMat);
flame.position.y = 1.2;
lantern.add(flame);

// ── Lights ──
const pointLight = new THREE.PointLight(0xff6622, 15, 20, 2);
pointLight.position.y = 1.2;
lantern.add(pointLight);

const rimLight = new THREE.DirectionalLight(0x334466, 0.5);
rimLight.position.set(-3, 4, -2);
scene.add(rimLight);

scene.add(lantern);

// ── Floating Embers ──
const emberCount = 60;
const emberGeo = new THREE.BufferGeometry();
const emberPos = new Float32Array(emberCount * 3);
const emberVel = [];
for (let i = 0; i < emberCount; i++) {
  emberPos[i * 3] = (Math.random() - 0.5) * 4;
  emberPos[i * 3 + 1] = Math.random() * 6;
  emberPos[i * 3 + 2] = (Math.random() - 0.5) * 4;
  emberVel.push({
    x: (Math.random() - 0.5) * 0.003,
    y: Math.random() * 0.008 + 0.003,
    z: (Math.random() - 0.5) * 0.003,
  });
}
emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
const emberMat = new THREE.PointsMaterial({
  color: 0xff8833, size: 0.04, transparent: true, opacity: 0.7
});
const embers = new THREE.Points(emberGeo, emberMat);
scene.add(embers);

// ── Animate ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Flicker
  const flicker = 0.85 + Math.sin(t * 12) * 0.08 + Math.sin(t * 7.3) * 0.07;
  pointLight.intensity = 15 * flicker;
  glowMat.emissiveIntensity = 3 * flicker;
  flameMat.emissiveIntensity = 5 * flicker;

  // Flame sway
  flame.scale.set(1 + Math.sin(t * 15) * 0.15, 2.5 + Math.sin(t * 10) * 0.3, 1 + Math.sin(t * 13) * 0.15);

  // Gentle lantern bob
  lantern.position.y = Math.sin(t * 0.5) * 0.1;
  lantern.rotation.y = Math.sin(t * 0.3) * 0.05;

  // Embers rise
  const pos = embers.geometry.attributes.position;
  for (let i = 0; i < emberCount; i++) {
    pos.array[i * 3]     += emberVel[i].x + Math.sin(t + i) * 0.001;
    pos.array[i * 3 + 1] += emberVel[i].y;
    pos.array[i * 3 + 2] += emberVel[i].z;
    if (pos.array[i * 3 + 1] > 7) {
      pos.array[i * 3 + 1] = -0.5;
      pos.array[i * 3]     = (Math.random() - 0.5) * 4;
      pos.array[i * 3 + 2] = (Math.random() - 0.5) * 4;
    }
  }
  pos.needsUpdate = true;

  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What you get:**

- **Octagonal lantern** with a metal frame, transparent glass panels, conical roof, and curved handle
- **Flickering flame** inside — emissive sphere with animated scale simulating real fire movement
- **Dynamic point light** with intensity flicker that casts warm orange glow
- **Rising ember particles** drifting upward with gentle turbulence
- **Subtle lantern bob/sway** animation
- **Dark foggy atmosphere** to make the light pop
- **ACES filmic tone mapping** for cinematic color response
- **Responsive** — handles window resize

