    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffaa00, 0.5);
        backLight.position.set(-5, 5, -5);
        scene.add(backLight);

        // Materials
        const shellMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xd9381e, 
            roughness: 0.4, 
            metalness: 0.1 
        });
        const darkShellMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xa62b16, 
            roughness: 0.5 
        });
        const eyeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.2 
        });

        // Lobster Construction
        const lobster = new THREE.Group();

        // 1. Main Body (Thorax/Abdomen)
        const bodyGeo = new THREE.CapsuleGeometry(1, 2.5, 4, 16);
        const body = new THREE.Mesh(bodyGeo, shellMaterial);
        body.rotation.z = Math.PI / 2;
        body.position.set(0, 0, 0);
        body.castShadow = true;
        lobster.add(body);

        // 2. Head
        const headGeo = new THREE.SphereGeometry(1.1, 32, 32);
        const head = new THREE.Mesh(headGeo, shellMaterial);
        head.position.set(0, 0, 1.8);
        head.scale.set(1, 0.9, 1.1);
        head.castShadow = true;
        lobster.add(head);

        // 3. Tail Segments
        for (let i = 0; i < 4; i++) {
            const segGeo = new THREE.CylinderGeometry(0.9 - (i * 0.15), 1.0 - (i * 0.15), 0.6, 16);
            const seg = new THREE.Mesh(segGeo, darkShellMaterial);
            seg.rotation.x = Math.PI / 2;
            seg.position.set(0, 0, -1.5 - (i * 0.55));
            seg.castShadow = true;
            lobster.add(seg);
        }
        // Tail Fan
        const tailFanGeo = new THREE.ConeGeometry(1.2, 0.5, 3);
        const tailFan = new THREE.Mesh(tailFanGeo, shellMaterial);
        tailFan.rotation.x = -Math.PI / 2;
        tailFan.position.set(0, 0, -3.8);
        lobster.add(tailFan);

        // 4. Claws (Chelipeds)
        function createClaw(side) {
            const clawGroup = new THREE.Group();

            // Lower arm
            const armGeo = new THREE.CylinderGeometry(0.3, 0.4, 2, 8);
            const arm = new THREE.Mesh(armGeo, shellMaterial);
            arm.rotation.x = Math.PI / 2;
            arm.position.set(side * 1.5, -0.5, 1.5);
            arm.rotation.z = side * 0.5;
            clawGroup.add(arm);

            // The big pincer base
            const pincerBaseGeo = new THREE.SphereGeometry(0.6, 16, 16);
            const pincerBase = new THREE.Mesh(pincerBaseGeo, shellMaterial);
            pincerBase.position.set(side * 2.5, -0.8, 2.2);
            clawGroup.add(pincerBase);

            // Upper pincer part
            const upperPincerGeo = new THREE.CylinderGeometry(0.2, 0.4, 1.5, 8);
            const upperPincer = new THREE.Mesh(upperPincerGeo, shellMaterial);
            upperPincer.position.set(side * 2.5, -0.2, 2.8);
            upperPincer.rotation.x = Math.PI / 4;
            upperPincer.rotation.z = side * 0.2;
            clawGroup.add(upperPincer);

            // Lower pincer part
            const lowerPincerGeo = new THREE.CylinderGeometry(0.15, 0.3, 1.2, 8);
            const lowerPincer = new THREE.Mesh(lowerPincerGeo, shellMaterial);
            lowerPincer.position.set(side * 2.5, -1.2, 2.6);
            lowerPincer.rotation.x = -Math.PI / 4;
            lowerPincer.rotation.z = side * 0.2;
            clawGroup.add(lowerPincer);

            return clawGroup;
        }

        lobster.add(createClaw(1)); // Right
        lobster.add(createClaw(-1)); // Left

        // 5. Legs
        function createLeg(side, zOffset, angle) {
            const legGeo = new THREE.CylinderGeometry(0.05, 0.02, 1.5, 8);
            const leg = new THREE.Mesh(legGeo, darkShellMaterial);
            leg.position.set(side * 1.2, -1.2, zOffset);
            leg.rotation.z = side * angle;
            leg.rotation.x = -0.2;
            return leg;
        }

        for(let i=0; i<3; i++) {
            lobster.add(createLeg(1, 0.5 - (i*0.8), 0.5));
            lobster.add(createLeg(-1, 0.5 - (i*0.8), 0.5));
        }

        // 6. Antennae
        function createAntenna(side) {
            const curve = new THREE.CatmullRomCurve3([
                new THREE.Vector3(0, 0, 0),
                new THREE.Vector3(side * 0.5, 1, 2),
                new THREE.Vector3(side * 1.5, 2, 3.5),
                new THREE.Vector3(side * 2, 1.5, 5)
            ]);
            const geo = new THREE.TubeGeometry(curve, 20, 0.05, 8, false);
            const mesh = new THREE.Mesh(geo, darkShellMaterial);
            mesh.position.set(side * 0.5, 0.5, 2);
            return mesh;
        }
        lobster.add(createAntenna(1));
        lobster.add(createAntenna(-1));

        // 7. Eyes
        function createEye(side) {
            const stalkGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.4, 8);
            const stalk = new THREE.Mesh(stalkGeo, darkShellMaterial);
            stalk.position.set(side * 0.6, 0.8, 2.2);
            stalk.rotation.x = -Math.PI / 4;

            const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
            const eye = new THREE.Mesh(eyeGeo, eyeMaterial);
            eye.position.set(side * 0.8, 1.0, 2.4);

            const eyeGroup = new THREE.Group();
            eyeGroup.add(stalk);
            eyeGroup.add(eye);
            return eyeGroup;
        }
        lobster.add(createEye(1));
        lobster.add(createEye(-1));

        // Center and add to scene
        lobster.position.y = 1;
        scene.add(lobster);

        // Floor
        const floorGeo = new THREE.PlaneGeometry(50, 50);
        const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.8 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            const time = Date.now() * 0.001;
            lobster.position.y = 1 + Math.sin(time) * 0.2;
            lobster.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
