<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, .1, 1000);
camera.position.set(0, 0, 3.2);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ── Controls ───────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = .06;
controls.minDistance = 1.6;
controls.maxDistance = 8;
controls.autoRotate = true;
controls.autoRotateSpeed = .6;

// ── Stars ──────────────────────────────────────────────
const starGeo = new THREE.BufferGeometry();
const starCount = 6000;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++)
  starPos[i] = (Math.random() - .5) * 200;
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
scene.add(new THREE.Points(starGeo, new THREE.PointsMaterial({
  color: 0xffffff, size: .12, sizeAttenuation: true
})));

// ── Earth ──────────────────────────────────────────────
const earthGroup = new THREE.Group();
scene.add(earthGroup);

// Procedural Earth texture via canvas
function makeEarthTexture() {
  const c = document.createElement('canvas');
  c.width = 2048; c.height = 1024;
  const ctx = c.getContext('2d');

  // Ocean gradient
  const grad = ctx.createLinearGradient(0, 0, 0, c.height);
  grad.addColorStop(0, '#1a3a5c');
  grad.addColorStop(.5, '#1565a0');
  grad.addColorStop(1, '#1a3a5c');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, c.width, c.height);

  // Simplified continent shapes (lon/lat → pixel)
  const toXY = (lon, lat) => [(lon + 180) / 360 * c.width, (90 - lat) / 180 * c.height];
  const drawPoly = (points, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    const [sx, sy] = toXY(points[0][0], points[0][1]);
    ctx.moveTo(sx, sy);
    for (let i = 1; i < points.length; i++) {
      const [x, y] = toXY(points[i][0], points[i][1]);
      ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  };

  const land = '#2d6a2e';
  const land2 = '#3a7d3a';

  // North America
  drawPoly([[-130,55],[-125,65],[-100,70],[-80,65],[-60,50],[-65,45],[-75,30],[-82,25],[-100,20],[-105,25],[-120,35],[-125,48],[-130,55]], land);
  // South America
  drawPoly([[-80,10],[-60,10],[-35,-5],[-35,-20],[-40,-30],[-55,-35],[-70,-55],[-75,-45],[-70,-20],[-80,0],[-80,10]], land2);
  // Europe
  drawPoly([[-10,38],[0,43],[5,48],[15,55],[30,60],[40,55],[35,45],[25,38],[10,36],[-10,38]], land);
  // Africa
  drawPoly([[-15,30],[-5,35],[10,37],[30,32],[40,15],[50,5],[45,-10],[40,-35],[20,-35],[12,-25],[10,-5],[0,5],[-15,12],[-15,30]], land2);
  // Asia
  drawPoly([[30,60],[40,55],[50,55],[60,65],[80,70],[120,65],[140,55],[145,45],[130,35],[120,25],[105,20],[100,10],[80,15],[70,25],[60,30],[40,42],[30,45],[30,60]], land);
  // India
  drawPoly([[70,25],[80,30],[85,22],[80,10],[75,10],[70,15],[70,25]], land2);
  // Australia
  drawPoly([[115,-15],[130,-12],[150,-15],[155,-25],[150,-35],[135,-35],[120,-30],[115,-22],[115,-15]], land);
  // Greenland
  drawPoly([[-55,60],[-45,75],[-20,80],[-15,70],[-25,60],[-40,58],[-55,60]], '#d0d8d0');

  // Ice caps
  ctx.fillStyle = 'rgba(220,230,240,0.7)';
  ctx.fillRect(0, 0, c.width, c.height * .06);
  ctx.fillRect(0, c.height * .94, c.width, c.height * .06);

  return new THREE.CanvasTexture(c);
}

function makeBumpTexture() {
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, c.width, c.height);
  // Add noise
  const imgData = ctx.getImageData(0, 0, c.width, c.height);
  for (let i = 0; i < imgData.data.length; i += 4) {
    const v = Math.random() * 30;
    imgData.data[i] = imgData.data[i+1] = imgData.data[i+2] = v;
    imgData.data[i+3] = 255;
  }
  ctx.putImageData(imgData, 0, 0);
  return new THREE.CanvasTexture(c);
}

const earthGeo = new THREE.SphereGeometry(1, 64, 64);
const earthMat = new THREE.MeshPhongMaterial({
  map: makeEarthTexture(),
  bumpMap: makeBumpTexture(),
  bumpScale: .02,
  specular: new THREE.Color(0x333333),
  shininess: 15,
});
const earth = new THREE.Mesh(earthGeo, earthMat);
earthGroup.add(earth);

