    varying vec3 vPosition;
    void main() {
      float intensity = pow(0.65 - dot(vNormal, vec3(0.0,0.0,1.0)), 2.5);
      gl_FragColor = vec4(0.3, 0.6, 1.0, 1.0) * intensity * 1.5;
    }
  `,
  blending: THREE.AdditiveBlending,
  side: THREE.FrontSide,
  transparent: true,
  depthWrite: false,
});
earthGroup.add(new THREE.Mesh(atmosGeo, atmosMat));

// ── City markers ───────────────────────────────────────
const cities = [
  { name: 'New York',       lon: -74,  lat: 40.7 },
  { name: 'London',         lon: -0.1, lat: 51.5 },
  { name: 'Tokyo',          lon: 139.7,lat: 35.7 },
  { name: 'Sydney',         lon: 151.2,lat: -33.9 },
  { name: 'São Paulo',      lon: -46.6,lat: -23.5 },
  { name: 'Cairo',          lon: 31.2, lat: 30.0 },
  { name: 'Mumbai',         lon: 72.9, lat: 19.1 },
  { name: 'Los Angeles',    lon: -118, lat: 34.1 },
];

const markerGeo = new THREE.SphereGeometry(.012, 8, 8);
const markerMat = new THREE.MeshBasicMaterial({ color: 0xff4444 });

cities.forEach(city => {
  const phi = (90 - city.lat) * Math.PI / 180;
  const theta = (city.lon + 180) * Math.PI / 180;
  const r = 1.01;
  const marker = new THREE.Mesh(markerGeo, markerMat.clone());
  marker.position.set(
    -r * Math.sin(phi) * Math.cos(theta),
     r * Math.cos(phi),
     r * Math.sin(phi) * Math.sin(theta)
  );
  earthGroup.add(marker);

  // Pulse ring
  const ringGeo = new THREE.RingGeometry(.015, .025, 24);
  const ringMat = new THREE.MeshBasicMaterial({
    color: 0xff4444, transparent: true, opacity: .6, side: THREE.DoubleSide
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.position.copy(marker.position);
  ring.lookAt(new THREE.Vector3(0, 0, 0));
  ring.userData.pulse = true;
  earthGroup.add(ring);
});

// ── Lighting ───────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x404060, 1.5));
const sun = new THREE.DirectionalLight(0xffffff, 2.5);
sun.position.set(5, 3, 5);
scene.add(sun);
const rim = new THREE.DirectionalLight(0x4488ff, .8);
rim.position.set(-5, -2, -5);
scene.add(rim);

// ── Animate ────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Pulse rings
  earthGroup.children.forEach(child => {
    if (child.userData.pulse) {
      const s = 1 + .4 * Math.sin(t * 3);
      child.scale.set(s, s, s);
      child.material.opacity = .6 * (1 - .4 * Math.sin(t * 3));
    }
  });

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ─────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What you get:**

- **Procedural Earth globe** — continents, oceans, and ice caps drawn on a canvas texture (no external image dependencies)
- **Atmospheric glow** — custom GLSL shader with additive blending for a blue rim-light halo
- **Pulsing city markers** — 8 major world cities with animated red ring indicators
- **Starfield** — 6,000 randomized background stars
- **Orbit controls** — drag to rotate, scroll to zoom, with gentle auto-rotation and damping
- **Bump mapping** — subtle noise-based surface relief
- **Responsive** — adapts to window resize

