// Body
const body = new THREE.Mesh(new THREE.SphereGeometry(0.7, 32, 24), fur);
body.scale.set(1, 1.15, 0.9);
body.position.y = -0.1;
body.castShadow = true;
monkey.add(body);

// Belly
const belly = new THREE.Mesh(new THREE.SphereGeometry(0.42, 32, 24), face);
belly.position.set(0, -0.1, 0.38);
belly.scale.set(1, 1.1, 0.5);
monkey.add(belly);

