const head = new THREE.Mesh(new THREE.SphereGeometry(0.55, 32, 24), fur);
head.position.y = 1.1;
head.castShadow = true;
monkey.add(head);

// Face disc
const faceMesh = new THREE.Mesh(new THREE.SphereGeometry(0.4, 32, 24), face);
