  inner.position.set(x * 0.58, 1.1, 0.1);
  monkey.add(inner);
});

// Eyes
[[-1, 0], [1, 0]].forEach(([x]) => {
  const white = new THREE.Mesh(new THREE.SphereGeometry(0.1, 24, 16), eyeW);
  white.position.set(x * 0.18, 1.2, 0.62);
  monkey.add(white);
  const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 12), eyeP);
