});

// Nose
const noseMesh = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 12), nose);
noseMesh.position.set(0, 1.0, 0.72);
monkey.add(noseMesh);

// Mouth (torus arc)
const mouthGeo = new THREE.TorusGeometry(0.1, 0.02, 8, 16, Math.PI);
const mouth = new THREE.Mesh(mouthGeo, nose);
