  arm.position.set(x * 0.72, 0.2, 0.15);
  arm.rotation.z = x * 0.6;
  arm.rotation.x = -0.3;
  arm.castShadow = true;
  arm.userData = { side: x, type: 'arm' };
  monkey.add(arm);

  // Hand
  const hand = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), face);
  hand.position.set(x * 0.95, -0.05, 0.25);
  monkey.add(hand);
});

// Legs
[[-1, 0], [1, 0]].forEach(([x]) => {
  const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.5, 8, 16), fur);
  leg.position.set(x * 0.35, -0.8, 0.1);
  leg.rotation.z = x * 0.15;
  leg.castShadow = true;
  monkey.add(leg);

  // Foot
  const foot = new THREE.Mesh(new THREE.SphereGeometry(0.15, 16, 12), face);
  foot.scale.set(1, 0.6, 1.3);
  foot.position.set(x * 0.35, -1.08, 0.22);
