    -0.5 - Math.cos(angle) * 0.4 * (1 - t * 0.5)
  ));
}
const tailCurve = new THREE.CatmullRomCurve3(tailPoints);
const tailGeo = new THREE.TubeGeometry(tailCurve, 32, 0.05, 8, false);
