  const p = new THREE.Mesh(
    new THREE.SphereGeometry(0.03 + Math.random() * 0.04, 8, 8),
    new THREE.MeshBasicMaterial({ color: new THREE.Color().setHSL(0.12 + Math.random() * 0.05, 0.8, 0.6) })
  );
  p.position.set(
    (Math.random() - 0.5) * 10,
    Math.random() * 6 - 1,
    (Math.random() - 0.5) * 8
  );
  p.userData = { speed: 0.2 + Math.random() * 0.5, offset: Math.random() * Math.PI * 2 };
  scene.add(p);
  particles.push(p);
}

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
