<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene Setup ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.012);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 6, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.update();

// ── Lighting ─────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x404060, 0.8));

const sun = new THREE.DirectionalLight(0xffeedd, 2.5);
sun.position.set(5, 10, 5);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 30;
sun.shadow.camera.left = -8;
sun.shadow.camera.right = 8;
sun.shadow.camera.top = 8;
sun.shadow.camera.bottom = -8;
scene.add(sun);

const rim = new THREE.DirectionalLight(0x4488ff, 0.6);
rim.position.set(-5, 3, -5);
scene.add(rim);

const warm = new THREE.PointLight(0xffaa44, 1.5, 20);
warm.position.set(0, 4, 0);
scene.add(warm);

// ── Materials ────────────────────────────────────────────────
const twigColors = [0x6b4226, 0x5c3a1e, 0x7a5230, 0x4e3420, 0x8b6340, 0x6e4b30];

function twigMaterial() {
  return new THREE.MeshStandardMaterial({
    color: twigColors[Math.random() * twigColors.length | 0],
    roughness: 0.9,
    metalness: 0.0,
  });
}

// ── Nest Twig Generator ──────────────────────────────────────
const nestGroup = new THREE.Group();
scene.add(nestGroup);

function createTwig(radius, height, segments, thickness, twist) {
  const points = [];
  const steps = segments;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = t * Math.PI * 2 + twist;
    const r = radius * (0.7 + 0.3 * Math.sin(t * Math.PI));
    const y = height * t * t;
    const wobble = Math.sin(angle * 3 + t * 10) * 0.08;
    points.push(new THREE.Vector3(
      Math.cos(angle) * (r + wobble),
      y,
      Math.sin(angle) * (r + wobble)
    ));
  }
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, segments * 2, thickness, 5, false);
  return new THREE.Mesh(geo, twigMaterial());
}

// ── Build Nest ───────────────────────────────────────────────
const TWIG_COUNT = 60;
const NEST_RADIUS = 2.5;
const NEST_HEIGHT = 2.0;

// Base twigs – wider, thicker, form the foundation
for (let i = 0; i < 20; i++) {
  const r = NEST_RADIUS * (0.85 + Math.random() * 0.15);
  const twist = (i / 20) * Math.PI * 2 + Math.random() * 0.3;
  const h = NEST_HEIGHT * (0.3 + Math.random() * 0.2);
  const thick = 0.06 + Math.random() * 0.04;
  const twig = createTwig(r, h, 24, thick, twist);
  twig.castShadow = true;
  twig.receiveShadow = true;
  nestGroup.add(twig);
}

// Middle twigs – spiral upward
for (let i = 0; i < 25; i++) {
  const r = NEST_RADIUS * (0.75 + Math.random() * 0.25);
  const twist = (i / 25) * Math.PI * 2 + Math.random() * 0.2;
  const h = NEST_HEIGHT * (0.6 + Math.random() * 0.3);
  const thick = 0.04 + Math.random() * 0.03;
  const twig = createTwig(r, h, 28, thick, twist);
  twig.castShadow = true;
  twig.receiveShadow = true;
  nestGroup.add(twig);
}

// Top rim twigs – define the opening
for (let i = 0; i < 15; i++) {
  const r = NEST_RADIUS * (0.95 + Math.random() * 0.1);
  const twist = (i / 15) * Math.PI * 2;
  const h = NEST_HEIGHT * (0.85 + Math.random() * 0.15);
  const thick = 0.03 + Math.random() * 0.025;
  const twig = createTwig(r, h, 32, thick, twist);
  twig.castShadow = true;
  twig.receiveShadow = true;
  nestGroup.add(twig);
}

// Extra random crossing twigs for realism
for (let i = 0; i < 10; i++) {
  const angle1 = Math.random() * Math.PI * 2;
  const angle2 = angle1 + Math.PI * (0.5 + Math.random());
  const r1 = NEST_RADIUS * (0.5 + Math.random() * 0.5);
  const r2 = NEST_RADIUS * (0.5 + Math.random() * 0.5);
  const y1 = NEST_HEIGHT * Math.random() * 0.8;
  const y2 = NEST_HEIGHT * (0.5 + Math.random() * 0.5);
  const midY = (y1 + y2) / 2 + Math.random() * 0.5;

  const pts = [
    new THREE.Vector3(Math.cos(angle1) * r1, y1, Math.sin(angle1) * r1),
    new THREE.Vector3(
      Math.cos((angle1 + angle2) / 2) * (r1 * 0.5),
      midY,
      Math.sin((angle1 + angle2) / 2) * (r1 * 0.5)
    ),
    new THREE.Vector3(Math.cos(angle2) * r2, y2, Math.sin(angle2) * r2),
  ];
  const curve = new THREE.CatmullRomCurve3(pts);
  const thick = 0.03 + Math.random() * 0.03;
  const geo = new THREE.TubeGeometry(curve, 16, thick, 5, false);
  const twig = new THREE.Mesh(geo, twigMaterial());
  twig.castShadow = true;
  twig.receiveShadow = true;
  nestGroup.add(twig);
}

// ── Eggs ─────────────────────────────────────────────────────
const eggGroup = new THREE.Group();
nestGroup.add(eggGroup);

function createEgg(x, z, scale, color) {
  const geo = new THREE.SphereGeometry(0.35 * scale, 24, 24);
  geo.scale(1, 1.35, 1);
  const mat = new THREE.MeshStandardMaterial({
    color,
    roughness: 0.25,
    metalness: 0.05,
  });
  const egg = new THREE.Mesh(geo, mat);
  egg.position.set(x, NEST_HEIGHT * 0.75, z);
  egg.rotation.z = (Math.random() - 0.5) * 0.3;
  egg.rotation.x = (Math.random() - 0.5) * 0.2;
  egg.castShadow = true;
  egg.receiveShadow = true;
  return egg;
}

eggGroup.add(createEgg(-0.5, 0.3, 1.0, 0xd4a87c));
eggGroup.add(createEgg(0.3, -0.4, 0.95, 0xc9956b));
eggGroup.add(createEgg(0.2, 0.5, 1.05, 0xdfb48e));

// ── Branch perch ─────────────────────────────────────────────
const branchCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(-6, 3.5, -2),
  new THREE.Vector3(-3, 3.8, -0.5),
  new THREE.Vector3(0, 3.6, 0),
  new THREE.Vector3(3, 3.4, 0.5),
  new THREE.Vector3(6, 3.2, 1),
]);
const branchGeo = new THREE.TubeGeometry(branchCurve, 32, 0.12, 8, false);
const branchMat = new THREE.MeshStandardMaterial({
  color: 0x5a3a1a,
  roughness: 0.95,
  metalness: 0.0,
});
const branch = new THREE.Mesh(branchGeo, branchMat);
branch.castShadow = true;
branch.receiveShadow = true;
scene.add(branch);

// Nest sits on the branch
nestGroup.position.y = 0.1;

// ── Ground plane ─────────────────────────────────────────────
const groundGeo = new THREE.PlaneGeometry(60, 60);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x1a2a1a,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -2;
ground.receiveShadow = true;
scene.add(ground);

// ── Animation ────────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle egg breathing
  eggGroup.children.forEach((egg, i) => {
    egg.position.y = NEST_HEIGHT * 0.75 + Math.sin(t * 0.8 + i * 1.5) * 0.02;
  });

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ───────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
