        head.position.y = 2.2;
        head.scale.set(1.1, 1, 1);
        head.castShadow = true;
        owlGroup.add(head);

        // Face Disks (White circles around eyes)
        const faceGeo = new THREE.CircleGeometry(0.45, 32);
        const faceLeft = new THREE.Mesh(faceGeo, whiteMat);
        faceLeft.position.set(-0.35, 2.2, 0.65);
        owlGroup.add(faceLeft);

        const faceRight = new THREE.Mesh(faceGeo, whiteMat);
        faceRight.position.set(0.35, 2.2, 0.65);
        owlGroup.add(faceRight);

