        const footRight = new THREE.Mesh(footGeo, footMat);
        footRight.position.set(0.3, 0.1, 0.4);
        owlGroup.add(footRight);

        // Toes
        const toeGeo = new THREE.SphereGeometry(0.08);
        for(let i=0; i<3; i++) {
            const toeL = new THREE.Mesh(toeGeo, footMat);
            toeL.position.set(-0.3 + (i-1)*0.1, 0, 0.5);
            owlGroup.add(toeL);

            const toeR = new THREE.Mesh(toeGeo, footMat);
            toeR.position.set(0.3 + (i-1)*0.1, 0, 0.5);
            owlGroup.add(toeR);
        }

        scene.add(owlGroup);

        // Floor (invisible plane for shadow)
        const planeGeo = new THREE.PlaneGeometry(20, 20);
        const planeMat = new THREE.ShadowMaterial({ opacity: 0.3 });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -0.2;
