            requestAnimationFrame(animate);

            // Gentle bobbing animation
            const time = Date.now() * 0.001;
            owlGroup.position.y = Math.sin(time) * 0.1;
            owlGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

