}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 15, 30);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;

// Lights
scene.add(new THREE.AmbientLight(0xffffff, 0.6));
const sun = new THREE.DirectionalLight(0xfff4e0, 1.5);
sun.position.set(5, 10, 7);
sun.castShadow = true;
scene.add(sun);
scene.add(new THREE.HemisphereLight(0x87CEEB, 0x3a7d3a, 0.4));

// Materials
const green = new THREE.MeshStandardMaterial({ color: 0x228B22, roughness: 0.6 });
const darkGreen = new THREE.MeshStandardMaterial({ color: 0x1a6b1a, roughness: 0.6 });
const blue = new THREE.MeshStandardMaterial({ color: 0x2266CC, roughness: 0.5 });
const red = new THREE.MeshStandardMaterial({ color: 0xCC2222, roughness: 0.5 });
const yellow = new THREE.MeshStandardMaterial({ color: 0xFFCC00, roughness: 0.4 });
const orange = new THREE.MeshStandardMaterial({ color: 0xFF8833, roughness: 0.4 });
const white = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });
const black = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.3 });
const gray = new THREE.MeshStandardMaterial({ color: 0x666666, roughness: 0.7 });

const parrot = new THREE.Group();

// --- BODY ---
const body = new THREE.Mesh(new THREE.SphereGeometry(0.55, 32, 32), green);
body.scale.set(1, 1.2, 0.85);
body.position.set(0, 1.2, 0);
body.castShadow = true;
parrot.add(body);

// Belly (lighter)
const belly = new THREE.Mesh(new THREE.SphereGeometry(0.42, 32, 32), yellow);
belly.scale.set(0.9, 1.1, 0.6);
belly.position.set(0, 1.0, 0.15);
parrot.add(belly);

// --- HEAD ---
const head = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), green);
head.position.set(0, 1.95, 0.05);
head.castShadow = true;
parrot.add(head);

// Forehead red patch
const forehead = new THREE.Mesh(new THREE.SphereGeometry(0.15, 16, 16), red);
forehead.position.set(0, 2.15, 0.15);
parrot.add(forehead);

// --- BEAK ---
const beakUpper = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.28, 8), orange);
beakUpper.rotation.x = Math.PI / 2;
beakUpper.position.set(0, 1.92, 0.42);
beakUpper.scale.set(1, 1, 0.7);
parrot.add(beakUpper);

const beakLower = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.15, 8), orange);
beakLower.rotation.x = -Math.PI / 2;
beakLower.position.set(0, 1.86, 0.4);
parrot.add(beakLower);

// --- EYES ---
function makeEye(x) {
  const group = new THREE.Group();
  const sclera = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 16), white);
  const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.04, 16, 16), black);
  pupil.position.z = 0.04;
  const highlight = new THREE.Mesh(new THREE.SphereGeometry(0.015, 8, 8), white);
  highlight.position.set(0.015, 0.015, 0.06);
  group.add(sclera, pupil, highlight);
  group.position.set(x, 2.0, 0.28);
  return group;
}
parrot.add(makeEye(-0.18));
parrot.add(makeEye(0.18));

// --- WINGS ---
function makeWing(side) {
  const wing = new THREE.Group();
  const main = new THREE.Mesh(new THREE.SphereGeometry(0.45, 16, 16), blue);
  main.scale.set(0.3, 1.1, 0.6);
  main.position.set(0, -0.1, 0);
  wing.add(main);

  const tip = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), darkGreen);
  tip.scale.set(0.3, 0.8, 0.5);
  tip.position.set(0, -0.6, 0);
  wing.add(tip);

  wing.position.set(side * 0.55, 1.35, -0.1);
  wing.rotation.z = side * 0.3;
  return wing;
}
const leftWing = makeWing(-1);
const rightWing = makeWing(1);
parrot.add(leftWing, rightWing);

// --- TAIL FEATHERS ---
const tailFeathers = [
  { color: blue, angle: 0, len: 1.2 },
  { color: darkGreen, angle: -0.2, len: 1.0 },
  { color: darkGreen, angle: 0.2, len: 1.0 },
  { color: red, angle: -0.35, len: 0.8 },
  { color: red, angle: 0.35, len: 0.8 },
  { color: yellow, angle: 0, len: 0.9 },
];
tailFeathers.forEach(f => {
  const feather = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8),
    new THREE.MeshStandardMaterial({ color: f.color, roughness: 0.5 }));
  feather.scale.set(1, f.len, 0.5);
  feather.position.set(Math.sin(f.angle) * 0.15, 0.4, -0.3 - Math.abs(f.angle) * 0.1);
  feather.rotation.x = -0.3 + f.angle * 0.5;
  feather.castShadow = true;
  parrot.add(feather);
});

// --- LEGS & FEET ---
function makeLeg(x) {
  const leg = new THREE.Group();
  const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.025, 0.25, 8), gray);
  thigh.position.y = -0.12;
  leg.add(thigh);

  const foot = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.03, 0.08), orange);
  foot.position.set(0, -0.25, 0.02);
  leg.add(foot);

  // Toes
  for (let i = -1; i <= 1; i++) {
    const toe = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.01, 0.06, 6), orange);
    toe.rotation.x = Math.PI / 2;
    toe.position.set(i * 0.04, -0.25, 0.06);
    leg.add(toe);
  }

  leg.position.set(x, 0.72, 0.1);
  return leg;
}
parrot.add(makeLeg(-0.12), makeLeg(0.12));

scene.add(parrot);

// --- PERCH ---
const perch = new THREE.Mesh(
  new THREE.CylinderGeometry(0.06, 0.06, 3, 12),
  new THREE.MeshStandardMaterial({ color: 0x8B5E3C, roughness: 0.9 })
);
perch.rotation.z = Math.PI / 2;
perch.position.set(0, 0.55, 0);
perch.castShadow = true;
perch.receiveShadow = true;
scene.add(perch);

// Leaves on perch
for (let i = 0; i < 8; i++) {
  const leaf = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 8, 8),
    new THREE.MeshStandardMaterial({ color: 0x2d8a2d, roughness: 0.8 })
  );
  leaf.scale.set(1, 0.3, 0.6);
  const angle = (i / 8) * Math.PI * 2;
  leaf.position.set(Math.cos(angle) * 1.5, 0.6 + Math.sin(i * 2) * 0.1, Math.sin(angle) * 0.3);
  leaf.rotation.y = angle;
  scene.add(leaf);
}

// --- ANIMATION ---
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle bobbing
  parrot.position.y = Math.sin(t * 1.5) * 0.03;
