  // Head tilt
  head.rotation.z = Math.sin(t * 0.8) * 0.08;
  head.rotation.y = Math.sin(t * 0.5) * 0.15;

  // Wing flutter
  leftWing.rotation.z = -0.3 + Math.sin(t * 3) * 0.05;
  rightWing.rotation.z = 0.3 - Math.sin(t * 3) * 0.05;

  // Tail sway
  tailFeathers.forEach((f, i) => {
    const feather = parrot.children.find(c =>
      c.geometry?.parameters?.radius === 0.08 &&
      c.position.y < 0.5 && c.position.y > 0
    );
  });

  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
