    <div id="info">🐍 Three.js Snake — scroll to zoom, drag to orbit</div>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        // 2. Camera
        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        // 3. Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // 4. Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // 5. Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // 6. The Snake
        const snakeGroup = new THREE.Group();
        const segmentCount = 20;
        const segments = [];

        // Materials
        const bodyMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x4caf50, 
            roughness: 0.4,
            metalness: 0.1
        });
        const headMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x2e7d32, 
            roughness: 0.4 
        });

        // Create segments
        const geometry = new THREE.SphereGeometry(0.4, 16, 16);
        const headGeometry = new THREE.SphereGeometry(0.5, 16, 16);

        for (let i = 0; i < segmentCount; i++) {
            let mesh;
            if (i === 0) {
                // Head
                mesh = new THREE.Mesh(headGeometry, headMaterial);
                // Add eyes
                const eyeGeo = new THREE.SphereGeometry(0.1, 8, 8);
                const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
                const pupilGeo = new THREE.SphereGeometry(0.05, 8, 8);
                const pupilMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

                const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
                leftEye.position.set(0.2, 0.2, 0.3);
                const leftPupil = new THREE.Mesh(pupilGeo, pupilMat);
                leftPupil.position.z = 0.08;
                leftEye.add(leftPupil);

                const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
                rightEye.position.set(-0.2, 0.2, 0.3);
                const rightPupil = new THREE.Mesh(pupilGeo, pupilMat);
                rightPupil.position.z = 0.08;
                rightEye.add(rightPupil);

                mesh.add(leftEye);
                mesh.add(rightEye);
            } else {
                // Body
                mesh = new THREE.Mesh(geometry, bodyMaterial);
                // Taper the tail slightly
                const scale = 1 - (i / segmentCount) * 0.5;
                mesh.scale.set(scale, scale, scale);
            }

            mesh.castShadow = true;
            mesh.receiveShadow = true;
            snakeGroup.add(mesh);
            segments.push(mesh);
        }
        scene.add(snakeGroup);

        // 7. Environment (Ground)
        const planeGeometry = new THREE.PlaneGeometry(100, 100);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Grid helper for visual reference
        const gridHelper = new THREE.GridHelper(100, 100, 0x444444, 0x222222);
        scene.add(gridHelper);

        // 8. Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const speed = 2;

            // Animate snake movement (sine wave motion)
            segments.forEach((segment, index) => {
                // Move forward slightly
                segment.position.z = Math.sin(time * speed + index * 0.3) * 2;
                segment.position.x = Math.cos(time * speed + index * 0.3) * 2;

                // Bobbing up and down
                segment.position.y = Math.sin(time * 3 + index * 0.5) * 0.3 + 0.5;

                // Rotate head to face direction of movement roughly
                if (index === 0) {
                    segment.rotation.y = -time * speed;
                } else {
                    // Body follows head rotation roughly
                    segment.rotation.y = -time * speed;
                }
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
