        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // Materials
        const orangeMat = new THREE.MeshStandardMaterial({ color: 0xff8c00, roughness: 0.5 });
        const blackMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.5 });
        const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const noseMat = new THREE.MeshStandardMaterial({ color: 0x330000 });

        // Tiger Group
        const tiger = new THREE.Group();

        // Helper to create striped box
        function createStripedBox(w, h, d, stripeCount) {
            const group = new THREE.Group();
            const bodyGeo = new THREE.BoxGeometry(w, h, d);
            const body = new THREE.Mesh(bodyGeo, orangeMat);
            body.castShadow = true;
            group.add(body);

            const stripeW = w / (stripeCount * 2 + 1);
            for(let i=0; i<stripeCount; i++) {
                const stripeGeo = new THREE.BoxGeometry(stripeW, h + 0.05, d + 0.05);
                const stripe = new THREE.Mesh(stripeGeo, blackMat);
                stripe.position.x = -w/2 + stripeW + (i * (stripeW * 2));
                group.add(stripe);
            }
            return group;
        }

        // 1. Body
        const bodyGroup = createStripedBox(2, 1.5, 3.5, 4);
        bodyGroup.position.y = 1.5;
        tiger.add(bodyGroup);

        // 2. Head
        const headGroup = new THREE.Group();
        const headGeo = new THREE.BoxGeometry(1.8, 1.6, 1.6);
        const head = new THREE.Mesh(headGeo, orangeMat);
        head.castShadow = true;
        headGroup.add(head);

