        const earL = new THREE.Mesh(earGeo, orangeMat);
        earL.position.set(-0.6, 0.8, 0);
        earL.rotation.z = 0.5;
        headGroup.add(earL);

        const earR = new THREE.Mesh(earGeo, orangeMat);
        earR.position.set(0.6, 0.8, 0);
        earR.rotation.z = -0.5;
        headGroup.add(earR);

        // Snout
        const snoutGeo = new THREE.BoxGeometry(1, 0.8, 0.6);
        const snout = new THREE.Mesh(snoutGeo, whiteMat);
        snout.position.set(0, -0.2, 0.8);
        headGroup.add(snout);

        // Nose
        const noseGeo = new THREE.BoxGeometry(0.3, 0.2, 0.1);
        const nose = new THREE.Mesh(noseGeo, noseMat);
        nose.position.set(0, -0.1, 1.1);
        headGroup.add(nose);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const eyeL = new THREE.Mesh(eyeGeo, blackMat);
        eyeL.position.set(-0.5, 0.3, 0.8);
        headGroup.add(eyeL);
        const eyeR = new THREE.Mesh(eyeGeo, blackMat);
        eyeR.position.set(0.5, 0.3, 0.8);
        headGroup.add(eyeR);

        headGroup.position.set(0, 2.5, 2);
        tiger.add(headGroup);

        // 3. Legs
        const legGeo = new THREE.CylinderGeometry(0.3, 0.3, 1.5, 16);
        const legPositions = [
            { x: -0.8, z: 1.2 }, { x: 0.8, z: 1.2 }, // Front
            { x: -0.8, z: -1.2 }, { x: 0.8, z: -1.2 } // Back
        ];

        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, orangeMat);
            leg.position.set(pos.x, 0.75, pos.z);
            leg.castShadow = true;
            tiger.add(leg);

            // Paw
            const pawGeo = new THREE.BoxGeometry(0.4, 0.2, 0.5);
            const paw = new THREE.Mesh(pawGeo, blackMat);
            paw.position.set(pos.x, 0.1, pos.z);
            tiger.add(paw);
        });

        // 4. Tail
        const tailCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, 1.5, -1.8),
            new THREE.Vector3(0, 2.5, -2.5),
            new THREE.Vector3(0.5, 3.5, -2.5),
            new THREE.Vector3(0.5, 4, -2)
        ]);
