        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Ground
        const groundGeometry = new THREE.PlaneGeometry(100, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x3b7d3b }); // Grass green
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Turtle Construction
        const turtleGroup = new THREE.Group();

        // Materials
        const shellMaterial = new THREE.MeshStandardMaterial({ color: 0x2E8B57 }); // SeaGreen
        const skinMaterial = new THREE.MeshStandardMaterial({ color: 0x8FBC8F }); // DarkSeaGreen
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });

        // Shell (Main Body) - Using a flattened sphere for a dome shape
        const shellGeometry = new THREE.SphereGeometry(1.5, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        const shell = new THREE.Mesh(shellGeometry, shellMaterial);
        shell.position.y = 0.5;
        shell.castShadow = true;
        shell.receiveShadow = true;
        turtleGroup.add(shell);

        // Shell Bottom (Plastron) - A flat cylinder
        const plastronGeometry = new THREE.CylinderGeometry(1.4, 1.4, 0.2, 32);
        const plastron = new THREE.Mesh(plastronGeometry, skinMaterial);
        plastron.position.y = 0.1;
