<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

// Camera
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.appendChild(renderer.domElement);

// Lights
scene.add(new THREE.AmbientLight(0xffffff, 0.4));
const key = new THREE.DirectionalLight(0xffeedd, 2);
key.position.set(3, 5, 4);
scene.add(key);
const fill = new THREE.DirectionalLight(0x8888ff, 0.6);
fill.position.set(-4, 2, -2);
scene.add(fill);

// Vase profile (half-cross-section points)
const pts = [
  new THREE.Vector2(0, 0),
  new THREE.Vector2(0.05, 0),
  new THREE.Vector2(0.6, 0.05),
  new THREE.Vector2(0.85, 0.3),
  new THREE.Vector2(1.0, 0.7),
  new THREE.Vector2(1.05, 1.0),
  new THREE.Vector2(1.0, 1.4),
  new THREE.Vector2(0.85, 1.7),
  new THREE.Vector2(0.65, 1.9),
  new THREE.Vector2(0.55, 2.05),
  new THREE.Vector2(0.58, 2.2),
  new THREE.Vector2(0.65, 2.35),
  new THREE.Vector2(0.7, 2.45),
  new THREE.Vector2(0.7, 2.5),
  new THREE.Vector2(0.68, 2.52),
  new THREE.Vector2(0, 2.52),
].map(p => new THREE.CatmullRomCurve3 ? p : p);

// Actually, LatheGeometry accepts Vector2[] directly
const profile = [
  new THREE.Vector2(0, 0),
  new THREE.Vector2(0.05, 0),
  new THREE.Vector2(0.6, 0.05),
  new THREE.Vector2(0.85, 0.3),
  new THREE.Vector2(1.0, 0.7),
  new THREE.Vector2(1.05, 1.0),
  new THREE.Vector2(1.0, 1.4),
  new THREE.Vector2(0.85, 1.7),
  new THREE.Vector2(0.65, 1.9),
  new THREE.Vector2(0.55, 2.05),
  new THREE.Vector2(0.58, 2.2),
  new THREE.Vector2(0.65, 2.35),
  new THREE.Vector2(0.7, 2.45),
  new THREE.Vector2(0.7, 2.5),
  new THREE.Vector2(0.68, 2.52),
  new THREE.Vector2(0, 2.52),
];

const curve = new THREE.CatmullRomCurve3(profile.map(p => new THREE.Vector3(p.x, p.y, 0)));
const samples = curve.getSpacedPoints(64);

const geometry = new THREE.LatheGeometry(samples, 64);
geometry.computeVertexNormals();

const material = new THREE.MeshStandardMaterial({
  color: 0xc4956a,
  roughness: 0.35,
  metalness: 0.05,
  side: THREE.DoubleSide,
});

const vase = new THREE.Mesh(geometry, material);
scene.add(vase);

// Subtle ground plane
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(3, 64),
  new THREE.MeshStandardMaterial({ color: 0x1a1a2e, roughness: 1 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.2, 0);

// Animate
(function loop() {
  vase.rotation.y += 0.005;
  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(loop);
})();

// Resize
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What this does

- **LatheGeometry** — the vase is built by revolving a 2D profile curve around the Y-axis, the standard approach for vessels
- **CatmullRomCurve3** — the profile points are interpolated into a smooth curve, then sampled 64 times for a clean silhouette
- **Lighting** — a warm key light + cool fill light + ambient give the vase depth and character
- **OrbitControls** — click-drag to rotate, scroll to zoom
- **Auto-rotation** — the vase slowly spins so you can see it immediately

Open the file in any modern browser. No build step needed — Three.js loads from the CDN via an import map.

