      const t = clock.getElapsedTime();

      // Gentle bob
      penguin.position.y = 0.2 + Math.sin(t * 3) * 0.02;
      penguin.rotation.z = Math.sin(t * 1.5) * 0.03;

      // Wheel rotation (visual spin)
      wheels.forEach(w => {
        w.rotation.x = t * 5;
      });

      // Subtle skateboard tilt
      skateboard.rotation.z = Math.sin(t * 2) * 0.02;

      // Snowfall
      const positions = snowflakes.geometry.attributes.position.array;
      for (let i = 0; i < snowflakeCount; i++) {
        positions[i * 3 + 1] -= 0.01;
        if (positions[i * 3 + 1] < 0) positions[i * 3 + 1] = 15;
        positions[i * 3] += Math.sin(t + i) * 0.002;
      }
      snowflakes.geometry.attributes.position.needsUpdate = true;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // --- Resize ---
    window.addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
