        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 1, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeebb, 1.5);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Materials
        const mushroomStemMat = new THREE.MeshStandardMaterial({ color: 0xeecfa1, roughness: 0.8 });
        const mushroomCapMat = new THREE.MeshStandardMaterial({ color: 0xd9381e, roughness: 0.4 });
        const spotMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
        const dragonflyBodyMat = new THREE.MeshStandardMaterial({ color: 0x2288ff, roughness: 0.3, metalness: 0.2 });
        const dragonflyWingMat = new THREE.MeshStandardMaterial({ 
            color: 0xaaddff, 
            transparent: true, 
            opacity: 0.6, 
            side: THREE.DoubleSide,
            roughness: 0.1
        });

        // Mushroom Group
        const mushroom = new THREE.Group();

        // Stem
        const stemGeo = new THREE.CylinderGeometry(0.3, 0.4, 1.5, 16);
        const stem = new THREE.Mesh(stemGeo, mushroomStemMat);
        stem.position.y = 0.75;
        stem.castShadow = true;
        stem.receiveShadow = true;
        mushroom.add(stem);

        // Cap
        const capGeo = new THREE.SphereGeometry(1.2, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        const cap = new THREE.Mesh(capGeo, mushroomCapMat);
        cap.position.y = 1.5;
        cap.castShadow = true;
        cap.receiveShadow = true;
        mushroom.add(cap);

        // Spots on cap
        const spotGeo = new THREE.CircleGeometry(0.15, 16);
        const spotPositions = [
            { x: 0.5, z: 0.5, rotX: -0.5, rotZ: 0.5 },
            { x: -0.6, z: 0.2, rotX: -0.4, rotZ: -0.2 },
            { x: 0.1, z: -0.8, rotX: -0.6, rotZ: 0.1 },
            { x: -0.2, z: 0.7, rotX: -0.3, rotZ: -0.5 },
            { x: 0.8, z: -0.3, rotX: -0.7, rotZ: 0.3 }
        ];

        spotPositions.forEach(pos => {
            const spot = new THREE.Mesh(spotGeo, spotMat);
            // Approximate placement on sphere surface
            const phi = Math.acos(pos.z / 1.2); // rough approximation
            const theta = Math.atan2(pos.x, pos.z);

            // Better manual placement for visual appeal
            spot.position.set(pos.x * 1.1, 1.5 + Math.sqrt(1.2*1.2 - pos.x*pos.x - pos.z*pos.z) * 0.8, pos.z * 1.1);
            spot.lookAt(0, 1.5, 0); // Face center then rotate out? No, lookAt center makes it face in.
            // Let's just position them and rotate to face out roughly
            spot.lookAt(new THREE.Vector3(0, 1.5, 0));
            spot.rotateX(Math.PI); // Face out

            mushroom.add(spot);
        });

        scene.add(mushroom);

        // Dragonfly Group
        const dragonfly = new THREE.Group();

        // Body (Abdomen)
        const bodyGeo = new THREE.CylinderGeometry(0.05, 0.02, 1.2, 8);
        const body = new THREE.Mesh(bodyGeo, dragonflyBodyMat);
        body.rotation.x = Math.PI / 2; // Point along Z
        body.position.z = 0.6;
        body.castShadow = true;
        dragonfly.add(body);

        // Thorax
        const thoraxGeo = new THREE.SphereGeometry(0.12, 16, 16);
        const thorax = new THREE.Mesh(thoraxGeo, dragonflyBodyMat);
        thorax.position.z = 0;
        thorax.scale.set(1, 1, 1.5);
        thorax.castShadow = true;
        dragonfly.add(thorax);

        // Head
        const headGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const head = new THREE.Mesh(headGeo, dragonflyBodyMat);
        head.position.z = -0.2;
        head.castShadow = true;
        dragonfly.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.06, 8, 8);
        const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
        eyeL.position.set(0.08, 0.05, -0.25);
        dragonfly.add(eyeL);
        const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
        eyeR.position.set(-0.08, 0.05, -0.25);
        dragonfly.add(eyeR);

        // Wings
        const wingShape = new THREE.Shape();
        wingShape.moveTo(0, 0);
        wingShape.quadraticCurveTo(0.5, 0.2, 1.0, 0);
        wingShape.quadraticCurveTo(0.5, -0.1, 0, 0);

        const wingGeo = new THREE.ShapeGeometry(wingShape);

        // Left Wing 1 (Front)
        const wing1 = new THREE.Mesh(wingGeo, dragonflyWingMat);
        wing1.position.set(0.15, 0.1, 0.1);
        wing1.rotation.z = -0.2;
        wing1.rotation.x = 0.2;
        wing1.scale.set(1.5, 1.5, 1);
        dragonfly.add(wing1);

        // Right Wing 1 (Front)
        const wing2 = new THREE.Mesh(wingGeo, dragonflyWingMat);
        wing2.position.set(-0.15, 0.1, 0.1);
        wing2.rotation.z = Math.PI + 0.2; // Mirror
        wing2.rotation.x = 0.2;
        wing2.scale.set(1.5, 1.5, 1);
        dragonfly.add(wing2);

        // Left Wing 2 (Back)
        const wing3 = new THREE.Mesh(wingGeo, dragonflyWingMat);
        wing3.position.set(0.15, 0.05, -0.1);
        wing3.rotation.z = -0.1;
        wing3.rotation.x = 0.2;
        wing3.scale.set(1.2, 1.2, 1);
        dragonfly.add(wing3);

        // Right Wing 2 (Back)
        const wing4 = new THREE.Mesh(wingGeo, dragonflyWingMat);
        wing4.position.set(-0.15, 0.05, -0.1);
        wing4.rotation.z = Math.PI + 0.1;
        wing4.rotation.x = 0.2;
        wing4.scale.set(1.2, 1.2, 1);
        dragonfly.add(wing4);

        // Position Dragonfly on Mushroom
        // Mushroom cap top is roughly at y=1.5, radius 1.2
        // Place it slightly off center
        dragonfly.position.set(0.3, 2.4, 0.3);
        dragonfly.rotation.x = -0.5; // Tilt down slightly
        dragonfly.rotation.z = 0.2;  // Angle slightly

        scene.add(dragonfly);

        // Ground Plane (optional, for shadows)
        const planeGeo = new THREE.PlaneGeometry(20, 20);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Subtle wing flutter
            const time = Date.now() * 0.01;
            wing1.rotation.z = -0.2 + Math.sin(time) * 0.1;
            wing2.rotation.z = Math.PI + 0.2 - Math.sin(time) * 0.1;
            wing3.rotation.z = -0.1 + Math.sin(time + 1) * 0.1;
            wing4.rotation.z = Math.PI + 0.1 - Math.sin(time + 1) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
