moonLight.shadow.camera.far = 100;
scene.add(moonLight);

const hemiLight = new THREE.HemisphereLight(0x446688, 0x222233, 0.4);
scene.add(hemiLight);

// --- Ocean ---
const oceanGeo = new THREE.PlaneGeometry(300, 300, 128, 128);
const oceanMat = new THREE.MeshStandardMaterial({
  color: 0x0a2a3a,
  roughness: 0.15,
  metalness: 0.3,
  transparent: true,
  opacity: 0.9,
});
const ocean = new THREE.Mesh(oceanGeo, oceanMat);
ocean.rotation.x = -Math.PI / 2;
ocean.position.y = -2;
ocean.receiveShadow = true;
scene.add(ocean);

// --- Cliff ---
const cliffShape = new THREE.Shape();
cliffShape.moveTo(-18, 0);
cliffShape.lineTo(-16, 8);
cliffShape.lineTo(-14, 14);
cliffShape.lineTo(-10, 18);
cliffShape.lineTo(-4, 20);
cliffShape.lineTo(4, 20);
cliffShape.lineTo(10, 18);
cliffShape.lineTo(14, 14);
cliffShape.lineTo(16, 8);
cliffShape.lineTo(18, 0);
cliffShape.lineTo(-18, 0);

const cliffGeo = new THREE.ExtrudeGeometry(cliffShape, {
  depth: 24,
  bevelEnabled: true,
  bevelThickness: 1,
  bevelSize: 1,
  bevelSegments: 2,
});
cliffGeo.translate(0, 0, -12);

const cliffMat = new THREE.MeshStandardMaterial({
  color: 0x3a3a3a,
  roughness: 0.95,
  metalness: 0.05,
  flatShading: true,
});
const cliff = new THREE.Mesh(cliffGeo, cliffMat);
cliff.receiveShadow = true;
cliff.castShadow = true;
scene.add(cliff);

// Cliff top grass/rock patches
for (let i = 0; i < 15; i++) {
  const s = 0.5 + Math.random() * 2;
  const patch = new THREE.Mesh(
    new THREE.SphereGeometry(s, 6, 4),
    new THREE.MeshStandardMaterial({
      color: Math.random() > 0.5 ? 0x2d4a2d : 0x4a4a4a,
      roughness: 1,
      flatShading: true,
    })
  );
  patch.position.set(
    (Math.random() - 0.5) * 20,
    19 + Math.random() * 2,
    (Math.random() - 0.5) * 16
  );
  patch.scale.y = 0.3;
  patch.castShadow = true;
  scene.add(patch);
}

// --- Lighthouse Tower ---
const towerGroup = new THREE.Group();
towerGroup.position.set(0, 20, 0);

const towerMat = new THREE.MeshStandardMaterial({
