// Spotlight for beam effect
const spotLight = new THREE.SpotLight(0xffdd66, 20, 80, Math.PI / 6, 0.5, 1);
spotLight.position.set(0, 17, 0);
spotLight.target.position.set(0, 17, 40);
scene.add(spotLight);
scene.add(spotLight.target);

const spotLight2 = spotLight.clone();
spotLight2.target.position.set(0, 17, -40);
scene.add(spotLight2);
