// --- Small buildings ---
function createBuilding(x, z, w, h, d) {
  const group = new THREE.Group();
  const walls = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshStandardMaterial({ color: 0xd4c4a8, roughness: 0.9 })
  );
  walls.position.y = h / 2;
  walls.castShadow = true;
  walls.receiveShadow = true;
  group.add(walls);

  const roofMesh = new THREE.Mesh(
    new THREE.ConeGeometry(Math.max(w, d) * 0.75, h * 0.5, 4),
    new THREE.MeshStandardMaterial({ color: 0x8b4513, roughness: 0.8 })
  );
  roofMesh.position.y = h + h * 0.25;
  roofMesh.rotation.y = Math.PI / 4;
  roofMesh.castShadow = true;
  group.add(roofMesh);

  group.position.set(x, 20, z);
  scene.add(group);
}

createBuilding(6, 2, 2.5, 3, 2);
createBuilding(-7, 1, 2, 2.5, 2.5);

