  const phi = Math.random() * Math.PI * 0.45;
  const r = 200;
  starsPos.push(
    r * Math.sin(phi) * Math.cos(theta),
    r * Math.cos(phi) + 30,
    r * Math.sin(phi) * Math.sin(theta)
  );
}
starsGeo.setAttribute('position', new THREE.Float32BufferAttribute(starsPos, 3));
const starsMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.5, sizeAttenuation: true });
scene.add(new THREE.Points(starsGeo, starsMat));

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Rotate light beam
  const beamAngle = t * 0.5;
  beam.rotation.y = beamAngle;
  beam2.rotation.y = beamAngle;
  spotLight.target.position.set(Math.sin(beamAngle) * 40, 17, Math.cos(beamAngle) * 40);
