  // Flicker light
  lighthouseLight.intensity = 15 + Math.sin(t * 3) * 2;
  glassMat.emissiveIntensity = 0.8 + Math.sin(t * 3) * 0.2;

  // Animate ocean waves
  const pos = oceanGeo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const wave = Math.sin(x * 0.05 + t * 0.8) * 0.8 +
                 Math.sin(y * 0.08 + t * 0.6) * 0.5 +
                 Math.sin((x + y) * 0.03 + t * 1.2) * 0.4;
    pos.setZ(i, wave);
  }
  pos.needsUpdate = true;
  oceanGeo.computeVertexNormals();

  controls.update();
  renderer.render(scene, camera);
}

animate();

