        violinCase.add(body);

        // Top Handle
        const handleGroup = new THREE.Group();

        // Handle Grip
        const gripGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.6, 16);
        gripGeo.rotateZ(Math.PI / 2);
        const grip = new THREE.Mesh(gripGeo, leatherMaterial);
        grip.position.y = 0.25;
        grip.castShadow = true;
        handleGroup.add(grip);

        // Handle Mounts
        const mountGeo = new THREE.BoxGeometry(0.1, 0.15, 0.1);
        const mountL = new THREE.Mesh(mountGeo, metalMaterial);
        mountL.position.set(-0.25, 0.2, 0);
        handleGroup.add(mountL);

        const mountR = new THREE.Mesh(mountGeo, metalMaterial);
        mountR.position.set(0.25, 0.2, 0);
        handleGroup.add(mountR);

        // Handle Arch
        const archCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(-0.25, 0.2, 0),
            new THREE.Vector3(-0.3, 0.5, 0),
            new THREE.Vector3(0.3, 0.5, 0),
            new THREE.Vector3(0.25, 0.2, 0)
        ]);
        const archGeo = new THREE.TubeGeometry(archCurve, 20, 0.04, 8, false);
        const arch = new THREE.Mesh(archGeo, metalMaterial);
        arch.castShadow = true;
        handleGroup.add(arch);

        violinCase.add(handleGroup);

        // Latch / Clasp
        const latchGroup = new THREE.Group();
        const latchBaseGeo = new THREE.BoxGeometry(0.3, 0.1, 0.1);
        const latchBase = new THREE.Mesh(latchBaseGeo, metalMaterial);
        latchBase.position.set(0, 0.2, 1.75); // Front of case
        latchGroup.add(latchBase);

        const latchHookGeo = new THREE.TorusGeometry(0.08, 0.02, 8, 16, Math.PI);
        const latchHook = new THREE.Mesh(latchHookGeo, metalMaterial);
        latchHook.rotation.z = Math.PI / 2;
        latchHook.position.set(0, 0.2, 1.8);
        latchGroup.add(latchHook);

        violinCase.add(latchGroup);

        // Corner Protectors
        const cornerGeo = new THREE.SphereGeometry(0.12, 16, 16);
        const positions = [
            [-0.5, -0.15, 1.6], [0.5, -0.15, 1.6],
            [-0.5, -0.15, -1.6], [0.5, -0.15, -1.6]
        ];

        positions.forEach(pos => {
            const corner = new THREE.Mesh(cornerGeo, metalMaterial);
            corner.position.set(...pos);
            corner.castShadow = true;
            violinCase.add(corner);
        });

        // Add a subtle "Violin" shape indentation on top (simplified)
        const indentGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.05, 32);
        const indentMat = new THREE.MeshStandardMaterial({ color: 0x050505, roughness: 0.9 });
        const indent = new THREE.Mesh(indentGeo, indentMat);
        indent.position.set(0, 0.21, 0.5);
        indent.scale.set(1, 1, 2.5);
        violinCase.add(indent);

        scene.add(violinCase);

        // Floor (Shadow Catcher)
        const planeGeometry = new THREE.PlaneGeometry(50, 50);
        const planeMaterial = new THREE.ShadowMaterial({ opacity: 0.3 });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -0.5;
        plane.receiveShadow = true;
        scene.add(plane);

        // Remove loading text
        document.getElementById('loading').style.opacity = 0;
        setTimeout(() => document.getElementById('loading').remove(), 500);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation if not interacting
            // violinCase.rotation.y += 0.002;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
