```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hot Air Balloon</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ── Scene Setup ──
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 1000);
camera.position.set(0, 5, 18);
camera.lookAt(0, 4, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

// ── Sky Gradient ──
const skyGeo = new THREE.SphereGeometry(200, 32, 32);
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  uniforms: {
    topColor: { value: new THREE.Color(0x1a0533) },
    midColor: { value: new THREE.Color(0xff6b35) },
    bottomColor: { value: new THREE.Color(0xffd166) }
  },
  vertexShader: `
    varying vec3 vWorldPos;
    void main() {
      vec4 wp = modelMatrix * vec4(position, 1.0);
      vWorldPos = wp.xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 topColor, midColor, bottomColor;
    varying vec3 vWorldPos;
    void main() {
      float h = normalize(vWorldPos).y;
      vec3 col = mix(bottomColor, midColor, smoothstep(-0.2, 0.3, h));
      col = mix(col, topColor, smoothstep(0.3, 1.0, h));
      gl_FragColor = vec4(col, 1.0);
    }
  `
});
scene.add(new THREE.Mesh(skyGeo, skyMat));

// ── Lights ──
scene.add(new THREE.AmbientLight(0xffeedd, 0.6));
const sun = new THREE.DirectionalLight(0xffaa44, 2.5);
sun.position.set(10, 20, 10);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
scene.add(sun);
const fill = new THREE.DirectionalLight(0x4488ff, 0.4);
fill.position.set(-5, 3, -5);
scene.add(fill);

// ── Balloon Texture (striped) ──
function makeBalloonTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  const colors = ['#e63946', '#f4a261', '#2a9d8f', '#264653', '#e9c46a', '#e76f51'];
  const stripH = c.height / colors.length;
  colors.forEach((col, i) => {
    ctx.fillStyle = col;
    ctx.fillRect(0, i * stripH, c.width, stripH + 1);
  });
  // subtle noise
  const img = ctx.getImageData(0, 0, c.width, c.height);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (Math.random() - 0.5) * 15;
    img.data[i] += n; img.data[i+1] += n; img.data[i+2] += n;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

// ── Balloon Envelope ──
const balloonGroup = new THREE.Group();
scene.add(balloonGroup);

const envelopeGeo = new THREE.SphereGeometry(3, 64, 64, 0, Math.PI * 2, 0, Math.PI * 0.75);
const envelopeMat = new THREE.MeshStandardMaterial({
  map: makeBalloonTexture(),
  roughness: 0.6,
  metalness: 0.05,
  side: THREE.DoubleSide
});
const envelope = new THREE.Mesh(envelopeGeo, envelopeMat);
envelope.position.y = 5;
envelope.castShadow = true;
balloonGroup.add(envelope);

// ── Burner Flame ──
const flameGeo = new THREE.ConeGeometry(0.25, 0.8, 8);
const flameMat = new THREE.MeshBasicMaterial({ color: 0xff6600, transparent: true, opacity: 0.85 });
const flame = new THREE.Mesh(flameGeo, flameMat);
flame.position.y = 2.15;
flame.rotation.x = Math.PI;
balloonGroup.add(flame);

const flameGlow = new THREE.PointLight(0xff6600, 3, 6);
flameGlow.position.copy(flame.position);
balloonGroup.add(flameGlow);

// ── Burner Ring ──
const ringGeo = new THREE.TorusGeometry(0.35, 0.04, 8, 24);
const ringMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.9, roughness: 0.3 });
const ring = new THREE.Mesh(ringGeo, ringMat);
ring.position.y = 1.9;
ring.rotation.x = Math.PI / 2;
balloonGroup.add(ring);

// ── Basket ──
const basketGeo = new THREE.BoxGeometry(1.2, 1.0, 1.2);
const basketMat = new THREE.MeshStandardMaterial({ color: 0x8B5E3C, roughness: 0.9 });
const basket = new THREE.Mesh(basketGeo, basketMat);
basket.position.y = 0.5;
basket.castShadow = true;
balloonGroup.add(basket);

// basket weave lines
for (let i = 0; i < 5; i++) {
  const lineGeo = new THREE.BoxGeometry(1.22, 0.03, 1.22);
  const lineMat = new THREE.MeshStandardMaterial({ color: 0x6B3E1C });
  const line = new THREE.Mesh(lineGeo, lineMat);
  line.position.y = 0.1 + i * 0.2;
  balloonGroup.add(line);
}

// ── Ropes ──
const ropeMat = new THREE.LineBasicMaterial({ color: 0x555555 });
const corners = [[-0.55, -0.55], [0.55, -0.55], [-0.55, 0.55], [0.55, 0.55]];
corners.forEach(([x, z]) => {
  const pts = [
    new THREE.Vector3(x, 1.0, z),
    new THREE.Vector3(x * 0.6, 2.0, z * 0.6),
    new THREE.Vector3(x * 0.4, 2.5, z * 0.4)
  ];
  const curve = new THREE.CatmullRomCurve3(pts);
  const geo = new THREE.TubeGeometry(curve, 8, 0.015, 4, false);
  const mat = new THREE.MeshStandardMaterial({ color: 0x777777 });
  balloonGroup.add(new THREE.Mesh(geo, mat));
});

// ── Ground ──
const groundGeo = new THREE.CircleGeometry(120, 64);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x2d5a1e, roughness: 1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -2;
ground.receiveShadow = true;
scene.add(ground);

// ── Clouds ──
function makeCloud(y, z, s) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.7, roughness: 1 });
  for (let i = 0; i < 5; i++) {
    const r = (0.8 + Math.random() * 1.2) * s;
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 16, 16), mat);
    m.position.set((Math.random() - 0.5) * 3 * s, (Math.random() - 0.5) * 0.8 * s, (Math.random() - 0.5) * 1.5 * s);
    g.add(m);
  }
  g.position.set((Math.random() - 0.5) * 80, y, z);
  return g;
}

const clouds = [];
for (let i = 0; i < 12; i++) {
  const c = makeCloud(3 + Math.random() * 15, -20 - Math.random() * 60, 0.5 + Math.random() * 1);
  scene.add(c);
  clouds.push(c);
}

// ── Stars ──
const starGeo = new THREE.BufferGeometry();
const starPos = [];
for (let i = 0; i < 500; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(Math.random() * 0.6 + 0.4);
  const r = 150;
  starPos.push(r * Math.sin(phi) * Math.cos(theta), r * Math.cos(phi), r * Math.sin(phi) * Math.sin(theta));
}
starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
scene.add(new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 0.5, transparent: true, opacity: 0.6 })));

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Float
  balloonGroup.position.y = Math.sin(t * 0.5) * 0.5;
  balloonGroup.rotation.z = Math.sin(t * 0.3) * 0.03;
  balloonGroup.rotation.x = Math.sin(t * 0.4) * 0.02;

  // Flame flicker
  flame.scale.setScalar(0.8 + Math.sin(t * 12) * 0.2 + Math.sin(t * 17) * 0.1);
  flameGlow.intensity = 2 + Math.sin(t * 10) * 1.5;

  // Clouds drift
  clouds.forEach((c, i) => {
    c.position.x += 0.003 * (i % 3 + 1);
    if (c.position.x > 60) c.position.x = -60;
  });

  // Camera gentle sway
  camera.position.x = Math.sin(t * 0.15) * 2;
  camera.position.y = 5 + Math.sin(t * 0.2) * 0.5;
  camera.lookAt(0, 4, 0);

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**Features included:**

- **Striped balloon envelope** — a sphere with a canvas-generated 6-color striped texture
- **Wicker basket** with horizontal weave lines
- **Burner** with a flickering orange flame and dynamic point light
- **Support ropes** connecting basket to envelope via curved tubes
- **Sunset sky** — a gradient shader dome (deep purple → orange → gold)
- **Drifting clouds** made from clustered spheres
- **Stars** in the upper sky
- **Gentle animation** — floating, swaying, flame flicker, camera sway
- **Shadows** and ACES filmic tone mapping for a cinematic look

Just save it as `index.html` and open in any modern browser.

