        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        scene.add(dirLight);

        // Ground
        const groundGeometry = new THREE.PlaneGeometry(100, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x4caf50 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Windmill Group
        const windmill = new THREE.Group();

        // Tower (Cylinder)
        const towerGeo = new THREE.CylinderGeometry(2, 3, 10, 16);
        const towerMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const tower = new THREE.Mesh(towerGeo, towerMat);
        tower.position.y = 5;
        tower.castShadow = true;
        tower.receiveShadow = true;
        windmill.add(tower);

        // Roof (Cone)
        const roofGeo = new THREE.ConeGeometry(3.2, 3, 16);
        const roofMat = new THREE.MeshStandardMaterial({ color: 0x8b4513 });
        const roof = new THREE.Mesh(roofGeo, roofMat);
        roof.position.y = 11.5;
        roof.castShadow = true;
        windmill.add(roof);

        // Door
        const doorGeo = new THREE.PlaneGeometry(1.5, 2.5);
        const doorMat = new THREE.MeshStandardMaterial({ color: 0x5c4033 });
        const door = new THREE.Mesh(doorGeo, doorMat);
        door.position.set(0, 1.25, 2.9);
        windmill.add(door);

        // Blades Group
        const bladesGroup = new THREE.Group();
        bladesGroup.position.set(0, 8, 3.1); // Slightly in front of tower

        const bladeGeo = new THREE.BoxGeometry(1, 8, 0.2);
        const bladeMat = new THREE.MeshStandardMaterial({ color: 0xffffff });

        // Create 4 blades
        for (let i = 0; i < 4; i++) {
            const blade = new THREE.Mesh(bladeGeo, bladeMat);
            blade.position.y = 4; // Offset so it rotates around center
            blade.castShadow = true;

            // Create a pivot for each blade to rotate around the center
            const pivot = new THREE.Group();
            pivot.add(blade);
            pivot.rotation.z = (Math.PI / 2) * i;
            bladesGroup.add(pivot);
        }

        // Hub
        const hubGeo = new THREE.SphereGeometry(0.5, 16, 16);
        const hubMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const hub = new THREE.Mesh(hubGeo, hubMat);
        bladesGroup.add(hub);

        windmill.add(bladesGroup);
        scene.add(windmill);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Rotate blades
            bladesGroup.rotation.z += 0.02;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
