            text-shadow: 1px 1px 2px black;
        }
    </style>
</head>
<body>

    <div id="ui-container">
        <button id="open-btn">✦ Open the Chest ✦</button>
    </div>
    <div id="instructions">Drag to rotate · Scroll to zoom</div>
    <div id="canvas-container"></div>

    <!-- Import Three.js as a module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const container = document.getElementById('canvas-container');
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a1a);
        scene.fog = new THREE.Fog(0x1a1a1a, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 4, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        container.appendChild(renderer.domElement);

        // --- Controls ---
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.maxPolarAngle = Math.PI / 2 - 0.1; // Prevent going below ground
        controls.minDistance = 3;
        controls.maxDistance = 15;

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 0.5, 10);
        pointLight.position.set(0, 2, 0);
        scene.add(pointLight);

        // --- Materials ---
        const woodMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x5c4033, 
            roughness: 0.8,
            metalness: 0.1
        });

        const darkWoodMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3e2723, 
            roughness: 0.9 
        });

        const metalMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xd4af37, // Gold
            roughness: 0.3, 
            metalness: 0.8 
        });

        const lockMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x888888, 
            roughness: 0.4, 
            metalness: 0.9 
        });

        const gemMaterial = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            emissive: 0xff0000,
            emissiveIntensity: 0.5,
            roughness: 0.1,
            metalness: 0.1
        });

        // --- Chest Construction ---
        const chestGroup = new THREE.Group();
        scene.add(chestGroup);

        // Dimensions
        const width = 3;
        const height = 1.5;
        const depth = 2;
        const lidHeight = 1;

        // 1. Base Box
        const baseGeo = new THREE.BoxGeometry(width, height, depth);
        const base = new THREE.Mesh(baseGeo, woodMaterial);
        base.position.y = height / 2;
        base.castShadow = true;
        base.receiveShadow = true;
        chestGroup.add(base);

        // 2. Lid Group (Pivot point at the back edge)
        const lidPivot = new THREE.Group();
        lidPivot.position.set(0, height, -depth / 2); // Back edge of the base
        chestGroup.add(lidPivot);

        // Lid Box (offset so pivot is at its bottom-back edge)
        const lidGeo = new THREE.BoxGeometry(width, lidHeight, depth);
        const lid = new THREE.Mesh(lidGeo, woodMaterial);
        lid.position.set(0, lidHeight / 2, depth / 2); // Center the lid relative to pivot
        lid.castShadow = true;
        lid.receiveShadow = true;
        lidPivot.add(lid);

        // 3. Metal Bands (Base)
        function createBand(w, h, d, x, y, z) {
            const geo = new THREE.BoxGeometry(w, h, d);
            const mesh = new THREE.Mesh(geo, metalMaterial);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            return mesh;
        }

        // Vertical bands on base
        chestGroup.add(createBand(0.2, height + 0.1, depth + 0.1, -width/2 + 0.4, height/2, 0));
        chestGroup.add(createBand(0.2, height + 0.1, depth + 0.1, width/2 - 0.4, height/2, 0));

        // Horizontal band on base
        chestGroup.add(createBand(width + 0.1, 0.2, depth + 0.1, 0, height/2, 0));

        // 4. Metal Bands (Lid)
        // Vertical bands on lid
        lidPivot.add(createBand(0.2, lidHeight + 0.1, depth + 0.1, -width/2 + 0.4, lidHeight/2, depth/2));
        lidPivot.add(createBand(0.2, lidHeight + 0.1, depth + 0.1, width/2 - 0.4, lidHeight/2, depth/2));

        // Horizontal band on lid
        lidPivot.add(createBand(width + 0.1, 0.2, depth + 0.1, 0, lidHeight/2, depth/2));

        // 5. Lock Mechanism
        const lockGroup = new THREE.Group();
        lockGroup.position.set(0, height, depth / 2 + 0.01); // Front center of base
        chestGroup.add(lockGroup);

        // Lock plate
        const plateGeo = new THREE.BoxGeometry(0.6, 0.8, 0.1);
        const plate = new THREE.Mesh(plateGeo, metalMaterial);
        lockGroup.add(plate);

        // Keyhole
        const keyholeGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.15, 16);
        const keyhole = new THREE.Mesh(keyholeGeo, new THREE.MeshStandardMaterial({ color: 0x111111 }));
        keyhole.rotation.x = Math.PI / 2;
        keyhole.position.z = 0.06;
        lockGroup.add(keyhole);

        // 6. Treasure (Inside)
        // We need a container inside the base that is hidden until opened
        const treasureGroup = new THREE.Group();
        treasureGroup.position.set(0, height - 0.2, 0);
        chestGroup.add(treasureGroup);

        // Gold coins
        const coinGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.05, 16);
        for(let i=0; i<15; i++) {
            const coin = new THREE.Mesh(coinGeo, metalMaterial);
            coin.position.set(
                (Math.random() - 0.5) * 2,
                Math.random() * 0.5,
                (Math.random() - 0.5) * 1.5
            );
            coin.rotation.x = Math.random() * Math.PI;
            coin.rotation.y = Math.random() * Math.PI;
            treasureGroup.add(coin);
        }

        // Gem
        const gemGeo = new THREE.OctahedronGeometry(0.4);
        const gem = new THREE.Mesh(gemGeo, gemMaterial);
        gem.position.set(0, 0.6, 0);
        treasureGroup.add(gem);

        // --- Animation State ---
        let isOpen = false;
        let targetRotation = 0;
        const openAngle = -Math.PI / 1.8; // How far it opens

        // --- Interaction ---
        const btn = document.getElementById('open-btn');
        btn.addEventListener('click', () => {
            isOpen = !isOpen;
            targetRotation = isOpen ? openAngle : 0;
            btn.textContent = isOpen ? "✦ Close the Chest ✦" : "✦ Open the Chest ✦";

            // Simple light effect when opening
            if(isOpen) {
                pointLight.intensity = 2;
                pointLight.color.setHex(0xffaa00);
            } else {
                pointLight.intensity = 0.5;
                pointLight.color.setHex(0xffaa00);
            }
        });

        // --- Ground Plane ---
        const planeGeo = new THREE.PlaneGeometry(50, 50);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            // Smooth lid animation
            const currentRot = lidPivot.rotation.x;
            const diff = targetRotation - currentRot;

            if (Math.abs(diff) > 0.001) {
                lidPivot.rotation.x += diff * 0.05;
            }

            // Gem floating animation
            if (isOpen) {
                gem.position.y = 0.6 + Math.sin(Date.now() * 0.003) * 0.1;
                gem.rotation.y += 0.02;
            } else {
                gem.position.y = 0.6;
            }

            controls.update();
            renderer.render(scene, camera);
        }

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
