        const darkPinkMaterial = new THREE.MeshStandardMaterial({ color: 0xff1493 }); // Darker Pink for details
        const blackMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // Body (Oval shape)
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        const body = new THREE.Mesh(bodyGeo, pinkMaterial);
        body.scale.set(1, 0.8, 1.3);
        body.castShadow = true;
