        const leg2 = new THREE.Mesh(legGeo, pinkMaterial);
        leg2.position.set(-0.2, -1.5, 0.2);
        leg2.castShadow = true;
        flamingoGroup.add(leg2);

        // Tail feathers (simple cones)
