        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0xffaa00, 5);
        spotLight.position.set(0, 5, 2);
        spotLight.angle = Math.PI / 6;
        spotLight.penumbra = 0.5;
        scene.add(spotLight);

        // Materials
        const woodMaterial = new THREE.MeshStandardMaterial({ color: 0x5c3a21, roughness: 0.7 });
        const darkWoodMaterial = new THREE.MeshStandardMaterial({ color: 0x3e2716, roughness: 0.8 });
        const goldMaterial = new THREE.MeshStandardMaterial({ color: 0xffd700, metalness: 0.8, roughness: 0.2 });
        const glassMaterial = new THREE.MeshStandardMaterial({ color: 0x88ccff, transparent: true, opacity: 0.3, roughness: 0.1 });
        const faceMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const handMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // Clock Group
        const clockGroup = new THREE.Group();

        // 1. Main Body (The long part)
        const bodyGeo = new THREE.BoxGeometry(1.2, 3.5, 0.8);
        const body = new THREE.Mesh(bodyGeo, woodMaterial);
        body.position.y = 1.75;
        body.castShadow = true;
        body.receiveShadow = true;
        clockGroup.add(body);

        // 2. Top Hood (The top part)
        const hoodGeo = new THREE.BoxGeometry(1.4, 1.2, 1.0);
        const hood = new THREE.Mesh(hoodGeo, woodMaterial);
        hood.position.y = 3.6;
        hood.castShadow = true;
        clockGroup.add(hood);

        // 3. Pediment (The very top curved bit - simplified as a box for minimalism)
        const pedimentGeo = new THREE.BoxGeometry(1.4, 0.4, 1.0);
        const pediment = new THREE.Mesh(pedimentGeo, darkWoodMaterial);
        pediment.position.y = 4.3;
        clockGroup.add(pediment);

