        const faceGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.1, 32);
        const face = new THREE.Mesh(faceGeo, faceMaterial);
        face.rotation.x = Math.PI / 2;
        face.position.set(0, 3.6, 0.51);
