        const hourHand = new THREE.Mesh(hourHandGeo, handMaterial);
        hourHand.position.set(0, 3.6, 0.58);
        hourHand.rotation.z = -Math.PI / 4; // Set time roughly
        clockGroup.add(hourHand);

        const minuteHandGeo = new THREE.BoxGeometry(0.03, 0.35, 0.02);
        const minuteHand = new THREE.Mesh(minuteHandGeo, handMaterial);
        minuteHand.position.set(0, 3.6, 0.59);
        minuteHand.rotation.z = Math.PI / 3;
        clockGroup.add(minuteHand);

        // 6. Pendulum
        const pendulumRodGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.5, 8);
        const pendulumRod = new THREE.Mesh(pendulumRodGeo, goldMaterial);
        pendulumRod.position.set(0, 2.2, 0.45);
        clockGroup.add(pendulumRod);

        const bobGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const bob = new THREE.Mesh(bobGeo, goldMaterial);
        bob.position.set(0, 1.4, 0.45);
        clockGroup.add(bob);

        // 7. Weights
