        const weight1 = new THREE.Mesh(weightGeo, goldMaterial);
        weight1.position.set(-0.3, 1.5, 0.45);
        clockGroup.add(weight1);

        const weight2 = new THREE.Mesh(weightGeo, goldMaterial);
        weight2.position.set(0.3, 1.8, 0.45);
        clockGroup.add(weight2);

        // 8. Glass Door (Front of body)
        const glassGeo = new THREE.PlaneGeometry(1.0, 2.5);
        const glass = new THREE.Mesh(glassGeo, glassMaterial);
        glass.position.set(0, 1.8, 0.41);
        clockGroup.add(glass);

        // 9. Base
        const baseGeo = new THREE.BoxGeometry(1.4, 0.2, 1.0);
        const base = new THREE.Mesh(baseGeo, darkWoodMaterial);
        base.position.y = 0.1;
        base.castShadow = true;
        clockGroup.add(base);

        scene.add(clockGroup);

        // Floor
        const floorGeo = new THREE.PlaneGeometry(20, 20);
        const floorMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Swing Pendulum
            const swingAngle = Math.sin(time * 2) * 0.2;
            pendulumRod.rotation.z = swingAngle;
            bob.position.x = Math.sin(swingAngle) * 1.5; // Approximate arc

            // Move Weights slightly with pendulum
            weight1.position.x = -0.3 + Math.sin(swingAngle) * 0.1;
            weight2.position.x = 0.3 + Math.sin(swingAngle) * 0.1;

            // Rotate Minute Hand slowly
            minuteHand.rotation.z = -time * 0.5;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
