</head>
<body>
<div id="info">🛰️ Drag to orbit · Scroll to zoom</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ── Scene ─────────────────────────────────────────── */
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, .1, 1000);
camera.position.set(5, 4, 7);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

/* ── Controls ──────────────────────────────────────── */
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = .06;

/* ── Lighting ──────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0x334466, 1.5));
const sun = new THREE.DirectionalLight(0xfff4e0, 4);
sun.position.set(10, 8, 5);
scene.add(sun);
const rim = new THREE.DirectionalLight(0x4488ff, 1);
rim.position.set(-6, -2, -4);
scene.add(rim);

/* ── Materials ─────────────────────────────────────── */
const bodyMat   = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: .35, metalness: .7 });
const panelMat  = new THREE.MeshStandardMaterial({ color: 0x1a2a5a, roughness: .2, metalness: .4 });
const goldMat   = new THREE.MeshStandardMaterial({ color: 0xd4a017, roughness: .4, metalness: .6 });
const dishMat   = new THREE.MeshStandardMaterial({ color: 0xeeeeee, roughness: .3, metalness: .8 });
const antennaMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: .5, metalness: .9 });
const redMat    = new THREE.MeshStandardMaterial({ color: 0xcc2222, roughness: .5, metalness: .3 });
const darkMat   = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: .6, metalness: .5 });

/* ── Satellite Group ───────────────────────────────── */
const satellite = new THREE.Group();

// Central bus
const bus = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.2, 1.4), bodyMat);
satellite.add(bus);

// Top gold foil layer
const topFoil = new THREE.Mesh(new THREE.BoxGeometry(1.45, 0.04, 1.45), goldMat);
topFoil.position.y = 0.62;
satellite.add(topFoil);

// Bottom gold foil layer
const botFoil = new THREE.Mesh(new THREE.BoxGeometry(1.45, 0.04, 1.45), goldMat);
botFoil.position.y = -0.62;
satellite.add(botFoil);

// Side panels (solar wings)
function makePanel(x) {
  const group = new THREE.Group();

  // Support strut
  const strut = new THREE.Mesh(new THREE.CylinderGeometry(.04, .04, 1.6, 8), antennaMat);
  strut.rotation.z = Math.PI / 2;
  strut.position.x = x * 0.8;
  group.add(strut);

  // Panel body
  const panel = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.06, 1.0), panelMat);
  panel.position.x = x * 2.0;
  group.add(panel);

  // Grid lines on panel
  const gridGeo = new THREE.EdgesGeometry(new THREE.BoxGeometry(2.4, 0.06, 1.0));
  const gridMat = new THREE.LineBasicMaterial({ color: 0x3355aa, transparent: true, opacity: 0.5 });
  const grid = new THREE.LineSegments(gridGeo, gridMat);
  grid.position.copy(panel.position);
  group.add(grid);

  // Panel frame
  const frame = new THREE.Mesh(new THREE.BoxGeometry(2.44, 0.08, 1.04), darkMat);
  frame.position.copy(panel.position);
  frame.position.y -= 0.01;
  group.add(frame);

  return group;
}

satellite.add(makePanel(1));
satellite.add(makePanel(-1));

// Dish antenna
const dish = new THREE.Mesh(new THREE.SphereGeometry(0.5, 32, 16, 0, Math.PI * 2, 0, Math.PI * 0.35), dishMat);
dish.position.set(0, 0.9, 0);
dish.rotation.x = Math.PI;
satellite.add(dish);

// Dish feed pole
const feedPole = new THREE.Mesh(new THREE.CylinderGeometry(.025, .025, .55, 8), antennaMat);
feedPole.position.set(0, 1.15, 0);
satellite.add(feedPole);

// Feed tip
const feedTip = new THREE.Mesh(new THREE.SphereGeometry(.06, 16, 16), redMat);
feedTip.position.set(0, 1.45, 0);
satellite.add(feedTip);

// Small antennas
for (const [x, z] of [[.5, .5], [-.5, .5], [.5, -.5], [-.5, -.5]]) {
  const rod = new THREE.Mesh(new THREE.CylinderGeometry(.015, .015, .7, 8), antennaMat);
  rod.position.set(x, 1.0, z);
  satellite.add(rod);
  const tip = new THREE.Mesh(new THREE.SphereGeometry(.03, 8, 8), redMat);
  tip.position.set(x, 1.35, z);
  satellite.add(tip);
}

// Thruster nozzles
for (const [x, z] of [[.4, .4], [-.4, .4], [.4, -.4], [-.4, -.4]]) {
  const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(.08, .12, .15, 12), darkMat);
  nozzle.position.set(x, -0.7, z);
  satellite.add(nozzle);
}

// Status light (emissive)
const statusLight = new THREE.Mesh(
  new THREE.SphereGeometry(.04, 12, 12),
  new THREE.MeshStandardMaterial({ color: 0x00ff44, emissive: 0x00ff44, emissiveIntensity: 2 })
);
statusLight.position.set(0, 0.65, .55);
satellite.add(statusLight);

scene.add(satellite);

/* ── Starfield ─────────────────────────────────────── */
const starCount = 2000;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
const starCol = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  const r = 80 + Math.random() * 120;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  starPos[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
  starPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  starPos[i * 3 + 2] = r * Math.cos(phi);
  const brightness = .6 + Math.random() * .4;
  starCol[i * 3]     = brightness;
  starCol[i * 3 + 1] = brightness;
  starCol[i * 3 + 2] = brightness + Math.random() * .1;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
starGeo.setAttribute('color', new THREE.BufferAttribute(starCol, 3));
const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ size: .3, vertexColors: true, sizeAttenuation: true }));
scene.add(stars);

/* ── Animation ─────────────────────────────────────── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle tumble
  satellite.rotation.y = t * .25;
  satellite.rotation.x = Math.sin(t * .15) * .08;
  satellite.rotation.z = Math.cos(t * .12) * .04;

  // Blink status light
  statusLight.material.emissiveIntensity = 1.5 + Math.sin(t * 4) * .8;

  controls.update();
  renderer.render(scene, camera);
}
animate();

/* ── Resize ────────────────────────────────────────── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
