renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 4;
controls.maxDistance = 20;
controls.update();

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0x8888cc, 0.6);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1.8);
dirLight.position.set(5, 10, 7);
scene.add(dirLight);

const dirLight2 = new THREE.DirectionalLight(0xffeedd, 0.9);
dirLight2.position.set(-4, 6, -5);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xff6699, 1.5, 15);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

const rimLight = new THREE.PointLight(0x4488ff, 1.0, 12);
rimLight.position.set(-3, 7, -3);
scene.add(rimLight);

// ── Jar Dimensions ──
const JAR_RADIUS = 1.8;
const JAR_HEIGHT = 4.5;
const JAR_LIP = 0.15;
const JAR_LID_HEIGHT = 0.4;
const JAR_LID_RADIUS = JAR_RADIUS + 0.15;

// ── Jar Glass Body ──
const jarBodyGeo = new THREE.CylinderGeometry(
  JAR_RADIUS, JAR_RADIUS * 0.92, JAR_HEIGHT, 64, 1, true
);
const jarGlassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transparent: true,
  opacity: 0.18,
  roughness: 0.05,
  metalness: 0.0,
  transmission: 0.92,
  thickness: 0.5,
  ior: 1.5,
  side: THREE.DoubleSide,
  depthWrite: false,
});
const jarBody = new THREE.Mesh(jarBodyGeo, jarGlassMat);
jarBody.position.y = JAR_HEIGHT / 2 + 0.3;
scene.add(jarBody);

// Jar bottom cap
const jarBottomGeo = new THREE.CircleGeometry(JAR_RADIUS, 64);
const jarBottomMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, transparent: true, opacity: 0.22,
  roughness: 0.05, transmission: 0.9, thickness: 0.5, ior: 1.5,
  side: THREE.DoubleSide, depthWrite: false,
});
const jarBottom = new THREE.Mesh(jarBottomGeo, jarBottomMat);
jarBottom.rotation.x = -Math.PI / 2;
jarBottom.position.y = 0.3;
scene.add(jarBottom);

// ── Jar Lip / Rim ──
const rimGeo = new THREE.TorusGeometry(JAR_RADIUS + 0.05, 0.08, 16, 64);
const rimMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, transparent: true, opacity: 0.3,
  roughness: 0.05, transmission: 0.85, thickness: 0.3, ior: 1.5,
});
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = JAR_HEIGHT + 0.3;
scene.add(rim);

// ── Lid ──
const lidGeo = new THREE.CylinderGeometry(JAR_LID_RADIUS, JAR_LID_RADIUS * 0.95, JAR_LID_HEIGHT, 64);
const lidMat = new THREE.MeshPhysicalMaterial({
  color: 0xcc3333, roughness: 0.3, metalness: 0.6,
  clearcoat: 0.5, clearcoatRoughness: 0.2,
});
const lid = new THREE.Mesh(lidGeo, lidMat);
lid.position.y = JAR_HEIGHT + 0.3 + JAR_LID_HEIGHT / 2 + 0.05;
scene.add(lid);

// Lid top dome
const lidDomeGeo = new THREE.SphereGeometry(JAR_LID_RADIUS * 0.95, 64, 16, 0, Math.PI * 2, 0, Math.PI * 0.35);
const lidDome = new THREE.Mesh(lidDomeGeo, lidMat);
lidDome.position.y = JAR_HEIGHT + 0.3 + JAR_LID_HEIGHT + 0.05;
scene.add(lidDome);

// ── Jar Label (simple band) ──
const labelGeo = new THREE.CylinderGeometry(JAR_RADIUS + 0.01, JAR_RADIUS + 0.01, 1.2, 64, 1, true);
const labelMat = new THREE.MeshStandardMaterial({
  color: 0xfff8e7, roughness: 0.8, side: THREE.DoubleSide,
});
const label = new THREE.Mesh(labelGeo, labelMat);
label.position.y = 1.8;
scene.add(label);

// Label text stripe
const stripeGeo = new THREE.CylinderGeometry(JAR_RADIUS + 0.02, JAR_RADIUS + 0.02, 0.12, 64, 1, true);
const stripeMat = new THREE.MeshStandardMaterial({ color: 0xcc3333, roughness: 0.5, side: THREE.DoubleSide });
[-0.2, 0.2].forEach(yOff => {
  const stripe = new THREE.Mesh(stripeGeo, stripeMat);
  stripe.position.y = 1.8 + yOff;
  scene.add(stripe);
});

// ── Jellybeans ──
const jellybeanColors = [
  0xff3366, 0xff6633, 0xffcc00, 0x33cc33,
  0x3399ff, 0x9933ff, 0xff66cc, 0xff9933,
  0x66ffcc, 0xff4488, 0x44bbff, 0xffee44,
  0x7744ff, 0xff77aa, 0x22dd66, 0xff5522,
];

const jellybeanGroup = new THREE.Group();
scene.add(jellybeanGroup);

const jellybeans = [];
const JELLY_RADIUS = 0.18;
const JELLY_HEIGHT = 0.35;
const MAX_JELLYBEANS = 280;

// Capsule-like jellybean geometry
const jellyGeo = new THREE.SphereGeometry(1, 12, 8);
// Stretch it
jellyGeo.scale(1, 1.9, 0.85);

function isInsideJar(x, y, z) {
  if (y < 0.5 || y > JAR_HEIGHT - 0.3) return false;
  const dist = Math.sqrt(x * x + z * z);
  const rAtY = JAR_RADIUS * (0.92 + 0.08 * ((y - 0.3) / JAR_HEIGHT));
  return dist < rAtY - JELLY_RADIUS * 1.2;
}

function jellybeansCollide(a, b) {
  const dx = a.position.x - b.position.x;
  const dy = a.position.y - b.position.y;
  const dz = a.position.z - b.position.z;
  const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
  return dist < JELLY_RADIUS * 2.2;
}

for (let i = 0; i < MAX_JELLYBEANS; i++) {
  const color = jellybeanColors[Math.floor(Math.random() * jellybeanColors.length)];
  const mat = new THREE.MeshPhysicalMaterial({
    color,
    roughness: 0.15,
    metalness: 0.0,
    clearcoat: 1.0,
    clearcoatRoughness: 0.1,
    sheen: 0.3,
    sheenRoughness: 0.5,
    sheenColor: new THREE.Color(color).multiplyScalar(0.5),
  });

  const mesh = new THREE.Mesh(jellyGeo, mat);
  const scale = 0.85 + Math.random() * 0.3;
  mesh.scale.setScalar(scale);

  let placed = false;
  for (let attempt = 0; attempt < 50; attempt++) {
    const angle = Math.random() * Math.PI * 2;
    const r = Math.random() * (JAR_RADIUS - JELLY_RADIUS * 1.5);
    const x = Math.cos(angle) * r;
    const z = Math.sin(angle) * r;
    const y = 0.6 + Math.random() * (JAR_HEIGHT - 1.2);

    if (!isInsideJar(x, y, z)) continue;

    const tooClose = jellybeans.some(jb => jellybeansCollide(
      { position: { x, y, z } },
      { position: jb.position }
    ));
    if (tooClose) continue;

    mesh.position.set(x, y, z);
    mesh.rotation.set(
      Math.random() * Math.PI,
      Math.random() * Math.PI,
      Math.random() * Math.PI
    );
    placed = true;
    break;
  }

  if (placed) {
    jellybeanGroup.add(mesh);
    jellybeans.push(mesh);
  }
}

// ── Table / Surface ──
const tableGeo = new THREE.CylinderGeometry(5, 5, 0.15, 64);
const tableMat = new THREE.MeshStandardMaterial({
  color: 0x2a1a0a, roughness: 0.7, metalness: 0.1,
});
const table = new THREE.Mesh(tableGeo, tableMat);
table.position.y = -0.075;
scene.add(table);

// ── Background gradient sphere ──
const bgGeo = new THREE.SphereGeometry(30, 32, 32);
const bgMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  uniforms: {
    colorTop: { value: new THREE.Color(0x2a1a4e) },
    colorBottom: { value: new THREE.Color(0x0a0a1e) },
  },
  vertexShader: `
    varying vec3 vWorldPos;
    void main() {
      vWorldPos = (modelMatrix * vec4(position, 1.0)).xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 colorTop;
    uniform vec3 colorBottom;
    varying vec3 vWorldPos;
    void main() {
      float t = smoothstep(-15.0, 15.0, vWorldPos.y);
      gl_FragColor = vec4(mix(colorBottom, colorTop, t), 1.0);
    }
  `,
});
scene.add(new THREE.Mesh(bgGeo, bgMat));

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle jellybean wobble
  jellybeans.forEach((jb, i) => {
    const speed = 0.3 + (i % 5) * 0.1;
    jb.rotation.y += 0.001 * speed;
    jb.position.y += Math.sin(t * speed + i * 0.5) * 0.00015;
  });

  // Subtle light movement
  pointLight.position.x = Math.sin(t * 0.5) * 1.5;
  pointLight.position.z = Math.cos(t * 0.5) * 1.5;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What you get

| Feature | Detail |
|---|---|
| **Glass jar** | Transparent cylinder with `MeshPhysicalMaterial` transmission/refraction, a torus rim, and a glass bottom cap |
| **Red lid** | Capped with a dome, metallic red with clearcoat |
| **Label band** | Cream-colored band with red stripes wrapping the jar |
| **~280 jellybeans** | Scaled spheres with `MeshPhysicalMaterial` — high clearcoat, sheen, and vibrant colors (16 shades) |
| **Packing** | Collision-aware random placement so beans don't overlap |
| **Lighting** | 4 lights (ambient, 2 directional, moving point, rim) for glossy specular highlights |
| **Background** | Gradient shader sphere (purple → dark navy) + fog |
| **Table** | Dark wood-toned cylinder beneath the jar |
| **Controls** | `OrbitControls` — drag to rotate, scroll to zoom |
| **Animation** | Gentle jellybean wobble + orbiting point

