<body>
    <div id="info">🌲 Giant Redwood — drag to orbit, scroll to zoom</div>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 200);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 40, 100);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 30, 0);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        scene.add(dirLight);

        // --- Materials ---
        const trunkMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x8B4513, // SaddleBrown
            roughness: 0.9,
            bumpScale: 0.5
        });

        const foliageMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x228B22, // ForestGreen
            roughness: 0.8,
            flatShading: true
        });

        const groundMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3a5f0b, 
            roughness: 1 
        });

        // --- Tree Generation ---
        const treeGroup = new THREE.Group();
        scene.add(treeGroup);

        // 1. Trunk
        // Redwoods are tall and straight.
        const trunkHeight = 80;
        const trunkRadiusBottom = 4;
        const trunkRadiusTop = 2.5;
        const trunkGeo = new THREE.CylinderGeometry(trunkRadiusTop, trunkRadiusBottom, trunkHeight, 16);
        const trunk = new THREE.Mesh(trunkGeo, trunkMaterial);
        trunk.position.y = trunkHeight / 2;
        trunk.castShadow = true;
        trunk.receiveShadow = true;
        treeGroup.add(trunk);

        // 2. Foliage (Procedural Clumps)
        // Redwoods have foliage that starts higher up and forms a large canopy.
        function createFoliageClump(y, radius, height) {
            const group = new THREE.Group();

            // Main cone
            const geo = new THREE.ConeGeometry(radius, height, 8);
            const mesh = new THREE.Mesh(geo, foliageMaterial);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            group.add(mesh);

            // Add some irregularity with smaller spheres/cones
            const detailCount = 3;
            for(let i=0; i<detailCount; i++) {
                const detailGeo = new THREE.IcosahedronGeometry(radius * 0.6, 0);
                const detailMesh = new THREE.Mesh(detailGeo, foliageMaterial);
                detailMesh.position.set(
                    (Math.random() - 0.5) * radius,
                    (Math.random() - 0.5) * height * 0.5,
                    (Math.random() - 0.5) * radius
                );
                detailMesh.castShadow = true;
                group.add(detailMesh);
            }

            group.position.y = y;
            return group;
        }

        // Add foliage layers
        // Base foliage starts around 30 units up
        const foliageStartY = 30;
        const foliageEndY = 85;

        for (let y = foliageStartY; y < foliageEndY; y += 4) {
            // Tapering logic: wider in the middle-top, narrower at very top and bottom
            let progress = (y - foliageStartY) / (foliageEndY - foliageStartY);
            let radius = 12; 

            // Shape the canopy
            if (progress < 0.2) radius = 12 * (progress / 0.2); // Taper bottom
            else if (progress > 0.8) radius = 12 * (1 - (progress - 0.8) / 0.2); // Taper top

            // Add some randomness to radius
            radius += (Math.random() - 0.5) * 2;

            const clump = createFoliageClump(y, radius, 6);
            // Random rotation for organic look
            clump.rotation.y = Math.random() * Math.PI;
            treeGroup.add(clump);
        }

        // Add a top crown
        const topCrown = createFoliageClump(88, 8, 8);
        treeGroup.add(topCrown);

        // --- Ground ---
        const groundGeo = new THREE.PlaneGeometry(500, 500);
        const ground = new THREE.Mesh(groundGeo, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
