<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chameleon on a Branch</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a2e; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // Materials
        const branchMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.9 });
        const chameleonBodyMaterial = new THREE.MeshStandardMaterial({ color: 0x32CD32, roughness: 0.4 }); // Lime green
        const chameleonDarkMaterial = new THREE.MeshStandardMaterial({ color: 0x006400, roughness: 0.4 }); // Dark green
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0xFFFFFF });
        const pupilMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });

        // --- Create Branch ---
        const branchGroup = new THREE.Group();

        // Main branch
        const branchGeo = new THREE.CylinderGeometry(0.3, 0.4, 12, 12);
        const branch = new THREE.Mesh(branchGeo, branchMaterial);
        branch.rotation.z = Math.PI / 2;
        branch.position.y = -1;
        branch.castShadow = true;
        branch.receiveShadow = true;
        branchGroup.add(branch);

        // Small offshoot
        const offshootGeo = new THREE.CylinderGeometry(0.1, 0.2, 3, 8);
        const offshoot = new THREE.Mesh(offshootGeo, branchMaterial);
        offshoot.position.set(2, -1, 0);
        offshoot.rotation.z = Math.PI / 4;
        offshoot.castShadow = true;
        branchGroup.add(offshoot);

        scene.add(branchGroup);

        // --- Create Chameleon ---
        const chameleon = new THREE.Group();

        // Body
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        bodyGeo.scale(1.5, 1, 1);
        const body = new THREE.Mesh(bodyGeo, chameleonBodyMaterial);
        body.position.set(0, 0.5, 0);
        body.castShadow = true;
        chameleon.add(body);

        // Head
        const headGeo = new THREE.SphereGeometry(0.6, 32, 32);
        const head = new THREE.Mesh(headGeo, chameleonBodyMaterial);
        head.position.set(1.2, 0.8, 0);
        head.castShadow = true;
        chameleon.add(head);

        // Casque (head crest)
        const casqueGeo = new THREE.ConeGeometry(0.4, 0.8, 16);
        const casque = new THREE.Mesh(casqueGeo, chameleonBodyMaterial);
        casque.position.set(1.2, 1.4, 0);
        casque.rotation.z = -Math.PI / 6;
        chameleon.add(casque);

        // Eye Turret
        const turretGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.4, 16);
        const turret = new THREE.Mesh(turretGeo, chameleonBodyMaterial);
        turret.position.set(1.4, 0.9, 0.4);
        turret.rotation.x = Math.PI / 2;
        chameleon.add(turret);

        // Eye
        const eyeGeo = new THREE.SphereGeometry(0.25, 32, 32);
        const eye = new THREE.Mesh(eyeGeo, eyeMaterial);
        eye.position.set(1.4, 0.9, 0.6);
        chameleon.add(eye);

        // Pupil
        const pupilGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const pupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        pupil.position.set(1.4, 0.9, 0.8);
        chameleon.add(pupil);

        // Tail (Spiral approximation using a curve)
        class SpiralCurve extends THREE.Curve {
            constructor(scale = 1) {
                super();
                this.scale = scale;
            }
            getPoint(t) {
                const angle = t * Math.PI * 4; // 2 loops
                const radius = 0.5 + t * 0.5;
                const x = Math.cos(angle) * radius;
                const y = Math.sin(angle) * radius;
                const z = t * 0.5; // tapering out
                return new THREE.Vector3(x, y, z).multiplyScalar(this.scale);
            }
        }

        const tailCurve = new SpiralCurve(0.8);
        const tailGeo = new THREE.TubeGeometry(tailCurve, 64, 0.15, 8, false);
        const tail = new THREE.Mesh(tailGeo, chameleonBodyMaterial);
        tail.position.set(-1.2, 0.5, 0);
        tail.rotation.y = Math.PI; // Point backwards
        tail.castShadow = true;
        chameleon.add(tail);

        // Legs (Simple cylinders)
        function createLeg(x, y, z, rotZ) {
            const legGeo = new THREE.CylinderGeometry(0.15, 0.1, 0.8, 8);
            const leg = new THREE.Mesh(legGeo, chameleonBodyMaterial);
            leg.position.set(x, y, z);
            leg.rotation.z = rotZ;
            leg.castShadow = true;
            return leg;
        }

        // Front legs
        chameleon.add(createLeg(0.8, -0.2, 0.4, -0.5));
        chameleon.add(createLeg(0.8, -0.2, -0.4, 0.5));
        // Back legs
        chameleon.add(createLeg(-0.8, -0.2, 0.4, -0.5));
        chameleon.add(createLeg(-0.8, -0.2, -0.4, 0.5));

        // Position Chameleon on Branch
        chameleon.position.set(0, -0.5, 0);
        scene.add(chameleon);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Subtle breathing animation
            body.scale.y = 1 + Math.sin(time * 2) * 0.02;
            body.scale.x = 1.5 + Math.sin(time * 2) * 0.02;

            // Eye movement
            eye.position.x = 1.4 + Math.sin(time * 0.5) * 0.1;
            pupil.position.x = eye.position.x;
            turret.position.x = eye.position.x;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
