        leftKnob.rotation.z = Math.PI / 2;
        leftKnob.position.set(-3, 2.3, -1.5);
        typewriter.add(leftKnob);

        const rightKnob = new THREE.Mesh(knobGeo, brassMaterial);
        rightKnob.rotation.z = Math.PI / 2;
        rightKnob.position.set(3, 2.3, -1.5);
        typewriter.add(rightKnob);

        // 4. Paper
        const paperGeo = new THREE.BoxGeometry(4, 0.05, 3);
        const paper = new THREE.Mesh(paperGeo, paperMaterial);
        paper.position.set(0, 2.9, -2.5);
        paper.rotation.x = 0.1; // Slight tilt
        typewriter.add(paper);

        // 5. Keyboard Area (Sloped)
        const keyboardGeo = new THREE.BoxGeometry(5.8, 0.2, 2.5);
        const keyboard = new THREE.Mesh(keyboardGeo, bodyMaterial);
        keyboard.position.set(0, 1.6, 1.2);
        keyboard.rotation.x = -0.2; // Slope
        keyboard.castShadow = true;
        typewriter.add(keyboard);

        // 6. Keys
        const keyStemGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.4);
        const keyCapGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.1, 16);

        const rows = 4;
        const cols = 10;
        const spacingX = 0.5;
        const spacingZ = 0.5;
        const startX = -2.25;
        const startZ = 0.5;

        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
