        const domeRadius = 6;
        const slitAngle = Math.PI * 0.2; // Width of the slit
        const domeGeo = new THREE.SphereGeometry(domeRadius, 64, 32, 0, Math.PI * 2 - slitAngle, 0, Math.PI / 2);
        const dome = new THREE.Mesh(domeGeo, domeMaterial);
        dome.position.y = 3;
        dome.castShadow = true;
        dome.receiveShadow = true;
        scene.add(dome);

        // 4. The Slit Cover (The part that closes the opening)
        // We create a partial sphere to cover the gap
        const coverGeo = new THREE.SphereGeometry(domeRadius + 0.1, 32, 32, 0, slitAngle, 0, Math.PI / 2);
        const cover = new THREE.Mesh(coverGeo, domeMaterial);
        cover.position.y = 3;
        cover.castShadow = true;
