        const mount = new THREE.Mesh(mountGeo, baseMaterial);
        mount.position.y = 0.5;
        telescopeGroup.add(mount);

        scene.add(telescopeGroup);

        // 6. Stars (Particles)
        const starsGeo = new THREE.BufferGeometry();
        const starsCount = 2000;
        const posArray = new Float32Array(starsCount * 3);
        for(let i = 0; i < starsCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 200; // Spread wide
            if (i % 3 === 1 && posArray[i] < 0) posArray[i] *= -1; // Keep above ground mostly
        }
        starsGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const starsMat = new THREE.PointsMaterial({ size: 0.2, color: 0xffffff });
        const stars = new THREE.Points(starsGeo, starsMat);
