            // If opening, rotate cover away. If closing, rotate cover into the gap.
            // Actually, simpler logic: 
            // Open: Cover is rotated out of the way (or hidden). 
            // Let's just rotate the cover mesh around Y axis.
            // The gap is at angle 0 to slitAngle.
            // If open, cover should be at angle (Math.PI * 2 - slitAngle) effectively, or just hidden.
            // Let's just toggle visibility for simplicity in this demo, or rotate it.
            // Let's rotate it.
            if(isSlitOpen) {
                cover.visible = false;
                telescopeLight.intensity = 5;
            } else {
                cover.visible = true;
                telescopeLight.intensity = 0;
            }
        });

        document.getElementById('btn-telescope').addEventListener('click', () => {
            isTelescopeVisible = !isTelescopeVisible;
            telescopeGroup.visible = isTelescopeVisible;
