                if(isSlitOpen) telescopeLight.intensity = 5;
            } else {
                scene.background = new THREE.Color(0x87CEEB); // Sky blue
                scene.fog.color.setHex(0x87CEEB);
                sunLight.intensity = 2;
                ambientLight.intensity = 1;
                stars.visible = false;
                telescopeLight.intensity = 0; // No beam needed in day
            }
        });

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            // Smooth rotation for cover if we were animating it, 
            // but for now we just toggle visibility based on the button logic above.

            // Rotate telescope slowly
            if (isTelescopeVisible) {
                telescopeGroup.rotation.y += 0.005;
                // Point light with telescope
                telescopeLight.position.copy(telescopeGroup.position);
                telescopeLight.position.y += 7; // Top of tube
                telescopeLight.target.position.copy(telescopeGroup.position);
                telescopeLight.target.position.y += 20; // Far away
                // Calculate direction based on rotation
                const dir = new THREE.Vector3(0, 1, 0).applyAxisAngle(new THREE.Vector3(0,1,0), telescopeGroup.rotation.y);
                telescopeLight.target.position.copy(telescopeGroup.position).add(dir.multiplyScalar(20));
            }

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
