<body>
    <div id="info">🐚 Coral Reef — drag to orbit</div>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x001e36); // Deep ocean blue
        scene.fog = new THREE.FogExp2(0x001e36, 0.03); // Underwater fog

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 4, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.maxPolarAngle = Math.PI / 2 - 0.1; // Don't go below ground

        // 2. Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 3); // Soft ambient
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 5);
        scene.add(dirLight);

        const blueLight = new THREE.PointLight(0x0088ff, 2, 20);
        blueLight.position.set(0, 5, 0);
        scene.add(blueLight);

        // 3. Floor (Sand)
        const planeGeometry = new THREE.PlaneGeometry(100, 100);
        const planeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x0b1d3a, 
            roughness: 1,
            metalness: 0
        });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -2;
        scene.add(plane);

        // 4. Procedural Coral Generation
        const coralGroup = new THREE.Group();
        scene.add(coralGroup);

        const coralColors = [0xff6b6b, 0xff9f43, 0xfeca57, 0x48dbfb, 0xff9ff3, 0x54a0ff, 0x1dd1a1];

        function createBranchingCoral(x, z) {
            const group = new THREE.Group();
            group.position.set(x, -2, z);

            const color = coralColors[Math.floor(Math.random() * coralColors.length)];
            const material = new THREE.MeshStandardMaterial({ color: color, roughness: 0.7 });

            // Recursive branch function
            function branch(parent, height, radius, depth) {
                if (depth === 0) return;

                const geo = new THREE.CylinderGeometry(radius * 0.7, radius, height, 8);
                const mesh = new THREE.Mesh(geo, material);
                mesh.position.y = height / 2;
                parent.add(mesh);

                const newHeight = height * 0.7;
                const newRadius = radius * 0.7;
                const count = depth > 1 ? 2 : 1; // Fewer branches at top

                for (let i = 0; i < count; i++) {
                    const childGroup = new THREE.Group();
                    childGroup.position.y = height;
                    childGroup.rotation.z = (Math.random() - 0.5) * 1.5;
                    childGroup.rotation.x = (Math.random() - 0.5) * 1.5;
                    parent.add(childGroup);
                    branch(childGroup, newHeight, newRadius, depth - 1);
                }
            }

            branch(group, 1.5, 0.2, 3);
            return group;
        }

        function createTubeCoral(x, z) {
            const group = new THREE.Group();
            group.position.set(x, -2, z);

            const color = coralColors[Math.floor(Math.random() * coralColors.length)];
            const material = new THREE.MeshStandardMaterial({ color: color, roughness: 0.5 });

            for(let i=0; i<5; i++) {
                const h = 1 + Math.random();
                const geo = new THREE.CylinderGeometry(0.15, 0.2, h, 16, 1, true);
                const mesh = new THREE.Mesh(geo, material);
                mesh.position.set((Math.random()-0.5)*0.8, h/2, (Math.random()-0.5)*0.8);
                group.add(mesh);
            }
            return group;
        }

        function createBrainCoral(x, z) {
            const group = new THREE.Group();
            group.position.set(x, -2, z);

            const color = coralColors[Math.floor(Math.random() * coralColors.length)];
            const material = new THREE.MeshStandardMaterial({ color: color, roughness: 0.8 });

            const geo = new THREE.SphereGeometry(1, 32, 32);
            const mesh = new THREE.Mesh(geo, material);
            mesh.scale.y = 0.6;
            mesh.position.y = 0.6;
            group.add(mesh);
            return group;
        }

        // Populate the reef
        for (let i = 0; i < 30; i++) {
            const x = (Math.random() - 0.5) * 20;
            const z = (Math.random() - 0.5) * 20;
            const type = Math.random();

            if (type < 0.4) {
                coralGroup.add(createBranchingCoral(x, z));
            } else if (type < 0.7) {
                coralGroup.add(createTubeCoral(x, z));
            } else {
                coralGroup.add(createBrainCoral(x, z));
            }
        }

        // 5. Bubbles
        const bubbleGeo = new THREE.SphereGeometry(0.05, 8, 8);
        const bubbleMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 });
        const bubbles = [];

        for(let i=0; i<100; i++) {
            const bubble = new THREE.Mesh(bubbleGeo, bubbleMat);
            bubble.position.set(
                (Math.random() - 0.5) * 20,
                Math.random() * 10 - 2,
                (Math.random() - 0.5) * 20
            );
            bubble.userData = { speed: 0.01 + Math.random() * 0.03 };
            scene.add(bubble);
            bubbles.push(bubble);
        }

        // 6. Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();

            // Animate bubbles
            bubbles.forEach(b => {
                b.position.y += b.userData.speed;
                if(b.position.y > 8) {
                    b.position.y = -2;
                    b.position.x = (Math.random() - 0.5) * 20;
                    b.position.z = (Math.random() - 0.5) * 20;
                }
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
