    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222); // Dark grey background to see the cricket better
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        // Camera
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // Ground Plane
        const planeGeometry = new THREE.PlaneGeometry(50, 50);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Cricket Construction
        const cricketGroup = new THREE.Group();

        // Materials
        const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0x4a3c31, roughness: 0.7 }); // Dark brown
        const legMaterial = new THREE.MeshStandardMaterial({ color: 0x2a2018, roughness: 0.8 }); // Darker brown
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // 1. Abdomen (Rear)
        const abdomenGeo = new THREE.CapsuleGeometry(0.6, 1.5, 4, 8);
        const abdomen = new THREE.Mesh(abdomenGeo, bodyMaterial);
        abdomen.rotation.x = Math.PI / 2;
        abdomen.position.z = -1.2;
        abdomen.castShadow = true;
        cricketGroup.add(abdomen);

        // 2. Thorax (Middle)
        const thoraxGeo = new THREE.SphereGeometry(0.7, 16, 16);
        const thorax = new THREE.Mesh(thoraxGeo, bodyMaterial);
        thorax.scale.set(1, 0.8, 1.2);
        thorax.position.z = 0.2;
        thorax.castShadow = true;
        cricketGroup.add(thorax);

        // 3. Head
        const headGeo = new THREE.SphereGeometry(0.5, 16, 16);
        const head = new THREE.Mesh(headGeo, bodyMaterial);
        head.position.z = 1.2;
        head.castShadow = true;
        cricketGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.15, 8, 8);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.4, 0.2, 1.5);
        cricketGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.4, 0.2, 1.5);
        cricketGroup.add(rightEye);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.03, 0.01, 3, 8);
        const leftAntenna = new THREE.Mesh(antennaGeo, legMaterial);
        leftAntenna.position.set(-0.3, 0.5, 2.2);
        leftAntenna.rotation.set(0.5, 0, -0.5);
        cricketGroup.add(leftAntenna);

        const rightAntenna = new THREE.Mesh(antennaGeo, legMaterial);
        rightAntenna.position.set(0.3, 0.5, 2.2);
        rightAntenna.rotation.set(0.5, 0, 0.5);
        cricketGroup.add(rightAntenna);

        // Legs Helper Function
        function createLeg(x, y, z, rotX, rotZ) {
            const legGroup = new THREE.Group();

            // Upper leg
            const upperLegGeo = new THREE.CylinderGeometry(0.08, 0.06, 1.5, 8);
            const upperLeg = new THREE.Mesh(upperLegGeo, legMaterial);
            upperLeg.position.y = -0.75;
            legGroup.add(upperLeg);

            // Lower leg
            const lowerLegGeo = new THREE.CylinderGeometry(0.06, 0.04, 1.5, 8);
            const lowerLeg = new THREE.Mesh(lowerLegGeo, legMaterial);
            lowerLeg.position.y = -1.5;
            lowerLeg.rotation.z = 0.5; // Bend
            legGroup.add(lowerLeg);

            legGroup.position.set(x, y, z);
            legGroup.rotation.x = rotX;
            legGroup.rotation.z = rotZ;

            return legGroup;
        }

        // Add 6 legs
        // Front pair
        cricketGroup.add(createLeg(-0.6, 0, 0.8, 0.2, 0.5));
        cricketGroup.add(createLeg(0.6, 0, 0.8, 0.2, -0.5));

        // Middle pair
        cricketGroup.add(createLeg(-0.7, 0, 0, 0, 0.8));
        cricketGroup.add(createLeg(0.7, 0, 0, 0, -0.8));

