        const backLegGeo = new THREE.CylinderGeometry(0.1, 0.08, 2.5, 8);
        const backLowerGeo = new THREE.CylinderGeometry(0.08, 0.05, 2.5, 8);

        function createBackLeg(x, z, rotZ) {
            const legGroup = new THREE.Group();
            const upper = new THREE.Mesh(backLegGeo, legMaterial);
            upper.position.y = -1.25;
            legGroup.add(upper);

            const lower = new THREE.Mesh(backLowerGeo, legMaterial);
            lower.position.y = -2.5;
            lower.rotation.z = 0.8;
            legGroup.add(lower);

            legGroup.position.set(x, 0, z);
            legGroup.rotation.z = rotZ;
            return legGroup;
        }

        cricketGroup.add(createBackLeg(-0.8, -0.8, 1.2));
        cricketGroup.add(createBackLeg(0.8, -0.8, -1.2));

        // Position the whole cricket
        cricketGroup.position.y = 1.5;
        scene.add(cricketGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Simple idle animation
            const time = Date.now() * 0.001;
            cricketGroup.position.y = 1.5 + Math.sin(time * 2) * 0.1;
            cricketGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
