```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Folding Fan</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a2e; }
canvas { display: block; }
#info {
  position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
  color: #ccc; font-family: system-ui; font-size: 14px;
  background: rgba(0,0,0,.5); padding: 8px 18px; border-radius: 20px;
  pointer-events: none;
}
</style>
</head>
<body>
<div id="info">Drag to orbit · Scroll to zoom</div>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js", "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/" } }
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 20;

// --- Fan parameters ---
const NUM_RIBS = 16;
const RIB_LENGTH = 4.5;
const RIB_THICKNESS = 0.04;
const RIB_WIDTH = 0.08;
const OPEN_ANGLE = Math.PI * 0.9;
const FAN_RADIUS = RIB_LENGTH;

// --- Materials ---
const ribMat = new THREE.MeshStandardMaterial({
  color: 0x8B4513, roughness: 0.3, metalness: 0.1
});
const handleMat = new THREE.MeshStandardMaterial({
  color: 0x5C3317, roughness: 0.4, metalness: 0.05
});
const fabricMat = new THREE.MeshStandardMaterial({
  color: 0xCC2233, roughness: 0.7, metalness: 0.0,
  side: THREE.DoubleSide, transparent: true, opacity: 0.88
});
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xDAA520, roughness: 0.2, metalness: 0.8
});
const tipMat = new THREE.MeshStandardMaterial({
  color: 0x5C3317, roughness: 0.3, metalness: 0.1
});

// --- Fan group ---
const fanGroup = new THREE.Group();
scene.add(fanGroup);

// Pivot is at (0, 0, 0) of fanGroup, handle extends downward
fanGroup.position.y = 0.5;

// --- Handle ---
const handleGeo = new THREE.CylinderGeometry(0.1, 0.15, 1.2, 12);
const handle = new THREE.Mesh(handleGeo, handleMat);
handle.position.y = -0.8;
fanGroup.add(handle);

// Handle cap
const capGeo = new THREE.SphereGeometry(0.16, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2);
const cap = new THREE.Mesh(capGeo, goldMat);
cap.position.y = -1.4;
cap.rotation.x = Math.PI;
fanGroup.add(cap);

// Handle top ring
const ringGeo = new THREE.TorusGeometry(0.12, 0.02, 8, 16);
const ring = new THREE.Mesh(ringGeo, goldMat);
ring.position.y = -0.2;
fanGroup.add(ring);

// --- Ribs and fabric ---
const ribs = [];
const fabricPanels = [];

function createRib(index, total) {
  const angle = (index / (total - 1)) * OPEN_ANGLE - OPEN_ANGLE / 2;

  const group = new THREE.Group();

  // Rib bone
  const ribGeo = new THREE.BoxGeometry(RIB_THICKNESS, RIB_WIDTH, RIB_LENGTH);
  const rib = new THREE.Mesh(ribGeo, ribMat);
  rib.position.y = RIB_LENGTH / 2;
  group.add(rib);

  // Gold tip
  const tipGeo = new THREE.SphereGeometry(0.06, 8, 8);
  const tip = new THREE.Mesh(tipGeo, goldMat);
  tip.position.y = RIB_LENGTH;
  group.add(tip);

  group.rotation.z = angle;
  group.userData.restAngle = angle;
  ribs.push(group);
  fanGroup.add(group);
  return group;
}

function createFabricPanel(ribA, ribB) {
  const a = ribA.userData.restAngle;
  const b = ribB.userData.restAngle;

  // Build quad between two ribs
  const segments = 6;
  const positions = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const r = t * RIB_LENGTH;
    for (const angle of [a, b]) {
      positions.push(Math.sin(angle) * r, r, Math.cos(angle) * r);
      uvs.push((angle - a) / (b - a), t);
    }
  }

  for (let i = 0; i < segments; i++) {
    const base = i * 2;
    indices.push(base, base + 1, base + 2);
    indices.push(base + 1, base + 3, base + 2);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();

  const mesh = new THREE.Mesh(geo, fabricMat);
  fabricPanels.push(mesh);
  fanGroup.add(mesh);
}

for (let i = 0; i < NUM_RIBS; i++) createRib(i, NUM_RIBS);
for (let i = 0; i < NUM_RIBS - 1; i++) createFabricPanel(ribs[i], ribs[i + 1]);

// --- Decorative top edge (head of fan) ---
const headPoints = [];
for (let i = 0; i <= NUM_RIBS; i++) {
  const a = (i / NUM_RIBS) * OPEN_ANGLE - OPEN_ANGLE / 2;
  headPoints.push(new THREE.Vector3(Math.sin(a) * RIB_LENGTH, RIB_LENGTH, Math.cos(a) * RIB_LENGTH));
}
const headCurve = new THREE.CatmullRomCurve3(headPoints);
const headGeo = new THREE.TubeGeometry(headCurve, 40, 0.03, 8, false);
fanGroup.add(new THREE.Mesh(headGeo, goldMat));

// --- Pivot cap ---
const pivotGeo = new THREE.SphereGeometry(0.14, 16, 16);
const pivot = new THREE.Mesh(pivotGeo, goldMat);
fanGroup.add(pivot);

// --- Painted pattern on fabric (decorative lines) ---
const patternMat = new THREE.MeshStandardMaterial({
  color: 0xFFD700, roughness: 0.5, metalness: 0.3,
  side: THREE.DoubleSide, transparent: true, opacity: 0.5
});

for (let r = 1; r <= 3; r++) {
  const rr = (r / 4) * RIB_LENGTH;
  const pts = [];
  for (let i = 0; i <= NUM_RIBS; i++) {
    const a = (i / NUM_RIBS) * OPEN_ANGLE - OPEN_ANGLE / 2;
    pts.push(new THREE.Vector3(Math.sin(a) * rr, rr, Math.cos(a) * rr));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const tubeGeo = new THREE.TubeGeometry(curve, 30, 0.015, 6, false);
  fanGroup.add(new THREE.Mesh(tubeGeo, patternMat));
}

// --- Lighting ---
const ambLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambLight);

const dirLight = new THREE.DirectionalLight(0xffeedd, 2);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);

const dirLight2 = new THREE.DirectionalLight(0x8888ff, 0.5);
dirLight2.position.set(-3, 2, -2);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xff6644, 1, 10);
pointLight.position.set(0, 4, 3);
scene.add(pointLight);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Smooth open/close cycle: 0 = closed, 1 = fully open
  const openAmount = (Math.sin(t * 0.8) * 0.5 + 0.5);
  const eased = openAmount * openAmount * (3 - 2 * openAmount); // smoothstep

  // Update rib angles
  for (const rib of ribs) {
    rib.rotation.z = rib.userData.restAngle * eased;
  }

  // Update fabric panels
  for (let i = 0; i < fabricPanels.length; i++) {
    const panel = fabricPanels[i];
    const a = ribs[i].rotation.z;
    const b = ribs[i + 1].rotation.z;
    const pos = panel.geometry.attributes.position;
    const segments = 6;

    for (let j = 0; j <= segments; j++) {
      const t2 = j / segments;
      const r = t2 * RIB_LENGTH;
      // vertex 0 = ribA, vertex 1 = ribB
      const idxA = j * 2;
      const idxB = j * 2 + 1;

      pos.setXYZ(idxA, Math.sin(a) * r, r, Math.cos(a) * r);
      pos.setXYZ(idxB, Math.sin(b) * r, r, Math.cos(b) * r);
    }
    pos.needsUpdate = true;
    panel.geometry.computeVertexNormals();
  }

  // Update head curve
  const headMesh = fanGroup.children.find(c => c.geometry?.type === 'TubeGeometry' && c.material === goldMat);
  if (headMesh && headMesh !== cap && headMesh !== ring && headMesh !== pivot) {
    // Skip — we handle decorative tubes separately
  }

  // Gentle floating
  fanGroup.position.y = 0.5 + Math.sin(t * 1.2) * 0.15;
  fanGroup.rotation.y = Math.sin(t * 0.3) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**Features:**

- **16 wooden ribs** with gold tips that pivot from a central handle
- **Translucent red fabric** panels between ribs that deform smoothly as the fan opens/closes
- **Gold decorative arc** along the top edge + concentric golden pattern lines on the fabric
- **Smooth open/close animation** using a sine wave with smoothstep easing (~5 second cycle)
- **Gentle floating** motion — the fan hovers and subtly sways
- **OrbitControls** — drag to rotate the view, scroll to zoom
- **PBR materials** with environment mapping for realistic wood, gold, and silk appearance
- **Atmospheric fog** and multi-source lighting for depth

