        // Materials
        const whiteFeatherMat = new THREE.MeshStandardMaterial({ color: 0xf0f0f0, roughness: 0.8 });
        const darkFeatherMat = new THREE.MeshStandardMaterial({ color: 0x3d2b1f, roughness: 0.9 });
        const eyeMat = new THREE.MeshStandardMaterial({ color: 0x000000, roughness: 0.2 });
        const beakMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.5 });
        const wingMat = new THREE.MeshStandardMaterial({ color: 0x8b5a2b, roughness: 0.8 });

        // 1. Body
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        const body = new THREE.Mesh(bodyGeo, darkFeatherMat);
        body.scale.set(1, 1.2, 0.9);
        body.position.y = -0.5;
        body.castShadow = true;
        owl.add(body);

        // 2. Head
        const headGroup = new THREE.Group();
        headGroup.position.y = 1.2;
        owl.add(headGroup);

        // Head Base (The heart shape is tricky with primitives, let's use a sphere and a face mask)
        const headGeo = new THREE.SphereGeometry(0.9, 32, 32);
        const head = new THREE.Mesh(headGeo, darkFeatherMat);
        head.scale.set(1, 0.9, 1);
        head.castShadow = true;
        headGroup.add(head);

        // Face Mask (The white heart part)
        // We approximate the heart shape with a flattened sphere and a custom shape or just a disc
        const faceMaskGeo = new THREE.CircleGeometry(0.75, 32);
        const faceMask = new THREE.Mesh(faceMaskGeo, whiteFeatherMat);
        faceMask.position.set(0, 0, 0.7);
        faceMask.rotation.x = 0;
        headGroup.add(faceMask);

        // 3. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.22, 32, 32);

        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.35, 0.1, 0.75);
        headGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.35, 0.1, 0.75);
        headGroup.add(rightEye);

        // Eye Highlights
