        const beak = new THREE.Mesh(beakGeo, beakMat);
        beak.position.set(0, -0.15, 0.85);
        beak.rotation.x = Math.PI / 2; // Point forward
        headGroup.add(beak);

        // 5. Wings
        const wingGeo = new THREE.BoxGeometry(0.4, 2.2, 0.1);
        // Modify geometry to taper
        const posAttribute = wingGeo.attributes.position;
        for (let i = 0; i < posAttribute.count; i++) {
            const y = posAttribute.getY(i);
            if (y < 0) {
                // Taper the bottom
                const taper = 1 + (y * 0.3); 
                posAttribute.setX(i, posAttribute.getX(i) * taper);
            }
        }
        wingGeo.computeVertexNormals();

        const leftWing = new THREE.Mesh(wingGeo, wingMat);
        leftWing.position.set(-1.1, -0.2, -0.2);
        leftWing.rotation.z = 0.2;
        leftWing.rotation.x = 0.1;
