        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x0044ff, 0.5);
        backLight.position.set(-5, 5, -5);
        scene.add(backLight);

        // Hedgehog Construction
        const hedgehogGroup = new THREE.Group();

        // Materials
        const bodyMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x8B4513, 
            roughness: 0.8 
        });
        const spikeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3e2723, 
            roughness: 0.9 
        });
        const faceMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xd2b48c, 
            roughness: 0.5 
        });
        const eyeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x000000, 
            roughness: 0.2 
        });

        // Body (Curled Sphere)
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        const body = new THREE.Mesh(bodyGeo, bodyMaterial);
        body.castShadow = true;
        body.receiveShadow = true;
        hedgehogGroup.add(body);

        // Spikes
        const spikeGeo = new THREE.ConeGeometry(0.08, 0.4, 8);
        const spikeCount = 200;

        for (let i = 0; i < spikeCount; i++) {
            const spike = new THREE.Mesh(spikeGeo, spikeMaterial);

            // Random position on sphere surface
            const phi = Math.acos(-1 + (2 * i) / spikeCount);
            const theta = Math.sqrt(spikeCount * Math.PI) * phi;

            // Convert spherical to cartesian
            const r = 1.0; // Radius of body
            const x = r * Math.cos(theta) * Math.sin(phi);
            const y = r * Math.sin(theta) * Math.sin(phi);
            const z = r * Math.cos(phi);

            spike.position.set(x, y, z);

            // Orient spike outwards
            spike.lookAt(0, 0, 0);
            spike.rotateX(Math.PI / 2); // Cone points up by default, rotate to point out

            // Add some randomness to length/rotation for natural look
            const scale = 0.8 + Math.random() * 0.5;
            spike.scale.set(scale, scale, scale);
            spike.rotation.z += (Math.random() - 0.5) * 0.2;
            spike.rotation.x += (Math.random() - 0.5) * 0.2;

            hedgehogGroup.add(spike);
        }

        // Face (Snout)
        const snoutGeo = new THREE.ConeGeometry(0.3, 0.6, 16);
        const snout = new THREE.Mesh(snoutGeo, faceMaterial);
        snout.position.set(0, 0, 1.1);
        snout.rotation.x = Math.PI / 2;
        snout.castShadow = true;
        hedgehogGroup.add(snout);

        // Nose
        const noseGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const noseMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const nose = new THREE.Mesh(noseGeo, noseMat);
        nose.position.set(0, 0, 1.4);
        hedgehogGroup.add(nose);

        // Eyes
