        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.2, 0.2, 1.25);
        hedgehogGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.2, 0.2, 1.25);
        hedgehogGroup.add(rightEye);

        // Add to scene
        scene.add(hedgehogGroup);

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Gentle breathing/bobbing
            const time = Date.now() * 0.001;
            hedgehogGroup.position.y = Math.sin(time) * 0.05;
            hedgehogGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
