<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050510);
scene.fog = new THREE.FogExp2(0x050510, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2.5, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.8, 0);
controls.maxPolarAngle = Math.PI * 0.8;

// --- Environment (procedural) ---
const cubeRT = new THREE.WebGLCubeRenderTarget(256);
const cubeCamera = new THREE.CubeCamera(0.1, 50, cubeRT);
scene.environment = cubeRT.texture;

// Background stars for reflections
const starGeo = new THREE.BufferGeometry();
const starCount = 2000;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++) {
  starPos[i] = (Math.random() - 0.5) * 60;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.05, sizeAttenuation: true });
const stars = new THREE.Points(starGeo, starMat);
scene.add(stars);

// Colored nebula lights in the environment
const envColors = [0x4400aa, 0x0044aa, 0x006644, 0x662200];
envColors.forEach((c, i) => {
  const light = new THREE.PointLight(c, 3, 20);
  const angle = (i / envColors.length) * Math.PI * 2;
  light.position.set(Math.cos(angle) * 5, 2 + Math.sin(i) * 2, Math.sin(angle) * 5);
  scene.add(light);
});

// --- Crystal Ball ---
const ballRadius = 1.2;
const ballGeo = new THREE.SphereGeometry(ballRadius, 128, 128);
const ballMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.97,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.05,
  ior: 1.52,
  thickness: 1.2,
  specularIntensity: 1,
  specularColor: 0xffffff,
  envMapIntensity: 1.5,
  clearcoat: 1,
  clearcoatRoughness: 0.05,
  attenuationColor: new THREE.Color(0.6, 0.7, 1.0),
  attenuationDistance: 2,
});
const ball = new THREE.Mesh(ballGeo, ballMat);
ball.position.y = 2.8;
scene.add(ball);

// --- Inner Glow Particles ---
const innerCount = 300;
const innerGeo = new THREE.BufferGeometry();
const innerPositions = new Float32Array(innerCount * 3);
const innerSizes = new Float32Array(innerCount);
for (let i = 0; i < innerCount; i++) {
  const r = Math.random() * ballRadius * 0.85;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  innerPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  innerPositions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  innerPositions[i * 3 + 2] = r * Math.cos(phi);
  innerSizes[i] = Math.random() * 3 + 1;
}
innerGeo.setAttribute('position', new THREE.BufferAttribute(innerPositions, 3));
innerGeo.setAttribute('size', new THREE.BufferAttribute(innerSizes, 1));

const innerMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0.4, 0.6, 1.0) },
  },
  vertexShader: `
    attribute float size;
    uniform float uTime;
    varying float vAlpha;
    void main() {
      vec3 pos = position;
      pos.y += sin(uTime * 0.5 + position.x * 3.0) * 0.05;
      pos.x += cos(uTime * 0.3 + position.z * 2.0) * 0.03;
      vAlpha = 0.4 + 0.6 * sin(uTime + position.y * 5.0);
      vec4 mvPos = modelViewMatrix * vec4(pos, 1.0);
      gl_PointSize = size * (200.0 / -mvPos.z);
      gl_Position = projectionMatrix * mvPos;
    }
  `,
  fragmentShader: `
    uniform vec3 uColor;
    varying float vAlpha;
    void main() {
      float d = length(gl_PointCoord - 0.5);
      if (d > 0.5) discard;
      float alpha = smoothstep(0.5, 0.0, d) * vAlpha * 0.6;
      gl_FragColor = vec4(uColor, alpha);
    }
  `,
  transparent: true,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});
const innerParticles = new THREE.Points(innerGeo, innerMat);
innerParticles.position.copy(ball.position);
scene.add(innerParticles);

// --- Inner Mist (volumetric-like fog sphere) ---
const mistGeo = new THREE.SphereGeometry(ballRadius * 0.7, 32, 32);
const mistMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vPosition;
    void main() {
      vNormal = normalize(normalMatrix * normal);
      vPosition = position;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;
    void main() {
      float fresnel = pow(1.0 - abs(dot(vNormal, vec3(0.0, 0.0, 1.0))), 2.0);
      float noise = sin(vPosition.x * 4.0 + uTime) * sin(vPosition.y * 4.0 + uTime * 0.7) * sin(vPosition.z * 4.0 + uTime * 0.5);
      float alpha = fresnel * (0.3 + 0.2 * noise);
      gl_FragColor = vec4(0.3, 0.5, 1.0, alpha * 0.3);
    }
  `,
  transparent: true,
  depthWrite: false,
  side: THREE.BackSide,
});
const mist = new THREE.Mesh(mistGeo, mistMat);
mist.position.copy(ball.position);
scene.add(mist);

// --- Pedestal ---
