  metalness: 0.8,
  roughness: 0.3,
});
const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
pedestal.position.y = 1.6;
scene.add(pedestal);

// Pedestal ring
const ringGeo = new THREE.TorusGeometry(0.65, 0.04, 16, 64);
const ringMat = new THREE.MeshStandardMaterial({ color: 0x4444aa, metalness: 1, roughness: 0.2, emissive: 0x222266, emissiveIntensity: 0.3 });
const ring = new THREE.Mesh(ringGeo, ringMat);
ring.rotation.x = Math.PI / 2;
ring.position.y = 1.9;
scene.add(ring);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0x111122, 0.5);
scene.add(ambientLight);

const mainLight = new THREE.DirectionalLight(0xaabbff, 2);
mainLight.position.set(3, 5, 4);
scene.add(mainLight);

const rimLight = new THREE.DirectionalLight(0x6644aa, 1.5);
rimLight.position.set(-3, 3, -2);
scene.add(rimLight);

const bottomLight = new THREE.PointLight(0x3344aa, 2, 8);
bottomLight.position.set(0, 0.5, 0);
scene.add(bottomLight);

// --- Floor ---
const floorGeo = new THREE.CircleGeometry(8, 64);
const floorMat = new THREE.MeshStandardMaterial({ color: 0x0a0a15, metalness: 0.5, roughness: 0.7 });
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = 1.2;
scene.add(floor);

// --- Animation ---
const clock = new THREE.Clock();
let envUpdateCounter = 0;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  innerMat.uniforms.uTime.value = t;
  mistMat.uniforms.uTime.value = t;

  // Gentle floating
  ball.position.y = 2.8 + Math.sin(t * 0.5) * 0.05;
  innerParticles.position.y = ball.position.y;
  mist.position.y = ball.position.y;

  stars.rotation.y = t * 0.01;

  // Update cube camera infrequently for performance
  envUpdateCounter++;
  if (envUpdateCounter % 60 === 0) {
    ball.visible = false;
    innerParticles.visible = false;
    mist.visible = false;
    cubeCamera.position.copy(ball.position);
    cubeCamera.update(renderer, scene);
    ball.visible = true;
    innerParticles.visible = true;
    mist.visible = true;
  }

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**Features:**

- **Glass-like sphere** using `MeshPhysicalMaterial` with transmission, IOR 1.52, and attenuation color for realistic refraction
- **Inner glow particles** with additive blending that gently drift and pulse
- **Volumetric mist layer** (back-face shader) simulating fog inside the ball
- **Metallic pedestal** with a glowing ring
- **CubeCamera environment map** updated every 60 frames so the ball reflects its surroundings
- **Starfield background** for atmospheric reflections
- **OrbitControls** — drag to rotate, scroll to zoom
- Gentle floating animation on the ball

