        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // Peacock Group
        const peacock = new THREE.Group();
        scene.add(peacock);

        // Materials
        const bodyMat = new THREE.MeshStandardMaterial({ color: 0x006400, roughness: 0.4 }); // Dark Green
        const headMat = new THREE.MeshStandardMaterial({ color: 0x228B22, roughness: 0.4 }); // Forest Green
        const beakMat = new THREE.MeshStandardMaterial({ color: 0xFFA500 }); // Orange
        const eyeMat = new THREE.MeshStandardMaterial({ color: 0x000000 }); // Black
        const featherStemMat = new THREE.MeshStandardMaterial({ color: 0x004d00 }); // Darker Green
        const featherEyeMat = new THREE.MeshStandardMaterial({ color: 0x0000FF, emissive: 0x000044 }); // Blue
        const featherRingMat = new THREE.MeshStandardMaterial({ color: 0xFFD700 }); // Gold

        // 1. Body
        const bodyGeo = new THREE.CylinderGeometry(0.8, 1.2, 2.5, 16);
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = 2.5;
        body.castShadow = true;
        peacock.add(body);

        // 2. Neck
        const neckGeo = new THREE.CylinderGeometry(0.3, 0.4, 2, 12);
        const neck = new THREE.Mesh(neckGeo, headMat);
        neck.position.y = 4.2;
        neck.castShadow = true;
        peacock.add(neck);

        // 3. Head
        const headGeo = new THREE.SphereGeometry(0.45, 16, 16);
        const head = new THREE.Mesh(headGeo, headMat);
        head.position.y = 5.5;
        head.castShadow = true;
        peacock.add(head);

        // 4. Beak
        const beakGeo = new THREE.ConeGeometry(0.15, 0.6, 8);
        const beak = new THREE.Mesh(beakGeo, beakMat);
        beak.rotation.x = Math.PI / 2;
        beak.position.set(0, 5.5, 0.6);
        peacock.add(beak);

        // 5. Crest (Crown)
        for (let i = 0; i < 5; i++) {
            const stemGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.8);
            const stem = new THREE.Mesh(stemGeo, featherStemMat);
            const tipGeo = new THREE.SphereGeometry(0.08);
            const tip = new THREE.Mesh(tipGeo, featherEyeMat);

            const angle = (i - 2) * 0.3;
            stem.position.set(Math.sin(angle) * 0.3, 6.1, Math.cos(angle) * 0.3);
            stem.rotation.z = Math.sin(angle) * 0.5;
            stem.rotation.x = Math.cos(angle) * 0.5;

            tip.position.set(0, 0.4, 0);
            stem.add(tip);
            peacock.add(stem);
        }

        // 6. Tail Feathers (The Fan)
        const feathersGroup = new THREE.Group();
        feathersGroup.position.y = 2.5;
        peacock.add(feathersGroup);

        function createFeather(angle) {
            const featherGroup = new THREE.Group();

            // Stem
            const stemGeo = new THREE.CylinderGeometry(0.05, 0.08, 6, 8);
            const stem = new THREE.Mesh(stemGeo, featherStemMat);
            stem.position.y = 3; // Half height
            featherGroup.add(stem);

            // The "Eye" of the feather
            const eyeGroup = new THREE.Group();
            eyeGroup.position.y = 6;

            // Blue center
            const blueGeo = new THREE.SphereGeometry(0.4, 16, 16);
            const blueMesh = new THREE.Mesh(blueGeo, featherEyeMat);
            eyeGroup.add(blueMesh);

            // Gold ring
            const ringGeo = new THREE.TorusGeometry(0.35, 0.05, 8, 16);
            const ringMesh = new THREE.Mesh(ringGeo, featherRingMat);
            eyeGroup.add(ringMesh);

            // Green outer rim (simulated with a slightly larger sphere behind)
            const rimGeo = new THREE.SphereGeometry(0.45, 16, 16);
            const rimMesh = new THREE.Mesh(rimGeo, bodyMat);
            rimMesh.position.z = -0.05;
            eyeGroup.add(rimMesh);

            featherGroup.add(eyeGroup);

            // Rotate the whole feather to fan out
            featherGroup.rotation.z = angle;
            featherGroup.rotation.y = angle * 0.5; // Slight twist

            return featherGroup;
        }

        // Create a fan of feathers
        const numFeathers = 25;
        const spreadAngle = Math.PI * 1.2; // 216 degrees spread
        const startAngle = -spreadAngle / 2;

        for (let i = 0; i < numFeathers; i++) {
            const t = i / (numFeathers - 1);
            const angle = startAngle + t * spreadAngle;
            const feather = createFeather(angle);
            feathersGroup.add(feather);
        }

        // Ground Plane
        const planeGeo = new THREE.PlaneGeometry(50, 50);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x2a2a4e });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle breathing animation
            const time = Date.now() * 0.001;
            peacock.position.y = Math.sin(time) * 0.1;

            // Subtle tail sway
            feathersGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
