<title>Snowflake</title>
<style>
  * { margin: 0; padding: 0; }
  body { overflow: hidden; background: #000; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x050510, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setClearColor(0x050510);
document.body.appendChild(renderer.domElement);

/* ── Build snowflake geometry ── */
const points = [];

function addLine(a, b) {
  points.push(a[0], a[1], a[2], b[0], b[1], b[2]);
}

function branch(origin, angle, length, depth, spread) {
  if (depth <= 0 || length < 0.02) return;
  const end = [
    origin[0] + Math.cos(angle) * length,
    origin[1] + Math.sin(angle) * length,
    0
  ];
  addLine(origin, end);

  const subLen = length * 0.42;
  const subSpread = spread + 0.15;
  branch(end, angle + subSpread, subLen, depth - 1, spread);
  branch(end, angle - subSpread, subLen, depth - 1, spread);
  branch(end, angle + subSpread * 0.5, subLen * 0.7, depth - 2, spread * 0.8);
  branch(end, angle - subSpread * 0.5, subLen * 0.7, depth - 2, spread * 0.8);
}

for (let i = 0; i < 6; i++) {
  const a = (Math.PI / 3) * i;
  branch([0, 0, 0], a, 1.0, 6, 0.6);
}

const geo = new THREE.BufferGeometry();
geo.setAttribute('position', new THREE.Float32BufferAttribute(points, 3));

const mat = new THREE.LineBasicMaterial({
  color: 0xc8e4ff,
  transparent: true,
  opacity: 0.85,
  linewidth: 1,
});

const snowflake = new THREE.LineSegments(geo, mat);
scene.add(snowflake);

/* ── Glowing node at center ── */
const coreGeo = new THREE.SphereGeometry(0.06, 16, 16);
const coreMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
scene.add(new THREE.Mesh(coreGeo, coreMat));

/* ── Background snow particles ── */
const N = 600;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(N * 3);
const pVel = [];
for (let i = 0; i < N; i++) {
  pPos[i * 3]     = (Math.random() - 0.5) * 30;
  pPos[i * 3 + 1] = (Math.random() - 0.5) * 30;
  pPos[i * 3 + 2] = (Math.random() - 0.5) * 20 - 5;
  pVel.push(0.005 + Math.random() * 0.015, (Math.random() - 0.5) * 0.003);
}
pGeo.setAttribute('position', new THREE.Float32BufferAttribute(pPos, 3));
const pMat = new THREE.PointsMaterial({
  color: 0xaac8ee,
  size: 0.04,
  transparent: true,
  opacity: 0.6,
});
const particles = new THREE.Points(pGeo, pMat);
scene.add(particles);

/* ── Animate ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  snowflake.rotation.z = t * 0.15;
  snowflake.rotation.x = Math.sin(t * 0.1) * 0.15;
  snowflake.rotation.y = Math.cos(t * 0.13) * 0.1;

  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < N; i++) {
    pos[i * 3 + 1] -= pVel[i * 2];
    pos[i * 3]     += pVel[i * 2 + 1] + Math.sin(t + i) * 0.001;
    if (pos[i * 3 + 1] < -15) {
      pos[i * 3 + 1] = 15;
      pos[i * 3]     = (Math.random() - 0.5) * 30;
    }
  }
  particles.geometry.attributes.position.needsUpdate = true;

  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What it does:**

- **Procedural snowflake** — 6-fold symmetric crystalline structure built from 6 recursive branching arms (depth 6), drawn as `LineSegments` in icy blue-white.
- **Gentle 3D rotation** — slow tumbling on all three axes with sinusoidal wobble.
- **Falling snow particles** — 600 drifting background particles with slight horizontal drift for atmosphere.
- **Fog & dark background** — deep navy-black with exponential fog for depth.
- **Responsive** — handles window resize.

