        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x88ccff, 0.5);
        backLight.position.set(-5, 5, -5);
        scene.add(backLight);

        // Hummingbird Construction
        const hummingbird = new THREE.Group();

        // Materials
        const bodyMat = new THREE.MeshStandardMaterial({ color: 0x2ecc71, roughness: 0.4, metalness: 0.1 }); // Emerald Green
        const headMat = new THREE.MeshStandardMaterial({ color: 0x27ae60, roughness: 0.4 }); // Darker Green
        const throatMat = new THREE.MeshStandardMaterial({ color: 0xe74c3c, roughness: 0.2, metalness: 0.3 }); // Ruby Red
        const beakMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.2 });
        const wingMat = new THREE.MeshStandardMaterial({ color: 0x1abc9c, roughness: 0.5, side: THREE.DoubleSide });
        const tailMat = new THREE.MeshStandardMaterial({ color: 0x16a085, roughness: 0.5 });

        // 1. Body (Capsule-like shape using sphere + cylinder)
        const bodyGeo = new THREE.SphereGeometry(0.6, 32, 32);
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.scale.set(1, 0.8, 1.5);
        body.castShadow = true;
        hummingbird.add(body);

        // 2. Head
        const headGeo = new THREE.SphereGeometry(0.45, 32, 32);
        const head = new THREE.Mesh(headGeo, headMat);
        head.position.set(0, 0.3, 0.8);
        head.castShadow = true;
        hummingbird.add(head);

        // 3. Throat (Gorget)
        const throatGeo = new THREE.SphereGeometry(0.35, 32, 32);
        const throat = new THREE.Mesh(throatGeo, throatMat);
        throat.position.set(0, -0.1, 1.0);
        throat.scale.set(1, 0.8, 0.8);
        hummingbird.add(throat);

        // 4. Beak
        const beakGeo = new THREE.CylinderGeometry(0.02, 0.01, 1.5, 8);
        const beak = new THREE.Mesh(beakGeo, beakMat);
        beak.rotation.x = Math.PI / 2;
        beak.position.set(0, 0.2, 1.8);
        hummingbird.add(beak);

        // 5. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.06, 16, 16);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(0.3, 0.4, 1.0);
        hummingbird.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(-0.3, 0.4, 1.0);
        hummingbird.add(rightEye);

        // 6. Wings (Pivot groups for animation)
        const wingPivotLeft = new THREE.Group();
        wingPivotLeft.position.set(0.5, 0.2, 0.2);
        hummingbird.add(wingPivotLeft);

        const wingGeo = new THREE.BoxGeometry(0.1, 2.5, 0.8);
        // Taper the wing slightly by modifying vertices or just using a cone? 
        // Let's use a custom shape for a better wing look
        const wingShape = new THREE.Shape();
        wingShape.moveTo(0, 0);
        wingShape.lineTo(0.1, 1.5);
        wingShape.lineTo(-0.1, 1.5);
        wingShape.lineTo(-0.2, 0);

        const extrudeSettings = { depth: 0.05, bevelEnabled: false };
        const wingMeshGeo = new THREE.ExtrudeGeometry(wingShape, extrudeSettings);

        const leftWing = new THREE.Mesh(wingMeshGeo, wingMat);
        leftWing.rotation.x = -Math.PI / 2;
        leftWing.position.set(0, 0, 0);
        leftWing.castShadow = true;
        wingPivotLeft.add(leftWing);

        const wingPivotRight = new THREE.Group();
        wingPivotRight.position.set(-0.5, 0.2, 0.2);
        hummingbird.add(wingPivotRight);

        const rightWing = new THREE.Mesh(wingMeshGeo, wingMat);
        rightWing.rotation.x = -Math.PI / 2;
        rightWing.rotation.y = Math.PI; // Flip for other side
        rightWing.castShadow = true;
        wingPivotRight.add(rightWing);

        // 7. Tail
        const tailGroup = new THREE.Group();
        tailGroup.position.set(0, -0.2, -0.8);
        tailGroup.rotation.x = -0.5;
        hummingbird.add(tailGroup);

        const tailFeatherGeo = new THREE.ConeGeometry(0.15, 1.2, 8);
        const centerFeather = new THREE.Mesh(tailFeatherGeo, tailMat);
        centerFeather.rotation.x = -Math.PI / 2;
        centerFeather.position.z = 0.6;
        tailGroup.add(centerFeather);

        const sideFeatherGeo = new THREE.ConeGeometry(0.1, 1.0, 8);
        const leftFeather = new THREE.Mesh(sideFeatherGeo, tailMat);
        leftFeather.rotation.x = -Math.PI / 2;
        leftFeather.rotation.z = 0.3;
        leftFeather.position.set(0.2, 0, 0.5);
        tailGroup.add(leftFeather);

        const rightFeather = new THREE.Mesh(sideFeatherGeo, tailMat);
        rightFeather.rotation.x = -Math.PI / 2;
        rightFeather.rotation.z = -0.3;
        rightFeather.position.set(-0.2, 0, 0.5);
        tailGroup.add(rightFeather);

        // Add bird to scene
        scene.add(hummingbird);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Hover effect
            hummingbird.position.y = Math.sin(time * 2) * 0.2;
            hummingbird.rotation.z = Math.sin(time * 1.5) * 0.05;

            // Wing Flapping (Fast!)
            const flapSpeed = 20;
            const flapAngle = Math.sin(time * flapSpeed) * 0.5;

            wingPivotLeft.rotation.z = flapAngle;
            wingPivotRight.rotation.z = -flapAngle;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
