<body>
<div id="info">🥞 Drag to orbit · Scroll to zoom</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a0e05);
scene.fog = new THREE.FogExp2(0x1a0e05, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(5, 6, 7);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI / 2 + 0.3;
controls.minDistance = 3;
controls.maxDistance = 20;
controls.update();

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.6);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xfff0dd, 2.5);
keyLight.position.set(5, 8, 4);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 25;
keyLight.shadow.camera.left = -6;
keyLight.shadow.camera.right = 6;
keyLight.shadow.camera.top = 6;
keyLight.shadow.camera.bottom = -6;
keyLight.shadow.bias = -0.001;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xffccaa, 0.8);
fillLight.position.set(-4, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff9944, 1.5, 15);
rimLight.position.set(-3, 5, -4);
scene.add(rimLight);

const warmGlow = new THREE.PointLight(0xffaa55, 0.6, 10);
warmGlow.position.set(0, 4, 0);
scene.add(warmGlow);

// --- Materials ---
function pancakeMaterial(baseColor, darkColor) {
  return new THREE.MeshStandardMaterial({
    color: baseColor,
    roughness: 0.75,
    metalness: 0.0,
    flatShading: false,
  });
}

// --- Helpers ---
function perturbVertices(geometry, radius, amplitude) {
  const pos = geometry.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const z = pos.getZ(i);
    if (Math.abs(y) < 0.05) {
      const angle = Math.atan2(z, x);
      const dist = Math.sqrt(x * x + z * z);
      const bump = Math.sin(angle * 7) * amplitude +
                   Math.cos(angle * 11 + 1.3) * amplitude * 0.5 +
                   Math.sin(angle * 3 + 0.7) * amplitude * 0.3;
      const scale = 1 + bump / radius;
      pos.setX(i, x * scale);
      pos.setZ(i, z * scale);
    }
  }
  pos.needsUpdate = true;
  geometry.computeVertexNormals();
}

function createPancake(radius, height, color, darkColor) {
  const segments = 64;
  const geo = new THREE.CylinderGeometry(radius, radius, height, segments, 2);
  perturbVertices(geo, radius, 0.08 + Math.random() * 0.06);

  // Slightly randomize top/bottom face heights for wobbly look
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const y = pos.getY(i);
    if (y > 0) {
      pos.setY(i, y + (Math.random() - 0.5) * 0.02);
    }
  }
  pos.needsUpdate = true;
  geo.computeVertexNormals();

  const mat = pancakeMaterial(color, darkColor);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// --- Plate ---
const plateGeo = new THREE.CylinderGeometry(3.5, 3.2, 0.2, 64);
const plateMat = new THREE.MeshStandardMaterial({
  color: 0xfaf5ee,
  roughness: 0.3,
  metalness: 0.05,
});
const plate = new THREE.Mesh(plateGeo, plateMat);
plate.position.y = -0.1;
plate.receiveShadow = true;
scene.add(plate);

// Plate rim
const rimGeo = new THREE.TorusGeometry(3.35, 0.12, 8, 64);
const rimMat = new THREE.MeshStandardMaterial({ color: 0xf0e6d6, roughness: 0.3 });
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = -0.05;
rim.receiveShadow = true;
scene.add(rim);

// --- Pancake stack ---
const pancakeData = [
  { radius: 1.8, height: 0.18, color: 0xd4943a, darkColor: 0x8b5e1a },
  { radius: 1.75, height: 0.2,  color: 0xc98830, darkColor: 0x7d5218 },
  { radius: 1.85, height: 0.16, color: 0xdda04a, darkColor: 0x9a6a20 },
  { radius: 1.7,  height: 0.22, color: 0xc07e28, darkColor: 0x704814 },
  { radius: 1.8,  height: 0.17, color: 0xd89840, darkColor: 0x8a5c1c },
];

const stack = new THREE.Group();
let currentY = 0.05;

pancakeData.forEach((data, i) => {
  const pancake = createPancake(data.radius, data.height, data.color, data.darkColor);
  pancake.position.y = currentY + data.height / 2;
  pancake.rotation.y = (i * 0.4 + Math.random() * 0.3) ;
  // Slight offset for natural look
  pancake.position.x = (Math.random() - 0.5) * 0.08;
  pancake.position.z = (Math.random() - 0.5) * 0.08;
  stack.add(pancake);
  currentY += data.height;
});
scene.add(stack);

// --- Butter pat ---
const butterGeo = new THREE.BoxGeometry(0.5, 0.25, 0.4);
// Round the butter a bit
const bPos = butterGeo.attributes.position;
for (let i = 0; i < bPos.count; i++) {
  const x = bPos.getX(i);
  const y = bPos.getY(i);
  const z = bPos.getZ(i);
  const n = 0.95 + Math.sin(x * 8) * 0.03 + Math.cos(z * 6) * 0.03;
  bPos.setX(i, x * n);
  bPos.setY(i, y * n);
  bPos.setZ(i, z * n);
}
bPos.needsUpdate = true;
butterGeo.computeVertexNormals();

const butterMat = new THREE.MeshStandardMaterial({
  color: 0xffee88,
  roughness: 0.4,
  metalness: 0.0,
});
const butter = new THREE.Mesh(butterGeo, butterMat);
butter.position.y = currentY + 0.125;
butter.rotation.y = 0.5;
butter.castShadow = true;
butter.receiveShadow = true;
stack.add(butter);

// --- Syrup drops (small spheres on sides) ---
function createSyrupDrop(x, y, z) {
  const geo = new THREE.SphereGeometry(0.08 + Math.random() * 0.06, 8, 6);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x4a2800,
    roughness: 0.3,
    metalness: 0.1,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  return mesh;
}

// Add a few syrup drips
for (let i = 0; i < 8; i++) {
  const angle = Math.random() * Math.PI * 2;
  const r = 1.5 + Math.random() * 0.3;
  const y = 0.2 + Math.random() * (currentY - 0.2);
  const drop = createSyrupDrop(
    Math.cos(angle) * r,
    y,
    Math.sin(angle) * r
  );
  drop.scale.y = 0.6 + Math.random() * 0.4;
  stack.add(drop);
}

// Syrup pool on top
const syrupGeo = new THREE.CircleGeometry(0.8, 32);
const syrupMat = new THREE.MeshStandardMaterial({
  color: 0x3d1a00,
  roughness: 0.2,
  metalness: 0.15,
  transparent: true,
  opacity: 0.85,
  side: THREE.DoubleSide,
});
const syrup = new THREE.Mesh(syrupGeo, syrupMat);
syrup.rotation.x = -Math.PI / 2;
syrup.position.y = currentY + 0.005;
stack.add(syrup);

// --- Table surface ---
const tableGeo = new THREE.CylinderGeometry(20, 20, 0.5, 64);
const tableMat = new THREE.MeshStandardMaterial({
  color: 0x3d2b1f,
  roughness: 0.8,
  metalness: 0.0,
});
const table = new THREE.Mesh(tableGeo, tableMat);
table.position.y = -0.5;
table.receiveShadow = true;
scene.add(table);

// --- Floating particles (warm dust motes) ---
const particleCount = 60;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);
const particleSpeeds = [];
for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3] = (Math.random() - 0.5) * 12;
  particlePositions[i * 3 + 1] = Math.random() * 8;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 12;
  particleSpeeds.push(0.002 + Math.random() * 0.005);
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0xffcc88,
  size: 0.04,
  transparent: true,
  opacity: 0.5,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle steam-like bob on the stack
  stack.position.y = Math.sin(t * 0.8) * 0.03;

  // Butter slowly melts (scales down in Y, up in XZ)
  const meltProgress = Math.min(t * 0.03, 0.3);
  butter.scale.y = 1 - meltProgress * 0.5;
  butter.scale.x = 1 + meltProgress * 0.3;
  butter.scale.z = 1 + meltProgress * 0.3;
  butter.position.y = currentY + 0.125 * butter.scale.y;

  // Animate particles
  const pPos = particles.geometry.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    let y = pPos.getY(i);
    y += particleSpeeds[i];
    if (y > 8) y = 0;
    pPos.setY(i, y);
    pPos.setX(i, pPos.getX(i) + Math.sin(t + i) * 0.001);
  }
  pPos.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
