  #info p { font-size: 0.8rem; opacity: 0.6; margin-top: 6px; }
</style>
</head>
<body>
<div id="info">
  <h1>DNA DOUBLE HELIX</h1>
  <p>Drag to rotate · Scroll to zoom</p>
</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';

// ── Scene Setup ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x020810, 0.012);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 0, 32);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post-processing (bloom) ──────────────────────────────────
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 0.8, 0.4, 0.85
);
composer.addPass(bloom);

// ── Controls ─────────────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 1.2;
controls.maxDistance = 70;
controls.minDistance = 10;

// ── Lighting ─────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x334466, 1.5));

const dirLight = new THREE.DirectionalLight(0xffffff, 2);
dirLight.position.set(10, 20, 15);
scene.add(dirLight);

const pointA = new THREE.PointLight(0x4488ff, 3, 60);
pointA.position.set(-15, 10, 10);
scene.add(pointA);

const pointB = new THREE.PointLight(0xff6644, 2, 60);
pointB.position.set(15, -10, -10);
scene.add(pointB);

// ── DNA Parameters ───────────────────────────────────────────
const NUM_PAIRS    = 60;
const RADIUS       = 3.5;
const HELIX_STEP   = 0.38;          // vertical spacing per pair
const FULL_HEIGHT  = NUM_PAIRS * HELIX_STEP;
const RISE_PER_PAIR = HELIX_STEP;

// Base-pair color palette
const BASE_COLORS = [
  { a: 0xff4466, t: 0x44aaff },   // A–T  red ↔ blue
  { a: 0x44dd66, t: 0xddaa22 },   // G–C  green ↔ gold
  { a: 0xff4466, t: 0x44aaff },   // A–T
  { a: 0x44dd66, t: 0xddaa22 },   // G–C
];

function getRandomBasePair() {
  return BASE_COLORS[Math.floor(Math.random() * BASE_COLORS.length)];
}

// ── Helper: helix point ──────────────────────────────────────
function helixPoint(i, strandOffset = 0) {
  const angle = i * Math.PI * 2 / 10 + strandOffset;
  return new THREE.Vector3(
    RADIUS * Math.cos(angle),
    (i - NUM_PAIRS / 2) * RISE_PER_PAIR,
    RADIUS * Math.sin(angle)
  );
}

// ── Build backbone curves ────────────────────────────────────
function buildBackboneStrand(offset) {
  const pts = [];
  for (let i = 0; i < NUM_PAIRS; i++) pts.push(helixPoint(i, offset));
  const curve = new THREE.CatmullRomCurve3(pts);
  const geo = new THREE.TubeGeometry(curve, NUM_PAIRS * 6, 0.12, 8, false);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x8899bb,
    metalness: 0.6,
    roughness: 0.25,
    emissive: 0x223344,
    emissiveIntensity: 0.3,
  });
  return new THREE.Mesh(geo, mat);
}

scene.add(buildBackboneStrand(0));
scene.add(buildBackboneStrand(Math.PI));

// ── Build base-pair rungs ────────────────────────────────────
const rungGroup = new THREE.Group();
scene.add(rungGroup);

const sphereGeo = new THREE.SphereGeometry(0.22, 12, 12);

for (let i = 0; i < NUM_PAIRS; i++) {
  const p1 = helixPoint(i, 0);
  const p2 = helixPoint(i, Math.PI);
  const bp = getRandomBasePair();

  // Rung cylinder
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const rungGeo = new THREE.CylinderGeometry(0.06, 0.06, len, 6);
  const rungMat = new THREE.MeshStandardMaterial({
    color: 0x667788,
    metalness: 0.4,
    roughness: 0.5,
  });
  const rung = new THREE.Mesh(rungGeo, rungMat);
  const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
  rung.position.copy(mid);
  rung.lookAt(p2);
  rung.rotateX(Math.PI / 2);
  rungGroup.add(rung);

  // Nucleotide spheres
  const s1 = new THREE.Mesh(sphereGeo, new THREE.MeshStandardMaterial({
    color: bp.a, emissive: bp.a, emissiveIntensity: 0.5, metalness: 0.3, roughness: 0.3,
  }));
  s1.position.copy(p1);
  rungGroup.add(s1);

  const s2 = new THREE.Mesh(sphereGeo, new THREE.MeshStandardMaterial({
    color: bp.t, emissive: bp.t, emissiveIntensity: 0.5, metalness: 0.3, roughness: 0.3,
  }));
  s2.position.copy(p2);
  rungGroup.add(s2);
}

// ── Floating particles ───────────────────────────────────────
const particleCount = 600;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(particleCount * 3);
const pSizes = new Float32Array(particleCount);
for (let i = 0; i < particleCount; i++) {
  pPos[i * 3]     = (Math.random() - 0.5) * 60;
  pPos[i * 3 + 1] = (Math.random() - 0.5) * 60;
  pPos[i * 3 + 2] = (Math.random() - 0.5) * 60;
  pSizes[i] = Math.random() * 2 + 0.5;
}
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
pGeo.setAttribute('size', new THREE.BufferAttribute(pSizes, 1));

const pMat = new THREE.PointsMaterial({
  color: 0x6699cc,
  size: 0.12,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
});
const particles = new THREE.Points(pGeo, pMat);
scene.add(particles);

// ── Central glow ring (decorative) ───────────────────────────
const ringGeo = new THREE.TorusGeometry(RADIUS * 1.6, 0.03, 8, 80);
const ringMat = new THREE.MeshBasicMaterial({ color: 0x3366aa, transparent: true, opacity: 0.25 });
const ring = new THREE.Mesh(ringGeo, ringMat);
ring.rotation.x = Math.PI / 2;
scene.add(ring);

// ── Animation ────────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle DNA "breathing"
  rungGroup.children.forEach((child, idx) => {
    if (child.geometry.type === 'SphereGeometry') {
      const phase = (idx * 0.15) % (Math.PI * 2);
      child.scale.setScalar(1 + 0.12 * Math.sin(t * 2 + phase));
    }
  });

  // Rotate particles slowly
  particles.rotation.y = t * 0.03;
  particles.rotation.x = Math.sin(t * 0.01) * 0.1;

  // Ring pulse
  ring.material.opacity = 0.15 + 0.1 * Math.sin(t * 1.5);
  ring.scale.setScalar(1 + 0.05 * Math.sin(t * 0.8));

  controls.update();
  composer.render();
}

animate();

// ── Resize ───────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
