<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Rowboat</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
