<body>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.FogExp2(0x87CEEB, 0.008);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 500);
camera.position.set(8, 5, 12);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lights ---
const ambient = new THREE.AmbientLight(0x6688aa, 0.6);
scene.add(ambient);

const sun = new THREE.DirectionalLight(0xfff4e0, 1.2);
sun.position.set(10, 15, 8);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 50;
sun.shadow.camera.left = -15;
sun.shadow.camera.right = 15;
sun.shadow.camera.top = 15;
sun.shadow.camera.bottom = -15;
scene.add(sun);

const hemi = new THREE.HemisphereLight(0x87CEEB, 0x362907, 0.4);
scene.add(hemi);

// --- Materials ---
const hullMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.7, metalness: 0.1 });
const innerMat = new THREE.MeshStandardMaterial({ color: 0x654321, roughness: 0.8 });
const seatMat = new THREE.MeshStandardMaterial({ color: 0x5C3317, roughness: 0.6 });
const oarMat = new THREE.MeshStandardMaterial({ color: 0xA0522D, roughness: 0.5 });
const bladeMat = new THREE.MeshStandardMaterial({ color: 0x8B6914, roughness: 0.6 });
const metalMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.3, metalness: 0.8 });
const waterMat = new THREE.MeshStandardMaterial({
  color: 0x1a6b8a,
  roughness: 0.2,
  metalness: 0.3,
  transparent: true,
  opacity: 0.85,
});

// --- Hull ---
function createHull() {
  const group = new THREE.Group();

  // Side profile shape (XZ plane view from side)
  const shape = new THREE.Shape();
  const len = 5.0, deep = 0.7, bowUp = 0.5, sternUp = 0.35;
  const bottomFwd = -len / 2 + 0.6, bottomAft = len / 2 - 0.6;

  shape.moveTo(-len / 2, bowUp);
  shape.quadraticCurveTo(-len / 2 - 0.3, bowUp + 0.4, -len / 2 + 0.3, deep);
  shape.lineTo(bottomFwd, 0.15);
  shape.quadraticCurveTo(0, -0.1, bottomAft, 0.15);
  shape.lineTo(len / 2 - 0.3, deep);
  shape.quadraticCurveTo(len / 2 + 0.3, sternUp + 0.4, len / 2, sternUp);
  shape.quadraticCurveTo(len / 2 - 0.15, -0.05, len / 2 - 0.5, deep - 0.1);
  shape.lineTo(-len / 2 + 0.5, deep - 0.1);
  shape.quadraticCurveTo(-len / 2 + 0.15, -0.05, -len / 2, bowUp);

  const extrudeSettings = {
    depth: 1.8,
    bevelEnabled: true,
    bevelThickness: 0.15,
    bevelSize: 0.15,
    bevelOffset: 0,
    bevelSegments: 5,
    steps: 1
  };

  const hullGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  hullGeo.center();
  const hull = new THREE.Mesh(hullGeo, hullMat);
  hull.rotation.x = -Math.PI / 2;
  hull.position.y = 0.55;
  hull.castShadow = true;
  hull.receiveShadow = true;
  group.add(hull);

  // Inner hull (darker, slightly smaller)
  const innerShape = new THREE.Shape();
  const il = len - 0.6, ideep = 0.5;
  innerShape.moveTo(-il / 2, 0.2);
  innerShape.quadraticCurveTo(-il / 2 + 0.2, 0.0, -il / 2 + 0.5, -0.1);
  innerShape.lineTo(il / 2 - 0.5, -0.1);
  innerShape.quadraticCurveTo(il / 2 - 0.2, 0.0, il / 2, 0.2);
  innerShape.lineTo(-il / 2, 0.2);

  const innerGeo = new THREE.ExtrudeGeometry(innerShape, {
    depth: 1.5, bevelEnabled: true, bevelThickness: 0.08, bevelSize: 0.08, bevelSegments: 3
  });
  innerGeo.center();
  const inner = new THREE.Mesh(innerGeo, innerMat);
  inner.rotation.x = -Math.PI / 2;
  inner.position.y = 0.85;
  inner.receiveShadow = true;
  group.add(inner);

  return group;
}

// --- Seats (Thwarts) ---
function createSeat(x) {
  const group = new THREE.Group();
  const geo = new THREE.BoxGeometry(0.12, 0.06, 1.55);
  const seat = new THREE.Mesh(geo, seatMat);
  seat.position.set(x, 0.85, 0);
  seat.castShadow = true;
  group.add(seat);

  // End rails
  for (let z of [-0.77, 0.77]) {
    const railGeo = new THREE.BoxGeometry(0.15, 0.05, 0.08);
    const rail = new THREE.Mesh(railGeo, seatMat);
    rail.position.set(x, 0.88, z);
    group.add(rail);
  }
  return group;
}

// --- Oars ---
function createOar(side) {
  const group = new THREE.Group();
  const s = side; // 1 or -1

  // Shaft
  const shaftGeo = new THREE.CylinderGeometry(0.025, 0.02, 3.5, 8);
  const shaft = new THREE.Mesh(shaftGeo, oarMat);
  shaft.position.set(-0.5, 0.95, s * 1.2);
  shaft.rotation.z = s * 0.15;
  shaft.rotation.x = Math.PI / 2 - 0.3;
  shaft.castShadow = true;
  group.add(shaft);

  // Blade
  const bladeGeo = new THREE.BoxGeometry(0.35, 0.02, 0.08);
  const blade = new THREE.Mesh(bladeGeo, bladeMat);
  blade.position.set(-1.8, 0.55, s * 1.6);
  blade.rotation.x = 0.3;
  blade.castShadow = true;
  group.add(blade);

  // Oarlock (metal ring)
  const ringGeo = new THREE.TorusGeometry(0.06, 0.015, 8, 16);
  const ring = new THREE.Mesh(ringGeo, metalMat);
  ring.position.set(0.2, 1.0, s * 0.85);
  ring.rotation.y = Math.PI / 2;
  group.add(ring);

  return group;
}

// --- Gunwale rails ---
function createGunwale(side) {
  const s = side;
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(-2.5, 0.95, s * 0.9),
    new THREE.Vector3(0, 1.0, s * 0.95),
    new THREE.Vector3(2.5, 0.95, s * 0.9)
  );
  const points = curve.getPoints(30);
  const tubeGeo = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(points), 30, 0.03, 8, false
  );
  return new THREE.Mesh(tubeGeo, seatMat);
}

// --- Assemble Boat ---
const boat = new THREE.Group();
boat.add(createHull());
boat.add(createSeat(-1.2));
boat.add(createSeat(0.3));
boat.add(createSeat(1.5));
boat.add(createOar(-1));
boat.add(createOar(1));
boat.add(createGunwale(-1));
boat.add(createGunwale(1));
scene.add(boat);

// --- Water ---
const waterGeo = new THREE.PlaneGeometry(200, 200, 120, 120);
waterGeo.rotateX(-Math.PI / 2);
const water = new THREE.Mesh(waterGeo, waterMat);
water.position.y = -0.1;
water.receiveShadow = true;
scene.add(water);

const waterVerts = waterGeo.attributes.position;
const waterOrig = new Float32Array(waterVerts.array);

// --- Sky dome ---
const skyGeo = new THREE.SphereGeometry(150, 32, 32);
const skyMat = new THREE.MeshBasicMaterial({
  side: THREE.BackSide,
  vertexColors: true
});
const colors = [];
const pos = skyGeo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const y = pos.getY(i);
  const t = (y + 150) / 300;
  if (t > 0.5) {
    colors.push(0.4 + 0.2 * t, 0.6 + 0.3 * t, 0.85 + 0.15 * t);
  } else {
    colors.push(0.6 + 0.3 * t, 0.75 + 0.15 * t, 0.85);
  }
}
skyGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
scene.add(new THREE.Mesh(skyGeo, skyMat));

// --- Simple clouds ---
function createCloud(x, y, z, scale) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, transparent: true, opacity: 0.85 });
  for (let i = 0; i < 5; i++) {
    const r = (0.5 + Math.random() * 1.0) * scale;
    const geo = new THREE.SphereGeometry(r, 12, 10);
    const m = new THREE.Mesh(geo, mat);
    m.position.set((Math.random() - 0.5) * 3 * scale, (Math.random() - 0.5) * 0.5 * scale, (Math.random() - 0.5) * 1.5 * scale);
    g.add(m);
  }
  g.position.set(x, y, z);
  return g;
}
scene.add(createCloud(-25, 22, -30, 2.5));
scene.add(createCloud(30, 25, -40, 3));
scene.add(createCloud(15, 18, 20, 2));
scene.add(createCloud(-35, 20, 15, 1.8));

// --- Camera orbit ---
let angle = 0;

// --- Animate ---
function animate(time) {
  requestAnimationFrame(animate);
  const t = time * 0.001;

  // Water waves
  for (let i = 0; i < waterVerts.count; i++) {
    const x = waterOrig[i * 3];
    const z = waterOrig[i * 3 + 2];
    waterVerts.setZ(i,
      Math.sin(x * 0.3 + t * 1.2) * 0.15 +
      Math.cos(z * 0.25 + t * 0.9) * 0.12 +
      Math.sin((x + z) * 0.15 + t * 1.5) * 0.08
    );
  }
  waterVerts.needsUpdate = true;
  waterGeo.computeVertexNormals();

  // Gentle boat bob
  boat.position.y = Math.sin(t * 0.8) * 0.08;
  boat.rotation.z = Math.sin(t * 0.5) * 0.015;
  boat.rotation.x = Math.sin(t * 0.6 + 1) * 0.01;

  // Camera orbit
  angle += 0.003;
  camera.position.x = Math.cos(angle) * 14;
  camera.position.z = Math.sin(angle) * 14;
  camera.position.y = 4 + Math.sin(angle * 0.7) * 1.5;
  camera.lookAt(0, 0.3, 0);

  renderer.render(scene, camera);
}
animate(0);

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
