</head>
<body>
    <div id="info">Drag to orbit - Scroll to zoom</div>

    <!-- Import Three.js as an ES module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        // Camera
        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 10, 30);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        scene.add(dirLight);

        // Ground
        const groundGeometry = new THREE.PlaneGeometry(200, 200);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x3a9d23 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -10;
        ground.receiveShadow = true;
        scene.add(ground);

        // Ferris Wheel Group
        const ferrisWheelGroup = new THREE.Group();
        scene.add(ferrisWheelGroup);

        // Materials
        const metalMaterial = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.4, metalness: 0.6 });
        const gondolaMaterial = new THREE.MeshStandardMaterial({ color: 0xff4444, roughness: 0.5 });
        const supportMaterial = new THREE.MeshStandardMaterial({ color: 0x555555 });

        // Wheel Parameters
        const radius = 10;
        const numGondolas = 12;

        // 1. The Rim (Torus)
        const rimGeometry = new THREE.TorusGeometry(radius, 0.2, 16, 100);
        const rim = new THREE.Mesh(rimGeometry, metalMaterial);
        rim.castShadow = true;
        ferrisWheelGroup.add(rim);

        // 2. The Spokes
        const spokeGroup = new THREE.Group();
        ferrisWheelGroup.add(spokeGroup);

        for (let i = 0; i < numGondolas; i++) {
            const angle = (i / numGondolas) * Math.PI * 2;

            // Spoke bar
            const spokeGeo = new THREE.CylinderGeometry(0.1, 0.1, radius, 8);
            const spoke = new THREE.Mesh(spokeGeo, metalMaterial);
            spoke.position.y = radius / 2;
            spoke.rotation.z = angle;
            spoke.castShadow = true;
            spokeGroup.add(spoke);

            // Cross braces (X shape between spokes)
            if (i < numGondolas / 2) {
                const braceGeo = new THREE.CylinderGeometry(0.05, 0.05, radius * 1.4, 8);
                const brace = new THREE.Mesh(braceGeo, metalMaterial);
                brace.rotation.z = angle + (Math.PI / numGondolas);
                brace.castShadow = true;
                spokeGroup.add(brace);
            }
        }

        // 3. The Gondolas
        const gondolaGroup = new THREE.Group();
        ferrisWheelGroup.add(gondolaGroup);

        for (let i = 0; i < numGondolas; i++) {
            const angle = (i / numGondolas) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius;

            // Pivot point for the gondola to hang
            const pivot = new THREE.Group();
            pivot.position.set(x, y, 0);
            gondolaGroup.add(pivot);

            // Connector arm
            const armGeo = new THREE.CylinderGeometry(0.1, 0.1, 1.5, 8);
            const arm = new THREE.Mesh(armGeo, metalMaterial);
            arm.position.y = -0.75;
            arm.castShadow = true;
            pivot.add(arm);

            // The Cabin
            const cabinGeo = new THREE.BoxGeometry(1.5, 1.5, 1.5);
            const cabin = new THREE.Mesh(cabinGeo, gondolaMaterial);
            cabin.position.y = -1.5;
            cabin.castShadow = true;
            pivot.add(cabin);
        }

        // 4. Support Structure (A-Frame)
        const supportGroup = new THREE.Group();
        scene.add(supportGroup);

        // Base
        const baseGeo = new THREE.BoxGeometry(12, 1, 2);
        const base = new THREE.Mesh(baseGeo, supportMaterial);
        base.position.y = -10;
        base.castShadow = true;
        supportGroup.add(base);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.4, 0.4, 12, 8);

        const leftLeg = new THREE.Mesh(legGeo, supportMaterial);
        leftLeg.position.set(-4, -4, 0);
        leftLeg.rotation.z = Math.PI / 6; // 30 degrees
        leftLeg.castShadow = true;
        supportGroup.add(leftLeg);

        const rightLeg = new THREE.Mesh(legGeo, supportMaterial);
        rightLeg.position.set(4, -4, 0);
        rightLeg.rotation.z = -Math.PI / 6; // -30 degrees
        rightLeg.castShadow = true;
        supportGroup.add(rightLeg);

        // Center Axle
        const axleGeo = new THREE.CylinderGeometry(0.5, 0.5, 2, 16);
        const axle = new THREE.Mesh(axleGeo, metalMaterial);
        axle.rotation.x = Math.PI / 2;
        ferrisWheelGroup.add(axle);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Rotate the wheel
            ferrisWheelGroup.rotation.z -= 0.005;

            // Keep gondolas upright (counter-rotate them)
            // Since the parent group rotates, we need to rotate the gondola pivots in the opposite direction
            // to keep them hanging down due to gravity simulation
            gondolaGroup.children.forEach(pivot => {
                pivot.rotation.z -= 0.005; 
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
