            roughness: 0.1,
            metalness: 0.8
        });

        // A. The Feather (Main body)
        // Using a cone geometry, scaled to be flat like a feather
        const featherGeo = new THREE.ConeGeometry(1.2, 4, 32);
        const feather = new THREE.Mesh(featherGeo, featherMaterial);
        feather.scale.set(1, 1, 0.1); // Flatten it
        feather.position.y = 2;
        feather.castShadow = true;
        quillGroup.add(feather);

