    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 4, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // Materials
        const giraffeMat = new THREE.MeshStandardMaterial({ color: 0xd4a373 }); // Orange-ish
        const spotMat = new THREE.MeshStandardMaterial({ color: 0x8b5a2b }); // Darker brown
        const leafMat = new THREE.MeshStandardMaterial({ color: 0x4caf50 }); // Green
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x8fbc8f }); // SeaGreen

        // Helper to create giraffe parts
        function createLimb(radius, height, x, y, z, rotZ = 0) {
            const geo = new THREE.CylinderGeometry(radius, radius, height, 16);
            const mesh = new THREE.Mesh(geo, giraffeMat);
            mesh.position.set(x, y, z);
            mesh.rotation.z = rotZ;
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Giraffe Group
        const giraffe = new THREE.Group();

        // Body
        const bodyGeo = new THREE.BoxGeometry(2, 2.5, 4);
        const body = new THREE.Mesh(bodyGeo, giraffeMat);
        body.position.y = 4;
        body.castShadow = true;
        giraffe.add(body);

        // Legs
        const legHeight = 3.5;
        const legRadius = 0.3;
        const leg1 = createLimb(legRadius, legHeight, -0.8, 1.75, 1.2);
        const leg2 = createLimb(legRadius, legHeight, 0.8, 1.75, 1.2);
        const leg3 = createLimb(legRadius, legHeight, -0.8, 1.75, -1.2);
        const leg4 = createLimb(legRadius, legHeight, 0.8, 1.75, -1.2);
        giraffe.add(leg1, leg2, leg3, leg4);

        // Neck
        const neckGeo = new THREE.CylinderGeometry(0.4, 0.6, 5, 16);
        const neck = new THREE.Mesh(neckGeo, giraffeMat);
        neck.position.set(0, 7, 1.5);
        neck.rotation.x = -Math.PI / 6; // Lean forward slightly
        neck.castShadow = true;
        giraffe.add(neck);

        // Head
        const headGeo = new THREE.BoxGeometry(1.2, 1, 1.5);
        const head = new THREE.Mesh(headGeo, giraffeMat);
        head.position.set(0, 9.5, 2.5);
        head.rotation.x = -Math.PI / 4; // Looking down
        head.castShadow = true;
        giraffe.add(head);

        // Ears
        const earGeo = new THREE.ConeGeometry(0.2, 0.5, 8);
        const earL = new THREE.Mesh(earGeo, giraffeMat);
        earL.position.set(-0.6, 9.8, 2.2);
        earL.rotation.z = Math.PI / 4;
        giraffe.add(earL);

        const earR = new THREE.Mesh(earGeo, giraffeMat);
        earR.position.set(0.6, 9.8, 2.2);
        earR.rotation.z = -Math.PI / 4;
        giraffe.add(earR);

        // Ossicones (horns)
        const hornGeo = new THREE.CylinderGeometry(0.05, 0.1, 0.5, 8);
        const hornL = new THREE.Mesh(hornGeo, spotMat);
        hornL.position.set(-0.3, 10.2, 2.5);
        giraffe.add(hornL);
        const hornR = new THREE.Mesh(hornGeo, spotMat);
        hornR.position.set(0.3, 10.2, 2.5);
        giraffe.add(hornR);

        // Leaves (Tree branch)
        const branchGroup = new THREE.Group();
        const branchGeo = new THREE.CylinderGeometry(0.1, 0.1, 4, 8);
        const branch = new THREE.Mesh(branchGeo, spotMat);
        branch.rotation.z = Math.PI / 2;
        branch.rotation.y = Math.PI / 4;
        branch.position.set(0, 9, 3);
        branchGroup.add(branch);

        // Leaf clusters
        for(let i=0; i<8; i++) {
            const leafGeo = new THREE.SphereGeometry(0.4 + Math.random()*0.3, 8, 8);
            const leaf = new THREE.Mesh(leafGeo, leafMat);
            leaf.position.set(
                (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 1.5,
                (Math.random() - 0.5) * 1.5
            );
            leaf.castShadow = true;
            branchGroup.add(leaf);
        }

        // Position branch near mouth
        branchGroup.position.set(0, 8.5, 3.5);
        giraffe.add(branchGroup);

        scene.add(giraffe);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(100, 100);
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Subtle breathing/movement
            giraffe.position.y = Math.sin(time * 2) * 0.05;

            // Head bobbing while eating
            head.rotation.x = -Math.PI / 4 + Math.sin(time * 3) * 0.05;
            neck.rotation.x = -Math.PI / 6 + Math.sin(time * 3) * 0.02;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
