<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.012);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 3, 14);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Lantern Group ──
const lantern = new THREE.Group();

// Paper body – octagonal column
const bodyGeo = new THREE.CylinderGeometry(1.6, 1.6, 3.2, 8, 1, true);
const bodyMat = new THREE.MeshStandardMaterial({
  color: 0xffeedd,
  emissive: 0xffaa33,
  emissiveIntensity: 0.6,
  transparent: true,
  opacity: 0.82,
  side: THREE.DoubleSide,
  roughness: 0.9,
  metalness: 0.0,
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
lantern.add(body);

// Inner glow sphere
const glowGeo = new THREE.SphereGeometry(0.9, 16, 16);
const glowMat = new THREE.MeshBasicMaterial({ color: 0xffcc55 });
const glow = new THREE.Mesh(glowGeo, glowMat);
lantern.add(glow);

// Flame flicker light
const flameLight = new THREE.PointLight(0xff9922, 8, 25, 1.5);
flameLight.position.y = 0;
lantern.add(flameLight);

// Wooden ribs – horizontal rings
const ribGeo = new THREE.TorusGeometry(1.62, 0.04, 8, 8);
const ribMat = new THREE.MeshStandardMaterial({ color: 0x4a3520, roughness: 0.8 });
for (const y of [-1.5, -0.5, 0.5, 1.5]) {
  const rib = new THREE.Mesh(ribGeo, ribMat);
  rib.rotation.x = Math.PI / 2;
  rib.position.y = y;
  lantern.add(rib);
}

// Vertical ribs
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const vRib = new THREE.Mesh(
    new THREE.CylinderGeometry(0.03, 0.03, 3.25, 6),
    ribMat
  );
  vRib.position.set(Math.cos(angle) * 1.62, 0, Math.sin(angle) * 1.62);
  lantern.add(vRib);
}

// Top cap
const topCapGeo = new THREE.CylinderGeometry(0.3, 1.7, 0.5, 8);
const capMat = new THREE.MeshStandardMaterial({ color: 0x3a2510, roughness: 0.7 });
const topCap = new THREE.Mesh(topCapGeo, capMat);
topCap.position.y = 1.85;
lantern.add(topCap);

// Top finial
const finialGeo = new THREE.SphereGeometry(0.22, 12, 12);
const finial = new THREE.Mesh(finialGeo, capMat);
finial.position.y = 2.25;
lantern.add(finial);

// Bottom cap
const botCapGeo = new THREE.CylinderGeometry(1.5, 0.25, 0.5, 8);
const botCap = new THREE.Mesh(botCapGeo, capMat);
botCap.position.y = -1.85;
lantern.add(botCap);

// Bottom tassel
const tasselMat = new THREE.MeshStandardMaterial({ color: 0xcc2200, roughness: 0.6 });
const tasselGeo = new THREE.ConeGeometry(0.2, 1.2, 8);
const tassel = new THREE.Mesh(tasselGeo, tasselMat);
tassel.position.y = -2.7;
lantern.add(tassel);

// Handle loop
const handleCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 2.25, 0),
  new THREE.Vector3(0, 3.2, 0),
  new THREE.Vector3(0, 3.2, 0.8),
  new THREE.Vector3(0, 2.25, 1.2),
]);
const handleGeo = new THREE.TubeGeometry(handleCurve, 20, 0.04, 8, false);
const handle = new THREE.Mesh(handleGeo, capMat);
lantern.add(handle);

// Second half of handle
const handleCurve2 = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 2.25, 0),
  new THREE.Vector3(0, 3.2, 0),
  new THREE.Vector3(0, 3.2, -0.8),
  new THREE.Vector3(0, 2.25, -1.2),
]);
const handleGeo2 = new THREE.TubeGeometry(handleCurve2, 20, 0.04, 8, false);
const handle2 = new THREE.Mesh(handleGeo2, capMat);
lantern.add(handle2);

lantern.position.y = 0;
scene.add(lantern);

// ── Ambient light ──
scene.add(new THREE.AmbientLight(0x1a1a3a, 0.5));

// ── Fireflies ──
const FF_COUNT = 60;
const ffGeo = new THREE.BufferGeometry();
const ffPos = new Float32Array(FF_COUNT * 3);
const ffPhase = new Float32Array(FF_COUNT);
for (let i = 0; i < FF_COUNT; i++) {
  ffPos[i * 3]     = (Math.random() - 0.5) * 50;
  ffPos[i * 3 + 1] = (Math.random() - 0.5) * 30;
  ffPos[i * 3 + 2] = (Math.random() - 0.5) * 50;
  ffPhase[i] = Math.random() * Math.PI * 2;
}
ffGeo.setAttribute('position', new THREE.BufferAttribute(ffPos, 3));

const ffMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0xffdd66) },
  },
  vertexShader: `
    attribute vec3 position;
    uniform float uTime;
    varying float vAlpha;
    void main() {
      float phase = position.x * 0.5 + position.z * 0.3;
      vAlpha = 0.3 + 0.7 * pow(sin(uTime * 1.5 + phase * 10.0) * 0.5 + 0.5, 4.0);
      vec4 mv = modelViewMatrix * vec4(position, 1.0);
      gl_PointSize = max(1.0, 6.0 * (1.0 / -mv.z));
      gl_Position = projectionMatrix * mv;
    }
  `,
  fragmentShader: `
    uniform vec3 uColor;
    varying float vAlpha;
    void main() {
      float d = length(gl_PointCoord - 0.5) * 2.0;
      float a = smoothstep(1.0, 0.0, d) * vAlpha;
      gl_FragColor = vec4(uColor, a * 0.8);
    }
  `,
  transparent: true,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});

const fireflies = new THREE.Points(ffGeo, ffMat);
scene.add(fireflies);

// ── Stars ──
const starCount = 300;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI;
  const r = 80 + Math.random() * 40;
  starPos[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
  starPos[i * 3 + 1] = r * Math.cos(phi);
  starPos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.4,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
});
scene.add(new THREE.Points(starGeo, starMat));

// ── Ground mist particles ──
const mistCount = 200;
const mistGeo = new THREE.BufferGeometry();
const mistPos = new Float32Array(mistCount * 3);
for (let i = 0; i < mistCount; i++) {
  mistPos[i * 3]     = (Math.random() - 0.5) * 60;
  mistPos[i * 3 + 1] = -6 + Math.random() * 2;
  mistPos[i * 3 + 2] = (Math.random() - 0.5) * 60;
}
mistGeo.setAttribute('position', new THREE.BufferAttribute(mistPos, 3));
const mistMat = new THREE.PointsMaterial({
  color: 0x667799,
  size: 1.5,
  transparent: true,
  opacity: 0.15,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const mist = new THREE.Points(mistGeo, mistMat);
scene.add(mist);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Lantern bob
  lantern.position.y = Math.sin(t * 0.6) * 0.6 + 1.0;
  lantern.rotation.y = Math.sin(t * 0.15) * 0.15;
  lantern.rotation.z = Math.sin(t * 0.25) * 0.04;
  lantern.rotation.x = Math.sin(t * 0.2) * 0.03;

  // Flame flicker
  flameLight.intensity = 7 + Math.sin(t * 8) * 1.5 + Math.sin(t * 13) * 0.8 + Math.sin(t * 21) * 0.4;
  glowMat.color.setHSL(0.1, 0.9, 0.55 + Math.sin(t * 7) * 0.05);

  // Body emissive pulse
  bodyMat.emissiveIntensity = 0.55 + Math.sin(t * 6) * 0.1;

  // Fireflies
  ffMat.uniforms.uTime.value = t;
  const positions = fireflies.geometry.attributes.position.array;
  for (let i = 0; i < FF_COUNT; i++) {
    positions[i * 3 + 1] += Math.sin(t * 0.8 + ffPhase[i]) * 0.003;
  }
  fireflies.geometry.attributes.position.needsUpdate = true;

  // Mist drift
  const mPos = mist.geometry.attributes.position.array;
  for (let i = 0; i < mistCount; i++) {
    mPos[i * 3] += Math.sin(t * 0.2 + i) * 0.005;
  }
  mist.geometry.attributes.position.needsUpdate = true;

  // Gentle camera sway
  camera.position.x = Math.sin(t * 0.1) * 0.8;
  camera.position.y = 3 + Math.sin(t * 0.15) * 0.3;
  camera.lookAt(0, 0.5, 0);

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in the scene:**

- **Paper lantern** — octagonal translucent body with wooden ribs (horizontal rings + vertical spars), top/bottom caps, a tassel, and a handle loop
- **Warm flickering flame** — a point light with multi-frequency sine-wave intensity + a pulsing emissive inner sphere
- **Gentle floating motion** — the lantern bobs, sways, and slowly rotates
- **60 fireflies** — custom shader with additive blending, each pulsing at different phases
- **300 stars** — scattered on a distant sphere
- **Ground mist** — low-drifting particles near the bottom
- **Subtle camera sway** — keeps the scene alive
- **Atmospheric fog** — exponential fog for depth

Just save as `index.html` and open in a browser.

