        thorax.position.z = 0.5;
        thorax.castShadow = true;
        mantis.add(thorax);

        // Head
        const headGeo = new THREE.ConeGeometry(0.5, 1.2, 4);
        const head = new THREE.Mesh(headGeo, greenMat);
        head.rotation.x = -Math.PI / 2;
        head.position.z = 1.5;
