            const legGroup = new THREE.Group();
            const legGeo = new THREE.CylinderGeometry(0.08, 0.05, length, 6);
            const leg = new THREE.Mesh(legGeo, greenMat);
            leg.position.y = -length / 2;
            leg.rotation.z = angleZ;
            leg.rotation.x = angleX;
            legGroup.add(leg);
            legGroup.position.copy(startPos);
            return legGroup;
