        // Raptorial Forelegs (The "Praying" hands)
        function createRaptorialLeg(side) {
            const legGroup = new THREE.Group();
            const xDir = side === 'left' ? 1 : -1;

            // Upper arm
            const upperArmGeo = new THREE.CylinderGeometry(0.12, 0.1, 1.5, 6);
