            const claw1 = new THREE.Mesh(clawGeo, darkGreenMat);
            claw1.position.set(0, -1.2, 0);
            claw1.rotation.z = xDir * 0.5;
            lowerArmGroup.add(claw1);

            legGroup.add(lowerArmGroup);
            return legGroup;
        }

        mantis.add(createRaptorialLeg('left'));
        mantis.add(createRaptorialLeg('right'));

        // Middle Legs
        mantis.add(createLeg(new THREE.Vector3(0.7, 0, 0), 2, 0.5, 0));
        mantis.add(createLeg(new THREE.Vector3(-0.7, 0, 0), 2, -0.5, 0));

        // Back Legs
        mantis.add(createLeg(new THREE.Vector3(0.6, 0, -1), 2.5, 0.8, 0));
        mantis.add(createLeg(new THREE.Vector3(-0.6, 0, -1), 2.5, -0.8, 0));

