        const woodMaterial = new THREE.MeshStandardMaterial({ color: 0x8b4513, roughness: 0.7 });
        const darkWoodMaterial = new THREE.MeshStandardMaterial({ color: 0x3e1e09, roughness: 0.8 });
        const keyWhiteMaterial = new THREE.MeshStandardMaterial({ color: 0xfffff0, roughness: 0.3 });
        const keyBlackMaterial = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.3 });
        const metalMaterial = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.8, roughness: 0.2 });
        const redFabricMaterial = new THREE.MeshStandardMaterial({ color: 0x800000, roughness: 0.9 });

        // Barrel Organ Group
        const organGroup = new THREE.Group();

        // 1. Main Barrel Body
        const barrelGeo = new THREE.CylinderGeometry(1.2, 1.2, 2.5, 32);
        const barrel = new THREE.Mesh(barrelGeo, woodMaterial);
        barrel.position.y = 1.5;
        barrel.castShadow = true;
        barrel.receiveShadow = true;
        organGroup.add(barrel);

        // Decorative bands on barrel
        const bandGeo = new THREE.CylinderGeometry(1.22, 1.22, 0.1, 32);
        const band1 = new THREE.Mesh(bandGeo, darkWoodMaterial);
        band1.position.y = 2.2;
        organGroup.add(band1);
        const band2 = new THREE.Mesh(bandGeo, darkWoodMaterial);
        band2.position.y = 0.8;
        organGroup.add(band2);

        // 2. Keyboard Base
        const keyboardBaseGeo = new THREE.BoxGeometry(1.8, 0.4, 0.5);
        const keyboardBase = new THREE.Mesh(keyboardBaseGeo, darkWoodMaterial);
        keyboardBase.position.set(0, 1.5, 1.1);
        keyboardBase.castShadow = true;
        organGroup.add(keyboardBase);

        // 3. Keys
        const keyWidth = 0.12;
        const keyDepth = 0.4;
        const keyHeight = 0.25;
        const blackKeyHeight = 0.15;
        const blackKeyDepth = 0.25;

        // White keys
        for (let i = 0; i < 12; i++) {
            const keyGeo = new THREE.BoxGeometry(keyWidth, keyHeight, keyDepth);
            const key = new THREE.Mesh(keyGeo, keyWhiteMaterial);
            key.position.set(-0.7 + (i * 0.14), 1.5 + 0.32, 1.35);
            key.castShadow = true;
            organGroup.add(key);
        }

        // Black keys (simplified pattern)
        const blackKeyPositions = [0, 1, 3, 4, 5, 7, 8, 10]; // indices relative to white keys
        for (let i of blackKeyPositions) {
            const keyGeo = new THREE.BoxGeometry(keyWidth * 0.7, blackKeyHeight, blackKeyDepth);
            const key = new THREE.Mesh(keyGeo, keyBlackMaterial);
            key.position.set(-0.7 + ((i + 0.5) * 0.14), 1.5 + 0.45, 1.3);
            key.castShadow = true;
            organGroup.add(key);
        }

        // 4. Crank Handle (Right side)
        const crankArmGeo = new THREE.BoxGeometry(0.1, 0.1, 0.6);
        const crankArm = new THREE.Mesh(crankArmGeo, metalMaterial);
        crankArm.position.set(1.2, 1.5, 0);
        organGroup.add(crankArm);

        const crankHandleGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.4, 16);
        const crankHandle = new THREE.Mesh(crankHandleGeo, woodMaterial);
        crankHandle.rotation.x = Math.PI / 2;
        crankHandle.position.set(1.2, 1.5, 0.4);
        organGroup.add(crankHandle);

        // 5. Legs
        const legGeo = new THREE.CylinderGeometry(0.08, 0.06, 0.8, 12);
        const legPositions = [
            [-0.8, 0.4, 0.8],
            [0.8, 0.4, 0.8],
            [-0.8, 0.4, -0.8],
            [0.8, 0.4, -0.8]
        ];
        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, darkWoodMaterial);
            leg.position.set(...pos);
            leg.castShadow = true;
            organGroup.add(leg);
        });

        // 6. Decorative Top (Canopy)
        const canopyGeo = new THREE.CylinderGeometry(1.3, 1.2, 0.2, 32);
        const canopy = new THREE.Mesh(canopyGeo, redFabricMaterial);
        canopy.position.y = 2.8;
        organGroup.add(canopy);

        // Add group to scene
        scene.add(organGroup);

        // Floor
        const floorGeo = new THREE.PlaneGeometry(20, 20);
        const floorMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Slow rotation for demo purposes
            organGroup.rotation.y += 0.002;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
