        paw1.position.set(0.8, -0.4, 0.4);
        otterGroup.add(paw1);
        const paw2 = new THREE.Mesh(pawGeo, furMat);
        paw2.position.set(0.8, -0.4, -0.4);
        otterGroup.add(paw2);

        scene.add(otterGroup);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Animation Loop
        function animate() {
