        const barGeo = new THREE.CylinderGeometry(0.05, 0.05, 4, 8);
        const bar = new THREE.Mesh(barGeo, woodMat);
        bar.rotation.z = Math.PI / 2;
        bar.position.y = 3;
        puppet.add(bar);

        // Helper to create string and attach part
        function createStringAndPart(startX, startY, length, partGeo, partMat, partOffsetY = 0) {
            const group = new THREE.Group();
            group.position.set(startX, startY, 0);

            // String
            const points = [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, -length, 0)];
            const stringGeo = new THREE.BufferGeometry().setFromPoints(points);
            const stringLine = new THREE.Line(stringGeo, stringMat);
            group.add(stringLine);

            // Part
            if (partGeo) {
                const part = new THREE.Mesh(partGeo, partMat);
                part.position.y = -length + partOffsetY;
                group.add(part);
            }

            puppet.add(group);
            return group;
        }

