        // Legs
        const legGeo = new THREE.CylinderGeometry(0.08, 0.08, 1.5);
        const leftLeg = createStringAndPart(-0.8, 3, 1.5, legGeo, woodMat);
        leftLeg.position.set(-0.2, -3.1, 0);

        const rightLeg = createStringAndPart(0.8, 3, 1.5, legGeo, woodMat);
        rightLeg.position.set(0.2, -3.1, 0);

        // Mouse Interaction
        const mouse = new THREE.Vector2();
        const targetPos = new THREE.Vector3();

        window.addEventListener('mousemove', (event) => {
            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            // Map mouse to scene coordinates roughly
            targetPos.x = mouse.x * 4;
            targetPos.y = mouse.y * 2 + 1; 
        });

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Smooth follow
            puppet.position.x += (targetPos.x - puppet.position.x) * 0.1;
            puppet.position.y += (targetPos.y - puppet.position.y) * 0.1;

            // Add some swing
            const time = Date.now() * 0.001;
            puppet.rotation.z = Math.sin(time) * 0.05 + (targetPos.x * 0.05);
            puppet.rotation.x = Math.cos(time * 0.8) * 0.05;

            renderer.render(scene, camera);
        }

        animate();

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
