```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Wind Chime</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();

// Gradient sky
const skyCanvas = document.createElement('canvas');
skyCanvas.width = 512; skyCanvas.height = 512;
const ctx = skyCanvas.getContext('2d');
const grad = ctx.createLinearGradient(0, 0, 0, 512);
grad.addColorStop(0, '#0a0a2e');
grad.addColorStop(0.3, '#1a1a4e');
grad.addColorStop(0.6, '#3a2060');
grad.addColorStop(0.8, '#c0504a');
grad.addColorStop(1, '#f0a050');
ctx.fillStyle = grad;
ctx.fillRect(0, 0, 512, 512);
const skyTex = new THREE.CanvasTexture(skyCanvas);
scene.background = skyTex;
scene.fog = new THREE.FogExp2(0x1a1a3e, 0.012);

// ── Camera ──
const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 2, 8);

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);
controls.maxPolarAngle = Math.PI * 0.85;
controls.minDistance = 3;
controls.maxDistance = 20;

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffa060, 2.5);
sunLight.position.set(5, 8, 3);
scene.add(sunLight);

const fillLight = new THREE.DirectionalLight(0x6080ff, 0.6);
fillLight.position.set(-4, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff8040, 1.5, 20);
rimLight.position.set(0, 6, -3);
scene.add(rimLight);

// ── Materials ──
const metalMat = new THREE.MeshStandardMaterial({
  color: 0xc8b88a,
  metalness: 0.85,
  roughness: 0.2,
});

const darkMetalMat = new THREE.MeshStandardMaterial({
  color: 0x887755,
  metalness: 0.9,
  roughness: 0.15,
});

const stringMat = new THREE.MeshStandardMaterial({
  color: 0xddd5c0,
  metalness: 0.0,
  roughness: 0.9,
});

const woodMat = new THREE.MeshStandardMaterial({
  color: 0x6b4423,
  metalness: 0.0,
  roughness: 0.8,
});

const clapperMat = new THREE.MeshStandardMaterial({
  color: 0x8b7355,
  metalness: 0.1,
  roughness: 0.7,
});

// ── Wind Chime Group ──
const chimeGroup = new THREE.Group();
scene.add(chimeGroup);

// Top cap / ring
const topRing = new THREE.Mesh(
  new THREE.TorusGeometry(0.5, 0.04, 16, 48),
  darkMetalMat
);
topRing.position.y = 4.5;
chimeGroup.add(topRing);

// Hanging loop
const loopGeo = new THREE.TorusGeometry(0.12, 0.02, 12, 24);
const loop = new THREE.Mesh(loopGeo, darkMetalMat);
loop.position.y = 4.85;
chimeGroup.add(loop);

// Wooden cross bar
const crossBar = new THREE.Mesh(
  new THREE.CylinderGeometry(0.04, 0.04, 2.0, 12),
  woodMat
);
crossBar.rotation.z = Math.PI / 2;
crossBar.position.y = 4.2;
chimeGroup.add(crossBar);

// End caps on cross bar
for (let side of [-1, 1]) {
  const cap = new THREE.Mesh(
    new THREE.SphereGeometry(0.06, 12, 12),
    darkMetalMat
  );
  cap.position.set(side * 1.0, 4.2, 0);
  chimeGroup.add(cap);
}

// ── Tubes ──
const tubeData = [];
const tubeLengths = [1.8, 1.5, 1.2, 0.9, 1.35, 1.05];
const tubeAngles = [-0.45, -0.28, -0.1, 0.1, 0.28, 0.45];

tubeLengths.forEach((len, i) => {
  const tubeGroup = new THREE.Group();

  // String
  const stringGeo = new THREE.CylinderGeometry(0.005, 0.005, 0.6, 6);
  const string = new THREE.Mesh(stringGeo, stringMat);
  string.position.y = -0.3;
  tubeGroup.add(string);

  // Tube
  const tubeGeo = new THREE.CylinderGeometry(0.06, 0.06, len, 16, 1, true);
  const tube = new THREE.Mesh(tubeGeo, metalMat);
  tube.position.y = -0.6 - len / 2;

  // Add a subtle seam line
  const seamGeo = new THREE.CylinderGeometry(0.062, 0.062, len, 16, 1, true);
  const seamMat = new THREE.MeshStandardMaterial({
    color: 0xb0a070, metalness: 0.9, roughness: 0.15,
    transparent: true, opacity: 0.3
  });
  const seam = new THREE.Mesh(seamGeo, seamMat);
  seam.position.y = -0.6 - len / 2;

  // Bottom cap ring
  const bottomRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.062, 0.008, 8, 24),
    darkMetalMat
  );
  bottomRing.rotation.x = Math.PI / 2;
  bottomRing.position.y = -0.6 - len;

  // Small hole at bottom (visual)
  const holeGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.02, 8);
  const hole = new THREE.Mesh(holeGeo, darkMetalMat);
  hole.position.y = -0.6 - len;

  tubeGroup.add(tube);
  tubeGroup.add(seam);
  tubeGroup.add(bottomRing);
  tubeGroup.add(hole);

  tubeGroup.position.set(Math.sin(tubeAngles[i]) * 1.0, 4.2, Math.cos(tubeAngles[i]) * 1.0 * 0.05);
  tubeGroup.rotation.x = tubeAngles[i] * 0.1;

  chimeGroup.add(tubeGroup);

  tubeData.push({
    group: tubeGroup,
    baseAngle: tubeAngles[i],
    length: len,
    phase: i * 1.3,
    speed: 0.4 + Math.random() * 0.3,
    amplitude: 0.02 + Math.random() * 0.02,
  });
});

// ── Central clapper ──
const clapperGroup = new THREE.Group();

const clapperString = new THREE.Mesh(
  new THREE.CylinderGeometry(0.005, 0.005, 1.2, 6),
  stringMat
);
clapperString.position.y = -0.6;
clapperGroup.add(clapperString);

const clapperHead = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 16, 16),
  clapperMat
);
clapperHead.position.y = -1.2;
clapperGroup.add(clapperHead);

const clapperTip = new THREE.Mesh(
  new THREE.ConeGeometry(0.06, 0.12, 12),
  clapperMat
);
clapperTip.position.y = -1.32;
clapperGroup.add(clapperTip);

clapperGroup.position.set(0, 4.2, 0);
chimeGroup.add(clapperGroup);

// ── Bottom weight / catcher ──
const bottomGeo = new THREE.CylinderGeometry(0.15, 0.1, 0.15, 24);
const bottomWeight = new THREE.Mesh(bottomGeo, darkMetalMat);
bottomWeight.position.y = -2.0;
clapperGroup.add(bottomWeight);

// ── Stars ──
const starCount = 500;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  starPos[i * 3] = (Math.random() - 0.5) * 100;
  starPos[i * 3 + 1] = Math.random() * 40 + 5;
  starPos[i * 3 + 2] = (Math.random() - 0.5) * 100 - 20;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.08, transparent: true, opacity: 0.7 });
scene.add(new THREE.Points(starGeo, starMat));

// ── Floating particles (dust / pollen) ──
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const particlePos = new Float32Array(particleCount * 3);
const particleVel = [];
for (let i = 0; i < particleCount; i++) {
  particlePos[i * 3] = (Math.random() - 0.5) * 10;
  particlePos[i * 3 + 1] = Math.random() * 8;
  particlePos[i * 3 + 2] = (Math.random() - 0.5) * 10;
  particleVel.push({
    x: (Math.random() - 0.5) * 0.003,
    y: (Math.random() - 0.5) * 0.002,
    z: (Math.random() - 0.5) * 0.003,
  });
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePos, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xffe8c0, size: 0.03, transparent: true, opacity: 0.5
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle overall sway
  chimeGroup.rotation.z = Math.sin(t * 0.3) * 0.015;
  chimeGroup.rotation.x = Math.sin(t * 0.25 + 1) * 0.01;

  // Individual tube sway
  tubeData.forEach((td) => {
    const sway = Math.sin(t * td.speed + td.phase) * td.amplitude;
    td.group.rotation.z = sway;
    td.group.rotation.x = Math.sin(t * td.speed * 0.7 + td.phase + 0.5) * td.amplitude * 0.5;
  });

  // Clapper swing
  clapperGroup.rotation.z = Math.sin(t * 0.6 + 0.5) * 0.04;
  clapperGroup.rotation.x = Math.sin(t * 0.5 + 1.2) * 0.025;

  // Animate particles
  const positions = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    positions[i * 3] += particleVel[i].x + Math.sin(t + i) * 0.001;
    positions[i * 3 + 1] += particleVel[i].y + Math.cos(t * 0.5 + i) * 0.0005;
    positions[i * 3 + 2] += particleVel[i].z + Math.sin(t * 0.7 + i * 0.3) * 0.001;

    // Wrap around
    if (positions[i * 3] > 5) positions[i * 3] = -5;
    if (positions[i * 3] < -5) positions[i * 3] = 5;
    if (positions[i * 3 + 1] > 8) positions[i * 3 + 1] = 0;
    if (positions[i * 3 + 1] < 0) positions[i * 3 + 1] = 8;
    if (positions[i * 3 + 2] > 5) positions[i * 3 + 2] = -5;
    if (positions[i * 3 + 2] < -5) positions[i * 3 + 2] = 5;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  // Subtle light flicker
  rimLight.intensity = 1.5 + Math.sin(t * 2.1) * 0.2 + Math.sin(t * 3.7) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This creates a complete wind chime scene featuring:

- **Top cap** — a torus ring with a hanging loop
- **Wooden cross bar** — with decorative end caps
- **Six metal tubes** — varying lengths with metallic gold/brass material, bottom rings, and seam details
- **Central clapper** — a wooden sphere-and-cone pendulum that swings between the tubes
- **Bottom weight** — attached below the clapper

**Visual effects:**
- 🌅 Sunset-to-night gradient sky
- ✨ 500 background stars
- 🌬️ Floating dust/pollen particles with wind drift

