const rimLight = new THREE.DirectionalLight(0xffe0a0, 0.5);
rimLight.position.set(-3, 4, -8);
scene.add(rimLight);

// ── Materials ──
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xDAA520, roughness: 0.7, metalness: 0.0
});
const lightGoldMat = new THREE.MeshStandardMaterial({
  color: 0xF0C860, roughness: 0.7, metalness: 0.0
});
const darkGoldMat = new THREE.MeshStandardMaterial({
  color: 0xB8860B, roughness: 0.7, metalness: 0.0
});
const whiteMat = new THREE.MeshStandardMaterial({
  color: 0xFFF8DC, roughness: 0.8, metalness: 0.0
});
const noseMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a1a, roughness: 0.3, metalness: 0.1
});
const eyeMat = new THREE.MeshStandardMaterial({
  color: 0x3B1F0B, roughness: 0.2, metalness: 0.3
});
const eyeWhiteMat = new THREE.MeshStandardMaterial({
  color: 0xFFF5EE, roughness: 0.5
});
const tongueMat = new THREE.MeshStandardMaterial({
  color: 0xE8707A, roughness: 0.6
});
const collarMat = new THREE.MeshStandardMaterial({
  color: 0xCC2200, roughness: 0.5, metalness: 0.1
});
const tagMat = new THREE.MeshStandardMaterial({
  color: 0xFFD700, roughness: 0.3, metalness: 0.8
});
const grassMat = new THREE.MeshStandardMaterial({
  color: 0x4a8c3f, roughness: 0.9
});
const pathMat = new THREE.MeshStandardMaterial({
  color: 0xc4a882, roughness: 0.95
});

// ── Dog Group ──
const dog = new THREE.Group();
scene.add(dog);

// ── Helper Functions ──
function createLimb(radiusTop, radiusBottom, height, mat, segments = 8) {
  const geo = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function createSphere(rx, ry, rz, mat) {
  const geo = new THREE.SphereGeometry(1, 16, 16);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.scale.set(rx, ry, rz);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// ── Body ──
const body = createSphere(1.3, 1.0, 2.0, goldMat);
body.position.set(0, 2.2, 0);
dog.add(body);

// Chest
const chest = createSphere(1.1, 1.05, 1.2, lightGoldMat);
chest.position.set(0, 2.0, 1.4);
dog.add(chest);

// Hindquarters
