    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 6);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 1, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(50, 50);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Forest Green
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Hermit Crab Construction
        const crabGroup = new THREE.Group();

        // Materials
        const shellMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.8 }); // SaddleBrown
        const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0xFF6347, roughness: 0.5 }); // Tomato
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });

        // 1. The Shell (A spiral cone approximation)
        const shellGeo = new THREE.ConeGeometry(1.2, 2, 32, 1, true);
        const shell = new THREE.Mesh(shellGeo, shellMaterial);
        shell.position.set(0, 1.2, -0.5);
        shell.rotation.x = -Math.PI / 2; // Lay on side
        shell.rotation.z = Math.PI / 4; // Tilt slightly
        shell.castShadow = true;
        crabGroup.add(shell);

        // Shell opening (dark circle)
        const openingGeo = new THREE.CircleGeometry(0.8, 32);
        const openingMat = new THREE.MeshBasicMaterial({ color: 0x1a0f00 });
        const opening = new THREE.Mesh(openingGeo, openingMat);
        opening.position.set(0, 1.2, -0.5);
        opening.rotation.x = -Math.PI / 2;
        opening.rotation.z = Math.PI / 4;
        opening.translateZ(0.01); // Slight offset to prevent z-fighting
        crabGroup.add(opening);

        // 2. The Body (Cephalothorax)
        const bodyGeo = new THREE.SphereGeometry(0.7, 32, 16);
        const body = new THREE.Mesh(bodyGeo, bodyMaterial);
        body.position.set(0, 0.8, 0.8);
        body.scale.set(1, 0.8, 1.2);
        body.castShadow = true;
        crabGroup.add(body);

        // 3. Eyes
        const stalkGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.6);
        const eyeBallGeo = new THREE.SphereGeometry(0.12);

        function createEye(xPos, rotZ) {
            const stalk = new THREE.Mesh(stalkGeo, bodyMaterial);
            stalk.position.set(xPos, 1.3, 1.2);
            stalk.rotation.z = rotZ;
            stalk.castShadow = true;
            crabGroup.add(stalk);

            const eye = new THREE.Mesh(eyeBallGeo, eyeMaterial);
            eye.position.set(xPos + (rotZ * 0.3), 1.6, 1.2);
            crabGroup.add(eye);
        }

        createEye(-0.3, 0.3);
        createEye(0.3, -0.3);

        // 4. Legs
        const legGeo = new THREE.CylinderGeometry(0.06, 0.04, 1.5);

        function createLeg(xPos, zPos, rotZ, isRight) {
            const leg = new THREE.Mesh(legGeo, bodyMaterial);
            leg.position.set(xPos, 0.5, zPos);
            leg.rotation.x = Math.PI / 2; // Point outwards
            leg.rotation.z = rotZ;
            leg.castShadow = true;
            crabGroup.add(leg);
        }

        // Left legs
        createLeg(-0.6, 0.5, 0.5, false);
        createLeg(-0.6, 0.9, 0.3, false);
        createLeg(-0.6, 1.3, 0.1, false);

        // Right legs
        createLeg(0.6, 0.5, -0.5, true);
        createLeg(0.6, 0.9, -0.3, true);
        createLeg(0.6, 1.3, -0.1, true);

        // 5. Claws
        const clawGeo = new THREE.SphereGeometry(0.25);
        const leftClaw = new THREE.Mesh(clawGeo, bodyMaterial);
        leftClaw.position.set(-0.8, 0.8, 1.5);
        leftClaw.scale.set(1, 1, 1.5);
        leftClaw.castShadow = true;
        crabGroup.add(leftClaw);

        const rightClaw = new THREE.Mesh(clawGeo, bodyMaterial);
        rightClaw.position.set(0.8, 0.8, 1.5);
        rightClaw.scale.set(1, 1, 1.5);
        rightClaw.castShadow = true;
        crabGroup.add(rightClaw);

        scene.add(crabGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Simple idle animation
            const time = Date.now() * 0.001;
            crabGroup.position.y = Math.sin(time) * 0.1;
            crabGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
