                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

        // Camera
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Skateboard Group
        const skateboard = new THREE.Group();

        // Materials
        const deckMaterial = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 }); // Grip tape
        const woodMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.6 }); // Wood bottom
        const truckMaterial = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, metalness: 0.8, roughness: 0.2 }); // Silver metal
        const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0xff4444, roughness: 0.4 }); // Red wheels

        // 1. Deck
        // Main body
        const deckGeo = new THREE.BoxGeometry(8, 0.2, 2.5);
        const deck = new THREE.Mesh(deckGeo, deckMaterial);
        deck.castShadow = true;
        deck.receiveShadow = true;

        // Add a slight curve to the deck visually by scaling vertices (simple trick) or just keep it boxy for simplicity
        // Let's add a "wood" bottom layer slightly smaller
        const bottomGeo = new THREE.BoxGeometry(7.8, 0.15, 2.3);
        const bottom = new THREE.Mesh(bottomGeo, woodMaterial);
        bottom.position.y = -0.05;
        deck.add(bottom);

        // Nose and Tail (simple geometry additions)
        const noseGeo = new THREE.BoxGeometry(1.5, 0.2, 2.5);
        const nose = new THREE.Mesh(noseGeo, deckMaterial);
        nose.position.x = 4.5;
        nose.rotation.z = -0.1; // Kick up
        deck.add(nose);

        const tailGeo = new THREE.BoxGeometry(1.5, 0.2, 2.5);
        const tail = new THREE.Mesh(tailGeo, deckMaterial);
        tail.position.x = -4.5;
        tail.rotation.z = 0.1; // Kick up
        deck.add(tail);

        skateboard.add(deck);

        // 2. Trucks
        function createTruck(xPos) {
            const truckGroup = new THREE.Group();

            // Baseplate
            const baseGeo = new THREE.BoxGeometry(1.5, 0.1, 2.2);
            const base = new THREE.Mesh(baseGeo, truckMaterial);
            base.position.y = -0.15;
            truckGroup.add(base);

            // Hanger
            const hangerGeo = new THREE.BoxGeometry(1.2, 0.15, 2.8);
            const hanger = new THREE.Mesh(hangerGeo, truckMaterial);
            hanger.position.y = -0.3;
            truckGroup.add(hanger);

            // Axle
            const axleGeo = new THREE.CylinderGeometry(0.1, 0.1, 3.2, 16);
            const axle = new THREE.Mesh(axleGeo, truckMaterial);
            axle.rotation.x = Math.PI / 2;
            axle.position.y = -0.4;
            truckGroup.add(axle);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);

            const w1 = new THREE.Mesh(wheelGeo, wheelMaterial);
            w1.rotation.x = Math.PI / 2;
            w1.position.set(0, -0.4, 1.1);
            truckGroup.add(w1);

            const w2 = new THREE.Mesh(wheelGeo, wheelMaterial);
            w2.rotation.x = Math.PI / 2;
            w2.position.set(0, -0.4, -1.1);
            truckGroup.add(w2);

            truckGroup.position.set(xPos, -0.1, 0);
            return truckGroup;
        }

        const frontTruck = createTruck(2.5);
        const backTruck = createTruck(-2.5);
        skateboard.add(frontTruck);
        skateboard.add(backTruck);

        // Rotate entire board to look nice
        skateboard.rotation.x = 0.2;
        skateboard.rotation.y = -0.5;
        scene.add(skateboard);

        // Floor (invisible plane for shadows)
        const planeGeo = new THREE.PlaneGeometry(50, 50);
        const planeMat = new THREE.ShadowMaterial({ opacity: 0.3 });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            skateboard.position.y = Math.sin(Date.now() * 0.001) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
