        const backLight = new THREE.DirectionalLight(0x4444ff, 1); // Blue rim light
        backLight.position.set(-2, 0, -5);
        scene.add(backLight);

        // Butterfly Construction
        const butterflyGroup = new THREE.Group();

        // Materials
        const wingMaterial = new THREE.MeshStandardMaterial({
            color: 0x0055ff, // Morpho Blue
            side: THREE.DoubleSide,
            roughness: 0.3,
            metalness: 0.2,
            emissive: 0x001133,
            emissiveIntensity: 0.2
        });

        const bodyMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.8 
        });

        // Wing Shape Definition
        const wingShape = new THREE.Shape();
        wingShape.moveTo(0, 0);
        // Upper wing
        wingShape.bezierCurveTo(0.2, 0.5, 1.2, 1.0, 1.5, 2.0);
        wingShape.bezierCurveTo(1.2, 2.5, 0.5, 2.2, 0.2, 1.8);
        // Lower wing
        wingShape.bezierCurveTo(0.5, 1.5, 1.0, 1.0, 1.2, 0.5);
        wingShape.bezierCurveTo(0.8, 0.0, 0.2, -0.2, 0, 0);

        const wingGeometry = new THREE.ShapeGeometry(wingShape, 12);

        // Create Wings
        const leftWing = new THREE.Mesh(wingGeometry, wingMaterial);
        leftWing.position.x = -0.05;
        butterflyGroup.add(leftWing);

        const rightWing = new THREE.Mesh(wingGeometry, wingMaterial);
        rightWing.scale.x = -1; // Mirror
        rightWing.position.x = 0.05;
        butterflyGroup.add(rightWing);

        // Body
        const bodyGeo = new THREE.CapsuleGeometry(0.05, 1.5, 4, 8);
        const body = new THREE.Mesh(bodyGeo, bodyMaterial);
        body.rotation.x = Math.PI / 2;
        butterflyGroup.add(body);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.01, 0.01, 0.6);
        const antenna1 = new THREE.Mesh(antennaGeo, bodyMaterial);
        antenna1.position.set(-0.05, 0, 0.8);
        antenna1.rotation.z = 0.4;
        antenna1.rotation.x = -0.2;
