    <style>
        body { margin: 0; overflow: hidden; background-color: #050505; }
        canvas { display: block; }
        #info {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: #ffaa00;
            font-family: 'Courier New', Courier, monospace;
            font-weight: bold;
            pointer-events: none;
            text-shadow: 0 0 5px #ff4400;
        }
    </style>
</head>
<body>
    <div id="info">⚒ The Blacksmith's Forge ⚒</div>

    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.03);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 6);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        // Dim ambient light for the dark workshop
        const ambientLight = new THREE.AmbientLight(0x222222, 1);
        scene.add(ambientLight);

        // The main fire light (orange/red)
        const fireLight = new THREE.PointLight(0xff6600, 3, 15);
        fireLight.position.set(-2.5, 1.5, 0);
        fireLight.castShadow = true;
        fireLight.shadow.mapSize.width = 1024;
        fireLight.shadow.mapSize.height = 1024;
        scene.add(fireLight);

        // A subtle blue rim light for contrast
        const rimLight = new THREE.PointLight(0x4444ff, 0.5, 10);
        rimLight.position.set(3, 2, -3);
        scene.add(rimLight);

        // --- Materials ---
        const stoneMat = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            roughness: 0.9, 
            metalness: 0.1 
        });

        const metalMat = new THREE.MeshStandardMaterial({ 
            color: 0x555555, 
            roughness: 0.3, 
            metalness: 0.8 
        });

        const hotMetalMat = new THREE.MeshStandardMaterial({ 
            color: 0xff3300, 
            emissive: 0xff2200,
            emissiveIntensity: 2,
            roughness: 0.4, 
            metalness: 0.5 
        });

        // --- Objects ---

        // 1. Ground
        const groundGeo = new THREE.PlaneGeometry(30, 30);
        const ground = new THREE.Mesh(groundGeo, stoneMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // 2. The Anvil
        const anvilGroup = new THREE.Group();

        // Base
        const baseGeo = new THREE.CylinderGeometry(0.8, 1, 0.6, 8);
        const base = new THREE.Mesh(baseGeo, metalMat);
        base.position.y = 0.3;
        base.castShadow = true;
        base.receiveShadow = true;
        anvilGroup.add(base);

        // Top Block
        const topGeo = new THREE.BoxGeometry(1.6, 0.5, 0.9);
        const top = new THREE.Mesh(topGeo, metalMat);
        top.position.y = 0.85;
        top.castShadow = true;
        top.receiveShadow = true;
        anvilGroup.add(top);

        // Horn
        const hornGeo = new THREE.ConeGeometry(0.25, 1.2, 8);
        const horn = new THREE.Mesh(hornGeo, metalMat);
        horn.rotation.z = Math.PI / 2;
        horn.position.set(1.3, 0.85, 0);
        horn.castShadow = true;
        anvilGroup.add(horn);

        anvilGroup.position.set(1.5, 0, 0);
        scene.add(anvilGroup);

        // 3. The Forge/Fire Pit
        const pitGroup = new THREE.Group();

        // Stone base of the pit
        const pitBaseGeo = new THREE.CylinderGeometry(1.2, 1.4, 1, 16);
        const pitBase = new THREE.Mesh(pitBaseGeo, stoneMat);
        pitBase.position.y = 0.5;
        pitBase.castShadow = true;
        pitBase.receiveShadow = true;
        pitGroup.add(pitBase);

        // The Fire (Glowing Sphere)
        const fireGeo = new THREE.SphereGeometry(0.6, 16, 16);
        const fireMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
        const fireMesh = new THREE.Mesh(fireGeo, fireMat);
        fireMesh.position.y = 1.2;
        pitGroup.add(fireMesh);

        // Coals
        const coalGeo = new THREE.DodecahedronGeometry(0.3);
        for(let i=0; i<5; i++) {
            const coal = new THREE.Mesh(coalGeo, hotMetalMat);
            coal.position.set(
                (Math.random() - 0.5) * 0.8,
                1.0 + Math.random() * 0.2,
                (Math.random() - 0.5) * 0.8
            );
            coal.rotation.set(Math.random(), Math.random(), Math.random());
            pitGroup.add(coal);
        }

        pitGroup.position.set(-2.5, 0, 0);
        scene.add(pitGroup);

        // 4. A Hammer
        const hammerGroup = new THREE.Group();
        const handleGeo = new THREE.CylinderGeometry(0.05, 0.05, 1.5);
        const handleMat = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
        const handle = new THREE.Mesh(handleGeo, handleMat);
        handle.rotation.z = Math.PI / 4;
        handle.position.set(0.5, 0.5, 0);

        const headGeo = new THREE.BoxGeometry(0.4, 0.2, 0.3);
        const head = new THREE.Mesh(headGeo, metalMat);
        head.position.set(0.8, 0.8, 0);

        hammerGroup.add(handle);
        hammerGroup.add(head);
        hammerGroup.position.set(2.5, 0, 1);
        hammerGroup.rotation.y = -0.5;
        scene.add(hammerGroup);

        // 5. Sparks Particle System
        const sparkCount = 100;
        const sparkGeo = new THREE.BufferGeometry();
        const sparkPositions = new Float32Array(sparkCount * 3);
        const sparkVelocities = [];

        for(let i=0; i<sparkCount; i++) {
            resetSpark(i);
        }

        sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPositions, 3));
        const sparkMat = new THREE.PointsMaterial({ 
            color: 0xffaa00, 
            size: 0.08,
            transparent: true,
            opacity: 0.8
        });
        const sparks = new THREE.Points(sparkGeo, sparkMat);
        scene.add(sparks);

        function resetSpark(i) {
            sparkPositions[i*3] = -2.5 + (Math.random() - 0.5) * 0.8; // x
            sparkPositions[i*3+1] = 1.2 + Math.random() * 0.5;       // y
            sparkPositions[i*3+2] = (Math.random() - 0.5) * 0.8;     // z

            sparkVelocities[i] = {
                x: (Math.random() - 0.5) * 0.05,
                y: Math.random() * 0.08 + 0.02,
                z: (Math.random() - 0.5) * 0.05
            };
        }

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Flicker fire light
            fireLight.intensity = 2.5 + Math.sin(time * 10) * 0.5 + Math.random() * 0.5;
            fireMesh.scale.setScalar(0.9 + Math.sin(time * 15) * 0.1);

            // Update sparks
            const positions = sparks.geometry.attributes.position.array;
            for(let i=0; i<sparkCount; i++) {
                positions[i*3] += sparkVelocities[i].x;
                positions[i*3+1] += sparkVelocities[i].y;
                positions[i*3+2] += sparkVelocities[i].z;

                // Gravity effect on sparks (slow down rising)
                sparkVelocities[i].y -= 0.001;

                // Reset if too high or fallen back down
                if(positions[i*3+1] > 4 || positions[i*3+1] < 0) {
                    resetSpark(i);
                }
            }
            sparks.geometry.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
        }

        animate();

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
