        scene.add(octopus);

        // Materials
        const skinMaterial = new THREE.MeshStandardMaterial({
            color: 0xff6b6b,
            roughness: 0.4,
            metalness: 0.1,
        });

        const eyeMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            roughness: 0.2,
        });

        const pupilMaterial = new THREE.MeshStandardMaterial({
            color: 0x000000,
        });

        // Head (Mantle)
        const headGeometry = new THREE.SphereGeometry(1.5, 32, 32);
        // Squash the sphere slightly to make it look more like an octopus head
        headGeometry.scale(1, 0.8, 1); 
        const head = new THREE.Mesh(headGeometry, skinMaterial);
        head.position.y = 1.5;
        head.castShadow = true;
        octopus.add(head);

        // Eyes
        function createEye(xPos) {
            const eyeGroup = new THREE.Group();

            const eyeWhite = new THREE.Mesh(new THREE.SphereGeometry(0.3, 16, 16), eyeMaterial);
            eyeGroup.add(eyeWhite);

            const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 16), pupilMaterial);
            pupil.position.z = 0.2;
            eyeGroup.add(pupil);

            eyeGroup.position.set(xPos, 1.6, 1.2);
            eyeGroup.rotation.y = xPos > 0 ? -0.5 : 0.5;
            return eyeGroup;
        }

        octopus.add(createEye(-0.6));
        octopus.add(createEye(0.6));

        // Tentacles
        const tentacles = [];
        const tentacleCount = 8;

        for (let i = 0; i < tentacleCount; i++) {
            const angle = (i / tentacleCount) * Math.PI * 2;

            // Create a curve for the tentacle
            const points = [];
            const segments = 10;
            for (let j = 0; j <= segments; j++) {
                const t = j / segments;
                const x = Math.cos(angle) * (1.2 + t * 0.5);
                const z = Math.sin(angle) * (1.2 + t * 0.5);
                const y = 1.5 - t * 4; // Droop down
                points.push(new THREE.Vector3(x, y, z));
            }

            const curve = new THREE.CatmullRomCurve3(points);
            const geometry = new THREE.TubeGeometry(curve, 20, 0.2 - 0.1 * (i/tentacleCount), 8, false);
            const mesh = new THREE.Mesh(geometry, skinMaterial);
            mesh.castShadow = true;

            octopus.add(mesh);
            tentacles.push({ mesh, curve, baseAngle: angle, phase: Math.random() * Math.PI * 2 });
        }

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Bob the whole octopus
            octopus.position.y = Math.sin(time * 0.5) * 0.5;
            octopus.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Wiggle tentacles
            tentacles.forEach((tentacle, index) => {
                const positions = tentacle.curve.points;
                for (let i = 1; i < positions.length; i++) {
                    const t = i / positions.length;
                    // Add sine wave motion to x and z based on time and position along tentacle
                    positions[i].x += Math.sin(time * 2 + i + tentacle.phase) * 0.002;
                    positions[i].z += Math.cos(time * 2 + i + tentacle.phase) * 0.002;
                }
                tentacle.curve.points = positions;
                tentacle.mesh.geometry.dispose();
                tentacle.mesh.geometry = new THREE.TubeGeometry(tentacle.curve, 20, 0.2 - 0.1 * (index/tentacleCount), 8, false);
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```

This creates a complete animated octopus with:

- **Body** — A rounded mantle/head built from merged sphere geometries in a deep reddish-purple
- **8 Tentacles** — Each made from a `TubeGeometry` along an animated `CatmullRomCurve3`, with sine-wave undulation giving organic, wavy motion. Each tentacle has a unique phase and speed
- **Suckers** — Small spheres along each tentacle that follow the curve in real-time
- **Eyes** — White sclera with dark pupils and tiny specular highlights, angled toward the viewer
- **Atmosphere** — Floating plankton particles, exponential fog, and multi-directional lighting (cool blue fill + warm rim light)
- **Animation** — Gentle body bobbing, subtle rotation, and continuous tentacle undulation

