</head>
<body>
<script type="x-shader/x-vertex" id="vshader">
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position, 1.0);
  }
</script>
<script type="x-shader/x-fragment" id="fshader">
  precision highp float;
  uniform float uTime;
  uniform vec2 uResolution;
  uniform vec2 uMouse;
  varying vec2 vUv;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
      mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
      f.y
    );
  }

  float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 6; i++) {
      v += a * noise(p);
      p = rot * p * 2.0 + vec2(100.0);
      a *= 0.5;
    }
    return v;
  }

  vec2 kaleidoscope(vec2 uv, int segments) {
    float angle = atan(uv.y, uv.x);
    float radius = length(uv);
    float segmentAngle = 6.28318 / float(segments);
    angle = mod(angle, segmentAngle);
    angle = abs(angle - segmentAngle * 0.5);
    return vec2(cos(angle), sin(angle)) * radius;
  }

  void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution) / min(uResolution.x, uResolution.y);
    vec2 mouse = uMouse / min(uResolution.x, uResolution.y);

    int segments = 6;
    float t = uTime * 0.15;

    // Layer 1: Outer flowing pattern
    vec2 p1 = kaleidoscope(uv * 1.5 + mouse * 0.3, segments);
    float n1 = fbm(p1 * 3.0 + t * vec2(1.0, -0.5));

    // Layer 2: Inner spinning pattern
    vec2 p2 = kaleidoscope(uv * 2.5 + mouse * 0.5, segments * 2);
    float n2 = fbm(p2 * 2.5 - t * vec2(0.7, 1.1));

    // Layer 3: Deep mandala
    vec2 p3 = kaleidoscope(uv * 4.0 - mouse * 0.2, segments * 3);
    float n3 = fbm(p3 * 2.0 + t * vec2(1.2, 0.8));

    // Color palette using cosine gradients
    vec3 col = 0.5 + 0.5 * cos(
      6.28318 * (
        vec3(0.5, 0.2, 0.75) * n1
        + vec3(0.0, 0.33, 0.67) * n2
        + vec3(0.25, 0.6, 0.9) * n3
        + t * 0.3
      )
    );

    // Radial vignette glow
    float r = length(uv);
    col *= smoothstep(1.2, 0.2, r);

    // Brightness boost and slight saturation
    col = pow(col, vec3(0.85));
    col *= 1.2;

    gl_FragColor = vec4(col, 1.0);
  }
</script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  document.body.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

  const uniforms = {
    uTime:     { value: 0 },
    uResolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) },
    uMouse:    { value: new THREE.Vector2(0, 0) }
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader:   document.getElementById('vshader').textContent,
    fragmentShader: document.getElementById('fshader').textContent
  });

  scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material));

  window.addEventListener('mousemove', e => {
    uniforms.uMouse.value.set(e.clientX - window.innerWidth / 2, e.clientY - window.innerHeight / 2);
  });

  window.addEventListener('resize', () => {
    renderer.setSize(window.innerWidth, window.innerHeight);
    uniforms.uResolution.value.set(window.innerWidth, window.innerHeight);
  });

  function animate(time) {
    uniforms.uTime.value = time * 0.001;
    renderer.render(scene, camera);
    requestAnimationFrame(animate);
  }
  requestAnimationFrame(animate);
</script>
