<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ── scene setup ─────────────────────────────────── */
const scene    = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 30, 60);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(6, 5, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.5, 0);
controls.enableDamping = true;
controls.update();

/* ── lighting ────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0x999bbb, 1.2));

const sun = new THREE.DirectionalLight(0xfff4e0, 2.5);
sun.position.set(8, 12, 6);
sun.castShadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;  sun.shadow.camera.far = 30;
sun.shadow.camera.left = sun.shadow.camera.bottom = -8;
sun.shadow.camera.right = sun.shadow.camera.top = 8;
scene.add(sun);

const fill = new THREE.DirectionalLight(0x8899cc, 0.6);
fill.position.set(-6, 4, -4);
scene.add(fill);

/* ── ground ──────────────────────────────────────── */
const groundGeo = new THREE.CircleGeometry(25, 64);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x5a8f3c, roughness: 0.95 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

