const shellMat    = new THREE.MeshStandardMaterial({ color: 0x6b5b45, roughness: 0.6, metalness: 0.1 });
const shellDark   = new THREE.MeshStandardMaterial({ color: 0x4a3e2e, roughness: 0.7 });
const skinMat     = new THREE.MeshStandardMaterial({ color: 0xb0a090, roughness: 0.8 });
const noseMat     = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.4 });
const eyeMat      = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.2 });
const earInnerMat = new THREE.MeshStandardMaterial({ color: 0xd4a0a0, roughness: 0.7 });
const tailMat     = new THREE.MeshStandardMaterial({ color: 0x5a4d3a, roughness: 0.75 });

/* ── armadillo group ─────────────────────────────── */
const armadillo = new THREE.Group();

// helper: scaled sphere
function sphere(sx, sy, sz, mat) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 24), mat);
  m.scale.set(sx, sy, sz);
  return m;
}

// helper: cylinder
function cyl(rT, rB, h, mat) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rT, rB, h, 16), mat);
  return m;
}

/* ── body ────────────────────────────────────────── */
// main body (underbelly)
const body = sphere(1.0, 0.7, 1.8, skinMat);
body.position.set(0, 1.3, 0);
body.castShadow = true;
armadillo.add(body);

/* ── shell dome ──────────────────────────────────── */
// main dome
const dome = sphere(1.05, 0.65, 1.85, shellMat);
dome.position.set(0, 1.95, 0);
dome.castShadow = true;
armadillo.add(dome);

// shell bands (horizontal ridges)
const bandCount = 7;
for (let i = 0; i < bandCount; i++) {
  const t = (i + 1) / (bandCount + 1);
  const z = (t - 0.5) * 3.2;
  // band ring
  const ringGeo = new THREE.TorusGeometry(
    0.95 + Math.sin(t * Math.PI) * 0.15,
    0.045, 8, 32
  );
  const ring = new THREE.Mesh(ringGeo, shellDark);
  ring.position.set(0, 1.95 + Math.sin(t * Math.PI) * 0.55, z);
  ring.rotation.y = Math.PI / 2;
  ring.castShadow = true;
  armadillo.add(ring);
}

// head shield
const headShield = sphere(0.55, 0.45, 0.55, shellMat);
headShield.position.set(0, 1.75, 1.95);
headShield.castShadow = true;
armadillo.add(headShield);

// rear shield
const rearShield = sphere(0.65, 0.5, 0.4, shellMat);
rearShield.position.set(0, 1.7, -1.65);
rearShield.castShadow = true;
armadillo.add(rearShield);

/* ── head / snout ────────────────────────────────── */
const snout = sphere(0.3, 0.25, 0.6, skinMat);
snout.position.set(0, 1.45, 2.55);
snout.castShadow = true;
armadillo.add(snout);

const nose = sphere(0.12, 0.1, 0.12, noseMat);
nose.position.set(0, 1.38, 2.95);
armadillo.add(nose);

// eyes
for (const side of [-1, 1]) {
  const eye = sphere(0.08, 0.08, 0.08, eyeMat);
  eye.position.set(side * 0.32, 1.62, 2.35);
  armadillo.add(eye);
}

// ears
for (const side of [-1, 1]) {
  const earOuter = sphere(0.18, 0.2, 0.12, skinMat);
  earOuter.position.set(side * 0.42, 2.05, 2.0);
  earOuter.rotation.z = side * 0.3;
  armadillo.add(earOuter);

  const earInner = sphere(0.1, 0.12, 0.06, earInnerMat);
  earInner.position.set(side * 0.42, 2.05, 2.08);
  earInner.rotation.z = side * 0.3;
  armadillo.add(earInner);
}

/* ── legs ────────────────────────────────────────── */
const legPositions = [
  { x: -0.65, z:  1.1 },
  { x:  0.65, z:  1.1 },
  { x: -0.65, z: -1.0 },
  { x:  0.65, z: -1.0 },
];

legPositions.forEach(({ x, z }) => {
  const leg = cyl(0.12, 0.14, 0.7, skinMat);
  leg.position.set(x, 0.55, z);
  leg.castShadow = true;
  armadillo.add(leg);

  // foot
  const foot = sphere(0.14, 0.08, 0.2, skinMat);
  foot.position.set(x, 0.15, z + 0.08);
  armadillo.add(foot);
});

/* ── tail ────────────────────────────────────────── */
const tailSegments = 10;
for (let i = 0; i < tailSegments; i++) {
  const t = i / tailSegments;
  const radius = 0.25 * (1 - t * 0.85);
  const seg = sphere(radius, radius * 0.7, 0.22, i % 2 === 0 ? tailMat : shellDark);
  seg.position.set(0, 1.2 - t * 0.4, -1.8 - t * 1.6);
  seg.castShadow = true;
  armadillo.add(seg);
}

// tail tip
const tailTip = sphere(0.06, 0.06, 0.06, noseMat);
tailTip.position.set(0, 0.8, -3.4);
armadillo.add(tailTip);

scene.add(armadillo);

/* ── idle animation ──────────────────────────────── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // gentle breathing / bob
  armadillo.position.y = Math.sin(t * 1.8) * 0.04;
  // subtle head tilt
  headShield.rotation.x = Math.sin(t * 1.2) * 0.03;
  snout.rotation.x      = Math.sin(t * 1.2) * 0.03;
  nose.rotation.x       = Math.sin(t * 1.2) * 0.03;

  // slow rotation
  armadillo.rotation.y = Math.sin(t * 0.3) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}
animate();

/* ── resize ──────────────────────────────────────── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
