controls.target.set(0, 1.0, 0);
controls.enableDamping = true;
controls.minDistance = 2;
controls.maxDistance = 8;
controls.maxPolarAngle = Math.PI * 0.85;
controls.update();

// --- Marble Shader Material ---
function createMarbleMaterial(baseColor, veinColor, veinScale) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uBaseColor: { value: new THREE.Color(baseColor) },
      uVeinColor: { value: new THREE.Color(veinColor) },
      uVeinScale: { value: veinScale },
      uLightPos1: { value: new THREE.Vector3(3, 5, 4) },
      uLightPos2: { value: new THREE.Vector3(-3, 3, -2) },
      uLightPos3: { value: new THREE.Vector3(0, -2, 5) },
      uLightCol1: { value: new THREE.Color(0xfff5e6) },
      uLightCol2: { value: new THREE.Color(0xc8d8f0) },
      uLightCol3: { value: new THREE.Color(0x333340) },
      uCamPos: { value: camera.position },
      uTime: { value: 0 }
    },
    vertexShader: `
      varying vec3 vNormal;
      varying vec3 vWorldPos;
      varying vec3 vViewDir;
      varying vec2 vUv;

      void main() {
        vNormal = normalize(normalMatrix * normal);
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldPos = wp.xyz;
        vViewDir = normalize(cameraPosition - wp.xyz);
        vUv = uv;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform vec3 uBaseColor;
      uniform vec3 uVeinColor;
      uniform float uVeinScale;
      uniform vec3 uLightPos1, uLightPos2, uLightPos3;
      uniform vec3 uLightCol1, uLightCol2, uLightCol3;
      uniform vec3 uCamPos;
      uniform float uTime;
      varying vec3 vNormal;
      varying vec3 vWorldPos;
      varying vec3 vViewDir;
      varying vec2 vUv;

      // Simplex-like noise
      vec3 mod289(vec3 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
      vec4 mod289(vec4 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
      vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
      vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

      float snoise(vec3 v) {
        const vec2 C = vec2(1.0/6.0, 1.0/3.0);
        const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
        vec3 i = floor(v + dot(v, C.yyy));
        vec3 x0 = v - i + dot(i, C.xxx);
        vec3 g = step(x0.yzx, x0.xyz);
        vec3 l = 1.0 - g;
        vec3 i1 = min(g.xyz, l.zxy);
        vec3 i2 = max(g.xyz, l.zxy);
        vec3 x1 = x0 - i1 + C.xxx;
        vec3 x2 = x0 - i2 + C.yyy;
        vec3 x3 = x0 - D.yyy;
        i = mod289(i);
        vec4 p = permute(permute(permute(
          i.z + vec4(0.0, i1.z, i2.z, 1.0))
          + i.y + vec4(0.0, i1.y, i2.y, 1.0))
          + i.x + vec4(0.0, i1.x, i2.x, 1.0));
        float n_ = 0.142857142857;
        vec3 ns = n_ * D.wyz - D.xzx;
        vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
        vec4 x_ = floor(j * ns.z);
        vec4 y_ = floor(j - 7.0 * x_);
        vec4 x = x_ * ns.x + ns.yyyy;
        vec4 y = y_ * ns.x + ns.yyyy;
        vec4 h = 1.0 - abs(x) - abs(y);
        vec4 b0 = vec4(x.xy, y.xy);
        vec4 b1 = vec4(x.zw, y.zw);
        vec4 s0 = floor(b0)*2.0 + 1.0;
        vec4 s1 = floor(b1)*2.0 + 1.0;
        vec4 sh = -step(h, vec4(0.0));
        vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
        vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
        vec3 p0 = vec3(a0.xy, h.x);
        vec3 p1 = vec3(a0.zw, h.y);
        vec3 p2 = vec3(a1.xy, h.z);
        vec3 p3 = vec3(a1.zw, h.w);
        vec4 norm = taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
        p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
        vec4 m = max(0.6 - vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)), 0.0);
        m = m * m;
        return 42.0 * dot(m*m, vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
      }

      float fbm(vec3 p) {
        float v = 0.0, a = 0.5;
        vec3 shift = vec3(100.0);
        for (int i = 0; i < 5; i++) {
          v += a * snoise(p);
          p = p * 2.0 + shift;
          a *= 0.5;
        }
        return v;
      }

      void main() {
        // Marble veining
        vec3 wp = vWorldPos * uVeinScale;
        float n1 = fbm(wp + vec3(0.0));
        float n2 = fbm(wp + vec3(31.416, 17.0, 93.333));
        float n3 = fbm(wp * 1.5 + vec3(50.0));

        float vein = smoothstep(0.0, 0.15, n1) * 0.6;
        vein += smoothstep(0.3, 0.5, n2) * 0.3;
        vein += smoothstep(0.4, 0.6, n3) * 0.1;
        vein = clamp(vein, 0.0, 1.0);

        vec3 albedo = mix(uBaseColor, uVeinColor, vein * 0.5);

        // Subtle warm tint variation
        float warmth = snoise(wp * 0.5) * 0.05;
        albedo += vec3(warmth, warmth * 0.7, warmth * 0.3);

        // Lighting
        vec3 N = normalize(vNormal);
        vec3 V = normalize(vViewDir);

        vec3 color = albedo * 0.08; // ambient

        // Light 1 - warm key
        {
          vec3 L = normalize(uLightPos1 - vWorldPos);
          vec3 H = normalize(L + V);
          float diff = max(dot(N, L), 0.0);
          float spec = pow(max(dot(N, H), 0.0), 64.0);
          color += albedo * diff * 0.9 * uLightCol1;
          color += spec * 0.4 * uLightCol1;
        }

        // Light 2 - cool fill
        {
          vec3 L = normalize(uLightPos2 - vWorldPos);
          vec3 H = normalize(L + V);
          float diff = max(dot(N, L), 0.0);
          float spec = pow(max(dot(N, H), 0.0), 32.0);
          color += albedo * diff * 0.5 * uLightCol2;
          color += spec * 0.15 * uLightCol2;
        }

        // Light 3 - rim
        {
          vec3 L = normalize(uLightPos3 - vWorldPos);
          float rim = 1.0 - max(dot(N, V), 0.0);
          rim = pow(rim, 3.0);
          color += rim * 0.2 * uLightCol2;
        }

        // Subsurface scattering approximation
        float sss = max(dot(V, -normalize(uLightPos1 - vWorldPos)), 0.0);
        sss = pow(sss, 3.0) * 0.15;
        color += albedo * sss * vec3(1.0, 0.95, 0.85);

        gl_FragColor = vec4(color, 1.0);
      }
    `
  });
}

