        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // 5. Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffaa00, 0.5);
        backLight.position.set(-5, -5, -5);
        scene.add(backLight);

        // 6. Hive Construction (Honeycomb)
        const hiveGroup = new THREE.Group();

        // Hexagon parameters
        const radius = 0.6;
        const depth = 1.5; // Depth of the cell
        const geometry = new THREE.CylinderGeometry(radius, radius, depth, 6);

        // Wax Material
        const waxMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xFFD700, // Gold
            roughness: 0.3,
            metalness: 0.1,
            flatShading: true
        });

        // Darker material for the inside of cells (simulated by scaling or just visual trick)
        // We will just use the main material but maybe add a cap or just rely on lighting.

        // Create a grid of hexagons
        const rows = 6;
        const cols = 6;
        const spacingX = radius * 1.732; // sqrt(3) * radius for tight packing horizontally
        const spacingY = radius * 1.5;   // 1.5 * radius for vertical packing

        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const mesh = new THREE.Mesh(geometry, waxMaterial);

                // Hexagonal grid math
                let x = c * spacingX;
                let y = r * spacingY;

                // Offset every other row
                if (r % 2 !== 0) {
                    x += spacingX / 2;
                }

                // Center the group roughly
                mesh.position.set(
                    x - (cols * spacingX) / 2, 
                    y - (rows * spacingY) / 2, 
                    0
                );

                // Add slight organic variation
                mesh.rotation.z = (Math.random() - 0.5) * 0.05;
                mesh.rotation.x = (Math.random() - 0.5) * 0.05;

                // Scale variation
                const scale = 0.9 + Math.random() * 0.2;
                mesh.scale.set(scale, scale, scale);

                mesh.castShadow = true;
                mesh.receiveShadow = true;

                hiveGroup.add(mesh);
            }
        }

        // Add a "backing" board to make it look like a frame
        const boardGeometry = new THREE.BoxGeometry(8, 8, 0.2);
        const boardMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513 }); // Brown wood
        const board = new THREE.Mesh(boardGeometry, boardMaterial);
        board.position.z = -1;
        hiveGroup.add(board);

        scene.add(hiveGroup);

        // 7. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            hiveGroup.rotation.y += 0.002;

            controls.update();
            renderer.render(scene, camera);
        }

        // 8. Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
