const rimLight = new THREE.PointLight(0xffaa66, 0.8, 15);
rimLight.position.set(-3, 6, -4);
scene.add(rimLight);

// Materials
const barkMat = new THREE.MeshStandardMaterial({
  color: 0x5c3a1e, roughness: 0.9, metalness: 0.0,
});
const branchMat = new THREE.MeshStandardMaterial({
  color: 0x6b4226, roughness: 0.85, metalness: 0.0,
});
const foliageMats = [
  new THREE.MeshStandardMaterial({ color: 0x2d6b30, roughness: 0.7, metalness: 0.0 }),
  new THREE.MeshStandardMaterial({ color: 0x3a8c3f, roughness: 0.7, metalness: 0.0 }),
  new THREE.MeshStandardMaterial({ color: 0x1f5c24, roughness: 0.7, metalness: 0.0 }),
  new THREE.MeshStandardMaterial({ color: 0x4a9e4e, roughness: 0.7, metalness: 0.0 }),
];
const potMat = new THREE.MeshStandardMaterial({
  color: 0x8b4513, roughness: 0.6, metalness: 0.1,
});
const soilMat = new THREE.MeshStandardMaterial({
  color: 0x3b2507, roughness: 1.0, metalness: 0.0,
});

// Shared geometries
const icoGeo = new THREE.IcosahedronGeometry(1, 2);

// Pot
function createPot() {
  const group = new THREE.Group();

  const potProfile = [];
  const segments = 20;
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const r = 1.2 + Math.sin(t * Math.PI) * 0.15 - t * 0.15;
    potProfile.push(new THREE.Vector2(r, t * 0.9));
  }
  const potGeo = new THREE.LatheGeometry(potProfile, 32);
  const pot = new THREE.Mesh(potGeo, potMat);
  pot.castShadow = true;
  pot.receiveShadow = true;
  group.add(pot);

  const soilGeo = new THREE.CylinderGeometry(1.05, 1.05, 0.08, 32);
  const soil = new THREE.Mesh(soilGeo, soilMat);
  soil.position.y = 0.86;
  soil.receiveShadow = true;
  group.add(soil);

  group.position.y = 0.05;
  return group;
}
scene.add(createPot());

// Tree
const treeGroup = new THREE.Group();
scene.add(treeGroup);

function createBranch(start, end, radius, depth, maxDepth) {
  if (depth > maxDepth || radius < 0.01) return;

  const dir = new THREE.Vector3().subVectors(end, start);
  const length = dir.length();
  const mid = new THREE.Vector3().addVectors(start, end).multiplyScalar(0.5);

  const geo = new THREE.CylinderGeometry(
    radius * 0.7, radius, length, 6, 1
  );
  geo.translate(0, length / 2, 0);
  geo.rotateX(Math.PI / 2);

  const mat = depth <= 1 ? barkMat : branchMat;
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.copy(start);
  mesh.lookAt(end);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  treeGroup.add(mesh);

  if (depth >= maxDepth - 1) {
    createFoliage(end, radius * 6 + Math.random() * 3, depth);
  }

  const branches = depth === 0 ? 3 : (depth === 1 ? 3 : 2);
  const spread = 0.6 + depth * 0.15;
  const shrink = 0.65 + Math.random() * 0.1;
  const lengthShrink = 0.7 + Math.random() * 0.15;

  for (let i = 0; i < branches; i++) {
    const angle = ((i / branches) * Math.PI * 2) + (Math.random() - 0.5) * 0.8;
    const tilt = 0.3 + Math.random() * 0.6 + depth * 0.1;
    const newLen = length * lengthShrink * (0.7 + Math.random() * 0.6);

    const newDir = new THREE.Vector3(
      Math.cos(angle) * Math.sin(tilt),
      Math.cos(tilt) * 0.6 + 0.4,
      Math.sin(angle) * Math.sin(tilt)
    ).normalize().multiplyScalar(newLen);

    const newEnd = new THREE.Vector3().copy(end).add(newDir);

    createBranch(end, newEnd, radius * shrink, depth + 1, maxDepth);
  }
}

function createFoliage(position, size, depth) {
  const count = 2 + Math.floor(Math.random() * 3);
  for (let i = 0; i < count; i++) {
    const s = size * (0.4 + Math.random() * 0.6);
    const geo = icoGeo.clone();
    // Slightly distort vertices for organic feel
    const pos = geo.attributes.position;
    for (let j = 0; j < pos.count; j++) {
      pos.setX(j, pos.getX(j) + (Math.random() - 0.5) * 0.15);
      pos.setY(j, pos.getY(j) + (Math.random() - 0.5) * 0.15);
      pos.setZ(j, pos.getZ(j) + (Math.random() - 0.5) * 0.15);
    }
    geo.computeVertexNormals();

    const mat = foliageMats[Math.floor(Math.random() * foliageMats.length)];
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position);
    mesh.position.x += (Math.random() - 0.5) * s * 0.5;
    mesh.position.y += (Math.random() - 0.5) * s * 0.3;
    mesh.position.z += (Math.random() - 0.5) * s * 0.5;
    mesh.scale.setScalar(s);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    treeGroup.add(mesh);
  }
}

