        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const rimLight = new THREE.DirectionalLight(0x4444ff, 0.5);
        rimLight.position.set(-5, 5, -5);
        scene.add(rimLight);

        // Owl Group
        const owlGroup = new THREE.Group();
        scene.add(owlGroup);

        // Materials
        const whiteFur = new THREE.MeshStandardMaterial({ 
            color: 0xf0f0f0, 
            roughness: 0.8,
            flatShading: true 
        });
        const darkFur = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            roughness: 0.8,
            flatShading: true 
        });
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0xffcc00, emissive: 0xaa8800, emissiveIntensity: 0.2 });
        const pupilMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const beakMaterial = new THREE.MeshStandardMaterial({ color: 0xff8800 });

        // 1. Body
        const bodyGeo = new THREE.SphereGeometry(1.5, 16, 16);
        const body = new THREE.Mesh(bodyGeo, whiteFur);
        body.scale.set(1, 1.2, 0.9);
        body.castShadow = true;
        owlGroup.add(body);

        // 2. Head
        const headGeo = new THREE.SphereGeometry(1.1, 16, 16);
        const head = new THREE.Mesh(headGeo, whiteFur);
        head.position.y = 1.6;
        head.castShadow = true;
        owlGroup.add(head);

        // 3. Face Disk (Darker area around eyes)
        const faceDiskGeo = new THREE.SphereGeometry(0.9, 16, 16);
        const faceDisk = new THREE.Mesh(faceDiskGeo, darkFur);
        faceDisk.position.set(0, 1.6, 0.4);
        faceDisk.scale.set(1, 0.8, 0.5);
        owlGroup.add(faceDisk);

        // 4. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.35, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.4, 1.7, 0.8);
        owlGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.4, 1.7, 0.8);
        owlGroup.add(rightEye);

        // Pupils
        const pupilGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const leftPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        leftPupil.position.set(-0.4, 1.7, 1.1);
        owlGroup.add(leftPupil);

        const rightPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        rightPupil.position.set(0.4, 1.7, 1.1);
        owlGroup.add(rightPupil);

        // 5. Beak
        const beakGeo = new THREE.ConeGeometry(0.15, 0.4, 8);
        const beak = new THREE.Mesh(beakGeo, beakMaterial);
        beak.position.set(0, 1.4, 1.0);
        beak.rotation.x = Math.PI / 2;
        owlGroup.add(beak);

        // 6. Ear Tufts
        const tuftGeo = new THREE.ConeGeometry(0.2, 0.6, 8);
        const leftTuft = new THREE.Mesh(tuftGeo, whiteFur);
        leftTuft.position.set(-0.6, 2.5, 0);
        leftTuft.rotation.z = 0.5;
        owlGroup.add(leftTuft);

        const rightTuft = new THREE.Mesh(tuftGeo, whiteFur);
        rightTuft.position.set(0.6, 2.5, 0);
        rightTuft.rotation.z = -0.5;
        owlGroup.add(rightTuft);

        // 7. Wings
        const wingGeo = new THREE.SphereGeometry(1.2, 16, 16);
        const leftWing = new THREE.Mesh(wingGeo, whiteFur);
        leftWing.position.set(-1.4, 0.2, -0.2);
        leftWing.scale.set(0.4, 1.2, 0.8);
        leftWing.rotation.z = 0.5;
        owlGroup.add(leftWing);

        const rightWing = new THREE.Mesh(wingGeo, whiteFur);
        rightWing.position.set(1.4, 0.2, -0.2);
        rightWing.scale.set(0.4, 1.2, 0.8);
        rightWing.rotation.z = -0.5;
        owlGroup.add(rightWing);

        // 8. Feet
        const footGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.5);
        const leftFoot = new THREE.Mesh(footGeo, beakMaterial);
        leftFoot.position.set(-0.4, -1.6, 0.5);
        owlGroup.add(leftFoot);

        const rightFoot = new THREE.Mesh(footGeo, beakMaterial);
        rightFoot.position.set(0.4, -1.6, 0.5);
        owlGroup.add(rightFoot);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle floating
            owlGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Subtle head turn
            head.rotation.y = Math.sin(time * 0.3) * 0.2;
            faceDisk.rotation.y = Math.sin(time * 0.3) * 0.2;
            leftEye.rotation.y = Math.sin(time * 0.3) * 0.2;
            rightEye.rotation.y = Math.sin(time * 0.3) * 0.2;
            leftPupil.rotation.y = Math.sin(time * 0.3) * 0.2;
            rightPupil.rotation.y = Math.sin(time * 0.3) * 0.2;
            beak.rotation.y = Math.sin(time * 0.3) * 0.2;
            leftTuft.rotation.y = Math.sin(time * 0.3) * 0.2;
            rightTuft.rotation.y = Math.sin(time * 0.3) * 0.2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
