<title>Three.js Weathervane</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #000; font-family: Georgia, serif; }
canvas { display: block; }
#info {
  position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
  color: #ccc; font-size: 13px; background: rgba(0,0,0,0.5);
  padding: 8px 18px; border-radius: 20px; pointer-events: none;
}
</style>
</head>
<body>
<div id="info">Drag to orbit · Scroll to zoom · Weathervane responds to simulated wind</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene, Camera, Renderer ──────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.012);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 200);
camera.position.set(8, 10, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 6, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2.05;
controls.minDistance = 5;
controls.maxDistance = 40;

// ── Lighting ─────────────────────────────────────────────
const ambientLight = new THREE.AmbientLight(0x404060, 0.8);
scene.add(ambientLight);

const moonLight = new THREE.DirectionalLight(0x8888cc, 2.5);
moonLight.position.set(-10, 20, 10);
moonLight.castShadow = true;
moonLight.shadow.mapSize.set(2048, 2048);
moonLight.shadow.camera.near = 1;
moonLight.shadow.camera.far = 50;
moonLight.shadow.camera.left = -15;
moonLight.shadow.camera.right = 15;
moonLight.shadow.camera.top = 20;
moonLight.shadow.camera.bottom = -5;
scene.add(moonLight);

const warmLight = new THREE.PointLight(0xffaa44, 1.5, 30);
warmLight.position.set(5, 3, 5);
scene.add(warmLight);

const rimLight = new THREE.DirectionalLight(0x4488ff, 0.6);
rimLight.position.set(10, 5, -10);
scene.add(rimLight);

// ── Materials ────────────────────────────────────────────
const copperMat = new THREE.MeshStandardMaterial({
  color: 0xb87333, metalness: 0.85, roughness: 0.25
});

const brassMat = new THREE.MeshStandardMaterial({
  color: 0xd4a843, metalness: 0.9, roughness: 0.15
});

const darkMetalMat = new THREE.MeshStandardMaterial({
  color: 0x333333, metalness: 0.7, roughness: 0.4
});

const stoneMat = new THREE.MeshStandardMaterial({
  color: 0x555555, metalness: 0.1, roughness: 0.9
});

const groundMat = new THREE.MeshStandardMaterial({
  color: 0x2a3a2a, metalness: 0.0, roughness: 0.95
});

// ── Ground ───────────────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(60, 64),
  groundMat
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ── Weathervane Group ────────────────────────────────────
const weathervane = new THREE.Group();
scene.add(weathervane);

// ── Base / Pedestal ──────────────────────────────────────
const baseGeo = new THREE.CylinderGeometry(0.6, 0.8, 0.5, 8);
const base = new THREE.Mesh(baseGeo, stoneMat);
base.position.y = 0.25;
base.castShadow = true;
base.receiveShadow = true;
weathervane.add(base);

// ── Main Pole ────────────────────────────────────────────
const poleGeo = new THREE.CylinderGeometry(0.08, 0.1, 10, 12);
const pole = new THREE.Mesh(poleGeo, brassMat);
pole.position.y = 5.5;
pole.castShadow = true;
weathervane.add(pole);

// ── Finial (top ball) ────────────────────────────────────
const finialGeo = new THREE.SphereGeometry(0.2, 16, 16);
const finial = new THREE.Mesh(finialGeo, brassMat);
finial.position.y = 10.6;
finial.castShadow = true;
weathervane.add(finial);

// Small spike above finial
const spikeGeo = new THREE.ConeGeometry(0.05, 0.4, 8);
const spike = new THREE.Mesh(spikeGeo, brassMat);
spike.position.y = 10.95;
weathervane.add(spike);

// ── Rotating Arrow Assembly ──────────────────────────────
const arrowGroup = new THREE.Group();
arrowGroup.position.y = 9.2;
weathervane.add(arrowGroup);

// Pivot ring
const pivotRing = new THREE.Mesh(
  new THREE.TorusGeometry(0.15, 0.04, 8, 24),
  brassMat
);
pivotRing.rotation.x = Math.PI / 2;
arrowGroup.add(pivotRing);

// ── Arrow (points into wind) ─────────────────────────────
const arrowShape = new THREE.Shape();
arrowShape.moveTo(0, 0);
arrowShape.lineTo(2.5, 0.3);
arrowShape.lineTo(2.0, 0);
arrowShape.lineTo(2.5, -0.3);
arrowShape.closePath();

const arrowGeo = new THREE.ExtrudeGeometry(arrowShape, {
  depth: 0.08, bevelEnabled: true, bevelThickness: 0.02, bevelSize: 0.02
});
const arrow = new THREE.Mesh(arrowGeo, copperMat);
arrow.rotation.y = Math.PI / 2;
arrow.position.set(-1.25, 0, -0.04);
arrow.castShadow = true;
arrowGroup.add(arrow);

// Arrow tail / feather
const tailShape = new THREE.Shape();
tailShape.moveTo(0, 0);
tailShape.lineTo(-1.8, 0.5);
tailShape.lineTo(-1.5, 0);
tailShape.lineTo(-1.8, -0.5);
tailShape.closePath();

const tailGeo = new THREE.ExtrudeGeometry(tailShape, {
  depth: 0.06, bevelEnabled: true, bevelThickness: 0.01, bevelSize: 0.01
});
const tail = new THREE.Mesh(tailGeo, copperMat);
tail.rotation.y = Math.PI / 2;
tail.position.set(-1.8, 0, -0.03);
tail.castShadow = true;
arrowGroup.add(tail);

// Crossbar on arrow (perpendicular stabilizer)
const crossbarGeo = new THREE.BoxGeometry(0.6, 0.06, 0.06);
const crossbar = new THREE.Mesh(crossbarGeo, copperMat);
crossbar.position.set(-1.8, 0, 0);
crossbar.rotation.y = Math.PI / 2;
arrowGroup.add(crossbar);

// ── Directional Arms ─────────────────────────────────────
const dirs = ['N', 'S', 'E', 'W'];
const dirAngles = [0, Math.PI, Math.PI / 2, -Math.PI / 2];
const dirGroup = new THREE.Group();
dirGroup.position.y = 7.5;
weathervane.add(dirGroup);

// Cross frame
const frameGeo = new THREE.BoxGeometry(4.5, 0.06, 0.06);
const frame1 = new THREE.Mesh(frameGeo, darkMetalMat);
frame1.castShadow = true;
dirGroup.add(frame1);

const frame2 = new THREE.Mesh(frameGeo, darkMetalMat);
frame2.rotation.y = Math.PI / 2;
frame2.castShadow = true;
dirGroup.add(frame2);

// Direction labels as 3D text using sprites
function createLabel(text, x, z) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'transparent';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = 'bold 80px Georgia';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#d4a843';
  ctx.shadowColor = '#000';
  ctx.shadowBlur = 6;
  ctx.fillText(text, 64, 64);

  const texture = new THREE.CanvasTexture(canvas);
  const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.position.set(x, 0, z);
  sprite.scale.set(0.6, 0.6, 1);
  return sprite;
}

const labelPositions = [
  ['N', 0, 2.3],
  ['S', 0, -2.3],
  ['E', 2.3, 0],
  ['W', -2.3, 0]
];

labelPositions.forEach(([text, x, z]) => {
  dirGroup.add(createLabel(text, x, z));
});

// Small decorative balls at ends
labelPositions.forEach(([, x, z]) => {
  const ball = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 8, 8),
    brassMat
  );
  ball.position.set(x, 0, z);
  dirGroup.add(ball);
});

// ── Support ring below arrow ─────────────────────────────
const supportRing = new THREE.Mesh(
  new THREE.TorusGeometry(0.5, 0.03, 8, 32),
  brassMat
);
supportRing.rotation.x = Math.PI / 2;
supportRing.position.y = 8.5;
weathervane.add(supportRing);

// ── Decorative scrollwork on pole ────────────────────────
for (let i = 0; i < 3; i++) {
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.2 + i * 0.05, 0.02, 8, 24),
    brassMat
  );
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 3 + i * 1.5;
  weathervane.add(ring);
}

// ── Roof / Cupola (decorative top piece) ─────────────────
const roofGeo = new THREE.ConeGeometry(0.5, 0.6, 4);
const roof = new THREE.Mesh(roofGeo, copperMat);
roof.position.y = 11.5;
roof.rotation.y = Math.PI / 4;
roof.castShadow = true;
weathervane.add(roof);

// ── Wind simulation ──────────────────────────────────────
let targetAngle = 0;
let currentAngle = 0;
let windChangeTimer = 0;
let gustIntensity = 0;

function updateWind(dt) {
  windChangeTimer -= dt;
  if (windChangeTimer <= 0) {
    targetAngle = Math.random() * Math.PI * 2;
    windChangeTimer = 2 + Math.random() * 4;
    gustIntensity = 0.3 + Math.random() * 0.7;
  }

  // Smooth interpolation toward target
  const speed = 0.8 * gustIntensity;
  currentAngle += (targetAngle - currentAngle) * speed * dt;

  // Add slight oscillation (gust effect)
  const oscillation = Math.sin(Date.now() * 0.003) * 0.05 * gustIntensity;
  arrowGroup.rotation.y = currentAngle + oscillation;
}

// ── Stars background ─────────────────────────────────────
const starCount = 500;
const starPositions = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI * 0.5;
  const r = 80 + Math.random() * 20;
  starPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  starPositions[i * 3 + 1] = r * Math.cos(phi) + 10;
  starPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}
const starGeo = new THREE.BufferGeometry();
starGeo.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.15, transparent: true, opacity: 0.7 });
scene.add(new THREE.Points(starGeo, starMat));

// ── Animation Loop ───────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();

  updateWind(dt);
  controls.update();

  // Subtle warm light flicker
  warmLight.intensity = 1.5 + Math.sin(Date.now() * 0.002) * 0.3;

  renderer.render(scene, camera);
}

animate();

