const frameMat = darkWoodMat;
const topBar = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.04, 0.04), frameMat);
topBar.position.set(0, 2.42, 0.36);
clock.add(topBar);
const botBar = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.04, 0.04), frameMat);
botBar.position.set(0, 0.62, 0.36);
clock.add(botBar);
const leftBar = new THREE.Mesh(new THREE.BoxGeometry(0.04, 1.84, 0.04), frameMat);
leftBar.position.set(-0.455, 1.52, 0.36);
clock.add(leftBar);
const rightBar = new THREE.Mesh(new THREE.BoxGeometry(0.04, 1.84, 0.04), frameMat);
rightBar.position.set(0.455, 1.52, 0.36);
clock.add(rightBar);

// ── Animation ──
const clockTime = new Date();
const pendulumPeriod = 2.0; // seconds per full swing
const maxAngle = Math.PI / 8; // ~22.5 degrees

function animate() {
  requestAnimationFrame(animate);

  const t = performance.now() / 1000;

  // Pendulum swing - damped harmonic motion
  const angle = Math.sin(t * (2 * Math.PI / pendulumPeriod)) * maxAngle;
  pendulumPivot.rotation.z = angle;

  // Slowly rotate clock hands
  const seconds = clockTime.getSeconds() + clockTime.getMilliseconds() / 1000;
  const minutes = clockTime.getMinutes() + seconds / 60;
  const hours = (clockTime.getHours() % 12) + minutes / 60;

  minuteHand.rotation.z = -(minutes / 60) * Math.PI * 2;
  hourHand.rotation.z = -(hours / 12) * Math.PI * 2;

  // Subtle point light flicker
  pointLight.intensity = 0.8 + Math.sin(t * 0.5) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

animate();
</script>
</body>
</html>
```

This creates a fully rendered 3D grandfather clock with:

- **Clock cabinet** — dark wood body with a pediment top, base, and brass accents
- **Clock face** — white dial with 12 brass hour markers, glass cover, and working hour/minute hands synced to your real time
- **Swinging pendulum** — brass rod and weighted bob swinging with realistic harmonic motion (~22.5° amplitude, 2s period)
- **Lower display door** — glass panel with wooden frame
- **Lighting** — warm key light, cool fill light, ambient, and a subtle flickering point light
- **OrbitControls** — drag to rotate, scroll to zoom
- **Shadows & fog** — soft shadow mapping and atmospheric depth fog

