```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>3D Compass Rose</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #0a0a1a; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene Setup ──────────────────────────────────────────
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.015);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 14, 10);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.maxPolarAngle = Math.PI / 2.1;
controls.minDistance = 5;
controls.maxDistance = 30;

// ── Lighting ─────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x334466, 0.8));

const dirLight = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight.position.set(5, 12, 8);
dirLight.castShadow = true;
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.6);
fillLight.position.set(-6, 4, -4);
scene.add(fillLight);

const pointLight = new THREE.PointLight(0xffaa44, 1.5, 20);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// ── Materials ────────────────────────────────────────────
const matRed    = new THREE.MeshStandardMaterial({ color: 0xcc2233, metalness: 0.6, roughness: 0.25 });
const matGold   = new THREE.MeshStandardMaterial({ color: 0xd4a843, metalness: 0.8, roughness: 0.2 });
const matSilver = new THREE.MeshStandardMaterial({ color: 0x8899aa, metalness: 0.7, roughness: 0.3 });
const matDark   = new THREE.MeshStandardMaterial({ color: 0x1a1a2e, metalness: 0.5, roughness: 0.4 });
const matWhite  = new THREE.MeshStandardMaterial({ color: 0xeeddcc, metalness: 0.3, roughness: 0.5 });

// ── Pointer Shape Factory ────────────────────────────────
function createPointerShape(length, baseWidth, tipWidth) {
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.lineTo(tipWidth / 2, baseWidth);
  s.lineTo(0, length);
  s.lineTo(-tipWidth / 2, baseWidth);
  s.closePath();
  return s;
}

function createPointer(length, baseWidth, tipWidth, material, offsetAngle = 0) {
  const shape = createPointerShape(length, baseWidth, tipWidth);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.15, bevelEnabled: true, bevelThickness: 0.05, bevelSize: 0.05, bevelSegments: 3
  });
  const mesh = new THREE.Mesh(geo, material);
  mesh.rotation.x = -Math.PI / 2;
  mesh.rotation.z = offsetAngle;
  mesh.position.y = 0.08;
  mesh.castShadow = true;
  return mesh;
}

// ── Build Compass Rose ───────────────────────────────────
const compass = new THREE.Group();

// Main N/S pointers (red)
const nPtr = createPointer(4.5, 1.2, 0.5, matRed, 0);
compass.add(nPtr);
const sPtr = createPointer(4.5, 1.2, 0.5, matRed, Math.PI);
compass.add(sPtr);

// Main E/W pointers (gold)
const ePtr = createPointer(4.5, 1.2, 0.5, matGold, Math.PI / 2);
compass.add(ePtr);
const wPtr = createPointer(4.5, 1.2, 0.5, matGold, -Math.PI / 2);
compass.add(wPtr);

// Intermediate pointers (silver)
const intermediates = [
  { angle: Math.PI / 4,  mat: matSilver },
  { angle: -Math.PI / 4, mat: matSilver },
  { angle: 3 * Math.PI / 4, mat: matSilver },
  { angle: -3 * Math.PI / 4, mat: matSilver },
];
intermediates.forEach(({ angle, mat }) => {
  compass.add(createPointer(3.0, 0.8, 0.35, mat, angle));
});

// Half-wind pointers (small, subtle)
const halfWinds = [
  Math.PI / 8, -Math.PI / 8, 3 * Math.PI / 8, -3 * Math.PI / 8,
  5 * Math.PI / 8, -5 * Math.PI / 8, 7 * Math.PI / 8, -7 * Math.PI / 8,
];
halfWinds.forEach(angle => {
  compass.add(createPointer(2.0, 0.5, 0.2, matDark, angle));
});

// ── Decorative Rings ─────────────────────────────────────
function makeRing(radius, tubeRadius, material) {
  const geo = new THREE.TorusGeometry(radius, tubeRadius, 16, 64);
  const mesh = new THREE.Mesh(geo, material);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.2;
  return mesh;
}

compass.add(makeRing(5.2, 0.06, matGold));
compass.add(makeRing(4.8, 0.04, matSilver));
compass.add(makeRing(3.5, 0.05, matDark));

// ── Central Hub ──────────────────────────────────────────
const hubGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.35, 32);
const hub = new THREE.Mesh(hubGeo, matGold);
hub.position.y = 0.18;
compass.add(hub);

const hubTopGeo = new THREE.CylinderGeometry(0.45, 0.6, 0.12, 32);
const hubTop = new THREE.Mesh(hubTopGeo, matRed);
hubTop.position.y = 0.38;
compass.add(hubTop);

const hubCapGeo = new THREE.SphereGeometry(0.15, 16, 16);
const hubCap = new THREE.Mesh(hubCapGeo, matGold);
hubCap.position.y = 0.5;
compass.add(hubCap);

// ── Cardinal Direction Labels (small cones) ──────────────
const labelPositions = [
  { pos: [0, 0, -5.5], rot: [0, 0, 0] },
  { pos: [0, 0, 5.5], rot: [0, Math.PI, 0] },
  { pos: [5.5, 0, 0], rot: [0, Math.PI / 2, 0] },
  { pos: [-5.5, 0, 0], rot: [0, -Math.PI / 2, 0] },
];
labelPositions.forEach(({ pos, rot }) => {
  const markerGeo = new THREE.ConeGeometry(0.15, 0.4, 6);
  const marker = new THREE.Mesh(markerGeo, matGold);
  marker.position.set(...pos);
  marker.position.y = 0.3;
  marker.rotation.set(...rot);
  compass.add(marker);
});

// ── Base Plate ───────────────────────────────────────────
const plateGeo = new THREE.CylinderGeometry(6, 6.2, 0.2, 64);
const plate = new THREE.Mesh(plateGeo, matDark);
plate.position.y = -0.1;
compass.add(plate);

// Compass rose base circle with tick marks
const tickGroup = new THREE.Group();
for (let i = 0; i < 36; i++) {
  const angle = (i / 36) * Math.PI * 2;
  const isCardinal = i % 9 === 0;
  const tickLen = isCardinal ? 0.3 : 0.15;
  const tickGeo = new THREE.BoxGeometry(0.04, 0.06, tickLen);
  const tick = new THREE.Mesh(tickGeo, isCardinal ? matGold : matSilver);
  tick.position.y = 0.12;
  tick.position.x = Math.cos(angle) * 5.8;
  tick.position.z = Math.sin(angle) * 5.8;
  tick.rotation.y = angle;
  tickGroup.add(tick);
}
compass.add(tickGroup);

scene.add(compass);

// ── Ground Plane ─────────────────────────────────────────
const groundGeo = new THREE.PlaneGeometry(60, 60);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x0a0a1a, roughness: 0.9 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.25;
scene.add(ground);

// ── Starfield Particles ──────────────────────────────────
const starsGeo = new THREE.BufferGeometry();
const starCount = 800;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  starPos[i * 3]     = (Math.random() - 0.5) * 60;
  starPos[i * 3 + 1] = Math.random() * 25 + 2;
  starPos[i * 3 + 2] = (Math.random() - 0.5) * 60;
}
starsGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starsMat = new THREE.PointsMaterial({ color: 0xaabbdd, size: 0.08, sizeAttenuation: true });
scene.add(new THREE.Points(starsGeo, starsMat));

// ── Animation ────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle rotation
  compass.rotation.y = Math.sin(t * 0.15) * 0.3;

  // Subtle float
  compass.position.y = Math.sin(t * 0.5) * 0.15;

  // Pulsing point light
  pointLight.intensity = 1.5 + Math.sin(t * 2) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ───────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
