        headGroup.add(leftPatch);

        const rightPatch = new THREE.Mesh(patchGeo, eyePatchMaterial);
        rightPatch.position.set(0.25, 0.1, 0.45);
        rightPatch.scale.set(1, 1.2, 0.5);
        rightPatch.rotation.y = 0.3;
        headGroup.add(rightPatch);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.25, 0.1, 0.6);
        headGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.25, 0.1, 0.6);
        headGroup.add(rightEye);

        // Nose
        const noseGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const nose = new THREE.Mesh(noseGeo, noseMaterial);
        nose.position.set(0, -0.1, 0.65);
        nose.scale.set(1.2, 0.8, 0.8);
        headGroup.add(nose);

        // Limbs
        const limbLength = 1.2;
        const limbRadius = 0.25;

        // Front Left
        const flLimb = createLimb(limbLength, limbRadius);
        flLimb.position.set(-0.6, 0.5, 0.8);
        flLimb.rotation.z = Math.PI / 2.5;
        flLimb.rotation.x = -0.5;
        slothGroup.add(flLimb);

        // Front Right
        const frLimb = createLimb(limbLength, limbRadius);
        frLimb.position.set(0.6, 0.5, 0.8);
        frLimb.rotation.z = -Math.PI / 2.5;
        frLimb.rotation.x = -0.5;
        slothGroup.add(frLimb);

        // Back Left
        const blLimb = createLimb(limbLength * 1.1, limbRadius * 1.1);
        blLimb.position.set(-0.7, -0.2, -0.5);
        blLimb.rotation.z = Math.PI / 2.2;
        blLimb.rotation.x = 0.2;
        slothGroup.add(blLimb);

        // Back Right
        const brLimb = createLimb(limbLength * 1.1, limbRadius * 1.1);
        brLimb.position.set(0.7, -0.2, -0.5);
        brLimb.rotation.z = -Math.PI / 2.2;
        brLimb.rotation.x = 0.2;
        slothGroup.add(brLimb);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle swaying
            slothGroup.rotation.z = Math.sin(time * 0.5) * 0.05;
            slothGroup.position.y = Math.sin(time * 0.5 + Math.PI/2) * 0.05;

            // Head bob
            headGroup.rotation.z = Math.sin(time * 0.8) * 0.05;
            headGroup.rotation.x = Math.sin(time * 0.6) * 0.02;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
