        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeebb, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 0.5, 10);
        pointLight.position.set(-2, 3, 2);
        scene.add(pointLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xd4af37, // Brass/Gold color
            metalness: 0.8,
            roughness: 0.3,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            metalness: 0.9,
            roughness: 0.4,
        });

        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaccff,
            metalness: 0,
            roughness: 0,
            transmission: 0.9,
            thickness: 0.5,
            ior: 1.5,
        });

        // Telescope Construction
        const telescopeGroup = new THREE.Group();

        // Main Tube
        const mainTubeGeo = new THREE.CylinderGeometry(0.8, 0.8, 5, 32);
        const mainTube = new THREE.Mesh(mainTubeGeo, brassMaterial);
        mainTube.rotation.x = Math.PI / 2;
        mainTube.castShadow = true;
        mainTube.receiveShadow = true;
        telescopeGroup.add(mainTube);

        // Front Lens Housing (Wider part)
        const frontHousingGeo = new THREE.CylinderGeometry(1.1, 1.1, 1.5, 32);
        const frontHousing = new THREE.Mesh(frontHousingGeo, brassMaterial);
        frontHousing.rotation.x = Math.PI / 2;
        frontHousing.position.z = 3;
        frontHousing.castShadow = true;
        frontHousing.receiveShadow = true;
        telescopeGroup.add(frontHousing);

        // Front Lens Rim
        const frontRimGeo = new THREE.TorusGeometry(1.1, 0.05, 16, 32);
        const frontRim = new THREE.Mesh(frontRimGeo, darkMetalMaterial);
        frontRim.position.z = 3.75;
        telescopeGroup.add(frontRim);

        // Front Glass
        const frontGlassGeo = new THREE.CircleGeometry(1.05, 32);
        const frontGlass = new THREE.Mesh(frontGlassGeo, glassMaterial);
        frontGlass.position.z = 3.76;
        telescopeGroup.add(frontGlass);

        // Eyepiece (Narrower part)
        const eyepieceGeo = new THREE.CylinderGeometry(0.4, 0.5, 1.5, 32);
        const eyepiece = new THREE.Mesh(eyepieceGeo, brassMaterial);
        eyepiece.rotation.x = Math.PI / 2;
        eyepiece.position.z = -3;
        eyepiece.castShadow = true;
        eyepiece.receiveShadow = true;
        telescopeGroup.add(eyepiece);

        // Eyepiece Rim
        const eyepieceRimGeo = new THREE.TorusGeometry(0.4, 0.05, 16, 32);
        const eyepieceRim = new THREE.Mesh(eyepieceRimGeo, darkMetalMaterial);
        eyepieceRim.position.z = -3.75;
        telescopeGroup.add(eyepieceRim);

        // Decorative Rings
        const ringGeo = new THREE.TorusGeometry(0.82, 0.05, 16, 32);
        const ring1 = new THREE.Mesh(ringGeo, darkMetalMaterial);
        ring1.position.z = 1;
        telescopeGroup.add(ring1);

        const ring2 = new THREE.Mesh(ringGeo, darkMetalMaterial);
        ring2.position.z = -1;
        telescopeGroup.add(ring2);

        // Finder Scope (Small telescope on top)
        const finderGroup = new THREE.Group();
        const finderTubeGeo = new THREE.CylinderGeometry(0.2, 0.2, 2, 16);
        const finderTube = new THREE.Mesh(finderTubeGeo, brassMaterial);
        finderTube.rotation.x = Math.PI / 2;
        finderGroup.add(finderTube);

        const finderMountGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.5, 8);
        const mount1 = new THREE.Mesh(finderMountGeo, darkMetalMaterial);
        mount1.position.set(0.5, 0, 0.5);
        finderGroup.add(mount1);
        const mount2 = new THREE.Mesh(finderMountGeo, darkMetalMaterial);
        mount2.position.set(0.5, 0, -0.5);
        finderGroup.add(mount2);

        finderGroup.position.set(0, 0.9, 0);
        telescopeGroup.add(finderGroup);

        // Tripod/Mount (Simple representation)
        const mountBaseGeo = new THREE.CylinderGeometry(0.5, 0.6, 0.2, 32);
        const mountBase = new THREE.Mesh(mountBaseGeo, darkMetalMaterial);
        mountBase.position.y = -1.2;
        telescopeGroup.add(mountBase);

        const mountPillarGeo = new THREE.CylinderGeometry(0.3, 0.3, 1.5, 16);
        const mountPillar = new THREE.Mesh(mountPillarGeo, darkMetalMaterial);
        mountPillar.position.y = -0.4;
        telescopeGroup.add(mountPillar);

        // Position the whole telescope
        telescopeGroup.rotation.z = -Math.PI / 6; // Tilt it up slightly
        telescopeGroup.rotation.y = Math.PI / 4; // Angle it slightly
        scene.add(telescopeGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            telescopeGroup.rotation.y += 0.002;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
