        // Lemur Group
        const lemur = new THREE.Group();

        // Body
        const bodyGeo = new THREE.SphereGeometry(0.9, 32, 32);
        const body = new THREE.Mesh(bodyGeo, greyFur);
        body.scale.set(1, 1.1, 0.9);
        body.position.y = 0.5;
