        const earGeo = new THREE.SphereGeometry(0.25, 32, 32);
        const earL = new THREE.Mesh(earGeo, greyFur);
        earL.position.set(-0.5, 2.0, 0.2);
        lemur.add(earL);
        const earR = new THREE.Mesh(earGeo, greyFur);
        earR.position.set(0.5, 2.0, 0.2);
