        const eyeLWhite = new THREE.Mesh(eyeGeo, eyeWhite);
        eyeLWhite.position.set(-0.22, 1.65, 0.75);
        lemur.add(eyeLWhite);
        const eyeLPupil = new THREE.Mesh(new THREE.SphereGeometry(0.1, 32, 32), eyePupil);
        eyeLPupil.position.set(-0.22, 1.65, 0.88);
        lemur.add(eyeLPupil);

        // Right Eye
        const eyeRWhite = new THREE.Mesh(eyeGeo, eyeWhite);
        eyeRWhite.position.set(0.22, 1.65, 0.75);
        lemur.add(eyeRWhite);
        const eyeRPupil = new THREE.Mesh(new THREE.SphereGeometry(0.1, 32, 32), eyePupil);
