        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x4444ff, 0.8);
        pointLight.position.set(-5, -5, 5);
        scene.add(pointLight);

        // Magnifying Glass Group
        const magnifyingGlass = new THREE.Group();

        // 1. The Frame (Torus)
        const frameGeometry = new THREE.TorusGeometry(2, 0.15, 16, 50);
        const frameMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.3, 
            metalness: 0.8 
        });
        const frame = new THREE.Mesh(frameGeometry, frameMaterial);
        frame.castShadow = true;
        magnifyingGlass.add(frame);

        // 2. The Lens (Circle with transparency)
        const lensGeometry = new THREE.CircleGeometry(1.85, 32);
        const lensMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x88ccff,
            transparent: true,
            opacity: 0.3,
            roughness: 0.1,
            metalness: 0.1,
            transmission: 0.9, // Glass-like transmission
            thickness: 0.5,
            side: THREE.DoubleSide
        });
        const lens = new THREE.Mesh(lensGeometry, lensMaterial);
        magnifyingGlass.add(lens);

        // 3. The Handle
        const handleGroup = new THREE.Group();

        // Connector
        const connectorGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.5, 16);
        const connector = new THREE.Mesh(connectorGeo, frameMaterial);
        connector.position.y = -2.2;
        handleGroup.add(connector);

        // Grip
        const gripGeo = new THREE.CylinderGeometry(0.2, 0.15, 2.5, 16);
        const grip = new THREE.Mesh(gripGeo, frameMaterial);
        grip.position.y = -3.5;
        grip.castShadow = true;
        handleGroup.add(grip);

        // Rotate handle to attach to bottom of frame
        handleGroup.rotation.z = Math.PI / 2; // Point down
        handleGroup.position.y = -2; // Move to bottom of frame
        magnifyingGlass.add(handleGroup);

        // Tilt the whole glass slightly
        magnifyingGlass.rotation.x = 0.2;
        magnifyingGlass.rotation.y = -0.2;
        scene.add(magnifyingGlass);

        // Add a grid helper for context
        const gridHelper = new THREE.GridHelper(20, 20, 0x444444, 0x222222);
        gridHelper.position.y = -5;
        scene.add(gridHelper);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            const time = Date.now() * 0.001;
            magnifyingGlass.position.y = Math.sin(time) * 0.2;
            magnifyingGlass.rotation.z = Math.sin(time * 0.5) * 0.05;

            renderer.render(scene, camera);
