```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fennec Fox – Three.js</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a2e; }
canvas { display: block; }
#info {
  position: absolute; top: 12px; width: 100%; text-align: center;
  color: #f0d9a0; font-family: system-ui, sans-serif; font-size: 14px;
  pointer-events: none; text-shadow: 0 1px 4px rgba(0,0,0,.6);
}
</style>
</head>
<body>
<div id="info">🦊 Fennec Fox — drag to orbit · scroll to zoom</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ─── scene ─── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;

/* ─── lights ─── */
scene.add(new THREE.AmbientLight(0xffeedd, 0.6));
const sun = new THREE.DirectionalLight(0xfff0dd, 1.8);
sun.position.set(5, 8, 4);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.near = 1; sun.shadow.camera.far = 20;
sun.shadow.camera.left = -5; sun.shadow.camera.right = 5;
sun.shadow.camera.top = 5; sun.shadow.camera.bottom = -5;
scene.add(sun);

const rim = new THREE.DirectionalLight(0x6688cc, 0.4);
rim.position.set(-4, 3, -3);
scene.add(rim);

/* ─── materials ─── */
const fur      = new THREE.MeshStandardMaterial({ color: 0xd4a057, roughness: 0.9 });
const furLight = new THREE.MeshStandardMaterial({ color: 0xe8c07a, roughness: 0.85 });
const furDark  = new THREE.MeshStandardMaterial({ color: 0xb07830, roughness: 0.9 });
const white    = new THREE.MeshStandardMaterial({ color: 0xf5f0e8, roughness: 0.85 });
const black    = new THREE.MeshStandardMaterial({ color: 0x1a1008, roughness: 0.7 });
const nose     = new THREE.MeshStandardMaterial({ color: 0x2a1a0a, roughness: 0.5, metalness: 0.1 });
const innerEar = new THREE.MeshStandardMaterial({ color: 0xe8a0a0, roughness: 0.8 });

/* ─── helper ─── */
function mesh(geo, mat, pos, rot, scale, castShadow = true) {
  const m = new THREE.Mesh(geo, mat);
  if (pos) m.position.set(...pos);
  if (rot) m.rotation.set(...rot);
  if (scale) m.scale.set(...scale);
  m.castShadow = castShadow;
  m.receiveShadow = true;
  return m;
}

/* ─── fox group ─── */
const fox = new THREE.Group();

// body
fox.add(mesh(new THREE.SphereGeometry(1, 16, 12), fur, [0, 1.35, 0], null, [1, 0.85, 0.75]));
// chest (white)
fox.add(mesh(new THREE.SphereGeometry(0.65, 12, 10), white, [0, 1.15, 0.55], null, [0.9, 0.8, 0.6]));

// head
fox.add(mesh(new THREE.SphereGeometry(0.55, 14, 12), fur, [0, 2.15, 0.55], null, [1.1, 1, 0.95]));
// muzzle
fox.add(mesh(new THREE.SphereGeometry(0.28, 10, 8), furLight, [0, 1.92, 1.05], null, [1.3, 0.9, 1.1]));
fox.add(mesh(new THREE.SphereGeometry(0.18, 8, 6), white, [0, 1.85, 1.2], null, [1.2, 0.8, 1]));
// nose tip
fox.add(mesh(new THREE.SphereGeometry(0.06, 8, 6), nose, [0, 1.92, 1.35]));
// eyes
fox.add(mesh(new THREE.SphereGeometry(0.07, 8, 6), black, [-0.22, 2.22, 0.95]));
fox.add(mesh(new THREE.SphereGeometry(0.07, 8, 6), black, [0.22, 2.22, 0.95]));
// eye shine
fox.add(mesh(new THREE.SphereGeometry(0.025, 6, 4), white, [-0.20, 2.24, 1.01], null, null, false));
fox.add(mesh(new THREE.SphereGeometry(0.025, 6, 4), white, [0.24, 2.24, 1.01], null, null, false));

/* ─── big fennec ears ─── */
function makeEar(side) {
  const g = new THREE.Group();
  const s = side === 'left' ? -1 : 1;

  // outer ear shape (thin stretched sphere)
  g.add(mesh(new THREE.SphereGeometry(0.35, 10, 8), fur,
    [s * 0.28, 2.75, 0.45], [0, 0, s * 0.3], [0.55, 1.6, 0.5]));

  // inner ear
  g.add(mesh(new THREE.SphereGeometry(0.28, 8, 6), innerEar,
    [s * 0.26, 2.72, 0.48], [0, 0, s * 0.3], [0.45, 1.4, 0.4]));

  // ear tip
  g.add(mesh(new THREE.SphereGeometry(0.1, 6, 4), furDark,
    [s * 0.18, 3.35, 0.38], [0, 0, s * 0.2]));

  return g;
}
fox.add(makeEar('left'));
fox.add(makeEar('right'));

/* ─── legs ─── */
const legPositions = [
  [-0.35, 0.45, 0.5],  // front L
  [ 0.35, 0.45, 0.5],  // front R
  [-0.35, 0.45, -0.45], // hind L
  [ 0.35, 0.45, -0.45], // hind R
];
legPositions.forEach(p => {
  fox.add(mesh(new THREE.CapsuleGeometry(0.1, 0.6, 6, 8), fur, p));
  // paw
  fox.add(mesh(new THREE.SphereGeometry(0.12, 6, 4), furDark, [p[0], 0.12, p[2]], null, [1.3, 0.6, 1]));
});

/* ─── tail ─── */
const tailGroup = new THREE.Group();
tailGroup.position.set(0, 1.25, -0.6);

// main tail curve
const tailGeo = new THREE.CapsuleGeometry(0.12, 1.2, 6, 8);
const tailMesh = mesh(tailGeo, fur, [0, 0.4, -0.5], [Math.PI / 2.5, 0, 0.15]);
tailGroup.add(tailMesh);

// tail tip (white, bushy)
const tipGeo = new THREE.SphereGeometry(0.2, 8, 6);
const tipMesh = mesh(tipGeo, white, [0.15, 0.95, -1.05]);
tailGroup.add(tipMesh);

// extra fluff on tail
tailGroup.add(mesh(new THREE.SphereGeometry(0.15, 6, 4), white, [0.05, 0.75, -0.85], null, [1, 0.9, 1]));

fox.add(tailGroup);

scene.add(fox);

/* ─── ground ─── */
const groundGeo = new THREE.CircleGeometry(12, 48);
const groundMat = new THREE.MeshStandardMaterial({ color: 0xc2a060, roughness: 1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// scattered pebbles
for (let i = 0; i < 40; i++) {
  const r = 1.5 + Math.random() * 8;
  const a = Math.random() * Math.PI * 2;
  const s = 0.03 + Math.random() * 0.06;
  const pebble = mesh(
    new THREE.DodecahedronGeometry(s, 0),
    new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(0.08, 0.3 + Math.random() * 0.2, 0.35 + Math.random() * 0.25), roughness: 1 }),
    [Math.cos(a) * r, s * 0.5, Math.sin(a) * r],
    [Math.random(), Math.random(), Math.random()],
    [1, 0.5 + Math.random() * 0.5, 1],
    false
  );
  scene.add(pebble);
}

/* ─── animation ─── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // gentle idle breathing
  fox.position.y = Math.sin(t * 1.5) * 0.03;

  // subtle tail wag
  tailGroup.rotation.y = Math.sin(t * 2) * 0.15;
  tailGroup.rotation.z = Math.sin(t * 1.3) * 0.05;

  // slight head bob
  fox.children.forEach(c => {
    if (c.position && c.position.y > 1.8 && c.position.y < 2.5 && c !== tailGroup) {
      // already handled by group
    }
  });

  controls.update();
  renderer.render(scene, camera);
}
animate();

/* ─── resize ─── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's included:**

- **Fennec fox** built entirely from Three.js primitives (spheres, capsules) with sandy/tan fur, white underbelly & tail tip, dark paw pads, and black eyes with specular highlights
- **Oversized ears** — the signature fennec trait — with pink inner ear material
- **Subtle animations** — gentle breathing bob and a swishing tail
- **Sandy ground** with scattered pebble decorations
- **Shadows** (PCF soft shadow map), rim lighting, and fog for atmosphere
- **OrbitControls** — drag to rotate, scroll to zoom
- Fully self-contained — just open the HTML file in a browser

