        }
        #instruction {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: rgba(255,255,255,0.6);
            pointer-events: none;
            font-size: 0.9rem;
            letter-spacing: 2px;
        }
    </style>
</head>
<body>
    <div id="ui">❄ SNOW GLOBE ❄</div>
    <div id="instruction">CLICK TO SHAKE</div>

    <!-- Import Three.js as an ES module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.FogExp2(0x1a1a2e, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.maxPolarAngle = Math.PI / 2; // Prevent going below ground
        controls.minDistance = 4;
        controls.maxDistance = 15;

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x4444ff, 0.5);
        pointLight.position.set(-5, 2, -5);
        scene.add(pointLight);

        // --- Snow Globe Group ---
        const globeGroup = new THREE.Group();
        scene.add(globeGroup);

        // 1. The Glass Sphere
        const glassGeometry = new THREE.SphereGeometry(2, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            ior: 1.5,
            clearcoat: 1,
            clearcoatRoughness: 0,
            transparent: true,
            opacity: 0.3,
            side: THREE.DoubleSide
        });
        const glassSphere = new THREE.Mesh(glassGeometry, glassMaterial);
        glassSphere.position.y = 2;
        globeGroup.add(glassSphere);

        // 2. The Base
        const baseGeometry = new THREE.CylinderGeometry(1.8, 2, 1.5, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3d2b1f, // Dark wood
            roughness: 0.6,
            metalness: 0.1
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = 0.75;
        base.castShadow = true;
        base.receiveShadow = true;
        globeGroup.add(base);

        // Base Top Rim
        const rimGeometry = new THREE.CylinderGeometry(2.0, 1.8, 0.2, 32);
        const rimMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.5, roughness: 0.2 });
        const rim = new THREE.Mesh(rimGeometry, rimMaterial);
        rim.position.y = 1.5;
        globeGroup.add(rim);

        // 3. Inside Content (Snow Ground)
        const groundGeometry = new THREE.CircleGeometry(1.9, 32);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = 0.2; // Just above the bottom of the sphere
        globeGroup.add(ground);

        // 4. Inside Content (Tree)
        const treeGroup = new THREE.Group();
        treeGroup.position.y = 0.2;

        // Trunk
        const trunkGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.6, 8);
        const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3c31 });
        const trunk = new THREE.Mesh(trunkGeo, trunkMat);
        trunk.position.y = 0.3;
        treeGroup.add(trunk);

        // Leaves (Cones)
        const leavesMat = new THREE.MeshStandardMaterial({ color: 0x2d5a27 });
        const leafGeo1 = new THREE.ConeGeometry(0.6, 1, 8);
        const leaf1 = new THREE.Mesh(leafGeo1, leavesMat);
        leaf1.position.y = 0.8;
        treeGroup.add(leaf1);

        const leafGeo2 = new THREE.ConeGeometry(0.45, 0.8, 8);
        const leaf2 = new THREE.Mesh(leafGeo2, leavesMat);
        leaf2.position.y = 1.3;
        treeGroup.add(leaf2);

        globeGroup.add(treeGroup);

        // 5. Snow Particles
        const particleCount = 400;
        const particlesGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const velocities = []; // Store velocity for animation

        for (let i = 0; i < particleCount; i++) {
            // Random position inside sphere
            const r = 1.8 * Math.cbrt(Math.random());
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta) + 2; // Center around y=2
            const z = r * Math.cos(phi);

            // Keep snow above the ground mostly
            if (y < 0.5) {
                positions[i * 3] = x;
                positions[i * 3 + 1] = 0.5 + Math.random() * 0.5;
                positions[i * 3 + 2] = z;
            } else {
                positions[i * 3] = x;
                positions[i * 3 + 1] = y;
                positions[i * 3 + 2] = z;
            }

            velocities.push({
                x: (Math.random() - 0.5) * 0.01,
                y: -Math.random() * 0.02 - 0.005,
                z: (Math.random() - 0.5) * 0.01,
                originalY: y
            });
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const particlesMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.08,
            transparent: true,
            opacity: 0.8
        });
        const snowSystem = new THREE.Points(particlesGeometry, particlesMaterial);
        globeGroup.add(snowSystem);

        // --- Animation Logic ---
        let shakeIntensity = 0;
        let shakeDecay = 0.95;

        function animate() {
            requestAnimationFrame(animate);

            // Snow Falling Logic
            const posAttribute = snowSystem.geometry.attributes.position;
            const positionsArray = posAttribute.array;

            for (let i = 0; i < particleCount; i++) {
                const idx = i * 3;
                const vel = velocities[i];

                // Apply gravity
                positionsArray[idx + 1] += vel.y;

                // Apply shake if active
                if (shakeIntensity > 0.01) {
                    positionsArray[idx] += (Math.random() - 0.5) * shakeIntensity;
                    positionsArray[idx + 1] += (Math.random() - 0.5) * shakeIntensity;
                    positionsArray[idx + 2] += (Math.random() - 0.5) * shakeIntensity;
                }

                // Reset if hits bottom
                if (positionsArray[idx + 1] < 0.2) {
                    positionsArray[idx + 1] = 3.5; // Reset to top
                    // Randomize X/Z slightly on reset
                    positionsArray[idx] = (Math.random() - 0.5) * 3;
                    positionsArray[idx + 2] = (Math.random() - 0.5) * 3;
                }
            }
            posAttribute.needsUpdate = true;

            // Shake Decay
            if (shakeIntensity > 0) {
                shakeIntensity *= shakeDecay;
                // Rotate globe slightly during shake
                globeGroup.rotation.z = (Math.random() - 0.5) * shakeIntensity * 0.5;
                globeGroup.rotation.x = (Math.random() - 0.5) * shakeIntensity * 0.5;
            } else {
                // Gentle idle rotation
                globeGroup.rotation.y += 0.002;
                globeGroup.rotation.z = 0;
                globeGroup.rotation.x = 0;
            }

            controls.update();
            renderer.render(scene, camera);
        }

        // --- Interaction ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        window.addEventListener('mousedown', () => {
            shakeIntensity = 0.3;
        });

        // Touch support for mobile
        window.addEventListener('touchstart', () => {
            shakeIntensity = 0.3;
        });

        animate();
    </script>
</body>
</html>
