            { x: 0.6, y: -0.6, z: 0.6, rz: -0.3 },
            { x: -0.6, y: -0.6, z: -0.6, rz: 0.3 },
            { x: 0.6, y: -0.6, z: -0.6, rz: -0.3 }
        ];

        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, pinkMat);
            leg.position.set(pos.x, pos.y, pos.z);
            leg.rotation.z = pos.rz;
            leg.castShadow = true;
            axolotlGroup.add(leg);
        });

        scene.add(axolotlGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            const time = Date.now() * 0.001;
            axolotlGroup.position.y = Math.sin(time) * 0.2;
            axolotlGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
