```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Firefly Jar</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050510);
scene.fog = new THREE.FogExp2(0x050510, 0.04);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.2, 0);
controls.maxDistance = 10;
controls.minDistance = 2;

// --- Jar ---
const jarGroup = new THREE.Group();
scene.add(jarGroup);

// Glass material
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.05,
  ior: 1.5,
  thickness: 0.1,
  side: THREE.DoubleSide,
  depthWrite: false,
});

// Jar body — tapered cylinder
const jarGeo = new THREE.CylinderGeometry(0.6, 0.7, 1.8, 32, 1, true);
const jar = new THREE.Mesh(jarGeo, glassMat);
jar.position.y = 1.2;
jarGroup.add(jar);

// Jar bottom
const bottomGeo = new THREE.CircleGeometry(0.7, 32);
const bottom = new THREE.Mesh(bottomGeo, glassMat);
bottom.rotation.x = -Math.PI / 2;
bottom.position.y = 0.3;
jarGroup.add(bottom);

// Jar rim
const rimGeo = new THREE.TorusGeometry(0.6, 0.025, 8, 32);
const rimMat = new THREE.MeshPhysicalMaterial({ color: 0x888888, metalness: 0.8, roughness: 0.2 });
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 2.1;
jarGroup.add(rim);

// Wire lid
const lidGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.08, 32, 1, true);
const lid = new THREE.Mesh(lidGeo, glassMat);
lid.position.y = 2.14;
jarGroup.add(lid);

// Lid top cap
const capGeo = new THREE.CylinderGeometry(0.45, 0.55, 0.06, 32);
const cap = new THREE.Mesh(capGeo, glassMat);
cap.position.y = 2.18;
jarGroup.add(cap);

// Lid wire mesh
const wireMat = new THREE.MeshBasicMaterial({ color: 0xaaaacc, wireframe: true });
for (let i = 0; i < 6; i++) {
  const ringGeo = new THREE.TorusGeometry(0.48, 0.005, 4, 32);
  const ring = new THREE.Mesh(ringGeo, wireMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 2.12 + i * 0.015;
  jarGroup.add(ring);
}

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x111118, roughness: 1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
scene.add(ground);

// --- Fireflies ---
const fireflies = [];
const COUNT = 18;
const jarRadius = 0.55;
const jarBottom = 0.4;
const jarTop = 2.0;

const glowTexture = (() => {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,200,1)');
  g.addColorStop(0.2, 'rgba(255,230,100,0.8)');
  g.addColorStop(0.5, 'rgba(255,200,50,0.3)');
  g.addColorStop(1, 'rgba(255,180,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
})();

for (let i = 0; i < COUNT; i++) {
  const group = new THREE.Group();

  // Glowing core
  const coreGeo = new THREE.SphereGeometry(0.015, 8, 8);
  const coreMat = new THREE.MeshBasicMaterial({ color: 0xffffcc });
  const core = new THREE.Mesh(coreGeo, coreMat);
  group.add(core);

  // Glow sprite
  const spriteMat = new THREE.SpriteMaterial({
    map: glowTexture,
    blending: THREE.AdditiveBlending,
    transparent: true,
    opacity: 0.9,
    depthWrite: false,
  });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.setScalar(0.15);
  group.add(sprite);

  // Point light (only some get one for performance)
  let light = null;
  if (i < 6) {
    light = new THREE.PointLight(0xffcc44, 0.6, 2.5, 2);
    group.add(light);
  }

  // Random position inside jar
  const angle = Math.random() * Math.PI * 2;
  const r = Math.random() * jarRadius;
  group.position.set(
    Math.cos(angle) * r,
    jarBottom + Math.random() * (jarTop - jarBottom),
    Math.sin(angle) * r
  );

  scene.add(group);

  fireflies.push({
    group,
    sprite,
    light,
    phase: Math.random() * Math.PI * 2,
    speed: 0.3 + Math.random() * 0.5,
    amplitude: 0.1 + Math.random() * 0.2,
    pulseSpeed: 1 + Math.random() * 2,
    pulsePhase: Math.random() * Math.PI * 2,
    orbitAngle: angle,
    orbitRadius: r,
    orbitSpeed: (Math.random() - 0.5) * 0.4,
    yBase: group.position.y,
    yAmplitude: 0.1 + Math.random() * 0.3,
  });
}

// --- Ambient ---
scene.add(new THREE.AmbientLight(0x222244, 0.3));
const moonLight = new THREE.DirectionalLight(0x4466aa, 0.15);
moonLight.position.set(-3, 5, 2);
scene.add(moonLight);

// --- Stars (tiny background dots) ---
const starsGeo = new THREE.BufferGeometry();
const starPos = [];
for (let i = 0; i < 500; i++) {
  starPos.push(
    (Math.random() - 0.5) * 40,
    Math.random() * 15 + 2,
    (Math.random() - 0.5) * 40
  );
}
starsGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
const starsMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.03, transparent: true, opacity: 0.6 });
scene.add(new THREE.Points(starsGeo, starsMat));

// --- Animate ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  for (const f of fireflies) {
    // Orbital drift
    f.orbitAngle += f.orbitSpeed * 0.016;

    // Target position
    const targetX = Math.cos(f.orbitAngle) * f.orbitRadius;
    const targetZ = Math.sin(f.orbitAngle) * f.orbitRadius;
    const targetY = f.yBase + Math.sin(t * f.speed + f.phase) * f.yAmplitude;

    // Smooth follow
    f.group.position.x += (targetX - f.group.position.x) * 0.01;
    f.group.position.z += (targetZ - f.group.position.z) * 0.01;
    f.group.position.y += (targetY - f.group.position.y) * 0.01;

    // Pulse
    const pulse = 0.5 + 0.5 * Math.sin(t * f.pulseSpeed + f.pulsePhase);
    const glowScale = 0.1 + pulse * 0.15;
    f.sprite.scale.setScalar(glowScale);
    f.sprite.material.opacity = 0.4 + pulse * 0.6;

    if (f.light) {
      f.light.intensity = pulse * 0.8;
    }
  }

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in the demo:**

- **Glass jar** — tapered cylinder with `MeshPhysicalMaterial` transmission (realistic glass), a torus rim, and a wire-mesh lid
- **18 fireflies** — each is a tiny bright core + additive-blended glow sprite + (for 6 of them) a real `PointLight` for area illumination
- **Behavior** — fireflies orbit slowly inside the jar, drift vertically with sinusoidal motion, and pulse in brightness asynchronously
- **Atmosphere** — dark background, exponential fog, distant star particles, soft moonlight, ACES filmic tone mapping
- **Interaction** — `OrbitControls` with damping to rotate/zoom around the jar

