<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kaleidoscope</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="x-shader/x-vertex" id="vshader">
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
</script>

<script type="x-shader/x-fragment" id="fshader">
  precision highp float;
  varying vec2 vUv;
  uniform float uTime;
  uniform vec2 uResolution;
  uniform vec2 uMouse;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
  }

  vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(6.28318 * (c * t + d));
  }

  void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution.xy) / min(uResolution.x, uResolution.y);
    vec2 mouse = (uMouse - 0.5 * uResolution.xy) / min(uResolution.x, uResolution.y);

    float t = uTime * 0.3;

    // Polar coordinates
    vec2 p = uv;

    // Mouse-influenced rotation
    float angle = atan(p.y, p.x);
    float radius = length(p);

    // Add swirl from mouse
    angle += mouse.x * 2.0 * sin(radius * 3.0 + t);
    radius += mouse.y * 0.2 * sin(radius * 5.0 - t * 2.0);

    // Kaleidoscope fold - 8 segments
    float segments = 8.0;
    angle = mod(angle, 6.28318 / segments);
    angle = abs(angle - 3.14159 / segments);

    // Convert back to cartesian
    vec2 sym = vec2(cos(angle), sin(angle)) * radius;

    // Layered pattern generation
    float pattern = 0.0;

    // Layer 1: Concentric rings
    float rings = sin(radius * 12.0 - t * 3.0 + sym.x * 4.0);
    pattern += rings * 0.4;

    // Layer 2: Radial waves
    float waves = sin(angle * 6.0 + radius * 8.0 - t * 2.0);
    pattern += waves * 0.3;

    // Layer 3: Interference pattern
    float interference = sin(sym.x * 10.0 + t) * sin(sym.y * 10.0 - t * 1.5);
    pattern += interference * 0.3;

    // Layer 4: Organic noise-like detail
    float detail = sin(radius * 20.0 + t * 4.0) * sin(angle * 12.0 - t);
    pattern += detail * 0.2;

    // Layer 5: Pulsing center
    float pulse = exp(-radius * 3.0) * sin(t * 2.0) * 0.5;
    pattern += pulse;

    // Color mapping
    float colorShift = pattern * 0.3 + radius * 0.5 + t * 0.1;
    vec3 col = palette(colorShift);

    // Brightness modulation
    float brightness = 0.6 + 0.4 * sin(pattern * 3.14159);
    col *= brightness;

    // Vignette
    float vignette = 1.0 - radius * 0.8;
    vignette = smoothstep(0.0, 1.0, vignette);
    col *= vignette;

    // Glow at center
    col += vec3(0.3, 0.15, 0.4) * exp(-radius * 4.0) * (0.8 + 0.2 * sin(t * 3.0));

    // Subtle edge glow per segment
    float edgeGlow = exp(-abs(angle) * 40.0) * 0.3;
    col += vec3(0.2, 0.4, 0.6) * edgeGlow;

    gl_FragColor = vec4(col, 1.0);
  }
</script>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
