const rimLight = new THREE.DirectionalLight(0xffaa44, 1.2);
rimLight.position.set(0, 2, -8);
scene.add(rimLight);

// ── Materials ────────────────────────────────────────────────
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xd4a843,
  metalness: 0.92,
  roughness: 0.18,
});

const goldMatDark = new THREE.MeshStandardMaterial({
