  metalness: 0.9,
  roughness: 0.25,
});

const watchFaceMat = new THREE.MeshStandardMaterial({
  color: 0xfff8ee,
  metalness: 0.05,
  roughness: 0.6,
  emissive: 0xfff8ee,
  emissiveIntensity: 0.15,
});

const darkMat = new THREE.MeshStandardMaterial({
  color: 0x111111,
  metalness: 0.8,
  roughness: 0.3,
});

// ── Chain Link Builder ───────────────────────────────────────
function createLink(radius = 0.3, tubeRadius = 0.06) {
  const torusGeo = new THREE.TorusGeometry(radius, tubeRadius, 16, 32);
  const mesh = new THREE.Mesh(torusGeo, goldMat);
  mesh.castShadow = true;
  return mesh;
}

// ── Build Chain ──────────────────────────────────────────────
const chainGroup = new THREE.Group();
const linkCount = 40;
const linkSpacing = 0.52;

for (let i = 0; i < linkCount; i++) {
  const t = i / linkCount;

  // Catenary-like curve
  const x = (t - 0.5) * 8;
  const sag = Math.cosh((t - 0.5) * 3) * 0.35;
  const y = 6 - sag;
  const z = Math.sin(t * Math.PI * 2) * 0.3;

  const link = createLink(0.28, 0.055);
  link.position.set(x, y, z);

  // Alternate orientation every other link
  if (i % 2 === 0) {
    link.rotation.y = Math.PI / 2;
  }

  // Gentle twist along the chain
  link.rotation.z = Math.sin(t * Math.PI * 3) * 0.15;

  chainGroup.add(link);
}

scene.add(chainGroup);

// ── Pocket Watch ─────────────────────────────────────────────
const watchGroup = new THREE.Group();
const watchX = -4;
const watchY = 6 - Math.cosh(-0.5 * 3) * 0.35;

// Watch body (cylinder)
const bodyGeo = new THREE.CylinderGeometry(1.0, 1.0, 0.35, 48);
const body = new THREE.Mesh(bodyGeo, goldMat);
body.rotation.x = Math.PI / 2;
watchGroup.add(body);

// Bezel rim
