const bezel = new THREE.Mesh(bezelGeo, goldMatDark);
bezel.position.z = 0.18;
watchGroup.add(bezel);

const bezelBack = bezel.clone();
bezelBack.position.z = -0.18;
watchGroup.add(bezelBack);

// Watch face
const faceGeo = new THREE.CircleGeometry(0.88, 48);
const face = new THREE.Mesh(faceGeo, watchFaceMat);
face.position.z = 0.185;
watchGroup.add(face);

// Hour markers
for (let h = 0; h < 12; h++) {
  const angle = (h / 12) * Math.PI * 2 - Math.PI / 2;
  const markerGeo = new THREE.BoxGeometry(
    h % 3 === 0 ? 0.06 : 0.035,
    h % 3 === 0 ? 0.18 : 0.12,
    0.02
  );
