  marker.position.x = Math.cos(angle) * 0.76;
  marker.position.y = Math.sin(angle) * 0.76;
  marker.position.z = 0.195;
  marker.rotation.z = angle + Math.PI / 2;
  watchGroup.add(marker);
}

// Hour hand
const hourHandGeo = new THREE.BoxGeometry(0.05, 0.45, 0.025);
const hourHand = new THREE.Mesh(hourHandGeo, darkMat);
hourHand.position.set(0.12, 0.12, 0.21);
hourHand.rotation.z = -0.4;
watchGroup.add(hourHand);

// Minute hand
const minuteHandGeo = new THREE.BoxGeometry(0.035, 0.6, 0.025);
const minuteHand = new THREE.Mesh(minuteHandGeo, darkMat);
minuteHand.position.set(-0.08, 0.18, 0.22);
minuteHand.rotation.z = 1.2;
watchGroup.add(minuteHand);

// Center pin
const pinGeo = new THREE.CylinderGeometry(0.04, 0.04, 0.06, 16);
const pin = new THREE.Mesh(pinGeo, goldMat);
pin.rotation.x = Math.PI / 2;
pin.position.z = 0.23;
watchGroup.add(pin);

// Crown (winder) on top
const crownGeo = new THREE.CylinderGeometry(0.15, 0.18, 0.2, 16);
const crown = new THREE.Mesh(crownGeo, goldMatDark);
crown.rotation.z = Math.PI / 2;
crown.position.set(0, 1.1, 0);
watchGroup.add(crown);

// Crown ridges
for (let r = 0; r < 8; r++) {
  const ridgeGeo = new THREE.BoxGeometry(0.015, 0.18, 0.06);
  const ridge = new THREE.Mesh(ridgeGeo, goldMatDark);
  const a = (r / 8) * Math.PI * 2;
  ridge.position.set(
    0,
    1.1 + Math.sin(a) * 0.17,
    Math.cos(a) * 0.17
  );
  ridge.rotation.x = a;
  watchGroup.add(ridge);
}

// Bail (loop connecting to chain)
const bailGeo = new THREE.TorusGeometry(0.2, 0.04, 12, 24, Math.PI);
const bail = new THREE.Mesh(bailGeo, goldMat);
bail.position.set(0, 1.15, 0);
bail.rotation.y = Math.PI / 2;
watchGroup.add(bail);

// Sub-connector link
const connLink = createLink(0.18, 0.045);
connLink.position.set(0, 1.35, 0);
connLink.rotation.y = Math.PI / 2;
watchGroup.add(connLink);

watchGroup.position.set(watchX, watchY, Math.sin(0 * Math.PI * 2) * 0.3);
scene.add(watchGroup);

// ── Key (fob) at the other end ───────────────────────────────
const keyGroup = new THREE.Group();
const keyX = 4;
const keyY = 6 - Math.cosh(0.5 * 3) * 0.35;

const keyConnLink = createLink(0.18, 0.045);
keyConnLink.rotation.y = Math.PI / 2;
keyGroup.add(keyConnLink);

// Key bow (loop)
const bowGeo = new THREE.TorusGeometry(0.25, 0.04, 12, 32);
const bow = new THREE.Mesh(bowGeo, goldMat);
bow.position.y = 0.4;
keyGroup.add(bow);

// Key shaft
const shaftGeo = new THREE.CylinderGeometry(0.035, 0.035, 1.2, 12);
const shaft = new THREE.Mesh(shaftGeo, goldMat);
shaft.position.y = -0.2;
