const bitGeo = new THREE.BoxGeometry(0.12, 0.25, 0.04);
const bit = new THREE.Mesh(bitGeo, goldMatDark);
bit.position.set(0.04, -0.85, 0);
keyGroup.add(bit);

keyGroup.position.set(keyX, keyY, Math.sin(1 * Math.PI * 2) * 0.3);
scene.add(keyGroup);

// ── Subtle Animation ─────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const elapsed = clock.getElapsedTime();

  // Gentle sway
  chainGroup.rotation.z = Math.sin(elapsed * 0.5) * 0.015;
  watchGroup.rotation.z = Math.sin(elapsed * 0.5) * 0.02;
  keyGroup.rotation.z = Math.sin(elapsed * 0.5 + 1) * 0.02;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ───────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
