<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene, Camera, Renderer ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// --- Environment (colorful objects to refract) ---
const envScene = new THREE.Scene();

const envGeo = new THREE.BoxGeometry(2, 2, 2);
const colors = [0xff0040, 0x00ff88, 0x0088ff, 0xffaa00, 0xff00ff, 0x00ffff];
colors.forEach((c, i) => {
  const mat = new THREE.MeshStandardMaterial({ color: c, emissive: c, emissiveIntensity: 0.5 });
  const mesh = new THREE.Mesh(envGeo, mat);
  const angle = (i / colors.length) * Math.PI * 2;
  mesh.position.set(Math.cos(angle) * 5, (Math.random() - 0.5) * 4, Math.sin(angle) * 5);
  mesh.rotation.set(Math.random(), Math.random(), Math.random());
  envScene.add(mesh);
});

const envLight = new THREE.HemisphereLight(0xffffff, 0x444444, 2);
envScene.add(envLight);
envScene.add(new THREE.DirectionalLight(0xffffff, 3).translateZ(5));

const pmremGenerator = new THREE.PMREMGenerator(renderer);
pmremGenerator.compileEquirectangularShader();
const envMap = pmremGenerator.fromScene(envScene, 0.04).texture;
scene.environment = envMap;

// --- Glass Marble ---
const marbleGeo = new THREE.SphereGeometry(1.5, 256, 256);
const marbleMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 1.0,
  opacity: 1,
  metalness: 0.0,
  roughness: 0.0,
  ior: 1.52,
  thickness: 3.0,
  envMapIntensity: 1.5,
  clearcoat: 0.1,
  clearcoatRoughness: 0.0,
  attenuationColor: new THREE.Color(0.9, 0.95, 1.0),
  attenuationDistance: 4,
});

const marble = new THREE.Mesh(marbleGeo, marbleMat);
scene.add(marble);

// --- Small inner marble (core) for extra refraction ---
const coreGeo = new THREE.SphereGeometry(0.3, 64, 64);
const coreMat = new THREE.MeshPhysicalMaterial({
  color: 0x88ccff,
  transmission: 0.9,
  opacity: 1,
  roughness: 0.05,
  ior: 1.6,
  thickness: 1.0,
  envMapIntensity: 1.0,
  clearcoat: 0.5,
});
const core = new THREE.Mesh(coreGeo, coreMat);
scene.add(core);

// --- Lighting ---
scene.add(new THREE.DirectionalLight(0xffffff, 5).translateZ(8));
scene.add(new THREE.DirectionalLight(0x4488ff, 3).translateX(-6).translateY(4));
scene.add(new THREE.PointLight(0xff8844, 3, 20).translateX(5).translateY(-2));

// --- Floor (subtle reflection plane) ---
const floorGeo = new THREE.PlaneGeometry(40, 40);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e,
  roughness: 0.3,
  metalness: 0.8,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2;
scene.add(floor);

// --- Controls ---
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 3;
controls.maxDistance = 15;

// --- Animation ---
function animate(time) {
  requestAnimationFrame(animate);
  const t = time * 0.001;

  marble.rotation.y = t * 0.3;
  core.rotation.y = -t * 0.5;
  core.position.y = Math.sin(t * 0.8) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}
animate(0);

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
