            scene.add(treeGroup);
        }

        createTree(-10, -10);
        createTree(12, -8);
        createTree(-8, 10);
        createTree(15, 12);
        createTree(0, -15);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Hover effect
            eagleGroup.position.y = Math.sin(time * 1.5) * 0.2;

            // Subtle wing flap
            wingL.rotation.z = 0.2 + Math.sin(time * 2) * 0.1;
            wingR.rotation.z = -0.2 - Math.sin(time * 2) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
