  const seedBody = new THREE.Mesh(seedGeo, seedMat);
  seedBody.position.copy(pos);
  group.add(seedBody);

  // Stalk
  const stalkLen = 0.6 + Math.random() * 0.4;
  const stalk = new THREE.Mesh(stalkGeo, stalkMat);
  const midPoint = pos.clone().add(dir.clone().multiplyScalar(stalkLen * 0.5));
  stalk.position.copy(midPoint);
  stalk.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  stalk.scale.set(1, stalkLen, 1);
  group.add(stalk);

