      Math.cos(theta),
      Math.sin(theta) * Math.sin(phi)
    );

    // Rotate hairDir to align with stalk direction
    const up = new THREE.Vector3(0, 1, 0);
    const quat = new THREE.Quaternion().setFromUnitVectors(up, dir);
    hairDir.applyQuaternion(quat);

    const tip = hairBase.clone().add(hairDir.clone().multiplyScalar(hairLen));

    // Add slight curve via midpoint
    const mid = hairBase.clone().lerp(tip, 0.5);
    const perp = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)).normalize();
