const extrudeSettings = { depth: 0.08, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.04, bevelSegments: 6 };
const mainPadGeo = new THREE.ExtrudeGeometry(mainPadShape, extrudeSettings);
const mainPad = new THREE.Mesh(mainPadGeo, printMat);
mainPad.rotation.x = -Math.PI / 2;
mainPad.position.y = 0.01;
mainPad.castShadow = true;
mainPad.receiveShadow = true;
scene.add(mainPad);

// Toe pads — 4 digital pads in an arc, slightly staggered
const toeConfigs = [
  { x: -0.55, z: -0.85, rx: 0.18, rz: 0.22, angle: 0.3 },
  { x: -0.22, z: -1.05, rx: 0.17, rz: 0.21, angle: 0.1 },
  { x:  0.22, z: -1.05, rx: 0.17, rz: 0.21, angle: -0.1 },
  { x:  0.55, z: -0.85, rx: 0.18, rz: 0.22, angle: -0.3 },
];

toeConfigs.forEach(c => {
  const geo = new THREE.SphereGeometry(1, 24, 16);
  geo.scale(c.rx, 0.06, c.rz);
  const toe = new THREE.Mesh(geo, printMat);
  toe.position.set(c.x, 0.01, c.z);
  toe.rotation.y = c.angle;
  toe.castShadow = true;
  scene.add(toe);
});

// Claw marks — subtle crescent arcs above toe pads
const clawConfigs = [
  { x: -0.55, z: -1.15, angle: 0.3 },
  { x: -0.22, z: -1.35, angle: 0.1 },
  { x:  0.22, z: -1.35, angle: -0.1 },
  { x:  0.55, z: -1.15, angle: -0.3 },
];

const clawMat = new THREE.MeshStandardMaterial({ color: 0xc4956a, roughness: 0.7 });

clawConfigs.forEach(c => {
  const clawShape = new THREE.Shape();
  clawShape.moveTo(0, 0);
  clawShape.quadraticCurveTo(0.06, 0.08, 0, 0.16);
  const clawGeo = new THREE.ExtrudeGeometry(clawShape, { depth: 0.02, bevelEnabled: true, bevelThickness: 0.01, bevelSize: 0.01, bevelSegments: 2 });
  const claw = new THREE.Mesh(clawGeo, clawMat);
  claw.position.set(c.x, 0.01, c.z);
  claw.rotation.x = -Math.PI / 2;
  claw.rotation.z = -c.angle * 2;
  scene.add(claw);
});

// Lighting
const ambient = new THREE.AmbientLight(0x8888aa, 0.8);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffeedd, 1.8);
dirLight.position.set(3, 6, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 15;
dirLight.shadow.camera.left = -4;
dirLight.shadow.camera.right = 4;
dirLight.shadow.camera.top = 4;
dirLight.shadow.camera.bottom = -4;
scene.add(dirLight);

const rimLight = new THREE.DirectionalLight(0x6688cc, 0.5);
rimLight.position.set(-3, 2, -3);
scene.add(rimLight);

// Subtle snow particles
const snowCount = 300;
const snowGeo = new THREE.BufferGeometry();
const snowPos = new Float32Array(snowCount * 3);
const snowVel = [];
for (let i = 0; i < snowCount; i++) {
  snowPos[i * 3]     = (Math.random() - 0.5) * 12;
  snowPos[i * 3 + 1] = Math.random() * 8;
  snowPos[i * 3 + 2] = (Math.random() - 0.5) * 12;
  snowVel.push({ x: (Math.random() - 0.5) * 0.003, y: -0.005 - Math.random() * 0.01, z: (Math.random() - 0.5) * 0.003 });
}
snowGeo.setAttribute('position', new THREE.BufferAttribute(snowPos, 3));
const snowMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.04, transparent: true, opacity: 0.6 });
const snow = new THREE.Points(snowGeo, snowMat);
scene.add(snow);

// Animate
function animate() {
  requestAnimationFrame(animate);
  const pos = snow.geometry.attributes.position.array;
  for (let i = 0; i < snowCount; i++) {
    pos[i * 3]     += snowVel[i].x + Math.sin(Date.now() * 0.001 + i) * 0.001;
    pos[i * 3 + 1] += snowVel[i].y;
    pos[i * 3 + 2] += snowVel[i].z;
    if (pos[i * 3 + 1] < 0) { pos[i * 3 + 1] = 8; pos[i * 3] = (Math.random() - 0.5) * 12; pos[i * 3 + 2] = (Math.random() - 0.5) * 12; }
  }
  snow.geometry.attributes.position.needsUpdate = true;
  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What this creates:**

- **Main pad** — an extruded Bézier-curve shape with beveled edges, matching the broad, rounded-triangle characteristic of a snow leopard's meat pad
- **4 toe pads** — scaled spheres arranged in a natural arc, each slightly angled outward
- **4 claw marks** — subtle crescent shapes positioned just ahead of the toe pads (snow leopards often show claw marks)
- **Falling snow particles** — gently drifting with wind sway for atmosphere
- **Warm directional lighting** with soft shadows and a cool blue rim light
- **OrbitControls** — drag to rotate, scroll to zoom around the print

