        // Crab Construction
        const crabGroup = new THREE.Group();
        const crabMaterial = new THREE.MeshStandardMaterial({ color: 0xf0f0f0, roughness: 0.5 }); // Ghost crab white
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // Carapace (Body)
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        const body = new THREE.Mesh(bodyGeo, crabMaterial);
        body.scale.set(1.2, 0.6, 1.5);
        body.castShadow = true;
        crabGroup.add(body);

        // Eyes
        function createEye(x, z) {
            const stalkGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.8);
            const stalk = new THREE.Mesh(stalkGeo, crabMaterial);
            stalk.position.set(x, 0.6, z);
            stalk.rotation.z = x > 0 ? -0.3 : 0.3;

            const eyeGeo = new THREE.SphereGeometry(0.15);
            const eye = new THREE.Mesh(eyeGeo, eyeMaterial);
            eye.position.set(0, 0.4, 0);
            stalk.add(eye);

            crabGroup.add(stalk);
        }
        createEye(-0.6, 0.8);
        createEye(0.6, 0.8);

        // Legs and Claws
        function createLeg(side, index, isClaw = false) {
            const legGroup = new THREE.Group();
            const length = isClaw ? 1.5 : 1.8;
            const segments = 3;

            let currentPos = new THREE.Vector3(side * 1.1, 0, 0.5 - (index * 0.4));
            legGroup.position.copy(currentPos);

            // Base segment
            const seg1Geo = new THREE.CylinderGeometry(0.08, 0.08, length * 0.4);
            const seg1 = new THREE.Mesh(seg1Geo, crabMaterial);
            seg1.rotation.z = Math.PI / 2;
            seg1.rotation.y = side * 0.5;
            seg1.position.set(side * (length * 0.2), 0, 0);
            legGroup.add(seg1);

            // Middle segment
            const seg2Geo = new THREE.CylinderGeometry(0.07, 0.07, length * 0.4);
            const seg2 = new THREE.Mesh(seg2Geo, crabMaterial);
            seg2.rotation.z = Math.PI / 2;
            seg2.rotation.y = side * 0.2;
            seg2.position.set(side * (length * 0.6), -0.2, 0);
            legGroup.add(seg2);

            // End segment
            const seg3Geo = new THREE.CylinderGeometry(0.06, 0.06, length * 0.4);
            const seg3 = new THREE.Mesh(seg3Geo, crabMaterial);
            seg3.rotation.z = Math.PI / 2;
            seg3.rotation.y = side * 0.8;
            seg3.position.set(side * (length * 1.0), -0.4, 0);
            legGroup.add(seg3);

            if (isClaw) {
                // Claw pincers
                const pincerGeo = new THREE.BoxGeometry(0.4, 0.1, 0.6);
                const pincer1 = new THREE.Mesh(pincerGeo, crabMaterial);
                pincer1.position.set(side * 1.4, -0.5, 0.2);
                pincer1.rotation.y = side * 0.5;
                legGroup.add(pincer1);

                const pincer2 = new THREE.Mesh(pincerGeo, crabMaterial);
                pincer2.position.set(side * 1.4, -0.5, -0.2);
                pincer2.rotation.y = side * 0.5;
                legGroup.add(pincer2);
            }

            crabGroup.add(legGroup);
        }

        // Create 4 walking legs per side
        for (let i = 0; i < 4; i++) {
            createLeg(1, i); // Right side
            createLeg(-1, i); // Left side
        }
        // Create 2 claws
        createLeg(1, 0, true); // Right claw (overwrites first leg roughly, simplified)
        createLeg(-1, 0, true); // Left claw

        scene.add(crabGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
