        toyGroup.position.z = 2;
        scene.add(toyGroup);

        // --- Interaction Logic ---
        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2();
        let isWinding = false;
        let windEnergy = 0;
        const maxEnergy = 100;

        // UI Elements
        const windBar = document.getElementById('wind-bar');

        window.addEventListener('click', (event) => {
            // Calculate mouse position in normalized device coordinates
            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            raycaster.setFromCamera(mouse, camera);

            // Check intersection with the toy group
            const intersects = raycaster.intersectObjects(toyGroup.children, true);

            if (intersects.length > 0) {
                // Add energy
                windEnergy = Math.min(windEnergy + 20, maxEnergy);
                isWinding = true;
            }
        });

