                });

                // Decay energy (friction)
                windEnergy -= 0.5;
                if (windEnergy < 0) windEnergy = 0;
            }

            // Update UI
            windBar.style.width = `${(windEnergy / maxEnergy) * 100}%`;

            // Reset if it goes too far
            if (toyGroup.position.z < -15) {
                toyGroup.position.z = 5;
