            const claw2 = new THREE.Mesh(clawGeo, yellowMat);
            claw2.position.set(-0.15, -2.2, 0.7);
            claw2.rotation.x = Math.PI / 2;
            legGroup.add(claw2);

            legGroup.position.set(xPos, 1.5, 0);
            return legGroup;
        }

        const leftLeg = createLeg(-0.4);
        const rightLeg = createLeg(0.4);
        cassowaryGroup.add(leftLeg);
        cassowaryGroup.add(rightLeg);

        // Position the whole bird
        cassowaryGroup.position.y = 0.5;
        scene.add(cassowaryGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Subtle idle animation
            const time = Date.now() * 0.001;
            cassowaryGroup.position.y = 0.5 + Math.sin(time * 2) * 0.05;
            neck.rotation.z = Math.sin(time * 3) * 0.05;
            head.rotation.z = Math.sin(time * 3) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
