<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

/* ── renderer ── */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

/* ── scene & camera ── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;

/* ── environment for reflections ── */
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;
pmrem.dispose();

/* ── lighting ── */
const amb = new THREE.AmbientLight(0xffeedd, 0.3);
scene.add(amb);

const key = new THREE.DirectionalLight(0xfff4e0, 2.5);
key.position.set(4, 6, 4);
key.castShadow = true;
key.shadow.mapSize.set(1024, 1024);
scene.add(key);

const fill = new THREE.DirectionalLight(0xc8d8ff, 0.8);
fill.position.set(-5, 3, -2);
scene.add(fill);

const rim = new THREE.PointLight(0xffaa44, 1.5, 15);
rim.position.set(-3, 1, -4);
scene.add(rim);

/* ── brass material ── */
const brass = new THREE.MeshStandardMaterial({
  color: 0xc9a84c,
  metalness: 0.95,
  roughness: 0.18,
  envMapIntensity: 1.4,
});

const darkBrass = new THREE.MeshStandardMaterial({
  color: 0x8a6f2e,
  metalness: 0.95,
  roughness: 0.35,
  envMapIntensity: 1.2,
});

/* ── key ring (split ring style) ── */
const ringGroup = new THREE.Group();
scene.add(ringGroup);

// Main ring torus
const ringGeo = new THREE.TorusGeometry(1.4, 0.1, 32, 128);
const ring = new THREE.Mesh(ringGeo, brass);
ring.castShadow = true;
ring.receiveShadow = true;
ringGroup.add(ring);

// Second ring for split-ring look
const ring2 = new THREE.Mesh(
  new THREE.TorusGeometry(1.4, 0.09, 32, 128),
  brass
);
ring2.rotation.x = Math.PI / 2;
ring2.castShadow = true;
ringGroup.add(ring2);

// Third ring at angle
const ring3 = new THREE.Mesh(
  new THREE.TorusGeometry(1.4, 0.085, 32, 128),
  brass
);
ring3.rotation.y = Math.PI / 3;
ring3.castShadow = true;
ringGroup.add(ring3);

/* ── key builder ── */
function makeKey(config) {
  const g = new THREE.Group();

  // Bow (head) — decorative oval ring
  const bowGeo = new THREE.TorusGeometry(config.bowRadius || 0.35, 0.06, 16, 32);
  const bow = new THREE.Mesh(bowGeo, brass);
  bow.position.y = config.bowOffset || 0.9;
  bow.castShadow = true;
  g.add(bow);

  // Shaft
  const shaftGeo = new THREE.BoxGeometry(0.08, config.shaftLen || 1.4, 0.04);
  const shaft = new THREE.Mesh(shaftGeo, brass);
  shaft.position.y = config.shaftOffset || 0.15;
  shaft.castShadow = true;
  g.add(shaft);

  // Blade (flat part)
  const bladeGeo = new THREE.BoxGeometry(0.03, config.shaftLen || 1.4, 0.02);
  const blade = new THREE.Mesh(bladeGeo, darkBrass);
  blade.position.set(0, config.shaftOffset || 0.15, 0.025);
  g.add(blade);

  // Teeth
  const toothPositions = config.teeth || [0.3, 0.6, 0.9];
  toothPositions.forEach(t => {
    const toothGeo = new THREE.BoxGeometry(0.1, 0.06, 0.04);
    const tooth = new THREE.Mesh(toothGeo, brass);
    tooth.position.set(0.06, t, 0.025);
    tooth.castShadow = true;
    g.add(tooth);
  });

  // Tip
  const tipGeo = new THREE.CylinderGeometry(0.04, 0.02, 0.08, 12);
  const tip = new THREE.Mesh(tipGeo, brass);
  tip.rotation.x = Math.PI / 2;
  tip.position.set(0, -config.shaftLen / 2 - config.bowOffset + 0.15, 0.025);
  g.add(tip);

  return g;
}

/* ── attach keys ── */
const keys = [];

const keyConfigs = [
  { teeth: [0.25, 0.55, 0.85],  bowRadius: 0.35, bowOffset: 0.85,  shaftLen: 1.5 },
  { teeth: [0.35, 0.7],         bowRadius: 0.3,  bowOffset: 0.8,   shaftLen: 1.3 },
  { teeth: [0.2, 0.5, 0.75, 1.0],bowRadius: 0.4, bowOffset: 0.95,  shaftLen: 1.6 },
  { teeth: [0.4, 0.7],          bowRadius: 0.28, bowOffset: 0.75,  shaftLen: 1.2 },
];

const keyAngles = [0, Math.PI * 0.45, Math.PI * 0.9, Math.PI * 1.35];

keyConfigs.forEach((cfg, i) => {
  const k = makeKey(cfg);
  // Position on ring
  const angle = keyAngles[i];
  const r = 1.4;
  k.position.set(Math.cos(angle) * r, Math.sin(angle) * r * 0.3, Math.sin(angle) * r * 0.5);
  k.rotation.set(0.15, angle + 0.3, 0.05);
  k.castShadow = true;
  keys.push(k);
  ringGroup.add(k);
});

/* ── ground plane ── */
const ground = new THREE.Mesh(
