/* ── animation ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating & sway
  ringGroup.position.y = Math.sin(t * 0.6) * 0.15;
  ringGroup.rotation.x = Math.sin(t * 0.4) * 0.08;
  ringGroup.rotation.z = Math.sin(t * 0.3) * 0.05;

