<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene Setup ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a12, 0.012);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 200);
camera.position.set(12, 8, 14);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 5;
controls.maxDistance = 50;

// ── Lighting ─────────────────────────────────────────────────
const ambientLight = new THREE.AmbientLight(0x334466, 0.8);
scene.add(ambientLight);

const dirLight1 = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight1.position.set(10, 15, 10);
scene.add(dirLight1);

const dirLight2 = new THREE.DirectionalLight(0x8899cc, 1.0);
dirLight2.position.set(-10, 5, -10);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xffccaa, 1.5, 30);
pointLight.position.set(0, 8, 5);
scene.add(pointLight);

const rimLight = new THREE.PointLight(0x4466aa, 1.0, 40);
rimLight.position.set(-8, -3, -10);
scene.add(rimLight);

// ── Nautilus Spiral Curve ────────────────────────────────────
const NAUTILUS_TURNS = 4.2;
const NAUTILUS_B = 0.18;
const NAUTILUS_A = 0.35;
const NAUTILUS_MAX_THETA = NAUTILUS_TURNS * Math.PI * 2;
const NAUTILUS_Z_SCALE = 0.06;

class NautilusCurve extends THREE.Curve {
  getPoint(t) {
    const theta = t * NAUTILUS_MAX_THETA;
    const r = NAUTILUS_A * Math.exp(NAUTILUS_B * theta);
    return new THREE.Vector3(
      r * Math.cos(theta),
      r * Math.sin(theta),
      NAUTILUS_Z_SCALE * theta
    );
  }
}

// ── Shell Tube Geometry (outer wall) ─────────────────────────
function createShellWall() {
  const curve = new NautilusCurve();
  const segments = 500;
  const radialSegments = 48;
  const baseRadius = 0.65;
  const wallThickness = 0.22;

  // Radius grows exponentially along the spiral
  function radiusAt(t) {
    const theta = t * NAUTILUS_MAX_THETA;
    return baseRadius * Math.exp(NAUTILUS_B * theta * 0.35);
  }

  const geo = new THREE.TubeGeometry(curve, segments, baseRadius, radialSegments, false);

  // Scale the cross-section radius along the tube
  const pos = geo.attributes.position;
  const norm = geo.attributes.normal;
  const v3 = new THREE.Vector3();

  // Get frame vectors along the curve
  const frames = [];
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const theta = t * NAUTILUS_MAX_THETA;
    const r = NAUTILUS_A * Math.exp(NAUTILUS_B * theta);

    const eps = 0.001;
    const p0 = curve.getPoint(Math.max(0, t - eps));
    const p1 = curve.getPoint(t);
    const p2 = curve.getPoint(Math.min(1, t + eps));

    const tangent = new THREE.Vector3().subVectors(p2, p0).normalize();
    const up = new THREE.Vector3(0, 0, 1);
    if (Math.abs(tangent.dot(up)) > 0.999) up.set(1, 0, 0);

    const normal = new THREE.Vector3().crossVectors(tangent, up).normalize();
    const binormal = new THREE.Vector3().crossVectors(tangent, normal).normalize();

    frames.push({ normal, binormal });
  }

  // Build custom geometry with varying radius
  const vertices = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const center = curve.getPoint(t);
    const r = radiusAt(t);
    const frame = frames[i];

    for (let j = 0; j <= radialSegments; j++) {
      const phi = (j / radialSegments) * Math.PI * 2;
      const cosPhi = Math.cos(phi);
      const sinPhi = Math.sin(phi);

      const nx = frame.normal.x * cosPhi + frame.binormal.x * sinPhi;
      const ny = frame.normal.y * cosPhi + frame.binormal.y * sinPhi;
      const nz = frame.normal.z * cosPhi + frame.binormal.z * sinPhi;

      vertices.push(
        center.x + r * nx,
        center.y + r * ny,
        center.z + r * nz
      );
      normals.push(nx, ny, nz);
      uvs.push(j / radialSegments, t);
    }
  }

  for (let i = 0; i < segments; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * (radialSegments + 1) + j;
      const b = a + radialSegments + 1;
      indices.push(a, b, a + 1);
      indices.push(b, b + 1, a + 1);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();

  return geometry;
}

// ── Iridescent Shell Material ────────────────────────────────
const shellMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uLightPos1: { value: dirLight1.position },
    uLightPos2: { value: dirLight2.position },
    uLightColor1: { value: new THREE.Color(0xffeedd) },
    uLightColor2: { value: new THREE.Color(0x8899cc) },
    uAmbientColor: { value: new THREE.Color(0x334466) },
    uCameraPos: { value: camera.position },
    uBaseColor1: { value: new THREE.Color(0xd4a574) },
    uBaseColor2: { value: new THREE.Color(0xe8c9a0) },
    uIridescence1: { value: new THREE.Color(0xff99aa) },
    uIridescence2: { value: new THREE.Color(0x99ccff) },
    uIridescence3: { value: new THREE.Color(0xaaffcc) },
  },
