<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// ── Scene & Camera ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(2.5, 2.2, 3);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 2;
controls.maxDistance = 10;
controls.maxPolarAngle = Math.PI / 2.05;
controls.update();

// ── Environment Map ──
const pmremGenerator = new THREE.PMREMGenerator(renderer);
pmremGenerator.compileEquirectangularShader();
const envTexture = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envTexture;

// ── Lights ──
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(3, 5, 2);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 15;
keyLight.shadow.camera.left = -3;
keyLight.shadow.camera.right = 3;
keyLight.shadow.camera.top = 3;
keyLight.shadow.camera.bottom = -3;
keyLight.shadow.bias = -0.001;
keyLight.shadow.radius = 4;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899ff, 1);
fillLight.position.set(-3, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffa644, 2, 10);
rimLight.position.set(-1, 2, -3);
scene.add(rimLight);

const bottomLight = new THREE.PointLight(0x4488ff, 0.5, 5);
bottomLight.position.set(0, -0.5, 0);
scene.add(bottomLight);

// ── Floor ──
const floorGeo = new THREE.CircleGeometry(8, 64);
const floorMat = new THREE.MeshPhysicalMaterial({
  color: 0x2a2a3e,
  roughness: 0.35,
  metalness: 0.1,
  clearcoat: 0.3,
  clearcoatRoughness: 0.2,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// ── Glass Material ──
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.03,
  ior: 1.52,
  thickness: 0.8,
  specularIntensity: 1.0,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1.5,
  clearcoat: 0.1,
  clearcoatRoughness: 0.05,
  attenuationColor: new THREE.Color(0xddeeff),
  attenuationDistance: 2.0,
  side: THREE.DoubleSide,
});

// ── Paperweight Dome (hemisphere) ──
const domeGeo = new THREE.SphereGeometry(0.7, 128, 64, 0, Math.PI * 2, 0, Math.PI / 2);
const dome = new THREE.Mesh(domeGeo, glassMat);
dome.position.y = 0.08;
dome.castShadow = true;
scene.add(dome);

// ── Paperweight Base (thick disc) ──
const baseGeo = new THREE.CylinderGeometry(0.72, 0.75, 0.08, 128);
const baseMesh = new THREE.Mesh(baseGeo, glassMat);
baseMesh.position.y = 0.04;
baseMesh.castShadow = true;
scene.add(baseMesh);

// ── Rim ring ──
const rimGeo = new THREE.TorusGeometry(0.73, 0.015, 16, 128);
const rimMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, transmission: 0.92, roughness: 0.02,
  ior: 1.52, thickness: 0.3, envMapIntensity: 1.5,
  attenuationColor: new THREE.Color(0xddeeff),
});
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.08;
scene.add(rim);

// ── Inner Object: a small colorful "flower" ──
const innerGroup = new THREE.Group();
innerGroup.position.y = 0.35;

const petalColors = [0xff4488, 0xff8844, 0xffcc22, 0x44ffaa, 0x4488ff, 0xaa44ff];
const petalGeo = new THREE.SphereGeometry(0.06, 16, 16);

for (let i = 0; i < 6; i++) {
  const petal = new THREE.Mesh(petalGeo, new THREE.MeshPhysicalMaterial({
    color: petalColors[i],
    roughness: 0.3,
    metalness: 0.1,
    clearcoat: 0.5,
    clearcoatRoughness: 0.1,
    emissive: petalColors[i],
    emissiveIntensity: 0.15,
  }));
  const angle = (i / 6) * Math.PI * 2;
  petal.position.set(Math.cos(angle) * 0.12, 0.04, Math.sin(angle) * 0.12);
  petal.scale.set(1, 0.5, 1);
  innerGroup.add(petal);
}

// Center sphere
const centerGeo = new THREE.SphereGeometry(0.05, 16, 16);
const centerMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, roughness: 0.1, metalness: 0.3,
  clearcoat: 1.0, clearcoatRoughness: 0.05,
  emissive: 0xffeedd, emissiveIntensity: 0.2,
});
const centerSphere = new THREE.Mesh(centerGeo, centerMat);
centerSphere.position.y = 0.02;
innerGroup.add(centerSphere);

// Small crystal shard inside
const crystalGeo = new THREE.OctahedronGeometry(0.07, 0);
const crystalMat = new THREE.MeshPhysicalMaterial({
  color: 0x88ccff, transmission: 0.6, roughness: 0.05,
  ior: 1.6, thickness: 0.2, envMapIntensity: 2.0,
  emissive: 0x4488cc, emissiveIntensity: 0.1,
});
const crystal = new THREE.Mesh(crystalGeo, crystalMat);
crystal.position.set(0, 0.15, 0);
crystal.rotation.set(0.3, 0.5, 0.2);
innerGroup.add(crystal);

scene.add(innerGroup);

// ── Contact shadow (fake soft shadow under paperweight) ──
const shadowGeo = new THREE.CircleGeometry(0.78, 64);
const shadowMat = new THREE.MeshBasicMaterial({
  color: 0x000000, transparent: true, opacity: 0.25,
  depthWrite: false,
});
const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
shadowPlane.rotation.x = -Math.PI / 2;
shadowPlane.position.y = 0.001;
scene.add(shadowPlane);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle float of inner object
  innerGroup.position.y = 0.35 + Math.sin(t * 0.8) * 0.015;
  innerGroup.rotation.y = t * 0.15;
  crystal.rotation.y = t * 0.5;
  crystal.rotation.x = 0.3 + Math.sin(t * 0.7) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```

This creates a photorealistic glass paperweight with:

- **Realistic glass** using `MeshPhysicalMaterial` with transmission, IOR 1.52 (real glass), attenuation color, and clearcoat
- **Hemisphere dome + flat base + rim ring** matching a classic paperweight shape
- **Inner "flower"** — six colored petals in a ring with a center sphere and a floating crystal shard, all gently animating
- **Studio lighting** — key, fill, rim, and bottom lights with soft shadows
- **Room environment map** (from `RoomEnvironment`) for realistic reflections and refractions
- **Dark polished floor** that receives shadows
- **OrbitControls** — drag to rotate, scroll to zoom

