        });

        // Helper to add spikes
        function addSpikes(group, count, radius, yOffset, zBias) {
            const spikeGeo = new THREE.ConeGeometry(0.08, 0.3, 4);
            for (let i = 0; i < count; i++) {
                const spike = new THREE.Mesh(spikeGeo, spikeMat);

                // Random point on sphere
                const u = Math.random();
                const v = Math.random();
                const theta = 2 * Math.PI * u;
                const phi = Math.acos(2 * v - 1);

                let x = radius * Math.sin(phi) * Math.cos(theta);
                let y = radius * Math.sin(phi) * Math.sin(theta);
                let z = radius * Math.cos(phi);

                // Apply biases
                y += yOffset;
                z += zBias;

                // Flatten body slightly
                y *= 0.6;

                spike.position.set(x, y, z);

                // Orient outward
                spike.lookAt(0, yOffset, zBias);
                spike.rotateX(Math.PI); // Point away from center

                // Randomize rotation slightly for organic look
                spike.rotation.z += (Math.random() - 0.5) * 0.5;
                spike.rotation.y += (Math.random() - 0.5) * 0.5;

                // Random scale
                const s = 0.5 + Math.random() * 1.5;
                spike.scale.set(s, s, s);

                spike.castShadow = true;
                group.add(spike);
            }
