<body>
    <div id="info">Velvet Worm (Onychophora) — click & drag to orbit</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 0.5);
        pointLight.position.set(-5, 2, -5);
        scene.add(pointLight);

        // Ground
        const planeGeometry = new THREE.PlaneGeometry(50, 50);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Velvet Worm Construction
        const wormGroup = new THREE.Group();

        // 1. Body Curve
        const points = [];
        const segments = 20;
        for (let i = 0; i <= segments; i++) {
            const t = i / segments;
            // Create a wiggly shape
            const x = (t - 0.5) * 6; 
            const y = 0.5 + Math.sin(t * Math.PI * 4) * 0.1; // Slight undulation
            const z = Math.sin(t * Math.PI * 2) * 0.5;
            points.push(new THREE.Vector3(x, y, z));
        }
        const curve = new THREE.CatmullRomCurve3(points);

        // Body Material (Velvety look: high roughness, specific color)
        const bodyMaterial = new THREE.MeshStandardMaterial({
            color: 0xd2691e, // Chocolate/Orange-brown
            roughness: 0.9,
            metalness: 0.1,
            bumpScale: 0.02
        });

        // Body Geometry
        const tubeGeometry = new THREE.TubeGeometry(curve, 64, 0.25, 12, false);
        const bodyMesh = new THREE.Mesh(tubeGeometry, bodyMaterial);
        bodyMesh.castShadow = true;
        wormGroup.add(bodyMesh);

        // 2. Legs (Stumpy legs characteristic of Onychophora)
        const legMaterial = new THREE.MeshStandardMaterial({ color: 0xb5551a, roughness: 0.9 });
        const legGeometry = new THREE.CylinderGeometry(0.05, 0.08, 0.4, 8);

        // Add legs along the body
        for (let i = 2; i < segments - 2; i++) {
            const t = i / segments;
            const pos = curve.getPointAt(t);
            const tangent = curve.getTangentAt(t);

            // Create a pair of legs
            const legL = new THREE.Mesh(legGeometry, legMaterial);
            const legR = new THREE.Mesh(legGeometry, legMaterial);

            // Position legs
            legL.position.copy(pos);
            legR.position.copy(pos);

            // Orient legs roughly perpendicular to body and down
            // Simple approximation: rotate around tangent
            const up = new THREE.Vector3(0, -1, 0);
            const right = new THREE.Vector3().crossVectors(tangent, up).normalize();

            legL.position.add(right.clone().multiplyScalar(0.25));
            legR.position.add(right.clone().multiplyScalar(-0.25));

            // Rotate to point down-ish
            legL.lookAt(pos.clone().add(new THREE.Vector3(0, -1, 0)));
            legR.lookAt(pos.clone().add(new THREE.Vector3(0, -1, 0)));

            // Tilt them slightly forward/back based on sine wave
            legL.rotation.z = Math.sin(t * Math.PI * 4) * 0.2;
            legR.rotation.z = Math.sin(t * Math.PI * 4) * 0.2;

            legL.castShadow = true;
            legR.castShadow = true;

            wormGroup.add(legL);
            wormGroup.add(legR);
        }

        // 3. Head
        const headGeometry = new THREE.SphereGeometry(0.35, 16, 16);
        const headMesh = new THREE.Mesh(headGeometry, bodyMaterial);
        const headPos = curve.getPointAt(0);
        headMesh.position.copy(headPos);
        headMesh.castShadow = true;
        wormGroup.add(headMesh);

        // 4. Antennae
        const antennaMaterial = new THREE.MeshStandardMaterial({ color: 0x8b4513 });
        const antennaGeometry = new THREE.CylinderGeometry(0.02, 0.01, 0.8, 6);

        const antL = new THREE.Mesh(antennaGeometry, antennaMaterial);
        const antR = new THREE.Mesh(antennaGeometry, antennaMaterial);

        antL.position.set(headPos.x - 0.1, headPos.y + 0.3, headPos.z);
        antR.position.set(headPos.x + 0.1, headPos.y + 0.3, headPos.z);

        antL.rotation.z = 0.3;
        antR.rotation.z = -0.3;

        wormGroup.add(antL);
        wormGroup.add(antR);

        // Center the worm
        wormGroup.position.y = 0.5;
        scene.add(wormGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Subtle movement
            const time = Date.now() * 0.001;
            wormGroup.position.y = 0.5 + Math.sin(time) * 0.05;
            wormGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
