    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const container = document.getElementById('canvas-container');
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a120b);
        scene.fog = new THREE.Fog(0x1a120b, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        container.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.autoRotate = false;
        controls.autoRotateSpeed = 2.0;

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x886644, 0.5);
        backLight.position.set(-5, 0, -5);
        scene.add(backLight);

        // --- Geometry Creation ---

        // Function to create a single pangolin scale
        function createScale() {
            const group = new THREE.Group();

            // Material: Keratin-like (brownish, slightly shiny)
            const material = new THREE.MeshStandardMaterial({
                color: 0x5c4033, // Dark brown
                roughness: 0.4,
                metalness: 0.1,
            });

            // 1. The Base Plate (Shield shape)
            // We use a Shape to define the outline
            const shape = new THREE.Shape();
            const w = 1.0;
            const h = 1.4;

            // Draw a shield/hexagon shape
            shape.moveTo(0, -h/2);
            shape.bezierCurveTo(w/2, -h/2, w, -h/4, w/2, h/4); // Right side curve
            shape.lineTo(0, h/2); // Top point
            shape.lineTo(-w/2, h/4); // Left side top
            shape.bezierCurveTo(-w, -h/4, -w/2, -h/2, 0, -h/2); // Left side curve

            const extrudeSettings = {
                steps: 1,
                depth: 0.15,
                bevelEnabled: true,
                bevelThickness: 0.05,
                bevelSize: 0.05,
                bevelSegments: 3
            };

            const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            geometry.center(); // Center the geometry

            const baseMesh = new THREE.Mesh(geometry, material);
            baseMesh.castShadow = true;
            baseMesh.receiveShadow = true;
            // Rotate to lay flat
            baseMesh.rotation.x = -Math.PI / 2; 
            group.add(baseMesh);

            // 2. The Central Ridge
            const ridgeGeo = new THREE.BoxGeometry(0.2, 0.05, h * 0.8);
            const ridgeMesh = new THREE.Mesh(ridgeGeo, material);
            ridgeMesh.position.y = 0.1; // Slightly above base
            ridgeMesh.castShadow = true;
            group.add(ridgeMesh);

            return group;
        }

        // --- Scene Objects Management ---
        let currentMode = 'patch'; // 'patch', 'single', 'exploded'
        const scalesGroup = new THREE.Group();
        scene.add(scalesGroup);

        const scales = []; // Array to store individual scale meshes for animation

        function buildScene(mode) {
            // Clear existing
            while(scalesGroup.children.length > 0){ 
                const obj = scalesGroup.children[0];
                obj.geometry?.dispose();
                obj.material?.dispose();
                scalesGroup.remove(obj); 
            }
            scales.length = 0;

            if (mode === 'single') {
                const scale = createScale();
                scale.scale.set(2, 2, 2);
                scalesGroup.add(scale);
                scales.push(scale);
            } 
            else {
                // Create a grid of scales (Patch or Exploded)
                const rows = 5;
                const cols = 5;
                const spacingX = 0.6;
                const spacingY = 0.8;

                for (let r = 0; r < rows; r++) {
                    for (let c = 0; c < cols; c++) {
                        const scale = createScale();

                        // Staggered grid pattern (brick layout)
                        let x = (c - cols/2) * spacingX;
                        let y = (r - rows/2) * spacingY;

                        if (r % 2 !== 0) {
                            x += spacingX / 2;
                        }

                        // Exploded offset
                        if (mode === 'exploded') {
                            x *= 2.5;
                            y *= 2.5;
                            // Add some random rotation for "exploded" feel
                            scale.rotation.z = (Math.random() - 0.5) * 0.5;
                            scale.rotation.x = (Math.random() - 0.5) * 0.5;
                        } else {
                            // Patch view: slight overlap and rotation
                            scale.rotation.z = (Math.random() - 0.5) * 0.1;
                        }

                        scale.position.set(x, y, 0);
                        scalesGroup.add(scale);
                        scales.push(scale);
                    }
                }
            }
        }

        // Initial build
        buildScene('patch');

        // --- UI Logic ---
        const btnPatch = document.getElementById('btn-patch');
        const btnSingle = document.getElementById('btn-single');
        const btnExploded = document.getElementById('btn-exploded');
        const btnRotate = document.getElementById('btn-rotate');

        function setActiveButton(btn) {
            [btnPatch, btnSingle, btnExploded].forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
        }

        btnPatch.addEventListener('click', () => {
            currentMode = 'patch';
            buildScene('patch');
            setActiveButton(btnPatch);
        });

        btnSingle.addEventListener('click', () => {
            currentMode = 'single';
            buildScene('single');
            setActiveButton(btnSingle);
        });

        btnExploded.addEventListener('click', () => {
            currentMode = 'exploded';
            buildScene('exploded');
            setActiveButton(btnExploded);
        });

        btnRotate.addEventListener('click', () => {
            controls.autoRotate = !controls.autoRotate;
            btnRotate.classList.toggle('active');
        });

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
