grad.addColorStop(1, '#1a1a2e');
ctx.fillStyle = grad;
ctx.fillRect(0, 0, 1024, 512);

// Bright spots for specular highlights
ctx.fillStyle = 'rgba(255,255,240,0.9)';
ctx.beginPath(); ctx.ellipse(280, 140, 60, 40, 0, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = 'rgba(200,220,255,0.5)';
ctx.beginPath(); ctx.ellipse(700, 200, 40, 30, 0, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = 'rgba(255,200,150,0.4)';
ctx.beginPath(); ctx.ellipse(500, 100, 80, 25, 0.3, 0, Math.PI * 2); ctx.fill();

const envTexture = new THREE.CanvasTexture(bgCanvas);
envScene.background = envTexture;
const envMap = pmrem.fromScene(envScene, 0.04).texture;
scene.environment = envMap;

// ── Eye Group ──────────────────────────────────────────
const eyeGroup = new THREE.Group();
scene.add(eyeGroup);

// ── Sclera (white of the eye) ──────────────────────────
const scleraGeo = new THREE.SphereGeometry(1, 64, 64);
const scleraMat = new THREE.MeshStandardMaterial({
  color: 0xf0ece4,
  roughness: 0.4,
  metalness: 0.0,
  side: THREE.FrontSide,
});
const sclera = new THREE.Mesh(scleraGeo, scleraMat);
eyeGroup.add(sclera);

// ── Iris texture (procedural) ──────────────────────────
const irisCanvas = document.createElement('canvas');
irisCanvas.width = 512; irisCanvas.height = 512;
const ictx = irisCanvas.getContext('2d');

function generateIris() {
  const cx = 256, cy = 256;

  // Base gradient
  const baseGrad = ictx.createRadialGradient(cx, cy, 60, cx, cy, 220);
  baseGrad.addColorStop(0, '#0a1628');
  baseGrad.addColorStop(0.15, '#1a3a5c');
  baseGrad.addColorStop(0.35, '#2e7d8a');
  baseGrad.addColorStop(0.55, '#3a9e8e');
  baseGrad.addColorStop(0.75, '#5cb87a');
  baseGrad.addColorStop(0.9, '#8a7a4a');
  baseGrad.addColorStop(1, '#6a5a3a');
  ictx.fillStyle = baseGrad;
  ictx.fillRect(0, 0, 512, 512);

  // Fibrous radial lines (iris texture)
  ictx.globalAlpha = 0.15;
  for (let i = 0; i < 600; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r1 = 40 + Math.random() * 180;
    const r2 = r1 + 10 + Math.random() * 40;
    const w = 0.5 + Math.random() * 2;
    ictx.strokeStyle = Math.random() > 0.5 ? '#1a3a2a' : '#5a8a6a';
    ictx.lineWidth = w;
    ictx.beginPath();
    ictx.moveTo(cx + Math.cos(angle) * r1, cy + Math.sin(angle) * r1);
    ictx.lineTo(cx + Math.cos(angle) * r2, cy + Math.sin(angle) * r2);
    ictx.stroke();
  }

  // Crypts (darker irregular spots)
  ictx.globalAlpha = 0.12;
  for (let i = 0; i < 40; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r = 80 + Math.random() * 140;
    ictx.fillStyle = '#0a2a1a';
    ictx.beginPath();
    ictx.ellipse(cx + Math.cos(angle) * r, cy + Math.sin(angle) * r,
      3 + Math.random() * 8, 2 + Math.random() * 4, angle, 0, Math.PI * 2);
    ictx.fill();
  }

  // Collarette ring
  ictx.globalAlpha = 0.25;
  ictx.strokeStyle = '#1a2a3a';
  ictx.lineWidth = 4;
  ictx.beginPath();
  ictx.arc(cx, cy, 130, 0, Math.PI * 2);
  ictx.stroke();

  // Limbal ring (outer edge)
  ictx.globalAlpha = 0.5;
  ictx.strokeStyle = '#2a3a2a';
  ictx.lineWidth = 12;
  ictx.beginPath();
  ictx.arc(cx, cy, 210, 0, Math.PI * 2);
  ictx.stroke();

  ictx.globalAlpha = 1;
}
generateIris();

const irisTexture = new THREE.CanvasTexture(irisCanvas);
const irisGeo = new THREE.CircleGeometry(0.52, 64);
const irisMat = new THREE.MeshStandardMaterial({
  map: irisTexture,
  roughness: 0.6,
  metalness: 0.0,
  side: THREE.FrontSide,
});
const iris = new THREE.Mesh(irisGeo, irisMat);
iris.position.z = 0.94;
eyeGroup.add(iris);

// ── Pupil ──────────────────────────────────────────────
const pupilGeo = new THREE.CircleGeometry(0.2, 64);
const pupilMat = new THREE.MeshStandardMaterial({
  color: 0x020204,
  roughness: 0.3,
  metalness: 0.1,
  side: THREE.FrontSide,
});
const pupil = new THREE.Mesh(pupilGeo, pupilMat);
pupil.position.z = 0.95;
eyeGroup.add(pupil);

// ── Cornea (glass outer shell) ─────────────────────────
const corneaGeo = new THREE.SphereGeometry(1.02, 64, 64);
const corneaMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.02,
  ior: 1.38,
  thickness: 0.3,
  specularIntensity: 1.0,
  specularColor: new THREE.Color(0xffffff),
  clearcoat: 1.0,
  clearcoatRoughness: 0.01,
  envMapIntensity: 1.5,
  side: THREE.DoubleSide,
  attenuationColor: new THREE.Color(0.95, 0.97, 1.0),
  attenuationDistance: 2,
});
const cornea = new THREE.Mesh(corneaGeo, corneaMat);
eyeGroup.add(cornea);

// ── Tear film (subtle outer layer) ─────────────────────
const tearGeo = new THREE.SphereGeometry(1.04, 64, 64);
const tearMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.9,
  transparent: true,
  roughness: 0.01,
  ior: 1.33,
  thickness: 0.05,
  specularIntensity: 1.0,
  clearcoat: 1.0,
  clearcoatRoughness: 0.0,
  envMapIntensity: 2.0,
  side: THREE.FrontSide,
  attenuationColor: new THREE.Color(1, 1, 1),
  attenuationDistance: 1,
});
const tearFilm = new THREE.Mesh(tearGeo, tearMat);
eyeGroup.add(tearFilm);

// ── Blood vessels on sclera ────────────────────────────
const vesselCanvas = document.createElement('canvas');
vesselCanvas.width = 512; vesselCanvas.height = 512;
const vctx = vesselCanvas.getContext('2d');

// Polar to cartesian for wrapping around sphere
for (let i = 0; i < 80; i++) {
  const startAngle = Math.random() * Math.PI * 2;
  const startR = 0.6 + Math.random() * 0.35;
  const endR = startR + 0.05 + Math.random() * 0.15;
  const angleSpread = (Math.random() - 0.5) * 0.4;

  vctx.strokeStyle = `rgba(180, 50, 50, ${0.05 + Math.random() * 0.15})`;
  vctx.lineWidth = 0.5 + Math.random() * 1.5;
  vctx.beginPath();

  const steps = 8;
  for (let s = 0; s <= steps; s++) {
    const t = s / steps;
    const r = startR + (endR - startR) * t;
    const a = startAngle + angleSpread * t;
    const x = 256 + Math.cos(a) * r * 256;
    const y = 256 + Math.sin(a) * r * 256;
    if (s === 0) vctx.moveTo(x, y);
    else vctx.lineTo(x, y);
  }
  vctx.stroke();
}

const vesselTexture = new THREE.CanvasTexture(vesselCanvas);
const vesselGeo = new THREE.SphereGeometry(1.005, 64, 64);
const vesselMat = new THREE.MeshStandardMaterial({
  map: vesselTexture,
  transparent: true,
  opacity: 0.6,
  roughness: 0.5,
  depthWrite: false,
  side: THREE.FrontSide,
});
const vessels = new THREE.Mesh(vesselGeo, vesselMat);
eyeGroup.add(vessels);

// ── Lighting ───────────────────────────────────────────
const keyLight = new THREE.DirectionalLight(0xfff5e6, 3);
keyLight.position.set(2, 3, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc8d8ff, 1.5);
fillLight.position.set(-3, 1, 2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffeedd, 2);
rimLight.position.set(0, -2, -3);
scene.add(rimLight);

const spotLight = new THREE.SpotLight(0xffffff, 8, 15, Math.PI / 6, 0.5);
spotLight.position.set(1.5, 2, 3);
spotLight.target = eyeGroup;
scene.add(spotLight);

// ── Animation ──────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Subtle eye movement
  eyeGroup.rotation.y = Math.sin(t * 0.3) * 0.15;
  eyeGroup.rotation.x = Math.sin(t * 0.2) * 0.05;

  // Subtle pupil breathing
  const pupilScale = 1 + Math.sin(t * 0.8) * 0.05;
  pupil.scale.set(pupilScale, pupilScale, 1);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ─────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in the scene:**

| Layer | Purpose |
|---|---|
| **Sclera** | White base sphere with subtle warmth |
| **Blood vessels** | Faint red procedural veins mapped onto the sclera surface |
| **Iris** | Canvas-generated procedural texture with fibrous radial lines, crypts, collarette ring, and limbal ring — greenish-teal tones |
| **Pupil** | Dark circle with gentle "breathing" animation |
| **Cornea** | `MeshPhysicalMaterial` with high **transmission** (0.95), **IOR 1.38**, clearcoat, and near-zero roughness for realistic glass refraction |
| **Tear film** | Thin outer shell with even lower IOR (1.33) for the real-world tear layer effect |
| **Environment map** | Custom canvas gradient with bright spots baked into a PMREM for convincing specular highlights |
| **Lighting** | Key, fill, rim, and a focused spotlight to accentuate the glass reflections |
| **Animation** | Gentle side-to-side eye movement and subtle pupil dilation |

