        const legMaterial = new THREE.MeshStandardMaterial({ color: 0xA0522D, roughness: 0.7 }); // Sienna
        const clawMaterial = new THREE.MeshStandardMaterial({ color: 0xCD5C5C, roughness: 0.5 }); // IndianRed
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.2 });

        // Crab Group
        const crab = new THREE.Group();

        // 1. Carapace (Main Body)
        const carapaceGeo = new THREE.BoxGeometry(2.2, 0.6, 1.6);
        // Round the edges slightly by scaling a sphere? No, let's just use a box for low poly look or a cylinder
        const carapace = new THREE.Mesh(carapaceGeo, shellMaterial);
