            const pincerBaseGeo = new THREE.BoxGeometry(0.4, 0.4, 0.6);
            const pincerBase = new THREE.Mesh(pincerBaseGeo, clawMaterial);
            pincerBase.position.set(xDir * 1.2, 0.4, 0);
            pincerBase.rotation.z = Math.PI / 4;
            pincerBase.castShadow = true;

            // Pincer Fingers
            const fingerGeo = new THREE.BoxGeometry(0.15, 0.15, 0.8);
            const finger1 = new THREE.Mesh(fingerGeo, clawMaterial);
            finger1.position.set(xDir * 1.4, 0.6, 0.2);
            finger1.rotation.z = Math.PI / 4;

            const finger2 = new THREE.Mesh(fingerGeo, clawMaterial);
            finger2.position.set(xDir * 1.4, 0.2, -0.2);
            finger2.rotation.z = Math.PI / 4;

            clawGroup.add(arm);
            clawGroup.add(pincerBase);
            clawGroup.add(finger1);
            clawGroup.add(finger2);

            clawGroup.position.set(xDir * 0.8, 0.5, -0.4);
            return clawGroup;
        }

        crab.add(createClaw('left'));
        crab.add(createClaw('right'));

        // Add crab to scene
        scene.add(crab);

        // Ground
        const groundGeo = new THREE.PlaneGeometry(50, 50);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Subtle idle animation
            const time = Date.now() * 0.001;
            crab.position.y = Math.sin(time) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Resize handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
