<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Crystal Prism</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; background: #000; }
  canvas { display: block; }
  #info {
    position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
    color: rgba(255,255,255,0.5); font: 14px/1 system-ui, sans-serif;
    pointer-events: none; text-align: center;
  }
</style>
</head>
<body>
<div id="info">Crystal Prism — Three.js</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Renderer ──────────────────────────────────────────────
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Scene & Camera ────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a12);

const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);

// ── Environment (for refraction reflections) ──────────────
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// ── Crystal Geometry (hexagonal bipyramid) ────────────────
function createCrystalGeometry() {
  const topRadius = 1.4;
  const midRadius = 1.8;
  const bottomRadius = 1.4;
  const topY = 2.2;
  const midY = 0;
  const bottomY = -2.2;
  const segments = 6;

  const vertices = [];
  const indices = [];

  // Top apex
  const topIdx = vertices.length / 3;
  vertices.push(0, topY, 0);

  // Mid ring
  for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    vertices.push(Math.cos(angle) * midRadius, midY, Math.sin(angle) * midRadius);
  }

  // Inner mid ring (smaller, for faceting)
  for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * Math.PI * 2 + Math.PI / segments;
    vertices.push(Math.cos(angle) * (midRadius * 0.65), midY * 0.55, Math.sin(angle) * (midRadius * 0.65));
  }

  // Bottom apex
  const bottomIdx = vertices.length / 3;
  vertices.push(0, bottomY, 0);

  // Top ring (smaller)
  for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    vertices.push(Math.cos(angle) * topRadius, topY * 0.45, Math.sin(angle) * topRadius);
  }

  // Bottom ring (smaller)
  for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    vertices.push(Math.cos(angle) * bottomRadius, bottomY * 0.45, Math.sin(angle) * bottomRadius);
  }

  const midStart = topIdx + 1;
  const innerStart = midStart + segments;
  const topRingStart = bottomIdx + 1;
  const bottomRingStart = topRingStart + segments;

  // Top apex → top ring → mid ring
  for (let i = 0; i < segments; i++) {
    const next = (i + 1) % segments;
    indices.push(topIdx, topRingStart + i, topRingStart + next);
    indices.push(topIdx, topRingStart + next, midStart + i);
    indices.push(topRingStart + i, topRingStart + next, midStart + i);
    indices.push(midStart + i, midStart + next, innerStart + i);
  }

  // Inner ring connections
  for (let i = 0; i < segments; i++) {
    const prev = (i - 1 + segments) % segments;
    indices.push(innerStart + i, midStart + i, midStart + prev);
    indices.push(innerStart + i, midStart + prev, innerStart + prev);
  }

  // Bottom: mid ring → bottom ring → bottom apex
  for (let i = 0; i < segments; i++) {
    const next = (i + 1) % segments;
    indices.push(midStart + i, bottomRingStart + i, midStart + next);
    indices.push(bottomRingStart + i, bottomRingStart + next, midStart + next);
    indices.push(midStart + next, bottomRingStart + next, bottomIdx);
    indices.push(bottomRingStart + next, bottomIdx, bottomRingStart + i);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  return geo;
}

const crystalGeo = createCrystalGeometry();

// ── Crystal Material ──────────────────────────────────────
const crystalMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.97,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.02,
  ior: 2.4,               // diamond-like
  thickness: 2.5,
  specularIntensity: 1.0,
  specularColor: new THREE.Color(0xffffff),
  clearcoat: 1.0,
  clearcoatRoughness: 0.01,
  attenuationColor: new THREE.Color(0.85, 0.92, 1.0),
  attenuationDistance: 4,
  envMapIntensity: 2.0,
  side: THREE.DoubleSide,
});

const crystal = new THREE.Mesh(crystalGeo, crystalMat);
scene.add(crystal);

// ── Inner glow core ───────────────────────────────────────
const coreGeo = new THREE.IcosahedronGeometry(0.6, 1);
const coreMat = new THREE.MeshBasicMaterial({
  color: 0xaaccff,
  transparent: true,
  opacity: 0.3,
});
const core = new THREE.Mesh(coreGeo, coreMat);
crystal.add(core);

// ── Point light inside crystal ────────────────────────────
const innerLight = new THREE.PointLight(0x88aaff, 3, 6);
crystal.add(innerLight);

// ── Rainbow floor disc ────────────────────────────────────
const rainbowCanvas = document.createElement('canvas');
rainbowCanvas.width = 512;
rainbowCanvas.height = 512;
const ctx = rainbowCanvas.getContext('2d');
const gradient = ctx.createRadialGradient(256, 256, 0, 256, 256, 256);
gradient.addColorStop(0.0, 'rgba(255,255,255,0.25)');
gradient.addColorStop(0.15, 'rgba(200,220,255,0.15)');
gradient.addColorStop(0.3, 'rgba(100,180,255,0.08)');
gradient.addColorStop(0.5, 'rgba(100,255,200,0.04)');
gradient.addColorStop(0.7, 'rgba(255,200,100,0.02)');
gradient.addColorStop(1.0, 'rgba(0,0,0,0)');
ctx.fillStyle = gradient;
ctx.fillRect(0, 0, 512, 512);

const rainbowTex = new THREE.CanvasTexture(rainbowCanvas);
const floorGeo = new THREE.CircleGeometry(5, 64);
const floorMat = new THREE.MeshBasicMaterial({
  map: rainbowTex,
  transparent: true,
  opacity: 0.8,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3.2;
scene.add(floor);

// ── Lighting ──────────────────────────────────────────────
const ambient = new THREE.AmbientLight(0x334466, 0.5);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899ff, 1.5);
fillLight.position.set(-5, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff8866, 1.0);
rimLight.position.set(0, -2, -6);
scene.add(rimLight);

// Colored accent lights for prism dispersion feel
const rLight = new THREE.PointLight(0xff4466, 2, 15);
rLight.position.set(4, 2, 3);
scene.add(rLight);

const gLight = new THREE.PointLight(0x44ff88, 2, 15);
gLight.position.set(-4, 1, 3);
scene.add(gLight);

const bLight = new THREE.PointLight(0x4466ff, 2, 15);
bLight.position.set(0, -3, 5);
scene.add(bLight);

// ── Floating particles ────────────────────────────────────
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3]     = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x8899cc,
  size: 0.03,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ─────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  crystal.rotation.y = t * 0.25;
  crystal.position.y = Math.sin(t * 0.5) * 0.3;

  core.rotation.x = t * 0.4;
  core.rotation.z = t * 0.3;
  coreMat.opacity = 0.2 + Math.sin(t * 2) * 0.1;

  innerLight.intensity = 2 + Math.sin(t * 1.5) * 1;

  particles.rotation.y = t * 0.02;
  particles.rotation.x = t * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```

**What's in this demo:**

- **Custom crystal geometry** — a faceted hexagonal bipyramid with inner ridges for extra refraction surfaces
- **`MeshPhysicalMaterial`** with high IOR (2.4, diamond-like), 97% transmission, clearcoat, and blue-ish attenuation color for a realistic glass/crystal look
- **Glowing core** — a softly pulsing icosahedron + point light inside the crystal
- **Rainbow floor** — an additive-blended disc beneath the crystal suggesting light dispersion
- **Multi-colored lighting** — warm key, cool fill, orange rim, plus red/green/blue accent point lights
- **Floating particles** — subtle ambient dust motes with additive blending
- **OrbitControls** — drag to rotate, scroll to zoom
- **Gentle animation** — slow rotation, floating bob, and pulsing inner glow

