        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Frog Construction
        const frogGroup = new THREE.Group();
        const frogMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x66cc44, 
            roughness: 0.4,
            metalness: 0.1
        });
        const eyeMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const pupilMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });

        // Body
        const bodyGeo = new THREE.SphereGeometry(2, 32, 32);
        const body = new THREE.Mesh(bodyGeo, frogMaterial);
        body.scale.set(1, 0.8, 1.2);
        body.position.y = 2;
        body.castShadow = true;
        body.receiveShadow = true;
        frogGroup.add(body);

        // Belly
        const bellyGeo = new THREE.SphereGeometry(1.5, 32, 32);
        const bellyMat = new THREE.MeshStandardMaterial({ color: 0xccffcc });
        const belly = new THREE.Mesh(bellyGeo, bellyMat);
        belly.scale.set(0.9, 0.7, 1.1);
        belly.position.set(0, 1.5, 0.5);
        frogGroup.add(belly);

        // Eyes
        function createEye(xPos) {
            const eyeGroup = new THREE.Group();
            const eyeWhite = new THREE.Mesh(new THREE.SphereGeometry(0.6, 16, 16), eyeMaterial);
            eyeWhite.position.set(0, 0, 0);
            eyeWhite.castShadow = true;

            const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), pupilMaterial);
            pupil.position.set(0, 0, 0.45);

            eyeGroup.add(eyeWhite);
            eyeGroup.add(pupil);
            eyeGroup.position.set(xPos, 3.2, 0.5);
            return eyeGroup;
        }

        frogGroup.add(createEye(-1.2));
        frogGroup.add(createEye(1.2));

        // Legs
        function createLeg(xPos, zPos, rotZ, rotX) {
            const legGroup = new THREE.Group();
            const upperLeg = new THREE.Mesh(new THREE.CapsuleGeometry(0.4, 1.5, 4, 8), frogMaterial);
            upperLeg.position.set(0, 0, 0);
            upperLeg.castShadow = true;

            const foot = new THREE.Mesh(new THREE.SphereGeometry(0.5, 16, 16), frogMaterial);
            foot.position.set(0, -0.8, 0.5);
            foot.scale.set(1.2, 0.5, 1.5);
            foot.castShadow = true;

            legGroup.add(upperLeg);
            legGroup.add(foot);

            legGroup.position.set(xPos, 1.5, zPos);
            legGroup.rotation.z = rotZ;
            legGroup.rotation.x = rotX;
            return legGroup;
        }

        // Back legs
        frogGroup.add(createLeg(-1.5, -0.5, 0.5, -0.5));
        frogGroup.add(createLeg(1.5, -0.5, -0.5, -0.5));

        // Front legs
        frogGroup.add(createLeg(-1.2, 1.2, 0.2, 0.5));
        frogGroup.add(createLeg(1.2, 1.2, -0.2, 0.5));

        scene.add(frogGroup);

