            roughness: 0.2,
        });

        // Sundial Construction
        const sundialGroup = new THREE.Group();
        scene.add(sundialGroup);

        // 1. Base Plate (Circular)
        const baseGeometry = new THREE.CylinderGeometry(2, 2, 0.1, 64);
        const base = new THREE.Mesh(baseGeometry, brassMaterial);
        base.receiveShadow = true;
        base.castShadow = true;
        sundialGroup.add(base);

        // 2. Inner Dial Face (Slightly smaller, darker for contrast)
        const faceGeometry = new THREE.CylinderGeometry(1.8, 1.8, 0.11, 64);
        const face = new THREE.Mesh(faceGeometry, darkMetalMaterial);
        face.receiveShadow = true;
        sundialGroup.add(face);

        // 3. Hour Lines
        const hourLineGeometry = new THREE.BoxGeometry(0.02, 0.02, 1.6);
        for (let i = 0; i < 12; i++) {
            const angle = (i * 30) * (Math.PI / 180); // 30 degrees per hour
            const line = new THREE.Mesh(hourLineGeometry, brassMaterial);
            line.rotation.y = angle;
            line.position.z = 0.9; // Offset from center
            line.position.y = 0.06; // Slightly above face
            line.castShadow = true;
            sundialGroup.add(line);

            // Add numbers (simulated with small dots for simplicity in pure geometry)
            const dotGeo = new THREE.SphereGeometry(0.05, 16, 16);
            const dot = new THREE.Mesh(dotGeo, brassMaterial);
            dot.position.set(Math.sin(angle) * 1.7, 0.06, Math.cos(angle) * 1.7);
            sundialGroup.add(dot);
        }

        // 4. Gnomon (The triangular pointer)
        // Create a custom shape for the gnomon
        const gnomonShape = new THREE.Shape();
        gnomonShape.moveTo(0, 0);
        gnomonShape.lineTo(0.5, 1.5); // Tip
        gnomonShape.lineTo(1.0, 0);
        gnomonShape.lineTo(0, 0);

        const extrudeSettings = {
            steps: 1,
            depth: 0.05,
            bevelEnabled: true,
            bevelThickness: 0.02,
            bevelSize: 0.02,
            bevelSegments: 2
        };

        const gnomonGeometry = new THREE.ExtrudeGeometry(gnomonShape, extrudeSettings);
        const gnomon = new THREE.Mesh(gnomonGeometry, brassMaterial);

        // Position and rotate gnomon
        // It needs to point North (along Z axis) and be tilted by latitude (approx 40 deg)
        gnomon.rotation.x = -Math.PI / 2; // Lay flat first
        gnomon.rotation.z = Math.PI / 2; // Rotate to stand up
        gnomon.rotation.y = Math.PI / 4; // Tilt for latitude (approx 45 deg for visual effect)

        // Center the geometry roughly
        gnomon.position.set(0, 0.1, 0);
        gnomon.castShadow = true;
        gnomon.receiveShadow = true;
        sundialGroup.add(gnomon);

        // 5. Ring around the edge
        const ringGeometry = new THREE.TorusGeometry(2, 0.05, 16, 100);
        const ring = new THREE.Mesh(ringGeometry, brassMaterial);
        ring.rotation.x = Math.PI / 2;
        ring.position.y = 0.05;
        ring.castShadow = true;
        sundialGroup.add(ring);

        // Ground Plane (to catch shadows if camera moves low)
        const planeGeometry = new THREE.PlaneGeometry(100, 100);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a2e });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -0.1;
        plane.receiveShadow = true;
        scene.add(plane);

        // Interaction Logic
        const slider = document.getElementById('timeSlider');
        const timeDisplay = document.getElementById('timeDisplay');

        function updateSunPosition(hour) {
            // Convert hour to angle
            // 12:00 is noon (sun overhead/south), 6:00 is sunrise (east), 18:00 is sunset (west)
            // We map 6-18 to -90deg to +90deg relative to South

            const normalizedHour = (hour - 12) / 6; // -1 to 1
            const angle = normalizedHour * (Math.PI / 2); // -90 to 90 degrees

            // Calculate position
            const distance = 10;
            const x = Math.sin(angle) * distance;
            const z = Math.cos(angle) * distance;
            const y = Math.cos(angle) * distance * 0.5 + 2; // Arc height

            sunLight.position.set(x, y, z);
            sunLight.lookAt(0, 0, 0);

            // Update UI text
            const h = Math.floor(hour);
            const m = Math.round((hour - h) * 60);
            timeDisplay.textContent = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
        }

        slider.addEventListener('input', (e) => {
            updateSunPosition(parseFloat(e.target.value));
        });

        // Initial update
        updateSunPosition(12);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
