</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a1a);

const pmrem = new THREE.PMREMGenerator(renderer);
pmrem.compileEquirectangularShader();
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 0.5, 5);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.8;
controls.target.set(0, 0, 0);

// ── Glass Marble ──
const glassGeo = new THREE.SphereGeometry(1.5, 128, 128);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.97,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.02,
  ior: 1.52,
  thickness: 1.5,
  specularIntensity: 1,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1.5,
  clearcoat: 0.1,
  clearcoatRoughness: 0.05,
  attenuationColor: new THREE.Color(0.85, 0.9, 1.0),
  attenuationDistance: 3,
});
const marble = new THREE.Mesh(glassGeo, glassMat);
scene.add(marble);

// ── Swirl Ribbons ──
function createSwirlRibbon(radius, tubeRadius, color1, color2, scale, twist, segments) {
  const points = [];
  const turns = twist;
  for (let i = 0; i <= segments; i++) {
    const t = (i / segments) * Math.PI * 2 * turns;
    const r = radius * (0.3 + 0.7 * Math.sin(t / (Math.PI * 2 * turns) * Math.PI));
    const x = r * Math.cos(t) * scale;
    const y = r * Math.sin(t) * scale * 0.6;
    const z = (i / segments - 0.5) * 2.5 * scale;
    points.push(new THREE.Vector3(x, y, z));
  }
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, segments * 4, tubeRadius * scale, 12, false);
  const mat = new THREE.MeshPhysicalMaterial({
    color: color1,
    emissive: color2,
    emissiveIntensity: 0.6,
    transmission: 0.3,
    transparent: true,
    opacity: 0.75,
    roughness: 0.1,
    metalness: 0.3,
    ior: 1.8,
    thickness: 0.5,
    envMapIntensity: 1,
  });
  return new THREE.Mesh(geo, mat);
}

const swirlGroup = new THREE.Group();

const ribbonConfigs = [
  { r: 1.0, tr: 0.06, c1: 0xff4488, c2: 0xff2266, s: 0.75, tw: 3, seg: 200 },
  { r: 0.85, tr: 0.05, c1: 0x44aaff, c2: 0x2288ff, s: 0.7, tw: -2.5, seg: 200 },
  { r: 1.1, tr: 0.04, c1: 0x88ff44, c2: 0x66ff22, s: 0.65, tw: 4, seg: 200 },
  { r: 0.7, tr: 0.07, c1: 0xffaa22, c2: 0xff8800, s: 0.8, tw: -3.5, seg: 200 },
  { r: 0.95, tr: 0.035, c1: 0xcc44ff, c2: 0xaa22ee, s: 0.6, tw: 2, seg: 200 },
  { r: 0.6, tr: 0.055, c1: 0x22ffcc, c2: 0x00ddaa, s: 0.85, tw: -4, seg: 200 },
];

ribbonConfigs.forEach(cfg => {
  const ribbon = createSwirlRibbon(cfg.r, cfg.tr, cfg.c1, cfg.c2, cfg.s, cfg.tw, cfg.seg);
  ribbon.rotation.x = Math.random() * Math.PI;
  ribbon.rotation.z = Math.random() * Math.PI;
  swirlGroup.add(ribbon);
});

// ── Inner Sparkle Particles ──
const particleCount = 600;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const colors = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = Math.pow(Math.random(), 0.5) * 1.3;
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  positions[i * 3 + 2] = r * Math.cos(phi);

  const hue = Math.random();
  const col = new THREE.Color().setHSL(hue, 0.8, 0.7);
  colors[i * 3] = col.r;
  colors[i * 3 + 1] = col.g;
  colors[i * 3 + 2] = col.b;

  sizes[i] = Math.random() * 3 + 1;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uPixelRatio: { value: renderer.getPixelRatio() },
  },
  vertexShader: `
    attribute float size;
    attribute vec3 color;
    varying vec3 vColor;
    varying float vAlpha;
    uniform float uTime;
    uniform float uPixelRatio;
    void main() {
      vColor = color;
      vec3 pos = position;
      pos += sin(uTime * 0.5 + position * 2.0) * 0.02;
      vec4 mvPos = modelViewMatrix * vec4(pos, 1.0);
      gl_PointSize = size * uPixelRatio * (80.0 / -mvPos.z);
      gl_Position = projectionMatrix * mvPos;
      vAlpha = smoothstep(1.5, 0.0, length(pos)) * 0.8;
    }
  `,
  fragmentShader: `
    varying vec3 vColor;
    varying float vAlpha;
    void main() {
      float d = length(gl_PointCoord - 0.5);
      if (d > 0.5) discard;
      float alpha = smoothstep(0.5, 0.0, d) * vAlpha;
      gl_FragColor = vec4(vColor * 1.5, alpha);
    }
  `,
  transparent: true,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});

const particles = new THREE.Points(particleGeo, particleMat);
swirlGroup.add(particles);

marble.add(swirlGroup);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffffff, 3);
keyLight.position.set(5, 5, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 1.5);
fillLight.position.set(-5, -2, 3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff8844, 2);
rimLight.position.set(0, 3, -5);
scene.add(rimLight);

// ── Post-Processing ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.4, 0.4, 0.85
);
composer.addPass(bloomPass);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  swirlGroup.rotation.y = t * 0.15;
  swirlGroup.rotation.x = Math.sin(t * 0.1) * 0.1;

  particleMat.uniforms.uTime.value = t;

  // Gentle floating
  marble.position.y = Math.sin(t * 0.5) * 0.1;

  controls.update();
  composer.render();
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
  particleMat.uniforms.uPixelRatio.value = renderer.getPixelRatio();
});
</script>
</body>
</html>
```

**What this creates:**

- **Glass marble** — a high-fidelity sphere using `MeshPhysicalMaterial` with transmission, IOR 1.52 (glass), attenuation color, and clearcoat for realistic refraction and transparency
- **6 colored swirl ribbons** — helical tube geometries in pink, blue, green, orange, purple, and teal that twist through the marble interior with different scales and winding directions
- **600 sparkle particles** — additive-blended point sprites with a custom shader for gentle floating motion and soft glow
- **Studio lighting** — key, fill, and rim lights plus a `RoomEnvironment` probe for rich reflections
- **Bloom post-processing** — subtle `UnrealBloomPass` for internal glow
- **OrbitControls** — auto-rotates slowly; drag to orbit, scroll to zoom

