        pointLight1.position.set(-5, 2, 0);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xff4444, 5, 20);
        pointLight2.position.set(5, 2, 0);
        scene.add(pointLight2);

        // Environment Map (Simple procedural one for reflections)
        const cubeRenderTarget = new THREE.WebGLCubeRenderTarget(256);
        const cubeCamera = new THREE.CubeCamera(0.1, 100, cubeRenderTarget);
        scene.add(cubeCamera);

        // Glass Material
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            ior: 1.5,
            envMap: cubeRenderTarget.texture,
            envMapIntensity: 1.0,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            side: THREE.DoubleSide
        });

        // The Harmonica Group
        const harmonicaGroup = new THREE.Group();
        scene.add(harmonicaGroup);

        // Central Spindle
        const spindleGeo = new THREE.CylinderGeometry(0.1, 0.1, 12, 16);
        const spindleMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.8, roughness: 0.2 });
        const spindle = new THREE.Mesh(spindleGeo, spindleMat);
        spindle.rotation.z = Math.PI / 2;
        harmonicaGroup.add(spindle);

        // Create Bowls
        const bowlCount = 24;
        const bowls = [];

        // Geometry for a bowl (Cylinder with open top)
        // radiusTop, radiusBottom, height, radialSegments, heightSegments, openEnded
        const bowlGeo = new THREE.CylinderGeometry(1, 0.8, 0.6, 32, 1, true);

        for (let i = 0; i < bowlCount; i++) {
            // Size decreases as we go "in" (or along the axis)
            // Franklin's instrument had bowls nested inside each other.
            // We will simulate this by scaling them and stacking them slightly.

            const scale = 1.0 - (i * 0.035); 
            if (scale <= 0.2) break;

            const bowl = new THREE.Mesh(bowlGeo, glassMaterial);

            // Position along the X axis
            // We stack them slightly so they don't clip perfectly
            const xPos = (i - bowlCount/2) * 0.15; 

            bowl.scale.set(scale, scale, scale);
            bowl.position.set(xPos, 0, 0);

            // Add a rim (torus) to make it look more like a glass bowl
            const rimGeo = new THREE.TorusGeometry(1 * scale, 0.02 * scale, 8, 32);
            const rim = new THREE.Mesh(rimGeo, glassMaterial);
            rim.rotation.x = Math.PI / 2;
            rim.position.y = 0.3 * scale; // Top of the bowl
            bowl.add(rim);

            bowls.push(bowl);
            harmonicaGroup.add(bowl);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Update environment map occasionally for reflections
            if (Math.floor(time * 10) % 5 === 0) {
                harmonicaGroup.visible = false;
                cubeCamera.position.copy(harmonicaGroup.position);
                cubeCamera.update(renderer, scene);
                harmonicaGroup.visible = true;
            }

            // Gentle floating animation
            harmonicaGroup.position.y = Math.sin(time * 0.5) * 0.2;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
