<body>
    <div id="info">Marine Sextant — Drag to orbit · Scroll to zoom</div>

    <!-- Import Three.js from CDN -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
