            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.9,
            thickness: 0.1,
            transparent: true,
            opacity: 0.3
        });

        // Sextant Group
        const sextantGroup = new THREE.Group();
        scene.add(sextantGroup);

        // 1. The Frame (Arc)
        // Radius 2, Tube 0.1, Arc 60 degrees (PI/3)
        const frameGeometry = new THREE.TorusGeometry(2, 0.08, 16, 50, Math.PI / 3);
        const frame = new THREE.Mesh(frameGeometry, brassMaterial);
        frame.rotation.z = Math.PI / 6; // Center the arc visually
        frame.castShadow = true;
        sextantGroup.add(frame);

        // 2. The Index Arm (The moving part)
        const armGroup = new THREE.Group();
        // Pivot point is at the center of the arc (0,0,0)
        sextantGroup.add(armGroup);

        // Arm body
        const armGeometry = new THREE.BoxGeometry(0.15, 2.2, 0.05);
        const arm = new THREE.Mesh(armGeometry, brassMaterial);
        arm.position.y = 1.1; // Offset so it starts from center
        arm.castShadow = true;
        armGroup.add(arm);

        // Index Mirror (on the arm)
        const indexMirrorGeo = new THREE.BoxGeometry(0.4, 0.4, 0.02);
        const indexMirror = new THREE.Mesh(indexMirrorGeo, glassMaterial);
        indexMirror.position.set(0, 1.8, 0.05);
        indexMirror.rotation.x = -0.2; // Tilted
        armGroup.add(indexMirror);

        // 3. The Telescope (Fixed on the side)
        const telescopeGroup = new THREE.Group();
        telescopeGroup.position.set(1.73, 1, 0); // End of the arc (approx cos(30), sin(30))
        telescopeGroup.rotation.z = -Math.PI / 6; // Align with tangent
        sextantGroup.add(telescopeGroup);

        const tubeGeo = new THREE.CylinderGeometry(0.12, 0.15, 1.5, 16);
        const tube = new THREE.Mesh(tubeGeo, brassMaterial);
        tube.rotation.x = Math.PI / 2;
        tube.castShadow = true;
        telescopeGroup.add(tube);

        // Eyepiece
        const eyeGeo = new THREE.CylinderGeometry(0.08, 0.12, 0.3, 16);
        const eye = new THREE.Mesh(eyeGeo, darkMetalMaterial);
        eye.rotation.x = Math.PI / 2;
        eye.position.z = -0.9;
        telescopeGroup.add(eye);

        // 4. Horizon Glass (Fixed on the frame near telescope)
        const horizonGlassGeo = new THREE.BoxGeometry(0.3, 0.3, 0.02);
        const horizonGlass = new THREE.Mesh(horizonGlassGeo, glassMaterial);
        horizonGlass.position.set(1.6, 0.8, 0.1);
        horizonGlass.rotation.z = -Math.PI / 6;
        sextantGroup.add(horizonGlass);

        // 5. Handle (Bottom)
        const handleGeo = new THREE.BoxGeometry(0.2, 1.5, 0.1);
        const handle = new THREE.Mesh(handleGeo, brassMaterial);
        handle.position.set(0, -1.5, 0);
        handle.castShadow = true;
        sextantGroup.add(handle);

        // Handle Grip (Leather-like texture simulation via color)
        const gripGeo = new THREE.BoxGeometry(0.22, 0.8, 0.12);
        const gripMat = new THREE.MeshStandardMaterial({ color: 0x5c4033, roughness: 0.9 });
        const grip = new THREE.Mesh(gripGeo, gripMat);
        grip.position.set(0, -1.8, 0);
        sextantGroup.add(grip);

        // 6. Micrometer Drum (On the arm)
        const drumGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.1, 32);
        const drum = new THREE.Mesh(drumGeo, darkMetalMaterial);
        drum.rotation.x = Math.PI / 2;
        drum.position.set(0, 0.5, 0.1);
        armGroup.add(drum);

        // 7. Vernier Scale (On the frame)
        const scaleGeo = new THREE.BoxGeometry(0.05, 0.8, 0.02);
        const scale = new THREE.Mesh(scaleGeo, darkMetalMaterial);
        scale.position.set(0.1, 0.5, 0);
        sextantGroup.add(scale);

        // Add some decorative rivets
        const rivetGeo = new THREE.CylinderGeometry(0.03, 0.03, 0.05, 8);
        const rivetPositions = [
            { x: 1.73, y: 1, z: 0.06 }, // Top of frame
            { x: 0, y: 2, z: 0.06 }, // Top of arc
            { x: -1.73, y: 1, z: 0.06 } // Bottom of arc
        ];

        rivetPositions.forEach(pos => {
            const rivet = new THREE.Mesh(rivetGeo, darkMetalMaterial);
            rivet.position.set(pos.x, pos.y, pos.z);
            rivet.rotation.x = Math.PI / 2;
            sextantGroup.add(rivet);
        });

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Slow rotation for presentation
            sextantGroup.rotation.y += 0.002;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
