        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 1, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0x00ff00, 5);
        spotLight.position.set(-5, 5, 0);
        spotLight.lookAt(0, 0, 0);
        scene.add(spotLight);

        // Materials
        const mantisGreen = new THREE.MeshStandardMaterial({ 
            color: 0x4caf50, 
            roughness: 0.4,
            metalness: 0.1
        });
        const darkGreen = new THREE.MeshStandardMaterial({ 
            color: 0x2e7d32, 
            roughness: 0.5 
        });
        const eyeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.2 
        });

        // Mantis Construction
        const mantis = new THREE.Group();

        // 1. Abdomen
        const abdomenGeo = new THREE.CylinderGeometry(0.15, 0.05, 1.2, 8);
        const abdomen = new THREE.Mesh(abdomenGeo, mantisGreen);
        abdomen.rotation.x = Math.PI / 2;
        abdomen.position.set(0, 0, -0.6);
        abdomen.castShadow = true;
        mantis.add(abdomen);

        // 2. Thorax
        const thoraxGeo = new THREE.CylinderGeometry(0.2, 0.15, 0.4, 8);
        const thorax = new THREE.Mesh(thoraxGeo, mantisGreen);
        thorax.rotation.x = Math.PI / 2;
        thorax.position.set(0, 0, 0);
        thorax.castShadow = true;
        mantis.add(thorax);

        // 3. Head (Triangular shape)
        const headGeo = new THREE.ConeGeometry(0.2, 0.3, 3);
        const head = new THREE.Mesh(headGeo, mantisGreen);
        head.rotation.x = -Math.PI / 2; // Point forward
        head.rotation.z = Math.PI; // Invert to point up/forward correctly relative to body
        head.position.set(0, 0.1, 0.35);
        head.castShadow = true;
        mantis.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.06, 8, 8);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.15, 0.15, 0.45);
        mantis.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.15, 0.15, 0.45);
        mantis.add(rightEye);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.01, 0.005, 0.6, 4);
        const leftAntenna = new THREE.Mesh(antennaGeo, darkGreen);
        leftAntenna.position.set(-0.1, 0.2, 0.5);
        leftAntenna.rotation.set(0.5, 0, -0.5);
        mantis.add(leftAntenna);
        const rightAntenna = new THREE.Mesh(antennaGeo, darkGreen);
        rightAntenna.position.set(0.1, 0.2, 0.5);
        rightAntenna.rotation.set(0.5, 0, 0.5);
        mantis.add(rightAntenna);

        // 4. Wings (Simple flat shapes)
        const wingGeo = new THREE.BoxGeometry(0.3, 0.02, 1.0);
        const leftWing = new THREE.Mesh(wingGeo, darkGreen);
        leftWing.position.set(-0.15, 0.05, -0.3);
        leftWing.rotation.y = 0.1;
        mantis.add(leftWing);
        const rightWing = new THREE.Mesh(wingGeo, darkGreen);
        rightWing.position.set(0.15, 0.05, -0.3);
        rightWing.rotation.y = -0.1;
        mantis.add(rightWing);

        // 5. Legs
        function createLeg(isRaptorial = false) {
            const legGroup = new THREE.Group();

            if (isRaptorial) {
                // Raptorial Foreleg (The "praying" legs)
                // Upper arm
                const upperArmGeo = new THREE.CylinderGeometry(0.04, 0.03, 0.4, 6);
                const upperArm = new THREE.Mesh(upperArmGeo, mantisGreen);
                upperArm.position.set(0, 0, 0.2);
                upperArm.rotation.x = Math.PI / 4;
                legGroup.add(upperArm);

                // Lower leg (femur) - thick and spiky
                const femurGeo = new THREE.CylinderGeometry(0.05, 0.03, 0.5, 6);
                const femur = new THREE.Mesh(femurGeo, mantisGreen);
                femur.position.set(0, 0.2, 0.4);
                femur.rotation.x = -Math.PI / 3;
                legGroup.add(femur);

                // Tibia (shin) - folded
                const tibiaGeo = new THREE.CylinderGeometry(0.03, 0.02, 0.4, 6);
                const tibia = new THREE.Mesh(tibiaGeo, mantisGreen);
                tibia.position.set(0, 0.4, 0.2);
                tibia.rotation.x = Math.PI / 2;
                legGroup.add(tibia);

                // Spikes on femur
                for(let i=0; i<3; i++) {
                    const spikeGeo = new THREE.ConeGeometry(0.02, 0.1, 4);
                    const spike = new THREE.Mesh(spikeGeo, darkGreen);
                    spike.position.set(0, 0.2 + (i*0.1), 0.4 + (i*0.05));
                    spike.rotation.z = Math.PI / 2;
                    legGroup.add(spike);
                }

            } else {
                // Standard Leg (Middle/Back)
                const upperGeo = new THREE.CylinderGeometry(0.03, 0.02, 0.3, 6);
                const upper = new THREE.Mesh(upperGeo, mantisGreen);
                upper.position.set(0, 0, 0.15);
                upper.rotation.x = Math.PI / 4;
                legGroup.add(upper);

                const lowerGeo = new THREE.CylinderGeometry(0.02, 0.01, 0.6, 6);
                const lower = new THREE.Mesh(lowerGeo, mantisGreen);
                lower.position.set(0, 0.15, 0.3);
                lower.rotation.x = -Math.PI / 4;
                legGroup.add(lower);
            }
            return legGroup;
        }

        // Forelegs (Raptorial)
        const leftForeleg = createLeg(true);
        leftForeleg.position.set(-0.2, 0, 0.2);
        leftForeleg.rotation.y = 0.5;
        mantis.add(leftForeleg);

        const rightForeleg = createLeg(true);
        rightForeleg.position.set(0.2, 0, 0.2);
        rightForeleg.rotation.y = -0.5;
        mantis.add(rightForeleg);

        // Middle Legs
        const leftMidLeg = createLeg(false);
        leftMidLeg.position.set(-0.2, 0, 0);
        leftMidLeg.rotation.y = 0.8;
        mantis.add(leftMidLeg);

        const rightMidLeg = createLeg(false);
        rightMidLeg.position.set(0.2, 0, 0);
        rightMidLeg.rotation.y = -0.8;
        mantis.add(rightMidLeg);

        // Back Legs
        const leftBackLeg = createLeg(false);
        leftBackLeg.position.set(-0.15, 0, -0.3);
        leftBackLeg.rotation.y = 1.2;
        mantis.add(leftBackLeg);

        const rightBackLeg = createLeg(false);
        rightBackLeg.position.set(0.15, 0, -0.3);
        rightBackLeg.rotation.y = -1.2;
        mantis.add(rightBackLeg);

        // Position the whole mantis
        mantis.position.y = 1.5;
        mantis.rotation.y = -Math.PI / 4;
        scene.add(mantis);

        // Ground Plane
        const planeGeo = new THREE.PlaneGeometry(20, 20);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const plane = new THREE.Mesh(planeGeo, planeMat);
