    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510); // Deep ocean dark blue
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0x00ffff, 5);
        spotLight.position.set(-5, 5, 0);
        spotLight.lookAt(0, 0, 0);
        scene.add(spotLight);

        // Octopus Construction
        const octopusGroup = new THREE.Group();
        scene.add(octopusGroup);

        // Materials
        const skinMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x8B5A2B, // Brownish
            roughness: 0.6,
            metalness: 0.1
        });

        const ringMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x0000FF, 
            emissive: 0x0000AA,
            emissiveIntensity: 0.5,
            roughness: 0.2,
            metalness: 0.5
        });

        const eyeWhiteMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const pupilMaterial = new THREE.MeshStandardMaterial({ color: 0x000000 });

        // 1. Mantle (Body)
        const mantleGeometry = new THREE.SphereGeometry(1.2, 32, 32);
        mantleGeometry.scale(1, 0.8, 1.2); // Flatten slightly
        const mantle = new THREE.Mesh(mantleGeometry, skinMaterial);
        mantle.castShadow = true;
        mantle.receiveShadow = true;
        octopusGroup.add(mantle);

        // 2. Blue Rings
        function createRing(radius, tubeRadius, position, rotation) {
            const geometry = new THREE.TorusGeometry(radius, tubeRadius, 16, 100);
            const ring = new THREE.Mesh(geometry, ringMaterial);
            ring.position.copy(position);
            ring.rotation.copy(rotation);
            return ring;
        }

        // Add rings around the mantle
        const ring1 = createRing(1.1, 0.05, new THREE.Vector3(0, 0.2, 0.5), new THREE.Euler(Math.PI / 2, 0, 0));
        octopusGroup.add(ring1);

        const ring2 = createRing(0.9, 0.05, new THREE.Vector3(0, -0.1, 0.8), new THREE.Euler(Math.PI / 2, 0, 0));
        octopusGroup.add(ring2);

        const ring3 = createRing(1.0, 0.05, new THREE.Vector3(0.5, 0.1, 0.6), new THREE.Euler(Math.PI / 2, Math.PI / 4, 0));
        octopusGroup.add(ring3);

        const ring4 = createRing(0.8, 0.05, new THREE.Vector3(-0.5, 0.1, 0.6), new THREE.Euler(Math.PI / 2, -Math.PI / 4, 0));
        octopusGroup.add(ring4);

        // 3. Tentacles
        const tentacles = [];
        const tentacleCount = 8;

        for (let i = 0; i < tentacleCount; i++) {
            const angle = (i / tentacleCount) * Math.PI * 2;

            // Create a curve for the tentacle
            const points = [];
            const startY = -0.5;
            const startX = Math.cos(angle) * 0.8;
            const startZ = Math.sin(angle) * 0.8;

            points.push(new THREE.Vector3(startX, startY, startZ));
            points.push(new THREE.Vector3(startX * 1.2, startY - 1.5, startZ * 1.2));
            points.push(new THREE.Vector3(startX * 1.5, startY - 2.5, startZ * 1.5));
            points.push(new THREE.Vector3(startX * 1.2, startY - 3.5, startZ * 1.2));

            const curve = new THREE.CatmullRomCurve3(points);
            const geometry = new THREE.TubeGeometry(curve, 20, 0.15, 8, false);
            const tentacle = new THREE.Mesh(geometry, skinMaterial);
            tentacle.castShadow = true;

            // Store original points for animation
            tentacle.userData = { 
                originalPoints: points.map(p => p.clone()),
                offset: Math.random() * Math.PI 
            };

            octopusGroup.add(tentacle);
            tentacles.push(tentacle);
        }

        // 4. Eyes
        const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const pupilGeo = new THREE.SphereGeometry(0.08, 16, 16);

        const leftEye = new THREE.Mesh(eyeGeo, eyeWhiteMaterial);
        leftEye.position.set(-0.4, 0.2, 1.1);
        octopusGroup.add(leftEye);

        const leftPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        leftPupil.position.set(-0.4, 0.2, 1.25);
        octopusGroup.add(leftPupil);

        const rightEye = new THREE.Mesh(eyeGeo, eyeWhiteMaterial);
        rightEye.position.set(0.4, 0.2, 1.1);
        octopusGroup.add(rightEye);

        const rightPupil = new THREE.Mesh(pupilGeo, pupilMaterial);
        rightPupil.position.set(0.4, 0.2, 1.25);
        octopusGroup.add(rightPupil);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Float the whole octopus
            octopusGroup.position.y = Math.sin(time * 0.5) * 0.2;
            octopusGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Animate tentacles
            tentacles.forEach((tentacle, index) => {
                const curve = tentacle.geometry.parameters.path;
                const points = curve.points;
                const offset = tentacle.userData.offset;

                // Wiggle the end of the tentacles
                points[2].x = tentacle.userData.originalPoints[2].x + Math.sin(time * 2 + offset) * 0.2;
                points[2].z = tentacle.userData.originalPoints[2].z + Math.cos(time * 2 + offset) * 0.2;

                points[3].x = tentacle.userData.originalPoints[3].x + Math.sin(time * 3 + offset) * 0.3;
                points[3].z = tentacle.userData.originalPoints[3].z + Math.cos(time * 3 + offset) * 0.3;

                // Update geometry
                tentacle.geometry.dispose();
                const newCurve = new THREE.CatmullRomCurve3(points);
                tentacle.geometry = new THREE.TubeGeometry(newCurve, 20, 0.15, 8, false);
            });

            // Pulse the rings
            const pulse = 1 + Math.sin(time * 5) * 0.1;
            ring1.scale.set(pulse, pulse, pulse);
            ring2.scale.set(pulse, pulse, pulse);
            ring3.scale.set(pulse, pulse, pulse);
            ring4.scale.set(pulse, pulse, pulse);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
