<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);
scene.fog = new THREE.FogExp2(0x1a1a1a, 0.04);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 4, 14);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0.5, 0);
controls.minDistance = 6;
controls.maxDistance = 30;

// --- Materials ---
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xc4923e, metalness: 0.92, roughness: 0.28
});
const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8b6914, metalness: 0.9, roughness: 0.35
});
const rodMat = new THREE.MeshStandardMaterial({
  color: 0xd4a84b, metalness: 0.95, roughness: 0.15
});
const beadMat = new THREE.MeshStandardMaterial({
  color: 0xb8860b, metalness: 0.88, roughness: 0.3
});

// --- Helpers ---
function roundedBox(w, h, d, r) {
  const shape = new THREE.Shape();
  const hw = w / 2 - r, hh = h / 2 - r;
  shape.moveTo(-hw - r, -hh);
  shape.lineTo(hw + r, -hh);
  shape.quadraticCurveTo(hw + r + r, -hh, hw + r, -hh + r);
  shape.lineTo(hw + r, hh + r - r);
  shape.quadraticCurveTo(hw + r, hh + r, hw, hh + r);
  shape.lineTo(-hw, hh + r);
  shape.quadraticCurveTo(-hw - r, hh + r, -hw - r, hh);
  shape.lineTo(-hw - r, -hh + r);
  shape.quadraticCurveTo(-hw - r, -hh, -hw, -hh);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: d, bevelEnabled: true, bevelThickness: r * 0.5,
    bevelSize: r * 0.5, bevelSegments: 4
  });
  geo.center();
  return geo;
}

// --- Frame ---
const frameGroup = new THREE.Group();

// Top bar
const topBar = new THREE.Mesh(roundedBox(7, 0.5, 1.2, 0.08), brassMat);
topBar.position.set(0, 3.8, 0);
frameGroup.add(topBar);

// Bottom bar
const botBar = new THREE.Mesh(roundedBox(7, 0.5, 1.2, 0.08), brassMat);
botBar.position.set(0, -2.8, 0);
frameGroup.add(botBar);

// Side posts
for (const x of [-3.25, 3.25]) {
  const post = new THREE.Mesh(roundedBox(0.5, 7.1, 1.2, 0.06), brassMat);
  post.position.set(x, 0.5, 0);
  frameGroup.add(post);
}

// Divider bar
const divider = new THREE.Mesh(roundedBox(7, 0.35, 1.25, 0.06), darkBrassMat);
divider.position.set(0, 1.0, 0);
frameGroup.add(divider);

// Decorative corners
for (const [x, y] of [[-3.25, 3.8], [3.25, 3.8], [-3.25, -2.8], [3.25, -2.8]]) {
  const corner = new THREE.Mesh(
    new THREE.SphereGeometry(0.3, 16, 16), brassMat
  );
  corner.position.set(x, y, 0);
  frameGroup.add(corner);
}

scene.add(frameGroup);

// --- Rods & Beads ---
const rodCount = 13;
const rodSpacing = 5.2 / (rodCount - 1);
const rodStartX = -3.0;

for (let i = 0; i < rodCount; i++) {
  const x = rodStartX + i * rodSpacing;

  // Rod (thin cylinder)
  const rodGeo = new THREE.CylinderGeometry(0.03, 0.03, 6.6, 8);
  const rod = new THREE.Mesh(rodGeo, rodMat);
  rod.position.set(x, 0.5, 0);
  scene.add(rod);

  // Heaven beads (above divider) - 1 per rod
  const heavenY = 2.5;
  const heavenBeadGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.25, 32);
  const hBead = new THREE.Mesh(heavenBeadGeo, beadMat);
  hBead.rotation.x = Math.PI / 2;
  hBead.position.set(x, heavenY, 0);
  // Randomly push some beads up
  if (Math.random() > 0.5) hBead.position.y = 3.2;
  scene.add(hBead);

  // Earth beads (below divider) - 4 per rod
  for (let j = 0; j < 4; j++) {
    const eBeadGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.25, 32);
    const eBead = new THREE.Mesh(eBeadGeo, beadMat);
    eBead.rotation.x = Math.PI / 2;
    eBead.position.set(x, -0.3 - j * 0.6, 0);
    // Randomly push some beads down
    if (j > 1 && Math.random() > 0.5) eBead.position.y -= 0.8;
    scene.add(eBead);
  }
}

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xfff4e0, 2.5);
dirLight.position.set(5, 8, 6);
dirLight.castShadow = true;
scene.add(dirLight);

const dirLight2 = new THREE.DirectionalLight(0xffc87a, 1.2);
dirLight2.position.set(-4, 3, -3);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xffaa44, 1.5, 20);
pointLight.position.set(0, 5, 4);
scene.add(pointLight);

// Rim light
const rimLight = new THREE.PointLight(0x4488ff, 0.6, 20);
rimLight.position.set(-6, 2, -5);
scene.add(rimLight);

// --- Ground reflection hint ---
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111111, metalness: 0.5, roughness: 0.6
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -4.5;
scene.add(ground);

// --- Animate ---
function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
