        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // Paw Print Group
        const pawGroup = new THREE.Group();
        scene.add(pawGroup);

        // Material for the paw (Snow leopard color - white/grey)
        const pawMaterial = new THREE.MeshStandardMaterial({
            color: 0xe0e0e0,
            roughness: 0.4,
            metalness: 0.1
        });

        // Helper function to create a pad
        function createPad(radius, x, y, z, scaleX = 1, scaleY = 1, scaleZ = 1) {
            const geometry = new THREE.SphereGeometry(radius, 32, 32);
            const mesh = new THREE.Mesh(geometry, pawMaterial);
            mesh.position.set(x, y, z);
            mesh.scale.set(scaleX, scaleY, scaleZ);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // 1. Main Metacarpal Pad (The big bottom pad)
        // Shaped somewhat like a heart/triangle
        const mainPadGeo = new THREE.SphereGeometry(1, 32, 32);
        const mainPad = new THREE.Mesh(mainPadGeo, pawMaterial);
        mainPad.scale.set(1.3, 0.4, 1.1); // Flatten it
        mainPad.position.set(0, 0, 0.5);
        mainPad.castShadow = true;
        mainPad.receiveShadow = true;
        pawGroup.add(mainPad);

        // 2. Digital Pads (The 4 toes)
        const toeRadius = 0.35;
        const toePositions = [
            { x: -0.8, z: -0.8, rot: 0.3 },   // Left outer
            { x: -0.3, z: -1.2, rot: 0.1 },   // Left inner
            { x: 0.3, z: -1.2, rot: -0.1 },   // Right inner
            { x: 0.8, z: -0.8, rot: -0.3 }    // Right outer
        ];

        toePositions.forEach(pos => {
            const toe = createPad(toeRadius, pos.x, 0, pos.z, 1, 0.8, 1);
            toe.rotation.x = Math.PI / 2; // Lay flat
            toe.rotation.z = pos.rot; // Slight angle
            pawGroup.add(toe);

            // Add a small claw tip
            const clawGeo = new THREE.ConeGeometry(0.08, 0.3, 16);
            const clawMat = new THREE.MeshStandardMaterial({ color: 0xdddddd });
            const claw = new THREE.Mesh(clawGeo, clawMat);

            // Position claw slightly in front of toe
            const clawDist = 0.4;
            const angle = Math.atan2(pos.x, pos.z); // Approximate angle
            claw.position.set(
                pos.x + Math.sin(angle) * clawDist,
                0.1,
                pos.z - Math.cos(angle) * clawDist
            );
            claw.rotation.x = Math.PI / 2;
            claw.rotation.z = pos.rot;
            claw.castShadow = true;
            pawGroup.add(claw);
        });

        // Ground Plane (Snow)
        const planeGeometry = new THREE.PlaneGeometry(20, 20);
        const planeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 1,
            metalness: 0
        });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -0.4; // Slightly below the paw
        plane.receiveShadow = true;
        scene.add(plane);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
