        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 6);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Environment for Glass Reflections
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        scene.environment = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffffff, 1);
        pointLight.position.set(-2, 3, 2);
        scene.add(pointLight);

        // Snow Globe Group
        const globeGroup = new THREE.Group();
        scene.add(globeGroup);

        // 1. The Glass Sphere
        const glassGeometry = new THREE.SphereGeometry(1.5, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            ior: 1.5,
            clearcoat: 1,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 1
        });
        const glassSphere = new THREE.Mesh(glassGeometry, glassMaterial);
        globeGroup.add(glassSphere);

        // 2. The Base (Wood-like)
        const baseGeometry = new THREE.CylinderGeometry(1.2, 1.3, 0.8, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x5c4033, 
            roughness: 0.6,
            metalness: 0.1
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = -1.2;
        globeGroup.add(base);

        // 3. Snow Ground inside
        const snowGroundGeo = new THREE.CircleGeometry(1.4, 32);
        const snowGroundMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
        const snowGround = new THREE.Mesh(snowGroundGeo, snowGroundMat);
        snowGround.rotation.x = -Math.PI / 2;
        snowGround.position.y = -1.15; // Just above the base
        globeGroup.add(snowGround);

        // 4. Snow Particles
        const particleCount = 400;
        const particlesGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const velocities = [];

        for (let i = 0; i < particleCount; i++) {
            // Random position inside sphere
            const r = 1.3 * Math.cbrt(Math.random());
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta) - 0.5; // Shift down a bit
            const z = r * Math.cos(phi);

            positions[i * 3] = x;
            positions[i * 3 + 1] = y;
            positions[i * 3 + 2] = z;

            velocities.push({
                x: (Math.random() - 0.5) * 0.005,
                y: -Math.random() * 0.01 - 0.005,
                z: (Math.random() - 0.5) * 0.005
            });
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const particlesMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.05,
            transparent: true,
            opacity: 0.8
        });
        const snowParticles = new THREE.Points(particlesGeometry, particlesMaterial);
        globeGroup.add(snowParticles);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 1.0;

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Animate Snow
            const posAttribute = particlesGeometry.getAttribute('position');
            for (let i = 0; i < particleCount; i++) {
                let y = posAttribute.getY(i);
                let x = posAttribute.getX(i);
                let z = posAttribute.getZ(i);

                // Apply velocity
                y += velocities[i].y;
                x += velocities[i].x;
                z += velocities[i].z;

                // Reset if hits bottom
                if (y < -1.1) {
                    y = 1.2;
                    x = (Math.random() - 0.5) * 2.5;
                    z = (Math.random() - 0.5) * 2.5;
                }

                posAttribute.setXYZ(i, x, y, z);
            }
            posAttribute.needsUpdate = true;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
