    <div id="info">Drag to rotate • Scroll to zoom</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 15);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x445566, 1);
        backLight.position.set(-5, -5, -5);
        scene.add(backLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642, // Brass color
            metalness: 0.9,
            roughness: 0.3,
        });

        const darkBrassMaterial = new THREE.MeshStandardMaterial({
            color: 0x8a7d32,
            metalness: 0.9,
            roughness: 0.4,
        });

        // Protractor Geometry Construction
        const protractorGroup = new THREE.Group();

        // 1. Main Body (Semi-circle with a hole)
        const shape = new THREE.Shape();
        const outerRadius = 5;
        const innerRadius = 0.5;
        const thickness = 0.3;

        // Outer Arc
        shape.absarc(0, 0, outerRadius, Math.PI, 0, false);
        // Line to inner hole start
        shape.lineTo(innerRadius, 0);
        // Inner Arc (Clockwise to create hole)
        shape.absarc(0, 0, innerRadius, 0, Math.PI, true);
        // Line back to start
        shape.lineTo(outerRadius, 0);

        const extrudeSettings = {
            steps: 1,
            depth: thickness,
            bevelEnabled: true,
            bevelThickness: 0.05,
            bevelSize: 0.05,
            bevelSegments: 3
        };

        const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
        // Center the geometry
        geometry.center();
        // Rotate to lie flat on XY plane (initially extruded along Z)
        geometry.rotateX(-Math.PI / 2);

        const protractorMesh = new THREE.Mesh(geometry, brassMaterial);
        protractorMesh.castShadow = true;
        protractorMesh.receiveShadow = true;
        protractorGroup.add(protractorMesh);

        // 2. Tick Marks
        const tickGeometry = new THREE.BoxGeometry(0.05, 0.15, 0.05); // width, height (along radius), depth
        const majorTickGeometry = new THREE.BoxGeometry(0.08, 0.25, 0.08);

        // We will use InstancedMesh for performance if we had many, but for ~18 ticks, simple meshes are fine.
        // Actually, let's just loop and add meshes for simplicity in a single file.

        const tickCount = 180;
        const tickStep = 1; // degrees

        // Create a merged geometry for ticks to keep draw calls low? 
        // Or just simple loop. Let's do simple loop for readability.

        for (let i = 0; i <= 180; i += tickStep) {
            const angle = (i * Math.PI) / 180;
            const isMajor = i % 10 === 0;
            const isMid = i % 5 === 0 && !isMajor;

            let currentGeo = tickGeometry;
            let currentHeight = 0.15;

            if (isMajor) {
                currentGeo = majorTickGeometry;
                currentHeight = 0.25;
            } else if (isMid) {
                currentHeight = 0.2;
                // Reuse geometry but scale? No, let's just make a medium one or scale the mesh.
                // Let's just use the major one scaled down or create a medium one.
                // To keep it simple, let's just use the major geometry and scale it.
            }

            const tick = new THREE.Mesh(currentGeo, darkBrassMaterial);

            // Position on the outer edge
            const r = outerRadius - 0.1; // slightly inside the edge
            const x = r * Math.cos(angle);
            const y = r * Math.sin(angle);

            tick.position.set(x, y, thickness / 2 + 0.02); // slightly above surface

            // Rotate to face center
            tick.rotation.z = -angle + Math.PI / 2;

            if (isMid) {
                tick.scale.set(1, 0.8, 1);
            }

            protractorGroup.add(tick);
        }

        // 3. Center Pivot Pin
        const pinGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.5, 32);
        const pin = new THREE.Mesh(pinGeo, darkBrassMaterial);
        pin.position.z = thickness / 2 + 0.1;
        protractorGroup.add(pin);

        // 4. Text/Numbers (Simulated with small boxes for simplicity, or just skip for "compact")
        // Adding actual text requires font loading which is complex for a single file without external assets.
        // We will rely on the ticks to convey "protractor".

        scene.add(protractorGroup);

        // Animation
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
