    <div id="info">🐴 Thorny Seahorse — drag to orbit</div>

    <!-- Import Three.js as an ES module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x001e36); // Deep ocean blue
        scene.fog = new THREE.Fog(0x001e36, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x0044ff, 1);
        backLight.position.set(-5, 0, -5);
        scene.add(backLight);

        // Seahorse Construction
        const seahorseGroup = new THREE.Group();
        const bodyMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffaa00, 
            roughness: 0.4,
            metalness: 0.1
        });
        const thornMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffcc00, 
            roughness: 0.3 
        });

        // 1. Main Body Curve
        // Points defining the S-shape of the seahorse
        const bodyPoints = [
            new THREE.Vector3(0, -2.5, 0),   // Tail start
            new THREE.Vector3(0.5, -1.5, 0), // Lower body
            new THREE.Vector3(0.8, -0.5, 0), // Mid body
            new THREE.Vector3(0.6, 0.5, 0),  // Upper body
            new THREE.Vector3(0.2, 1.2, 0),  // Neck
            new THREE.Vector3(-0.2, 1.6, 0), // Head top
            new THREE.Vector3(-0.6, 1.5, 0)  // Snout
        ];

        const bodyCurve = new THREE.CatmullRomCurve3(bodyPoints);
        const bodyGeometry = new THREE.TubeGeometry(bodyCurve, 20, 0.25, 8, false);
        const bodyMesh = new THREE.Mesh(bodyGeometry, bodyMaterial);
        bodyMesh.castShadow = true;
        seahorseGroup.add(bodyMesh);

        // 2. Tail Curl
        const tailPoints = [
            new THREE.Vector3(0, -2.5, 0),
            new THREE.Vector3(0.2, -2.8, 0.2),
            new THREE.Vector3(0.5, -2.8, 0),
            new THREE.Vector3(0.5, -2.5, -0.2),
            new THREE.Vector3(0.2, -2.4, 0)
        ];
        const tailCurve = new THREE.CatmullRomCurve3(tailPoints);
        const tailGeometry = new THREE.TubeGeometry(tailCurve, 20, 0.15, 8, false);
        const tailMesh = new THREE.Mesh(tailGeometry, bodyMaterial);
        tailMesh.castShadow = true;
        seahorseGroup.add(tailMesh);

        // 3. Head Details (Snout and Eyes)
        const snoutGeo = new THREE.ConeGeometry(0.15, 0.6, 8);
        const snout = new THREE.Mesh(snoutGeo, bodyMaterial);
        snout.position.set(-0.8, 1.5, 0);
        snout.rotation.z = Math.PI / 2;
        seahorseGroup.add(snout);

        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.3, 1.65, 0.2);
        seahorseGroup.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(-0.3, 1.65, -0.2);
        seahorseGroup.add(rightEye);

        // 4. Thorns (Spikes)
        // We sample points along the body curve and add cones
        const thornGeo = new THREE.ConeGeometry(0.05, 0.3, 4);

        // Add thorns along the main body
        for (let i = 0; i < 15; i++) {
            const t = i / 15;
            const point = bodyCurve.getPointAt(t);

            // Skip the very top (head) and very bottom (tail) for thorns
            if (t > 0.8 || t < 0.1) continue;

            // Create a thorn
            const thorn = new THREE.Mesh(thornGeo, thornMaterial);
            thorn.position.copy(point);

            // Offset slightly to the side
            thorn.position.x += 0.25; 

            // Rotate to point outwards
            thorn.rotation.z = -Math.PI / 2;
            thorn.rotation.y = Math.random() * Math.PI; // Random rotation around body

            seahorseGroup.add(thorn);
        }

        // Add dorsal fin (simple flat shape)
        const finShape = new THREE.Shape();
        finShape.moveTo(0, 0);
        finShape.quadraticCurveTo(0.2, 0.5, 0, 1);
        finShape.quadraticCurveTo(-0.1, 0.5, 0, 0);
        const finGeo = new THREE.ShapeGeometry(finShape);
        const finMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, side: THREE.DoubleSide });
        const fin = new THREE.Mesh(finGeo, finMat);
        fin.position.set(0.2, 0.5, 0.25);
        fin.rotation.x = -0.2;
        seahorseGroup.add(fin);

        scene.add(seahorseGroup);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating motion
            const time = Date.now() * 0.001;
            seahorseGroup.position.y = Math.sin(time) * 0.2;
            seahorseGroup.rotation.z = Math.sin(time * 0.5) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
