    dirMat
  );
  tip.rotation.z = dir === 'W' ? Math.PI / 2 : -Math.PI / 2;
  tip.position.x = dir === 'W' ? -0.35 : 0.35;
  group.add(tip);

  group.position.set(0, 4.5, 0);
  group.rotation.y = angle;
  return group;
}

