        });

        const dialMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.5,
        });

        const redNeedleMaterial = new THREE.MeshStandardMaterial({
            color: 0xcc0000,
            metalness: 0.2,
            roughness: 0.4,
        });

