        needleGroup.position.set(0, 0.43, 2);
        lidGroup.add(needleGroup);

        // Red half (North)
        const redNeedleGeo = new THREE.BoxGeometry(0.15, 0.02, 1.6);
        const redNeedle = new THREE.Mesh(redNeedleGeo, redNeedleMaterial);
        redNeedle.position.z = 0.8; // Offset to center
        needleGroup.add(redNeedle);

        // Black half (South)
        const blackNeedleGeo = new THREE.BoxGeometry(0.15, 0.02, 1.6);
        const blackNeedle = new THREE.Mesh(blackNeedleGeo, blackNeedleMaterial);
        blackNeedle.position.z = -0.8;
        needleGroup.add(blackNeedle);

        // Center Pin
        const pinGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.1, 16);
        const pin = new THREE.Mesh(pinGeo, brassMaterial);
        pin.rotation.x = Math.PI / 2;
        needleGroup.add(pin);

        // 6. Top Ring (for chain)
        const topRingGeo = new THREE.TorusGeometry(0.3, 0.05, 16, 32);
        const topRing = new THREE.Mesh(topRingGeo, brassMaterial);
        topRing.position.set(0, 0.5, 2);
        topRing.rotation.x = Math.PI / 2;
        lidGroup.add(topRing);

        // 7. Base Details (Rim)
        const rimGeo = new THREE.TorusGeometry(2, 0.1, 16, 32);
        const rim = new THREE.Mesh(rimGeo, darkBrassMaterial);
        rim.rotation.x = Math.PI / 2;
        rim.position.y = 0;
        compassGroup.add(rim);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Subtle needle wobble
            const time = Date.now() * 0.001;
            needleGroup.rotation.y = Math.sin(time) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
