**What's inside:**

- **Outer glass shell** — a `TorusKnotGeometry` with `MeshPhysicalMaterial` using `transmission`, `ior: 1.52`, `iridescence`, and `clearcoat` for realistic glass
- **Inner colored core** — a smaller, tinted torus knot nested inside with blue attenuation color for depth
- **Filament thread** — a thin innermost swirl with emissive glow
- **40 floating glass shards** — orbiting micro-marbles with individual rotation and bobbing
- **Reflective ground plane** — dark metallic floor for ground reflections
- **Dynamic colored lights** — two point lights orbit the scene (blue + pink) for shifting caustics
- **Bloom post-processing** — `UnrealBloomPass` adds a soft glow to specular highlights
- **OrbitControls** — drag to rotate, scroll to zoom

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Brass Keyhole Cover</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        scene.fog = new THREE.Fog(0x111111, 5, 15);

        // Camera
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 6);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 2);
        dirLight.position.set(5, 5, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 1, 10);
        pointLight.position.set(-2, 2, 3);
        scene.add(pointLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642, // Brass color
            metalness: 0.8,
            roughness: 0.2,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.5,
            roughness: 0.7,
        });

        // Geometry Construction
        // 1. Create the Keyhole Shape (Hole)
        const keyholeShape = new THREE.Shape();

        // Keyhole parameters
        const circleRadius = 0.6;
        const circleCenterY = 0.5;
        const slotWidth = 0.3;
        const slotBottomY = -1.0;
        const slotRadius = slotWidth / 2;

        // Start at top of the circle part
        keyholeShape.moveTo(0, circleCenterY + circleRadius);

        // Draw the top circle arc (right side to left side, counter-clockwise)
        // Start angle 0 (right), end angle PI (left)
        keyholeShape.absarc(0, circleCenterY, circleRadius, 0, Math.PI, false);

        // Line down the left side of the slot
        keyholeShape.lineTo(-slotRadius, slotBottomY);

        // Draw the bottom semi-circle of the slot (left to right, clockwise)
        // Start angle PI (left), end angle 0 (right)
        keyholeShape.absarc(0, slotBottomY, slotRadius, Math.PI, 0, true);

        // Line up the right side of the slot
        keyholeShape.lineTo(circleRadius, circleCenterY);

        // Close the shape (implicitly connects back to start)
        keyholeShape.closePath();

        // 2. Create the Plate Shape (Outer)
        const plateShape = new THREE.Shape();
        const plateRadius = 2.0;
        plateShape.absarc(0, 0, plateRadius, 0, Math.PI * 2, false);

        // Add the keyhole as a hole in the plate
        plateShape.holes.push(keyholeShape);

        // 3. Extrude the plate
        const extrudeSettings = {
            steps: 1,
            depth: 0.2, // Thickness of the cover
            bevelEnabled: true,
            bevelThickness: 0.05,
            bevelSize: 0.05,
            bevelSegments: 3
        };

        const plateGeometry = new THREE.ExtrudeGeometry(plateShape, extrudeSettings);
        // Center the geometry
        plateGeometry.center();

        const plateMesh = new THREE.Mesh(plateGeometry, brassMaterial);
        plateMesh.castShadow = true;
        plateMesh.receiveShadow = true;
        scene.add(plateMesh);

        // 4. Add a "hole" visual (dark cylinder inside) to simulate depth
        // We create a cylinder that fits inside the keyhole shape roughly
        // Since exact boolean subtraction is hard without CSG, we approximate the hole depth
        // by placing a dark cylinder behind the plate where the hole is.

        // Actually, a better way for the "hole" look is to just rely on the lighting 
        // and maybe add a dark plane behind it, or construct the hole geometry.
        // Let's construct a simple "hole" geometry using the keyhole shape extruded backwards?
        // No, let's just add a dark cylinder for the main shaft and a box for the slot.

        // Shaft hole
        const shaftHoleGeo = new THREE.CylinderGeometry(circleRadius - 0.05, circleRadius - 0.05, 0.5, 32);
        const shaftHoleMesh = new THREE.Mesh(shaftHoleGeo, darkMetalMaterial);
        shaftHoleMesh.position.set(0, circleCenterY, -0.1); // Slightly behind plate center
        scene.add(shaftHoleMesh);

        // Slot hole
        const slotHoleGeo = new THREE.BoxGeometry(slotWidth - 0.05, (slotBottomY - (circleCenterY - circleRadius)) + slotRadius, 0.5);
        // Adjust height to match the slot length roughly
        const slotHeight = Math.abs(slotBottomY - (circleCenterY - circleRadius)) + slotRadius;
        const slotHoleGeo2 = new THREE.BoxGeometry(slotWidth - 0.05, slotHeight, 0.5);
        const slotHoleMesh = new THREE.Mesh(slotHoleGeo2, darkMetalMaterial);
        // Position: Center of slot. 
        // Top of slot is roughly circleCenterY - circleRadius. Bottom is slotBottomY - slotRadius.
        const slotCenterY = ( (circleCenterY - circleRadius) + (slotBottomY - slotRadius) ) / 2;
        slotHoleMesh.position.set(0, slotCenterY, -0.1);
        scene.add(slotHoleMesh);

        // Add a rim/edge detail
        const rimGeo = new THREE.TorusGeometry(plateRadius, 0.05, 16, 100);
        const rimMesh = new THREE.Mesh(rimGeo, brassMaterial);
        rimMesh.rotation.x = Math.PI / 2;
        rimMesh.position.z = 0.1; // Slightly in front
        scene.add(rimMesh);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            plateMesh.rotation.y += 0.005;
            plateMesh.rotation.z = Math.sin(Date.now() * 0.001) * 0.05;

            // Sync children
            shaftHoleMesh.rotation.y = plateMesh.rotation.y;
            slotHoleMesh.rotation.y = plateMesh.rotation.y;
            rimMesh.rotation.y = plateMesh.rotation.y;
            rimMesh.rotation.z = plateMesh.rotation.z;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
