position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
color: #d4af37; font-family: 'Georgia', serif; font-size: 14px;
text-align: center; pointer-events: none; text-shadow: 0 1px 4px rgba(0,0,0,.8);
opacity: .7;
}
</style>
</head>
<body>
<div id="info">Brass Sundial · Drag to orbit · Scroll to zoom</div>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(3, 4, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// Environment for metallic reflections
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.1, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2.1;
controls.minDistance = 2;
controls.maxDistance = 12;

// ── Materials ──
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xc4a35a,
  metalness: 0.92,
  roughness: 0.22,
  envMapIntensity: 1.5,
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8a7033,
  metalness: 0.9,
  roughness: 0.3,
  envMapIntensity: 1.2,
});

const groundMat = new THREE.MeshStandardMaterial({
  color: 0x2a2a3a,
  metalness: 0.0,
  roughness: 0.9,
});

// ── Stone Ground ──
const ground = new THREE.Mesh(new THREE.PlaneGeometry(30, 30), groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// ── Sundial Group ──
const sundial = new THREE.Group();
scene.add(sundial);

// ── Base Plate (thick disc) ──
const plateGeo = new THREE.CylinderGeometry(1.6, 1.7, 0.08, 64);
const plate = new THREE.Mesh(plateGeo, brassMat);
plate.position.y = 0.04;
plate.castShadow = true;
plate.receiveShadow = true;
sundial.add(plate);

// ── Raised rim ──
const rimGeo = new THREE.TorusGeometry(1.65, 0.04, 8, 64);
const rim = new THREE.Mesh(rimGeo, darkBrassMat);
rim.rotation.x = -Math.PI / 2;
rim.position.y = 0.082;
sundial.add(rim);

// ── Decorative outer ring ──
const outerRingGeo = new THREE.TorusGeometry(1.55, 0.025, 8, 64);
const outerRing = new THREE.Mesh(outerRingGeo, darkBrassMat);
outerRing.rotation.x = -Math.PI / 2;
outerRing.position.y = 0.083;
sundial.add(outerRing);

// ── Center rose decoration ──
const roseGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.02, 32);
const rose = new THREE.Mesh(roseGeo, darkBrassMat);
rose.position.y = 0.09;
sundial.add(rose);

// ── Hour lines ──
const hourLineMat = new THREE.MeshStandardMaterial({
  color: 0x4a3a1a,
  metalness: 0.7,
  roughness: 0.4,
});

const hours = 12;
for (let i = 0; i < hours; i++) {
  const angle = (i / hours) * Math.PI * 2;
  const isMain = i % 3 === 0; // longer lines at 12, 3, 6, 9
  const innerR = 0.2;
  const outerR = isMain ? 1.35 : 1.15;
  const thickness = isMain ? 0.025 : 0.012;

  const lineGeo = new THREE.BoxGeometry(thickness, 0.005, outerR - innerR);
  const line = new THREE.Mesh(lineGeo, hourLineMat);
  line.position.y = 0.084;
  line.rotation.y = angle;
  line.position.x = Math.sin(angle) * (innerR + outerR) / 2;
  line.position.z = Math.cos(angle) * (innerR + outerR) / 2;
  sundial.add(line);

  // Hour dots on outer ring
  const dotGeo = new THREE.SphereGeometry(0.025, 8, 8);
  const dot = new THREE.Mesh(dotGeo, brassMat);
  dot.position.set(
    Math.sin(angle) * (outerR + 0.05),
    0.084,
    Math.cos(angle) * (outerR + 0.05)
  );
  sundial.add(dot);
}

// ── Minute tick marks ──
for (let i = 0; i < 60; i++) {
  if (i % 5 === 0) continue;
  const angle = (i / 60) * Math.PI * 2;
  const tickGeo = new THREE.BoxGeometry(0.008, 0.003, 0.04);
  const tick = new THREE.Mesh(tickGeo, hourLineMat);
  tick.position.y = 0.084;
  tick.rotation.y = angle;
  const r = 1.28;
  tick.position.set(Math.sin(angle) * r, 0.084, Math.cos(angle) * r);
  sundial.add(tick);
}

// ── Gnomon (triangular wedge) ──
const gnomonGroup = new THREE.Group();
gnomonGroup.position.y = 0.082;
sundial.add(gnomonGroup);

// Gnomon angle ~ 40° (approximate latitude)
const gnomonAngle = 40 * Math.PI / 180;

const gnomonShape = new THREE.Shape();
gnomonShape.moveTo(0, 0);
gnomonShape.lineTo(0.03, 0);
gnomonShape.lineTo(0.03, 1.2);
gnomonShape.lineTo(0.005, 1.2);
gnomonShape.lineTo(0, 0.35);
gnomonShape.lineTo(0, 0);

const gnomonExtrudeSettings = { depth: 0.06, bevelEnabled: true, bevelThickness: 0.005, bevelSize: 0.005, bevelSegments: 2 };
const gnomonGeo = new THREE.ExtrudeGeometry(gnomonShape, gnomonExtrudeSettings);
const gnomon = new THREE.Mesh(gnomonGeo, brassMat);
gnomon.rotation.x = -gnomonAngle;
gnomon.position.set(-0.015, 0, -0.03);
gnomon.castShadow = true;
gnomonGroup.add(gnomon);

// Counterweight / base block for gnomon
const gnomonBaseGeo = new THREE.BoxGeometry(0.12, 0.06, 0.12);
const gnomonBase = new THREE.Mesh(gnomonBaseGeo, darkBrassMat);
gnomonBase.position.y = 0.03;
gnomonGroup.add(gnomonBase);

// ── Decorative pillar on top of gnomon ──
const pillarGeo = new THREE.CylinderGeometry(0.03, 0.035, 0.12, 12);
const pillar = new THREE.Mesh(pillarGeo, brassMat);
pillar.position.set(0, 0.15, 0);
pillar.castShadow = true;
sundial.add(pillar);

const finialGeo = new THREE.SphereGeometry(0.04, 16, 16);
const finial = new THREE.Mesh(finialGeo, brassMat);
finial.position.set(0, 0.23, 0);
finial.castShadow = true;
sundial.add(finial);

// ── Inscription ring (decorative text-like bumps) ──
for (let i = 0; i < 48; i++) {
  const angle = (i / 48) * Math.PI * 2;
  const bumpGeo = new THREE.SphereGeometry(0.012, 6, 6);
  const bump = new THREE.Mesh(bumpGeo, darkBrassMat);
  bump.position.set(
    Math.sin(angle) * 1.42,
    0.084,
    Math.cos(angle) * 1.42
  );
  sundial.add(bump);
}

// ── Lighting ──
// Sun-like directional light
const sunLight = new THREE.DirectionalLight(0xfff4e0, 3.5);
sunLight.position.set(3, 5, 2);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 20;
sunLight.shadow.camera.left = -3;
sunLight.shadow.camera.right = 3;
sunLight.shadow.camera.top = 3;
sunLight.shadow.camera.bottom = -3;
sunLight.shadow.bias = -0.0005;
sunLight.shadow.normalBias = 0.02;
scene.add(sunLight);

// Fill light
const fillLight = new THREE.DirectionalLight(0x8899bb, 0.6);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

// Warm rim light
const rimLight = new THREE.PointLight(0xffcc88, 1.5, 10);
rimLight.position.set(-2, 3, 1);
scene.add(rimLight);

// Subtle ambient
scene.add(new THREE.AmbientLight(0x303050, 0.4));

// ── Animate sun to show shadow movement ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Slow sun rotation for dramatic shadow sweep
  const sunAngle = t * 0.15;
  sunLight.position.set(
    Math.cos(sunAngle) * 5,
    4 + Math.sin(sunAngle * 0.5) * 1.5,
    Math.sin(sunAngle) * 3
  );

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This single-file demo features:

- **Brass materials** — high metalness/low roughness `MeshStandardMaterial` with warm gold tones, plus a darker brass variant for contrast elements
- **Detailed sundial plate** — thick cylindrical disc with a raised torus rim, decorative outer ring, center rose, and inscription bumps
- **12 hour lines** — longer at cardinal positions (12/3/6/9), with 60 minute tick marks and brass dots
- **Gnomon** — an extruded triangular wedge tilted at ~40° (latitude angle), with a decorative pillar and spherical finial on top
- **Realistic shadows** — PCF soft shadow mapping from a directional "sun" light that slowly orbits, sweeping the gnomon's shadow across the hour lines
- **Three-point lighting** — warm key sun, cool fill, and rim light for dramatic brass reflections
- **Environment reflections** — `RoomEnvironment` via PMREM for convincing metallic highlights
- **OrbitControls** — drag to rotate, scroll to zoom, with damping and angle limits

