});

const brassPolished = new THREE.MeshStandardMaterial({
  color: 0xd4a843,
  metalness: 0.95,
  roughness: 0.1
});

// ── Environment (simple gradient sphere) ──
const envGeo = new THREE.SphereGeometry(30, 32, 32);
const envMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  uniforms: {
    colorTop: { value: new THREE.Color(0x2a1a0e) },
    colorBottom: { value: new THREE.Color(0x0a0a14) }
  },
  vertexShader: `varying vec3 vWorldPos;
    void main(){ vWorldPos = (modelMatrix * vec4(position,1.0)).xyz; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
  fragmentShader: `uniform vec3 colorTop, colorBottom; varying vec3 vWorldPos;
    void main(){ float t = smoothstep(-15.0, 15.0, vWorldPos.y); gl_FragColor = vec4(mix(colorBottom, colorTop, t), 1.0); }`
});
scene.add(new THREE.Mesh(envGeo, envMat));

// ── Lights ──
const keyLight = new THREE.DirectionalLight(0xffeedd, 3.5);
keyLight.position.set(5, 8, 4);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 1.0);
fillLight.position.set(-4, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffcc88, 2.0);
rimLight.position.set(-3, 2, 5);
scene.add(rimLight);

const spot = new THREE.SpotLight(0xffeebb, 5, 20, Math.PI / 6, 0.5);
spot.position.set(1, 6, 2);
spot.target.position.set(0, 0, 0);
scene.add(spot, spot.target);

scene.add(new THREE.AmbientLight(0x332211, 0.5));

// ── Sextant Arm Group ──
const arm = new THREE.Group();
scene.add(arm);

// Pivot point at origin — arm extends along +X
const ARM_LEN = 4.5;
const ARM_W = 0.38;
const ARM_THICK = 0.08;

// ── Main arm body (tapered) ──
const mainArmShape = new THREE.Shape();
mainArmShape.moveTo(0, -ARM_W / 2);
mainArmShape.lineTo(ARM_LEN, -ARM_W / 2 + 0.03);
mainArmShape.lineTo(ARM_LEN, ARM_W / 2 - 0.03);
mainArmShape.lineTo(0, ARM_W / 2);

const extrudeSettings = { depth: ARM_THICK, bevelEnabled: true, bevelThickness: 0.015, bevelSize: 0.015, bevelSegments: 3 };
const mainArmGeo = new THREE.ExtrudeGeometry(mainArmShape, extrudeSettings);
mainArmGeo.center();
const mainArm = new THREE.Mesh(mainArmGeo, brass);
mainArm.castShadow = true;
mainArm.position.set(ARM_LEN / 2 - 0.5, 0, -ARM_THICK / 2 - 0.015);
arm.add(mainArm);

// ── Edge bevel lines (decorative grooves) ──
function addGroove(y, width, xStart, xEnd) {
  const grooveShape = new THREE.Shape();
  grooveShape.moveTo(xStart, y - width / 2);
  grooveShape.lineTo(xEnd, y - width / 2);
  grooveShape.lineTo(xEnd, y + width / 2);
  grooveShape.lineTo(xStart, y + width / 2);

  const grooveGeo = new THREE.ExtrudeGeometry(grooveShape, {
    depth: 0.008, bevelEnabled: true, bevelThickness: 0.004, bevelSize: 0.004, bevelSegments: 2
  });
  const groove = new THREE.Mesh(grooveGeo, brassDark);
  groove.position.set(0, 0, ARM_THICK / 2 + 0.008);
  arm.add(groove);
}

addGroove(0, ARM_W * 0.85, 0.3, ARM_LEN - 0.3);
addGroove(0, ARM_W * 0.6, 0.5, ARM_LEN - 0.5);

// ── Degree markings along the edge ──
for (let i = 0; i <= 60; i++) {
  const t = 0.3 + (i / 60) * (ARM_LEN - 0.8);
  const isMajor = i % 10 === 0;
  const isMid = i % 5 === 0;
  const h = isMajor ? 0.06 : isMid ? 0.04 : 0.025;
  const w = 0.008;

  const markShape = new THREE.Shape();
  markShape.moveTo(t, ARM_W / 2 - 0.02);
  markShape.lineTo(t, ARM_W / 2 - 0.02 + h);
  markShape.lineTo(t + w, ARM_W / 2 - 0.02 + h);
  markShape.lineTo(t + w, ARM_W / 2 - 0.02);

  const markGeo = new THREE.ExtrudeGeometry(markShape, {
    depth: 0.006, bevelEnabled: false
  });
  const mark = new THREE.Mesh(markGeo, brassDark);
  mark.position.z = ARM_THICK / 2 + 0.01;
  arm.add(mark);
}

// ── Pivot bearing (circular at base) ──
const pivotGeo = new THREE.CylinderGeometry(0.22, 0.25, ARM_THICK + 0.06, 32);
const pivot = new THREE.Mesh(pivotGeo, brassPolished);
pivot.rotation.x = Math.PI / 2;
pivot.position.set(-0.15, 0, 0);
pivot.castShadow = true;
arm.add(pivot);

// Pivot ring
const ringGeo = new THREE.TorusGeometry(0.28, 0.025, 16, 48);
const ring = new THREE.Mesh(ringGeo, brassPolished);
ring.position.set(-0.15, 0, ARM_THICK / 2 + 0.04);
arm.add(ring);

// ── Micrometer drum assembly at the end ──
const drumX = ARM_LEN + 0.15;

// Drum cylinder
const drumGeo = new THREE.CylinderGeometry(0.18, 0.18, 0.55, 48);
const drum = new THREE.Mesh(drumGeo, brassPolished);
drum.rotation.z = Math.PI / 2;
drum.position.set(drumX, 0, 0);
drum.castShadow = true;
arm.add(drum);

// Drum end caps
const capGeo = new THREE.CylinderGeometry(0.19, 0.19, 0.03, 48);
for (const z of [-0.29, 0.29]) {
  const cap = new THREE.Mesh(capGeo, brass);
  cap.rotation.z = Math.PI / 2;
  cap.position.set(drumX, 0, z);
  arm.add(cap);
}

// Drum ridges (knurling)
for (let i = 0; i < 36; i++) {
  const angle = (i / 36) * Math.PI * 2;
  const ridgeGeo = new THREE.BoxGeometry(0.012, 0.46, 0.012);
  const ridge = new THREE.Mesh(ridgeGeo, brassDark);
  ridge.position.set(
    drumX,
    Math.cos(angle) * 0.185,
    Math.sin(angle) * 0.185
  );
  ridge.rotation.x = angle;
  arm.add(ridge);
}

// ── Vernier scale plate on drum ──
const vernierGeo = new THREE.BoxGeometry(0.08, 0.12, 0.01);
const vernier = new THREE.Mesh(vernierGeo, brassPolished);
vernier.position.set(drumX + 0.3, 0, 0);
arm.add(vernier);

// ── Sight / telescope bracket at end ──
const bracketGeo = new THREE.BoxGeometry(0.06, 0.35, 0.06);
const bracket = new THREE.Mesh(bracketGeo, brass);
bracket.position.set(ARM_LEN + 0.55, 0.15, 0);
bracket.castShadow = true;
arm.add(bracket);

// Top sight
const sightGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.08, 16);
const sight = new THREE.Mesh(sightGeo, brassPolished);
sight.position.set(ARM_LEN + 0.55, 0.37, 0);
arm.add(sight);

// ── Arc (partial circle behind the arm) ──
const arcCurve = new THREE.EllipseCurve(0, 0, 5.5, 5.5, -Math.PI * 0.35, Math.PI * 0.35, false, 0);
const arcPoints = arcCurve.getPoints(80);
const arcGeo2 = new THREE.BufferGeometry().setFromPoints(arcPoints);
const arcMat = new THREE.LineBasicMaterial({ color: 0xc4982d, linewidth: 1 });
const arcLine = new THREE.Line(arcGeo2, arcMat);
arcLine.position.z = -0.15;
scene.add(arcLine);

// Arc tick marks
for (let deg = -60; deg <= 60; deg += 1) {
  const rad = (deg * Math.PI) / 180;
  const innerR = deg % 5 === 0 ? 5.3 : 5.4;
  const outerR = 5.6;
  const tickGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(Math.cos(rad) * innerR, Math.sin(rad) * innerR, -0.15),
    new THREE.Vector3(Math.cos(rad) * outerR, Math.sin(rad) * outerR, -0.15)
  ]);
  const tick = new THREE.Line(tickGeo, new THREE.LineBasicMaterial({ color: 0xc4982d }));
  scene.add(tick);
}

// ── Decorative inlay (engraved line) ──
const inlayCurve = new THREE.QuadraticBezierCurve3(
  new THREE.Vector3(0.8, ARM_W / 2 - 0.05, ARM_THICK / 2 + 0.012),
  new THREE.Vector3(ARM_LEN / 2, ARM_W / 2 + 0.08, ARM_THICK / 2 + 0.012),
  new THREE.Vector3(ARM_LEN - 0.8, ARM_W / 2 - 0.05, ARM_THICK / 2 + 0.012)
);
const inlayPts = inlayCurve.getPoints(40);
const inlayGeo = new THREE.BufferGeometry().setFromPoints(inlayPts);
