<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

/* ── Scene ─────────────────────────────────────────── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a14);
scene.fog = new THREE.FogExp2(0x0a0a14, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0, 0);

/* ── Post-processing (bloom) ───────────────────────── */
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.4, 0.6, 0.2
);
composer.addPass(bloom);

/* ── Lights ────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0x334466, 0.6));

const sun = new THREE.DirectionalLight(0xffffff, 3);
sun.position.set(-6, 4, 2);
scene.add(sun);

const fill = new THREE.DirectionalLight(0x6688cc, 0.4);
fill.position.set(4, -2, -3);
scene.add(fill);

/* ── Glass Prism ───────────────────────────────────── */
const triShape = new THREE.Shape();
const s = 1.8;
triShape.moveTo(0, s * 0.866);
triShape.lineTo(-s, -s * 0.433);
triShape.lineTo(s, -s * 0.433);
triShape.closePath();

const extrudeSettings = { depth: 3.6, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.04, bevelSegments: 3 };
const prismGeo = new THREE.ExtrudeGeometry(triShape, extrudeSettings);
prismGeo.center();

const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.96,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.05,
  ior: 2.4,
  thickness: 1.5,
  specularIntensity: 1,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1,
  clearcoat: 1,
  clearcoatRoughness: 0,
  side: THREE.DoubleSide,
});

// Simple env map so glass has something to refract
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x111122);
const envLight1 = new THREE.DirectionalLight(0xffffff, 3);
envLight1.position.set(-5, 3, 2);
envScene.add(envLight1);
const envLight2 = new THREE.DirectionalLight(0x8888ff, 2);
envLight2.position.set(5, -2, -3);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene, 0.04);
scene.environment = envRT.texture;

const prism = new THREE.Mesh(prismGeo, glassMat);
prism.rotation.y = Math.PI * 0.1;
scene.add(prism);

/* ── Helper: glowing beam cylinder ─────────────────── */
function makeBeam(color, radius = 0.03) {
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 8);
  geo.translate(0, 0.5, 0);
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.85,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });
  return new THREE.Mesh(geo, mat);
}

/* ── White light beam (input) ──────────────────────── */
const whiteBeam = makeBeam(0xffffff, 0.06);
whiteBeam.position.set(-6, 1.2, 0);
whiteBeam.rotation.z = Math.PI / 2 - 0.28;
whiteBeam.scale.set(1, 1, 8);
scene.add(whiteBeam);

// Bright source sphere
const source = new THREE.Mesh(
  new THREE.SphereGeometry(0.15, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0xffffff })
);
source.position.set(-7, 1.55, 0);
scene.add(source);

/* ── Rainbow beams (output) ────────────────────────── */
const rainbowColors = [
  0xff2200, // red
  0xff8800, // orange
  0xffdd00, // yellow
  0x22cc44, // green
  0x2266ff, // blue
  0x4400cc, // indigo
  0xaa22ff, // violet
];

const beamAngle = 0.28; // roughly the prism entry angle
const spread = 0.18;    // total dispersion spread

const beams = [];
rainbowColors.forEach((c, i) => {
  const b = makeBeam(c, 0.025);
  const angle = beamAngle + (spread * (i / (rainbowColors.length - 1) - 0.5));
  // Position at prism exit face
  const exitX = 1.0;
  const exitY = -0.3;
  b.position.set(exitX, exitY, 0);
  b.rotation.z = -angle;
  b.scale.set(1, 1, 7);
  scene.add(b);
  beams.push(b);
});

/* ── Rainbow projection screen ─────────────────────── */
const screenGeo = new THREE.PlaneGeometry(6, 3.5, 1, 1);
const screenMat = new THREE.ShaderMaterial({
  transparent: true, depthWrite: false,
  uniforms: { uTime: { value: 0 } },
  vertexShader: `
    varying vec2 vUv;
    void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
  `,
  fragmentShader: `
    uniform float uTime;
    varying vec2 vUv;
    void main(){
      float t = vUv.x;
      vec3 r = vec3(1.,0.13,0.);
      vec3 o = vec3(1.,0.53,0.);
      vec3 y = vec3(1.,0.87,0.);
      vec3 g = vec3(0.13,0.8,0.27);
      vec3 b = vec3(0.13,0.4,1.);
      vec3 i = vec3(0.27,0.,0.8);
      vec3 v = vec3(0.67,0.13,1.);
      vec3 col;
      float band = 1./7.;
      if(t<band) col=mix(r,o,t/band);
      else if(t<band*2.) col=mix(o,y,(t-band)/band);
      else if(t<band*3.) col=mix(y,g,(t-band*2.)/band);
      else if(t<band*4.) col=mix(g,b,(t-band*3.)/band);
      else if(t<band*5.) col=mix(b,i,(t-band*4.)/band);
      else if(t<band*6.) col=mix(i,v,(t-band*5.)/band);
      else col=v;
      float falloff = smoothstep(0.,0.08,t) * smoothstep(1.,0.92,t);
      float glow = exp(-pow((t-0.5)*3.,2.)*0.8);
      float pulse = 0.85 + 0.15*sin(uTime*1.5 + t*12.);
      float alpha = (falloff * 0.7 + glow * 0.3) * pulse;
      gl_FragColor = vec4(col * 1.6, alpha);
    }
  `
});
const screen = new THREE.Mesh(screenGeo, screenMat);
screen.position.set(5.5, 0.2, 0);
screen.rotation.y = -0.15;
scene.add(screen);

/* ── Floating particles ────────────────────────────── */
const pCount = 300;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(pCount * 3);
const pCol = new Float32Array(pCount * 3);
for (let i = 0; i < pCount; i++) {
  pPos[i*3]   = (Math.random()-0.5)*20;
  pPos[i*3+1] = (Math.random()-0.5)*10;
  pPos[i*3+2] = (Math.random()-0.5)*10;
  const c = new THREE.Color().setHSL(0.55 + Math.random()*0.15, 0.8, 0.6);
  pCol[i*3]=c.r; pCol[i*3+1]=c.g; pCol[i*3+2]=c.b;
}
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos,3));
pGeo.setAttribute('color', new THREE.BufferAttribute(pCol,3));
const pMat = new THREE.PointsMaterial({ size:0.04, vertexColors:true, transparent:true, opacity:0.6, blending:THREE.AdditiveBlending, depthWrite:false });
const particles = new THREE.Points(pGeo, pMat);
scene.add(particles);

/* ── Ground plane ──────────────────────────────────── */
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x0c0c18, roughness: 0.8, metalness: 0.2 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -2;
scene.add(ground);

/* ── Animation ─────────────────────────────────────── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle prism rotation
  prism.rotation.y = Math.PI * 0.1 + Math.sin(t * 0.3) * 0.15;

  // Animate screen shader
  screenMat.uniforms.uTime.value = t;

  // Float particles
  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < pCount; i++) {
    pos[i*3+1] += Math.sin(t + i) * 0.001;
  }
  particles.geometry.attributes.position.needsUpdate = true;
  particles.rotation.y = t * 0.02;

  // Subtle beam shimmer
  beams.forEach((b, i) => {
    b.material.opacity = 0.6 + 0.3 * Math.sin(t * 2 + i * 0.8);
  });
  whiteBeam.material.opacity = 0.7 + 0.2 * Math.sin(t * 1.8);

  controls.update();
  composer.render();
}

animate();

/* ── Resize ────────────────────────────────────────── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What's happening in the scene

| Element | Detail |
|---|---|
| **Glass prism** | Extruded triangle with `MeshPhysicalMaterial` — high IOR (2.4), 96% transmission, clearcoat — for realistic glass refraction |
| **White light beam** | Additive-blended cylinder entering the prism from the left, with a glowing source sphere |
| **Rainbow beams** | 7 diverging colored cylinders (ROYGBIV) exiting the prism at spread angles simulating dispersion |
| **Rainbow screen** | A plane with a custom GLSL fragment shader that blends the 7 spectral colors with a Gaussian glow and gentle pulse animation |
| **Bloom** | `UnrealBloomPass` post-processing gives all emissive/glowing elements a soft halo |
| **Particles** | 300 floating blue-tinted points with additive blending for atmosphere |
| **Controls** | `OrbitControls` — drag to rotate, scroll to zoom |

