// Finder brackets
[-0.15, 0.15].forEach(x => {
  const bracket = new THREE.Mesh(
    new THREE.BoxGeometry(0.02, 0.08, 0.06),
    darkBrassMat
  );
  bracket.position.set(x, -0.04, 0);
