    const d = flake.userData;
    flake.position.y -= d.speed * 0.005;
    flake.position.x += Math.sin(t * d.wobbleSpeed + d.phase) * d.wobbleAmp * 0.003;
    flake.position.z += Math.cos(t * d.wobbleSpeed + d.phase) * d.wobbleAmp * 0.003;

    // Reset when below
    if (flake.position.y < -1.7) {
      flake.position.y = 1.5 + Math.random() * 0.5;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const r = Math.random() * 1.5;
      flake.position.x = r * Math.sin(phi) * Math.cos(theta);
      flake.position.z = r * Math.sin(phi) * Math.sin(theta);
    }
  });

  // Star glow
  starMat.emissiveIntensity = 0.5 + Math.sin(t * 2) * 0.3;
  star.rotation.y = t * 0.5;

  // Gentle globe rotation
  globeGroup.rotation.y = Math.sin(t * 0.15) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's included:**

- **Glass sphere** — `MeshPhysicalMaterial` with `transmission: 0.95`, IOR 1.52 (real glass), and a procedural environment map for realistic reflections/refractions
- **Decorative base** — Stacked cylinders with a warm wood tone, gold metallic rings, and a polished collar where the glass meets the stand
- **Christmas tree** — Layered cones with a trunk, glowing star on top, and colored ornaments
- **200 snowflakes** — Tiny spheres that gently fall and wobble inside the globe, resetting when they hit the bottom
- **Snow ground** — A curved white base inside the globe
- **OrbitControls** — Drag to rotate, scroll to zoom
- **Gentle sway** — The entire globe subtly rocks side to side

