<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RGBELoader } from 'three/addons/loaders/RGBELoader.js';

// ─── Scene Setup ───
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 2.5;
controls.maxDistance = 12;

// ─── Procedural Environment (Studio) ───
function createStudioEnvironment() {
  const pmremGenerator = new THREE.PMREMGenerator(renderer);
  pmremGenerator.compileEquirectangularShader();

  const envScene = new THREE.Scene();

  // Gradient background
  const bgGeo = new THREE.SphereGeometry(50, 32, 32);
  const bgMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    uniforms: {},
    vertexShader: `
      varying vec3 vWorldPos;
      void main() {
        vWorldPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vWorldPos;
      void main() {
        float y = normalize(vWorldPos).y * 0.5 + 0.5;
        vec3 top = vec3(0.05, 0.08, 0.15);
        vec3 mid = vec3(0.15, 0.2, 0.35);
        vec3 bot = vec3(0.02, 0.03, 0.06);
        vec3 col = mix(bot, mid, smoothstep(0.0, 0.5, y));
        col = mix(col, top, smoothstep(0.5, 1.0, y));
        gl_FragColor = vec4(col, 1.0);
      }
    `
  });
  envScene.add(new THREE.Mesh(bgGeo, bgMat));

  // Softbox lights
  const softboxMat = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
  const softboxMat2 = new THREE.MeshBasicMaterial({ color: 0x8899cc, side: THREE.DoubleSide });

  // Top softbox
  const sb1 = new THREE.Mesh(new THREE.PlaneGeometry(8, 4), softboxMat);
  sb1.position.set(0, 8, -2);
  sb1.rotation.x = -Math.PI * 0.35;
  envScene.add(sb1);

  // Left softbox
  const sb2 = new THREE.Mesh(new THREE.PlaneGeometry(6, 5), softboxMat2);
  sb2.position.set(-6, 3, 0);
  sb2.rotation.y = Math.PI * 0.4;
  envScene.add(sb2);

  // Right softbox
  const sb3 = new THREE.Mesh(new THREE.PlaneGeometry(5, 5), softboxMat2);
  sb3.position.set(6, 2, 2);
  sb3.rotation.y = -Math.PI * 0.35;
  envScene.add(sb3);

  // Bottom fill
  const sb4 = new THREE.Mesh(new THREE.PlaneGeometry(10, 6), new THREE.MeshBasicMaterial({
    color: 0x223344, side: THREE.DoubleSide
  }));
  sb4.position.set(0, -5, 0);
  sb4.rotation.x = Math.PI / 2;
  envScene.add(sb4);

  // Small bright accent
  const accent = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 3), new THREE.MeshBasicMaterial({
    color: 0xffeedd, side: THREE.DoubleSide
  }));
  accent.position.set(-2, 5, 4);
  accent.rotation.x = -0.5;
  accent.rotation.z = 0.3;
  envScene.add(accent);

  const envMap = pmremGenerator.fromScene(envScene, 0.04).texture;
  pmremGenerator.dispose();
  envScene.traverse(c => { if (c.geometry) c.geometry.dispose(); if (c.material) { if (c.material.map) c.material.map.dispose(); c.material.dispose(); }});
  return envMap;
}

const envMap = createStudioEnvironment();
scene.environment = envMap;

// ─── Marble Shader Material ───
const marbleVertexShader = `
  uniform float uTime;

  varying vec3 vNormal;
  varying vec3 vWorldPos;
  varying vec3 vViewDir;
  varying vec2 vUv;

  void main() {
    vUv = uv;
    vNormal = normalize(normalMatrix * normal);
    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    vWorldPos = worldPos.xyz;
    vViewDir = normalize(cameraPosition - worldPos.xyz);
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const marbleFragmentShader = `
  precision highp float;

  uniform float uTime;
  uniform vec3 uCamPos;
  uniform sampler2D tEnvMap;

  varying vec3 vNormal;
  varying vec3 vWorldPos;
  varying vec3 vViewDir;
  varying vec2 vUv;

  // ── Noise functions ──
  vec3 mod289(vec3 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
  vec4 mod289(vec4 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
  vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
  vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

  float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod289(i);
    vec4 p = permute(permute(permute(
      i.z + vec4(0.0, i1.z, i2.z, 1.0))
      + i.y + vec4(0.0, i1.y, i2.y, 1.0))
      + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    float n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);
    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
  }

  float fbm(vec3 p) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for (int i = 0; i < 6; i++) {
      val += amp * snoise(p * freq);
      freq *= 2.0;
      amp *= 0.5;
    }
    return val;
  }

  // ── Swirl pattern ──
  float swirl(vec3 p, float speed) {
    float r = length(p.xz);
    float theta = atan(p.z, p.x);

    // Twist along Y axis
    theta += p.y * 3.0 + speed * 0.3;
    r += 0.3 * snoise(vec3(theta * 0.5, p.y * 0.8, speed * 0.1));

    // Convert back
    vec3 p2 = vec3(cos(theta) * r, p.y, sin(theta) * r);

    // Add noise layers
    float n1 = snoise(p2 * 2.0 + speed * 0.05);
    float n2 = snoise(p2 * 4.0 - speed * 0.08 + vec3(0.0, 0.0, 10.0));
    float n3 = snoise(p2 * 1.5 + vec3(n1 * 0.5, n2 * 0.3, speed * 0.02));

