<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.035);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);

// --- Environment for reflections ---
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
const envGeo = new THREE.SphereGeometry(1, 32, 32);
const envMat = new THREE.MeshBasicMaterial({ color: 0x332211, side: THREE.BackSide });
envScene.add(new THREE.Mesh(envGeo, envMat));
const lightPanelGeo = new THREE.PlaneGeometry(4, 4);
const lightPanelMat = new THREE.MeshBasicMaterial({ color: 0xffeedd, side: THREE.DoubleSide });
for (let i = 0; i < 6; i++) {
  const p = new THREE.Mesh(lightPanelGeo, lightPanelMat);
  const angle = (i / 6) * Math.PI * 2;
  p.position.set(Math.cos(angle) * 5, 3 + Math.sin(i * 0.7) * 2, Math.sin(angle) * 5);
  p.lookAt(0, 0, 0);
  envScene.add(p);
}
const envMap = pmrem.fromScene(envScene).texture;
scene.environment = envMap;

// --- Brass material ---
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xc4923e,
  metalness: 0.95,
  roughness: 0.18,
  clearcoat: 0.3,
  clearcoatRoughness: 0.1,
  envMapIntensity: 1.5,
});

const darkBrassMat = new THREE.MeshPhysicalMaterial({
  color: 0x8b6914,
  metalness: 0.9,
  roughness: 0.35,
  clearcoat: 0.2,
  envMapIntensity: 1.0,
});

// --- Key ring torus ---
const ringGeo = new THREE.TorusGeometry(1.8, 0.12, 48, 128);
const ring = new THREE.Mesh(ringGeo, brassMat);
scene.add(ring);

// --- Key geometry builder ---
function createKey(scale = 1) {
  const group = new THREE.Group();

  // Bow (head) - oval ring
  const bowGeo = new THREE.TorusGeometry(0.35 * scale, 0.06 * scale, 16, 32);
  const bow = new THREE.Mesh(bowGeo, brassMat);
  bow.position.y = 0.7 * scale;
  group.add(bow);

  // Bow inner circle (decorative)
  const innerBowGeo = new THREE.TorusGeometry(0.2 * scale, 0.03 * scale, 12, 24);
  const innerBow = new THREE.Mesh(innerBowGeo, brassMat);
  innerBow.position.y = 0.7 * scale;
  group.add(innerBow);

  // Shaft
  const shaftGeo = new THREE.BoxGeometry(0.08 * scale, 1.4 * scale, 0.04 * scale);
  const shaft = new THREE.Mesh(shaftGeo, brassMat);
  shaft.position.y = 0.15 * scale;
  group.add(shaft);

  // Bit (teeth)
  const bitGeo = new THREE.BoxGeometry(0.22 * scale, 0.25 * scale, 0.04 * scale);
  const bit = new THREE.Mesh(bitGeo, brassMat);
  bit.position.set(0.07 * scale, -0.55 * scale, 0);
  group.add(bit);

  // Teeth notches
  const tooth1Geo = new THREE.BoxGeometry(0.07 * scale, 0.08 * scale, 0.05 * scale);
  const t1 = new THREE.Mesh(tooth1Geo, brassMat);
  t1.position.set(0.14 * scale, -0.4 * scale, 0);
  group.add(t1);

  const tooth2Geo = new THREE.BoxGeometry(0.05 * scale, 0.08 * scale, 0.05 * scale);
  const t2 = new THREE.Mesh(tooth2Geo, brassMat);
  t2.position.set(0.12 * scale, -0.5 * scale, 0);
  group.add(t2);

  // Key head decorative hole
  const holeGeo = new THREE.TorusGeometry(0.12 * scale, 0.02 * scale, 8, 16);
  const hole = new THREE.Mesh(holeGeo, darkBrassMat);
  hole.position.y = 0.7 * scale;
  group.add(hole);

  return group;
}

// --- Attach keys to ring ---
const keys = [];
const keyAngles = [0.3, 1.2, 2.1, 3.5, 4.8];
const keyScales = [1.0, 0.85, 1.1, 0.9, 0.95];

keyAngles.forEach((angle, i) => {
  const key = createKey(keyScales[i]);

  // Position on the ring
  const x = Math.cos(angle) * 1.8;
  const y = Math.sin(angle) * 1.8;
  key.position.set(x, y, 0);

  // Rotate key to hang naturally
  key.rotation.z = angle + Math.PI / 2 + (Math.random() - 0.5) * 0.3;
  key.rotation.y = (Math.random() - 0.5) * 0.4;

  // Slight offset from ring surface
  key.position.z = (Math.random() - 0.5) * 0.15;

  scene.add(key);
  keys.push(key);
});

// --- Split ring detail (slight gap to show it's a split ring) ---
const splitGeo = new THREE.TorusGeometry(1.8, 0.12, 48, 8, 0.15);
const splitPiece = new THREE.Mesh(splitGeo, brassMat);
scene.add(splitPiece);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const mainLight = new THREE.DirectionalLight(0xfff4e0, 2.5);
mainLight.position.set(5, 8, 5);
scene.add(mainLight);

const fillLight = new THREE.DirectionalLight(0xc8d8ff, 0.8);
fillLight.position.set(-4, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffaa44, 3, 15);
rimLight.position.set(-3, -2, 4);
scene.add(rimLight);

const bottomLight = new THREE.PointLight(0x4466aa, 1, 10);
bottomLight.position.set(0, -5, -2);
scene.add(bottomLight);

// --- Subtle particles / dust motes ---
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 12;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 12;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 12;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xffddaa,
  size: 0.02,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle ring sway
  ring.rotation.x = Math.sin(t * 0.5) * 0.08;
  ring.rotation.z = Math.cos(t * 0.3) * 0.05;
  splitPiece.rotation.x = ring.rotation.x;
  splitPiece.rotation.z = ring.rotation.z;

  // Keys swing naturally
  keys.forEach((key, i) => {
    const baseAngle = keyAngles[i];
    const sway = Math.sin(t * 0.8 + i * 1.5) * 0.06;
    const swayZ = Math.cos(t * 0.6 + i * 1.2) * 0.04;
    key.rotation.x = sway;
    key.rotation.z = baseAngle + Math.PI / 2 + swayZ;

    // Gentle position wobble
    key.position.z += Math.sin(t * 1.2 + i) * 0.0003;
  });

  // Particles drift
  particles.rotation.y = t * 0.02;
  particles.rotation.x = Math.sin(t * 0.01) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
