  grad.addColorStop(0, '#0a0a2e');
  grad.addColorStop(0.3, '#1a1a4e');
  grad.addColorStop(0.5, '#2a2a5e');
  grad.addColorStop(0.7, '#3a3a6e');
  grad.addColorStop(1, '#1a1a2e');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1024, 512);

  // Some bright spots for reflections
  const spots = [
    { x: 200, y: 100, r: 40, color: 'rgba(255,200,150,0.8)' },
    { x: 600, y: 150, r: 30, color: 'rgba(150,200,255,0.6)' },
    { x: 800, y: 80, r: 50, color: 'rgba(255,255,200,0.7)' },
    { x: 400, y: 200, r: 25, color: 'rgba(200,255,200,0.5)' },
    { x: 100, y: 300, r: 35, color: 'rgba(100,150,255,0.4)' },
    { x: 700, y: 250, r: 20, color: 'rgba(255,150,200,0.5)' },
  ];
  spots.forEach(s => {
    const g = ctx.createRadialGradient(s.x, s.y, 0, s.x, s.y, s.r);
    g.addColorStop(0, s.color);
    g.addColorStop(1, 'transparent');
    ctx.fillStyle = g;
