bgGrad.addColorStop(0, '#1a1a2e');
bgGrad.addColorStop(0.5, '#16213e');
bgGrad.addColorStop(1, '#0f3460');
bgCtx.fillStyle = bgGrad;
bgCtx.fillRect(0, 0, 2, 512);
const bgTex = new THREE.CanvasTexture(bgCanvas);
scene.background = bgTex;

// ── Ground plane ─────────────────────────────────────────
const groundGeo = new THREE.CircleGeometry(10, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111122,
  roughness: 0.8,
  metalness: 0.2,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
ground.receiveShadow = true;
scene.add(ground);

// ── Lighting ─────────────────────────────────────────────
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 5);
keyLight.castShadow = true;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 1);
fillLight.position.set(-5, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff8866, 1.5);
rimLight.position.set(0, -2, -5);
scene.add(rimLight);

const topLight = new THREE.PointLight(0xffffff, 2, 20);
topLight.position.set(0, 6, 0);
scene.add(topLight);

// ── Glass Paperweight Sphere ─────────────────────────────
const glassRadius = 1.5;
const glassGeo = new THREE.SphereGeometry(glassRadius, 128, 128);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.97,
  opacity: 1,
  metalness: 0.0,
  roughness: 0.02,
  ior: 1.52,
  thickness: 1.5,
  specularIntensity: 1,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1.5,
  clearcoat: 0.1,
  clearcoatRoughness: 0.05,
  attenuationColor: new THREE.Color(0xf0f0ff),
  attenuationDistance: 3,
});

const glassSphere = new THREE.Mesh(glassGeo, glassMat);
glassSphere.castShadow = true;
scene.add(glassSphere);

// ── Swirl Helper: create a spiral curve ──────────────────
function createSpiralCurve(radius, height, turns, startAngle, phaseOffset, wobble) {
  const points = [];
  const segments = 200;
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const angle = startAngle + phaseOffset + t * turns * Math.PI * 2;
    const r = radius * (0.3 + 0.7 * Math.sin(t * Math.PI)); // pinch at ends
    const wobbleR = r + Math.sin(angle * 3 + t * 10) * wobble;
    const x = Math.cos(angle) * wobbleR;
    const y = (t - 0.5) * height + Math.sin(t * Math.PI * 4) * 0.1;
    const z = Math.sin(angle) * wobbleR;
    points.push(new THREE.Vector3(x, y, z));
  }
  return new THREE.CatmullRomCurve3(points);
}

// ── Create Swirl Tubes ───────────────────────────────────
const swirlGroup = new THREE.Group();
scene.add(swirlGroup);

const swirlColors = [
  0xff2255, // red
  0x2255ff, // blue
  0x22ff55, // green
  0xffaa22, // orange
  0xaa22ff, // purple
  0x22ffff, // cyan
  0xff55aa, // pink
  0xffff22, // yellow
];

const swirlConfigs = [
  { radius: 0.8, height: 2.2, turns: 3, phase: 0, wobble: 0.06, colorIdx: 0, radiusTube: 0.025 },
  { radius: 0.7, height: 2.0, turns: -3, phase: Math.PI / 3, wobble: 0.05, colorIdx: 1, radiusTube: 0.022 },
  { radius: 0.6, height: 1.8, turns: 2, phase: Math.PI * 2 / 3, wobble: 0.07, colorIdx: 2, radiusTube: 0.02 },
  { radius: 0.9, height: 2.4, turns: -2, phase: Math.PI / 6, wobble: 0.04, colorIdx: 3, radiusTube: 0.018 },
  { radius: 0.5, height: 1.6, turns: 4, phase: Math.PI / 2, wobble: 0.08, colorIdx: 4, radiusTube: 0.015 },
  { radius: 0.75, height: 2.1, turns: -4, phase: Math.PI * 5 / 6, wobble: 0.05, colorIdx: 5, radiusTube: 0.017 },
  { radius: 0.65, height: 1.9, turns: 2.5, phase: Math.PI * 1.3, wobble: 0.06, colorIdx: 6, radiusTube: 0.014 },
  { radius: 0.55, height: 1.7, turns: -2.5, phase: Math.PI * 0.7, wobble: 0.07, colorIdx: 7, radiusTube: 0.013 },
];

swirlConfigs.forEach(cfg => {
  const curve = createSpiralCurve(
    cfg.radius, cfg.height, cfg.turns, 0, cfg.phase, cfg.wobble
  );
  const tubeGeo = new THREE.TubeGeometry(curve, 150, cfg.radiusTube, 12, false);
  const tubeMat = new THREE.MeshPhysicalMaterial({
    color: swirlColors[cfg.colorIdx],
    roughness: 0.15,
    metalness: 0.1,
    transmission: 0.3,
    thickness: 0.5,
    ior: 1.45,
    envMapIntensity: 0.8,
    clearcoat: 0.5,
    clearcoatRoughness: 0.1,
    emissive: swirlColors[cfg.colorIdx],
    emissiveIntensity: 0.15,
  });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  swirlGroup.add(tube);
});

// ── Inner "milk glass" cloud particles ───────────────────
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const colors = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  // Distribute in a swirling pattern inside the sphere
  const phi = Math.random() * Math.PI * 2;
  const theta = Math.acos(2 * Math.random() - 1);
  const r = Math.random() * 1.2;

  // Add swirl distortion
  const swirlAngle = phi + r * 3;
  const x = r * Math.sin(theta) * Math.cos(swirlAngle);
  const y = r * Math.cos(theta) * 0.8; // flatten slightly
  const z = r * Math.sin(theta) * Math.sin(swirlAngle);

  positions[i * 3] = x;
  positions[i * 3 + 1] = y;
  positions[i * 3 + 2] = z;

  const c = new THREE.Color(swirlColors[Math.floor(Math.random() * swirlColors.length)]);
  colors[i * 3] = c.r;
  colors[i * 3 + 1] = c.g;
  colors[i * 3 + 2] = c.b;

  sizes[i] = 0.01 + Math.random() * 0.03;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  size: 0.03,
  vertexColors: true,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});

const particles = new THREE.Points(particleGeo, particleMat);
swirlGroup.add(particles);

