}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1.5, 0);

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xfff5e0, 2.5);
keyLight.position.set(5, 8, 6);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc0d8ff, 0.8);
fillLight.position.set(-4, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffd699, 1.5);
rimLight.position.set(0, -2, -5);
scene.add(rimLight);

const pointLight = new THREE.PointLight(0xffaa44, 3, 20);
pointLight.position.set(3, 5, 4);
scene.add(pointLight);

// ── Brass Material ──
const brassMaterial = new THREE.MeshStandardMaterial({
  color: 0xb8860b,
  metalness: 0.92,
  roughness: 0.28,
  envMapIntensity: 1.5,
});

const darkBrassMaterial = new THREE.MeshStandardMaterial({
  color: 0x8b6914,
  metalness: 0.9,
  roughness: 0.35,
});

// ── Env Map (simple procedural) ──
const pmremGenerator = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x333344);
const envLight1 = new THREE.DirectionalLight(0xffffff, 3);
envLight1.position.set(5, 5, 5);
envScene.add(envLight1);
const envLight2 = new THREE.DirectionalLight(0xffaa44, 2);
envLight2.position.set(-5, 3, -5);
envScene.add(envLight2);
const envRT = pmremGenerator.fromScene(envScene);
scene.environment = envRT.texture;

// ── Protractor Arc Body ──
const outerRadius = 5;
const innerRadius = 3.8;
const arcThickness = 0.12;
const startAngle = 0;
const endAngle = Math.PI;

function createProtractorArc() {
  const shape = new THREE.Shape();
  // Outer arc (clockwise from right to left)
  shape.absarc(0, 0, outerRadius, startAngle, endAngle, false);
  // Inner arc (counter-clockwise from left to right)
  shape.absarc(0, 0, innerRadius, endAngle, startAngle, true);
  shape.closePath();

  const extrudeSettings = {
    depth: arcThickness,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 4,
  };

  const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geometry.center();
  const mesh = new THREE.Mesh(geometry, brassMaterial);
  return mesh;
}

const protractorGroup = new THREE.Group();
const arcBody = createProtractorArc();
arcBody.rotation.x = -Math.PI / 2;
arcBody.position.y = 0;
protractorGroup.add(arcBody);
scene.add(protractorGroup);

// ── Tick Marks ──
function createTick(radius, angle, height, material) {
  const tickGeo = new THREE.BoxGeometry(0.06, height, 0.08);
  const tick = new THREE.Mesh(tickGeo, material);
  tick.position.x = Math.cos(angle) * radius;
  tick.position.y = Math.sin(angle) * radius;
  tick.rotation.z = angle - Math.PI / 2;
  return tick;
}

for (let deg = 0; deg <= 180; deg += 1) {
  const rad = (Math.PI * deg) / 180;
  let height, material, radius;

  if (deg % 10 === 0) {
    height = 0.35;
    material = darkBrassMaterial;
    radius = outerRadius;
  } else if (deg % 5 === 0) {
    height = 0.22;
    material = darkBrassMaterial;
    radius = outerRadius;
  } else {
    height = 0.1;
    material = darkBrassMaterial;
    radius = outerRadius;
  }

  const tick = createTick(radius, rad, height, material);
  tick.rotation.x = -Math.PI / 2;
  tick.position.z = arcThickness / 2 + 0.005;
  protractorGroup.add(tick);

  // Inner ticks for major divisions
  if (deg % 10 === 0) {
    const innerTick = createTick(innerRadius, rad, 0.15, darkBrassMaterial);
    innerTick.rotation.x = -Math.PI / 2;
    innerTick.position.z = arcThickness / 2 + 0.005;
    protractorGroup.add(innerTick);
  }
}

// ── Degree Labels ──
function createTextSprite(text, fontSize = 64) {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, 256, 256);
  ctx.font = `bold ${fontSize}px Georgia, serif`;
  ctx.fillStyle = '#2a1a00';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 128, 128);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const spriteMat = new THREE.SpriteMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
  });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.set(0.7, 0.7, 1);
  return sprite;
}

for (let deg = 0; deg <= 180; deg += 10) {
  const rad = (Math.PI * deg) / 180;
  const labelRadius = innerRadius - 0.8;
  const sprite = createTextSprite(deg.toString(), deg % 30 === 0 ? 72 : 56);
  sprite.position.x = Math.cos(rad) * labelRadius;
  sprite.position.y = Math.sin(rad) * labelRadius;
  sprite.position.z = arcThickness / 2 + 0.02;
  sprite.rotation.x = -Math.PI / 2;
  protractorGroup.add(sprite);
}

// ── Center Post ──
const centerPostGeo = new THREE.CylinderGeometry(0.15, 0.15, arcThickness + 0.1, 32);
const centerPost = new THREE.Mesh(centerPostGeo, brassMaterial);
centerPost.rotation.x = Math.PI / 2;
centerPost.position.y = 0;
protractorGroup.add(centerPost);

const centerRingGeo = new THREE.TorusGeometry(0.2, 0.04, 16, 32);
const centerRing = new THREE.Mesh(centerRingGeo, darkBrassMaterial);
centerRing.position.z = arcThickness / 2 + 0.01;
protractorGroup.add(centerRing);

// ── Baseline Edge ──
const baselineGeo = new THREE.BoxGeometry(outerRadius * 2 + 0.2, 0.08, arcThickness + 0.06);
const baseline = new THREE.Mesh(baselineGeo, brassMaterial);
baseline.position.z = 0;
protractorGroup.add(baseline);

// ── Subtle rotation ──
protractorGroup.rotation.x = -Math.PI / 2;
protractorGroup.position.y = 0.06;

// ── Ground Plane ──
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111122,
  metalness: 0.3,
  roughness: 0.8,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -3;
scene.add(ground);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const elapsed = clock.getElapsedTime();

  // Gentle floating
  protractorGroup.position.y = 0.06 + Math.sin(elapsed * 0.5) * 0.1;

  // Subtle light animation
  pointLight.position.x = 3 + Math.sin(elapsed * 0.3) * 2;
  pointLight.position.z = 4 + Math.cos(elapsed * 0.3) * 2;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This creates a **3D brass protractor arc** with:

- **Extruded arc body** — a semi-circular ring from 0° to 180° with beveled edges
- **Tick marks** — three tiers of detail: major ticks every 10°, medium every 5°, and fine ticks every 1°
- **Degree labels** — canvas-rendered text sprites at every 10° (larger at every 30°)
- **Brass PBR material** — high metalness (0.92), warm gold color, tuned roughness for a polished-but-realistic look
- **Dramatic lighting** — key, fill, rim, and animated point light with ACES filmic tone mapping
- **Center post & baseline edge** — small decorative details for realism
- **Gentle floating animation** and **OrbitControls** for interactive inspection

