</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// ── Environment map (studio-like) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x303050);

const light1 = new THREE.PointLight(0xffeedd, 80);
light1.position.set(5, 5, 5);
envScene.add(light1);

const light2 = new THREE.PointLight(0x6688ff, 50);
light2.position.set(-5, -3, 4);
envScene.add(light2);

const light3 = new THREE.PointLight(0xff6688, 40);
light3.position.set(0, 5, -5);
envScene.add(light3);

const envMap = pmrem.fromScene(envScene, 0.04).texture;
scene.environment = envMap;

// ── Marble Shader Material ──
const marbleMaterial = new THREE.ShaderMaterial({
  uniforms: {
    envMap:       { value: envMap },
    ior:          { value: 1.52 },
    time:         { value: 0 },
    color1:       { value: new THREE.Color(0.95, 0.35, 0.45) },
    color2:       { value: new THREE.Color(0.25, 0.65, 0.95) },
    color3:       { value: new THREE.Color(0.85, 0.90, 0.40) },
    color4:       { value: new THREE.Color(0.55, 0.30, 0.90) },
    bgColor:      { value: new THREE.Color(0.10, 0.10, 0.18) },
  },
  vertexShader: /* glsl */`
    varying vec3 vWorldPos;
    varying vec3 vNormal;
    varying vec3 vViewDir;
    varying vec3 vObjPos;

    void main() {
      vObjPos  = position;
      vNormal  = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      vViewDir  = normalize(cameraPosition - worldPos.xyz);
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: /* glsl */`
    uniform sampler2D envMap;
    uniform float ior;
    uniform float time;
    uniform vec3 color1;
    uniform vec3 color2;
    uniform vec3 color3;
    uniform vec3 color4;
    uniform vec3 bgColor;

    varying vec3 vWorldPos;
    varying vec3 vNormal;
    varying vec3 vViewDir;
    varying vec3 vObjPos;

    // ── Hash & Noise ──
    vec3 hash3(vec3 p) {
      p = vec3(
        dot(p, vec3(127.1, 311.7,  74.3)),
        dot(p, vec3(269.5, 183.3, 246.1)),
        dot(p, vec3(113.5, 271.9, 124.6))
      );
      return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
    }

    float noise(vec3 p) {
      vec3 i = floor(p);
      vec3 f = fract(p);
      vec3 u = f * f * (3.0 - 2.0 * f);
      return mix(
        mix(mix(dot(hash3(i + vec3(0,0,0)), f - vec3(0,0,0)),
                dot(hash3(i + vec3(1,0,0)), f - vec3(1,0,0)), u.x),
            mix(dot(hash3(i + vec3(0,1,0)), f - vec3(0,1,0)),
                dot(hash3(i + vec3(1,1,0)), f - vec3(1,1,0)), u.x), u.y),
        mix(mix(dot(hash3(i + vec3(0,0,1)), f - vec3(0,0,1)),
                dot(hash3(i + vec3(1,0,1)), f - vec3(1,0,1)), u.x),
            mix(dot(hash3(i + vec3(0,1,1)), f - vec3(0,1,1)),
                dot(hash3(i + vec3(1,1,1)), f - vec3(1,1,1)), u.x), u.y), u.z);
    }

    float fbm(vec3 p) {
      float v = 0.0, a = 0.5;
      vec3 shift = vec3(100.0);
      for (int i = 0; i < 6; i++) {
        v += a * noise(p);
        p = p * 2.0 + shift;
        a *= 0.5;
      }
      return v;
    }

    // ── Swirl function ──
    float swirl(vec3 p) {
      float r = length(p.xz);
      float a = atan(p.z, p.x);
      vec3 sp = vec3(a * 0.5 + p.y * 0.8, p.y * 2.0 - r * 1.5, r + p.y * 0.6);
      return fbm(sp * 2.5 + time * 0.15);
    }

    void main() {
      vec3 N = normalize(vNormal);
      vec3 V = normalize(vViewDir);

      // ── Fresnel (Schlick) ──
      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 4.0);
      fresnel = mix(0.04, 1.0, fresnel);

      // ── Internal swirl colors ──
      vec3 p = vObjPos * 1.8;
      float s1 = swirl(p);
      float s2 = swirl(p + vec3(5.2, 1.3, 2.8));
      float s3 = swirl(p + vec3(9.1, 4.7, 6.3));

      vec3 swirlColor = mix(color1, color2, smoothstep(-0.3, 0.3, s1));
      swirlColor = mix(swirlColor, color3, smoothstep(0.0, 0.5, s2) * 0.6);
      swirlColor = mix(swirlColor, color4, smoothstep(0.1, 0.6, s3) * 0.4);

      // Depth-based fade (colors more visible toward center)
      float depth = 1.0 - max(dot(N, V), 0.0);
      depth = pow(depth, 0.7);
      vec3 volumeColor = swirlColor * (0.5 + 0.5 * depth);

      // ── Environment reflection ──
      vec3 R = reflect(-V, N);
      vec3 envColor = textureCube(envMap, R).rgb;

      // ── Refraction approximation ──
      vec3 refractDir = refract(-V, N, 1.0 / ior);
      vec3 refractColor = textureCube(envMap, refractDir).rgb;

      // ── Compose ──
      // Surface: mix of reflection and refracted light
      vec3 surface = mix(envColor, refractColor, 0.3);

      // Blend volume swirl with surface based on Fresnel
      vec3 finalColor = mix(volumeColor, surface, fresnel);

      // Add subtle specular highlight
      vec3 H = normalize(V + vec3(0.0, 1.0, 0.5));
      float spec = pow(max(dot(N, H), 0.0), 120.0) * 0.6;
      finalColor += spec;

      // Tone mapping hint
      finalColor = finalColor / (finalColor + vec3(1.0));

      gl_FragColor = vec4(finalColor, 1.0);
    }
  `,
});

// ── Marble geometry ──
const marble = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 128, 128),
  marbleMaterial
);
scene.add(marble);

// ── Ground plane (subtle) ──
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 20),
  new THREE.MeshStandardMaterial({
    color: 0x1a1a2e,
    roughness: 0.8,
    metalness: 0.2,
  })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -2;
scene.add(ground);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x6688ff, 1.5);
fillLight.position.set(-5, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff6688, 1.0);
rimLight.position.set(0, -2, -5);
scene.add(rimLight);

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ── Animate ──
function animate(t) {
  requestAnimationFrame(animate);
  marbleMaterial.uniforms.time.value = t * 0.001;
  marble.rotation.y = t * 0.0003;
  controls.update();
  renderer.render(scene, camera);
}
animate(0);
</script>
</body>
</html>
```

## What this does

| Feature | Detail |
|---|---|
| **Glass rendering** | Schlick Fresnel blends surface reflections with internal color; `refract()` approximates light bending through glass |
| **Swirl pattern** | 3D **fractal Brownian motion** (6-octave noise) is warped through a swirl coordinate transform, producing organic, flowing color bands |
| **Four swirl colors** | Coral, sky blue, lime, and violet — blended using noise-driven `smoothstep` ramps |
| **Depth fade** | Colors are more saturated toward the center of the marble and fade near the surface, mimicking volumetric light scattering |
| **Environment map** | A procedural PMREM studio lighting setup (warm key, blue fill, pink rim) gives realistic reflections and refractions |
| **Interaction** | `OrbitControls` — drag to rotate, scroll to zoom |
| **Slow spin** | The marble gently rotates on its own for a living feel |

Just save it as `index.html` and open in any modern browser — no build step needed.

