        southMesh.position.y = -0.4;
        needleGroup.add(southMesh);

        compassGroup.add(needleGroup);

        // Tilt the compass slightly for better viewing
        compassGroup.rotation.x = -Math.PI / 6;

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
