const waterGeo = new THREE.SphereGeometry(1.88, 64, 64);
const waterMat = new THREE.MeshPhysicalMaterial({
  color: 0x88bbee,
  transmission: 0.6,
  opacity: 0.7,
  transparent: true,
  metalness: 0,
  roughness: 0.15,
