  attenuationDistance: 3,
  side: THREE.DoubleSide,
});
const waterSphere = new THREE.Mesh(waterGeo, waterMat);
waterSphere.position.y = 1.5;
scene.add(waterSphere);

// --- Snow Particles ---
const SNOW_COUNT = 600;
const snowGeo = new THREE.BufferGeometry();
const snowPositions = new Float32Array(SNOW_COUNT * 3);
const snowSizes = new Float32Array(SNOW_COUNT);
const snowVelocities = [];

for (let i = 0; i < SNOW_COUNT; i++) {
  const r = 1.7 * Math.random();
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  snowPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  snowPositions[i * 3 + 1] = 1.5 + r * Math.sin(phi) * Math.sin(theta) - 0.3;
  snowPositions[i * 3 + 2] = r * Math.cos(phi);
  snowSizes[i] = Math.random() * 3 + 1;
  snowVelocities.push({
    y: -(Math.random() * 0.008 + 0.002),
    x: (Math.random() - 0.5) * 0.003,
    z: (Math.random() - 0.5) * 0.003,
    wobble: Math.random() * Math.PI * 2,
