    cone.position.y = (0.15 + i * 0.12) * scale;
    group.add(cone);
  }

  group.position.set(x, y, z);
  return group;
}

const treePositions = [
  [-0.6, 0.1, 0.5], [0.5, 0.1, -0.4], [0.0, 0.1, 0.8],
  [-0.3, 0.1, -0.6], [0.7, 0.1, 0.2], [-0.8, 0.1, -0.2],
  [0.2, 0.1, 0.0], [-0.1, 0.1, -0.9],
];
treePositions.forEach(([x, y, z]) => {
  scene.add(makeTree(x, y, z, 0.6 + Math.random() * 0.6));
