// --- Base ---
const baseGroup = new THREE.Group();
const woodMat = new THREE.MeshStandardMaterial({ color: 0x5c3a1e, roughness: 0.6, metalness: 0.1 });
const goldMat = new THREE.MeshStandardMaterial({ color: 0xccaa44, roughness: 0.2, metalness: 0.8 });

const baseBottom = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.7, 0.3, 64), woodMat);
baseBottom.position.y = -0.15;
baseGroup.add(baseBottom);

const baseMid = new THREE.Mesh(new THREE.CylinderGeometry(1.4, 1.55, 0.5, 64), woodMat);
baseMid.position.y = 0.2;
baseGroup.add(baseMid);

const baseTop = new THREE.Mesh(new THREE.CylinderGeometry(1.45, 1.4, 0.15, 64), woodMat);
baseTop.position.y = 0.5;
baseGroup.add(baseTop);

const goldRing = new THREE.Mesh(new THREE.TorusGeometry(1.42, 0.04, 16, 64), goldMat);
goldRing.position.y = 0.5;
goldRing.rotation.x = Math.PI / 2;
baseGroup.add(goldRing);

const goldRing2 = new THREE.Mesh(new THREE.TorusGeometry(1.65, 0.03, 16, 64), goldMat);
goldRing2.position.y = 0.0;
goldRing2.rotation.x = Math.PI / 2;
baseGroup.add(goldRing2);

// Plaque
const plaque = new THREE.Mesh(
  new THREE.BoxGeometry(0.8, 0.2, 0.02),
  goldMat
);
plaque.position.set(0, 0.2, 1.58);
baseGroup.add(plaque);

scene.add(baseGroup);

// --- Ground reflection ---
const groundGeo = new THREE.CircleGeometry(10, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111122, roughness: 0.3, metalness: 0.5
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.3;
