// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Animate snow
  const pos = snowGeo.attributes.position.array;
  for (let i = 0; i < SNOW_COUNT; i++) {
    const v = snowVelocities[i];
    pos[i * 3] += v.x + Math.sin(t * v.wobbleSpeed + v.wobble) * 0.001;
    pos[i * 3 + 1] += v.y;
    pos[i * 3 + 2] += v.z + Math.cos(t * v.wobbleSpeed + v.wobble) * 0.001;

    // Reset snow that falls below water level
    if (pos[i * 3 + 1] < 0.0) {
      const r = 1.7 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      pos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      pos[i * 3 + 1] = 1.5 + r * Math.sin(phi) * Math.sin(theta) - 0.3;
      pos[i * 3 + 2] = r * Math.cos(phi);
    }
  }
  snowGeo.attributes.position.needsUpdate = true;
  snowMat.uniforms.uTime.value = t;

  // Gentle water shimmer
  waterSphere.position.y = 1.5 + Math.sin(t * 0.5) * 0.01;

  // Subtle globe wobble
  glassSphere.rotation.y = Math.sin(t * 0.3) * 0.02;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
