renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.3, 0);
controls.maxPolarAngle = Math.PI / 2.05;
controls.minDistance = 2;
controls.maxDistance = 15;

// --- Brass Material ---
function brassMat(opts = {}) {
  return new THREE.MeshStandardMaterial({
    color: opts.color || 0xc9a84c,
    metalness: 0.92,
    roughness: opts.roughness ?? 0.28,
    ...opts
  });
}

// --- Dial Plate ---
const plateGeo = new THREE.CylinderGeometry(2.2, 2.2, 0.06, 128);
const plate = new THREE.Mesh(plateGeo, brassMat({ roughness: 0.35 }));
plate.position.y = 0.03;
plate.receiveShadow = true;
scene.add(plate);

// --- Outer Rim ---
const rimGeo = new THREE.TorusGeometry(2.2, 0.06, 16, 128);
const rim = new THREE.Mesh(rimGeo, brassMat({ roughness: 0.2 }));
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.06;
rim.castShadow = true;
scene.add(rim);

// --- Inner Decorative Ring ---
const ringGeo = new THREE.TorusGeometry(1.6, 0.025, 12, 128);
const ring = new THREE.Mesh(ringGeo, brassMat({ color: 0xb8943f, roughness: 0.4 }));
ring.rotation.x = Math.PI / 2;
ring.position.y = 0.07;
scene.add(ring);

// --- Hour Lines ---
const LATTITUDE = 45 * Math.PI / 180; // ~45° latitude
const hourLines = [];

for (let h = -6; h <= 6; h++) {
  const hourAngle = h * 15 * Math.PI / 180;
  const theta = Math.atan(Math.sin(LATTITUDE) * Math.tan(hourAngle));

  const isNoon = h === 0;
  const isHalf = h % 2 !== 0;
  const length = isNoon ? 2.0 : (isHalf ? 1.55 : 1.75);
  const thickness = isNoon ? 0.035 : (isHalf ? 0.012 : 0.02);

  const lineGeo = new THREE.BoxGeometry(thickness, 0.01, length);
  const line = new THREE.Mesh(lineGeo, brassMat({
    color: isNoon ? 0xe8c84a : 0xa08030,
    roughness: 0.5
  }));
  line.position.y = 0.065;
  line.rotation.y = -theta;
  line.position.x = Math.sin(-theta) * length * 0.35;
  line.position.z = Math.cos(-theta) * length * 0.35;
  line.castShadow = true;
  scene.add(line);
  hourLines.push(line);

  // Hour markers on rim
  if (!isHalf) {
    const markerGeo = new THREE.SphereGeometry(0.04, 12, 12);
    const marker = new THREE.Mesh(markerGeo, brassMat({ color: 0xe8c84a }));
    const mx = Math.sin(-theta) * 2.05;
    const mz = Math.cos(-theta) * 2.05;
    marker.position.set(mx, 0.07, mz);
    scene.add(marker);
  }
}

