const pinGeo = new THREE.CylinderGeometry(0.04, 0.05, 0.12, 24);
const pin = new THREE.Mesh(pinGeo, brassMat({ color: 0xe8c84a, roughness: 0.15 }));
pin.position.y = 0.12;
pin.castShadow = true;
scene.add(pin);

