const gnomonShape = new THREE.Shape();
gnomonShape.moveTo(0, 0);
gnomonShape.lineTo(0, 1.4);
gnomonShape.lineTo(0.01, 0);
gnomonShape.closePath();

const extrudeSettings = { depth: 0.12, bevelEnabled: true, bevelThickness: 0.01, bevelSize: 0.01, bevelSegments: 3 };
const gnomonGeo = new THREE.ExtrudeGeometry(gnomonShape, extrudeSettings);
const gnomon = new THREE.Mesh(gnomonGeo, brassMat({ color: 0xd4a840, roughness: 0.25 }));
gnomon.rotation.x = -Math.PI / 2 + LATTITUDE; // tilted to latitude
gnomon.rotation.y = Math.PI;
gnomon.position.set(0, 0.06, -0.06);
gnomon.castShadow = true;
scene.add(gnomon);

// --- Stone Pedestal ---
const pedGeo = new THREE.CylinderGeometry(0.6, 0.75, 0.5, 32);
const pedMat = new THREE.MeshStandardMaterial({ color: 0x8a8a7a, roughness: 0.85, metalness: 0.05 });
const pedestal = new THREE.Mesh(pedGeo, pedMat);
pedestal.position.y = -0.28;
pedestal.receiveShadow = true;
pedestal.castShadow = true;
scene.add(pedestal);

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a3a2a, roughness: 0.95 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.54;
ground.receiveShadow = true;
scene.add(ground);

// --- Ambient Light ---
const ambient = new THREE.AmbientLight(0x303050, 0.8);
scene.add(ambient);

// --- Hemisphere Light ---
const hemi = new THREE.HemisphereLight(0x87ceeb, 0x3a2a1a, 0.4);
scene.add(hemi);

// --- Sun Light (animated) ---
const sunLight = new THREE.DirectionalLight(0xffe4a0, 3.5);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 20;
sunLight.shadow.camera.left = -4;
sunLight.shadow.camera.right = 4;
sunLight.shadow.camera.top = 4;
sunLight.shadow.camera.bottom = -4;
sunLight.shadow.bias = -0.001;
scene.add(sunLight);

// Sun visual sphere
const sunVisGeo = new THREE.SphereGeometry(0.15, 16, 16);
const sunVisMat = new THREE.MeshBasicMaterial({ color: 0xffe4a0 });
const sunVis = new THREE.Mesh(sunVisGeo, sunVisMat);
scene.add(sunVis);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const hour = (t * 0.3) % 24; // slow sun motion
  const sunAngle = ((hour - 6) / 24) * Math.PI * 2;
  const sunHeight = Math.sin(sunAngle);

  if (sunHeight > -0.1) {
    const dist = 8;
    sunLight.position.set(
      Math.cos(sunAngle) * dist,
      Math.max(sunHeight * dist, 0.5),
      Math.sin(sunAngle) * dist * 0.5
    );
    sunVis.position.copy(sunLight.position);
    sunLight.intensity = Math.max(sunHeight, 0.05) * 4;
    sunVis.visible = true;
  } else {
    sunVis.visible = false;
    sunLight.intensity = 0.1;
  }

  controls.update();
  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
