controls.target.set(0, 0.5, 0);
controls.minDistance = 2;
controls.maxDistance = 12;

// ── Materials ──
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xc9a030,
  metalness: 0.95,
  roughness: 0.18,
