});

// ── Env map (simple procedural) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x1a1a2e);

// Add some bright spots for reflections
const envLight1 = new THREE.PointLight(0xffeedd, 50, 20);
envLight1.position.set(3, 5, 2);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0xccddff, 30, 20);
envLight2.position.set(-4, 3, -2);
envScene.add(envLight2);
const envLight3 = new THREE.PointLight(0xffcc88, 20, 15);
envLight3.position.set(0, -2, 4);
envScene.add(envLight3);

const envMap = pmrem.fromScene(envScene, 0.04).texture;
scene.environment = envMap;

// ── Eyepiece Group ──
const eyepiece = new THREE.Group();

// Helper: create cylinder
function cyl(radiusTop, radiusBot, height, pos, mat, rotX = 0) {
  const g = new THREE.CylinderGeometry(radiusTop, radiusBot, height, 64);
  const m = new THREE.Mesh(g, mat);
  m.position.copy(pos);
  if (rotX) m.rotation.x = rotX;
  return m;
}

// 1) Barrel top (thin threaded section)
eyepiece.add(cyl(0.32, 0.32, 1.2, new THREE.Vector3(0, 2.2, 0), brassMat));

// Barrel threads (decorative rings)
for (let i = 0; i < 8; i++) {
  const y = 1.7 + i * 0.06;
  const ring = cyl(0.335, 0.335, 0.015, new THREE.Vector3(0, y, 0), darkBrassMat);
  eyepiece.add(ring);
}

// 2) Shoulder / transition ring
eyepiece.add(cyl(0.38, 0.32, 0.15, new THREE.Vector3(0, 1.55, 0), brassMat));

// 3) Main housing body
eyepiece.add(cyl(0.42, 0.42, 0.9, new THREE.Vector3(0, 0.95, 0), brassMat));

// Housing decorative ring
eyepiece.add(cyl(0.44, 0.44, 0.06, new THREE.Vector3(0, 1.25, 0), darkBrassMat));
eyepiece.add(cyl(0.44, 0.44, 0.06, new THREE.Vector3(0, 0.65, 0), darkBrassMat));

// 4) Lower housing taper
eyepiece.add(cyl(0.42, 0.38, 0.2, new THREE.Vector3(0, 0.45, 0), brassMat));

// 5) Eyepiece bell (the part you look through)
eyepiece.add(cyl(0.38, 0.35, 0.35, new THREE.Vector3(0, 0.12, 0), brassMat));

// Bell edge ring
eyepiece.add(cyl(0.36, 0.36, 0.04, new THREE.Vector3(0, -0.05, 0), darkBrassMat));

// 6) Inner barrel (dark interior)
eyepiece.add(cyl(0.30, 0.30, 2.0, new THREE.Vector3(0, 1.6, 0), innerDarkMat));

