const fieldLens = cyl(0.30, 0.30, 0.06, new THREE.Vector3(0, 0.05, 0), lensMat);
eyepiece.add(fieldLens);

// Eyepiece lens (smaller, deeper inside)
const eyeLens = cyl(0.18, 0.18, 0.05, new THREE.Vector3(0, 0.6, 0), lensMat);
eyepiece.add(eyeLens);

// 8) Bottom rim / lip
const bottomRim = new THREE.TorusGeometry(0.35, 0.025, 16, 64);
const bottomRimMesh = new THREE.Mesh(bottomRim, brassMat);
bottomRimMesh.position.set(0, -0.05, 0);
bottomRimMesh.rotation.x = Math.PI / 2;
eyepiece.add(bottomRimMesh);

// 9) Top rim
const topRim = new THREE.TorusGeometry(0.32, 0.02, 16, 64);
const topRimMesh = new THREE.Mesh(topRim, brassMat);
topRimMesh.position.set(0, 2.8, 0);
topRimMesh.rotation.x = Math.PI / 2;
eyepiece.add(topRimMesh);

// 10) Small knurled focus ring (simulated with torus)
const focusRing = new THREE.TorusGeometry(0.43, 0.03, 12, 64);
const focusRingMesh = new THREE.Mesh(focusRing, darkBrassMat);
focusRingMesh.position.set(0, 0.75, 0);
focusRingMesh.rotation.x = Math.PI / 2;
eyepiece.add(focusRingMesh);

// Add small dots on focus ring for grip texture
for (let i = 0; i < 32; i++) {
  const angle = (i / 32) * Math.PI * 2;
  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(0.012, 8, 8),
