}

// Position entire group
eyepiece.position.y = -0.2;
scene.add(eyepiece);

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0x222233, 0.5);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3.0);
keyLight.position.set(5, 8, 3);
keyLight.castShadow = false;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x99aacc, 1.2);
fillLight.position.set(-4, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffccaa, 2.0);
rimLight.position.set(0, -3, -5);
scene.add(rimLight);

// Accent point lights for sparkle
const accent1 = new THREE.PointLight(0xffeecc, 2, 8);
accent1.position.set(2, 4, 1);
