```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Brass Compass Rose</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #1a1410; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1410);

// ── Camera ──
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 6, 8);

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Environment for metallic reflections ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI / 2.1;

// ── Materials ──
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xc5a55a,
  metalness: 0.95,
  roughness: 0.22,
  envMapIntensity: 1.5,
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8a7033,
  metalness: 0.95,
  roughness: 0.35,
  envMapIntensity: 1.2,
});

const redAccentMat = new THREE.MeshStandardMaterial({
  color: 0x8b1a1a,
  metalness: 0.6,
  roughness: 0.4,
  envMapIntensity: 1.0,
});

const blackMat = new THREE.MeshStandardMaterial({
  color: 0x111111,
  metalness: 0.1,
  roughness: 0.8,
});

// ── Helper: create a star arm (diamond shape) ──
function createStarArm(length, width, height) {
  const shape = new THREE.Shape();
  shape.moveTo(0, length);
  shape.lineTo(-width, 0);
  shape.lineTo(0, -length * 0.3);
  shape.lineTo(width, 0);
  shape.closePath();

  const extrudeSettings = { depth: height, bevelEnabled: true, bevelThickness: 0.02, bevelSize: 0.02, bevelSegments: 2 };
  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

// ── Compass Rose Group ──
const compass = new THREE.Group();

// ── Base plate ──
const baseGeo = new THREE.CylinderGeometry(3.2, 3.2, 0.12, 64);
const base = new THREE.Mesh(baseGeo, brassMat);
base.position.y = -0.06;
compass.add(base);

// Outer rim
const rimGeo = new THREE.TorusGeometry(3.2, 0.08, 16, 64);
const rim = new THREE.Mesh(rimGeo, darkBrassMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.02;
compass.add(rim);

// Inner decorative rings
for (let i = 0; i < 3; i++) {
  const r = 2.8 - i * 0.35;
  const ringGeo = new THREE.TorusGeometry(r, 0.025, 12, 64);
  const ring = new THREE.Mesh(ringGeo, darkBrassMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 0.07;
  compass.add(ring);
}

// ── Cardinal star arms (N, S, E, W) ──
const cardinalGeo = createStarArm(2.4, 0.35, 0.08);
const cardinalPositions = [
  { angle: 0, mat: redAccentMat },    // N
  { angle: Math.PI, mat: brassMat },  // S
  { angle: Math.PI / 2, mat: brassMat }, // E
  { angle: -Math.PI / 2, mat: brassMat }, // W
];

cardinalPositions.forEach(({ angle, mat }) => {
  const arm = new THREE.Mesh(cardinalGeo, mat);
  arm.position.y = 0.07;
  arm.rotation.y = -angle;
  compass.add(arm);

  // Mirror arm (back side of each point)
  const armBack = new THREE.Mesh(cardinalGeo, mat);
  armBack.position.y = 0.07;
  armBack.rotation.y = Math.PI - angle;
  armBack.scale.y = -1; // flip to point backward
  compass.add(armBack);
});

// ── Intercardinal star arms (NE, NW, SE, SW) ──
const interGeo = createStarArm(1.6, 0.25, 0.06);
const interAngles = [Math.PI / 4, -Math.PI / 4, 3 * Math.PI / 4, -3 * Math.PI / 4];

interAngles.forEach(angle => {
  const arm = new THREE.Mesh(interGeo, brassMat);
  arm.position.y = 0.07;
  arm.rotation.y = -angle;
  compass.add(arm);

  const armBack = new THREE.Mesh(interGeo, brassMat);
  armBack.position.y = 0.07;
  armBack.rotation.y = Math.PI - angle;
  armBack.scale.y = -1;
  compass.add(armBack);
});

// ── Center boss (raised dome) ──
const bossGeo = new THREE.SphereGeometry(0.22, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
const boss = new THREE.Mesh(bossGeo, brassMat);
boss.position.y = 0.07;
compass.add(boss);

const bossRimGeo = new THREE.TorusGeometry(0.22, 0.03, 12, 32);
const bossRim = new THREE.Mesh(bossRimGeo, darkBrassMat);
bossRim.rotation.x = Math.PI / 2;
bossRim.position.y = 0.07;
compass.add(bossRim);

// ── Pivot needle (thin center) ──
const pivotGeo = new THREE.CylinderGeometry(0.04, 0.04, 0.15, 16);
const pivot = new THREE.Mesh(pivotGeo, darkBrassMat);
pivot.position.y = 0.15;
compass.add(pivot);

// ── Cardinal direction markers ──
function createMarker(text, angle, radius, isCardinal = true) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = 'transparent';
  ctx.fillRect(0, 0, 128, 128);

  ctx.fillStyle = isCardinal ? '#c5a55a' : '#8a7033';
  ctx.font = isCardinal ? 'bold 80px serif' : 'bold 60px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 64, 64);

  const tex = new THREE.CanvasTexture(canvas);
  const spriteMat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(spriteMat);

  const s = isCardinal ? 0.4 : 0.28;
  sprite.scale.set(s, s, 1);
  sprite.position.set(Math.sin(angle) * radius, 0.09, Math.cos(angle) * radius);
  return sprite;
}

// N is at angle 0 (which is +Z in our setup)
compass.add(createMarker('N', 0, 2.9, true));
compass.add(createMarker('S', Math.PI, 2.9, true));
compass.add(createMarker('E', Math.PI / 2, 2.9, true));
compass.add(createMarker('W', -Math.PI / 2, 2.9, true));
compass.add(createMarker('NE', Math.PI / 4, 2.55, false));
compass.add(createMarker('NW', -Math.PI / 4, 2.55, false));
compass.add(createMarker('SE', 3 * Math.PI / 4, 2.55, false));
compass.add(createMarker('SW', -3 * Math.PI / 4, 2.55, false));

// ── Tick marks around the outer edge ──
for (let i = 0; i < 72; i++) {
  const angle = (i / 72) * Math.PI * 2;
  const isMajor = i % 18 === 0;
  const isMid = i % 9 === 0;
  const tickLen = isMajor ? 0.18 : (isMid ? 0.12 : 0.06);
  const r1 = 3.0;
  const r2 = 3.0 - tickLen;

  const tickGeo = new THREE.BoxGeometry(0.02, 0.03, tickLen);
  const tick = new THREE.Mesh(tickGeo, isMajor ? darkBrassMat : blackMat);
  tick.position.set(
    Math.sin(angle) * ((r1 + r2) / 2),
    0.07,
    Math.cos(angle) * ((r1 + r2) / 2)
  );
  tick.rotation.y = -angle;
  compass.add(tick);
}

// ── Decorative rosettes at cardinal points ──
for (let i = 0; i < 4; i++) {
  const angle = (i / 4) * Math.PI * 2;
  const rosetteGeo = new THREE.TorusGeometry(0.12, 0.025, 8, 16);
  const rosette = new THREE.Mesh(rosetteGeo, darkBrassMat);
  rosette.rotation.x = Math.PI / 2;
  rosette.position.set(Math.sin(angle) * 0.7, 0.07, Math.cos(angle) * 0.7);
  compass.add(rosette);
}

// ── Tilt the compass slightly ──
compass.rotation.x = -Math.PI / 6;
scene.add(compass);

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0xfff5e6, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight.position.set(5, 8, 5);
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0xc5a55a, 0.8);
fillLight.position.set(-4, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffd699, 1.5, 15);
rimLight.position.set(-3, 5, -5);
scene.add(rimLight);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle rotation
  compass.rotation.y = Math.sin(t * 0.15) * 0.15;

  // Subtle floating
  compass.position.y = Math.sin(t * 0.5) * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
