<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Brass Keyhole Escutcheon</title>
<style>
  * { margin: 0; padding: 0; }
  body { background: #1a1410; overflow: hidden; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1410);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0.3, 3.5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;

// ── Brass material ──
const brass = new THREE.MeshStandardMaterial({
  color: 0xb5863a,
  metalness: 0.92,
  roughness: 0.28,
});

const brassDark = new THREE.MeshStandardMaterial({
  color: 0x8a6528,
  metalness: 0.95,
  roughness: 0.35,
});

const holeMat = new THREE.MeshStandardMaterial({
  color: 0x0a0806,
  metalness: 0.3,
  roughness: 0.9,
});

// ── Keyhole shape ──
function keyholePath() {
  const s = new THREE.Shape();
  const r = 0.32;        // top circle radius
  const cy = 0.55;       // top circle center y
  const bw = 0.26;       // bottom width (half)
  const bh = 0.55;       // bottom height
  const neckW = 0.18;    // neck width (half)
  const neckH = 0.15;    // neck height

  // Build keyhole: circle → neck → flared bottom
  s.absarc(0, cy, r, 0, Math.PI * 2, false);
  s.moveTo(r, cy);
  s.lineTo(neckW, cy - r + neckH * 0.3);
  s.lineTo(neckW, cy - r);
  s.lineTo(neckW, cy - r - neckH);
  s.lineTo(bw, cy - r - neckH - bh * 0.6);
  s.lineTo(bw, cy - r - neckH - bh);
  // bottom arc
  s.absarc(0, cy - r - neckH - bh, bw, 0, Math.PI, false);
  // left side
  s.lineTo(-bw, cy - r - neckH - bh * 0.6);
  s.lineTo(-neckW, cy - r - neckH);
  s.lineTo(-neckW, cy - r);
  s.lineTo(-neckW, cy - r + neckH * 0.3);
  s.lineTo(-r, cy);
  return s;
}

// ── Escutcheon plate ──
function buildPlate() {
  const outer = new THREE.Shape();
  outer.absarc(0, 0, 1.15, 0, Math.PI * 2, false);

  const hole = new THREE.Path();
  const kp = keyholePath();
  hole.subPath = kp;
  // We need to extract points from the keyhole shape into a Path hole
  const pts = kp.getPoints(64);
  const holePath = new THREE.Path();
  pts.forEach((p, i) => i === 0 ? holePath.moveTo(p.x, p.y) : holePath.lineTo(p.x, p.y));
  outer.holes.push(holePath);

  const geo = new THREE.ExtrudeGeometry(outer, {
    depth: 0.08,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 4,
    curveSegments: 64,
  });
  geo.center();
  return geo;
}

// ── Decorative ring ──
function buildRing(radius, tube, segments) {
  const curve = new THREE.EllipseCurve(0, 0, radius, radius, 0, Math.PI * 2, false, 0);
  const points = curve.getPoints(segments);
  const shape = new THREE.Shape(points.map(p => new THREE.Vector2(p.x, p.y)));
  const inner = new THREE.Path();
  const innerPts = curve.getPoints(segments);
  innerPts.forEach((p, i) => {
    const r2 = radius - tube;
    const angle = (i / segments) * Math.PI * 2;
    i === 0 ? inner.moveTo(r2 * Math.cos(angle), r2 * Math.sin(angle))
            : inner.lineTo(r2 * Math.cos(angle), r2 * Math.sin(angle));
  });
  shape.holes.push(inner);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.015,
    bevelEnabled: true,
    bevelThickness: 0.005,
    bevelSize: 0.005,
    bevelSegments: 2,
    curveSegments: segments,
  });
  geo.translate(0, 0, 0.045);
  return geo;
}

// ── Decorative dots around the keyhole ──
function buildDots(count, radius) {
  const group = new THREE.Group();
  const dotGeo = new THREE.SphereGeometry(0.035, 16, 16);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const dot = new THREE.Mesh(dotGeo, brassDark);
    dot.position.set(Math.cos(angle) * radius, Math.sin(angle) * radius, 0.055);
    group.add(dot);
  }
  return group;
}

// ── Inner shadow ring around keyhole ──
function buildInnerRing() {
  const outerR = 0.52;
  const innerR = 0.48;
  const curve = new THREE.EllipseCurve(0, 0, outerR, outerR, 0, Math.PI * 2, false, 0);
  const pts = curve.getPoints(64);
  const shape = new THREE.Shape(pts.map(p => new THREE.Vector2(p.x, p.y)));
  const inner = new THREE.Path();
  const innerPts = curve.getPoints(64).map(p => {
    const scale = innerR / outerR;
    return new THREE.Vector2(p.x * scale, p.y * scale);
  });
  innerPts.forEach((p, i) => i === 0 ? inner.moveTo(p.x, p.y) : inner.lineTo(p.x, p.y));
  shape.holes.push(inner);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.01,
    bevelEnabled: false,
    curveSegments: 64,
  });
  geo.translate(0, 0, 0.07);
  return geo;
}

// ── Assemble ──
const escutcheon = new THREE.Group();

// Main plate
const plateGeo = buildPlate();
const plate = new THREE.Mesh(plateGeo, brass);
escutcheon.add(plate);

// Decorative outer ring
const ringGeo = buildRing(1.05, 0.06, 128);
const ring = new THREE.Mesh(ringGeo, brassDark);
escutcheon.add(ring);

// Inner shadow ring
const innerRingGeo = buildInnerRing();
const innerRing = new THREE.Mesh(innerRingGeo, brassDark);
escutcheon.add(innerRing);

// Decorative dots
const dots = buildDots(16, 0.82);
escutcheon.add(dots);

// Keyhole interior (dark depth)
const kp2 = keyholePath();
const kpPoints = kp2.getPoints(64);
const holeShape = new THREE.Shape(kpPoints.map(p => new THREE.Vector2(p.x, p.y)));
const holeGeo = new THREE.ExtrudeGeometry(holeShape, {
  depth: 0.12,
  bevelEnabled: false,
  curveSegments: 64,
});
holeGeo.translate(0, 0, -0.06);
const holeMesh = new THREE.Mesh(holeGeo, holeMat);
escutcheon.add(holeMesh);

scene.add(escutcheon);

// ── Lighting ──
const ambient = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambient);

const dir1 = new THREE.DirectionalLight(0xfff5e6, 3);
dir1.position.set(3, 4, 5);
scene.add(dir1);

const dir2 = new THREE.DirectionalLight(0xc8a86e, 1.5);
dir2.position.set(-3, -1, 3);
scene.add(dir2);

const point = new THREE.PointLight(0xffd699, 2, 10);
point.position.set(0, 2, 3);
scene.add(point);

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ── Animate ──
function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
