        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505); // Dark background to see the light

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.z = 5;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        // 2. Environment (Crucial for Glass/Transmission materials to look right)
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        scene.environment = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;

        // 3. The Glass Marble (Outer Shell)
        const glassGeometry = new THREE.SphereGeometry(1, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0.05,
            transmission: 1.0, // Makes it glass-like
            thickness: 1.5,   // Volume for refraction
            ior: 1.5,         // Index of Refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 1
        });
        const glassMarble = new THREE.Mesh(glassGeometry, glassMaterial);
        scene.add(glassMarble);

        // 4. The Swirl Light (Inner Core)
        // Generate a swirl texture procedurally
        const canvas = document.createElement('canvas');
        canvas.width = 512;
        canvas.height = 512;
        const ctx = canvas.getContext('2d');

        // Draw a colorful spiral
        ctx.translate(256, 256);
        ctx.lineWidth = 8;
        for (let i = 0; i < 800; i++) {
            let angle = i * 0.15;
            let radius = i * 0.6;
            let x = Math.cos(angle) * radius;
            let y = Math.sin(angle) * radius;

            ctx.strokeStyle = `hsl(${i * 0.5}, 100%, 60%)`;
            ctx.lineTo(x, y);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(x, y);
        }

        const swirlTexture = new THREE.CanvasTexture(canvas);

        const coreGeometry = new THREE.SphereGeometry(0.75, 32, 32);
        const coreMaterial = new THREE.MeshStandardMaterial({
            map: swirlTexture,
            emissive: 0xffffff,
            emissiveMap: swirlTexture,
            emissiveIntensity: 3, // Make it glow
            roughness: 0.4,
            metalness: 0.1
        });
        const core = new THREE.Mesh(coreGeometry, coreMaterial);
        scene.add(core);

        // 5. Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate the inner swirl
            core.rotation.y = time * 0.5;
            core.rotation.z = time * 0.2;

            // Gentle floating motion for the whole marble
            glassMarble.position.y = Math.sin(time) * 0.1;
            core.position.y = glassMarble.position.y;

            renderer.render(scene, camera);
        }

        animate();

        // 6. Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
