  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#808080';
  ctx.fillRect(0, 0, 512, 512);

  const spacing = 6;
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 1.5;

  for (let i = -512; i < 1024; i += spacing) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 512, 512); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(i + 512, 0); ctx.lineTo(i, 512); ctx.stroke();
  }
  ctx.strokeStyle = '#bbb';
  ctx.lineWidth = 0.8;
  for (let i = -512; i < 1024; i += spacing) {
    ctx.beginPath(); ctx.moveTo(i + 3, 0); ctx.lineTo(i + 515, 512); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(i + 515, 0); ctx.lineTo(i + 3, 512); ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(8, 1);
  return tex;
}

function makeNormalKnurl() {
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#8080ff';
  ctx.fillRect(0, 0, 512, 512);

  const sp = 6;
  for (let i = -512; i < 1024; i += sp) {
    ctx.strokeStyle = '#6060ff';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 512, 512); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(i + 512, 0); ctx.lineTo(i, 512); ctx.stroke();
    ctx.strokeStyle = '#a0a0ff';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(i + 2, 0); ctx.lineTo(i + 514, 512); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(i + 514, 0); ctx.lineTo(i + 2, 512); ctx.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(8, 1);
  return tex;
}

