// Create a procedural environment
function createEnvironment() {
  const envScene = new THREE.Scene();

  // Gradient sky dome
  const skyGeo = new THREE.SphereGeometry(50, 32, 32);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
