}

const envScene = createEnvironment();
const envMap = pmremGenerator.fromScene(envScene, 0.04).texture;
scene.environment = envMap;

// ── Swirl Marble Geometry ────────────────────────────────
function createSwirlGeometry(radius, detail, twistAmount, segments) {
  const geometry = new THREE.IcosahedronGeometry(radius, detail);
  const pos = geometry.attributes.position;
  const vec = new THREE.Vector3();

  for (let i = 0; i < pos.count; i++) {
    vec.fromBufferAttribute(pos, i);

    // Twist based on Y position
    const twist = vec.y * twistAmount;
    const cosT = Math.cos(twist);
    const sinT = Math.sin(twist);
    const x = vec.x * cosT - vec.z * sinT;
    const z = vec.x * sinT + vec.z * cosT;

    // Marble shape: slightly elongated with pinch
    const yNorm = vec.y / radius;
    const pinch = 1.0 - 0.15 * Math.abs(yNorm) + 0.3 * (1.0 - yNorm * yNorm);

    // Add subtle waviness for organic feel
    const wave = 1.0 + 0.04 * Math.sin(vec.x * 4.0 + vec.y * 6.0 + vec.z * 4.0);

    pos.setXYZ(i, x * pinch * wave, vec.y * 1.15, z * pinch * wave);
  }

  geometry.computeVertexNormals();
  return geometry;
}

// ── Glass Material ───────────────────────────────────────
function createGlassMaterial(color) {
  return new THREE.MeshPhysicalMaterial({
    color: color,
    metalness: 0.0,
    roughness: 0.02,
    transmission: 0.95,
    thickness: 1.5,
    ior: 1.52,
