// ── Floating Mini Marbles ────────────────────────────────
const miniMarbles = [];
const miniConfigs = [
  { pos: [3.5, 3.5, 1], scale: 0.5, twist: 2.0, color: 0x88ffcc, speed: 0.3, offset: 0 },
  { pos: [-3, 1.5, -1.5], scale: 0.4, twist: -3.0, color: 0xffcc88, speed: -0.25, offset: 1 },
