// ── Animation ────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Main marble gentle rotation
  mainMarble.rotation.y = t * 0.15;
  mainMarble.position.y = 2.2 + Math.sin(t * 0.5) * 0.15;

  innerMarble.rotation.y = -t * 0.3;
  innerMarble.rotation.x = Math.sin(t * 0.4) * 0.2;
  innerMarble.position.y = 2.2 + Math.sin(t * 0.5) * 0.15;

  // Mini marbles float and rotate
  miniMarbles.forEach(m => {
    m.mesh.rotation.y = t * m.cfg.speed;
    m.mesh.rotation.x = Math.sin(t * 0.3 + m.cfg.offset) * 0.3;
    m.mesh.position.y = m.cfg.pos[1] + Math.sin(t * 0.4 + m.cfg.offset * 1.5) * 0.3;
    m.mesh.position.x = m.cfg.pos[0] + Math.sin(t * 0.2 + m.cfg.offset) * 0.2;
  });

  // Animate point lights
  pointLight1.position.x = Math.sin(t * 0.5) * 4;
  pointLight1.position.z = Math.cos(t * 0.5) * 4;
  pointLight2.position.x = Math.cos(t * 0.3) * 3;
  pointLight2.position.z = Math.sin(t * 0.3) * 3;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ───────────────────────────────────────────────
