// ── Swirl Texture (procedural) ──
function createSwirlTexture(size = 1024) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');

  const cx = size / 2, cy = size / 2;

  // Base gradient
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, cx);
  grad.addColorStop(0, '#ff6b35');
  grad.addColorStop(0.3, '#ff3366');
  grad.addColorStop(0.6, '#8b5cf6');
  grad.addColorStop(1, '#1e3a5f');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Swirl arms
  for (let arm = 0; arm < 5; arm++) {
    const baseAngle = (arm / 5) * Math.PI * 2;
    ctx.beginPath();
    for (let i = 0; i < 300; i++) {
      const t = i / 300;
      const angle = baseAngle + t * Math.PI * 4;
      const radius = t * cx * 0.9;
      const wobble = Math.sin(t * 20 + arm) * 8 * t;
      const x = cx + Math.cos(angle) * (radius + wobble);
      const y = cy + Math.sin(angle) * (radius + wobble);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    const hue = (arm * 72 + 10) % 360;
    ctx.strokeStyle = `hsla(${hue}, 90%, 65%, 0.5)`;
    ctx.lineWidth = 3 + Math.random() * 4;
    ctx.lineCap = 'round';
    ctx.stroke();
  }

  // Bright core swirls
  for (let arm = 0; arm < 3; arm++) {
    const baseAngle = (arm / 3) * Math.PI * 2 + 0.5;
    ctx.beginPath();
    for (let i = 0; i < 200; i++) {
      const t = i / 200;
      const angle = baseAngle + t * Math.PI * 5;
      const radius = t * cx * 0.6;
      const x = cx + Math.cos(angle) * radius;
      const y = cy + Math.sin(angle) * radius;
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.strokeStyle = `hsla(${arm * 120 + 200}, 100%, 80%, 0.6)`;
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Noise speckles
  for (let i = 0; i < 2000; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r = Math.random() * cx;
    const x = cx + Math.cos(angle) * r;
    const y = cy + Math.sin(angle) * r;
    const brightness = 40 + Math.random() * 60;
    ctx.fillStyle = `hsla(${Math.random()*360}, 80%, ${brightness}%, ${Math.random()*0.3})`;
    ctx.fillRect(x, y, 2, 2);
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// ── Marble Group ──
const marbleGroup = new THREE.Group();
marbleGroup.position.y = 1;
scene.add(marbleGroup);

// Inner swirl sphere
const swirlGeo = new THREE.SphereGeometry(0.88, 64, 64);
