  swirlMesh.rotation.y = -t * 0.15;
  swirlMesh.rotation.x = Math.sin(t * 0.2) * 0.1;

  // Gentle float
  marbleGroup.position.y = 1 + Math.sin(t * 0.8) * 0.1;

  renderer.render(scene, camera);
}

animate();

