const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(2, 1.5, 3);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

const brass = new THREE.MeshStandardMaterial({
  color: 0xb8860b,
  metalness: 0.95,
  roughness: 0.22,
  envMapIntensity: 1.5,
});

const darkBrass = new THREE.MeshStandardMaterial({
  color: 0x8b6914,
  metalness: 0.93,
  roughness: 0.35,
  envMapIntensity: 1.2,
});

const group = new THREE.Group();

// --- Main handle body via LatheGeometry ---
const handlePoints = [];
const steps = 40;
for (let i = 0; i <= steps; i++) {
  const t = i / steps;
  const y = t * 2.2;

  let r;
  if (t < 0.05) {
    r = 0.18 + t * 4;
  } else if (t < 0.15) {
    r = 0.38 - (t - 0.05) * 0.3;
  } else if (t < 0.55) {
    const s = (t - 0.15) / 0.4;
    r = 0.35 + Math.sin(s * Math.PI) * 0.12;
  } else if (t < 0.75) {
    const s = (t - 0.55) / 0.2;
    r = 0.35 - s * 0.1;
  } else if (t < 0.9) {
    const s = (t - 0.75) / 0.15;
    r = 0.25 + s * 0.08;
  } else {
    const s = (t - 0.9) / 0.1;
    r = 0.33 + s * 0.07;
  }

  handlePoints.push(new THREE.Vector2(r, y));
}

const handleGeo = new THREE.LatheGeometry(handlePoints, 48);
const handle = new THREE.Mesh(handleGeo, brass);
group.add(handle);

// --- Top bulb (knob) ---
const knobGeo = new THREE.SphereGeometry(0.32, 32, 24, 0, Math.PI * 2, 0, Math.PI * 0.6);
const knob = new THREE.Mesh(knobGeo, brass);
knob.position.y = 2.2;
knob.rotation.x = Math.PI;
group.add(knob);

// --- Top cap ---
const capGeo = new THREE.CylinderGeometry(0.32, 0.32, 0.06, 48);
const cap = new THREE.Mesh(capGeo, darkBrass);
cap.position.y = 2.45;
group.add(cap);

// --- Decorative rings ---
const ringPositions = [0.35, 0.7, 1.1, 1.5, 1.85];
ringPositions.forEach((y, i) => {
  const ringGeo = new THREE.TorusGeometry(
    i % 2 === 0 ? 0.38 : 0.34,
    i % 2 === 0 ? 0.035 : 0.025,
    12, 48
  );
  const ring = new THREE.Mesh(ringGeo, i % 2 === 0 ? darkBrass : brass);
  ring.position.y = y;
  ring.rotation.x = Math.PI / 2;
  group.add(ring);
});

// --- Bottom mounting flange ---
const flangeGeo = new THREE.CylinderGeometry(0.42, 0.38, 0.12, 48);
const flange = new THREE.Mesh(flangeGeo, darkBrass);
flange.position.y = 0.06;
group.add(flange);

// --- Mounting plate (flat disc at bottom) ---
const plateGeo = new THREE.CylinderGeometry(0.5, 0.5, 0.04, 48);
const plate = new THREE.Mesh(plateGeo, brass);
plate.position.y = 0.02;
group.add(plate);

// --- Screws on plate ---
for (let i = 0; i < 4; i++) {
  const angle = (i / 4) * Math.PI * 2 + Math.PI / 4;
  const screwGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.06, 8);
