  const head = new THREE.Mesh(headGeo, darkBrass);
  head.position.set(Math.cos(angle) * 0.35, 0.06, Math.sin(angle) * 0.35);
  group.add(head);
}

// --- Small decorative engravings (torus bands) ---
const engravingPositions = [0.5, 0.9, 1.3, 1.7];
engravingPositions.forEach(y => {
  const engrGeo = new THREE.TorusGeometry(0.36, 0.008, 8, 48);
  const engr = new THREE.Mesh(engrGeo, darkBrass);
  engr.position.y = y;
  engr.rotation.x = Math.PI / 2;
  group.add(engr);
});

// --- Frame attachment bracket (side arm) ---
const bracketShape = new THREE.Shape();
bracketShape.moveTo(0, 0);
bracketShape.quadraticCurveTo(0.6, 0.15, 0.7, 0.5);
bracketShape.lineTo(0.55, 0.55);
bracketShape.quadraticCurveTo(0.4, 0.25, 0, 0.1);
bracketShape.closePath();

const bracketGeo = new THREE.ExtrudeGeometry(bracketShape, {
  depth: 0.06,
  bevelEnabled: true,
  bevelThickness: 0.015,
  bevelSize: 0.015,
  bevelSegments: 4,
  curveSegments: 16,
});
const bracket = new THREE.Mesh(bracketGeo, brass);
bracket.position.set(0.35, 0.8, -0.03);
bracket.rotation.y = 0.1;
group.add(bracket);

// --- Pivot pin on bracket ---
const pinGeo = new THREE.CylinderGeometry(0.04, 0.04, 0.12, 16);
const pin = new THREE.Mesh(pinGeo, darkBrass);
pin.position.set(0.7, 0.55, 0.06);
pin.rotation.x = Math.PI / 2;
group.add(pin);

// Center the model
const box = new THREE.Box3().setFromObject(group);
const center = box.getCenter(new THREE.Vector3());
group.position.sub(center);
group.position.y -= 0.2;
scene.add(group);

// --- Lighting ---
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899bb, 1);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffccaa, 2);
rimLight.position.set(-2, 3, -5);
scene.add(rimLight);

// --- Controls ---
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.autoRotate = true;
controls.autoRotateSpeed = 1.2;
controls.update();

// --- Animate ---
function animate(time) {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
