            clearcoatRoughness: 0.0,
            transparent: true,
            opacity: 1.0
        });
        const globe = new THREE.Mesh(globeGeometry, globeMaterial);
        scene.add(globe);

        // Snow Drift (Base)
        // Create a shape that looks like accumulated snow at the bottom
        const driftGroup = new THREE.Group();

        // Base cylinder
        const baseGeo = new THREE.CylinderGeometry(1.9, 1.9, 0.2, 64);
        const snowMat = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 0.9, 
            metalness: 0.0 
        });
        const baseMesh = new THREE.Mesh(baseGeo, snowMat);
        baseMesh.position.y = -1.8;
        driftGroup.add(baseMesh);

        // Snow mound
        const moundGeo = new THREE.SphereGeometry(1.8, 64, 32, 0, Math.PI * 2, 0, Math.PI / 2.5);
        const moundMesh = new THREE.Mesh(moundGeo, snowMat);
        moundMesh.position.y = -1.8;
        driftGroup.add(moundMesh);

