            requestAnimationFrame(animate);

            // Rotate the whole globe slightly
            globe.rotation.y += 0.002;
            driftGroup.rotation.y += 0.002;
            particles.rotation.y += 0.002;

            // Animate snow falling
            const posAttribute = particles.geometry.attributes.position;
            for (let i = 0; i < particlesCount; i++) {
                let y = posAttribute.getY(i);
                let x = posAttribute.getX(i);
                let z = posAttribute.getZ(i);

                // Apply velocity
                y += velocities[i].y;
                x += velocities[i].x;
                z += velocities[i].z;

                // Reset if hits bottom (approximate drift level)
                if (y < -1.5) {
                    y = 1.5;
                    x = (Math.random() - 0.5) * 3;
                    z = (Math.random() - 0.5) * 3;
                }

                posAttribute.setXYZ(i, x, y, z);
            }
            posAttribute.needsUpdate = true;

            renderer.render(scene, camera);
        }

        animate();

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
