            canvas.height = size;
            const ctx = canvas.getContext('2d');

            const gradient = ctx.createRadialGradient(size/2, size/2, 0, size/2, size/2, size/2);
            gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
            gradient.addColorStop(0.2, 'rgba(200, 240, 255, 0.6)');
            gradient.addColorStop(0.5, 'rgba(100, 100, 255, 0.2)');
            gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, size, size);

            return new THREE.CanvasTexture(canvas);
        }

        // The Marble Group
        const marbleGroup = new THREE.Group();
        scene.add(marbleGroup);

        // 1. The Inner Swirl Core
        const swirlTexture = createSwirlTexture();
        const coreGeometry = new THREE.SphereGeometry(0.7, 64, 64);
        const coreMaterial = new THREE.MeshStandardMaterial({
            map: swirlTexture,
            emissive: 0xffffff,
            emissiveMap: swirlTexture,
            emissiveIntensity: 0.8,
            roughness: 0.4,
            metalness: 0.1
        });
        const coreMesh = new THREE.Mesh(coreGeometry, coreMaterial);
        marbleGroup.add(coreMesh);

        // 2. The Glass Shell
        const glassGeometry = new THREE.SphereGeometry(1, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,     // Volume for refraction
            ior: 1.5,           // Index of refraction
            clearcoat: 1,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1
        });
        const glassMesh = new THREE.Mesh(glassGeometry, glassMaterial);
        marbleGroup.add(glassMesh);

        // 3. The Glow
        const glowTexture = createGlowTexture();
        const glowMaterial = new THREE.SpriteMaterial({ 
            map: glowTexture, 
            color: 0xaaccff, 
            transparent: true, 
            opacity: 0.6,
            blending: THREE.AdditiveBlending
        });
        const glowSprite = new THREE.Sprite(glowMaterial);
        glowSprite.scale.set(4, 4, 1);
        marbleGroup.add(glowSprite);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const pointLight1 = new THREE.PointLight(0x00ffff, 50, 10);
        pointLight1.position.set(2, 2, 2);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xff00ff, 50, 10);
        pointLight2.position.set(-2, -2, 2);
        scene.add(pointLight2);

        const pointLight3 = new THREE.PointLight(0xffff00, 30, 10);
        pointLight3.position.set(0, 2, -2);
        scene.add(pointLight3);

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Rotate the marble
            marbleGroup.rotation.y += 0.005;
            marbleGroup.rotation.x += 0.002;

            // Pulse the glow slightly
            const time = Date.now() * 0.001;
            glowSprite.material.opacity = 0.5 + Math.sin(time) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
