            const markerGeo = new THREE.BoxGeometry(0.05, 0.05, 0.3);
            const marker = new THREE.Mesh(markerGeo, new THREE.MeshStandardMaterial({ color: 0x111111 }));
            marker.position.x = Math.sin(angle) * 1.8;
            marker.position.z = Math.cos(angle) * 1.8;
            marker.position.y = 0.21;
            marker.rotation.y = -angle;
            marker.receiveShadow = true;
            sundialGroup.add(marker);
        }

        // Gnomon (The stick that casts the shadow)
        // Angled at approx 45 degrees for visual effect
        const gnomonGroup = new THREE.Group();
        gnomonGroup.position.y = 0.2;
        sundialGroup.add(gnomonGroup);

        const gnomonGeo = new THREE.BoxGeometry(0.1, 0.1, 2.5);
        const gnomon = new THREE.Mesh(gnomonGeo, brassMaterial);
        gnomon.position.z = 0.5; // Offset pivot
        gnomon.rotation.x = Math.PI / 4; // Angle it up
        gnomon.castShadow = true;
        gnomon.receiveShadow = true;
        gnomonGroup.add(gnomon);

        // Ground Plane (to catch shadow if it falls off the dial)
        const groundGeo = new THREE.PlaneGeometry(100, 100);
        const ground = new THREE.Mesh(groundGeo, stoneMaterial);
        ground.rotation.x = -Math.PI / 2;
