            // 6:00 -> -PI/2 (Left)
            // 12:00 -> 0 (Front/High) - actually let's do a semi-circle arc
            // 18:00 -> PI/2 (Right)

            const normalizedTime = (timeVal - 6) / 12; // 0 to 1
            const angle = (normalizedTime * Math.PI) - (Math.PI / 2); // -PI/2 to PI/2

            const radius = 10;
            const height = 5 + Math.sin(normalizedTime * Math.PI) * 5; // Arc height

            sunLight.position.set(
                Math.cos(angle) * radius,
                height,
                Math.sin(angle) * radius
            );

            sunLight.lookAt(0, 0, 0);
            sunHelper.position.copy(sunLight.position);
        }

