    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Glass Marble Swirl</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
        #info {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: #888;
            font-family: sans-serif;
            pointer-events: none;
            font-size: 12px;
        }
    </style>
</head>
<body>
    <div id="info">drag to orbit &bull; scroll to zoom</div>

    <!-- Import Three.js as an ES module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        // Add some fog for depth
        scene.fog = new THREE.Fog(0x111111, 5, 15);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 5);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        // 2. Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // 3. Create Swirl Texture Procedurally
        function createSwirlTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Fill background
            ctx.fillStyle = '#000000';
            ctx.fillRect(0, 0, size, size);

            const centerX = size / 2;
            const centerY = size / 2;

            // Draw swirl using pixels
            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;

            for (let y = 0; y < size; y++) {
                for (let x = 0; x < size; x++) {
                    const dx = x - centerX;
                    const dy = y - centerY;
                    const dist = Math.sqrt(dx * dx + dy * dy);
                    const angle = Math.atan2(dy, dx);

                    // Swirl math
                    const swirl = angle + dist * 0.02;
                    const noise = Math.sin(dist * 0.05) * 0.5 + 0.5;

                    // Color mapping (HSL-ish logic manually for speed)
                    const hue = (swirl * 50 + 200) % 360; 
                    const sat = 80 + noise * 20;
                    const light = 40 + noise * 30;

                    // Simple HSL to RGB conversion approximation or just use canvas gradients?
                    // Let's use a simpler approach: Radial gradients for bands
                }
            }

            // Actually, drawing pixel by pixel in JS is slow. Let's use canvas gradients for a cleaner look.
            ctx.clearRect(0,0,size,size);

            // Create a complex gradient pattern
            const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, size/2);
            gradient.addColorStop(0, '#ffffff');
            gradient.addColorStop(0.2, '#ff0055');
            gradient.addColorStop(0.4, '#00ddff');
            gradient.addColorStop(0.6, '#aa00ff');
            gradient.addColorStop(0.8, '#00ffaa');
            gradient.addColorStop(1, '#111111');

            ctx.fillStyle = gradient;
            ctx.fillRect(0,0,size,size);

            // Add some "swirl" distortion by drawing rotated arcs
            ctx.globalCompositeOperation = 'overlay';
            for(let i=0; i<20; i++) {
                ctx.beginPath();
                ctx.arc(centerX, centerY, i * 20 + 50, 0, Math.PI * 2);
                ctx.strokeStyle = `hsl(${i * 30}, 70%, 50%)`;
                ctx.lineWidth = 10 + Math.random() * 20;
                ctx.stroke();
            }

            // Add noise/grain
            const imgData = ctx.getImageData(0,0,size,size);
            for(let i=0; i<imgData.data.length; i+=4) {
                const noise = (Math.random() - 0.5) * 30;
                imgData.data[i] += noise;
                imgData.data[i+1] += noise;
                imgData.data[i+2] += noise;
            }
            ctx.putImageData(imgData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // 4. Create the Marble
        const geometry = new THREE.SphereGeometry(1, 64, 64);

        // Glass Material
        const material = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            map: swirlTexture, // The swirl pattern
            roughness: 0.1,
            metalness: 0.1,
            transmission: 0.95, // Glass-like transparency
            thickness: 1.5, // Volume for refraction
            ior: 1.5, // Index of refraction for glass
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.0,
            side: THREE.DoubleSide
        });

        const marble = new THREE.Mesh(geometry, material);
        scene.add(marble);

        // 5. Lighting
        // Ambient light for base visibility
        const ambientLight = new THREE.AmbientLight(0x404040, 2); 
        scene.add(ambientLight);

        // Main directional light (sun)
        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 5, 5);
        scene.add(dirLight);

        // Back light for rim lighting
        const backLight = new THREE.DirectionalLight(0xffffff, 2);
        backLight.position.set(-5, 0, -5);
        scene.add(backLight);

        // Point lights for colorful reflections
        const pointLight1 = new THREE.PointLight(0xff0055, 10, 20);
        pointLight1.position.set(2, 2, 2);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0x0055ff, 10, 20);
        pointLight2.position.set(-2, -2, 2);
        scene.add(pointLight2);

        // 6. Environment Map (Crucial for glass to look good)
        // Since we don't have an external HDR file, we create a simple PMREM from a scene or use a CubeCamera
        // For a single file without assets, a simple CubeCamera reflecting the scene is best, 
        // but that requires two render passes. 
        // Alternatively, we can just rely on the lights and the background. 
        // To make it look "glassy", we need reflections. 
        // Let's add a simple CubeCamera to capture the environment.

        const cubeRenderTarget = new THREE.WebGLCubeRenderTarget(256);
        const cubeCamera = new THREE.CubeCamera(0.1, 100, cubeRenderTarget);
        scene.add(cubeCamera);

        // We need to hide the marble while rendering the environment map to avoid infinite recursion
        // But for a simple demo, we can just set the envMap to the cubeRenderTarget texture
        // and update it occasionally.

        // Actually, for a single object, a simple gradient background often acts as a decent env map if we use PMREMGenerator
        // But let's stick to the lights. The transmission property handles the "glass" look well enough with lights.

        // Let's create a simple environment using a large sphere with a gradient texture behind it
        const envGeo = new THREE.SphereGeometry(20, 32, 32);
        const envMat = new THREE.MeshBasicMaterial({ 
            map: swirlTexture, 
            side: THREE.BackSide 
        });
        const envMesh = new THREE.Mesh(envGeo, envMat);
        scene.add(envMesh);

        // Update material envMap
        material.envMap = cubeRenderTarget.texture;

        // 7. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Rotate the marble slowly
            marble.rotation.y += 0.005;
            marble.rotation.x += 0.002;

            // Update controls
            controls.update();

            // Update CubeCamera (render environment)
            // Hide marble so it doesn't reflect itself infinitely in the env map generation
            marble.visible = false;
            cubeCamera.position.copy(marble.position);
            cubeCamera.update(renderer, scene);
            marble.visible = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
