<body>
    <div id="info">Brass Telescope Stand — drag to orbit, scroll to zoom</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a1a);
        scene.fog = new THREE.Fog(0x1a1a1a, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(8, 6, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 3, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeebb, 2);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 1, 10);
        pointLight.position.set(-2, 5, 2);
        scene.add(pointLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xd4af37, // Brass color
            metalness: 0.9,
            roughness: 0.3,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            metalness: 0.8,
            roughness: 0.5,
        });

        // Group for the whole stand
        const standGroup = new THREE.Group();
        scene.add(standGroup);

        // 1. Base
        const baseGeo = new THREE.CylinderGeometry(2.5, 3, 0.5, 32);
        const base = new THREE.Mesh(baseGeo, brassMaterial);
        base.position.y = 0.25;
        base.castShadow = true;
        base.receiveShadow = true;
        standGroup.add(base);

        // Base Ring Detail
        const ringGeo = new THREE.TorusGeometry(2.5, 0.1, 16, 32);
        const ring = new THREE.Mesh(ringGeo, brassMaterial);
        ring.rotation.x = Math.PI / 2;
        ring.position.y = 0.5;
        standGroup.add(ring);

        // 2. Main Column
        const columnGeo = new THREE.CylinderGeometry(0.4, 0.6, 4, 16);
        const column = new THREE.Mesh(columnGeo, brassMaterial);
        column.position.y = 2.5;
        column.castShadow = true;
        standGroup.add(column);

        // 3. Horizontal Arm (The part holding the telescope)
        const armGroup = new THREE.Group();
        armGroup.position.y = 4.5;
        standGroup.add(armGroup);

        // Pivot joint
        const pivotGeo = new THREE.SphereGeometry(0.6, 16, 16);
        const pivot = new THREE.Mesh(pivotGeo, brassMaterial);
        armGroup.add(pivot);

        // The arm itself
        const armGeo = new THREE.CylinderGeometry(0.3, 0.3, 3, 16);
        const arm = new THREE.Mesh(armGeo, brassMaterial);
        arm.rotation.z = Math.PI / 2;
        arm.position.x = 1.5;
        arm.castShadow = true;
        armGroup.add(arm);

        // 4. Telescope Tube
        const telescopeGroup = new THREE.Group();
        telescopeGroup.position.set(3, 0, 0); // End of arm
        armGroup.add(telescopeGroup);

        // Main tube
        const tubeGeo = new THREE.CylinderGeometry(0.5, 0.6, 4, 32);
        const tube = new THREE.Mesh(tubeGeo, brassMaterial);
        tube.rotation.z = Math.PI / 2;
        tube.position.x = 2;
        tube.castShadow = true;
        telescopeGroup.add(tube);

        // Decorative rings on tube
        const tubeRingGeo = new THREE.TorusGeometry(0.55, 0.05, 8, 32);
        const tubeRing1 = new THREE.Mesh(tubeRingGeo, brassMaterial);
        tubeRing1.rotation.y = Math.PI / 2;
        tubeRing1.position.set(1, 0, 0);
        telescopeGroup.add(tubeRing1);

        const tubeRing2 = new THREE.Mesh(tubeRingGeo, brassMaterial);
        tubeRing2.rotation.y = Math.PI / 2;
        tubeRing2.position.set(3, 0, 0);
        telescopeGroup.add(tubeRing2);

        // Eyepiece
        const eyeGeo = new THREE.CylinderGeometry(0.2, 0.3, 1, 16);
        const eye = new THREE.Mesh(eyeGeo, darkMetalMaterial);
        eye.rotation.z = Math.PI / 2;
        eye.position.set(4.2, 0.2, 0);
        telescopeGroup.add(eye);

        // Finder scope (smaller tube on top)
        const finderGeo = new THREE.CylinderGeometry(0.15, 0.15, 1.5, 16);
        const finder = new THREE.Mesh(finderGeo, brassMaterial);
        finder.rotation.z = Math.PI / 2;
        finder.position.set(2, 0.6, 0);
        telescopeGroup.add(finder);

        // Finder brackets
        const bracketGeo = new THREE.CylinderGeometry(0.16, 0.16, 0.2, 16);
        const bracket1 = new THREE.Mesh(bracketGeo, brassMaterial);
        bracket1.rotation.z = Math.PI / 2;
        bracket1.position.set(1.5, 0.6, 0);
        telescopeGroup.add(bracket1);

        const bracket2 = new THREE.Mesh(bracketGeo, brassMaterial);
        bracket2.rotation.z = Math.PI / 2;
        bracket2.position.set(2.5, 0.6, 0);
        telescopeGroup.add(bracket2);

        // Floor
        const floorGeo = new THREE.PlaneGeometry(50, 50);
        const floorMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
