  pointer-events: none; letter-spacing: 2px;
}
</style>
</head>
<body>
<div id="info">⟡ Brass Key Ring ⟡</div>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Environment map for realistic reflections ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 0, 0);
controls.autoRotate = true;
controls.autoRotateSpeed = 1.2;

// ── Brass material ──
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xc9a84c,
  metalness: 0.95,
  roughness: 0.18,
  clearcoat: 0.3,
  clearcoatRoughness: 0.1,
  envMapIntensity: 1.5,
});

const darkBrassMat = new THREE.MeshPhysicalMaterial({
  color: 0x8b7230,
  metalness: 0.93,
  roughness: 0.25,
  clearcoat: 0.2,
  envMapIntensity: 1.2,
});

// ── Spring ring curve ──
function createSpringRingCurve(R, r, coils, segments) {
  const points = [];
  const totalSteps = coils * segments;
  const gap = 0.08; // small gap in the ring

  for (let i = 0; i <= totalSteps; i++) {
    let theta = (i / totalSteps) * Math.PI * 2;

    // Skip the gap region
    if (theta > Math.PI * 1.85 && theta < Math.PI * 2 - gap) continue;

    const nTheta = theta * coils;
    const x = (R + r * Math.cos(nTheta)) * Math.cos(theta);
    const y = (R + r * Math.cos(nTheta)) * Math.sin(theta);
    const z = r * Math.sin(nTheta);
    points.push(new THREE.Vector3(x, y, z));
  }
  return new THREE.CatmullRomCurve3(points);
}

const ringCurve = createSpringRingCurve(1.0, 0.06, 28, 40);
const ringGeo = new THREE.TubeGeometry(ringCurve, 1200, 0.035, 12, false);
const ring = new THREE.Mesh(ringGeo, brassMat);
scene.add(ring);

// ── Key helper ──
function createKey(scale = 1, angle = 0) {
  const group = new THREE.Group();

  // Key head (bow) – circular ring
  const bowGeo = new THREE.TorusGeometry(0.22 * scale, 0.04 * scale, 12, 24);
  const bow = new THREE.Mesh(bowGeo, darkBrassMat);
  bow.position.y = 0.9 * scale;
  group.add(bow);

  // Inner circle of bow
  const innerBowGeo = new THREE.TorusGeometry(0.12 * scale, 0.025 * scale, 8, 20);
  const innerBow = new THREE.Mesh(innerBowGeo, darkBrassMat);
  innerBow.position.y = 0.9 * scale;
  group.add(innerBow);

  // Key shaft
  const shaftGeo = new THREE.CylinderGeometry(0.025 * scale, 0.025 * scale, 0.8 * scale, 8);
  const shaft = new THREE.Mesh(shaftGeo, darkBrassMat);
  shaft.position.y = 0.45 * scale;
  group.add(shaft);

  // Key blade (flat part)
  const bladeGeo = new THREE.BoxGeometry(0.08 * scale, 0.6 * scale, 0.015 * scale);
  const blade = new THREE.Mesh(bladeGeo, darkBrassMat);
  blade.position.set(0.025 * scale, 0.2 * scale, 0);
  group.add(blade);

  // Teeth
  const toothPositions = [
    { y: 0.45, w: 0.06 },
    { y: 0.28, w: 0.05 },
    { y: 0.12, w: 0.07 },
  ];
  toothPositions.forEach(t => {
    const toothGeo = new THREE.BoxGeometry(t.w * scale, 0.04 * scale, 0.018 * scale);
    const tooth = new THREE.Mesh(toothGeo, darkBrassMat);
    tooth.position.set(0.065 * scale, t.y * scale, 0);
    group.add(tooth);
  });

  // Key tip
  const tipGeo = new THREE.SphereGeometry(0.028 * scale, 8, 8);
  const tip = new THREE.Mesh(tipGeo, darkBrassMat);
  tip.position.y = 0.85 * scale;
  group.add(tip);

  group.rotation.z = angle;
  return group;
}

// ── Attach keys to the ring ──
const keys = [];

// Key 1
const key1 = createKey(1.0, -0.15);
key1.position.set(0, -0.55, 0);
key1.rotation.x = 0.1;
scene.add(key1);
keys.push(key1);

// Key 2
const key2 = createKey(0.9, 0.2);
key2.position.set(0.3, -0.5, 0.2);
key2.rotation.x = -0.15;
key2.rotation.y = 0.4;
scene.add(key2);
keys.push(key2);

// Key 3
const key3 = createKey(0.85, -0.05);
key3.position.set(-0.25, -0.45, 0.25);
key3.rotation.x = 0.08;
key3.rotation.y = -0.35;
scene.add(key3);
keys.push(key3);

// ── Subtle ground reflection plane ──
const planeGeo = new THREE.PlaneGeometry(30, 30);
const planeMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e,
  metalness: 0.5,
  roughness: 0.6,
});
const plane = new THREE.Mesh(planeGeo, planeMat);
plane.rotation.x = -Math.PI / 2;
plane.position.y = -2.5;
scene.add(plane);

// ── Subtle lighting ──
const ambient = new THREE.AmbientLight(0xffeedd, 0.3);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xfff4e0, 1.5);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0xc8b8ff, 0.4);
fillLight.position.set(-4, 2, -3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffd680, 1.0, 15);
rimLight.position.set(-3, 1, -2);
scene.add(rimLight);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle bob
  ring.position.y = Math.sin(t * 0.8) * 0.05;
  keys.forEach((k, i) => {
    k.position.y = -0.5 - i * 0.05 + Math.sin(t * 0.8 + i * 0.5) * 0.04;
  });

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
