</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a0c);
scene.fog = new THREE.FogExp2(0x0a0a0c, 0.08);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0.3, 0);
controls.minDistance = 2;
controls.maxDistance = 12;

// --- Brass material ---
const brass = new THREE.MeshPhysicalMaterial({
  color: 0xc8a24e,
  metalness: 0.95,
  roughness: 0.18,
  clearcoat: 0.4,
  clearcoatRoughness: 0.1,
  reflectivity: 1.0,
});

// --- Compass needle tip via LatheGeometry ---
const tipProfile = [];
const segments = 32;

// Teardrop profile: point → full belly → slight taper at base
for (let i = 0; i <= segments; i++) {
  const t = i / segments;
  let r;
  if (t < 0.05) {
    // sharp tip
    r = t / 0.05 * 0.06;
  } else if (t < 0.5) {
    // curve out to belly
    const s = (t - 0.05) / 0.45;
    r = 0.06 + s * 0.34;
  } else if (t < 0.85) {
    // gentle taper
    const s = (t - 0.5) / 0.35;
    r = 0.4 - s * 0.06;
  } else {
    // base
    const s = (t - 0.85) / 0.15;
    r = 0.34 - s * 0.04;
  }
  tipProfile.push(new THREE.Vector2(r, t * 3.0 - 0.2));
}

const tipGeo = new THREE.LatheGeometry(tipProfile, 64);
const tip = new THREE.Mesh(tipGeo, brass);
tip.rotation.x = Math.PI / 2;
tip.position.set(0, 0.3, 0);
scene.add(tip);

// --- Polished base ring ---
const ringGeo = new THREE.TorusGeometry(0.38, 0.03, 16, 64);
const ring = new THREE.Mesh(ringGeo, brass);
ring.position.set(0, -0.05, 0);
ring.rotation.x = Math.PI / 2;
scene.add(ring);

// --- Small pivot pin ---
