keyLight.position.set(3, 5, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc8d4ff, 1.0);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffe8c0, 2.0);
rimLight.position.set(0, 1, -5);
scene.add(rimLight);

const ambient = new THREE.AmbientLight(0x222233, 0.5);
scene.add(ambient);

// --- Small point light for a hot specular spot ---
const spot = new THREE.PointLight(0xffffff, 5, 10);
spot.position.set(1.5, 3, 2);
scene.add(spot);

// --- Subtle ground plane ---
const groundGeo = new THREE.CircleGeometry(4, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111115,
  metalness: 0.5,
  roughness: 0.8,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.19;
scene.add(ground);

// --- Animation ---
function animate(time) {
  requestAnimationFrame(animate);
  // Gentle float
  tip.position.y = 0.3 + Math.sin(time * 0.001) * 0.04;
  ring.position.y = -0.05 + Math.sin(time * 0.001) * 0.04;
  pin.position.y = -0.12 + Math.sin(time * 0.001) * 0.04;
  controls.update();
  renderer.render(scene, camera);
}
animate(0);

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
