<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a0f);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0.5, 4);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0, 0);
controls.minDistance = 1.5;
controls.maxDistance = 10;

// --- Brass materials ---
const brassMain = new THREE.MeshPhysicalMaterial({
  color: 0xc8a84e,
  metalness: 0.95,
  roughness: 0.18,
  clearcoat: 0.3,
  clearcoatRoughness: 0.1,
  envMapIntensity: 1.5,
});

const brassDark = new THREE.MeshPhysicalMaterial({
  color: 0x8a7030,
  metalness: 0.95,
  roughness: 0.35,
  envMapIntensity: 1.2,
});

const brassBright = new THREE.MeshPhysicalMaterial({
  color: 0xe8cc6e,
  metalness: 0.98,
  roughness: 0.08,
  clearcoat: 0.5,
  envMapIntensity: 2.0,
});

const blackMat = new THREE.MeshStandardMaterial({
  color: 0x111111,
  metalness: 0.1,
  roughness: 0.8,
});

// --- Sextant arc group ---
const sextant = new THREE.Group();

const RADIUS = 1.8;
const ARC_ANGLE = Math.PI / 3.2; // ~56 degrees span
const ARC_THICKNESS = 0.12;
const ARC_DEPTH = 0.06;

// Main arc body — torus segment
const arcGeo = new THREE.TorusGeometry(
  RADIUS, ARC_THICKNESS, 16, 64, ARC_ANGLE
);
const arcMesh = new THREE.Mesh(arcGeo, brassMain);
arcMesh.rotation.x = Math.PI / 2;
arcMesh.rotation.z = -ARC_ANGLE / 2;
sextant.add(arcMesh);

// Inner and outer rim edges (thin bright torus rings for bevel look)
for (const sign of [-1, 1]) {
  const rimGeo = new THREE.TorusGeometry(
    RADIUS + sign * ARC_THICKNESS * 0.92, 0.008, 8, 64, ARC_ANGLE
  );
  const rim = new THREE.Mesh(rimGeo, brassBright);
  rim.rotation.x = Math.PI / 2;
  rim.rotation.z = -ARC_ANGLE / 2;
  sextant.add(rim);
}

// Tick marks along the outer edge
const tickCount = 61; // every degree-ish
const tickStep = ARC_ANGLE / (tickCount - 1);

for (let i = 0; i < tickCount; i++) {
  const angle = -ARC_ANGLE / 2 + i * tickStep;
  const isMajor = i % 10 === 0;
  const isMid = i % 5 === 0 && !isMajor;
  const height = isMajor ? 0.06 : isMid ? 0.04 : 0.022;
  const width = isMajor ? 0.018 : 0.01;

  const tickGeo = new THREE.BoxGeometry(width, height, ARC_DEPTH);
  const tick = new THREE.Mesh(tickGeo, isMajor ? brassBright : brassDark);

  const outerR = RADIUS + ARC_THICKNESS + height / 2;
  tick.position.set(
    Math.cos(angle) * outerR,
    Math.sin(angle) * outerR,
    0
  );
  tick.rotation.z = angle;
  sextant.add(tick);
}

// Black inlay behind ticks for contrast
const inlayGeo = new THREE.TorusGeometry(
  RADIUS + ARC_THICKNESS + 0.01, 0.04, 8, 64, ARC_ANGLE
);
const inlay = new THREE.Mesh(inlayGeo, blackMat);
inlay.rotation.x = Math.PI / 2;
inlay.rotation.z = -ARC_ANGLE / 2;
inlay.position.z = -0.005;
sextant.add(inlay);

// Degree index marks (small dots on inner edge at major ticks)
for (let i = 0; i <= 60; i += 10) {
  const angle = -ARC_ANGLE / 2 + (i / 60) * ARC_ANGLE;
  const dotGeo = new THREE.SphereGeometry(0.012, 8, 8);
  const dot = new THREE.Mesh(dotGeo, brassBright);
  const innerR = RADIUS - ARC_THICKNESS;
  dot.position.set(
    Math.cos(angle) * innerR,
    Math.sin(angle) * innerR,
    0
  );
  sextant.add(dot);
}

// Frame / backing plate
const frameShape = new THREE.Shape();
const frameR = RADIUS + ARC_THICKNESS + 0.08;
const startAngle = -ARC_ANGLE / 2 - 0.05;
const endAngle = ARC_ANGLE / 2 + 0.05;

frameShape.absarc(0, 0, frameR, startAngle, endAngle, false);
frameShape.absarc(0, 0, frameR - 0.22, endAngle, startAngle, true);

const frameGeo = new THREE.ExtrudeGeometry(frameShape, {
  depth: 0.02,
  bevelEnabled: true,
  bevelThickness: 0.005,
  bevelSize: 0.005,
  bevelSegments: 2,
});
const frame = new THREE.Mesh(frameGeo, brassDark);
frame.position.z = -0.03;
sextant.add(frame);

// Center pin
const pinGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.08, 16);
const pin = new THREE.Mesh(pinGeo, brassBright);
pin.position.z = 0.01;
sextant.add(pin);

scene.add(sextant);

// --- Lighting ---
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(3, 4, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 1);
fillLight.position.set(-3, -1, 3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffcc88, 2);
rimLight.position.set(0, -3, -4);
scene.add(rimLight);

// --- Animation ---
function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
