<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(5, 8, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.5, 0);
controls.enableDamping = true;

// Brass material
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xb5a642,
  metalness: 0.85,
  roughness: 0.25,
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8a7a30,
  metalness: 0.9,
  roughness: 0.3,
});

const group = new THREE.Group();
scene.add(group);

// Base / foot of sundial
const baseGeo = new THREE.CylinderGeometry(1.4, 1.6, 0.3, 48);
const base = new THREE.Mesh(baseGeo, brassMat);
base.position.y = 0.15;
base.castShadow = true;
base.receiveShadow = true;
group.add(base);

// Second base ring
const baseRingGeo = new THREE.CylinderGeometry(1.8, 2.0, 0.15, 48);
const baseRing = new THREE.Mesh(baseRingGeo, darkBrassMat);
baseRing.position.y = 0.075;
baseRing.receiveShadow = true;
group.add(baseRing);

// Pillar
const pillarGeo = new THREE.CylinderGeometry(0.25, 0.35, 2.0, 24);
const pillar = new THREE.Mesh(pillarGeo, brassMat);
pillar.position.y = 1.3;
pillar.castShadow = true;
group.add(pillar);

// Dial plate (tilted)
const dialGroup = new THREE.Group();
dialGroup.position.y = 2.3;
dialGroup.rotation.x = -Math.PI * 0.38;
group.add(dialGroup);

// Dial disc
const discGeo = new THREE.CylinderGeometry(1.6, 1.6, 0.06, 64);
const disc = new THREE.Mesh(discGeo, brassMat);
disc.receiveShadow = true;
dialGroup.add(disc);

// Raised rim
const rimGeo = new THREE.TorusGeometry(1.6, 0.05, 8, 64);
const rim = new THREE.Mesh(rimGeo, darkBrassMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.03;
dialGroup.add(rim);

// Hour marks (12 hours)
for (let i = 0; i < 12; i++) {
  const angle = (i / 12) * Math.PI * 2;
  const isMain = i % 3 === 0;
  const markLen = isMain ? 0.25 : 0.15;
  const markWidth = isMain ? 0.06 : 0.03;
  const outerR = 1.45;
  const innerR = outerR - markLen;

  const shape = new THREE.Shape();
  shape.moveTo(innerR, -markWidth / 2);
  shape.lineTo(outerR, -markWidth * 1.2);
  shape.lineTo(outerR, markWidth * 1.2);
  shape.lineTo(innerR, markWidth / 2);

  const extrudeSettings = { depth: 0.04, bevelEnabled: true, bevelThickness: 0.01, bevelSize: 0.01 };
  const markGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  const mark = new THREE.Mesh(markGeo, darkBrassMat);
  mark.rotation.z = -angle;
  mark.rotation.x = -Math.PI / 2;
  mark.position.y = 0.04;
  dialGroup.add(mark);
}

// Inner decorative ring
const innerRingGeo = new THREE.TorusGeometry(0.6, 0.025, 8, 48);
const innerRing = new THREE.Mesh(innerRingGeo, darkBrassMat);
innerRing.rotation.x = Math.PI / 2;
innerRing.position.y = 0.045;
dialGroup.add(innerRing);

// Gnomon (triangular pointer)
const gnomonShape = new THREE.Shape();
gnomonShape.moveTo(0, 0);
gnomonShape.lineTo(1.2, 0.02);
gnomonShape.lineTo(0, 0.6);

const gnomonGeo = new THREE.ExtrudeGeometry(gnomonShape, {
  depth: 0.02,
  bevelEnabled: true,
  bevelThickness: 0.005,
  bevelSize: 0.005,
});
const gnomon = new THREE.Mesh(gnomonGeo, brassMat);
gnomon.rotation.x = -Math.PI / 2;
gnomon.rotation.z = Math.PI / 2;
gnomon.position.set(-0.6, 0.06, -0.01);
gnomon.castShadow = true;
dialGroup.add(gnomon);

// Small sphere at gnomon tip
const tipGeo = new THREE.SphereGeometry(0.05, 16, 16);
const tip = new THREE.Mesh(tipGeo, brassMat);
tip.position.set(0, 0.08, 0);
tip.castShadow = true;
dialGroup.add(tip);

// Shadow line (simulated)
const shadowGeo = new THREE.PlaneGeometry(0.04, 1.0);
const shadowMat = new THREE.MeshBasicMaterial({
  color: 0x000000,
  transparent: true,
  opacity: 0.35,
});
const shadow = new THREE.Mesh(shadowGeo, shadowMat);
shadow.rotation.x = -Math.PI / 2;
shadow.rotation.z = 0.4;
shadow.position.set(0.15, 0.05, 0.2);
dialGroup.add(shadow);

// Lighting
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffeedd, 3);
sunLight.position.set(5, 10, 3);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 30;
sunLight.shadow.camera.left = -5;
sunLight.shadow.camera.right = 5;
sunLight.shadow.camera.top = 5;
sunLight.shadow.camera.bottom = -5;
scene.add(sunLight);

const fillLight = new THREE.DirectionalLight(0x8888cc, 0.8);
fillLight.position.set(-3, 4, -2);
scene.add(fillLight);

const pointLight = new THREE.PointLight(0xffcc66, 1, 15);
pointLight.position.set(2, 5, 2);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.CircleGeometry(20, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x2a2a3e,
  roughness: 0.9,
  metalness: 0.1,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Subtle pedestal ring on ground
const pedestalGeo = new THREE.RingGeometry(2.2, 3.0, 64);
const pedestalMat = new THREE.MeshStandardMaterial({
  color: 0x3a3a50,
  roughness: 0.7,
  metalness: 0.3,
});
const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
pedestal.rotation.x = -Math.PI / 2;
pedestal.position.y = 0.005;
pedestal.receiveShadow = true;
scene.add(pedestal);

// Animation
let time = 0;
function animate() {
  requestAnimationFrame(animate);
  time += 0.003;

  // Slowly rotate shadow to simulate time passing
  shadow.rotation.z = 0.4 + Math.sin(time * 0.5) * 0.6;
  shadow.scale.y = 0.8 + Math.sin(time * 0.5) * 0.4;

  // Subtle light animation
  pointLight.intensity = 1 + Math.sin(time * 2) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// Resize
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This creates a **brass sundial** scene featuring:

- **Brass materials** — `MeshStandardMaterial` with high metalness and warm gold tones to simulate real brass, with a darker brass variant for contrast on hour marks and rims
- **Sundial structure** — a stepped base, central pillar, and a tilted dial plate (angled at ~69° like a real sundial for northern latitude)
- **12 hour marks** — tapered pointers extruded around the dial, with bolder marks at 3, 6, 9, and 12
- **Triangular gnomon** — the classic pointer that casts the shadow, with a small decorative sphere at its tip
- **Animated shadow** — a translucent shadow plane that slowly sweeps across the dial to simulate the passage of time
- **Rich lighting** — directional sunlight with soft shadows, a blue-toned fill light, and a warm point light for specular highlights on the brass
- **Orbit controls** — click and drag to rotate around the sundial

