        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        // Environment for realistic glass refraction
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const envMap = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
        scene.environment = envMap;

        // Create Swirl Texture
        function createSwirlTexture() {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, size, size);

            // Swirl
            const centerX = size / 2;
            const centerY = size / 2;

            for (let i = 0; i < 200; i++) {
                const angle = i * 0.1;
                const radius = i * 1.5;
                const x = centerX + Math.cos(angle) * radius;
                const y = centerY + Math.sin(angle) * radius;

                ctx.beginPath();
                ctx.arc(x, y, 5 + (i % 10), 0, Math.PI * 2);
                ctx.fillStyle = `rgba(${50 + i}, ${50 + i}, ${200 - i}, 0.5)`;
                ctx.fill();
            }

            // Add some noise/edge detail
            for(let i=0; i<500; i++) {
                const x = Math.random() * size;
                const y = Math.random() * size;
                ctx.fillStyle = `rgba(255, 255, 255, ${Math.random() * 0.3})`;
                ctx.fillRect(x, y, 2, 2);
            }

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // Glass Marble Material
        const material = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 1.5,     // Volume for refraction
            ior: 1.5,           // Index of refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.0,
            map: swirlTexture,  // Apply swirl texture
            transparent: true,
            opacity: 1.0
        });

        const geometry = new THREE.SphereGeometry(1.5, 64, 64);
        const marble = new THREE.Mesh(geometry, material);
        scene.add(marble);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Animation
        function animate() {
            requestAnimationFrame(animate);
            marble.rotation.y += 0.005;
            marble.rotation.x += 0.002;
            controls.update();
            renderer.render(scene, camera);
        }

        // Resize handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
