    foot.position.set(Math.cos(angle) * 1.7, 0.02, Math.sin(angle) * 1.7);
    group.add(foot);
  }

  return group;
}
const base = createBase();
scene.add(base);

// ── Interior Snow Ground ───────────────────────────────
const snowGroundGeo = new THREE.CylinderGeometry(2.2, 2.2, 0.3, 64);
const snowGroundMat = new THREE.MeshPhysicalMaterial({
  color: 0xeef4ff, roughness: 0.9, metalness: 0,
  clearcoat: 0.1, clearcoatRoughness: 0.8,
});
const snowGround = new THREE.Mesh(snowGroundGeo, snowGroundMat);
snowGround.position.y = GLOBE_RADIUS - 0.15;
scene.add(snowGround);

// Mound
const moundGeo = new THREE.SphereGeometry(1.8, 64, 32, 0, Math.PI * 2, 0, Math.PI * 0.35);
const mound = new THREE.Mesh(moundGeo, snowGroundMat);
mound.position.y = GLOBE_RADIUS - 0.1;
mound.scale.y = 0.3;
scene.add(mound);

// ── Tiny Trees ─────────────────────────────────────────
function createMiniTree(height, x, z) {
  const group = new THREE.Group();
  const trunkGeo = new THREE.CylinderGeometry(0.03, 0.04, height * 0.3, 8);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x3a2211, roughness: 0.9 });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = height * 0.15;
  group.add(trunk);

  for (let i = 0; i < 3; i++) {
    const coneH = height * (0.35 - i * 0.05);
    const coneR = (0.25 - i * 0.06) * (height / 0.8);
    const coneGeo = new THREE.ConeGeometry(coneR, coneH, 8);
    const coneMat = new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(0.3 + Math.random() * 0.05, 0.5, 0.15 + i * 0.05),
      roughness: 0.85,
    });
    const cone = new THREE.Mesh(coneGeo, coneMat);
    cone.position.y = height * 0.3 + i * coneH * 0.45;
    group.add(cone);
  }

  group.position.set(x, GLOBE_RADIUS - 0.05, z);
  return group;
}

const treePositions = [
  { x: 0.8, z: 0.6 }, { x: -0.7, z: 0.9 }, { x: 0.3, z: -1.0 },
  { x: -1.1, z: -0.4 }, { x: 1.2, z: -0.3 }, { x: -0.2, z: 1.3 },
];
treePositions.forEach(p => {
  const tree = createMiniTree(0.5 + Math.random() * 0.5, p.x, p.z);
  scene.add(tree);
});

// ── Tiny House ─────────────────────────────────────────
function createMiniHouse(x, z) {
  const group = new THREE.Group();
  const wallMat = new THREE.MeshStandardMaterial({ color: 0x884433, roughness: 0.8 });
  const walls = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.3, 0.25), wallMat);
  walls.position.y = 0.15;
  group.add(walls);

  const roofMat = new THREE.MeshStandardMaterial({ color: 0x334455, roughness: 0.7 });
  const roof = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.2, 4), roofMat);
  roof.position.y = 0.4;
  roof.rotation.y = Math.PI / 4;
  group.add(roof);

  const doorMat = new THREE.MeshStandardMaterial({ color: 0x553322, roughness: 0.8 });
  const door = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.14, 0.02), doorMat);
  door.position.set(0, 0.07, 0.13);
  group.add(door);

  // Window glow
  const winMat = new THREE.MeshStandardMaterial({
    color: 0xffdd88, emissive: 0xffaa44, emissiveIntensity: 2,
  });
  const win = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.06, 0.02), winMat);
  win.position.set(0.1, 0.2, 0.13);
  group.add(win);

  const win2 = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.06, 0.02), winMat);
  win2.position.set(-0.1, 0.2, 0.13);
  group.add(win2);

  // Chimney
  const chimney = new THREE.Mesh(
    new THREE.BoxGeometry(0.06, 0.15, 0.06),
    new THREE.MeshStandardMaterial({ color: 0x553322, roughness: 0.9 })
  );
  chimney.position.set(0.12, 0.48, -0.05);
  group.add(chimney);

  group.position.set(x, GLOBE_RADIUS - 0.1, z);
  return group;
}

