  text-align: center; pointer-events: none; opacity: .7;
}
</style>
</head>
<body>
<div id="info">drag to orbit · scroll to zoom</div>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a12);
scene.fog = new THREE.FogExp2(0x0a0a12, 0.04);

const camera = new THREE.PerspectiveCamera(35, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.4;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 2;
controls.maxDistance = 14;

// ── Environment ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// ── Materials ──
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xc9a84c, metalness: 0.95, roughness: 0.18,
  clearcoat: 0.3, clearcoatRoughness: 0.1,
  envMapIntensity: 1.5
});

const darkBrass = new THREE.MeshPhysicalMaterial({
  color: 0x8a6d2b, metalness: 0.93, roughness: 0.28,
  envMapIntensity: 1.2
});

const lensGlass = new THREE.MeshPhysicalMaterial({
  color: 0xddeeff, metalness: 0.0, roughness: 0.02,
  transmission: 0.92, thickness: 0.6, ior: 1.52,
  clearcoat: 1.0, clearcoatRoughness: 0.0,
  specularIntensity: 1.0, specularColor: 0xffffff,
  envMapIntensity: 1.0, transparent: true, opacity: 0.85
});

const coating = new THREE.MeshPhysicalMaterial({
  color: 0x8899bb, metalness: 0.0, roughness: 0.05,
  transmission: 0.6, thickness: 0.3, ior: 1.52,
  clearcoat: 1.0, envMapIntensity: 0.8, transparent: true, opacity: 0.5
});

// ── Helpers ──
function makeBrassRing(radius, tube, segs = 64) {
  const g = new THREE.TorusGeometry(radius, tube, 16, segs);
  return new THREE.Mesh(g, brassMat);
}

function makeBrassBarrel(radius, height, segs = 64) {
  const g = new THREE.CylinderGeometry(radius, radius, height, segs, 1, true);
  return new THREE.Mesh(g, brassMat);
}

function makeLensElement(radius, thickness, sagitta) {
  // Biconvex lens via lathe
  const pts = [];
  const steps = 32;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const r = radius * Math.sin(t * Math.PI * 0.5);
    const y = sagitta * Math.cos(t * Math.PI);
    pts.push(new THREE.Vector2(r, y));
  }
  // Second surface
  for (let i = steps; i >= 0; i--) {
    const t = i / steps;
    const r = radius * Math.sin(t * Math.PI * 0.5);
    const y = -sagitta * Math.cos(t * Math.PI);
    pts.push(new THREE.Vector2(r, y));
  }
  const g = new THREE.LatheGeometry(pts, 64);
  g.computeVertexNormals();
  return new THREE.Mesh(g, lensGlass);
}

// ── Build Telescope Lens Assembly ──
const assembly = new THREE.Group();

// Outer brass barrel
const barrel = makeBrassBarrel(0.85, 3.2, 64);
assembly.add(barrel);

// Barrel end caps / rings
for (const z of [-1.6, 1.6]) {
  const ring = makeBrassRing(0.88, 0.04);
  ring.rotation.x = Math.PI / 2;
  ring.position.z = z;
  assembly.add(ring);
}

// Decorative rings along barrel
for (const z of [-1.0, -0.5, 0.5, 1.0]) {
  const ring = makeBrassRing(0.87, 0.025);
  ring.rotation.x = Math.PI / 2;
  ring.position.z = z;
  assembly.add(ring);
}

// Brass focusing ring (thicker, knurled look)
const focusRing = makeBrassRing(0.92, 0.06);
focusRing.rotation.x = Math.PI / 2;
focusRing.position.z = -0.3;
assembly.add(focusRing);

// Small brass adjustment knobs
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const knob = new THREE.Mesh(
    new THREE.CylinderGeometry(0.04, 0.04, 0.08, 8),
    darkBrass
  );
  knob.position.set(Math.cos(angle) * 0.92, Math.sin(angle) * 0.92, -0.3);
  knob.rotation.z = Math.PI / 2;
  assembly.add(knob);
}

// ── Lens Elements ──
// Front lens (larger)
const lens1 = makeLensElement(0.7, 0.15, 0.18);
lens1.rotation.x = Math.PI / 2;
lens1.position.z = 1.4;
assembly.add(lens1);

// Anti-reflective coating on front
const coat1 = makeLensElement(0.68, 0.02, 0.15);
coat1.rotation.x = Math.PI / 2;
coat1.position.z = 1.48;
coat1.material = coating;
assembly.add(coat1);

// Brass spacer ring
const spacer1 = makeBrassRing(0.72, 0.035);
spacer1.rotation.x = Math.PI / 2;
spacer1.position.z = 0.9;
assembly.add(spacer1);

// Second lens element
const lens2 = makeLensElement(0.65, 0.12, 0.14);
lens2.rotation.x = Math.PI / 2;
lens2.position.z = 0.5;
assembly.add(lens2);

// Inner brass ring
const innerRing = makeBrassRing(0.68, 0.03);
innerRing.rotation.x = Math.PI / 2;
innerRing.position.z = 0.1;
assembly.add(innerRing);

// Third lens (eyepiece side)
const lens3 = makeLensElement(0.55, 0.1, 0.12);
lens3.rotation.x = Math.PI / 2;
lens3.position.z = -0.4;
assembly.add(lens3);

// Rear brass ring
const rearRing = makeBrassRing(0.6, 0.04);
rearRing.rotation.x = Math.PI / 2;
rearRing.position.z = -1.0;
assembly.add(rearRing);

// Final eyepiece lens
const lens4 = makeLensElement(0.45, 0.08, 0.1);
lens4.rotation.x = Math.PI / 2;
lens4.position.z = -1.45;
assembly.add(lens4);

// Eyepiece brass cap
const eyepieceCap = makeBrassBarrel(0.52, 0.2, 48);
eyepieceCap.position.z = -1.55;
assembly.add(eyepieceCap);

// Front brass cap with emblem
const frontCap = makeBrassBarrel(0.82, 0.12, 48);
frontCap.position.z = 1.65;
assembly.add(frontCap);

// Small front emblem disc
const emblem = new THREE.Mesh(
  new THREE.CylinderGeometry(0.15, 0.15, 0.02, 32),
  darkBrass
);
emblem.rotation.x = Math.PI / 2;
emblem.position.z = 1.72;
assembly.add(emblem);

assembly.rotation.x = 0.15;
scene.add(assembly);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xfff0d4, 3);
keyLight.position.set(3, 4, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 1.2);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffeedd, 2);
rimLight.position.set(0, -3, -5);
scene.add(rimLight);

const pointLight = new THREE.PointLight(0xffc864, 2, 10);
pointLight.position.set(2, 1, 3);
scene.add(pointLight);

// ── Dust particles ──
const dustCount = 200;
const dustGeo = new THREE.BufferGeometry();
const dustPos = new Float32Array(dustCount * 3);
for (let i = 0; i < dustCount; i++) {
  dustPos[i * 3]     = (Math.random() - 0.5) * 12;
  dustPos[i * 3 + 1] = (Math.random() - 0.5) * 12;
  dustPos[i * 3 + 2] = (Math.random() - 0.5) * 12;
}
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0xc9a84c, size: 0.015, transparent: true, opacity: 0.4,
  sizeAttenuation: true
});
const dust = new THREE.Points(dustGeo, dustMat);
scene.add(dust);

// ── Animate ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  assembly.rotation.y = Math.sin(t * 0.3) * 0.15;
  assembly.position.y = Math.sin(t * 0.5) * 0.08;

  dust.rotation.y = t * 0.02;
  dust.rotation.x = t * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This creates a rich 3D visualization featuring:

- **Multi-element lens assembly** — four biconvex glass lens elements (biconvex via `LatheGeometry`) separated by brass spacer rings, mimicking a real achromatic telescope design
- **Brass housing** — an outer barrel with decorative rings, a knurled focusing ring with 8 adjustment knobs, front/rear caps, and a small emblem disc
- **Realistic materials** — `MeshPhysicalMaterial` with high metalness/low roughness for brass, and transmission/IOR-based glass with anti-reflective coating layers
- **Environment reflections** — uses `RoomEnvironment` via PMREM for realistic metallic reflections on the brass
- **Cinematic lighting** — key, fill, rim, and accent point lights in warm tones
- **Floating dust particles** — subtle golden particles drifting in the scene
- **Gentle animation** — the telescope slowly rocks and floats; drag to orbit, scroll to zoom

