            const time = Date.now() * 0.001;

            // Gentle rotation
            globeGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Shake effect
            if (shakeIntensity > 0.01) {
                globeGroup.rotation.x = (Math.random() - 0.5) * shakeIntensity;
                globeGroup.rotation.z = (Math.random() - 0.5) * shakeIntensity;
                shakeIntensity *= shakeDecay;
            } else {
                globeGroup.rotation.x = 0;
                globeGroup.rotation.z = 0;
            }

            // Animate Snow
            const positions = snowSystem.geometry.attributes.position.array;
            for (let i = 0; i < particleCount; i++) {
                // Apply velocity
                positions[i * 3] += velocities[i].x;
                positions[i * 3 + 1] -= velocities[i].y; // Fall down
                positions[i * 3 + 2] += velocities[i].z;

                // Shake influence on snow
                if (shakeIntensity > 0.01) {
                    positions[i * 3] += (Math.random() - 0.5) * shakeIntensity * 0.5;
                    positions[i * 3 + 2] += (Math.random() - 0.5) * shakeIntensity * 0.5;
                }

                // Reset if below ground
                if (positions[i * 3 + 1] < -1.8) {
                    positions[i * 3 + 1] = 2.0; // Reset to top
                    // Randomize X/Z again to keep them inside sphere
                    const r = 2.0 * Math.cbrt(Math.random());
                    const theta = Math.random() * 2 * Math.PI;
                    const phi = Math.acos(2 * Math.random() - 1);
                    positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
                    positions[i * 3 + 2] = r * Math.cos(phi);
                }
            }
            snowSystem.geometry.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
