<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Brass Protractor</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a2e; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 8, 10);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xfff4e0, 2.5);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
scene.add(dirLight);

const dirLight2 = new THREE.DirectionalLight(0xc8d8ff, 1.0);
dirLight2.position.set(-5, 5, -5);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xffaa44, 1.5, 20);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// --- Brass Material ---
const brassMaterial = new THREE.MeshStandardMaterial({
  color: 0xb5a642,
  metalness: 0.92,
  roughness: 0.28,
  envMapIntensity: 1.0,
});

const darkBrassMaterial = new THREE.MeshStandardMaterial({
  color: 0x8a7a30,
  metalness: 0.95,
  roughness: 0.35,
});

// --- Environment Map (simple procedural) ---
const pmremGenerator = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x222233);
const envLight1 = new THREE.DirectionalLight(0xffffff, 3);
envLight1.position.set(5, 10, 5);
envScene.add(envLight1);
const envLight2 = new THREE.DirectionalLight(0xffaa66, 2);
envLight2.position.set(-5, 3, -5);
envScene.add(envLight2);
const envRT = pmremGenerator.fromScene(envScene);
scene.environment = envRT.texture;

// --- Protractor Group ---
const protractor = new THREE.Group();
scene.add(protractor);

const OUTER_R = 4.0;
const INNER_R = 3.4;
const MARK_R = 3.6;

// --- Protractor Body (half-ring) ---
function createProtractorBody() {
  const shape = new THREE.Shape();
  // Outer arc (half circle, left to right, going over the top)
  for (let i = 0; i <= 64; i++) {
    const angle = Math.PI + (Math.PI * i) / 64;
    const x = Math.cos(angle) * OUTER_R;
    const y = Math.sin(angle) * OUTER_R;
    if (i === 0) shape.moveTo(x, y);
    else shape.lineTo(x, y);
  }
  // Inner arc (backwards)
  for (let i = 64; i >= 0; i--) {
    const angle = Math.PI + (Math.PI * i) / 64;
    const x = Math.cos(angle) * INNER_R;
    const y = Math.sin(angle) * INNER_R;
    shape.lineTo(x, y);
  }
  shape.closePath();

  // Center hole
  const holePath = new THREE.Path();
  const holeR = 0.35;
  for (let i = 0; i <= 32; i++) {
    const angle = (Math.PI * 2 * i) / 32;
    const x = Math.cos(angle) * holeR;
    const y = Math.sin(angle) * holeR;
    if (i === 0) holePath.moveTo(x, y);
    else holePath.lineTo(x, y);
  }
  holePath.closePath();
  shape.holes.push(holePath);

  const thickness = 0.08;
  const extrudeSettings = { depth: thickness, bevelEnabled: true, bevelThickness: 0.015, bevelSize: 0.015, bevelSegments: 3 };
  const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geometry.center();

  const mesh = new THREE.Mesh(geometry, brassMaterial);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.01;
  return mesh;
}
protractor.add(createProtractorBody());

// --- Edge ring (outer rim highlight) ---
function createOuterRim() {
  const curve = new THREE.EllipseCurve(0, 0, OUTER_R, OUTER_R, Math.PI, 0, false, 0);
  const points = curve.getPoints(128);
  const geometry = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p.x, 0, p.y))),
    128, 0.02, 8, false
  );
  const mesh = new THREE.Mesh(geometry, darkBrassMaterial);
  mesh.position.y = 0.05;
  return mesh;
}
protractor.add(createOuterRim());

// --- Inner Rim ---
function createInnerRim() {
  const curve = new THREE.EllipseCurve(0, 0, INNER_R, INNER_R, Math.PI, 0, false, 0);
  const points = curve.getPoints(128);
  const geometry = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p.x, 0, p.y))),
    128, 0.015, 8, false
  );
  const mesh = new THREE.Mesh(geometry, darkBrassMaterial);
  mesh.position.y = 0.05;
  return mesh;
}
protractor.add(createInnerRim());

// --- Degree Marks ---
const markMaterial = new THREE.MeshStandardMaterial({
  color: 0x2a2210,
  metalness: 0.3,
  roughness: 0.7,
});

for (let deg = 0; deg <= 180; deg++) {
  const rad = (deg * Math.PI) / 180;
  let major = false;
  let medium = false;

  if (deg % 10 === 0) major = true;
  else if (deg % 5 === 0) medium = true;

  const startR = major ? 3.55 : medium ? 3.62 : 3.68;
  const endR = OUTER_R - 0.05;

  const x1 = Math.cos(Math.PI - rad) * startR;
  const y1 = Math.sin(Math.PI - rad) * startR;
  const x2 = Math.cos(Math.PI - rad) * endR;
  const y2 = Math.sin(Math.PI - rad) * endR;

  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy);

  if (len < 0.001) continue;

  const markGeo = new THREE.BoxGeometry(
    major ? 0.04 : medium ? 0.03 : 0.02,
    0.015,
    len + 0.01
  );

  const mark = new THREE.Mesh(markGeo, markMaterial);
  mark.position.set((x1 + x2) / 2, 0.05, (y1 + y2) / 2);
  mark.rotation.y = -(Math.PI - rad) + Math.PI / 2;
  protractor.add(mark);
}

// --- Degree Numbers ---
function createTextTexture(text, fontSize = 64) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = `bold ${fontSize}px Georgia, serif`;
  ctx.fillStyle = '#1a1508';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 64, 64);
  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  return texture;
}

for (let deg = 0; deg <= 180; deg += 10) {
  const rad = (deg * Math.PI) / 180;
  const textR = 3.1;
  const x = Math.cos(Math.PI - rad) * textR;
  const z = Math.sin(Math.PI - rad) * textR;

  const texture = createTextTexture(String(deg), deg === 90 ? 72 : 56);
  const aspect = texture.image.width / texture.image.height;
  const planeGeo = new THREE.PlaneGeometry(0.5 * aspect, 0.5);
  const planeMat = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
  });
  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.position.set(x, 0.06, z);
  plane.rotation.x = -Math.PI / 2;
  // Rotate text to face center
  plane.rotation.z = -(Math.PI - rad);
  protractor.add(plane);
}

// --- Center Crosshair ---
const crossMat = new THREE.MeshStandardMaterial({ color: 0x2a2210, metalness: 0.3, roughness: 0.7 });

function createCrosshairLine(angle, length) {
  const geo = new THREE.BoxGeometry(length, 0.015, 0.025);
  const mesh = new THREE.Mesh(geo, crossMat);
  mesh.position.y = 0.055;
  mesh.rotation.y = angle;
  return mesh;
}

protractor.add(createCrosshairLine(0, 0.6));
protractor.add(createCrosshairLine(Math.PI / 2, 0.6));

// --- Baseline (flat edge line) ---
const baseGeo = new THREE.BoxGeometry(OUTER_R * 2 - 0.1, 0.015, 0.03);
const baseLine = new THREE.Mesh(baseGeo, crossMat);
baseLine.position.y = 0.055;
protractor.add(baseLine);

// --- Small decorative dots at 0, 90, 180 ---
const dotGeo = new THREE.SphereGeometry(0.06, 16, 16);
const dotMat = new THREE.MeshStandardMaterial({ color: 0x2a2210, metalness: 0.5, roughness: 0.5 });
[0, Math.PI / 2, Math.PI].forEach(angle => {
  const dot = new THREE.Mesh(dotGeo, dotMat);
  dot.position.set(
    Math.cos(Math.PI - angle) * INNER_R * 0.6,
    0.06,
    Math.sin(Math.PI - angle) * INNER_R * 0.6
  );
  protractor.add(dot);
});

// --- Display Text "DEGREES" ---
const degTexture = createTextTexture('DEGREES', 40);
const degAspect = degTexture.image.width / degTexture.image.height;
const degPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(1.2 * degAspect, 1.2),
  new THREE.MeshBasicMaterial({ map: degTexture, transparent: true, depthWrite: false })
);
degPlane.position.set(0, 0.06, 1.8);
degPlane.rotation.x = -Math.PI / 2;
degPlane.rotation.z = Math.PI;
protractor.add(degPlane);

// --- Subtle tilt for dramatic presentation ---
protractor.rotation.x = -0.15;
protractor.rotation.z = 0.05;

// --- Ground Plane ---
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111122,
  metalness: 0.8,
  roughness: 0.4,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.5;
scene.add(ground);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating
  protractor.position.y = Math.sin(t * 0.5) * 0.15;
  protractor.rotation.y = Math.sin(t * 0.3) * 0.05;

  // Subtle light animation
  pointLight.intensity = 1.5 + Math.sin(t * 1.2) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What this creates

A **3D brass protractor** rendered with Three.js featuring:

- **Half-ring body** — extruded semi-circle with a center hole, beveled edges, and brass PBR material (`metalness: 0.92`, `roughness: 0.28`)
- **181 degree marks** — three tiers of depth/width:
  - **Major** (every 10°): longest, widest marks
  - **Medium** (every 5°): mid-length marks
  - **Minor** (every 1°): short tick marks
- **Degree numbers** (0–180, every 10°) rendered via canvas textures, rotated to face the center
- **Decorative details**: center crosshair, baseline edge line, dark rim tubes, decorative dots, and a "DEGREES" label
- **Cinematic presentation**: gentle floating animation, warm multi-light setup with ACES filmic tone mapping, dark reflective ground plane, and fog
- **OrbitControls** — click and drag to rotate, scroll to zoom

