}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(2, 1.8, 2.5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// Brass material
const brass = new THREE.MeshStandardMaterial({
  color: 0xc4a035,
  metalness: 0.95,
  roughness: 0.22,
  envMapIntensity: 1.4,
});

const darkBrass = new THREE.MeshStandardMaterial({
  color: 0x8a7320,
  metalness: 0.9,
  roughness: 0.35,
  envMapIntensity: 1.0,
});

const polishedBrass = new THREE.MeshStandardMaterial({
  color: 0xd4b84a,
  metalness: 0.97,
  roughness: 0.08,
  envMapIntensity: 1.8,
});

const compassGroup = new THREE.Group();

// === BASE RING ===
const baseRingGeo = new THREE.TorusGeometry(0.55, 0.045, 24, 64);
const baseRing = new THREE.Mesh(baseRingGeo, polishedBrass);
baseRing.rotation.x = Math.PI / 2;
baseRing.position.y = 0.02;
compassGroup.add(baseRing);

// Outer base plate
const basePlateGeo = new THREE.CylinderGeometry(0.58, 0.6, 0.04, 64);
const basePlate = new THREE.Mesh(basePlateGeo, brass);
basePlate.position.y = -0.015;
compassGroup.add(basePlate);

// Inner rim
const innerRimGeo = new THREE.TorusGeometry(0.48, 0.02, 16, 64);
const innerRim = new THREE.Mesh(innerRimGeo, darkBrass);
innerRim.rotation.x = Math.PI / 2;
innerRim.position.y = 0.04;
compassGroup.add(innerRim);

// === DOME COVER (open position, hinged open) ===
const domeGroup = new THREE.Group();

// Dome - slightly flattened hemisphere
const domeGeo = new THREE.SphereGeometry(0.52, 64, 32, 0, Math.PI * 2, 0, Math.PI * 0.52);
const dome = new THREE.Mesh(domeGeo, brass);
dome.position.y = 0.04;
domeGroup.add(dome);

// Dome rim
const domeRimGeo = new THREE.TorusGeometry(0.51, 0.018, 16, 64);
const domeRim = new THREE.Mesh(domeRimGeo, polishedBrass);
domeRim.rotation.x = Math.PI / 2;
domeRim.position.y = 0.04;
domeGroup.add(domeRim);

// Decorative ring on dome
const decoRingGeo = new THREE.TorusGeometry(0.35, 0.012, 12, 64);
const decoRing = new THREE.Mesh(decoRingGeo, polishedBrass);
decoRing.rotation.x = Math.PI / 2;
decoRing.position.y = 0.25;
domeGroup.add(decoRing);

// Small decorative boss/knob on top
const knobGeo = new THREE.SphereGeometry(0.035, 24, 24);
const knob = new THREE.Mesh(knobGeo, polishedBrass);
knob.position.y = 0.52;
domeGroup.add(knob);

// Knob base
const knobBaseGeo = new THREE.CylinderGeometry(0.04, 0.05, 0.03, 24);
const knobBase = new THREE.Mesh(knobBaseGeo, darkBrass);
knobBase.position.y = 0.50;
domeGroup.add(knobBase);

// Hinge the dome open
domeGroup.position.set(0, 0, -0.52);
domeGroup.rotation.x = -Math.PI * 0.55;
compassGroup.add(domeGroup);

// === HINGE MECHANISM ===
// Hinge barrel
const hingeBarrelGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.12, 16);
const hingeBarrel = new THREE.Mesh(hingeBarrelGeo, darkBrass);
hingeBarrel.rotation.z = Math.PI / 2;
hingeBarrel.position.set(0, 0.04, -0.52);
compassGroup.add(hingeBarrel);

// Hinge knuckle 1
const knuckleGeo = new THREE.SphereGeometry(0.03, 16, 16);
const knuckle1 = new THREE.Mesh(knuckleGeo, darkBrass);
knuckle1.position.set(-0.06, 0.04, -0.52);
compassGroup.add(knuckle1);

const knuckle2 = new THREE.Mesh(knuckleGeo, darkBrass);
knuckle2.position.set(0.06, 0.04, -0.52);
compassGroup.add(knuckle2);

// Hinge brackets
const bracketGeo = new THREE.BoxGeometry(0.04, 0.06, 0.06);
const bracket1 = new THREE.Mesh(bracketGeo, darkBrass);
bracket1.position.set(-0.04, 0.03, -0.50);
compassGroup.add(bracket1);

const bracket2 = new THREE.Mesh(bracketGeo, darkBrass);
bracket2.position.set(0.04, 0.03, -0.50);
compassGroup.add(bracket2);

// === LATCH / CATCH ===
const latchGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.15, 12);
const latch = new THREE.Mesh(latchGeo, polishedBrass);
latch.rotation.x = Math.PI / 2;
latch.position.set(0, 0.06, 0.52);
compassGroup.add(latch);

// Latch head
const latchHeadGeo = new THREE.SphereGeometry(0.03, 16, 16);
const latchHead = new THREE.Mesh(latchHeadGeo, polishedBrass);
latchHead.position.set(0, 0.06, 0.60);
compassGroup.add(latchHead);

// Latch catch on base
const catchGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.04, 12);
const catch_ = new THREE.Mesh(catchGeo, darkBrass);
catch_.rotation.x = Math.PI / 2;
catch_.position.set(0, 0.04, 0.55);
compassGroup.add(catch_);

// === COMPASS FACE (visible inside) ===
const faceGeo = new THREE.CircleGeometry(0.46, 64);
const faceMat = new THREE.MeshStandardMaterial({
  color: 0xf5f0e0,
  metalness: 0.0,
  roughness: 0.6,
  side: THREE.DoubleSide,
});
const face = new THREE.Mesh(faceGeo, faceMat);
face.rotation.x = -Math.PI / 2;
face.position.y = 0.035;
compassGroup.add(face);

// Cardinal direction markers
const markerGeo = new THREE.BoxGeometry(0.008, 0.002, 0.06);
const markerMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0, roughness: 0.8 });

const directions = [
  { angle: 0, label: 'N' },
  { angle: Math.PI / 2, label: 'E' },
  { angle: Math.PI, label: 'S' },
  { angle: Math.PI * 1.5, label: 'W' },
];

directions.forEach(d => {
  const marker = new THREE.Mesh(markerGeo, markerMat);
  marker.position.y = 0.036;
  marker.rotation.y = d.angle;
  if (d.label === 'N') marker.scale.z = 1.5;
  const r = 0.38;
  marker.position.x = Math.sin(d.angle) * r;
  marker.position.z = Math.cos(d.angle) * r;
  compassGroup.add(marker);
});

// Degree tick marks
for (let i = 0; i < 36; i++) {
  const tickGeo = new THREE.BoxGeometry(0.004, 0.001, i % 9 === 0 ? 0.03 : 0.015);
  const tick = new THREE.Mesh(tickGeo, markerMat);
  const angle = (i / 36) * Math.PI * 2;
  tick.position.y = 0.036;
  tick.rotation.y = angle;
  const r = 0.42;
  tick.position.x = Math.sin(angle) * r;
  tick.position.z = Math.cos(angle) * r;
  compassGroup.add(tick);
}

// Center pivot
const pivotGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.01, 24);
const pivot = new THREE.Mesh(pivotGeo, polishedBrass);
pivot.position.y = 0.038;
compassGroup.add(pivot);

// Needle
const needleHalfGeo = new THREE.BufferGeometry();
const nw = 0.012;
needleHalfGeo.setAttribute('position', new THREE.Float32BufferAttribute([
  0, 0, -0.25,
  nw, 0, 0,
  -nw, 0, 0,
], 3));
needleHalfGeo.computeVertexNormals();

const needleNorth = new THREE.Mesh(needleHalfGeo, new THREE.MeshStandardMaterial({
  color: 0xcc2222, metalness: 0.3, roughness: 0.5, side: THREE.DoubleSide
}));
needleNorth.position.y = 0.039;
compassGroup.add(needleNorth);

const needleSouth = new THREE.Mesh(needleHalfGeo.clone(), new THREE.MeshStandardMaterial({
  color: 0xeeeeee, metalness: 0.3, roughness: 0.5, side: THREE.DoubleSide
}));
needleSouth.position.y = 0.039;
needleSouth.rotation.y = Math.PI;
compassGroup.add(needleSouth);

// === DECORATIVE ENGRAVING RING ===
const engraveGeo = new THREE.TorusGeometry(0.53, 0.008, 8, 64);
const engraveMat = new THREE.MeshStandardMaterial({
  color: 0x6a5a15, metalness: 0.8, roughness: 0.4
});
const engrave = new THREE.Mesh(engraveGeo, engraveMat);
engrave.rotation.x = Math.PI / 2;
engrave.position.y = 0.001;
compassGroup.add(engrave);

// Second decorative ring
const engrave2Geo = new THREE.TorusGeometry(0.50, 0.006, 8, 64);
const engrave2 = new THREE.Mesh(engrave2Geo, engraveMat);
engrave2.rotation.x = Math.PI / 2;
engrave2.position.y = 0.001;
compassGroup.add(engrave2);

// Position compass group
compassGroup.rotation.y = 0.3;
scene.add(compassGroup);

// === LIGHTING ===
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(3, 5, 2);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xaabbff, 1);
fillLight.position.set(-3, 2, -1);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffddaa, 1.5);
rimLight.position.set(-1, 1, -3);
scene.add(rimLight);

const ambient = new THREE.AmbientLight(0x332211, 0.5);
scene.add(ambient);

// === CONTROLS ===
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0.15, 0);
controls.minDistance = 1.5;
controls.maxDistance = 6;
controls.update();

// === ANIMATE ===
function animate(time) {
  requestAnimationFrame(animate);
  compassGroup.rotation.y = 0.3 + Math.sin(time * 0.0003) * 0.15;
  controls.update();
  renderer.render(scene, camera);
}
animate(0);

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
