```

This creates a detailed **brass compass cover** scene with:

- **Dome cover** — a slightly flattened hemisphere hinged open at ~100°, revealing the compass face inside
- **Brass materials** — three PBR brass variants (polished, standard, dark/aged) with high metalness and environment reflections
- **Hinge mechanism** — barrel, knuckles, and brackets on the back
- **Latch/catch** — a small catch on the front rim
- **Compass face** — cream-colored dial with cardinal direction markers (N/E/S/W), degree tick marks, a center pivot, and a red/white needle
- **Decorative rings** — engraved detail bands around the base
- **Top knob** — a small polished brass boss on the dome apex
- **Three-point lighting** — warm key, cool fill, and rim light for dramatic metallic highlights
- **Gentle animation** — the compass slowly sways back and forth
- **Orbit controls** — drag to rotate, scroll to zoom

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snow Globe</title>
<style>
* { margin: 0; padding: 0; }
body { background: #1a1a2e; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.02);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.8, 0);
controls.enableDamping = true;
controls.minDistance = 3;
controls.maxDistance = 12;

// ── Lights ──
const ambient = new THREE.AmbientLight(0x8899bb, 0.5);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffeedd, 2);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x88aaff, 0.8);
fillLight.position.set(-4, 3, -2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff6644, 1.5, 15);
rimLight.position.set(-3, 5, -4);
scene.add(rimLight);

// ── Glass Globe ──
const globeRadius = 2;
const glassGeo = new THREE.SphereGeometry(globeRadius, 64, 64);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.05,
  ior: 1.52,
  thickness: 0.15,
  specularIntensity: 1,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1,
  side: THREE.DoubleSide,
  depthWrite: false,
});
const globe = new THREE.Mesh(glassGeo, glassMat);
globe.position.y = globeRadius;
scene.add(globe);

// ── Snow Drift (displaced lower hemisphere) ──
function noise2D(x, z) {
  const n = Math.sin(x * 3.7 + z * 1.3) * 0.5
          + Math.sin(x * 7.1 - z * 4.2) * 0.25
          + Math.sin(x * 13.3 + z * 9.7) * 0.125;
  return n;
}

const driftGeo = new THREE.SphereGeometry(globeRadius - 0.02, 128, 64, 0, Math.PI * 2, 0, Math.PI * 0.55);
const pos = driftGeo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
  const r = Math.sqrt(x * x + z * z);
  const falloff = Math.max(0, 1 - r / (globeRadius * 0.95));
  const displacement = noise2D(x, z) * falloff * 0.35;
  const len = Math.sqrt(x * x + y * y + z * z);
  const scale = (len + displacement) / len;
  pos.setXYZ(i, x * scale, y * scale, z * scale);
}
driftGeo.computeVertexNormals();

const snowMat = new THREE.MeshStandardMaterial({
  color: 0xf0f4ff,
  roughness: 0.9,
  metalness: 0,
  flatShading: false,
});
const drift = new THREE.Mesh(driftGeo, snowMat);
drift.position.y = globeRadius;
drift.rotation.x = Math.PI;
scene.add(drift);

// ── Pine Tree ──
const trunkGeo = new THREE.CylinderGeometry(0.03, 0.05, 0.3, 8);
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5c3a1e, roughness: 0.9 });
const trunk = new THREE.Mesh(trunkGeo, trunkMat);
trunk.position.set(0, globeRadius + 0.15, 0);
scene.add(trunk);

for (let i = 0; i < 4; i++) {
  const r = 0.35 - i * 0.07;
  const h = 0.25 - i * 0.03;
  const coneGeo = new THREE.ConeGeometry(r, h, 8);
  const coneMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color().setHSL(0.32, 0.6, 0.15 + i * 0.03),
    roughness: 0.8,
  });
  const cone = new THREE.Mesh(coneGeo, coneMat);
  cone.position.set(0, globeRadius + 0.3 + i * 0.18, 0);
  scene.add(cone);
}

// ── Tiny House ──
const houseGroup = new THREE.Group();
const wallGeo = new THREE.BoxGeometry(0.3, 0.25, 0.25);
const wallMat = new THREE.MeshStandardMaterial({ color: 0x8b4513, roughness: 0.8 });
const walls = new THREE.Mesh(wallGeo, wallMat);
walls.position.y = 0.125;
houseGroup.add(walls);

const roofGeo = new THREE.ConeGeometry(0.24, 0.18, 4);
const roofMat = new THREE.MeshStandardMaterial({ color: 0xcc3333, roughness: 0.7 });
const roof = new THREE.Mesh(roofGeo, roofMat);
roof.position.y = 0.34;
roof.rotation.y = Math.PI / 4;
houseGroup.add(roof);

const doorGeo = new THREE.BoxGeometry(0.06, 0.12, 0.01);
const doorMat = new THREE.MeshStandardMaterial({ color: 0x4a2a0a });
const door = new THREE.Mesh(doorGeo, doorMat);
door.position.set(0, 0.06, 0.13);
houseGroup.add(door);

const windowGeo = new THREE.BoxGeometry(0.05, 0.05, 0.01);
const windowMat = new THREE.MeshStandardMaterial({ color: 0xffee88, emissive: 0xffdd44, emissiveIntensity: 0.6 });
const win1 = new THREE.Mesh(windowGeo, windowMat);
win1.position.set(-0.08, 0.18, 0.13);
houseGroup.add(win1);
const win2 = win1.clone();
win2.position.x = 0.08;
houseGroup.add(win2);

houseGroup.position.set(0.7, globeRadius + 0.05, 0.3);
houseGroup.rotation.y = -0.4;
scene.add(houseGroup);

// ── Snow Particles ──
const snowCount = 600;
const snowGeo = new THREE.BufferGeometry();
const snowPositions = new Float32Array(snowCount * 3);
const snowVelocities = [];
for (let i = 0; i < snowCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = Math.random() * (globeRadius - 0.2);
  snowPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  snowPositions[i * 3 + 1] = r * Math.cos(phi) + globeRadius;
  snowPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  snowVelocities.push({
    x: (Math.random() - 0.5) * 0.003,
    y: -0.002 - Math.random() * 0.004,
    z: (Math.random() - 0.5) * 0.003,
  });
}
snowGeo.setAttribute('position', new THREE.BufferAttribute(snowPositions, 3));

const snowParticleMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.04,
  transparent: true,
  opacity: 0.85,
  sizeAttenuation: true,
  depthWrite: false,
});
const snowParticles = new THREE.Points(snowGeo, snowParticleMat);
scene.add(snowParticles);

// ── Globe Base ──
const baseGroup = new THREE.Group();

const baseMat = new THREE.MeshStandardMaterial({
  color: 0x3d2b1f,
  roughness: 0.4,
  metalness: 0.1,
});

const bottomGeo = new THREE.CylinderGeometry(1.2, 1.3, 0.15, 32);
const bottom = new THREE.Mesh(bottomGeo, baseMat);
bottom.position.y = 0;
baseGroup.add(bottom);

const midGeo = new THREE.CylinderGeometry(1.15, 1.2, 0.3, 32);
const mid = new THREE.Mesh(midGeo, baseMat);
mid.position.y = 0.225;
baseGroup.add(mid);

const topGeo = new THREE.CylinderGeometry(1.0, 1.15, 0.1, 32);
const top = new THREE.Mesh(topGeo, baseMat);
top.position.y = 0.4;
baseGroup.add(top);

const plaqueGeo = new THREE.BoxGeometry(0.6, 0.15, 0.02);
const plaqueMat = new THREE.MeshStandardMaterial({ color: 0xdaa520, roughness: 0.3, metalness: 0.6 });
const plaque = new THREE.Mesh(plaqueGeo, plaqueMat);
plaque.position.set(0, 0.225, 1.21);
baseGroup.add(plaque);

scene.add(baseGroup);

// ── Ground Plane ──
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2e, roughness: 1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.08;
scene.add(ground);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Snow fall
  const positions = snowParticles.geometry.attributes.position;
  for (let i = 0; i < snowCount; i++) {
    let x = positions.getX(i);
    let y = positions.getY(i);
    let z = positions.getZ(i);

    const v = snowVelocities[i];
    x += v.x + Math.sin(t * 0.5 + i) * 0.001;
    y += v.y;
    z += v.z + Math.cos(t * 0.5 + i) * 0.001;

    const dist = Math.sqrt(x * x + (y - globeRadius) ** 2 + z * z);
    if (dist > globeRadius - 0.15 || y < globeRadius - globeRadius + 0.1) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const r = Math.random() * 0.3;
      x = r * Math.sin(phi) * Math.cos(theta);
      y = globeRadius + r * Math.cos(phi) + 0.5;
      z = r * Math.sin(phi) * Math.sin(theta);
    }

    positions.setXYZ(i, x, y, z);
  }
  positions.needsUpdate = true;

  // Gentle globe rotation
  globe.rotation.y = t * 0.05;
  drift.rotation.y = t * 0.05;
  snowParticles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's included:**

- **Glass globe** — `MeshPhysicalMaterial` with transmission/ior for realistic glass refraction
- **Snow drift** — A displaced lower hemisphere with layered noise for organic terrain shape
- **Pine tree** — Stacked cones with a brown trunk, sitting on the drift
- **Tiny house** — Box with a red roof, glowing yellow windows, and a door
- **600 snow particles** — Falling with gentle sinusoidal drift, respawning at the top when they hit the bottom
- **Wooden base** — Three-tier cylinder with a gold plaque
- **Three-point lighting** — Warm key, cool fill, orange rim light
- **OrbitControls** — Drag to rotate, scroll to zoom
- **Gentle auto-rotation** of the entire globe contents

