```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Glass Marble Swirl</title>
<style>
  * { margin: 0; padding: 0; }
  body { background: #000; overflow: hidden; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<!-- ── vertex shader ── -->
<script id="vshader" type="x-shader/x-vertex">
  varying vec3 vNormal;
  varying vec3 vWorldPos;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    vWorldPos = (modelMatrix * vec4(position, 1.0)).xyz;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
</script>

<!-- ── fragment shader ── -->
<script id="fshader" type="x-shader/x-fragment">
  precision highp float;

  uniform vec3  uLightPos;
  uniform vec3  uCamPos;
  uniform float uTime;

  varying vec3 vNormal;
  varying vec3 vWorldPos;

  /* ── hash / noise ── */
  float hash(vec3 p) {
    p = fract(p * 0.3183099 + vec3(.1,.2,.3));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
  }

  float noise(vec3 p) {
    vec3 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(mix(hash(i), hash(i + vec3(1,0,0)), f.x),
          mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
      mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x),
          mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);
  }

  float fbm(vec3 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 5; i++) {
      v += a * noise(p);
      p = p * 2.1 + vec3(0.13, 0.27, -0.41);
      a *= 0.5;
    }
    return v;
  }

  void main() {
    vec3 N  = normalize(vNormal);
    vec3 V  = normalize(uCamPos - vWorldPos);
    vec3 L  = normalize(uLightPos - vWorldPos);
    vec3 R  = reflect(-V, N);
    vec3 H  = normalize(V + L);

    /* ── fresnel ── */
    float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

    /* ── internal swirl pattern ── */
    float t = uTime * 0.15;
    vec3  p = vWorldPos * 2.5;
    p.xz += vec2(sin(t), cos(t)) * 0.3;          // gentle rotation
    float n1 = fbm(p + vec3(t * 0.2));
    float n2 = fbm(p * 1.7 + vec3(0.0, t * 0.15, -t * 0.1));
    float swirl = smoothstep(0.35, 0.65, n1)
                + smoothstep(0.4, 0.6, n2) * 0.5;

    /* colour palette – cool glass tones */
    vec3 cInner  = mix(vec3(0.05, 0.15, 0.40),
                       vec3(0.70, 0.85, 1.00), swirl);
    cInner       = mix(cInner, vec3(0.90, 0.60, 0.30),
                       smoothstep(0.7, 1.0, n2) * 0.35);

    /* ── subsurface-like glow ── */
    float sss = pow(max(dot(V, -L + N * 0.5), 0.0), 3.0) * 0.45;

    /* ── specular highlight (Blinn-Phong) ── */
    float spec = pow(max(dot(N, H), 0.0), 120.0) * 1.8;
    float spec2 = pow(max(dot(N, H), 0.0), 32.0) * 0.35;

    /* ── environment reflection (fake gradient sky) ── */
    float skyY = R.y * 0.5 + 0.5;
    vec3 env = mix(vec3(0.02, 0.02, 0.06),
                   vec3(0.12, 0.18, 0.35), skyY);
    env += vec3(0.6, 0.3, 0.1) * pow(max(-R.y, 0.0), 4.0) * 0.5;

    /* ── compose ── */
    vec3 col = env * (1.0 - fresnel) * 0.3;          // base reflection
    col += cInner * swirl * 0.55;                     // swirl body
    col += cInner * sss;                              // subsurface glow
    col += vec3(1.0) * (spec + spec2);                // highlights
    col += vec3(0.6, 0.8, 1.0) * fresnel * 0.7;      // rim glow

    /* ── tone-map ── */
    col = col / (col + vec3(1.0));
    col = pow(col, vec3(1.0 / 2.2));

    gl_FragColor = vec4(col, 1.0);
  }
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ── renderer ── */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
document.body.appendChild(renderer.domElement);

/* ── scene & camera ── */
const scene  = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0.5, 4);

/* ── controls ── */
new OrbitControls(camera, renderer.domElement).enableDamping = true;

/* ── light position (uniform) ── */
const lightPos = new THREE.Vector3(3, 4, 5);

/* ── marble material ── */
const marbleMat = new THREE.ShaderMaterial({
  uniforms: {
    uLightPos: { value: lightPos },
    uCamPos:   { value: camera.position },
    uTime:     { value: 0 },
  },
  vertexShader:   document.getElementById('vshader').textContent,
  fragmentShader: document.getElementById('fshader').textContent,
});

/* ── marble mesh ── */
const marble = new THREE.Mesh(new THREE.SphereGeometry(1, 128, 128), marbleMat);
scene.add(marble);

/* ── subtle ground plane (for depth) ── */
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 20),
  new THREE.MeshBasicMaterial({ color: 0x050510 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
scene.add(ground);

/* ── animation loop ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  marbleMat.uniforms.uTime.value = clock.getElapsedTime();
  marbleMat.uniforms.uCamPos.value.copy(camera.position);
  marble.rotation.y = clock.getElapsedTime() * 0.08;
  renderer.render(scene, camera);
}
animate();

/* ── resize ── */
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
