    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510); // Dark night sky
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 1.0;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 2); // Warm sunlight
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const backLight = new THREE.PointLight(0x4444ff, 1); // Cool rim light
        backLight.position.set(-5, 0, -5);
        scene.add(backLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xd4af37, // Brass gold
            metalness: 0.9,
            roughness: 0.3,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.8,
            roughness: 0.4,
        });

        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x88ccff,
            metalness: 0,
            roughness: 0,
            transmission: 0.9,
            thickness: 0.5,
            transparent: true,
            opacity: 0.5
        });

        // Sextant Construction Group
        const sextantGroup = new THREE.Group();

        // 1. The Main Arc (60 degrees)
        // TorusGeometry(radius, tube, radialSegments, tubularSegments, arc)
        const arcRadius = 3;
        const arcGeometry = new THREE.TorusGeometry(arcRadius, 0.15, 16, 50, Math.PI / 3);
        const arc = new THREE.Mesh(arcGeometry, brassMaterial);
        arc.rotation.z = Math.PI / 2; // Orient flat
        arc.rotation.x = Math.PI / 2; // Stand up
        arc.position.set(0, 0, 0);
        arc.castShadow = true;
        sextantGroup.add(arc);

        // 2. The Index Arm (The moving part)
        const armLength = 3.5;
        const armGeometry = new THREE.BoxGeometry(0.1, 0.05, armLength);
        const indexArm = new THREE.Mesh(armGeometry, brassMaterial);
        indexArm.position.set(0, 0, -armLength / 2 + 0.5); // Offset to pivot at center
        indexArm.rotation.x = 0.2; // Tilt slightly up
        indexArm.castShadow = true;
        sextantGroup.add(indexArm);

        // 3. The Telescope (Sight tube)
        const telescopeGroup = new THREE.Group();

        // Main tube
        const tubeGeo = new THREE.CylinderGeometry(0.15, 0.15, 2, 32);
        const tube = new THREE.Mesh(tubeGeo, darkMetalMaterial);
        tube.rotation.x = Math.PI / 2;
        telescopeGroup.add(tube);

        // Eyepiece
        const eyeGeo = new THREE.CylinderGeometry(0.1, 0.15, 0.3, 32);
        const eye = new THREE.Mesh(eyeGeo, darkMetalMaterial);
        eye.rotation.x = Math.PI / 2;
        eye.position.z = 1.1;
        telescopeGroup.add(eye);

        // Objective lens housing
        const objGeo = new THREE.CylinderGeometry(0.25, 0.15, 0.4, 32);
        const obj = new THREE.Mesh(objGeo, darkMetalMaterial);
        obj.rotation.x = Math.PI / 2;
        obj.position.z = -1.1;
        telescopeGroup.add(obj);

        // Lens glass
        const lensGeo = new THREE.CircleGeometry(0.24, 32);
        const lens = new THREE.Mesh(lensGeo, glassMaterial);
        lens.position.z = -1.3;
        telescopeGroup.add(lens);

        // Position telescope on the frame
        telescopeGroup.position.set(0, 1.5, -1);
        telescopeGroup.rotation.x = 0.1;
        sextantGroup.add(telescopeGroup);

        // 4. The Frame/Handle (Simplified)
        const handleGeo = new THREE.BoxGeometry(0.8, 1.5, 0.2);
        const handle = new THREE.Mesh(handleGeo, brassMaterial);
        handle.position.set(0, -1.5, 0);
        handle.castShadow = true;
        sextantGroup.add(handle);

        // 5. Horizon Mirror (Fixed)
        const mirrorGeo = new THREE.BoxGeometry(0.4, 0.4, 0.05);
        const horizonMirror = new THREE.Mesh(mirrorGeo, glassMaterial);
        horizonMirror.position.set(0, 0.5, -1.5);
        horizonMirror.rotation.x = 0.5;
        sextantGroup.add(horizonMirror);

        // 6. Index Mirror (On the arm)
        const indexMirror = new THREE.Mesh(mirrorGeo, glassMaterial);
        indexMirror.position.set(0, 0, -0.5); // Near pivot
        indexMirror.rotation.x = 0.5;
        sextantGroup.add(indexMirror);

        // 7. Scale markings (Simple lines on the arc)
        const scaleGroup = new THREE.Group();
        for(let i=0; i<10; i++) {
            const angle = (Math.PI / 3) * (i / 10);
            const markGeo = new THREE.BoxGeometry(0.02, 0.1, 0.05);
            const mark = new THREE.Mesh(markGeo, darkMetalMaterial);

            // Position along the arc
            const r = arcRadius;
            mark.position.x = Math.cos(angle) * r;
            mark.position.y = Math.sin(angle) * r;
            mark.rotation.z = -angle + Math.PI/2;

            scaleGroup.add(mark);
        }
        scaleGroup.rotation.x = Math.PI / 2;
        scaleGroup.position.z = 0.1; // Slightly in front of arc
        sextantGroup.add(scaleGroup);

        // Add the whole sextant to scene
        scene.add(sextantGroup);

        // Background Stars (Particles)
        const starsGeometry = new THREE.BufferGeometry();
        const starsCount = 1000;
        const posArray = new Float32Array(starsCount * 3);

        for(let i = 0; i < starsCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 50;
        }

        starsGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const starsMaterial = new THREE.PointsMaterial({
            size: 0.05,
            color: 0xffffff,
            transparent: true,
            opacity: 0.8
        });
        const starMesh = new THREE.Points(starsGeometry, starsMaterial);
        scene.add(starMesh);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating motion
            const time = Date.now() * 0.001;
            sextantGroup.position.y = Math.sin(time) * 0.2;
            sextantGroup.rotation.z = Math.sin(time * 0.5) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
