            ctx.strokeStyle = `hsl(${Math.random() * 360}, 70%, 60%)`;
            ctx.lineWidth = Math.random() * 50 + 20;
            ctx.lineCap = 'round';
            ctx.moveTo(Math.random() * 512, Math.random() * 512);
            ctx.bezierCurveTo(
                Math.random() * 512, Math.random() * 512,
                Math.random() * 512, Math.random() * 512,
                Math.random() * 512, Math.random() * 512
            );
            ctx.stroke();
