<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Glass Snow Globe Water Surface</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050510; }
        canvas { display: block; }
    </style>
    <!-- Import Map for Three.js -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
</head>
<body>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510); // Dark blue/black background
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 6);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 0.5;

        // Lighting - Crucial for glass/water
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
        scene.add(ambientLight);

        const mainLight = new THREE.DirectionalLight(0xffffff, 2);
        mainLight.position.set(5, 10, 7);
        scene.add(mainLight);

        const fillLight = new THREE.DirectionalLight(0x4455ff, 1);
        fillLight.position.set(-5, 0, -5);
        scene.add(fillLight);

        const pointLight = new THREE.PointLight(0xffaa00, 5, 10);
        pointLight.position.set(0, 3, 0);
        scene.add(pointLight);

        // 1. The Glass Globe (Outer Shell)
        const globeGeometry = new THREE.SphereGeometry(2, 64, 64);
        const globeMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            ior: 1.5,
            clearcoat: 1,
            clearcoatRoughness: 0,
            transparent: true,
            opacity: 1
        });
        const globe = new THREE.Mesh(globeGeometry, globeMaterial);
        scene.add(globe);

        // 2. The Water Surface (Inside the globe)
        // We create a slightly curved surface or a plane inside
        const waterGeometry = new THREE.CircleGeometry(1.9, 64);
        const waterMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x0088ff,
            metalness: 0.1,
            roughness: 0.1,
            transmission: 0.6,
            thickness: 2,
            ior: 1.33,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide
        });
        const water = new THREE.Mesh(waterGeometry, waterMaterial);
        water.rotation.x = -Math.PI / 2;
        water.position.y = -0.5; // Positioned inside the lower half
        scene.add(water);

        // 3. Snow Particles
        const snowCount = 800;
        const snowGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(snowCount * 3);
        const velocities = [];

        for (let i = 0; i < snowCount; i++) {
            // Random position inside the sphere
            const r = 1.8 * Math.cbrt(Math.random());
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta);
            const z = r * Math.cos(phi);

            positions[i * 3] = x;
            positions[i * 3 + 1] = y;
            positions[i * 3 + 2] = z;

            velocities.push({
                x: (Math.random() - 0.5) * 0.01,
                y: -0.01 - Math.random() * 0.02, // Falling down
                z: (Math.random() - 0.5) * 0.01
            });
        }

        snowGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const snowMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.05,
            transparent: true,
            opacity: 0.8
        });
        const snow = new THREE.Points(snowGeometry, snowMaterial);
        scene.add(snow);

        // 4. Base of the Snow Globe
        const baseGeometry = new THREE.CylinderGeometry(1.5, 1.2, 0.5, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.2, 
            metalness: 0.8 
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = -2.2;
        scene.add(base);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Animate Water (gentle wave)
            const posAttribute = waterGeometry.attributes.position;
            for (let i = 0; i < posAttribute.count; i++) {
                const x = posAttribute.getX(i);
                const y = posAttribute.getY(i); // This is actually Z in local space before rotation
                // Simple sine wave based on distance from center
                const dist = Math.sqrt(x*x + y*y);
                const z = Math.sin(dist * 2 - time * 2) * 0.05;
                posAttribute.setZ(i, z);
            }
            posAttribute.needsUpdate = true;
            waterGeometry.computeVertexNormals();

            // Animate Snow
            const snowPos = snow.geometry.attributes.position;
            for (let i = 0; i < snowCount; i++) {
                let x = snowPos.getX(i);
                let y = snowPos.getY(i);
                let z = snowPos.getZ(i);

                // Apply velocity
                x += velocities[i].x;
                y += velocities[i].y;
                z += velocities[i].z;

                // Reset if below water level or out of bounds
                if (y < -1.5 || Math.abs(x) > 1.8 || Math.abs(z) > 1.8) {
                    // Reset to top
                    const r = 1.5 * Math.cbrt(Math.random());
                    const theta = Math.random() * 2 * Math.PI;
                    const phi = Math.acos(2 * Math.random() - 1);
                    x = r * Math.sin(phi) * Math.cos(theta);
                    y = 1.5; // Start near top
                    z = r * Math.cos(phi);
                }

                snowPos.setXYZ(i, x, y, z);
            }
            snowPos.needsUpdate = true;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
