<body>
<div id="info">Brass Telescope Tube Ring — drag to orbit · scroll to zoom</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.04);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.update();

// ── Materials ──
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xb8860b, metalness: 0.96, roughness: 0.22,
  envMapIntensity: 1.5
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8b6914, metalness: 0.94, roughness: 0.35
});

const padMat = new THREE.MeshStandardMaterial({
  color: 0x2a1a0a, metalness: 0.0, roughness: 0.85
});

const tubeMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a1a, metalness: 0.3, roughness: 0.6
});

// ── Env map (procedural) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x332211);
const light1 = new THREE.PointLight(0xffeedd, 100, 50);
light1.position.set(5, 8, 3);
envScene.add(light1);
const light2 = new THREE.PointLight(0xffaa44, 60, 50);
light2.position.set(-4, 3, -5);
envScene.add(light2);
const light3 = new THREE.PointLight(0xffffff, 40, 50);
light3.position.set(0, 6, 0);
envScene.add(light3);
const envMap = pmrem.fromScene(envScene).texture;
scene.environment = envMap;
brassMat.envMap = envMap;
darkBrassMat.envMap = envMap;

// ── Helpers ──
function makeRing(radius, tubeRadius, arc, padThickness, padWidth) {
  const group = new THREE.Group();

  // Main C-shaped ring body
  const ringGeo = new THREE.TorusGeometry(radius, tubeRadius, 24, 48, arc);
  const ring = new THREE.Mesh(ringGeo, brassMat);
  ring.castShadow = true;
  ring.receiveShadow = true;
  group.add(ring);

  // Filler blocks at the open gap (top faces of the C)
  const gapAngle = (2 * Math.PI - arc) / 2;
  const fillerRadius = radius + tubeRadius;
  for (let side = -1; side <= 1; side += 2) {
    const fillerGeo = new THREE.BoxGeometry(
      tubeRadius * 2.05, tubeRadius * 2.05, tubeRadius * 1.1
    );
    const filler = new THREE.Mesh(fillerGeo, brassMat);
    const angle = side * (Math.PI - gapAngle) / 2;
    filler.position.set(
      Math.sin(angle) * radius,
      Math.cos(angle) * radius,
      0
    );
    filler.rotation.z = angle;
    filler.castShadow = true;
    group.add(filler);
  }

  // Inner leather/felt padding
  if (padThickness > 0) {
    const padGeo = new THREE.TorusGeometry(radius - 0.005, padThickness, 16, 32, arc - 0.05);
    const pad = new THREE.Mesh(padGeo, padMat);
    pad.receiveShadow = true;
    group.add(pad);
  }

  // Bolts along the ring
  const boltCount = 5;
  for (let i = 0; i < boltCount; i++) {
    const angle = (arc / (boltCount - 1)) * i;
    const boltGeo = new THREE.CylinderGeometry(0.04, 0.04, tubeRadius * 2.1, 8);
    const bolt = new THREE.Mesh(boltGeo, darkBrassMat);
    bolt.position.set(
      Math.sin(angle) * radius,
      Math.cos(angle) * radius,
      0
    );
    bolt.rotation.z = angle;
    bolt.castShadow = true;
    group.add(bolt);
  }

  // Outer decorative ring edge
  const outerEdgeGeo = new THREE.TorusGeometry(radius + tubeRadius * 0.92, 0.025, 8, 48, arc);
  const outerEdge = new THREE.Mesh(outerEdgeGeo, darkBrassMat);
  outerEdge.castShadow = true;
  group.add(outerEdge);

  const innerEdgeGeo = new THREE.TorusGeometry(radius - tubeRadius * 0.92, 0.025, 8, 48, arc);
  const innerEdge = new THREE.Mesh(innerEdgeGeo, darkBrassMat);
  innerEdge.castShadow = true;
  group.add(innerEdge);

  return group;
}

function makeRingAssembly(zOffset, ringRadius = 1.0) {
  const assembly = new THREE.Group();

  // Two C-rings facing each other
  const arc = 1.55 * Math.PI; // ~279 degrees open

  const ring1 = makeRing(ringRadius, 0.12, arc, 0.04, 0.08);
  ring1.position.z = zOffset - 0.35;
  assembly.add(ring1);

  const ring2 = makeRing(ringRadius, 0.12, arc, 0.04, 0.08);
  ring2.position.z = zOffset + 0.35;
  ring2.rotation.y = Math.PI;
  assembly.add(ring2);

  // Fork arms connecting the two ring halves at the top
  for (let side = -1; side <= 1; side += 2) {
    const forkArmGeo = new THREE.BoxGeometry(0.08, 0.08, 0.8);
    const forkArm = new THREE.Mesh(forkArmGeo, brassMat);
    forkArm.position.set(0, ringRadius + 0.12, zOffset);
    forkArm.castShadow = true;
    assembly.add(forkArm);
  }

  // Clamp bolts on top
  for (let i = -1; i <= 1; i += 2) {
    const clampGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.9, 8);
    const clamp = new THREE.Mesh(clampGeo, darkBrassMat);
    clamp.position.set(i * 0.25, ringRadius + 0.12, zOffset);
    clamp.castShadow = true;
    assembly.add(clamp);

    // Wing nut on top
    const nutGeo = new THREE.CylinderGeometry(0.09, 0.09, 0.06, 6);
    const nut = new THREE.Mesh(nutGeo, darkBrassMat);
    nut.position.set(i * 0.25, ringRadius + 0.18, zOffset);
    assembly.add(nut);
  }

  return assembly;
}

// ── Build scene ──
const ringPair1 = makeRingAssembly(0, 1.0);
ringPair1.rotation.x = Math.PI * 0.5;
scene.add(ringPair1);

const ringPair2 = makeRingAssembly(1.8, 1.0);
ringPair2.rotation.x = Math.PI * 0.5;
scene.add(ringPair2);

// Telescope tube between rings
const tubeGeo = new THREE.CylinderGeometry(0.88, 0.88, 2.2, 48, 1, true);
const tube = new THREE.Mesh(tubeGeo, tubeMat);
tube.rotation.x = Math.PI * 0.5;
tube.position.z = 0.9;
tube.castShadow = true;
tube.receiveShadow = true;
scene.add(tube);

// Tube end cap (front)
const capGeo = new THREE.CylinderGeometry(0.92, 0.92, 0.08, 48);
const cap = new THREE.Mesh(capGeo, brassMat);
cap.rotation.x = Math.PI * 0.5;
cap.position.z = 2.0;
cap.castShadow = true;
scene.add(cap);

// Decorative rings on tube
for (let z of [0.3, 1.5]) {
  const decoGeo = new THREE.TorusGeometry(0.89, 0.02, 8, 48);
  const deco = new THREE.Mesh(decoGeo, brassMat);
  deco.position.z = z;
  scene.add(deco);
}

// ── Ground plane ──
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e, metalness: 0.5, roughness: 0.8
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.8;
ground.receiveShadow = true;
scene.add(ground);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 4);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 20;
keyLight.shadow.camera.left = -5;
keyLight.shadow.camera.right = 5;
keyLight.shadow.camera.top = 5;
keyLight.shadow.camera.bottom = -5;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 0.8);
fillLight.position.set(-4, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffaa44, 1.5);
rimLight.position.set(-2, 1, 6);
scene.add(rimLight);

const ambientLight = new THREE.AmbientLight(0x332211, 0.6);
scene.add(ambientLight);

// Warm point lights for brass sparkle
const point1 = new THREE.PointLight(0xffcc66, 2, 10);
point1.position.set(3, 4, 2);
scene.add(point1);

const point2 = new THREE.PointLight(0xff9933, 1.5, 8);
point2.position.set(-3, 2, -2);
scene.add(point2);

// ── Animate ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating rotation
  ringPair1.rotation.y = Math.sin(t * 0.3) * 0.05;
  ringPair2.rotation.y = Math.sin(t * 0.3) * 0.05;
  tube.rotation.y = Math.sin(t * 0.3) * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
