        // Create Swirl Texture Procedurally
        function createSwirlTexture() {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background
            ctx.fillStyle = '#000000';
            ctx.fillRect(0, 0, size, size);

            // Draw Swirl
            const centerX = size / 2;
            const centerY = size / 2;

            for (let i = 0; i < 200; i++) {
                const angle = i * 0.1;
                const radius = i * 1.5;
                const x = centerX + Math.cos(angle) * radius;
                const y = centerY + Math.sin(angle) * radius;

                ctx.beginPath();
                ctx.arc(x, y, 5 + Math.random() * 10, 0, Math.PI * 2);
                // Random bright colors for the swirl
                const hue = (i * 2) % 360;
                ctx.fillStyle = `hsl(${hue}, 80%, 60%)`;
                ctx.fill();
            }

            // Add some noise/grain
            for(let i=0; i<5000; i++) {
                ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1})`;
                ctx.fillRect(Math.random()*size, Math.random()*size, 2, 2);
            }

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // Inner Swirl Sphere (The "Center")
        const innerGeometry = new THREE.SphereGeometry(0.8, 64, 64);
        const innerMaterial = new THREE.MeshStandardMaterial({
            map: swirlTexture,
            emissive: 0xffffff,
            emissiveMap: swirlTexture,
            emissiveIntensity: 0.5,
            roughness: 0.4,
            metalness: 0.1
        });
        const innerSphere = new THREE.Mesh(innerGeometry, innerMaterial);
        scene.add(innerSphere);

        // Outer Glass Sphere
