// ── Dial Face Texture ──
function createDialTexture() {
  const c = document.createElement('canvas');
  c.width = 1024;
  c.height = 1024;
  const ctx = c.getContext('2d');
  const cx = 512, cy = 512, r = 480;

  // Parchment background
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  grad.addColorStop(0, '#f5f0e0');
  grad.addColorStop(0.7, '#ede6d0');
  grad.addColorStop(1, '#d8cda8');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();

  // Subtle ring pattern
  ctx.strokeStyle = 'rgba(139,119,75,0.15)';
  ctx.lineWidth = 1;
  for (let i = 1; i <= 8; i++) {
    ctx.beginPath();
    ctx.arc(cx, cy, r * (i / 10), 0, Math.PI * 2);
    ctx.stroke();
  }

  // Degree ticks
  ctx.lineWidth = 1.5;
  for (let deg = 0; deg < 360; deg += 5) {
    const rad = (deg - 90) * Math.PI / 180;
    const isMajor = deg % 30 === 0;
    const isMid = deg % 10 === 0;
    const len = isMajor ? 30 : isMid ? 20 : 10;
    const w = isMajor ? 2.5 : isMid ? 1.5 : 0.8;
    ctx.strokeStyle = deg % 30 === 0 ? '#2a2015' : '#5a4a30';
    ctx.lineWidth = w;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(rad) * (r - 30), cy + Math.sin(rad) * (r - 30));
    ctx.lineTo(cx + Math.cos(rad) * (r - 30 - len), cy + Math.sin(rad) * (r - 30 - len));
    ctx.stroke();
  }

  // Degree numbers
  ctx.fillStyle = '#2a2015';
  ctx.font = 'bold 28px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (let deg = 0; deg < 360; deg += 30) {
    const rad = (deg - 90) * Math.PI / 180;
    const nr = r - 62;
    ctx.fillText(`${deg}`, cx + Math.cos(rad) * nr, cy + Math.sin(rad) * nr);
  }

  // Cardinal directions
  ctx.font = 'bold 56px Georgia, serif';
  const dirs = [
    { label: 'N', deg: 0, color: '#8b0000' },
    { label: 'S', deg: 180, color: '#2a2015' },
    { label: 'E', deg: 90, color: '#2a2015' },
    { label: 'W', deg: 270, color: '#2a2015' },
  ];
  dirs.forEach(d => {
    const rad = (d.deg - 90) * Math.PI / 180;
    const dr = r - 110;
    ctx.fillStyle = d.color;
    ctx.fillText(d.label, cx + Math.cos(rad) * dr, cy + Math.sin(rad) * dr);
  });

  // Intercardinals
  ctx.font = 'bold 26px Georgia, serif';
  ctx.fillStyle = '#4a3a20';
  const inter = [
    { label: 'NE', deg: 45 }, { label: 'SE', deg: 135 },
    { label: 'SW', deg: 225 }, { label: 'NW', deg: 315 },
  ];
  inter.forEach(d => {
    const rad = (d.deg - 90) * Math.PI / 180;
    const dr = r - 155;
    ctx.fillText(d.label, cx + Math.cos(rad) * dr, cy + Math.sin(rad) * dr);
  });

  // Center circle
  ctx.fillStyle = '#c4a35a';
  ctx.beginPath();
  ctx.arc(cx, cy, 18, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#8a7235';
  ctx.lineWidth = 2;
  ctx.stroke();

  return new THREE.CanvasTexture(c);
}

