    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Environment for Glass Refraction
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        scene.environment = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;

        // Create Swirl Texture
        function createSwirlTexture() {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, size, size);

            // Draw Swirl
            const centerX = size / 2;
            const centerY = size / 2;

            for (let i = 0; i < 200; i++) {
                const angle = i * 0.1;
                const radius = i * 1.5;
                const x = centerX + Math.cos(angle) * radius;
                const y = centerY + Math.sin(angle) * radius;

                const hue = (i * 2) % 360;
                ctx.beginPath();
                ctx.arc(x, y, 10 + (i % 5), 0, Math.PI * 2);
                ctx.fillStyle = `hsla(${hue}, 70%, 50%, 0.3)`;
                ctx.fill();
            }

            // Add some noise/marble effect
            for(let i=0; i<500; i++) {
                const x = Math.random() * size;
                const y = Math.random() * size;
                ctx.beginPath();
                ctx.arc(x, y, Math.random() * 5, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(255, 255, 255, ${Math.random() * 0.5})`;
                ctx.fill();
            }

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // Geometry: Torus (Rim)
        const geometry = new THREE.TorusGeometry(2, 0.6, 64, 100);

        // Material: Glass Marble
        const material = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            map: swirlTexture,
            roughness: 0.05,
            metalness: 0.1,
            transmission: 0.95, // Glass-like transparency
            thickness: 1.5,     // Volume for refraction
            ior: 1.5,           // Index of refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            attenuationColor: new THREE.Color(0xffffff),
            attenuationDistance: 2,
            side: THREE.DoubleSide
        });

        const rim = new THREE.Mesh(geometry, material);
        scene.add(rim);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            rim.rotation.x += 0.005;
            rim.rotation.y += 0.01;

            controls.update();
            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
