<div id="info">drag to rotate · scroll to zoom</div>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js", "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/" } }
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);
scene.fog = new THREE.FogExp2(0x1a1a1a, 0.04);

const camera = new THREE.PerspectiveCamera(35, innerWidth / innerHeight, 0.1, 100);
camera.position.set(3, 2.5, 4);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 0.8, 0);
controls.minDistance = 2;
controls.maxDistance = 12;

// --- Materials ---
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xc8a84e,
  metalness: 0.92,
  roughness: 0.22,
  envMapIntensity: 1.5,
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8a7030,
  metalness: 0.95,
  roughness: 0.35,
});

const leatherMat = new THREE.MeshStandardMaterial({
  color: 0x3a1f0a,
  metalness: 0.0,
  roughness: 0.85,
});

// --- Env map (procedural) ---
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x302820);
const envLight1 = new THREE.PointLight(0xffeedd, 3, 20);
envLight1.position.set(3, 5, 2);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0x8899bb, 2, 20);
envLight2.position.set(-4, 3, -2);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene, 0.04);
scene.environment = envRT.texture;

// --- Lighting ---
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(4, 6, 3);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 20;
keyLight.shadow.camera.left = -4;
keyLight.shadow.camera.right = 4;
keyLight.shadow.camera.top = 4;
keyLight.shadow.camera.bottom = -4;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899bb, 0.8);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffddaa, 1.5);
rimLight.position.set(-2, 4, -4);
scene.add(rimLight);

const amb = new THREE.AmbientLight(0x302820, 0.5);
scene.add(amb);

// --- Ground ---
const ground = new THREE.Mesh(
  new THREE.CircleGeometry(6, 64),
  new THREE.MeshStandardMaterial({ color: 0x111111, metalness: 0.3, roughness: 0.9 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// --- Telescope Cap Group ---
const cap = new THREE.Group();

// Main body via LatheGeometry
const profile = [];
const R = 0.65;       // bottom outer radius
const rTop = 0.55;    // top outer radius (slightly tapered)
const H = 2.2;        // body height
const wall = 0.04;    // wall thickness
const domeR = rTop;
const knobR = 0.08;
const knobH = 0.15;

// Build profile from bottom to top (outer surface)
profile.push(new THREE.Vector2(0.001, 0));
profile.push(new THREE.Vector2(R, 0));
// Slight lip at bottom
profile.push(new THREE.Vector2(R + 0.02, 0.02));
profile.push(new THREE.Vector2(R + 0.03, 0.04));
profile.push(new THREE.Vector2(R + 0.02, 0.06));
profile.push(new THREE.Vector2(R, 0.08));
// Body taper
profile.push(new THREE.Vector2(rTop + 0.01, H));
// Dome transition
for (let i = 0; i <= 12; i++) {
  const t = i / 12;
  const angle = Math.PI / 2 * (1 - t);
  const x = domeR * Math.cos(angle);
  const y = H + domeR * Math.sin(angle);
  profile.push(new THREE.Vector2(x, y));
}
// Knob base
profile.push(new THREE.Vector2(knobR + 0.02, H + domeR + 0.02));
profile.push(new THREE.Vector2(knobR + 0.02, H + domeR + 0.03));
// Knob
profile.push(new THREE.Vector2(knobR, H + domeR + knobH));
profile.push(new THREE.Vector2(0.001, H + domeR + knobH + 0.01));

const bodyGeo = new THREE.LatheGeometry(profile, 64);
bodyGeo.computeVertexNormals();
const body = new THREE.Mesh(bodyGeo, brassMat);
body.castShadow = true;
body.receiveShadow = true;
cap.add(body);

// --- Decorative bands ---
function makeBand(y, radius, thickness, segments = 48) {
  const geo = new THREE.TorusGeometry(radius, thickness, 8, segments);
  const mesh = new THREE.Mesh(geo, darkBrassMat);
  mesh.position.y = y;
  mesh.rotation.x = Math.PI / 2;
  mesh.castShadow = true;
  return mesh;
}

cap.add(makeBand(0.15, R + 0.005, 0.018));
cap.add(makeBand(H * 0.3, R - 0.02, 0.012));
cap.add(makeBand(H * 0.6, R - 0.05, 0.012));
cap.add(makeBand(H * 0.85, rTop + 0.03, 0.010));
cap.add(makeBand(H - 0.05, rTop + 0.015, 0.015));

// --- Grip ridges (vertical grooves around the body) ---
const ridgeCount = 24;
for (let i = 0; i < ridgeCount; i++) {
  const angle = (i / ridgeCount) * Math.PI * 2;
  const ridgeH = H * 0.7;
  const ridgeY = H * 0.35;
  const midR = R - 0.03;

  const ridgeGeo = new THREE.BoxGeometry(0.008, ridgeH, 0.025);
  const ridge = new THREE.Mesh(ridgeGeo, darkBrassMat);
  ridge.position.set(
    Math.cos(angle) * midR,
    ridgeY,
    Math.sin(angle) * midR
  );
  ridge.rotation.y = -angle;
  ridge.castShadow = true;
  cap.add(ridge);
}

// --- Inner surface (dark, to show it's hollow) ---
const innerProfile = [];
const innerR = R - wall;
const innerTopR = rTop - wall;
const innerH = H;

innerProfile.push(new THREE.Vector2(0.001, 0));
innerProfile.push(new THREE.Vector2(innerR, 0));
innerProfile.push(new THREE.Vector2(innerR, 0.08));
innerProfile.push(new THREE.Vector2(innerTopR, innerH));
// Inner dome
for (let i = 0; i <= 10; i++) {
  const t = i / 10;
  const angle = Math.PI / 2 * (1 - t);
  const x = innerTopR * Math.cos(angle);
  const y = innerH + innerTopR * Math.sin(angle);
  innerProfile.push(new THREE.Vector2(x, y));
}
innerProfile.push(new THREE.Vector2(0.001, innerH + innerTopR + 0.01));

const innerGeo = new THREE.LatheGeometry(innerProfile, 48);
const innerMat = new THREE.MeshStandardMaterial({
  color: 0x2a1f0a,
  metalness: 0.6,
  roughness: 0.7,
  side: THREE.DoubleSide,
});
const inner = new THREE.Mesh(innerGeo, innerMat);
cap.add(inner);

// --- Leather strap detail ---
const strapGeo = new THREE.TorusGeometry(R + 0.025, 0.035, 6, 48, Math.PI * 0.6);
const strap = new THREE.Mesh(strapGeo, leatherMat);
strap.position.y = H * 0.55;
strap.rotation.x = Math.PI / 2;
strap.rotation.z = Math.PI * 0.7;
strap.castShadow = true;
cap.add(strap);

// --- Small screw/rivet details on bands ---
for (let b = 0; b < 5; b++) {
  const bandY = [0.15, H * 0.3, H * 0.6, H * 0.85, H - 0.05][b];
  const bandR = [R + 0.005, R - 0.02, R - 0.05, rTop + 0.03, rTop + 0.015][b];
  for (let j = 0; j < 4; j++) {
    const a = (j / 4) * Math.PI * 2 + b * 0.3;
    const rivet = new THREE.Mesh(
      new THREE.SphereGeometry(0.015, 8, 8),
      darkBrassMat
    );
    rivet.position.set(Math.cos(a) * bandR, bandY, Math.sin(a) * bandR);
    rivet.scale.y = 0.5;
    cap.add(rivet);
  }
}

cap.position.y = 0;
scene.add(cap);

// --- Animation ---
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  cap.rotation.y = Math.sin(t * 0.3) * 0.15;
  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
