</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ─── Scene Setup ───
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.2, 5);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// ─── Environment for glass reflections ───
const pmremGenerator = new THREE.PMREMGenerator(renderer);
const envTexture = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envTexture;

// ─── Post-processing ───
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight), 0.4, 0.5, 0.85
);
composer.addPass(bloomPass);

// ─── Controls ───
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0.8, 0);
controls.minDistance = 3;
controls.maxDistance = 10;
controls.maxPolarAngle = Math.PI * 0.85;
controls.update();

// ─── Lighting ───
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const mainLight = new THREE.DirectionalLight(0xffeedd, 2.5);
mainLight.position.set(5, 8, 5);
mainLight.castShadow = true;
mainLight.shadow.mapSize.set(1024, 1024);
mainLight.shadow.camera.near = 0.1;
mainLight.shadow.camera.far = 20;
mainLight.shadow.camera.left = -3;
mainLight.shadow.camera.right = 3;
mainLight.shadow.camera.top = 3;
mainLight.shadow.camera.bottom = -3;
scene.add(mainLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.8);
fillLight.position.set(-3, 4, -2);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffd4a6, 1.2);
rimLight.position.set(-2, 2, -5);
scene.add(rimLight);

const pointLight = new THREE.PointLight(0xaaccff, 1, 10);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// ─── Background gradient ───
const bgCanvas = document.createElement('canvas');
bgCanvas.width = 2; bgCanvas.height = 512;
const bgCtx = bgCanvas.getContext('2d');
const grad = bgCtx.createLinearGradient(0, 0, 0, 512);
grad.addColorStop(0, '#1a1a3e');
grad.addColorStop(0.5, '#0d0d2b');
grad.addColorStop(1, '#0a0a1a');
bgCtx.fillStyle = grad;
bgCtx.fillRect(0, 0, 2, 512);
const bgTexture = new THREE.CanvasTexture(bgCanvas);
scene.background = bgTexture;

// ─── Globe parameters ───
const GLOBE_RADIUS = 1.6;
const GLOBE_CENTER_Y = GLOBE_RADIUS + 0.1;

// ─── Glass Globe ───
const glassGeo = new THREE.SphereGeometry(GLOBE_RADIUS, 128, 128);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.05,
  ior: 1.52,
  thickness: 0.15,
  envMapIntensity: 1.5,
  clearcoat: 1.0,
  clearcoatRoughness: 0.02,
  side: THREE.DoubleSide,
  attenuationColor: new THREE.Color(0xddeeff),
  attenuationDistance: 2,
});
const glassSphere = new THREE.Mesh(glassGeo, glassMat);
glassSphere.position.y = GLOBE_CENTER_Y;
glassSphere.castShadow = true;
scene.add(glassSphere);

// ─── Glass rim highlight ───
const rimGeo = new THREE.TorusGeometry(GLOBE_RADIUS * 0.998, 0.015, 16, 128);
const rimMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, emissive: 0x4488cc, emissiveIntensity: 0.3,
  roughness: 0.1, metalness: 0.3, transparent: true, opacity: 0.6
});
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.position.y = GLOBE_CENTER_Y;
rim.rotation.x = Math.PI / 2;
scene.add(rim);

// ─── Snow Ground (inside globe) ───
const snowGroundGeo = new THREE.SphereGeometry(GLOBE_RADIUS * 0.97, 64, 32, 0, Math.PI * 2, 0, Math.PI * 0.35);
const snowGroundMat = new THREE.MeshPhysicalMaterial({
  color: 0xf0f4ff,
  roughness: 0.8,
  metalness: 0.0,
  clearcoat: 0.1,
  side: THREE.DoubleSide,
});
const snowGround = new THREE.Mesh(snowGroundGeo, snowGroundMat);
snowGround.position.y = GLOBE_CENTER_Y;
snowGround.rotation.x = Math.PI;
scene.add(snowGround);

// ─── Snow mounds ───
const moundGeo = new THREE.SphereGeometry(0.35, 16, 16);
const moundMat = new THREE.MeshPhysicalMaterial({
  color: 0xeef2ff, roughness: 0.9, metalness: 0.0
});

for (let i = 0; i < 5; i++) {
  const mound = new THREE.Mesh(moundGeo, moundMat);
  const angle = (i / 5) * Math.PI * 2 + Math.random() * 0.5;
  const r = 0.5 + Math.random() * 0.4;
  mound.position.set(
    Math.cos(angle) * r,
    GLOBE_CENTER_Y - GLOBE_RADIUS * 0.75 + Math.random() * 0.1,
    Math.sin(angle) * r
  );
  mound.scale.set(1 + Math.random() * 0.5, 0.4 + Math.random() * 0.3, 1 + Math.random() * 0.5);
  mound.castShadow = true;
  mound.receiveShadow = true;
  scene.add(mound);
}

// ─── Christmas Tree ───
function createTree() {
  const group = new THREE.Group();

  // Trunk
  const trunkGeo = new THREE.CylinderGeometry(0.04, 0.06, 0.25, 8);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5c3a1e, roughness: 0.9 });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = 0.125;
  trunk.castShadow = true;
  group.add(trunk);

  // Foliage layers
  const foliageMat = new THREE.MeshPhysicalMaterial({
    color: 0x1a5c2a, roughness: 0.7, metalness: 0.0,
    clearcoat: 0.2
  });

  const layers = [
    { r: 0.35, h: 0.3, y: 0.4 },
    { r: 0.28, h: 0.28, y: 0.62 },
    { r: 0.2, h: 0.25, y: 0.82 },
    { r: 0.12, h: 0.2, y: 0.98 },
  ];

  layers.forEach(l => {
    const coneGeo = new THREE.ConeGeometry(l.r, l.h, 8);
    const cone = new THREE.Mesh(coneGeo, foliageMat);
    cone.position.y = l.y;
    cone.castShadow = true;
    cone.receiveShadow = true;
    group.add(cone);
  });

  // Star
  const starGeo = new THREE.OctahedronGeometry(0.06, 0);
  const starMat = new THREE.MeshPhysicalMaterial({
    color: 0xffdd44, emissive: 0xffaa00, emissiveIntensity: 2,
    roughness: 0.1, metalness: 0.8
