<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Brass Protractor Center</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #1a1a1a; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);

// ── Camera ──
const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.01, 100);
camera.position.set(0, 0.4, 1.2);
camera.lookAt(0, 0, 0);

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 0.3;
controls.maxDistance = 4;
controls.target.set(0, 0.02, 0);

// ── Brass Material ──
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xb8860b,
  metalness: 0.95,
  roughness: 0.25,
  clearcoat: 0.3,
  clearcoatRoughness: 0.15,
  reflectivity: 1.0,
});

const darkBrassMat = new THREE.MeshPhysicalMaterial({
  color: 0x8b6914,
  metalness: 0.95,
  roughness: 0.4,
  clearcoat: 0.2,
});

// ── Build Semicircle Body ──
const RADIUS = 0.4;
const THICKNESS = 0.015;
const innerR = RADIUS * 0.15;

function createProtractorBody() {
  const shape = new THREE.Shape();
  // outer semicircle
  shape.absarc(0, 0, RADIUS, Math.PI, 0, false);
  // inner semicircle (hole)
  const holePath = new THREE.Path();
  holePath.absarc(0, 0, innerR, 0, Math.PI, true);
  shape.holes.push(holePath);

  const extrudeSettings = { depth: THICKNESS, bevelEnabled: true, bevelThickness: 0.002, bevelSize: 0.002, bevelSegments: 3 };
  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.center();
  return new THREE.Mesh(geo, brassMat);
}

const protractor = createProtractorBody();
protractor.castShadow = true;
protractor.receiveShadow = true;
scene.add(protractor);

// ── Center Mark (raised brass disc) ──
const centerDiscGeo = new THREE.CylinderGeometry(0.018, 0.018, THICKNESS + 0.004, 32);
const centerDisc = new THREE.Mesh(centerDiscGeo, brassMat);
centerDisc.position.set(0, 0, THICKNESS / 2 + 0.002);
scene.add(centerDisc);

// center hole
const centerHoleGeo = new THREE.CylinderGeometry(0.005, 0.005, THICKNESS + 0.006, 16);
const centerHole = new THREE.Mesh(centerHoleGeo, darkBrassMat);
centerHole.position.set(0, 0, THICKNESS / 2 + 0.002);
scene.add(centerHole);

// ── Tick Marks ──
function createTick(angleDeg, major) {
  const angleRad = -angleDeg * Math.PI / 180 + Math.PI; // flipped for visual
  const a = -angleDeg * Math.PI / 180;
  const outerR = RADIUS;
  const innerR2 = major ? RADIUS * 0.82 : RADIUS * 0.88;

  const shape = new THREE.Shape();
  shape.absarc(0, 0, outerR, a, a, false);
  shape.lineTo(
    Math.cos(a) * innerR2,
    Math.sin(a) * innerR2
  );
  shape.absarc(0, 0, innerR2, a, a, true);
  shape.closePath();

  const extSettings = { depth: THICKNESS, bevelEnabled: false };
  const geo = new THREE.ExtrudeGeometry(shape, extSettings);
  const mesh = new THREE.Mesh(geo, darkBrassMat);
  mesh.position.z = THICKNESS / 2;
  return mesh;
}

for (let deg = 0; deg <= 180; deg += 1) {
  const major = deg % 10 === 0;
  const mid   = deg % 5 === 0 && deg % 10 !== 0;
  if (!major && !mid) continue;

  const tick = createTick(deg, major || mid);
  scene.add(tick);
}

// ── Degree Labels (canvas textures on planes) ──
function createLabel(deg, position) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'transparent';
  ctx.fillRect(0, 0, 128, 64);
  ctx.font = 'bold 42px Georgia, serif';
  ctx.fillStyle = '#5a4210';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(deg.toString(), 64, 32);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const mat = new THREE.MeshBasicMaterial({ map: texture, transparent: true, depthWrite: false });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.06, 0.03), mat);
  plane.position.copy(position);
  plane.position.z = THICKNESS + 0.001;
  plane.rotation.x = -Math.PI / 2;
  return plane;
}

for (let deg = 0; deg <= 180; deg += 30) {
  const a = -deg * Math.PI / 180;
  const labelR = RADIUS * 0.65;
  const pos = new THREE.Vector3(Math.cos(a) * labelR, Math.sin(a) * labelR, 0);
  scene.add(createLabel(deg, pos));
}

// ── Straight Edge Line (decorative groove) ──
const grooveGeo = new THREE.BoxGeometry(RADIUS * 2, 0.002, THICKNESS + 0.002);
const groove = new THREE.Mesh(grooveGeo, darkBrassMat);
groove.position.set(0, 0, THICKNESS / 2 + 0.001);
scene.add(groove);

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0xfff5e6, 0.6);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3.5);
keyLight.position.set(2, 3, 2);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc8b8ff, 1.2);
fillLight.position.set(-2, 1, -1);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffd699, 2.0);
rimLight.position.set(0, -1, -3);
scene.add(rimLight);

// point light for specular sparkle
const spark = new THREE.PointLight(0xffffff, 2, 5);
spark.position.set(0.3, 0.5, 0.6);
scene.add(spark);

// ── Ground plane (subtle reflection surface) ──
const groundGeo = new THREE.PlaneGeometry(10, 10);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8, metalness: 0.2 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.02;
ground.receiveShadow = true;
scene.add(ground);

// ── Env map (simple PMREM from scene) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new THREE.Scene(), 0.04).texture;
scene.environment = envMap;

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ── Animate ──
function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
```

This single file creates a **3D brass protractor** with:

- **Semicircular body** — an extruded half-ring with beveled edges, rendered in a realistic brass `MeshPhysicalMaterial` (high metalness, warm gold color, clearcoat)
- **Degree tick marks** — minor ticks every 5°, major ticks every 10° along the arc, extruded as dark-brass grooves
- **Center mark** — a raised brass disc with a small center hole, sitting at the protractor's origin point
- **Degree labels** — canvas-textured planes showing 0°, 30°, 60°, … 180°
- **Decorative straight-edge groove** along the flat baseline
- **Multi-light setup** — warm key, purple fill, golden rim, and a specular sparkle point light for metallic reflections
- **OrbitControls** — drag to rotate, scroll to zoom

