        const pointLight = new THREE.PointLight(0x4444ff, 1, 20);
        pointLight.position.set(-5, 2, -5);
        scene.add(pointLight);

        // Snow Globe Group
        const globeGroup = new THREE.Group();
        scene.add(globeGroup);

        // 1. The Glass Sphere
        const glassGeometry = new THREE.SphereGeometry(2, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 1,
            side: THREE.DoubleSide
        });
        const glassSphere = new THREE.Mesh(glassGeometry, glassMaterial);
        globeGroup.add(glassSphere);

        // 2. The Base
        const baseGeometry = new THREE.CylinderGeometry(1.8, 1.6, 0.8, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.8,
            roughness: 0.2
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = -2.2;
        globeGroup.add(base);

        // 3. Snowflakes Cluster
        const snowflakeGroup = new THREE.Group();
        globeGroup.add(snowflakeGroup);

        const snowflakeGeometry = new THREE.IcosahedronGeometry(0.05, 0);
        const snowflakeMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            emissive: 0xaaaaaa,
            emissiveIntensity: 0.5,
            roughness: 0.1,
            metalness: 0.1
        });

        const snowflakes = [];
        const numSnowflakes = 150;

        for (let i = 0; i < numSnowflakes; i++) {
            const snowflake = new THREE.Mesh(snowflakeGeometry, snowflakeMaterial);

            // Random position inside sphere
            const r = 1.8 * Math.cbrt(Math.random());
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            snowflake.position.x = r * Math.sin(phi) * Math.cos(theta);
            snowflake.position.y = r * Math.sin(phi) * Math.sin(theta) - 0.5; // Shift down slightly
            snowflake.position.z = r * Math.cos(phi);

            // Random rotation
            snowflake.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);

            // Store initial data for animation
            snowflake.userData = {
                speed: 0.002 + Math.random() * 0.005,
                offset: Math.random() * 100,
                radius: r,
                theta: theta,
                phi: phi
            };

            snowflakeGroup.add(snowflake);
            snowflakes.push(snowflake);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Animate snowflakes gently swirling
            snowflakes.forEach(flake => {
                const d = flake.userData;
                // Gentle rotation around Y axis
                const currentTheta = d.theta + time * d.speed * 10;
                const currentPhi = d.phi + Math.sin(time * 0.5 + d.offset) * 0.1;

                // Keep them roughly in their spherical volume but moving
                flake.position.x = d.radius * Math.sin(currentPhi) * Math.cos(currentTheta);
                flake.position.z = d.radius * Math.sin(currentPhi) * Math.sin(currentTheta);
                flake.position.y = d.radius * Math.cos(currentPhi) - 0.5 + Math.sin(time * 2 + d.offset) * 0.1;

                flake.rotation.x += d.speed;
                flake.rotation.y += d.speed;
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
