envScene.background=new THREE.Color(0x332211);
const envLight1=new THREE.DirectionalLight(0xffeedd,3);
envLight1.position.set(5,10,5);
envScene.add(envLight1);
const envLight2=new THREE.DirectionalLight(0x8899bb,1);
envLight2.position.set(-5,3,-5);
envScene.add(envLight2);
const envLight3=new THREE.DirectionalLight(0xffccaa,2);
envLight3.position.set(0,5,8);
envScene.add(envLight3);
const envRT=pmrem.fromScene(envScene);
scene.environment=envRT.texture;

// Ground
const ground=new THREE.Mesh(
  new THREE.PlaneGeometry(40,40),
  new THREE.MeshStandardMaterial({color:0x2a2218,roughness:0.9,metalness:0.05})
);
ground.rotation.x=-Math.PI/2;
ground.receiveShadow=true;
scene.add(ground);

// Stone pedestal
const pedestal=new THREE.Mesh(
  new THREE.CylinderGeometry(2.2,2.5,0.6,48),
  new THREE.MeshStandardMaterial({color:0x555550,roughness:0.85,metalness:0.1})
);
pedestal.position.y=0.3;
pedestal.castShadow=true;
pedestal.receiveShadow=true;
scene.add(pedestal);

// Decorative ring on pedestal
const pedRing=new THREE.Mesh(
  new THREE.TorusGeometry(2.35,0.06,8,48),
  darkBrass
);
pedRing.rotation.x=Math.PI/2;
pedRing.position.y=0.6;
scene.add(pedRing);

// Sundial plate
const plate=new THREE.Mesh(
  new THREE.CylinderGeometry(2,2,0.12,64),
  brass
);
plate.position.y=0.66;
plate.castShadow=true;
plate.receiveShadow=true;
scene.add(plate);

// Outer decorative ring
const outerRing=new THREE.Mesh(
  new THREE.TorusGeometry(1.95,0.08,12,64),
  darkBrass
);
outerRing.rotation.x=Math.PI/2;
outerRing.position.y=0.73;
scene.add(outerRing);

// Inner decorative ring
const innerRing=new THREE.Mesh(
  new THREE.TorusGeometry(1.4,0.04,10,64),
  darkBrass
);
innerRing.rotation.x=Math.PI/2;
innerRing.position.y=0.73;
scene.add(innerRing);

// Hour markers (small dots between numerals)
for(let i=0;i<60;i++){
  const a=(i/60)*Math.PI*2-Math.PI/2;
  const isHour=i%5===0;
  const r=isHour?1.72:1.78;
  const dot=new THREE.Mesh(
    new THREE.CylinderGeometry(isHour?0.035:0.02, isHour?0.035:0.02, 0.03, 8),
    isHour?polishedBrass:darkBrass
  );
  dot.position.set(Math.cos(a)*r, 0.74, Math.sin(a)*r);
  scene.add(dot);
}

// Roman numerals
const romans=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];

function makeNumeralTexture(text){
  const c=document.createElement('canvas');
  c.width=256;c.height=128;
  const ctx=c.getContext('2d');
  ctx.clearRect(0,0,256,128);
  ctx.fillStyle='#1a1410';
  ctx.font='bold 72px serif';
  ctx.textAlign='center';
  ctx.textBaseline='middle';
  ctx.fillText(text,128,64);
  const tex=new THREE.CanvasTexture(c);
  tex.minFilter=THREE.LinearFilter;
  return tex;
}

