const gnomon=new THREE.Mesh(gnomonGeom,polishedBrass);
gnomon.position.set(0,0.72,-0.04);
gnomon.rotation.x=-0.4;
gnomon.castShadow=true;
scene.add(gnomon);

// Gnomon base plate
const gnomonBase=new THREE.Mesh(
