);
centerOrn.position.set(0,0.75,0);
centerOrn.castShadow=true;
scene.add(centerOrn);

// Small decorative feet (4 corner brackets)
for(let i=0;i<4;i++){
  const a=(i/4)*Math.PI*2+Math.PI/4;
  const foot=new THREE.Mesh(
    new THREE.CylinderGeometry(0.08,0.12,0.15,8),
