  );
  foot.position.set(Math.cos(a)*2.1,0.15,Math.sin(a)*2.1);
  foot.castShadow=true;
  scene.add(foot);
}

// Lighting
const sunLight=new THREE.DirectionalLight(0xffeedd,4);
sunLight.position.set(3,8,4);
sunLight.castShadow=true;
sunLight.shadow.mapSize.set(2048,2048);
sunLight.shadow.camera.near=0.5;
sunLight.shadow.camera.far=25;
sunLight.shadow.camera.left=-5;
sunLight.shadow.camera.right=5;
sunLight.shadow.camera.top=5;
sunLight.shadow.camera.bottom=-5;
sunLight.shadow.bias=-0.001;
scene.add(sunLight);

const fillLight=new THREE.DirectionalLight(0x8899bb,0.8);
fillLight.position.set(-4,3,-3);
scene.add(fillLight);

const rimLight=new THREE.DirectionalLight(0xffcc88,1.5);
rimLight.position.set(-2,5,6);
scene.add(rimLight);

const ambient=new THREE.AmbientLight(0x332211,0.5);
scene.add(ambient);

// Shadow indicator line from gnomon
const shadowLine=new THREE.Mesh(
  new THREE.PlaneGeometry(1.2,0.06),
  new THREE.MeshStandardMaterial({color:0x000000,transparent:true,opacity:0.3,roughness:1,metalness:0})
);
shadowLine.rotation.x=-Math.PI/2;
shadowLine.rotation.z=0.3;
shadowLine.position.set(0.35,0.731,0.15);
scene.add(shadowLine);

// Animation
const clock=new THREE.Clock();

function animate(){
  requestAnimationFrame(animate);
  const t=clock.getElapsedTime();

  // Slowly rotate sun light to simulate time passing
  const sunAngle=t*0.15;
  sunLight.position.x=Math.cos(sunAngle)*6;
  sunLight.position.z=Math.sin(sunAngle)*6;
  sunLight.position.y=6+Math.sin(sunAngle*0.5)*2;

  // Shadow follows sun
  shadowLine.rotation.z=-sunAngle*0.3+0.5;
  shadowLine.position.x=Math.cos(-sunAngle*0.3+0.5)*0.5;
  shadowLine.position.z=Math.sin(-sunAngle*0.3+0.5)*0.5;
  shadowLine.scale.x=0.8+Math.sin(sunAngle*0.3)*0.4;

  controls.update();
  renderer.render(scene,camera);
}
animate();

window.addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});
</script>
</body>
</html>
