<body>
    <div id="info">drag to orbit · scroll to zoom</div>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 4.5);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        // Environment for realistic glass reflections
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const envMap = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
        scene.environment = envMap;

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.minDistance = 2;
        controls.maxDistance = 10;

        // --- Procedural Swirl Texture Generation ---
        function createSwirlTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Base gradient
            const gradient = ctx.createRadialGradient(size/2, size/2, 0, size/2, size/2, size/2);
            gradient.addColorStop(0, '#ffffff');
            gradient.addColorStop(0.2, '#00ffff');
            gradient.addColorStop(0.5, '#ff00ff');
            gradient.addColorStop(0.8, '#0000ff');
            gradient.addColorStop(1, '#000000');

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, size, size);

            // Swirl lines
            ctx.globalCompositeOperation = 'overlay';
            for (let i = 0; i < 100; i++) {
                ctx.beginPath();
                ctx.strokeStyle = `rgba(255, 255, 255, ${Math.random() * 0.3})`;
                ctx.lineWidth = Math.random() * 10 + 2;
                const radius = Math.random() * (size/2);
                const startAngle = Math.random() * Math.PI * 2;
                ctx.arc(size/2, size/2, radius, startAngle, startAngle + Math.PI * 2);
                ctx.stroke();
            }

            // Add some noise/grain
            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;
            for (let i = 0; i < data.length; i += 4) {
                const noise = (Math.random() - 0.5) * 30;
                data[i] += noise;
                data[i+1] += noise;
                data[i+2] += noise;
            }
            ctx.putImageData(imageData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // --- The Marble Object ---
        const marbleGroup = new THREE.Group();
        scene.add(marbleGroup);

        // 1. Inner Core (The Swirl)
        const coreGeometry = new THREE.SphereGeometry(0.85, 64, 64);
        const coreMaterial = new THREE.MeshStandardMaterial({
            map: swirlTexture,
            emissive: 0xffffff,
            emissiveMap: swirlTexture,
            emissiveIntensity: 0.8,
            roughness: 0.4,
            metalness: 0.1,
            side: THREE.BackSide // Render inside out if we were inside, but here it's just the core
        });
        const core = new THREE.Mesh(coreGeometry, coreMaterial);
        marbleGroup.add(core);

        // 2. Outer Glass Shell
        const glassGeometry = new THREE.SphereGeometry(1.0, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.0,
            roughness: 0.05,
            transmission: 0.98, // High transparency
            thickness: 1.5, // Refraction volume
            ior: 1.5, // Index of refraction for glass
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            transparent: true,
            opacity: 1.0,
            envMapIntensity: 1.5
        });
        const glass = new THREE.Mesh(glassGeometry, glassMaterial);
        marbleGroup.add(glass);

        // --- Lighting ---
        // Although environment map handles reflections, we need lights for the core emission and general illumination
        const ambientLight = new THREE.AmbientLight(0x404040, 1);
        scene.add(ambientLight);

        const keyLight = new THREE.DirectionalLight(0xffffff, 3);
        keyLight.position.set(5, 5, 5);
        scene.add(keyLight);

        const fillLight = new THREE.DirectionalLight(0x4455ff, 2);
        fillLight.position.set(-5, -2, 2);
        scene.add(fillLight);

        const rimLight = new THREE.PointLight(0xff0055, 5, 10);
        rimLight.position.set(0, 2, -3);
        scene.add(rimLight);

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate the core slightly differently than the glass for a dynamic effect
            core.rotation.y = time * 0.1;
            core.rotation.z = time * 0.05;

            // Slowly rotate the whole marble
            marbleGroup.rotation.y = time * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', onWindowResize, false);

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        animate();
    </script>
</body>
</html>
