  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1,
  clearcoat: 1,
  clearcoatRoughness: 0.05,
  side: THREE.DoubleSide,
  depthWrite: false,
});
const globe = new THREE.Mesh(globeGeo, globeMat);
globe.position.y = 1.5;
scene.add(globe);

// ── Globe rim ring ──
const rimGeo = new THREE.TorusGeometry(1.5, 0.02, 16, 64);
const rimMat = new THREE.MeshStandardMaterial({
  color: 0xcccccc, metalness: 0.9, roughness: 0.1
});
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.position.y = 1.5;
scene.add(rim);

// ── Base ──
const baseMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e, metalness: 0.6, roughness: 0.3
});

const baseBottom = new THREE.Mesh(
  new THREE.CylinderGeometry(1.1, 1.2, 0.25, 48),
  baseMat
);
baseBottom.position.y = 0.125;
scene.add(baseBottom);

const baseMid = new THREE.Mesh(
  new THREE.CylinderGeometry(0.95, 1.05, 0.35, 48),
  baseMat
);
baseMid.position.y = 0.425;
scene.add(baseMid);

const baseTop = new THREE.Mesh(
  new THREE.CylinderGeometry(0.85, 0.95, 0.15, 48),
  baseMat
);
baseTop.position.y = 0.725;
scene.add(baseTop);

// Decorative ring on base
const baseRing = new THREE.Mesh(
  new THREE.TorusGeometry(1.0, 0.03, 8, 48),
  new THREE.MeshStandardMaterial({ color: 0x444466, metalness: 0.8, roughness: 0.2 })
);
baseRing.rotation.x = Math.PI / 2;
baseRing.position.y = 0.6;
scene.add(baseRing);

// ── Snow Scene Inside ──
// Ground snow
const snowGround = new THREE.Mesh(
  new THREE.CircleGeometry(1.3, 48),
  new THREE.MeshStandardMaterial({ color: 0xeef2ff, roughness: 1, metalness: 0 })
);
snowGround.rotation.x = -Math.PI / 2;
snowGround.position.y = 0.75;
scene.add(snowGround);

// Trees
function makeTree(x, z, scale) {
  const group = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1a, roughness: 0.9 });
  const foliageMat = new THREE.MeshStandardMaterial({ color: 0x1a3a2a, roughness: 0.8 });

  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.02 * scale, 0.04 * scale, 0.2 * scale, 6), trunkMat);
  trunk.position.y = 0.1 * scale;
  group.add(trunk);

  for (let i = 0; i < 3; i++) {
    const r = (0.18 - i * 0.05) * scale;
    const h = 0.22 * scale;
    const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 6), foliageMat);
    cone.position.y = (0.2 + i * 0.14) * scale;
    group.add(cone);
  }
  group.position.set(x, 0.75, z);
  return group;
}

scene.add(makeTree(-0.4, -0.3, 1.2));
scene.add(makeTree(0.35, -0.5, 0.9));
scene.add(makeTree(0.1, 0.3, 1.0));
scene.add(makeTree(-0.6, 0.1, 0.7));

// ── Snow Particles ──
const snowCount = 400;
const snowGeo = new THREE.BufferGeometry();
const snowPositions = new Float32Array(snowCount * 3);
const snowSizes = new Float32Array(snowCount);
const snowSpeeds = [];

for (let i = 0; i < snowCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = Math.random() * 1.35;
  snowPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  snowPositions[i * 3 + 1] = r * Math.cos(phi) + 1.5;
  snowPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  snowSizes[i] = Math.random() * 3 + 1;
  snowSpeeds.push(Math.random() * 0.3 + 0.1);
}

snowGeo.setAttribute('position', new THREE.BufferAttribute(snowPositions, 3));
snowGeo.setAttribute('size', new THREE.BufferAttribute(snowSizes, 1));

// Custom shader for soft circular particles
const snowMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0xffffff) },
  },
  vertexShader: `
    attribute float size;
    uniform float uTime;
    varying float vAlpha;
    void main() {
      vec3 pos = position;
      pos.y = mod(pos.y - uTime * 0.15 + 2.0, 3.0) + 0.2;
      pos.x += sin(uTime * 0.5 + pos.z * 3.0) * 0.03;
      pos.z += cos(uTime * 0.4 + pos.x * 3.0) * 0.03;
      vec4 mvPos = modelViewMatrix * vec4(pos, 1.0);
      gl_PointSize = size * (200.0 / -mvPos.z);
      gl_Position = projectionMatrix * mvPos;
      vAlpha = smoothstep(3.0, 1.0, -mvPos.z) * 0.8;
    }
  `,
  fragmentShader: `
    uniform vec3 uColor;
    varying float vAlpha;
    void main() {
      float d = length(gl_PointCoord - 0.5);
      if (d > 0.5) discard;
      float alpha = smoothstep(0.5, 0.1, d) * vAlpha;
      gl_FragColor = vec4(uColor, alpha);
    }
  `,
  transparent: true,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});

const snowPoints = new THREE.Points(snowGeo, snowMat);
scene.add(snowPoints);

// ── Subtle env map for glass reflections ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x111122);
const envLight1 = new THREE.PointLight(0x6666ff, 10, 20);
envLight1.position.set(-3, 5, -3);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0xff8866, 5, 20);
envLight2.position.set(3, 2, 2);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
scene.environment = envRT.texture;

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ── Animate ──
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  snowMat.uniforms.uTime.value = t;

  // Gentle globe rotation
  globe.rotation.y = t * 0.05;
  rim.rotation.y = t * 0.05;

  // Warm glow flicker
  warmGlow.intensity = 2 + Math.sin(t * 2) * 0.3;

  controls.update();
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
```

**What you get:**

- **Glass sphere** using `MeshPhysicalMaterial` with `transmission` (95%), IOR 1.52, clearcoat — realistic glass refraction
- **Dark silhouette aesthetic** — deep navy background, rim-lit from behind with cool blue + warm fill lights
- **Tiered base** with metallic dark material and decorative ring
- **Mini snow scene inside** — four pine trees (cone stacks) on a white ground plane
- **400 snow particles** with a custom shader — soft circular points that drift downward with gentle sine wobble, additive blending for a glow effect
- **Environment map** baked from a simple light scene so the glass has something to reflect
- **OrbitControls** — drag to rotate, scroll to zoom
- **Gentle animation** — globe slowly rotates, snow falls continuously, warm interior light flickers

Just save as `index.html` and open in any modern browser.

