// ── Combine all ──
const telescopeAssembly = new THREE.Group();
telescopeAssembly.add(dewShieldGroup);
telescopeAssembly.add(tubeGroup);
telescopeAssembly.rotation.x = -0.15;
telescopeAssembly.rotation.z = 0.05;
scene.add(telescopeAssembly);

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3.0);
keyLight.position.set(5, 8, 3);
keyLight.castShadow = false;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 1.0);
