controls.enableDamping = true;
controls.dampingFactor = 0.05;

// ── Environment (gradient sphere for reflections) ──
const envCanvas = document.createElement('canvas');
envCanvas.width = 1024; envCanvas.height = 512;
const ctx = envCanvas.getContext('2d');
const grad = ctx.createLinearGradient(0, 0, 0, 512);
grad.addColorStop(0, '#1a0533');
grad.addColorStop(0.3, '#0d3b66');
grad.addColorStop(0.5, '#f0c27f');
grad.addColorStop(0.7, '#fc5c7d');
grad.addColorStop(1, '#6a3093');
ctx.fillStyle = grad;
ctx.fillRect(0, 0, 1024, 512);
// Add some bright spots for specular highlights
ctx.fillStyle = 'rgba(255,255,255,0.8)';
ctx.beginPath(); ctx.arc(200, 120, 30, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(700, 200, 20, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(500, 80, 15, 0, Math.PI * 2); ctx.fill();

const envTexture = new THREE.CanvasTexture(envCanvas);
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromEquirectangular(envTexture).texture;
scene.environment = envMap;

// ── Background ──
scene.background = new THREE.Color(0x111118);

// ── Swirl Marble Inner Sphere ──
const innerVert = `
varying vec3 vPos;
void main() {
  vPos = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const innerFrag = `
precision highp float;
varying vec3 vPos;
uniform float uTime;

// Simplex-like 3D noise
vec3 mod289(vec3 x){ return x - floor(x*(1.0/289.0))*289.0; }
vec4 mod289(vec4 x){ return x - floor(x*(1.0/289.0))*289.0; }
vec4 perm(vec4 x){ return mod289(((x*34.0)+1.0)*x); }

float noise(vec3 p){
  vec3 a = floor(p);
  vec3 d = p - a;
  d = d*d*(3.0-2.0*d);
  vec4 b = a.xxyy + vec4(0,1,0,1);
  vec4 k1 = perm(b.xyxy);
  vec4 k2 = perm(k1.xyxy + b.zzww);
  vec4 c = k2 + a.zzzz;
  vec4 k3 = perm(c);
  vec4 k4 = perm(c+1.0);
  vec4 o1 = fract(k3*(1.0/41.0));
  vec4 o2 = fract(k4*(1.0/41.0));
  vec4 o3 = o2*d.z + o1*(1.0-d.z);
  vec2 o4 = o3.yw*d.x + o3.xz*(1.0-d.x);
  return o4.y*d.y + o4.x*(1.0-d.y);
}

float fbm(vec3 p) {
  float v = 0.0, a = 0.5;
  vec3 shift = vec3(100.0);
  for(int i=0; i<6; i++) {
    v += a * noise(p);
    p = p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec3 p = vPos * 2.5;

  // Swirl distortion
  float angle = length(p.xz) * 3.0 + p.y * 2.0 + uTime * 0.3;
  float swirl = sin(angle) * 0.5 + 0.5;

  // Layered noise for marble veins
  vec3 q = p + vec3(swirl * 0.8, swirl * 0.4, swirl * 0.6);
  float n1 = fbm(q * 1.2);
  float n2 = fbm(q * 2.0 + 5.0);
  float n3 = fbm(q * 0.8 + vec3(uTime * 0.1));

  // Combine into swirl marble pattern
  float pattern = n1 * 0.5 + n2 * 0.3 + n3 * 0.2;
  pattern = mix(pattern, swirl, 0.3);

  // Color palette: deep purples, teals, warm golds, whites
  vec3 c1 = vec3(0.15, 0.02, 0.35); // deep purple
  vec3 c2 = vec3(0.05, 0.35, 0.45); // teal
  vec3 c3 = vec3(0.95, 0.75, 0.30); // gold
  vec3 c4 = vec3(0.90, 0.85, 0.95); // pearl white
  vec3 c5 = vec3(0.60, 0.10, 0.25); // magenta

  vec3 color = c1;
  color = mix(color, c2, smoothstep(0.25, 0.40, pattern));
  color = mix(color, c5, smoothstep(0.35, 0.50, pattern));
  color = mix(color, c3, smoothstep(0.48, 0.62, pattern));
  color = mix(color, c4, smoothstep(0.60, 0.78, pattern));

  // Sharpen veins
  float veins = smoothstep(0.42, 0.48, pattern) * smoothstep(0.55, 0.48, pattern);
  color = mix(color, c3 * 1.3, veins * 0.6);

  // Subtle glow on bright areas
  color += vec3(0.15, 0.10, 0.20) * smoothstep(0.7, 0.9, pattern);

  // Depth-based vignette
  float depth = 1.0 - dot(normalize(vPos), normalize(vPos));
  color *= 0.7 + 0.3 * (1.0 - depth * 2.0);

  gl_FragColor = vec4(color, 1.0);
}`;

