  innerMat.uniforms.uTime.value = t;

  // Gentle marble rotation
  innerSphere.rotation.y = t * 0.1;
  innerSphere.rotation.x = Math.sin(t * 0.07) * 0.15;

  // Glass shell stays still (realistic)
  glassSphere.rotation.y = 0;

  // Slow particle drift
  particles.rotation.y = t * 0.02;
  particles.rotation.x = t * 0.01;

  controls.update();
  renderer.render(scene, camera);
}
animate();
</script>
