fill.position.set(-5,3,-2);scene.add(fill);
const rim=new THREE.PointLight(0xffd080,1.5,20);
rim.position.set(-3,5,4);scene.add(rim);
const warm=new THREE.PointLight(0xffa040,0.8,15);
warm.position.set(2,-2,5);scene.add(warm);

/* ── Sextant parameters ── */
const ARC_RADIUS=4.5;
const ARC_START=-Math.PI*0.28;   // ~50° from top-left
const ARC_END=-Math.PI*0.72;     // ~130° from top-left
const FRAME_THICKNESS=0.12;
const FRAME_DEPTH=0.35;

/* ── Helper: position on arc ── */
function arcPos(angle){
  return new THREE.Vector3(ARC_RADIUS*Math.cos(angle),ARC_RADIUS*Math.sin(angle),0);
}

/* ── Main arc frame (torus segment) ── */
const arcAngle=Math.abs(ARC_END-ARC_START);
const frameGeo=new THREE.TorusGeometry(ARC_RADIUS,FRAME_THICKNESS,8,64,arcAngle);
const frame=new THREE.Mesh(frameGeo,brassMat);
frame.rotation.z=ARC_START+arcAngle/2+Math.PI/2;
frame.castShadow=true;
scene.add(frame);

/* ── Outer decorative rim ── */
const outerGeo=new THREE.TorusGeometry(ARC_RADIUS+0.22,0.04,6,64,arcAngle);
const outerRim=new THREE.Mesh(outerGeo,darkBrassMat);
outerRim.rotation.z=ARC_START+arcAngle/2+Math.PI/2;
scene.add(outerRim);

/* ── Inner decorative rim ── */
const innerGeo=new THREE.TorusGeometry(ARC_RADIUS-0.22,0.04,6,64,arcAngle);
const innerRim=new THREE.Mesh(innerGeo,darkBrassMat);
innerRim.rotation.z=ARC_START+arcAngle/2+Math.PI/2;
scene.add(innerRim);

/* ── Tick marks ── */
const tickGroup=new THREE.Group();
const tickCount=141; // 0° to 140°
const degStep=arcAngle/(tickCount-1);

for(let i=0;i<tickCount;i++){
  const deg=Math.round(i*(140/(tickCount-1)));
  const angle=ARC_START+degStep*i;
  const pos=arcPos(angle);
  const isMajor=deg%10===0;
  const isMed=deg%5===0&&!isMajor;
  const len=isMajor?0.45:isMed?0.30:0.15;
  const thick=isMajor?0.025:isMed?0.018:0.012;

  const tickGeo=new THREE.BoxGeometry(thick,len,FRAME_DEPTH+0.05);
  const tick=new THREE.Mesh(tickGeo,isMajor?brassMat:darkBrassMat);
  tick.position.copy(pos);
  tick.lookAt(0,0,0);
  tick.rotateX(Math.PI/2);
  tick.castShadow=true;
  tickGroup.add(tick);
}
scene.add(tickGroup);

/* ── Degree labels (canvas textures on planes) ── */
function makeLabel(text,angle){
  const c=document.createElement('canvas');
  c.width=128;c.height=64;
  const ctx=c.getContext('2d');
  ctx.fillStyle='transparent';ctx.fillRect(0,0,128,64);
  ctx.fillStyle='#c9a84c';
  ctx.font='bold 42px Georgia, serif';
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.shadowColor='rgba(0,0,0,0.7)';ctx.shadowBlur=4;
  ctx.fillText(text,64,32);

  const tex=new THREE.CanvasTexture(c);
  const mat=new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false});
  const sprite=new THREE.Sprite(mat);
  const pos=arcPos(angle);
  const r=ARC_RADIUS+0.65;
  sprite.position.set(r*Math.cos(angle),r*Math.sin(angle),0);
  sprite.scale.set(0.6,0.3,1);
  return sprite;
}

for(let deg=0;deg<=140;deg+=10){
  const angle=ARC_START+deg*(arcAngle/140);
  scene.add(makeLabel(deg+'°',angle));
}

/* ── Subdivision labels (every 5° small dots) ── */
for(let deg=5;deg<140;deg+=5){
  if(deg%10===0)continue;
  const angle=ARC_START+deg*(arcAngle/140);
  const pos=arcPos(angle);
  const dotGeo=new THREE.SphereGeometry(0.025,6,6);
  const dot=new THREE.Mesh(dotGeo,patinaMat);
  const r=ARC_RADIUS+0.35;
  dot.position.set(r*Math.cos(angle),r*Math.sin(angle),0);
  scene.add(dot);
}

/* ── Center pivot assembly ── */
const pivotGeo=new THREE.CylinderGeometry(0.3,0.3,0.5,24);
const pivot=new THREE.Mesh(pivotGeo,brassMat);
pivot.castShadow=true;
scene.add(pivot);

const pivotKnobGeo=new THREE.SphereGeometry(0.35,16,16);
const pivotKnob=new THREE.Mesh(pivotKnobGeo,brassMat);
pivotKnob.position.y=0.3;
scene.add(pivotKnob);

const pivotRingGeo=new THREE.TorusGeometry(0.45,0.06,8,24);
const pivotRing=new THREE.Mesh(pivotRingGeo,darkBrassMat);
pivotRing.rotation.x=Math.PI/2;
pivotRing.position.y=0.05;
scene.add(pivotRing);

/* ── Index arm (pointer) ── */
const armAngle=ARC_START+45*(arcAngle/140); // pointing at ~45°
const armLen=ARC_RADIUS-0.3;
const armGeo=new THREE.BoxGeometry(0.06,armLen,0.15);
const arm=new THREE.Mesh(armGeo,brassMat);
const armTip=arcPos(armAngle).normalize().multiplyScalar(armLen/2);
arm.position.copy(armTip);
arm.lookAt(0,0,0);
arm.rotateX(Math.PI/2);
arm.rotateZ(Math.PI);
arm.castShadow=true;
scene.add(arm);

/* ── Arm tip triangle ── */
const tipGeo=new THREE.ConeGeometry(0.08,0.2,4);
const tip=new THREE.Mesh(tipGeo,brassMat);
const tipPos=arcPos(armAngle).normalize().multiplyScalar(armLen);
tip.position.copy(tipPos);
tip.lookAt(0,0,0);
tip.rotateX(Math.PI/2);
scene.add(tip);

/* ── Decorative side arms (simplified sextant body) ── */
function makeSideArm(side){
  const s=side; // -1 or 1
  const shape=new THREE.Shape();
  shape.moveTo(0,0);
  shape.lineTo(s*2.5,-1.5);
  shape.lineTo(s*2.5,-2.0);
  shape.lineTo(s*1.5,-3.0);
  shape.lineTo(s*1.2,-3.0);
  shape.lineTo(s*2.0,-1.8);
  shape.lineTo(s*1.0,-0.5);
  shape.closePath();

  const extSettings={depth:FRAME_DEPTH*0.6,bevelEnabled:true,bevelThickness:0.03,bevelSize:0.03,bevelSegments:2};
  const geo=new THREE.ExtrudeGeometry(shape,extSettings);
  geo.center();
  const mesh=new THREE.Mesh(geo,darkBrassMat);
  mesh.rotation.z=ARC_START+arcAngle*0.15;
  mesh.position.set(s*0.3,-1.5,0);
  mesh.castShadow=true;
  return mesh;
}

scene.add(makeSideArm(1));
scene.add(makeSideArm(-1));

/* ── Engraved decorative band on frame ── */
const bandGeo=new THREE.TorusGeometry(ARC_RADIUS,0.02,4,64,arcAngle*0.6);
const band=new THREE.Mesh(bandGeo,patinaMat);
band.rotation.z=ARC_START+arcAngle*0.2+Math.PI/2;
scene.add(band);

/* ── Small ornamental screws ── */
const screwGeo=new THREE.CylinderGeometry(0.06,0.06,0.08,8);
const screwHeadGeo=new THREE.SphereGeometry(0.07,8,8);
for(let i=0;i<3;i++){
  const angle=ARC_START+arcAngle*(0.15+i*0.35);
  const pos=arcPos(angle);
  const r=ARC_RADIUS+0.18;
  const screw=new THREE.Mesh(screwGeo,darkBrassMat);
  screw.position.set(r*Math.cos(angle),r*Math.sin(angle),0);
  screw.lookAt(0,0,0);
  screw.rotateX(Math.PI/2);
  scene.add(screw);

  const head=new THREE.Mesh(screwHeadGeo,darkBrassMat);
  head.position.copy(screw.position);
  head.position.z+=0.05;
  scene.add(head);
}

/* ── Animation ── */
const clock=new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const t=clock.getElapsedTime();
  // Subtle arm sway
  const swayAngle=ARC_START+(45+Math.sin(t*0.5)*15)*(arcAngle/140);
  const sLen=ARC_RADIUS-0.3;
  const sTip=arcPos(swayAngle).normalize().multiplyScalar(sLen/2);
  arm.position.copy(sTip);
  arm.lookAt(0,0,0);
  arm.rotateX(Math.PI/2);
  arm.rotateZ(Math.PI);

  const sTipPos=arcPos(swayAngle).normalize().multiplyScalar(sLen);
  tip.position.copy(sTipPos);
  tip.lookAt(0,0,0);
  tip.rotateX(Math.PI/2);

  // Rim light pulse
  rim.intensity=1.5+Math.sin(t*1.2)*0.3;

  controls.update();
  renderer.render(scene,camera);
}
animate();

/* ── Resize ── */
addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});
</script>
</body>
</html>
