<!-- Vertex Shader -->
<script id="vertexShader" type="x-shader/x-vertex">
  varying vec3 vNormal;
  varying vec3 vWorldPosition;
  varying vec3 vViewDir;
  varying vec3 vWorldNormal;

  void main() {
    vNormal = normalize(normalMatrix * normal);
    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    vWorldPosition = worldPos.xyz;
    vWorldNormal = normalize(mat3(modelMatrix) * normal);
    vViewDir = normalize(cameraPosition - worldPos.xyz);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
</script>

<!-- Fragment Shader -->
<script id="fragmentShader" type="x-shader/x-fragment">
  uniform float uTime;
  uniform vec3 uLightPos1;
  uniform vec3 uLightPos2;
  uniform vec3 uLightPos3;
  uniform vec3 uCameraPos;
  uniform sampler2D uEnvMap;

  varying vec3 vNormal;
  varying vec3 vWorldPosition;
  varying vec3 vViewDir;
  varying vec3 vWorldNormal;

  // --- Simplex 3D Noise ---
  vec4 permute(vec4 x) { return mod(((x * 34.0) + 1.0) * x, 289.0); }
  vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

  float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);

    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);

    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);

    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;

    i = mod(i, 289.0);
    vec4 p = permute(permute(permute(
      i.z + vec4(0.0, i1.z, i2.z, 1.0))
      + i.y + vec4(0.0, i1.y, i2.y, 1.0))
      + i.x + vec4(0.0, i1.x, i2.x, 1.0));

    float n_ = 1.0/7.0;
    vec3 ns = n_ * D.wyz - D.xzx;

    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);

    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);

    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);

    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));

    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;

    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);

    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;

    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
  }

  // --- FBM Noise ---
  float fbm(vec3 p, int octaves) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for (int i = 0; i < 8; i++) {
      if (i >= octaves) break;
      val += amp * snoise(p * freq);
      freq *= 2.0;
      amp *= 0.5;
    }
    return val;
  }

  // --- Curl Noise for swirls ---
  vec3 curlNoise(vec3 p) {
    float eps = 0.01;
    float dx = snoise(p + vec3(eps, 0.0, 0.0)) - snoise(p - vec3(eps, 0.0, 0.0));
    float dy = snoise(p + vec3(0.0, eps, 0.0)) - snoise(p - vec3(0.0, eps, 0.0));
    float dz = snoise(p + vec3(0.0, 0.0, eps)) - snoise(p - vec3(0.0, 0.0, eps));
    return vec3(dy - dz, dz - dx, dx - dy) / (2.0 * eps);
  }

  // --- Iris Color Palette ---
  vec3 irisPalette(float t) {
    // Deep greens, ambers, golds, hazel, dark brown
    vec3 a = vec3(0.30, 0.30, 0.30);
    vec3 b = vec3(0.45, 0.45, 0.50);
    vec3 c = vec3(1.00, 1.00, 1.00);
    vec3 d = vec3(0.26, 0.26, 0.26);
    return a + b * cos(6.28318 * (c * t + d));
  }

  vec3 irisPalette2(float t) {
    // Emerald, gold, amber, deep green
    vec3 a = vec3(0.50, 0.50, 0.50);
    vec3 b = vec3(0.50, 0.50, 0.50);
    vec3 c = vec3(1.00, 0.70, 0.40);
    vec3 d = vec3(0.00, 0.15, 0.20);
    return a + b * cos(6.28318 * (c * t + d));
  }

  void main() {
    vec3 N = normalize(vWorldNormal);
    vec3 V = normalize(vViewDir);
    vec3 I = reflect(-V, N);

    // --- Glass Fresnel ---
    float fresnel = pow(1.0 - max(dot(N, V), 0.0), 4.0);
    fresnel = mix(0.04, 1.0, fresnel);

    // --- Refraction ---
    float ior = 1.52; // glass
    vec3 R = refract(-V, N, 1.0 / ior);

    // --- Internal swirl iris pattern ---
    vec3 p = vWorldPosition * 2.5;
    float t = uTime * 0.05;

    // Curl noise for organic swirls
    vec3 curl1 = curlNoise(p * 0.8 + t);
    vec3 curl2 = curlNoise(p * 1.5 - t * 0.7 + 10.0);
    vec3 curl3 = curlNoise(p * 3.0 + t * 0.3 + 20.0);

    // Layered swirl pattern
    float swirl1 = fbm(p * 0.6 + curl1 * 0.3, 5);
    float swirl2 = fbm(p * 1.2 + curl2 * 0.2, 4);
    float swirl3 = fbm(p * 2.0 + curl3 * 0.15, 3);

    // Combine swirls into iris pattern
    float irisPattern = swirl1 * 0.5 + swirl2 * 0.3 + swirl3 * 0.2;
    irisPattern = irisPattern * 0.5 + 0.5; // normalize to 0-1

    // Radial modulation for iris ring structure
    float r = length(p.xy);
    float ring = sin(r * 4.0 + swirl1 * 2.0) * 0.5 + 0.5;
    irisPattern = irisPattern * 0.7 + ring * 0.3;

    // Iris colors
    vec3 irisColor = irisPalette(irisPattern * 0.6 + swirl2 * 0.2);
    irisColor = mix(irisColor, irisPalette2(swirl3 * 0.5 + 0.2), 0.3);

    // Dark pupil region
    float pupil = smoothstep(0.15, 0.05, 1.0 - length(p.xy) * 1.5);
    irisColor = mix(irisColor, vec3(0.02), pupil * 0.8);

    // Brighter edge ring
    float edgeRing = smoothstep(0.4, 0.35, length(p.xy)) * smoothstep(0.1, 0.15, 1.0 - length(p.xy));
    irisColor += vec3(0.15, 0.2, 0.1) * edgeRing;

    // --- Refracted internal color ---
    vec3 refractedColor = irisColor * 0.9;

    // Add some internal refraction depth effect
    float depth = dot(R, N);
    refractedColor *= 0.6 + 0.4 * max(depth, 0.0);

    // --- Environment reflection (procedural gradient) ---
    vec3 envDir = reflect(-V, N);
    float envGrad = envDir.y * 0.5 + 0.5;
    vec3 envColor = mix(
      vec3(0.05, 0.08, 0.15),
      vec3(0.15, 0.25, 0.45),
      envGrad
    );
    envColor += vec3(0.3, 0.5, 0.8) * pow(max(envDir.y, 0.0), 3.0) * 0.5;

    // --- Specular highlights ---
    vec3 L1 = normalize(uLightPos1 - vWorldPosition);
    vec3 L2 = normalize(uLightPos2 - vWorldPosition);
    vec3 L3 = normalize(uLightPos3 - vWorldPosition);
    vec3 H1 = normalize(L1 + V);
    vec3 H2 = normalize(L2 + V);
    vec3 H3 = normalize(L3 + V);

    float spec1 = pow(max(dot(N, H1), 0.0), 120.0) * 1.5;
    float spec2 = pow(max(dot(N, H2), 0.0), 80.0) * 0.8;
    float spec3 = pow(max(dot(N, H3), 0.0), 60.0) * 0.4;
    float specular = spec1 + spec2 + spec3;

    // --- Diffuse lighting on internal pattern ---
    float diff1 = max(dot(N, L1), 0.0) * 0.3;
    float diff2 = max(dot(N, L2), 0.0) * 0.15;
    float diff3 = max(dot(N, L3), 0.0) * 0.1;

    // --- Combine ---
    vec3 glassColor = mix(refractedColor, envColor, fresnel);
    glassColor += specular * vec3(1.0, 0.98, 0.95);
    glassColor += (diff1 + diff2 + diff3) * refractedColor * 0.2;

    // Subtle edge glow (subsurface-like)
    float edgeGlow = pow(1.0 - max(dot(N, V), 0.0), 8.0);
    glassColor += edgeGlow * vec3(0.1, 0.15, 0.1) * 0.3;

    // Tone mapping
    glassColor = glassColor / (glassColor + vec3(1.0));
    glassColor = pow(glassColor, vec3(1.0 / 2.2));

    gl_FragColor = vec4(glassColor, 1.0);
  }
</script>

