            side: THREE.DoubleSide
        });
        const glassSphere = new THREE.Mesh(glassGeometry, glassMaterial);
        globeGroup.add(glassSphere);

        // 2. The Base
        const baseGeometry = new THREE.CylinderGeometry(1.8, 1.6, 0.8, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.2, 
            metalness: 0.8 
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = -1.6;
        globeGroup.add(base);

        // Gold Rim
        const rimGeometry = new THREE.TorusGeometry(1.7, 0.05, 16, 100);
        const rimMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffd700, 
            roughness: 0.3, 
            metalness: 1.0 
        });
        const rim = new THREE.Mesh(rimGeometry, rimMaterial);
        rim.rotation.x = Math.PI / 2;
        rim.position.y = -1.2;
        globeGroup.add(rim);

        // 3. The Snow Cluster (Particles)
        const snowCount = 1500;
        const snowGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(snowCount * 3);
        const velocities = []; // Store velocity for animation

        for (let i = 0; i < snowCount; i++) {
            // Random position inside sphere
            const r = 1.8 * Math.cbrt(Math.random()); // Uniform distribution in sphere
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta) - 0.5; // Shift down slightly
            const z = r * Math.cos(phi);

            positions[i * 3] = x;
            positions[i * 3 + 1] = y;
            positions[i * 3 + 2] = z;

            velocities.push({
                x: (Math.random() - 0.5) * 0.01,
                y: (Math.random() - 0.5) * 0.01,
                z: (Math.random() - 0.5) * 0.01,
                originalY: y
            });
        }

        snowGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        const snowMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.08,
            transparent: true,
            opacity: 0.8,
            sizeAttenuation: true
        });

        const snowSystem = new THREE.Points(snowGeometry, snowMaterial);
        globeGroup.add(snowSystem);

        // 4. A small tree inside (optional but nice for context)
        const treeGroup = new THREE.Group();
        const trunkGeo = new THREE.CylinderGeometry(0.05, 0.08, 0.4, 8);
        const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3c31 });
        const trunk = new THREE.Mesh(trunkGeo, trunkMat);
        trunk.position.y = -1.0;
        treeGroup.add(trunk);

        const leavesGeo = new THREE.ConeGeometry(0.4, 1.2, 8);
        const leavesMat = new THREE.MeshStandardMaterial({ color: 0x2d5a27 });
        const leaves = new THREE.Mesh(leavesGeo, leavesMat);
        leaves.position.y = -0.4;
        treeGroup.add(leaves);

        globeGroup.add(treeGroup);

        // Animation State
        let isShaking = false;
        let shakeIntensity = 0;
        let time = 0;

        // Interaction
        window.addEventListener('click', () => {
            isShaking = true;
            shakeIntensity = 0.5;

            // Reset snow positions to top to simulate shaking up
            const pos = snowSystem.geometry.attributes.position.array;
            for(let i=0; i<snowCount; i++) {
                // Push them up and scatter
                pos[i*3 + 1] = (Math.random() * 1.5) + 0.5; 
                pos[i*3] += (Math.random() - 0.5) * 0.5;
                pos[i*3 + 2] += (Math.random() - 0.5) * 0.5;
            }
            snowSystem.geometry.attributes.position.needsUpdate = true;
        });

        // Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            time += 0.01;

            // Gentle rotation of the whole globe
            globeGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Shake effect
            if (isShaking) {
                shakeIntensity *= 0.95; // Decay
                if (shakeIntensity < 0.01) isShaking = false;

                globeGroup.position.x = (Math.random() - 0.5) * shakeIntensity;
                globeGroup.position.z = (Math.random() - 0.5) * shakeIntensity;
            } else {
                globeGroup.position.x = 0;
                globeGroup.position.z = 0;
            }

            // Snow Animation
            const positions = snowSystem.geometry.attributes.position.array;
            for (let i = 0; i < snowCount; i++) {
                const idx = i * 3;

                // Gravity
                positions[idx + 1] -= 0.005 + (shakeIntensity * 0.05);

                // Drift
                positions[idx] += Math.sin(time + i) * 0.002;
                positions[idx + 2] += Math.cos(time + i) * 0.002;

                // Floor collision (inside the globe)
                // Simple approximation: if y is too low, reset or bounce
                // The base is at y = -1.6. The sphere radius is 2.
                // Let's say snow settles around y = -1.2
                if (positions[idx + 1] < -1.2) {
                    positions[idx + 1] = -1.2 + Math.random() * 0.1;
                    // Settle horizontally
                    positions[idx] *= 0.95;
                    positions[idx + 2] *= 0.95;
                }

                // Keep inside sphere roughly
                const dist = Math.sqrt(positions[idx]**2 + positions[idx+1]**2 + positions[idx+2]**2);
                if (dist > 1.8) {
                    const scale = 1.8 / dist;
                    positions[idx] *= scale;
                    positions[idx+1] *= scale;
                    positions[idx+2] *= scale;
                }
            }
            snowSystem.geometry.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
