```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Brass Compass Card Edge</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #1a1a1a; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);
scene.fog = new THREE.FogExp2(0x1a1a1a, 0.06);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0.5, 3.5);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 1.5;
controls.maxDistance = 8;
controls.update();

// --- Brass material ---
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xc9a84c,
  metalness: 0.95,
  roughness: 0.22,
  clearcoat: 0.3,
  clearcoatRoughness: 0.15,
  reflectivity: 0.9,
});

const darkBrassMat = new THREE.MeshPhysicalMaterial({
  color: 0x8a6d2b,
  metalness: 0.9,
  roughness: 0.35,
  clearcoat: 0.2,
});

const inlayMat = new THREE.MeshStandardMaterial({
  color: 0x1a1510,
  metalness: 0.3,
  roughness: 0.6,
});

// --- Compass card edge: main ring ---
const ringGeo = new THREE.TorusGeometry(1.2, 0.08, 32, 128);
const ring = new THREE.Mesh(ringGeo, brassMat);
ring.rotation.x = Math.PI / 2;
scene.add(ring);

// --- Outer and inner bevel rings ---
const bevelGeo = new THREE.TorusGeometry(1.28, 0.02, 16, 128);
const bevelOuter = new THREE.Mesh(bevelGeo, darkBrassMat);
bevelOuter.rotation.x = Math.PI / 2;
scene.add(bevelOuter);

const bevelGeo2 = new THREE.TorusGeometry(1.12, 0.02, 16, 128);
const bevelInner = new THREE.Mesh(bevelGeo2, darkBrassMat);
bevelInner.rotation.x = Math.PI / 2;
scene.add(bevelInner);

// --- Tick marks ---
const tickGeoMajor = new THREE.BoxGeometry(0.015, 0.04, 0.008);
const tickGeoMinor = new THREE.BoxGeometry(0.01, 0.025, 0.005);
const tickGeoMid = new THREE.BoxGeometry(0.01, 0.032, 0.005);

for (let i = 0; i < 360; i += 1) {
  const angle = (i * Math.PI) / 180;
  let tick;
  if (i % 5 === 0) {
    tick = new THREE.Mesh(tickGeoMajor, inlayMat);
  } else if (i % 2 === 0) {
    tick = new THREE.Mesh(tickGeoMid, inlayMat);
  } else {
    tick = new THREE.Mesh(tickGeoMinor, inlayMat);
  }
  tick.position.set(Math.cos(angle) * 1.2, 0, Math.sin(angle) * 1.2);
  tick.rotation.y = -angle;
  scene.add(tick);
}

// --- Cardinal direction markers ---
function createLabel(text, angle) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#1a1510';
  ctx.fillRect(0, 0, 128, 128);
  ctx.fillStyle = '#c9a84c';
  ctx.font = 'bold 72px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 64, 64);

  const tex = new THREE.CanvasTexture(canvas);
  const mat = new THREE.MeshStandardMaterial({
    map: tex,
    transparent: true,
    metalness: 0.5,
    roughness: 0.4,
    alphaMap: tex,
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.18, 0.18), mat);
  plane.position.set(Math.cos(angle) * 1.2, 0, Math.sin(angle) * 1.2);
  plane.rotation.y = -angle + Math.PI / 2;
  scene.add(plane);
}

createLabel('N', 0);
createLabel('S', Math.PI);
createLabel('E', Math.PI / 2);
createLabel('W', -Math.PI / 2);

// --- Inner decorative ring with engraved pattern ---
const innerRingGeo = new THREE.TorusGeometry(0.75, 0.015, 8, 64);
const innerRing = new THREE.Mesh(innerRingGeo, darkBrassMat);
innerRing.rotation.x = Math.PI / 2;
scene.add(innerRing);

// --- Small degree numbers every 30 degrees ---
for (let deg = 0; deg < 360; deg += 30) {
  if (deg % 90 === 0) continue;
  const angle = (deg * Math.PI) / 180;
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#1a1510';
  ctx.fillRect(0, 0, 64, 64);
  ctx.fillStyle = '#c9a84c';
  ctx.font = 'bold 36px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(deg), 32, 32);

  const tex = new THREE.CanvasTexture(canvas);
  const mat = new THREE.MeshStandardMaterial({
    map: tex,
    transparent: true,
    metalness: 0.5,
    roughness: 0.4,
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.1, 0.1), mat);
  plane.position.set(Math.cos(angle) * 0.95, 0, Math.sin(angle) * 0.95);
  plane.rotation.y = -angle + Math.PI / 2;
  scene.add(plane);
}

// --- Center pivot ---
const pivotGeo = new THREE.CylinderGeometry(0.06, 0.08, 0.06, 32);
const pivot = new THREE.Mesh(pivotGeo, brassMat);
scene.add(pivot);

const pivotTopGeo = new THREE.SphereGeometry(0.05, 16, 16);
const pivotTop = new THREE.Mesh(pivotTopGeo, brassMat);
pivotTop.position.y = 0.04;
scene.add(pivotTop);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const dirLight1 = new THREE.DirectionalLight(0xfff4e0, 2.5);
dirLight1.position.set(3, 4, 2);
scene.add(dirLight1);

const dirLight2 = new THREE.DirectionalLight(0xc0d8ff, 1.0);
dirLight2.position.set(-3, 2, -2);
scene.add(dirLight2);

const pointLight = new THREE.PointLight(0xffcc88, 1.5, 10);
pointLight.position.set(0, 2, 1);
scene.add(pointLight);

const rimLight = new THREE.PointLight(0x8899cc, 0.8, 10);
rimLight.position.set(-2, 1, -3);
scene.add(rimLight);

// --- Subtle rotation ---
let time = 0;
function animate() {
  requestAnimationFrame(animate);
  time += 0.003;
  ring.rotation.z = time;
  bevelOuter.rotation.z = time;
  bevelInner.rotation.z = time;
  innerRing.rotation.z = time;

  // Update children that are tick marks and labels to rotate too
  scene.children.forEach(child => {
    if (child !== ring && child !== bevelOuter && child !== bevelInner
        && child !== innerRing && child !== pivot && child !== pivotTop
        && !child.isLight && child.position.y === 0
        && (Math.abs(child.position.x) > 0.1 || Math.abs(child.position.z) > 0.1)) {
      const angle = Math.atan2(child.position.z, child.position.x);
      const radius = Math.sqrt(child.position.x ** 2 + child.position.z ** 2);
      const newAngle = angle + time;
      child.position.x = Math.cos(newAngle) * radius;
      child.position.z = Math.sin(newAngle) * radius;
      child.rotation.y = -newAngle + (child.geometry?.type === 'PlaneGeometry' ? Math.PI / 2 : 0);
    }
  });

  controls.update();
  renderer.render(scene, camera);
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
