            transmission: 0.98, // High transmission for glass
            opacity: 1,
            metalness: 0,
            roughness: 0.05, // Very smooth
            ior: 1.5, // Index of refraction for glass
            thickness: 2.0, // Volume thickness
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            envMapIntensity: 1.5,
            transparent: true,
            side: THREE.DoubleSide
        });

