// ── Environment map (procedural) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x2a2040);
const envLight1 = new THREE.PointLight(0xffe8c0, 3, 20);
envLight1.position.set(4, 6, 3);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0xc0d0ff, 2, 20);
envLight2.position.set(-5, 4, -3);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
scene.environment = envRT.texture;

// ── Brass material ──
const brass = new THREE.MeshStandardMaterial({
  color: 0xc9a030,
  metalness: 0.92,
  roughness: 0.28,
  envMapIntensity: 1.2,
});

const brassDark = new THREE.MeshStandardMaterial({
  color: 0x8a6e20,
  metalness: 0.9,
