armMesh.receiveShadow = true;
armGroup.add(armMesh);

// ── Pivot hub (at origin) ──
const hubGeo = new THREE.CylinderGeometry(0.14, 0.14, 0.08, 32);
hubGeo.rotateZ(Math.PI / 2);
