knobGeo.scale(1, 1, 0.6);
const knob = new THREE.Mesh(knobGeo, brass);
knob.position.set(-0.15, 0, 0.06);
knob.castShadow = true;
armGroup.add(knob);

// ── Index mirror assembly (at arm tip) ──
const mirrorGroup = new THREE.Group();
mirrorGroup.position.set(armLen - 0.02, 0, 0);
armGroup.add(mirrorGroup);

// Mirror frame
const frameShape = roundedRect(0.28, 0.32, 0.015);
const frameGeo = new THREE.ExtrudeGeometry(frameShape, {
  depth: 0.025, bevelEnabled: true, bevelThickness: 0.004,
  bevelSize: 0.004, bevelSegments: 2,
});
frameGeo.translate(0, 0, -0.0125);
const frame = new THREE.Mesh(frameGeo, brass);
frame.castShadow = true;
mirrorGroup.add(frame);

// Mirror glass
const glassGeo = new THREE.PlaneGeometry(0.22, 0.26);
const glass = new THREE.Mesh(glassGeo, mirrorMat);
glass.position.z = 0.026;
mirrorGroup.add(glass);

// Mirror backing (dark side)
const backGeo = new THREE.PlaneGeometry(0.22, 0.26);
