// ── Vernier scale along arm edge ──
const vernierShape = roundedRect(0.9, 0.04, 0.005);
const vernierGeo = new THREE.ExtrudeGeometry(vernierShape, {
  depth: 0.008, bevelEnabled: true, bevelThickness: 0.002, bevelSize: 0.002, bevelSegments: 1,
});
vernierGeo.translate(0, 0, -0.004);
const vernier = new THREE.Mesh(vernierGeo, brassDark);
vernier.position.set(armLen * 0.45, -armW1 / 2 - 0.015, 0);
