// ── Decorative brass screws ──
function makeScrew(x, y, z) {
  const g = new THREE.CylinderGeometry(0.012, 0.012, 0.015, 12);
  g.rotateZ(Math.PI / 2);
  const m = new THREE.Mesh(g, brassDark);
  m.position.set(x, y, z);
  return m;
}
armGroup.add(makeScrew(armLen - 0.06, 0.12, 0.03));
armGroup.add(makeScrew(armLen - 0.06, -0.12, 0.03));
armGroup.add(makeScrew(0.3, 0.065, 0.03));
armGroup.add(makeScrew(0.3, -0.065, 0.03));

// ── Arc (partial, for context) ──
const arcCurve = new THREE.EllipseCurve(0, 0, 2.8, 2.8, -Math.PI * 0.35, Math.PI * 0.35, false, 0);
const arcPoints = arcCurve.getPoints(64);
const arcShape = new THREE.Shape();
arcShape.moveTo(arcPoints[0].x, arcPoints[0].y);
for (let i = 1; i < arcPoints.length; i++) arcShape.lineTo(arcPoints[i].x, arcPoints[i].y);
