const arcGeo = new THREE.ExtrudeGeometry(arcShape, {
  depth: 0.06, bevelEnabled: true, bevelThickness: 0.006,
  bevelSize: 0.006, bevelSegments: 2,
});
arcGeo.translate(0, 0, -0.03);
const arc = new THREE.Mesh(arcGeo, brass);
