  const r = 2.8;
  const tickLen = deg % 10 === 0 ? 0.08 : 0.04;
  const tickGeo = new THREE.BoxGeometry(0.008, tickLen, 0.015);
  const tick = new THREE.Mesh(tickGeo, brassDark);
  const cx = r * Math.cos(rad), cy = r * Math.sin(rad);
  tick.position.set(cx, cy, 0);
  tick.rotation.z = -rad;
  scene.add(tick);
}

// ── Position and tilt the whole arm ──
armGroup.rotation.x = -0.15;
armGroup.rotation.z = -0.4;

// ── Ground plane (subtle) ──
const groundGeo = new THREE.PlaneGeometry(20, 20);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2e, metalness: 0, roughness: 0.9 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
ground.receiveShadow = true;
scene.add(ground);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating oscillation
  armGroup.position.y = Math.sin(t * 0.5) * 0.05;
  armGroup.rotation.z = -0.4 + Math.sin(t * 0.3) * 0.08;

  controls.update();
  renderer.render(scene, camera);
}
