        // Generate Swirl Texture
        function createSwirlTexture() {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Fill background
            ctx.fillStyle = '#1a1a2e';
            ctx.fillRect(0, 0, size, size);

            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;

            for (let y = 0; y < size; y++) {
                for (let x = 0; x < size; x++) {
                    const u = (x / size) * 2 - 1;
                    const v = (y / size) * 2 - 1;

                    const angle = Math.atan2(v, u);
                    const radius = Math.sqrt(u * u + v * v);

                    // Swirl math
                    const swirl = Math.sin(angle * 8 + radius * 15) * 0.5 + 0.5;
                    const noise = Math.sin(x * 0.1) * Math.cos(y * 0.1) * 0.2;

                    const value = swirl + noise;

                    // Marble colors: Deep Blue, Cyan, White, Gold
                    const r = Math.floor(20 + value * 50 + (value > 0.8 ? 100 : 0));
                    const g = Math.floor(20 + value * 80);
                    const b = Math.floor(60 + value * 150);

                    const index = (y * size + x) * 4;
                    data[index] = r;
                    data[index + 1] = g;
                    data[index + 2] = b;
                    data[index + 3] = 255;
                }
            }

            ctx.putImageData(imageData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            return texture;
        }

