        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Environment for Glass Refraction
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const envMap = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
        scene.environment = envMap;

        // --- Generate Swirl/Fracture Texture ---
        function createSwirlFractureTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background (Dark glass interior)
            ctx.fillStyle = '#050505';
            ctx.fillRect(0, 0, size, size);

            // Helper to draw a line with some thickness and glow
            function drawLine(x1, y1, x2, y2, color, width) {
                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.strokeStyle = color;
                ctx.lineWidth = width;
                ctx.lineCap = 'round';
                ctx.stroke();
            }

            // Draw Swirls
            ctx.translate(size/2, size/2);

            // Multiple spiral arms
            for (let arm = 0; arm < 5; arm++) {
                ctx.rotate((Math.PI * 2 * arm) / 5);
                ctx.beginPath();
                for (let i = 0; i < 200; i++) {
                    const angle = i * 0.1;
                    const radius = i * 1.5;
                    const x = Math.cos(angle) * radius;
                    const y = Math.sin(angle) * radius;
                    if (i === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.strokeStyle = `rgba(200, 220, 255, ${0.1 + Math.random() * 0.2})`;
                ctx.lineWidth = 2 + Math.random() * 5;
                ctx.stroke();
            }

            // Draw Fractures (Jagged lines)
            ctx.rotate(Math.random() * Math.PI);
            for (let i = 0; i < 15; i++) {
                let cx = (Math.random() - 0.5) * size * 0.8;
                let cy = (Math.random() - 0.5) * size * 0.8;

                ctx.beginPath();
                ctx.moveTo(cx, cy);

                let segments = 10 + Math.random() * 20;
                for (let j = 0; j < segments; j++) {
                    cx += (Math.random() - 0.5) * 50;
                    cy += (Math.random() - 0.5) * 50;
                    ctx.lineTo(cx, cy);
                }

                ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + Math.random() * 0.5})`;
                ctx.lineWidth = 1 + Math.random() * 3;
                ctx.stroke();
            }

            // Add some noise/grain
            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;
            for (let i = 0; i < data.length; i += 4) {
                const noise = (Math.random() - 0.5) * 30;
                data[i] += noise;
                data[i+1] += noise;
                data[i+2] += noise;
            }
            ctx.putImageData(imageData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            texture.colorSpace = THREE.SRGBColorSpace;
            return texture;
        }

        const swirlTexture = createSwirlFractureTexture();

        // --- The Marble Object ---

        // Group to hold the marble parts
        const marbleGroup = new THREE.Group();
        scene.add(marbleGroup);

        // 1. Inner Core (The Swirl/Fracture pattern)
        // This sits inside the glass to be refracted
        const innerGeometry = new THREE.SphereGeometry(1.4, 64, 64);
        const innerMaterial = new THREE.MeshStandardMaterial({
