  const mat = new THREE.MeshBasicMaterial({
    map: tex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.3 * scale, 0.3 * scale), mat);
  const r = 0.82;
  mesh.position.set(Math.sin(angle) * r, 0.11, Math.cos(angle) * r);
  mesh.rotation.y = -angle;
  return mesh;
