            metalness: 0,
            roughness: 0,
            transmission: 1, // Glass-like transparency
            thickness: 1.5, // Refraction thickness
            ior: 1.5, // Index of refraction
            envMap: cubeRenderTarget.texture,
            envMapIntensity: 1,
            clearcoat: 1,
            clearcoatRoughness: 0,
            transparent: true,
            opacity: 1
        });
        const glassSphere = new THREE.Mesh(glassGeometry, glassMaterial);
        marbleGroup.add(glassSphere);

        // 2. The Swirl Filament (Inner Core)
        // Creating a spiral path
        class SpiralCurve extends THREE.Curve {
            constructor(scale = 1) {
                super();
                this.scale = scale;
            }
            getPoint(t) {
                const angle = t * Math.PI * 8; // 4 full twists
                const radius = 0.8 * (1 - t * 0.5); // Tapering radius
                const x = Math.cos(angle) * radius;
                const y = (t - 0.5) * 2.5; // Vertical span
                const z = Math.sin(angle) * radius;
                return new THREE.Vector3(x, y, z).multiplyScalar(this.scale);
            }
        }

