    <div id="canvas-container"></div>

    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const container = document.getElementById('canvas-container');
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        container.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xd4af37, 0.5, 20);
        pointLight.position.set(-5, 2, -5);
        scene.add(pointLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642, // Brass color
            metalness: 0.9,
            roughness: 0.2,
            envMapIntensity: 1.0
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            metalness: 0.8,
            roughness: 0.4
        });

        // Sundial Group
        const sundialGroup = new THREE.Group();
        scene.add(sundialGroup);

        // 1. The Latitude Arc (The main requested object)
        // A torus segment representing the adjustable latitude arc
        const arcRadius = 4;
        const arcTube = 0.15;
        const arcAngle = Math.PI; // Semi-circle
        const latitudeArc = new THREE.Mesh(
            new THREE.TorusGeometry(arcRadius, arcTube, 16, 50, arcAngle),
            brassMaterial
        );
        latitudeArc.rotation.x = Math.PI / 2; // Lay flat initially
        latitudeArc.rotation.z = Math.PI / 2; // Orient as an arc
        latitudeArc.castShadow = true;
        latitudeArc.receiveShadow = true;
        sundialGroup.add(latitudeArc);

        // 2. The Equatorial Ring (The dial face)
        const ringRadius = 3.5;
        const ringTube = 0.05;
        const equatorialRing = new THREE.Mesh(
            new THREE.TorusGeometry(ringRadius, ringTube, 16, 100),
            brassMaterial
        );
        equatorialRing.castShadow = true;
        sundialGroup.add(equatorialRing);

        // 3. Hour Markers (Simple lines on the ring)
        const hourGroup = new THREE.Group();
        for(let i=0; i<24; i++) {
            const angle = (i / 24) * Math.PI * 2;
            const isMainHour = i % 3 === 0;
            const length = isMainHour ? 0.3 : 0.15;

            const markerGeo = new THREE.BoxGeometry(0.05, length, 0.05);
            const marker = new THREE.Mesh(markerGeo, brassMaterial);

            marker.position.x = Math.cos(angle) * ringRadius;
            marker.position.z = Math.sin(angle) * ringRadius;
            marker.rotation.y = -angle;

            hourGroup.add(marker);
        }
        sundialGroup.add(hourGroup);

        // 4. The Gnomon (Shadow caster) - A simple rod
        const gnomonGeo = new THREE.CylinderGeometry(0.05, 0.05, ringRadius * 2, 8);
        const gnomon = new THREE.Mesh(gnomonGeo, darkMetalMaterial);
        gnomon.rotation.z = Math.PI / 2;
        sundialGroup.add(gnomon);

        // 5. Base/Stand
        const baseGeo = new THREE.CylinderGeometry(0.5, 0.8, 1, 32);
        const base = new THREE.Mesh(baseGeo, brassMaterial);
        base.position.y = -arcRadius - 0.5;
        base.castShadow = true;
        sundialGroup.add(base);

        // Initial Rotation to look nice
        sundialGroup.rotation.x = 0.2;
        sundialGroup.rotation.y = -0.2;

        // UI Logic
        const latSlider = document.getElementById('lat-slider');
        const latVal = document.getElementById('lat-val');
        const timeSlider = document.getElementById('time-slider');
        const timeVal = document.getElementById('time-val');

        latSlider.addEventListener('input', (e) => {
            const lat = parseFloat(e.target.value);
            latVal.textContent = lat;
            // Tilt the equatorial ring based on latitude (90 - lat)
            // In a universal equinoctial sundial, the ring is tilted to the co-latitude
            const tilt = (90 - lat) * (Math.PI / 180);
            equatorialRing.rotation.x = tilt;
            hourGroup.rotation.x = tilt;
            gnomon.rotation.x = tilt; // Gnomon stays perpendicular to ring
        });

        timeSlider.addEventListener('input', (e) => {
            const time = parseFloat(e.target.value);
            const hours = Math.floor(time);
            const minutes = Math.round((time - hours) * 60);
            timeVal.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;

            // Rotate the ring to simulate time passing (Earth rotation)
            // 360 degrees in 24 hours
            const rotation = (time / 24) * Math.PI * 2;
            equatorialRing.rotation.y = rotation;
            hourGroup.rotation.y = rotation;
        });

        // Trigger initial values
        latSlider.dispatchEvent(new Event('input'));
        timeSlider.dispatchEvent(new Event('input'));

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle floating animation
            sundialGroup.position.y = Math.sin(Date.now() * 0.001) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
