        // Procedural Texture for the Swirl Vein
        function createSwirlTexture() {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Fill background
            ctx.fillStyle = '#e0e0e0';
            ctx.fillRect(0, 0, size, size);

            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;

            for (let y = 0; y < size; y++) {
                for (let x = 0; x < size; x++) {
                    const u = x / size;
                    const v = y / size;

                    // Polar coordinates
                    const dx = u - 0.5;
                    const dy = v - 0.5;
                    const r = Math.sqrt(dx*dx + dy*dy) * 2;
                    const theta = Math.atan2(dy, dx);

                    // Swirl noise
                    const swirl = Math.sin(r * 10 - theta * 5) * 0.5 + 0.5;
                    const noise = Math.sin(r * 20 + theta * 10) * 0.2;

                    // Vein color (dark grey/black)
                    const veinIntensity = Math.max(0, swirl - 0.4 + noise);

                    const index = (y * size + x) * 4;

                    // Mix white marble with dark vein
                    const marbleBase = 0.8 + Math.random() * 0.1; // Slight noise
                    const veinColor = 0.1;

                    const mix = Math.min(1, veinIntensity * 2); // Sharpen the vein

                    data[index] = (marbleBase * (1-mix) + veinColor * mix) * 255;     // R
                    data[index + 1] = (marbleBase * (1-mix) + veinColor * mix) * 255; // G
                    data[index + 2] = (marbleBase * (1-mix) + veinColor * mix) * 255; // B
                    data[index + 3] = 255; // Alpha
                }
            }

            ctx.putImageData(imageData, 0, 0);
            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

