}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.012);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 200);
camera.position.set(6, 8, 10);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Controls ───────────────────────────────────────────
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2.1;

// ── Materials ──────────────────────────────────────────
const brass = new THREE.MeshStandardMaterial({
  color: 0xb5a642,
  metalness: 0.92,
  roughness: 0.28,
  envMapIntensity: 1.5,
});

const darkBrass = new THREE.MeshStandardMaterial({
  color: 0x8a7a30,
  metalness: 0.9,
  roughness: 0.35,
});

const stone = new THREE.MeshStandardMaterial({
  color: 0x3a3a4a,
  metalness: 0.05,
  roughness: 0.85,
});

// ── Env map (procedural) ──────────────────────────────
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x87ceeb);
const envLight1 = new THREE.DirectionalLight(0xffffff, 3);
envLight1.position.set(5, 10, 5);
envScene.add(envLight1);
const envLight2 = new THREE.DirectionalLight(0xffe0b0, 2);
envLight2.position.set(-5, 3, -5);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
scene.environment = envRT.texture;

// ── Ground ─────────────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(80, 80),
  new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.95 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// ── Sundial Group ──────────────────────────────────────
const sundial = new THREE.Group();
scene.add(sundial);

// ── Base / Pedestal ────────────────────────────────────
const pedestalGeo = new THREE.CylinderGeometry(1.8, 2.2, 0.3, 64);
const pedestal = new THREE.Mesh(pedestalGeo, stone);
pedestal.position.y = 0.15;
pedestal.castShadow = true;
pedestal.receiveShadow = true;
sundial.add(pedestal);

// ── Dial Plate ─────────────────────────────────────────
const dialGeo = new THREE.CylinderGeometry(1.7, 1.7, 0.06, 64);
const dial = new THREE.Mesh(dialGeo, brass);
dial.position.y = 0.33;
dial.castShadow = true;
dial.receiveShadow = true;
sundial.add(dial);

// ── Hour Markers ───────────────────────────────────────
const hourAngles = [];
for (let i = 1; i <= 12; i++) {
  hourAngles.push((i / 12) * Math.PI * 2 - Math.PI / 2);
}

const markerGeo = new THREE.BoxGeometry(0.035, 0.04, 0.12);
const smallMarkerGeo = new THREE.BoxGeometry(0.02, 0.04, 0.06);

for (let i = 0; i < 12; i++) {
  const angle = hourAngles[i];
  const isQuarter = i % 3 === 0;
  const geo = isQuarter ? markerGeo : smallMarkerGeo;
  const marker = new THREE.Mesh(geo, darkBrass);

  const r = 1.55;
  marker.position.set(
    Math.cos(angle) * r,
    0.37,
    Math.sin(angle) * r
  );
  marker.rotation.y = -angle + Math.PI / 2;
  marker.castShadow = true;
  sundial.add(marker);

  // Hour numbers (tiny torus rings as decorative dots)
  if (isQuarter) {
    const dotGeo = new THREE.TorusGeometry(0.04, 0.012, 8, 16);
    const dot = new THREE.Mesh(dotGeo, darkBrass);
    dot.position.set(
      Math.cos(angle) * (r + 0.12),
      0.37,
      Math.sin(angle) * (r + 0.12)
    );
    dot.rotation.x = -Math.PI / 2;
    sundial.add(dot);
  }
}

// ── Inner decorative ring ──────────────────────────────
const ringGeo = new THREE.TorusGeometry(1.2, 0.015, 8, 64);
const ring = new THREE.Mesh(ringGeo, darkBrass);
ring.position.y = 0.37;
ring.rotation.x = -Math.PI / 2;
sundial.add(ring);

const ring2Geo = new THREE.TorusGeometry(0.6, 0.012, 8, 64);
const ring2 = new THREE.Mesh(ring2Geo, darkBrass);
ring2.position.y = 0.37;
ring2.rotation.x = -Math.PI / 2;
sundial.add(ring2);

// ── Gnomon (the sundial line) ──────────────────────────
const GNOMON_ANGLE = 0.41; // ~23.5° in radians
const GNOMON_LENGTH = 2.2;

const gnomonGroup = new THREE.Group();
gnomonGroup.position.y = 0.36;
sundial.add(gnomonGroup);

// Main gnomon rod — a thin elongated box (the "line")
const gnomonGeo = new THREE.BoxGeometry(0.04, 0.04, GNOMON_LENGTH);
const gnomon = new THREE.Mesh(gnomonGeo, brass);
gnomon.position.z = GNOMON_LENGTH / 2 * Math.cos(GNOMON_ANGLE);
gnomon.position.y = GNOMON_LENGTH / 2 * Math.sin(GNOMON_ANGLE);
gnomon.rotation.x = -GNOMON_ANGLE;
gnomon.castShadow = true;
gnomonGroup.add(gnomon);

// Triangular gnomon plate (traditional sundial style)
const plateShape = new THREE.Shape();
plateShape.moveTo(0, 0);
plateShape.lineTo(0.35, 0);
plateShape.lineTo(0.35, GNOMON_LENGTH * Math.sin(GNOMON_ANGLE));
plateShape.closePath();

const plateExtrudeSettings = { depth: 0.008, bevelEnabled: true, bevelThickness: 0.002, bevelSize: 0.002 };
const plateGeo = new THREE.ExtrudeGeometry(plateShape, plateExtrudeSettings);
const plate = new THREE.Mesh(plateGeo, brass);
plate.position.set(-0.18, 0, 0);
plate.rotation.x = -GNOMON_ANGLE;
plate.castShadow = true;
gnomonGroup.add(plate);

// Mirror plate on other side
const plate2 = new THREE.Mesh(plateGeo, brass);
plate2.position.set(0.18, 0, 0);
plate2.rotation.x = -GNOMON_ANGLE;
plate2.rotation.y = Math.PI;
plate2.castShadow = true;
gnomonGroup.add(plate2);

// Pivot sphere
const pivotGeo = new THREE.SphereGeometry(0.06, 16, 16);
const pivot = new THREE.Mesh(pivotGeo, darkBrass);
pivot.castShadow = true;
gnomonGroup.add(pivot);

// ── Cardinal direction markers (N, S, E, W) ────────────
const cardinalGeo = new THREE.SphereGeometry(0.05, 8, 8);
const cardinals = [
  { label: 'N', angle: -Math.PI / 2 },
  { label: 'E', angle: 0 },
  { label: 'S', angle: Math.PI / 2 },
  { label: 'W', angle: Math.PI },
];

cardinals.forEach(({ angle }) => {
  const dot = new THREE.Mesh(cardinalGeo, darkBrass);
  const r = 1.65;
  dot.position.set(Math.cos(angle) * r, 0.37, Math.sin(angle) * r);
  sundial.add(dot);
});

// ── Lighting ───────────────────────────────────────────
const sunLight = new THREE.DirectionalLight(0xfff4e0, 3.5);
sunLight.position.set(8, 12, 4);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 0.5;
sunLight.shadow.camera.far = 50;
sunLight.shadow.camera.left = -8;
sunLight.shadow.camera.right = 8;
sunLight.shadow.camera.top = 8;
sunLight.shadow.camera.bottom = -8;
sunLight.shadow.bias = -0.001;
scene.add(sunLight);

const ambientLight = new THREE.AmbientLight(0x404060, 0.6);
scene.add(ambientLight);

const fillLight = new THREE.DirectionalLight(0x8888cc, 0.4);
fillLight.position.set(-5, 3, -5);
scene.add(fillLight);

// ── Shadow line indicator (animated shadow cast by sun) ─
const shadowLineGeo = new THREE.PlaneGeometry(0.02, 3);
const shadowLineMat = new THREE.MeshBasicMaterial({
  color: 0x000000,
  transparent: true,
  opacity: 0.35,
  depthWrite: false,
});
const shadowLine = new THREE.Mesh(shadowLineGeo, shadowLineMat);
shadowLine.rotation.x = -Math.PI / 2;
shadowLine.rotation.z = Math.PI / 2;
shadowLine.position.y = 0.365;
sundial.add(shadowLine);

// ── Animation ──────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Slowly rotate sun to simulate time passing
  const sunAngle = (t * 0.1) % (Math.PI * 2);
  sunLight.position.set(
    Math.cos(sunAngle) * 10,
    10 + Math.sin(sunAngle * 0.5) * 3,
    Math.sin(sunAngle) * 10
  );

  // Update shadow line direction based on sun position
  const shadowDir = new THREE.Vector3(-sunLight.position.x, 0, -sunLight.position.z).normalize();
  shadowLine.rotation.z = Math.atan2(shadowDir.x, shadowDir.z);
  shadowLine.position.x = shadowDir.x * 1.1;
  shadowLine.position.z = shadowDir.z * 1.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ─────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
