        const frameGeoBottom = new THREE.BoxGeometry(width, frameThickness, depth);
        const frameGeoLeft = new THREE.BoxGeometry(frameThickness, height, depth);
        const frameGeoRight = new THREE.BoxGeometry(frameThickness, height, depth);

        const topBar = new THREE.Mesh(frameGeoTop, brassMaterial);
        topBar.position.y = height / 2;
        mirrorGroup.add(topBar);

        const bottomBar = new THREE.Mesh(frameGeoBottom, brassMaterial);
        bottomBar.position.y = -height / 2;
        mirrorGroup.add(bottomBar);

        const leftBar = new THREE.Mesh(frameGeoLeft, brassMaterial);
        leftBar.position.x = -width / 2;
        mirrorGroup.add(leftBar);

        const rightBar = new THREE.Mesh(frameGeoRight, brassMaterial);
        rightBar.position.x = width / 2;
        mirrorGroup.add(rightBar);

        // Horizon Glass (Half Silvered, Half Clear)
