        silverPart.position.x = -halfWidth / 2 - frameThickness / 2;
        silverPart.position.z = 0.01; // Slightly in front
        mirrorGroup.add(silverPart);

        // Right half: Clear Glass
        const glassPart = new THREE.Mesh(mirrorGeo, glassMaterial);
        glassPart.position.x = halfWidth / 2 + frameThickness / 2;
        glassPart.position.z = 0.01;
        mirrorGroup.add(glassPart);

