        // Rotate the whole group slightly for better viewing angle
        mirrorGroup.rotation.y = -0.2;
        mirrorGroup.rotation.x = 0.1;

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

