<body>
    <div id="info">click & drag to orbit - scroll to zoom</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        // Environment for Glass Refraction
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const envMap = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
        scene.environment = envMap;

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // --- Swirl Texture Generation ---
        function createSwirlTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, size, size);

            // Swirl
            const cx = size / 2;
            const cy = size / 2;

            for (let i = 0; i < 200; i++) {
                ctx.beginPath();
                const angle = i * 0.1;
                const radius = i * 2.5;
                const x = cx + Math.cos(angle) * radius;
                const y = cy + Math.sin(angle) * radius;

                ctx.moveTo(cx, cy);
                ctx.quadraticCurveTo(cx + Math.cos(angle + 1) * radius * 1.5, cy + Math.sin(angle + 1) * radius * 1.5, x, y);

                ctx.strokeStyle = `rgba(${50 + Math.random()*50}, ${150 + Math.random()*100}, ${200 + Math.random()*55}, ${0.1 + Math.random()*0.2})`;
                ctx.lineWidth = 5 + Math.random() * 15;
                ctx.stroke();
            }

            // Add some noise/grain
            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;
            for (let i = 0; i < data.length; i += 4) {
                const noise = (Math.random() - 0.5) * 20;
                data[i] += noise;
                data[i+1] += noise;
                data[i+2] += noise;
            }
            ctx.putImageData(imageData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // --- Marble Geometry & Material ---
        const geometry = new THREE.SphereGeometry(2, 64, 64);

        const material = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 2.0,     // Volume for refraction
            ior: 1.5,           // Index of refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            map: swirlTexture,  // The swirl pattern
            side: THREE.DoubleSide
        });

        const marble = new THREE.Mesh(geometry, material);
        scene.add(marble);

        // --- Fracture Line ---
        // Create a jagged line on the surface of the sphere
        const fracturePoints = [];
        const segments = 50;
        const radius = 2.005; // Slightly outside to avoid z-fighting

        // Start point
        let currentPos = new THREE.Vector3(0, 1.5, 1.5).normalize().multiplyScalar(radius);
        fracturePoints.push(currentPos);

        for (let i = 0; i < segments; i++) {
            // Random direction on tangent plane
            const tangent = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5);
            tangent.sub(currentPos.clone().normalize().multiplyScalar(tangent.dot(currentPos.normalize()))).normalize();

            // Move along tangent
            const step = 0.15;
            const nextPos = currentPos.clone().add(tangent.multiplyScalar(step));

            // Project back to sphere surface
            nextPos.normalize().multiplyScalar(radius);

            // Add some jaggedness perpendicular to movement
            const normal = nextPos.clone().normalize();
            const binormal = new THREE.Vector3().crossVectors(tangent, normal).normalize();
            const jaggedness = (Math.random() - 0.5) * 0.1;
            nextPos.add(binormal.multiplyScalar(jaggedness));
            nextPos.normalize().multiplyScalar(radius);

            fracturePoints.push(nextPos);
            currentPos = nextPos;
        }

        const fractureGeometry = new THREE.BufferGeometry().setFromPoints(fracturePoints);
        const fractureMaterial = new THREE.LineBasicMaterial({ 
            color: 0x000000, 
            linewidth: 2, // Note: linewidth > 1 only works in some browsers/WebGL implementations
            transparent: true,
            opacity: 0.8
        });
        const fractureLine = new THREE.Line(fractureGeometry, fractureMaterial);
        scene.add(fractureLine);

        // Add a second, thinner white line for highlight on the crack
        const fractureHighlightMat = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
        const fractureHighlight = new THREE.Line(fractureGeometry, fractureHighlightMat);
        fractureHighlight.scale.set(0.99, 0.99, 0.99); // Slightly inside
        scene.add(fractureHighlight);


        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            // Slow rotation
            marble.rotation.y += 0.002;
            fractureLine.rotation.y += 0.002;
            fractureHighlight.rotation.y += 0.002;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
