<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a12);
scene.fog = new THREE.FogExp2(0x0a0a12, 0.08);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0.5, 0);

// ── Lighting ──
const ambient = new THREE.AmbientLight(0x404060, 0.5);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffeedd, 2);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);

const rimLight = new THREE.DirectionalLight(0x8888ff, 1.5);
rimLight.position.set(-4, 2, -3);
scene.add(rimLight);

const bottomLight = new THREE.PointLight(0xffffff, 1, 8);
bottomLight.position.set(0, -1, 0);
scene.add(bottomLight);

// ── Glass Globe ──
const globeRadius = 2;
const glassGeo = new THREE.SphereGeometry(globeRadius, 64, 64);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.95,
  opacity: 1,
  transparent: true,
  metalness: 0,
  roughness: 0.05,
  ior: 1.5,
  thickness: 0.1,
  specularIntensity: 1,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1,
  clearcoat: 1,
  clearcoatRoughness: 0.05,
  side: THREE.DoubleSide,
  depthWrite: false,
});

// Simple env map for reflections
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x1a1a2e);
const envLight1 = new THREE.PointLight(0xffeedd, 10, 20);
envLight1.position.set(3, 4, 3);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0x8888ff, 8, 20);
envLight2.position.set(-3, 1, -2);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
glassMat.envMap = envRT.texture;

const globe = new THREE.Mesh(glassGeo, glassMat);
globe.position.y = globeRadius;
scene.add(globe);

// ── Snow Layer ──
function simpleNoise(x, y) {
  const n = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
  return n - Math.floor(n);
}

const snowGeo = new THREE.SphereGeometry(globeRadius - 0.02, 80, 24, 0, Math.PI * 2, Math.PI * 0.55, Math.PI * 0.15);
const pos = snowGeo.attributes.position;

for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i);
  const y = pos.getY(i);
  const z = pos.getZ(i);

  // More displacement near the bottom, tapering toward the edge
  const heightFactor = Math.max(0, (y + globeRadius) / (globeRadius * 0.4));
  const noise1 = simpleNoise(x * 3, z * 3) * 0.15;
  const noise2 = simpleNoise(x * 7 + 100, z * 7 + 100) * 0.06;
  const noise3 = simpleNoise(x * 15 + 200, z * 15 + 200) * 0.02;
  const displacement = (noise1 + noise2 + noise3) * heightFactor;

  const len = Math.sqrt(x * x + y * y + z * z);
  const scale = (len + displacement) / len;
  pos.setXYZ(i, x * scale, y * scale, z * scale);
}

snowGeo.computeVertexNormals();

const snowMat = new THREE.MeshPhysicalMaterial({
  color: 0xf0f0ff,
  roughness: 0.8,
  metalness: 0,
  clearcoat: 0.1,
  sheen: 1,
  sheenRoughness: 0.5,
  sheenColor: new THREE.Color(0xccddff),
});

const snow = new THREE.Mesh(snowGeo, snowMat);
snow.position.y = globeRadius;
scene.add(snow);

// ── Base / Pedestal ──
const baseGeo = new THREE.CylinderGeometry(1.6, 1.7, 0.3, 48);
const baseMat = new THREE.MeshPhysicalMaterial({
  color: 0x1a1a2e,
  roughness: 0.3,
  metalness: 0.8,
  clearcoat: 0.5,
});
const base = new THREE.Mesh(baseGeo, baseMat);
base.position.y = 0.15;
scene.add(base);

const baseRingGeo = new THREE.TorusGeometry(1.65, 0.04, 16, 48);
const baseRingMat = new THREE.MeshPhysicalMaterial({
  color: 0x334466,
  roughness: 0.2,
  metalness: 0.9,
});
const baseRing = new THREE.Mesh(baseRingGeo, baseRingMat);
baseRing.rotation.x = Math.PI / 2;
baseRing.position.y = 0.3;
scene.add(baseRing);

// ── Floating Snow Particles ──
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI;
  const r = globeRadius * (0.3 + Math.random() * 0.6);
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.cos(phi) + globeRadius;
  positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  sizes[i] = Math.random() * 3 + 1;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.04,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
  depthWrite: false,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle snow drift
  const pArr = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    pArr[i * 3 + 1] -= 0.002 + Math.sin(t + i) * 0.001;
    pArr[i * 3] += Math.sin(t * 0.5 + i * 0.1) * 0.0005;

    // Reset particles that fall below the snow layer
    if (pArr[i * 3 + 1] < globeRadius - 0.5) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * Math.PI * 0.5;
      const r = globeRadius * (0.3 + Math.random() * 0.5);
      pArr[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      pArr[i * 3 + 1] = r * Math.cos(phi) + globeRadius * 0.8;
      pArr[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
    }
  }
  particles.geometry.attributes.position.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
