        const pointerGeometry = new THREE.CylinderGeometry(0.05, 0.4, 1.2, 3); 
        const pointer = new THREE.Mesh(pointerGeometry, brassMaterial);
        pointer.position.y = 0.6; // Lift it up from the base
        pointer.rotation.x = Math.PI / 2; // Lay it flat initially
        pointer.rotation.z = Math.PI / 4; // Angle it up
        pointer.castShadow = true;
        pointer.receiveShadow = true;
        sundialGroup.add(pointer);

        // Add some hour markers (simple lines)
        const markerGeometry = new THREE.BoxGeometry(0.05, 0.05, 0.2);
        for (let i = 0; i < 12; i++) {
            const angle = (i / 12) * Math.PI * 2;
            const marker = new THREE.Mesh(markerGeometry, brassMaterial);
            marker.position.x = Math.sin(angle) * 1.3;
            marker.position.z = Math.cos(angle) * 1.3;
            marker.position.y = 0.05;
            marker.rotation.y = -angle;
            marker.castShadow = true;
            sundialGroup.add(marker);
        }

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Slowly rotate the sundial to show it off
            sundialGroup.rotation.y += 0.005;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
