<body>
    <div id="info">Brass Sextant Limb — drag to orbit, scroll to zoom</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 5, 5);
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffaa00, 0.5);
        backLight.position.set(-5, -5, -5);
        scene.add(backLight);

        // Brass Material
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642, // Brass color
            metalness: 0.8,
            roughness: 0.3,
        });

        const darkBrassMaterial = new THREE.MeshStandardMaterial({
            color: 0x8c7e35,
            metalness: 0.8,
            roughness: 0.4,
        });

        // Sextant Limb Group
        const limbGroup = new THREE.Group();
        scene.add(limbGroup);

        // Main Arc (The Limb)
        // Radius 2, Tube 0.15, Arc 60 degrees (PI/3)
        const radius = 2.5;
        const tubeRadius = 0.12;
        const arcAngle = Math.PI / 3; // 60 degrees

        const limbGeometry = new THREE.TorusGeometry(radius, tubeRadius, 16, 64, arcAngle);
        const limbMesh = new THREE.Mesh(limbGeometry, brassMaterial);
        // Rotate to start from bottom left roughly
        limbMesh.rotation.z = Math.PI / 2 + arcAngle / 2; 
        limbGroup.add(limbMesh);

        // Ticks
        const tickCount = 60; // 1 degree per tick
        const tickLength = 0.15;
        const majorTickLength = 0.25;

        for (let i = 0; i <= tickCount; i++) {
            const angle = (i / tickCount) * arcAngle;
            const isMajor = i % 10 === 0;
            const isMid = i % 5 === 0;

            let len = tickLength;
            if (isMajor) len = majorTickLength;
            else if (isMid) len = tickLength * 1.5;

            const tickGeo = new THREE.BoxGeometry(0.02, len, 0.05);
            const tick = new THREE.Mesh(tickGeo, darkBrassMaterial);

            // Position tick on the outer edge of the arc
            // The torus is centered at 0,0. We need to offset by radius + tubeRadius
            const r = radius + tubeRadius + 0.01; 

            // Calculate position based on the rotation of the limb mesh
            // The limb mesh is rotated. Let's calculate local coordinates relative to the arc start.
            // The torus geometry creates an arc from 0 to arcAngle.
            // We need to rotate the tick to match the tangent of the arc at that point.

            // Actually, simpler approach: Place ticks in world space relative to the arc center
            // The arc goes from angle 0 to arcAngle in local space of the torus.
            // But the torus is rotated.

            // Let's place ticks manually using trigonometry relative to the limb's center
            // The limb is rotated by (PI/2 + arcAngle/2).
            // Let's define the arc from -30 deg to +30 deg relative to the limb group center for symmetry?
            // No, let's stick to the torus geometry logic.

            // TorusGeometry creates an arc from 0 to arcAngle.
            // We need to rotate the tick to face outward.
            // The angle of the tick on the torus is 'angle'.
            // The position on the torus surface is (r * cos(angle), r * sin(angle)).
            // But the torus is rotated.

            // Let's just create a curve and use getPointAt(t)
        }

        // Better approach for ticks: Use a curve
        const curve = new THREE.EllipseCurve(
            0, 0,            // ax, aY
            radius, radius,  // xRadius, yRadius
            0, arcAngle,     // aStartAngle, aEndAngle
            false,           // aClockwise
            0                // aRotation
        );

        const points = curve.getPoints(tickCount);

        // We need to rotate the whole tick system to match the limb mesh
        // The limb mesh was rotated by PI/2 + arcAngle/2.
        // The curve is drawn from 0 to arcAngle.
        // So we rotate the points by the same amount.

        const tickGroup = new THREE.Group();
        limbGroup.add(tickGroup);
        tickGroup.rotation.z = Math.PI / 2 + arcAngle / 2;

        for (let i = 0; i <= tickCount; i++) {
            const t = i / tickCount;
            const point = curve.getPoint(t);

            const isMajor = i % 10 === 0;
            const isMid = i % 5 === 0;

            let len = tickLength;
            if (isMajor) len = majorTickLength;
            else if (isMid) len = tickLength * 1.5;

            const tickGeo = new THREE.BoxGeometry(0.02, len, 0.05);
            const tick = new THREE.Mesh(tickGeo, darkBrassMaterial);

            // Position at the edge of the limb
            // The point is on the center line of the arc (radius).
            // We want the tick to start at radius + tubeRadius and go outwards.
            // So we offset the position by tubeRadius in the radial direction.
            const angle = t * arcAngle;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);

            // Offset position
            tick.position.x = point.x + cos * tubeRadius;
            tick.position.y = point.y + sin * tubeRadius;

            // Rotate tick to face outward
            tick.rotation.z = angle;

            tickGroup.add(tick);
        }

        // Add a simple frame/bracket to make it look more like a sextant part
        const frameGeo = new THREE.BoxGeometry(0.1, 1.5, 0.1);
        const frame = new THREE.Mesh(frameGeo, brassMaterial);
        // Position at the start of the arc (angle 0 in local curve space)
        // Curve starts at (radius, 0).
        // Rotated by PI/2 + arcAngle/2.
        // Let's just place it visually.
        // The arc is roughly from bottom-left to top-left in the rotated view?
        // Let's just add a center pivot block.

        const pivotGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.2, 32);
        const pivot = new THREE.Mesh(pivotGeo, brassMaterial);
        pivot.rotation.x = Math.PI / 2;
        limbGroup.add(pivot);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
