            metalness: 0.8, 
            roughness: 0.2 
        });
        const baseMesh = new THREE.Mesh(baseGeo, baseMat);
        baseMesh.position.y = -2.2;
        globeGroup.add(baseMesh);

        // 3. Snow Particles
        const snowCount = 400;
        const snowGeo = new THREE.BufferGeometry();
        const snowPos = new Float32Array(snowCount * 3);
        const snowVel = []; // Store velocity for animation

        for(let i=0; i<snowCount; i++) {
            // Random position inside sphere
            const r = globeRadius * Math.cbrt(Math.random()) * 0.9; // Keep inside
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta);
            const z = r * Math.cos(phi);

            snowPos[i*3] = x;
            snowPos[i*3+1] = y;
            snowPos[i*3+2] = z;

            snowVel.push({
                x: (Math.random() - 0.5) * 0.01,
                y: -Math.random() * 0.02 - 0.005, // Falling down
                z: (Math.random() - 0.5) * 0.01
            });
        }

        snowGeo.setAttribute('position', new THREE.BufferAttribute(snowPos, 3));
        const snowMat = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.05,
            transparent: true,
            opacity: 0.8
        });
        const snowSystem = new THREE.Points(snowGeo, snowMat);
        globeGroup.add(snowSystem);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const delta = clock.getDelta();

            // Rotate the whole globe slightly
            globeGroup.rotation.y = time * 0.1;

            // Animate Snow
            const positions = snowSystem.geometry.attributes.position.array;
            for(let i=0; i<snowCount; i++) {
                let x = positions[i*3];
                let y = positions[i*3+1];
                let z = positions[i*3+2];

                // Apply velocity
                x += snowVel[i].x;
                y += snowVel[i].y;
                z += snowVel[i].z;

                // Reset if below base
                if (y < -1.5) {
                    y = 1.5;
                    x = (Math.random() - 0.5) * 3;
                    z = (Math.random() - 0.5) * 3;
                }

                // Keep inside sphere roughly
                const dist = Math.sqrt(x*x + y*y + z*z);
                if (dist > globeRadius * 0.9) {
                    const scale = (globeRadius * 0.9) / dist;
                    x *= scale;
                    y *= scale;
                    z *= scale;
                }

                positions[i*3] = x;
                positions[i*3+1] = y;
                positions[i*3+2] = z;
            }
            snowSystem.geometry.attributes.position.needsUpdate = true;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

