function createSwirlTexture(size) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  const imageData = ctx.createImageData(size, size);
  const data = imageData.data;

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = x / size * 2 - 1;
      const v = y / size * 2 - 1;
      const r = Math.sqrt(u * u + v * v);
      const theta = Math.atan2(v, u);

      // Swirl function
      const swirl = theta + r * 6.0;
      const swirl2 = theta - r * 4.0 + 1.5;

      // Layered noise-like patterns
      let val = 0;
      val += Math.sin(swirl * 3.0) * 0.5;
      val += Math.sin(swirl2 * 2.5 + r * 8.0) * 0.3;
      val += Math.sin(swirl * 5.0 + theta * 2.0) * 0.15;
      val += Math.cos(r * 12.0 + swirl * 2.0) * 0.1;

      val = (val + 1.0) * 0.5;

      // Color mapping - vibrant jewel tones
      const hue = (val * 0.3 + r * 0.2) % 1.0;
      const sat = 0.6 + val * 0.4;
      const light = 0.3 + val * 0.5;

      // HSL to RGB
      const s = sat, l = light;
      const c = (1 - Math.abs(2 * l - 1)) * s;
      const x2 = c * (1 - Math.abs((hue * 6) % 2 - 1));
      const m = l - c / 2;
      let r2, g2, b2;
      const h = hue * 6;
      if (h < 1) { r2=c; g2=x2; b2=0; }
      else if (h < 2) { r2=x2; g2=c; b2=0; }
      else if (h < 3) { r2=0; g2=c; b2=x2; }
      else if (h < 4) { r2=0; g2=x2; b2=c; }
      else if (h < 5) { r2=x2; g2=0; b2=c; }
      else { r2=c; g2=0; b2=x2; }

      const idx = (y * size + x) * 4;
      data[idx]     = Math.floor(((r2 + m) * 255));
      data[idx + 1] = Math.floor(((g2 + m) * 255));
      data[idx + 2] = Math.floor(((b2 + m) * 255));
      data[idx + 3] = 255;
    }
  }

  ctx.putImageData(imageData, 0, 0);
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  return texture;
}

