        camera.position.set(0, 0, 4);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 5, 5);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 1, 10);
        pointLight.position.set(-2, 2, 3);
        scene.add(pointLight);

        // Create Compass Texture via Canvas
        function createCompassTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Background (Brass color base)
            ctx.fillStyle = '#b5a642'; 
            ctx.fillRect(0, 0, size, size);

            // Add some noise/grain for realism
            for (let i = 0; i < 50000; i++) {
                ctx.fillStyle = Math.random() > 0.5 ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)';
                ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
            }

            const cx = size / 2;
            const cy = size / 2;
            const radius = size / 2 - 20;

            // Outer Rim
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.lineWidth = 40;
            ctx.strokeStyle = '#8a7d32'; // Darker brass for rim
            ctx.stroke();

            // Inner Ring
            ctx.beginPath();
            ctx.arc(cx, cy, radius - 60, 0, Math.PI * 2);
            ctx.lineWidth = 10;
            ctx.strokeStyle = '#5e5520'; // Darker for engraving look
            ctx.stroke();

            // Ticks
            ctx.lineWidth = 4;
            ctx.strokeStyle = '#3d3612'; // Very dark for deep engraving
            for (let i = 0; i < 36; i++) {
                const angle = (i * 10) * (Math.PI / 180);
                const isMajor = i % 9 === 0; // N, E, S, W
                const isMid = i % 3 === 0;

                const len = isMajor ? 80 : (isMid ? 50 : 30);
                const w = isMajor ? 6 : (isMid ? 4 : 2);

                ctx.lineWidth = w;
                const x1 = cx + Math.cos(angle) * (radius - 60);
                const y1 = cy + Math.sin(angle) * (radius - 60);
                const x2 = cx + Math.cos(angle) * (radius - 60 - len);
                const y2 = cy + Math.sin(angle) * (radius - 60 - len);

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.stroke();
            }

            // Text (N, S, E, W)
            ctx.fillStyle = '#2a250e';
            ctx.font = 'bold 120px serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            ctx.fillText('N', cx, cy - (radius - 180));
            ctx.fillText('S', cx, cy + (radius - 180));
            ctx.fillText('E', cx + (radius - 180), cy);
            ctx.fillText('W', cx - (radius - 180), cy);

            // Center Pivot
            ctx.beginPath();
            ctx.arc(cx, cy, 40, 0, Math.PI * 2);
            ctx.fillStyle = '#5e5520';
            ctx.fill();
            ctx.beginPath();
            ctx.arc(cx, cy, 20, 0, Math.PI * 2);
            ctx.fillStyle = '#b5a642';
            ctx.fill();

            // Needle
            ctx.save();
            ctx.translate(cx, cy);
            // North part (Red usually, but let's keep it brass/dark for engraving style or distinct)
            // Let's make the needle distinct.
            ctx.beginPath();
            ctx.moveTo(0, -250);
            ctx.lineTo(15, 0);
            ctx.lineTo(-15, 0);
            ctx.closePath();
            ctx.fillStyle = '#8b0000'; // Dark red
            ctx.fill();

            // South part
            ctx.beginPath();
            ctx.moveTo(0, 250);
            ctx.lineTo(15, 0);
            ctx.lineTo(-15, 0);
            ctx.closePath();
            ctx.fillStyle = '#e0e0e0'; // Silver/White
            ctx.fill();
            ctx.restore();

            return canvas;
        }

        const compassCanvas = createCompassTexture();
        const texture = new THREE.CanvasTexture(compassCanvas);
        texture.colorSpace = THREE.SRGBColorSpace;

        // Material
        const material = new THREE.MeshStandardMaterial({
            map: texture,
            bumpMap: texture,
            bumpScale: 0.02, // Subtle engraving depth
            metalness: 0.7,
            roughness: 0.3,
            color: 0xffd700 // Gold tint
        });

        // Geometry (Flat Cylinder)
        const geometry = new THREE.CylinderGeometry(1.5, 1.5, 0.1, 64);
        const compass = new THREE.Mesh(geometry, material);
        compass.rotation.x = -Math.PI / 2; // Face up
        compass.receiveShadow = true;
        compass.castShadow = true;
        scene.add(compass);

        // Animation
        function animate() {
            requestAnimationFrame(animate);
            // Gentle rotation to show off the material
            compass.rotation.z += 0.002;
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
