  const positions = snow.geometry.attributes.position.array;
  for (let i = 0; i < snowCount; i++) {
    positions[i * 3] += snowVel[i].x + Math.sin(t + i) * 0.001;
    positions[i * 3 + 1] += snowVel[i].y;
    positions[i * 3 + 2] += snowVel[i].z + Math.cos(t + i) * 0.001;

