        // Procedural Texture Generation for Swirls
        function createSwirlTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Dark base
            ctx.fillStyle = '#000000';
            ctx.fillRect(0, 0, size, size);

            // Create swirls
            const centerX = size / 2;
            const centerY = size / 2;

            for (let i = 0; i < 40; i++) {
                ctx.beginPath();
                // Random colors for swirls
                const r = Math.floor(Math.random() * 200 + 55);
                const g = Math.floor(Math.random() * 200 + 55);
                const b = Math.floor(Math.random() * 200 + 55);
                ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${Math.random() * 0.4 + 0.1})`;
                ctx.lineWidth = Math.random() * 30 + 10;

                // Spiral logic
                const startAngle = Math.random() * Math.PI * 2;
                const radius = Math.random() * (size / 2);

                for (let a = startAngle; a < startAngle + Math.PI * 4; a += 0.1) {
                    const rCurrent = radius * (a / (Math.PI * 4)); // Expanding spiral
                    const x = centerX + Math.cos(a) * rCurrent;
                    const y = centerY + Math.sin(a) * rCurrent;
                    if (a === startAngle) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // Add noise for "density" texture
            const imageData = ctx.getImageData(0, 0, size, size);
            const data = imageData.data;
            for (let i = 0; i < data.length; i += 4) {
                const noise = (Math.random() - 0.5) * 40;
                data[i] = Math.min(255, Math.max(0, data[i] + noise));
                data[i+1] = Math.min(255, Math.max(0, data[i+1] + noise));
                data[i+2] = Math.min(255, Math.max(0, data[i+2] + noise));
            }
            ctx.putImageData(imageData, 0, 0);

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            return texture;
        }

        const swirlTexture = createSwirlTexture();

        // Material: Glass Marble
        const material = new THREE.MeshPhysicalMaterial({
