    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
  }

  float fbm(vec3 p) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 1.0;
    for (int i = 0; i < 6; i++) {
      value += amplitude * snoise(p * frequency);
      amplitude *= 0.5;
      frequency *= 2.0;
    }
    return value;
  }

  void main() {
    // Frost pattern using layered noise
    vec3 pos = vPosition * 2.0;
    float frost1 = fbm(pos + vec3(0.0, uTime * 0.02, 0.0));
    float frost2 = fbm(pos * 1.5 + vec3(uTime * 0.01, 0.0, 0.0));
    float frost3 = snoise(pos * 3.0 + uTime * 0.03);

    // Combine frost patterns
    float frost = frost1 * 0.5 + frost2 * 0.3 + frost3 * 0.2;
    frost = smoothstep(-0.3, 0.6, frost);

    // More frost at the top of the globe (gravity effect)
    float heightFactor = smoothstep(-0.8, 1.2, vPosition.y / 2.5);
