            font-size: 14px;
            pointer-events: none;
            text-transform: uppercase;
            letter-spacing: 2px;
        }
    </style>
</head>
<body>
    <div id="info">Compass Quadrant</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        scene.fog = new THREE.Fog(0x111111, 5, 15);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 5);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 5, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffaa00, 1, 10);
        pointLight.position.set(-2, 2, 2);
        scene.add(pointLight);

        // Materials
        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642, // Brass color
            metalness: 0.9,
            roughness: 0.3,
        });

        const darkBrassMaterial = new THREE.MeshStandardMaterial({
            color: 0x8a7d32,
            metalness: 0.8,
            roughness: 0.4,
        });

        // Group for the compass object
        const compassGroup = new THREE.Group();
        scene.add(compassGroup);

        // 1. Base Plate (Circular)
        const baseGeometry = new THREE.CylinderGeometry(1.2, 1.2, 0.1, 64);
        const base = new THREE.Mesh(baseGeometry, darkBrassMaterial);
        base.rotation.x = Math.PI / 2;
        base.receiveShadow = true;
        base.castShadow = true;
        compassGroup.add(base);

        // 2. The Quadrant Mark (90-degree arc)
        // RingGeometry(radiusInner, radiusOuter, thetaSegments, phiSegments, thetaStart, thetaLength)
        // A quadrant is 90 degrees = PI / 2
        const quadrantRadiusInner = 0.8;
        const quadrantRadiusOuter = 1.0;
        const quadrantThickness = 0.15;

        const quadrantGeometry = new THREE.RingGeometry(quadrantRadiusInner, quadrantRadiusOuter, 32, 1, 0, Math.PI / 2);
        const quadrant = new THREE.Mesh(quadrantGeometry, brassMaterial);
        quadrant.rotation.x = -Math.PI / 2; // Lay flat
        quadrant.position.z = 0.06; // Slightly above base
        quadrant.castShadow = true;
        compassGroup.add(quadrant);

        // 3. Extruded Quadrant Block (to give it 3D volume)
        const shape = new THREE.Shape();
        shape.absarc(0, 0, quadrantRadiusOuter, 0, Math.PI / 2, false);
        shape.absarc(0, 0, quadrantRadiusInner, Math.PI / 2, 0, true);

        const extrudeSettings = {
            steps: 1,
            depth: quadrantThickness,
            bevelEnabled: true,
            bevelThickness: 0.02,
            bevelSize: 0.02,
            bevelSegments: 2
        };

        const extrudedGeometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
        const extrudedQuadrant = new THREE.Mesh(extrudedGeometry, brassMaterial);
        extrudedQuadrant.rotation.x = -Math.PI / 2;
        extrudedQuadrant.position.z = 0.05;
        extrudedQuadrant.castShadow = true;
        compassGroup.add(extrudedQuadrant);

        // 4. Tick marks along the quadrant
        const tickCount = 10;
        for (let i = 0; i <= tickCount; i++) {
            const angle = (i / tickCount) * (Math.PI / 2);
            const isMajor = (i % 5 === 0);
            const tickLength = isMajor ? 0.1 : 0.05;
            const tickWidth = isMajor ? 0.04 : 0.02;

            const tickGeo = new THREE.BoxGeometry(tickWidth, tickLength, 0.05);
            const tick = new THREE.Mesh(tickGeo, brassMaterial);

            // Position on the outer edge
            const r = quadrantRadiusOuter + (tickLength / 2);
            tick.position.x = Math.cos(angle) * r;
            tick.position.y = Math.sin(angle) * r;
            tick.position.z = 0.15; // On top of the extruded part
            tick.rotation.z = -angle + Math.PI / 2; // Rotate to face center

            compassGroup.add(tick);
        }

        // 5. Center Pivot
        const pivotGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.2, 32);
        const pivot = new THREE.Mesh(pivotGeo, brassMaterial);
        pivot.position.z = 0.1;
        pivot.castShadow = true;
        compassGroup.add(pivot);

        // 6. Needle (Simple pointer)
        const needleShape = new THREE.Shape();
        needleShape.moveTo(0, 0);
        needleShape.lineTo(0.1, 0);
        needleShape.lineTo(0, 0.8);
        needleShape.lineTo(-0.1, 0);
        needleShape.lineTo(0, 0);

        const needleGeo = new THREE.ExtrudeGeometry(needleShape, { depth: 0.02, bevelEnabled: false });
        const needleMat = new THREE.MeshStandardMaterial({ color: 0xcc0000, metalness: 0.5, roughness: 0.5 }); // Red needle
        const needle = new THREE.Mesh(needleGeo, needleMat);
        needle.rotation.x = -Math.PI / 2;
        needle.position.z = 0.22;
        needle.rotation.z = Math.PI / 4; // Pointing into the quadrant
        compassGroup.add(needle);

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            compassGroup.rotation.y += 0.005;
            compassGroup.rotation.z = Math.sin(Date.now() * 0.001) * 0.1;

            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
