}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// ── Renderer ──
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Scene & Camera ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a12);

const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 6);

// ── Environment (for glass refraction) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// ── Controls ──
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);

// ── Glass Marble ──
const marbleGeo = new THREE.SphereGeometry(1.5, 128, 128);
const marbleMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.97,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.02,
  ior: 1.52,
  thickness: 2.5,
  envMapIntensity: 1.5,
  clearcoat: 1.0,
  clearcoatRoughness: 0.01,
  attenuationColor: new THREE.Color(0.85, 0.9, 1.0),
  attenuationDistance: 3,
  side: THREE.DoubleSide,
});
const marble = new THREE.Mesh(marbleGeo, marbleMat);
scene.add(marble);

// ── Swirl Streaks ──
const swirlGroup = new THREE.Group();
marble.add(swirlGroup);

const swirlColors = [
  new THREE.Color(0xff2266),
  new THREE.Color(0xff8800),
  new THREE.Color(0xffee00),
  new THREE.Color(0x00ff88),
  new THREE.Color(0x00aaff),
  new THREE.Color(0x8844ff),
  new THREE.Color(0xff44cc),
  new THREE.Color(0x44ffcc),
];

function createSwirlPath(radius, height, turns, offset, direction) {
  const points = [];
  const steps = 200;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = t * Math.PI * 2 * turns * direction + offset;
    const r = radius * (0.3 + 0.7 * Math.sin(t * Math.PI));
    const x = Math.cos(angle) * r;
    const z = Math.sin(angle) * r;
    const y = (t - 0.5) * height + Math.sin(t * Math.PI * 3) * 0.1;
    points.push(new THREE.Vector3(x, y, z));
  }
  return new THREE.CatmullRomCurve3(points);
}

function createSwirlPath2D(radius, turns, offset, plane) {
  const points = [];
  const steps = 256;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = t * Math.PI * 2 * turns + offset;
    const r = radius * (0.1 + 0.85 * Math.pow(Math.sin(t * Math.PI), 0.5));
    const x = Math.cos(angle) * r;
    const y = Math.sin(angle) * r;
    const z = Math.sin(t * Math.PI * 2) * 0.15;
    if (plane === 'xz') points.push(new THREE.Vector3(x, z, y));
    else if (plane === 'xy') points.push(new THREE.Vector3(x, y, z));
    else points.push(new THREE.Vector3(z, x, y));
  }
  return new THREE.CatmullRomCurve3(points);
}

const swirlConfigs = [
  // Helical spirals
  { path: () => createSwirlPath(1.1, 2.2, 3, 0, 1), radius: 0.035, color: 0 },
  { path: () => createSwirlPath(0.9, 2.0, 4, 1.2, -1), radius: 0.028, color: 1 },
  { path: () => createSwirlPath(0.7, 1.8, 5, 2.5, 1), radius: 0.022, color: 2 },
  { path: () => createSwirlPath(0.5, 1.6, 3.5, 0.8, -1), radius: 0.025, color: 3 },
  { path: () => createSwirlPath(1.0, 2.4, 2.5, 3.1, 1), radius: 0.03, color: 4 },
  { path: () => createSwirlPath(0.6, 1.4, 6, 1.8, -1), radius: 0.018, color: 5 },
  // 2D spiral layers
  { path: () => createSwirlPath2D(1.0, 4, 0, 'xz'), radius: 0.02, color: 6 },
  { path: () => createSwirlPath2D(0.8, 5, 1.5, 'xz'), radius: 0.025, color: 0 },
  { path: () => createSwirlPath2D(0.9, 3, 0.5, 'xy'), radius: 0.022, color: 2 },
  { path: () => createSwirlPath2D(0.7, 6, 2.0, 'xy'), radius: 0.018, color: 4 },
  { path: () => createSwirlPath2D(1.05, 3.5, 1.0, 'yz'), radius: 0.02, color: 1 },
  { path: () => createSwirlPath2D(0.65, 5.5, 2.5, 'yz'), radius: 0.024, color: 3 },
];

swirlConfigs.forEach(cfg => {
  const curve = cfg.path();
  const tubeGeo = new THREE.TubeGeometry(curve, 200, cfg.radius, 12, false);
  const tubeMat = new THREE.MeshPhysicalMaterial({
    color: swirlColors[cfg.color],
    emissive: swirlColors[cfg.color],
    emissiveIntensity: 0.6,
    transparent: true,
    opacity: 0.85,
    roughness: 0.1,
    metalness: 0.1,
    transmission: 0.3,
    thickness: 0.5,
  });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  swirlGroup.add(tube);
});

// ── Inner glow core ──
const coreGeo = new THREE.SphereGeometry(0.25, 32, 32);
const coreMat = new THREE.MeshBasicMaterial({
  color: 0xffffff,
  transparent: true,
  opacity: 0.15,
});
const core = new THREE.Mesh(coreGeo, coreMat);
swirlGroup.add(core);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffffff, 3);
keyLight.position.set(5, 5, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 1.5);
fillLight.position.set(-5, 0, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff8844, 2);
rimLight.position.set(0, -3, -5);
scene.add(rimLight);

const topLight = new THREE.PointLight(0xffffff, 2, 20);
topLight.position.set(0, 5, 0);
scene.add(topLight);

// ── Floor reflection hint ──
const floorGeo = new THREE.PlaneGeometry(30, 30);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x0a0a12,
  roughness: 0.3,
  metalness: 0.8,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2.2;
scene.add(floor);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  swirlGroup.rotation.y = t * 0.15;
  swirlGroup.rotation.x = Math.sin(t * 0.1) * 0.1;

  // Subtle color cycling
  swirlGroup.children.forEach((child, i) => {
    if (child.material && child.material.emissive) {
      const hue = (t * 0.05 + i * 0.08) % 1;
      child.material.emissive.setHSL(hue, 0.9, 0.5);
      child.material.color.setHSL(hue, 0.9, 0.5);
      child.material.emissiveIntensity = 0.5 + Math.sin(t * 2 + i) * 0.2;
    }
  });

  // Marble hover
  marble.position.y = Math.sin(t * 0.5) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
