        const snowCount = 400;
        const snowGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(snowCount * 3);
        const velocities = [];

        for (let i = 0; i < snowCount; i++) {
            // Random position inside sphere
            const r = 1.8 * Math.cbrt(Math.random());
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta);
            const z = r * Math.cos(phi);

            positions[i * 3] = x;
            positions[i * 3 + 1] = y;
            positions[i * 3 + 2] = z;

            velocities.push({
                x: (Math.random() - 0.5) * 0.005,
                y: -0.01 - Math.random() * 0.02, // Falling down
                z: (Math.random() - 0.5) * 0.005
            });
        }

        snowGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const snowMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.05,
            transparent: true,
            opacity: 0.8
        });
        const snowSystem = new THREE.Points(snowGeometry, snowMaterial);
        globeGroup.add(snowSystem);

        // 4. The Base
        const baseGeometry = new THREE.CylinderGeometry(1.2, 1.4, 0.5, 32);
        const baseMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            roughness: 0.2,
            metalness: 0.8
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = -2.2;
        globeGroup.add(base);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const positions = snowSystem.geometry.attributes.position.array;

            // Animate Snow
            for (let i = 0; i < snowCount; i++) {
                let x = positions[i * 3];
                let y = positions[i * 3 + 1];
                let z = positions[i * 3 + 2];

                // Apply velocity
                x += velocities[i].x;
                y += velocities[i].y;
                z += velocities[i].z;

                // Reset if below base
                if (y < -1.8) {
                    y = 1.8;
                    x = (Math.random() - 0.5) * 3;
                    z = (Math.random() - 0.5) * 3;
                }

                positions[i * 3] = x;
                positions[i * 3 + 1] = y;
                positions[i * 3 + 2] = z;
            }
            snowSystem.geometry.attributes.position.needsUpdate = true;

            // Gentle rotation of the whole globe
            globeGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
