const ambientLight = new THREE.AmbientLight(0xffeedd, 0.3);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xfff4e0, 2.5);
keyLight.position.set(5, 5, 8);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc4b080, 1.0);
fillLight.position.set(-5, 3, 4);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffd68a, 1.5);
rimLight.position.set(0, -3, -5);
scene.add(rimLight);

const pointLight = new THREE.PointLight(0xffaa44, 2, 20);
pointLight.position.set(3, 4, 6);
scene.add(pointLight);

// ── Brass Material ──
const brassMaterial = new THREE.MeshStandardMaterial({
  color: 0xc8a84e,
  metalness: 0.92,
  roughness: 0.18,
});

