});

const engravingMat = new THREE.MeshStandardMaterial({
  color: 0x2a1f0a,
  metalness: 0.3,
  roughness: 0.7,
});

// ── Arc Geometry (60° sextant arc) ──
const ARC_RADIUS = 4.0;
const ARC_START = -Math.PI / 3;  // -60°
const ARC_END = Math.PI / 3;     // +60°
const ARC_SEGMENTS = 120;

function createArc() {
  const group = new THREE.Group();

  // Main arc frame — outer and inner arcs connected by a ring
  const outerArcShape = new THREE.Shape();
  const innerR = ARC_RADIUS - 0.5;
  const outerR = ARC_RADIUS + 0.15;

  for (let i = 0; i <= ARC_SEGMENTS; i++) {
    const t = i / ARC_SEGMENTS;
    const angle = ARC_START + t * (ARC_END - ARC_START);
    const x = Math.cos(angle) * outerR;
    const y = Math.sin(angle) * outerR;
    if (i === 0) outerArcShape.moveTo(x, y);
    else outerArcShape.lineTo(x, y);
  }
  for (let i = ARC_SEGMENTS; i >= 0; i--) {
    const t = i / ARC_SEGMENTS;
    const angle = ARC_START + t * (ARC_END - ARC_START);
    const x = Math.cos(angle) * innerR;
    const y = Math.sin(angle) * innerR;
    outerArcShape.lineTo(x, y);
  }
  outerArcShape.closePath();

  const arcGeom = new THREE.ExtrudeGeometry(outerArcShape, {
    depth: 0.12, bevelEnabled: true, bevelThickness: 0.015,
    bevelSize: 0.015, bevelSegments: 2
  });
  const arcMesh = new THREE.Mesh(arcGeom, brassMaterial);
  arcMesh.rotation.x = 0;
  group.add(arcMesh);

