    const midR = (baseR + tipR) / 2;
    tick.position.set(Math.cos(angle) * midR, Math.sin(angle) * midR, 0);
    tick.rotation.z = -angle;
    group.add(tick);

    // Number labels as small 3D elements for major ticks
