    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510);
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.minDistance = 4;
        controls.maxDistance = 15;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.2);
        scene.add(ambientLight);

        const spotLight = new THREE.SpotLight(0xffffff, 20);
        spotLight.position.set(5, 10, 5);
        spotLight.angle = Math.PI / 6;
        spotLight.penumbra = 1;
        scene.add(spotLight);

        const blueLight = new THREE.PointLight(0x4444ff, 5, 10);
        blueLight.position.set(-3, 2, -3);
        scene.add(blueLight);

        const warmLight = new THREE.PointLight(0xffaa00, 5, 10);
        warmLight.position.set(3, 2, 3);
        scene.add(warmLight);

        // Environment Map (Simple procedural for reflections)
        const cubeRenderTarget = new THREE.WebGLCubeRenderTarget(256);
        const cubeCamera = new THREE.CubeCamera(0.1, 100, cubeRenderTarget);
        scene.add(cubeCamera);

        // Glass Globe
        const globeGeometry = new THREE.SphereGeometry(2, 64, 64);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.95, // Glass-like transparency
            thickness: 1.5, // Refraction volume
            ior: 1.5,
            clearcoat: 1,
            clearcoatRoughness: 0,
            envMap: cubeRenderTarget.texture,
            envMapIntensity: 1,
            transparent: true,
            opacity: 1
        });
        const globe = new THREE.Mesh(globeGeometry, glassMaterial);
        globe.position.y = 2;
        scene.add(globe);

        // Base
        const baseGeometry = new THREE.CylinderGeometry(1.8, 1.5, 1, 64);
        const baseMaterial = new THREE.MeshStandardMaterial({
            color: 0x111111,
            roughness: 0.2,
            metalness: 0.8
        });
        const base = new THREE.Mesh(baseGeometry, baseMaterial);
        base.position.y = 0.5;
        scene.add(base);

        // Particles (Snow/Water)
        const particleCount = 800;
        const particlesGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const velocities = [];

        for (let i = 0; i < particleCount; i++) {
            // Random position inside sphere
            const r = 1.8 * Math.cbrt(Math.random()); // Uniform distribution in sphere
            const theta = Math.random() * 2 * Math.PI;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = r * Math.sin(phi) * Math.cos(theta);
            const y = r * Math.sin(phi) * Math.sin(theta);
            const z = r * Math.cos(phi);

            positions[i * 3] = x;
            positions[i * 3 + 1] = y + 2; // Offset to center in globe
            positions[i * 3 + 2] = z;

            velocities.push({
                x: (Math.random() - 0.5) * 0.01,
                y: (Math.random() - 0.5) * 0.01,
                z: (Math.random() - 0.5) * 0.01,
                speed: 0.005 + Math.random() * 0.01
            });
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        // Create a soft circle texture for particles
        const getParticleTexture = () => {
            const canvas = document.createElement('canvas');
            canvas.width = 32;
            canvas.height = 32;
            const ctx = canvas.getContext('2d');
            const gradient = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            gradient.addColorStop(0, 'rgba(255,255,255,1)');
            gradient.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, 32, 32);
            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        };

        const particlesMaterial = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.08,
            map: getParticleTexture(),
            transparent: true,
            opacity: 0.8,
            depthWrite: false,
            blending: THREE.AdditiveBlending
        });

        const particleSystem = new THREE.Points(particlesGeometry, particlesMaterial);
        scene.add(particleSystem);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Update particles
            const posAttribute = particleSystem.geometry.attributes.position;
            for (let i = 0; i < particleCount; i++) {
                const v = velocities[i];

                // Simple floating motion
                let x = posAttribute.getX(i);
                let y = posAttribute.getY(i);
                let z = posAttribute.getZ(i);

                // Add some swirl
                const angle = time * v.speed + i;
                const radius = Math.sqrt(x*x + z*z);

                // Gentle rotation around Y axis
                const newX = x * Math.cos(0.005) - z * Math.sin(0.005);
                const newZ = x * Math.sin(0.005) + z * Math.cos(0.005);

                // Bobbing up and down
                y += Math.sin(time * 2 + i) * 0.002;

                // Keep inside sphere (simple boundary check)
                const dist = Math.sqrt(newX*newX + (y-2)*(y-2) + newZ*newZ);
                if (dist > 1.8) {
                    // Reset to center-ish if they escape
                    const scale = 1.8 / dist;
                    posAttribute.setXYZ(i, newX * scale, (y-2) * scale + 2, newZ * scale);
                } else {
                    posAttribute.setXYZ(i, newX, y, newZ);
                }
            }
            posAttribute.needsUpdate = true;

            // Update environment map occasionally for reflections
            if (Math.floor(time * 10) % 5 === 0) {
                globe.visible = false;
                cubeCamera.position.copy(globe.position);
                cubeCamera.update(renderer, scene);
                globe.visible = true;
            }

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
