            // Background
            ctx.fillStyle = '#d4af37';
            ctx.fillRect(0, 0, 512, 128);

            // Main horizontal lines
            ctx.strokeStyle = '#111';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(512, 0);
            ctx.moveTo(0, 64); ctx.lineTo(512, 64);
            ctx.moveTo(0, 128); ctx.lineTo(512, 128);
            ctx.stroke();

            // Vertical divisions (degrees)
            for(let i=0; i<=10; i++) {
                const x = i * (512/10);
                ctx.beginPath();
                ctx.moveTo(x, 0); ctx.lineTo(x, 128);
                ctx.stroke();

                // Subdivisions
                if(i < 10) {
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(x + (512/20), 20); ctx.lineTo(x + (512/20), 108);
                    ctx.stroke();
                    ctx.lineWidth = 2;
