                const endX = (i+1) * (512/10);
                // Diagonal 1
                ctx.moveTo(startX, 0); ctx.lineTo(endX, 128);
                // Diagonal 2
                ctx.moveTo(startX, 128); ctx.lineTo(endX, 0);
