controls.target.set(0, 0.6, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.minDistance = 3;
controls.maxDistance = 12;
controls.maxPolarAngle = Math.PI / 2 + 0.1;
controls.update();

// ── Glass Material ──
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  transmission: 0.92,
  opacity: 1,
  transparent: true,
  metalness: 0.0,
  roughness: 0.05,
  ior: 1.52,
  thickness: 0.5,
  specularIntensity: 1.0,
  specularColor: new THREE.Color(0xffffff),
  envMapIntensity: 1.5,
  clearcoat: 0.1,
  clearcoatRoughness: 0.05,
  side: THREE.DoubleSide,
});

// ── Gold trim material ──
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xc9a84c,
  metalness: 0.95,
  roughness: 0.18,
  envMapIntensity: 1.2,
});

// ── Build Base ──
const baseGroup = new THREE.Group();

// Bottom ring (widest)
const bottomRing = new THREE.Mesh(
  new THREE.CylinderGeometry(1.3, 1.4, 0.15, 64),
  glassMat
);
bottomRing.position.y = 0.075;
baseGroup.add(bottomRing);

// Gold trim ring at bottom
const bottomTrim = new THREE.Mesh(
  new THREE.TorusGeometry(1.35, 0.03, 16, 64),
  goldMat
);
bottomTrim.rotation.x = Math.PI / 2;
bottomTrim.position.y = 0.15;
baseGroup.add(bottomTrim);

// Main body (tapered cylinder going up)
const bodyGeo = new THREE.CylinderGeometry(1.0, 1.3, 0.7, 64, 1, true);
const body = new THREE.Mesh(bodyGeo, glassMat);
body.position.y = 0.5;
baseGroup.add(body);

