);
midTrim.rotation.x = Math.PI / 2;
midTrim.position.y = 0.85;
baseGroup.add(midTrim);

// Upper section (narrower)
const upperGeo = new THREE.CylinderGeometry(0.85, 1.0, 0.45, 64, 1, true);
const upper = new THREE.Mesh(upperGeo, glassMat);
upper.position.y = 1.12;
baseGroup.add(upper);

