scene.add(marble);

// ── Swirl Ribbon Geometry ──
function createSwirlRibbon(segments, rings, radius, width, turns) {
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const angle = t * Math.PI * 2 * turns;
    const spiralRadius = radius * (0.3 + 0.7 * Math.sin(t * Math.PI));
    const x = Math.cos(angle) * spiralRadius;
    const z = Math.sin(angle) * spiralRadius;
    const y = (t - 0.5) * radius * 2.5;

    // Tangent of the curve
    const da = (Math.PI * 2 * turns) / segments;
    const dt = 1 / segments;
    const nextAngle = angle + da;
    const nextT = t + dt;
    const nextSpiralR = radius * (0.3 + 0.7 * Math.sin(nextT * Math.PI));
    const dx = Math.cos(nextAngle) * nextSpiralR - x;
    const dy = dt * radius * 2.5;
    const dz = Math.sin(nextAngle) * nextSpiralR - z;
    const tangent = new THREE.Vector3(dx, dy, dz).normalize();

    // Up vector (cross with world up, then cross back)
    let up = new THREE.Vector3().crossVectors(tangent, new THREE.Vector3(0, 1, 0)).normalize();
    if (up.length() < 0.001) up.set(1, 0, 0);
    const normal = new THREE.Vector3().crossVectors(tangent, up).normalize();

    // Twist the ribbon
    const twistAngle = t * Math.PI * 6;
    const twistedNormal = new THREE.Vector3(
      normal.x * Math.cos(twistAngle) - up.x * Math.sin(twistAngle),
      normal.x * Math.cos(twistAngle) - up.x * Math.sin(twistAngle) * 0,
      normal.x * Math.cos(twistAngle) - up.x * Math.sin(twistAngle)
    );

    // Simpler twist: rotate around tangent
    const perp = new THREE.Vector3().crossVectors(tangent, new THREE.Vector3(0, 1, 0)).normalize();
    const side = new THREE.Vector3().crossVectors(tangent, perp).normalize();

    // Apply twist
    const cosTw = Math.cos(twistAngle);
    const sinTw = Math.sin(twistAngle);
    const ribbonDir = new THREE.Vector3(
      perp.x * cosTw + side.x * sinTw,
      perp.y * cosTw + side.y * sinTw,
      perp.z * cosTw + side.z * sinTw
    );

    // Inner and outer points
    const hw = width * 0.5;
    const inner = new THREE.Vector3(x, y, z).addScaledVector(ribbonDir, -hw);
    const outer = new THREE.Vector3(x, y, z).addScaledVector(ribbonDir, hw);

    positions.push(inner.x, inner.y, inner.z);
    positions.push(outer.x, outer.y, outer.z);

    // Approximate normals
    const nInner = ribbonDir.clone().negate();
    const nOuter = ribbonDir.clone();
    normals.push(nInner.x, nInner.y, nInner.z);
    normals.push(nOuter.x, nOuter.y, nOuter.z);

    uvs.push(0, t);
    uvs.push(1, t);

    if (i < segments) {
      const base = i * 2;
      indices.push(base, base + 1, base + 2);
      indices.push(base + 1, base + 3, base + 2);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  return geo;
}

// ── Ribbon Material with vibrant swirl colors ──
const ribbonCanvas = document.createElement('canvas');
ribbonCanvas.width = 512; ribbonCanvas.height = 64;
const rctx = ribbonCanvas.getContext('2d');
const ribbonGrad = rctx.createLinearGradient(0, 0, 512, 0);
ribbonGrad.addColorStop(0.0, '#ff0066');
ribbonGrad.addColorStop(0.15, '#ff6600');
ribbonGrad.addColorStop(0.3, '#ffcc00');
ribbonGrad.addColorStop(0.45, '#33ff66');
ribbonGrad.addColorStop(0.6, '#00ccff');
ribbonGrad.addColorStop(0.75, '#6633ff');
ribbonGrad.addColorStop(0.9, '#ff00cc');
ribbonGrad.addColorStop(1.0, '#ff0066');
rctx.fillStyle = ribbonGrad;
rctx.fillRect(0, 0, 512, 64);
const ribbonTexture = new THREE.CanvasTexture(ribbonCanvas);
ribbonTexture.wrapS = THREE.RepeatWrapping;

const ribbonMat = new THREE.MeshPhysicalMaterial({
  map: ribbonTexture,
  color: 0xffffff,
  metalness: 0.3,
  roughness: 0.15,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1,
  emissive: new THREE.Color(0x220022),
  emissiveIntensity: 0.3,
  side: THREE.DoubleSide,
});

const ribbonGeo = createSwirlRibbon(256, 16, 1.2, 0.18, 3);
const ribbon = new THREE.Mesh(ribbonGeo, ribbonMat);
scene.add(ribbon);

// ── Second thinner ribbon for extra swirl ──
const ribbon2Mat = new THREE.MeshPhysicalMaterial({
  map: ribbonTexture,
  color: 0xffffff,
  metalness: 0.2,
  roughness: 0.2,
  clearcoat: 1.0,
  clearcoatRoughness: 0.05,
  emissive: new THREE.Color(0x110033),
  emissiveIntensity: 0.2,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.8,
});

const ribbon2Geo = createSwirlRibbon(256, 16, 1.0, 0.1, 4);
const ribbon2 = new THREE.Mesh(ribbon2Geo, ribbon2Mat);
ribbon2.rotation.y = Math.PI / 3;
scene.add(ribbon2);

// ── Ground reflection plane ──
const groundGeo = new THREE.CircleGeometry(4, 64);
const groundMat = new THREE.MeshPhysicalMaterial({
  color: 0x111122,
  metalness: 0.8,
  roughness: 0.2,
  transparent: true,
  opacity: 0.5,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -2.2;
scene.add(ground);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 1.5);
fillLight.position.set(-5, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff6699, 2);
rimLight.position.set(0, -2, -5);
scene.add(rimLight);

const topLight = new THREE.PointLight(0xffffff, 2, 20);
topLight.position.set(0, 6, 0);
scene.add(topLight);

// ── Floating particles ──
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3] = (Math.random() - 0.5) * 10;
  particlePositions[i * 3 + 1] = (Math.random() - 0.5) * 10;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 10;
}
particleGeo.setAttribute('position', new THREE.Float32BufferAttribute(particlePositions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0x8888cc,
  size: 0.02,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Slowly rotate ribbons
  ribbon.rotation.y = t * 0.3;
  ribbon.rotation.x = Math.sin(t * 0.2) * 0.2;
  ribbon2.rotation.y = -t * 0.25 + Math.PI / 3;
  ribbon2.rotation.z = Math.sin(t * 0.15) * 0.15;

  // Gentle marble bob
  marble.position.y = Math.sin(t * 0.5) * 0.08;
  ribbon.position.y = marble.position.y;
  ribbon2.position.y = marble.position.y;

  // Rotate particles
  particles.rotation.y = t * 0.02;
  particles.rotation.x = t * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```

## What this creates:

- **Glass Marble** — A `MeshPhysicalMaterial` sphere with `transmission: 0.95`, IOR 1.52 (real glass), subtle blue attenuation color, and clearcoat for realistic refraction/reflection
- **Swirl Ribbon** — A custom parametric ribbon geometry that spirals 3 full turns through the marble with a 6× twist, colored with a vibrant gradient (pink → orange → yellow → green → blue → purple)
- **Second Ribbon** — A thinner, semi-transparent ribbon rotating in a different axis for extra depth and complexity
- **Environment** — Uses Three.js `RoomEnvironment` via PMREM for realistic glass reflections, plus a dark gradient background
- **Lighting** — Key, fill, rim, and top lights for dramatic glass highlights
- **Animation** — Gentle rotation of the ribbons inside the marble, subtle bob, and floating dust particles
- **OrbitControls** — Click and drag to rotate the view, scroll to zoom

