            roughness: 0.05,
            transmission: 0.95, // Glass transparency
            thickness: 2.0, // Volume for refraction
            ior: 1.5, // Index of refraction for glass
            envMapIntensity: 1.0,
            clearcoat: 1.0,
            clearcoatRoughness: 0.0,
            attenuationColor: new THREE.Color(0xffffff),
