        // Create a spiral curve
        const points = [];
        const turns = 3;
        const radius = 1.2;
        const height = 2.5;
        const segments = 100;

        for (let i = 0; i <= segments; i++) {
            const t = i / segments;
            const angle = t * Math.PI * 2 * turns;
            const x = Math.cos(angle) * radius * (1 - t * 0.2); // Slight taper
            const y = (t - 0.5) * height;
            const z = Math.sin(angle) * radius * (1 - t * 0.2);
            points.push(new THREE.Vector3(x, y, z));
        }

        const curve = new THREE.CatmullRomCurve3(points);
        const tubeGeometry = new THREE.TubeGeometry(curve, 100, 0.15, 12, false);

        // Vein Material - glowing and colorful
        const veinMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ffcc,
            emissive: 0x00aa88,
            emissiveIntensity: 2.0,
            roughness: 0.2,
            metalness: 0.8,
