        });

        const vein = new THREE.Mesh(tubeGeometry, veinMaterial);
        // Scale down slightly to fit inside
        vein.scale.set(0.8, 0.8, 0.8);
        scene.add(vein);

        // Add a second, thinner vein for complexity
        const points2 = [];
        for (let i = 0; i <= segments; i++) {
