renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.minDistance = 2;
controls.maxDistance = 15;

// ── Lighting ──
const ambientLight = new THREE.AmbientLight(0xffeedd, 0.4);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xfff5e0, 2.5);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xc8d8ff, 0.8);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffcc88, 1.5, 12);
rimLight.position.set(-2, -1, -3);
scene.add(rimLight);

const topLight = new THREE.PointLight(0xffffff, 1.0, 10);
topLight.position.set(0, 6, 2);
scene.add(topLight);

// ── Environment map (procedural) ──
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x2a2a3e);
const envLight1 = new THREE.PointLight(0xffeedd, 10, 20);
envLight1.position.set(3, 5, 3);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0x8899cc, 5, 20);
envLight2.position.set(-4, 1, -3);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
scene.environment = envRT.texture;

// ── Brass material ──
const brassMat = new THREE.MeshStandardMaterial({
  color: 0xc49a3c,
  metalness: 0.95,
  roughness: 0.18,
  envMapIntensity: 1.0,
});

const darkBrassMat = new THREE.MeshStandardMaterial({
  color: 0x8a6e2f,
  metalness: 0.92,
  roughness: 0.25,
  envMapIntensity: 0.8,
});

// ── Sextant parameters ──
const ARC_RADIUS = 2.0;
const ARC_ANGLE = 60 * (Math.PI / 180); // 60 degrees
const ARC_THICKNESS = 0.06;
const ARC_WIDTH = 0.35;
const TICK_INNER_R = ARC_RADIUS - ARC_WIDTH / 2;
const TICK_OUTER_R = ARC_RADIUS + ARC_WIDTH / 2;

// ── Main arc body ──
function createArcBody() {
  const shape = new THREE.Shape();
  const halfAngle = ARC_ANGLE / 2;
  const rInner = ARC_RADIUS - ARC_WIDTH / 2;
  const rOuter = ARC_RADIUS + ARC_WIDTH / 2;

  // Outer arc
  for (let i = 0; i <= 64; i++) {
    const a = -halfAngle + (ARC_ANGLE * i) / 64;
    const x = rOuter * Math.sin(a);
    const y = rOuter * Math.cos(a);
    if (i === 0) shape.moveTo(x, y);
    else shape.lineTo(x, y);
  }
  // Inner arc (reverse)
  for (let i = 64; i >= 0; i--) {
    const a = -halfAngle + (ARC_ANGLE * i) / 64;
    const x = rInner * Math.sin(a);
    const y = rInner * Math.cos(a);
    shape.lineTo(x, y);
  }
  shape.closePath();

  const extrudeSettings = { depth: ARC_THICKNESS, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.008, bevelSegments: 3 };
  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.center();
  return new THREE.Mesh(geo, brassMat);
}

scene.add(createArcBody());

// ── Tick marks ──
const tickGroup = new THREE.Group();
scene.add(tickGroup);

function addTick(angle, length, width, mat) {
  const geo = new THREE.BoxGeometry(width, length, ARC_THICKNESS + 0.015);
  const tick = new THREE.Mesh(geo, mat);

  const midR = ARC_RADIUS + (length / 2) * (length > 0 ? 1 : -1);
  const r = ARC_RADIUS;

  tick.position.set(
    r * Math.sin(angle),
    r * Math.cos(angle),
    0
  );
  tick.rotation.z = -angle;
  tickGroup.add(tick);
}

// Degree ticks along the arc
const totalDegrees = 60;
const angleStep = ARC_ANGLE / totalDegrees;

for (let deg = 0; deg <= totalDegrees; deg++) {
  const angle = -ARC_ANGLE / 2 + deg * angleStep;

  if (deg % 10 === 0) {
    // Major tick (10°) — longest, widest
    addTick(angle, 0.22, 0.035, darkBrassMat);
    // Double line for major
    addTick(angle, 0.22, 0.012, darkBrassMat);
    const offsetMesh = tickGroup.children[tickGroup.children.length - 1];
    offsetMesh.position.z += 0.008;
  } else if (deg % 5 === 0) {
    // Medium tick (5°)
    addTick(angle, 0.15, 0.025, brassMat);
  } else if (deg % 2 === 0) {
    // Half-degree tick
    addTick(angle, 0.10, 0.018, brassMat);
  } else {
