    addTick(angle, 0.07, 0.012, brassMat);
  }
}

// ── Center hub ──
const hubGeo = new THREE.CylinderGeometry(0.18, 0.18, ARC_THICKNESS + 0.04, 32);
const hub = new THREE.Mesh(hubGeo, brassMat);
hub.rotation.x = Math.PI / 2;
scene.add(hub);

const hubRingGeo = new THREE.TorusGeometry(0.22, 0.02, 8, 32);
const hubRing = new THREE.Mesh(hubRingGeo, darkBrassMat);
scene.add(hubRing);

// ── Index arm (pointer) ──
const armGeo = new THREE.BoxGeometry(0.04, 1.6, 0.04);
const arm = new THREE.Mesh(armGeo, brassMat);
arm.position.y = 0.5;
scene.add(arm);

// Index arm tip (small circle at arc)
const tipGeo = new THREE.CylinderGeometry(0.04, 0.04, 0.05, 16);
const tip = new THREE.Mesh(tipGeo, brassMat);
tip.rotation.x = Math.PI / 2;
tip.position.y = 1.3;
scene.add(tip);

