function createFrameArm(side) {
  const angle = side * (ARC_ANGLE / 2);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.lineTo(0.05 * side, 0.03);
  shape.lineTo(ARC_RADIUS * Math.sin(angle) - 0.02 * side, ARC_RADIUS * Math.cos(angle) - 0.01);
  shape.lineTo(ARC_RADIUS * Math.sin(angle) + 0.02 * side, ARC_RADIUS * Math.cos(angle) + 0.01);
  shape.lineTo(0.05 * side, -0.03);
  shape.closePath();

  const geo = new THREE.ExtrudeGeometry(shape, { depth: ARC_THICKNESS, bevelEnabled: true, bevelThickness: 0.005, bevelSize: 0.005, bevelSegments: 2 });
  const mesh = new THREE.Mesh(geo, brassMat);
  return mesh;
}

scene.add(createFrameArm(-1));
scene.add(createFrameArm(1));

// ── Degree labels (canvas textures) ──
function createLabel(text, angle) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, 128, 64);
  ctx.fillStyle = '#1a0f00';
  ctx.font = 'bold 40px Georgia';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 64, 32);

  const tex = new THREE.CanvasTexture(canvas);
  const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.35, 0.17), mat);

  const labelR = ARC_RADIUS + ARC_WIDTH / 2 + 0.25;
  plane.position.set(labelR * Math.sin(angle), labelR * Math.cos(angle), 0.04);
  plane.lookAt(0, 0, 0.04);
  return plane;
}

for (let deg = 0; deg <= 60; deg += 10) {
  const angle = -ARC_ANGLE / 2 + deg * (ARC_ANGLE / 60);
  scene.add(createLabel(deg.toString(), angle));
