scene.add(topLight);

// ── Environment (simple procedural) ──
const pmremGenerator = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x1a1a2e);
const envLight1 = new THREE.PointLight(0xffd699, 10, 50);
envLight1.position.set(5, 5, 5);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0xc4a060, 8, 50);
envLight2.position.set(-5, 3, -3);
envScene.add(envLight2);
const envRT = pmremGenerator.fromScene(envScene);
scene.environment = envRT.texture;

// ── Brass Material ──
const brassMaterial = new THREE.MeshStandardMaterial({
  color: 0xb8860b,
  metalness: 0.95,
  roughness: 0.18,
  envMapIntensity: 1.5,
});

const darkBrassMaterial = new THREE.MeshStandardMaterial({
  color: 0x8b6914,
  metalness: 0.92,
  roughness: 0.25,
  envMapIntensity: 1.2,
});

const redAccentMaterial = new THREE.MeshStandardMaterial({
  color: 0x8b1a1a,
  metalness: 0.85,
  roughness: 0.2,
  envMapIntensity: 1.3,
});

// ── Compass Group ──
const compass = new THREE.Group();
scene.add(compass);

// ── Helper: create a single compass point (diamond shape) ──
function createCompassPoint(length, width, height, isRed = false) {
  const shape = new THREE.Shape();
  shape.moveTo(0, length);
  shape.lineTo(-width, 0);
  shape.lineTo(0, -length * 0.25);
  shape.lineTo(width, 0);
  shape.closePath();

  const extrudeSettings = {
    depth: height,
    bevelEnabled: true,
    bevelThickness: height * 0.15,
    bevelSize: height * 0.1,
    bevelSegments: 3,
  };

  const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geometry.center();

  const material = isRed ? redAccentMaterial : brassMaterial;
  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// ── Main 4-point star (N, S, E, W) ──
const mainPoints = [];
for (let i = 0; i < 4; i++) {
  const point = createCompassPoint(3.2, 0.45, 0.15, i === 0);
  point.rotation.z = (Math.PI / 2) * i;
  compass.add(point);
  mainPoints.push(point);
}

// ── Secondary 4-point star (NE, NW, SE, SW) ──
const secondaryPoints = [];
for (let i = 0; i < 4; i++) {
  const point = createCompassPoint(2.0, 0.3, 0.12);
  point.rotation.z = (Math.PI / 4) + (Math.PI / 2) * i;
  compass.add(point);
  secondaryPoints.push(point);
}

// ── Tertiary small points (16-point compass) ──
for (let i = 0; i < 8; i++) {
  const point = createCompassPoint(1.2, 0.18, 0.08);
  point.rotation.z = (Math.PI / 8) + (Math.PI / 4) * i;
  compass.add(point);
}

// ── Base ring (outer) ──
const outerRingGeo = new THREE.TorusGeometry(3.8, 0.12, 16, 64);
const outerRing = new THREE.Mesh(outerRingGeo, brassMaterial);
outerRing.rotation.x = Math.PI / 2;
outerRing.position.y = -0.01;
outerRing.castShadow = true;
compass.add(outerRing);

// ── Inner ring ──
const innerRingGeo = new THREE.TorusGeometry(2.5, 0.06, 12, 64);
const innerRing = new THREE.Mesh(innerRingGeo, darkBrassMaterial);
innerRing.rotation.x = Math.PI / 2;
innerRing.position.y = -0.02;
compass.add(innerRing);

// ── Decorative circle ring ──
const decoRingGeo = new THREE.TorusGeometry(1.5, 0.04, 8, 48);
const decoRing = new THREE.Mesh(decoRingGeo, darkBrassMaterial);
decoRing.rotation.x = Math.PI / 2;
decoRing.position.y = -0.03;
compass.add(decoRing);

// ── Base plate ──
const baseGeo = new THREE.CylinderGeometry(3.6, 3.6, 0.08, 64);
const base = new THREE.Mesh(baseGeo, darkBrassMaterial);
base.position.y = -0.08;
base.receiveShadow = true;
compass.add(base);

// ── Center knob ──
const knobGeo = new THREE.CylinderGeometry(0.35, 0.4, 0.25, 32);
const knob = new THREE.Mesh(knobGeo, brassMaterial);
knob.position.y = 0.05;
knob.castShadow = true;
compass.add(knob);

const knobTopGeo = new THREE.SphereGeometry(0.35, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
const knobTop = new THREE.Mesh(knobTopGeo, brassMaterial);
knobTop.position.y = 0.175;
knobTop.castShadow = true;
compass.add(knobTop);

// ── Tick marks around outer ring ──
for (let i = 0; i < 72; i++) {
  const angle = (i / 72) * Math.PI * 2;
  const isMain = i % 18 === 0;
  const isMid = i % 9 === 0;
  const tickLen = isMain ? 0.35 : isMid ? 0.2 : 0.1;
  const tickWidth = isMain ? 0.04 : 0.02;

  const tickGeo = new THREE.BoxGeometry(tickWidth, tickLen, 0.06);
  const tick = new THREE.Mesh(tickGeo, isMain ? brassMaterial : darkBrassMaterial);
  const r = 3.8;
  tick.position.set(
    Math.cos(angle) * r,
    0,
    Math.sin(angle) * r
  );
  tick.rotation.y = -angle;
  compass.add(tick);
}

// ── Cardinal direction labels (canvas textures on planes) ──
function createLabel(text, angle, radius, fontSize = 48) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = `bold ${fontSize}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  const isNorth = text === 'N';
  ctx.fillStyle = isNorth ? '#cc2222' : '#b8965a';
  ctx.shadowColor = 'rgba(0,0,0,0.5)';
  ctx.shadowBlur = 4;
  ctx.fillText(text, 64, 64);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const mat = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const planeGeo = new THREE.PlaneGeometry(0.8, 0.8);
  const mesh = new THREE.Mesh(planeGeo, mat);

  const r = radius;
  mesh.position.set(
    Math.cos(angle) * r,
    0.02,
    Math.sin(angle) * r
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.rotation.z = angle + Math.PI / 2;
  return mesh;
}

const labels = ['N', 'E', 'S', 'W'];
const labelAngles = [-Math.PI / 2, 0, Math.PI / 2, Math.PI];
labels.forEach((label, i) => {
  compass.add(createLabel(label, labelAngles[i], 4.6, 56));
});

// ── Subtle particle dust ──
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 30;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xb8965a,
  size: 0.03,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating rotation
  compass.rotation.z = Math.sin(t * 0.3) * 0.05;
  compass.rotation.x = Math.sin(t * 0.2) * 0.03 + 0.1;
  compass.position.y = Math.sin(t * 0.5) * 0.15;

  // Slow auto-rotate
  compass.rotation.y += 0.002;

  // Particles drift
  const pos = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    pos[i * 3 + 1] += Math.sin(t + i) * 0.0003;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

This creates a fully self-contained 3D brass compass rose with:

- **Brass material** — high metalness, warm gold tones, and environment reflections via a procedural `PMREMGenerator`
- **Multi-layered compass star** — 16 points (4 main cardinal, 4 intercardinal, 8 tertiary) all extruded with bevels for a real 3D machined look
- **Red north pointer** — classic compass styling with a distinct red accent
- **Decorative rings** — outer ring, inner ring, and a detail ring
- **72 tick marks** — major ticks at cardinal directions, mid ticks at intercardinal, and fine ticks between
- **Cardinal labels** (N, E, S, W) — rendered as canvas textures on planes, with N highlighted in red
- **Center knob** — domed brass pivot point
- **Ambient particles** — subtle floating golden dust
- **Gentle animation** — slow auto-rotation, subtle floating bob, and a slight tilt sway
- **OrbitControls** — drag to rotate, scroll to zoom
- **Rich lighting** — directional key/fill, rim

