const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0.1, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2.1;
controls.minDistance = 2;
controls.maxDistance = 12;

// --- Brass Material ---
const brassMat = new THREE.MeshPhysicalMaterial({
  color: 0xb5892a,
  metalness: 0.95,
  roughness: 0.25,
  clearcoat: 0.3,
  clearcoatRoughness: 0.15,
  envMapIntensity: 1.0,
});

const brassMatDark = new THREE.MeshPhysicalMaterial({
  color: 0x8a6a1a,
  metalness: 0.95,
  roughness: 0.35,
  clearcoat: 0.2,
  clearcoatRoughness: 0.2,
});

// --- Environment (simple procedural) ---
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.background = new THREE.Color(0x333333);
const envLight1 = new THREE.PointLight(0xffeedd, 3, 20);
envLight1.position.set(5, 5, 5);
envScene.add(envLight1);
const envLight2 = new THREE.PointLight(0x8899bb, 2, 20);
envLight2.position.set(-5, 3, -3);
envScene.add(envLight2);
const envRT = pmrem.fromScene(envScene);
scene.environment = envRT.texture;

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0x404050, 0.5);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xfff0dd, 3);
sunLight.position.set(5, 8, 3);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 1;
sunLight.shadow.camera.far = 20;
sunLight.shadow.camera.left = -5;
sunLight.shadow.camera.right = 5;
sunLight.shadow.camera.top = 5;
sunLight.shadow.camera.bottom = -5;
sunLight.shadow.bias = -0.001;
sunLight.shadow.radius = 4;
scene.add(sunLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 0.6);
fillLight.position.set(-3, 4, -4);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xffcc88, 1, 15);
rimLight.position.set(-2, 3, 3);
scene.add(rimLight);

// --- Sundial Group ---
const sundial = new THREE.Group();
scene.add(sundial);

// --- Dial Plate ---
const plateGeo = new THREE.CylinderGeometry(2, 2, 0.08, 128);
const plate = new THREE.Mesh(plateGeo, brassMat);
plate.receiveShadow = true;
plate.castShadow = true;
sundial.add(plate);

// Raised rim
const rimGeo = new THREE.TorusGeometry(1.95, 0.06, 16, 128);
const rim = new THREE.Mesh(rimGeo, brassMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.04;
rim.castShadow = true;
sundial.add(rim);

// Outer decorative ring
const outerRingGeo = new THREE.TorusGeometry(2.05, 0.03, 8, 128);
const outerRing = new THREE.Mesh(outerRingGeo, brassMatDark);
outerRing.rotation.x = Math.PI / 2;
outerRing.position.y = 0.04;
sundial.add(outerRing);

// --- Minute tick marks (60) ---
for (let i = 0; i < 60; i++) {
  const angle = (i / 60) * Math.PI * 2;
  const isHour = i % 5 === 0;
  const len = isHour ? 0.18 : 0.08;
  const w = isHour ? 0.03 : 0.012;
  const tickGeo = new THREE.BoxGeometry(w, 0.02, len);
  const tick = new THREE.Mesh(tickGeo, isHour ? brassMat : brassMatDark);

  const r = 1.85;
  tick.position.x = Math.sin(angle) * r;
  tick.position.z = Math.cos(angle) * r;
  tick.position.y = 0.05;
  tick.rotation.y = -angle;
  tick.castShadow = true;
  sundial.add(tick);
}

// --- Hour Numbers (canvas texture) ---
function createNumberTexture(num) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'transparent';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = 'bold 72px Georgia, serif';
  ctx.fillStyle = '#b5892a';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(num.toString(), 64, 64);
  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  return tex;
}

for (let i = 1; i <= 12; i++) {
  const angle = ((i - 3) / 12) * Math.PI * 2;
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'transparent';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = 'bold 72px Georgia, serif';
  ctx.fillStyle = '#b5892a';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(i.toString(), 64, 64);

  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.MeshBasicMaterial({
    map: tex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.45, 0.45), mat);
  const r = 1.45;
  plane.position.x = Math.sin(angle) * r;
  plane.position.z = Math.cos(angle) * r;
  plane.position.y = 0.045;
  plane.rotation.x = -Math.PI / 2;
  plane.rotation.z = -angle + Math.PI / 2;
  sundial.add(plane);
}

// --- Decorative inner ring ---
const innerRingGeo = new THREE.TorusGeometry(1.2, 0.015, 8, 64);
const innerRing = new THREE.Mesh(innerRingGeo, brassMat);
innerRing.rotation.x = Math.PI / 2;
innerRing.position.y = 0.042;
sundial.add(innerRing);

// --- Decorative cardinal direction markers ---
const directions = [
  { label: 'S', angle: 0 },
  { label: 'W', angle: Math.PI / 2 },
  { label: 'N', angle: Math.PI },
  { label: 'E', angle: -Math.PI / 2 },
];

directions.forEach(d => {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
