<script type="x-shader/x-vertex" id="marbleVert">
varying vec3 vNormal;
varying vec3 vWorldPosition;
varying vec3 vViewDir;
varying vec3 vPosition;
varying vec2 vUv;

void main() {
  vUv = uv;
  vPosition = position;
  vNormal = normalize(normalMatrix * normal);
  vec4 worldPos = modelMatrix * vec4(position, 1.0);
  vWorldPosition = worldPos.xyz;
  vViewDir = normalize(cameraPosition - worldPos.xyz);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
</script>

<script type="x-shader/x-fragment" id="marbleFrag">
uniform float uTime;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform vec3 uColor4;
uniform vec3 uEnvTop;
uniform vec3 uEnvBottom;
uniform float uRoughness;
uniform float uIor;
uniform float uFractureIntensity;

varying vec3 vNormal;
varying vec3 vWorldPosition;
varying vec3 vViewDir;
varying vec3 vPosition;
varying vec2 vUv;

// --- Simplex 3D noise ---
vec4 permute(vec4 x) { return mod(((x*34.0)+1.0)*x, 289.0); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

float snoise(vec3 v) {
  const vec2 C = vec2(1.0/6.0, 1.0/3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy;
  vec3 x3 = x0 - D.yyy;
  i = mod(i, 289.0);
  vec4 p = permute(permute(permute(
    i.z + vec4(0.0, i1.z, i2.z, 1.0))
  + i.y + vec4(0.0, i1.y, i2.y, 1.0))
  + i.x + vec4(0.0, i1.x, i2.x, 1.0));
  float n_ = 1.0/7.0;
  vec3 ns = n_ * D.wyz - D.xzx;
  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = x_ * ns.x + ns.yyyy;
  vec4 y = y_ * ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  vec4 m = max(0.6 - vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)), 0.0);
  m = m * m;
  return 42.0 * dot(m*m, vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
}

float fbm(vec3 p) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for(int i = 0; i < 5; i++) {
    val += amp * snoise(p * freq);
    freq *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Swirl pattern using layered noise
float swirl(vec3 p, float t) {
  float n1 = snoise(p * 2.0 + vec3(0.0, t * 0.1, 0.0));
  float n2 = snoise(p * 3.0 + vec3(n1 * 0.5, 0.0, t * 0.15));
  float n3 = snoise(p * 1.5 + vec3(0.0, n2 * 0.3, 0.0) + vec3(t * 0.05, 0.0, 0.0));

  // Spiral distortion
  float angle = atan(p.z, p.x);
  float radius = length(p.xz);
  float spiral = snoise(vec3(radius * 3.0 - angle * 1.5 + t * 0.2, p.y * 2.0, t * 0.05));

  return n1 * 0.35 + n2 * 0.25 + n3 * 0.2 + spiral * 0.2;
}

// Fracture pattern - branching cracks
float fracture(vec3 p, float intensity) {
  float cracks = 0.0;

  // Radial cracks from a point
  vec3 crackOrigin = vec3(0.3, 0.5, -0.2);
  vec3 dir = normalize(p - crackOrigin);

  // Primary fracture lines using hash-like noise
  float primary = snoise(p * 8.0 + crackOrigin * 2.0);
  float line1 = smoothstep(0.47, 0.50, primary) * smoothstep(0.53, 0.50, primary);

  // Secondary branching
  float secondary = snoise(p * 15.0 + crackOrigin * 3.0 + vec3(0.0, 0.0, 1.0));
  float line2 = smoothstep(0.48, 0.50, secondary) * smoothstep(0.52, 0.50, secondary);

  // Distance-based fade from crack origin
  float dist = length(p - crackOrigin);
  float fade = smoothstep(1.2, 0.0, dist);

  // Angular crack pattern
  float angle = atan(dir.y, length(dir.xz));
  float angularCracks = snoise(vec3(angle * 5.0, dist * 3.0, 0.0));
  float line3 = smoothstep(0.48, 0.50, angularCracks) * smoothstep(0.52, 0.50, angularCracks);

  // Combine fracture layers
  cracks += line1 * fade * 0.6;
  cracks += line2 * fade * 0.35 * step(0.3, dist) * step(dist, 0.9);
  cracks += line3 * fade * 0.25;

  // Additional random crack network
  float net = snoise(p * 12.0 + vec3(1.0, 2.0, 3.0));
  float netCracks = smoothstep(0.49, 0.50, net) * smoothstep(0.51, 0.50, net);
  cracks += netCracks * 0.15 * fade;

  return cracks * intensity;
}

// Fresnel-Schlick approximation
float fresnelSchlick(float cosTheta, vec3 F0) {
  return F0 + (1.0 - F0) * pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);
}

void main() {
  vec3 N = normalize(vNormal);
  vec3 V = normalize(vViewDir);

  // --- Refraction ---
  float ior = uIor;
  float ratio = 1.0 / ior;
  float cosTheta = clamp(dot(N, V), 0.0, 1.0);
  float sinTheta2 = 1.0 - cosTheta * cosTheta;
  float sinThetaT = ratio * sqrt(sinTheta2);
  float cosThetaT = sqrt(1.0 - sinThetaT * sinThetaT);

  // Refracted direction (simplified - pointing into sphere)
  vec3 refractDir = refract(V, N, ratio);

  // Sample internal swirl along refracted ray
  float t1 = 0.3;
  float t2 = 0.7;
  float t3 = 1.0;

  vec3 center = vec3(0.0);
  vec3 rayOrigin = vWorldPosition + N * 0.01;

  float s1 = swirl(rayOrigin + refractDir * t1, uTime);
  float s2 = swirl(rayOrigin + refractDir * t2, uTime);
  float s3 = swirl(rayOrigin + refractDir * t3, uTime);
  float sAvg = (s1 + s2 + s3) / 3.0;

  // Color mapping for swirls
  float t = sAvg * 0.5 + 0.5;
  vec3 swirlColor = mix(uColor1, uColor2, smoothstep(0.0, 0.33, t));
  swirlColor = mix(swirlColor, uColor3, smoothstep(0.33, 0.66, t));
  swirlColor = mix(swirlColor, uColor4, smoothstep(0.66, 1.0, t));

  // Add subtle brightness variation
  swirlColor *= 0.8 + 0.4 * fbm(vPosition * 4.0 + uTime * 0.05);

  // --- Fracture ---
