const brass = createBrassMaterial(0xb5882a, 0.22, 0.96);
const darkBrass = createBrassMaterial(0x8a6d1b, 0.3, 0.95);
const polishedBrass = createBrassMaterial(0xd4a843, 0.12, 0.98);
