}

// Back outer ring
const backOuterGeo = new THREE.CylinderGeometry(1.3, 1.15, 0.1, 64);
const backOuter = new THREE.Mesh(backOuterGeo, polishedBrass);
backOuter.position.y = -3.15;
filterGroup.add(backOuter);

// Decorative bands along the tube
const bandPositions = [-1.5, 0, 1.5];
bandPositions.forEach((y, idx) => {
  const bandGeo = new THREE.TorusGeometry(1.22, 0.08, 12, 64);
  const band = new THREE.Mesh(bandGeo, polishedBrass);
  band.rotation.x = Math.PI / 2;
