  const innerBand = new THREE.Mesh(innerBandGeo, darkBrass);
  innerBand.rotation.x = Math.PI / 2;
  innerBand.position.y = y;
  filterGroup.add(innerBand);
});

// Engraving-like ridges (small grooves around the tube)
for (let i = 0; i < 48; i++) {
