  dot.position.set(Math.cos(angle) * 0.9, 3.2, Math.sin(angle) * 0.9);
  filterGroup.add(dot);
}

// Central sun emblem
const sunEmblemGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.06, 32);
const sunEmblem = new THREE.Mesh(sunEmblemGeo, polishedBrass);
sunEmblem.position.y = 3.2;
filterGroup.add(sunEmblem);

// Sun rays on emblem
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const rayGeo = new THREE.BoxGeometry(0.04, 0.04, 0.25);
  const ray = new THREE.Mesh(rayGeo, polishedBrass);
  ray.position.set(Math.cos(angle) * 0.5, 3.23, Math.sin(angle) * 0.5);
  ray.rotation.y = -angle;
  filterGroup.add(ray);
}

// Position the filter at an angle
filterGroup.rotation.z = Math.PI / 6;
filterGroup.rotation.x = Math.PI / 8;

// Ground plane with subtle reflection
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
