function createSnowflakeGeometry(size = 1) {
  const shape = new THREE.Shape();
  const branches = 6;
  for (let i = 0; i < branches; i++) {
    const angle = (i / branches) * Math.PI * 2;
    const nextAngle = ((i + 0.5) / branches) * Math.PI * 2;
    const outerR = size;
    const midR = size * 0.55;
    const innerR = size * 0.35;

    if (i === 0) {
      shape.moveTo(Math.cos(angle) * innerR, Math.sin(angle) * innerR);
    }
    shape.lineTo(Math.cos(nextAngle - 0.15) * midR, Math.sin(nextAngle - 0.15) * midR);
    shape.lineTo(Math.cos((nextAngle - angle) * 0.3) * outerR, Math.sin((nextAngle - angle) * 0.3 + angle) * outerR);
    shape.lineTo(Math.cos(nextAngle - 0.05) * midR * 0.7, Math.sin(nextAngle - 0.05) * midR * 0.7);
    shape.lineTo(Math.cos(((i + 1) / branches) * Math.PI * 2) * innerR,
                 Math.sin(((i + 1) / branches) * Math.PI * 2) * innerR);
  }
  shape.closePath();

  const extrudeSettings = { depth: 0.02 * size, bevelEnabled: true, bevelThickness: 0.005 * size, bevelSize: 0.005 * size, bevelSegments: 1 };
  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

