    const branchCount = 3 + Math.floor(Math.random() * 3);
    const perBranch = Math.floor(count / (numTrees * branchCount));

    for (let b = 0; b < branchCount; b++) {
      const dir = new THREE.Vector3(
        (Math.random() - 0.5),
        Math.random() * 0.5 + 0.3,
        (Math.random() - 0.5)
      ).normalize();

      const branchLen = 0.3 + Math.random() * 0.8;
      const segments = perBranch + Math.floor(Math.random() * 3);

      for (let s = 0; s < segments; s++) {
        const t_param = s / segments;
        const pos = origin.clone().add(dir.clone().multiplyScalar(t_param * branchLen));

        // Add lateral branching
        const lateralBranch = Math.random() < 0.3;
        if (lateralBranch && t_param > 0.2 && t_param < 0.8) {
          const lateralDir = new THREE.Vector3(
            (Math.random() - 0.5),
            (Math.random() - 0.5) * 0.3,
