  // Gradient background
  const grad = ctx.createRadialGradient(size/2, size/3, 0, size/2, size/2, size);
  grad.addColorStop(0, '#1a1a3e');
  grad.addColorStop(0.5, '#0a0a20');
  grad.addColorStop(1, '#020208');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Bright spots for reflections
  const spots = [
    { x: 0.3, y: 0.2, r: 30, c: 'rgba(100,180,255,0.8)' },
    { x: 0.7, y: 0.3, r: 20, c: 'rgba(255,100,180,0.6)' },
    { x: 0.5, y: 0.7, r: 25, c: 'rgba(100,255,180,0.5)' },
    { x: 0.8, y: 0.8, r: 15, c: 'rgba(255,200,100,0.7)' },
    { x: 0.15, y: 0.6, r: 18, c: 'rgba(200,100,255,0.5)' },
  ];
  spots.forEach(s => {
    const g = ctx.createRadialGradient(s.x*size, s.y*size, 0, s.x*size, s.y*size, s.r);
    g.addColorStop(0, s.c);
    g.addColorStop(1, 'transparent');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);
  });

  const texture = new THREE.CanvasTexture(canvas);
  texture.mapping = THREE.EquirectangularReflectionMapping;
  return texture;
}

