        // Procedural Swirl Texture Generation
        function createSwirlTexture() {
            const size = 1024;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');

            // Base color
            ctx.fillStyle = '#f0f0f0';
            ctx.fillRect(0, 0, size, size);

            const cx = size / 2;
            const cy = size / 2;

            // Draw Swirl
            for (let i = 0; i < 4000; i++) {
                const angle = i * 0.03;
                const radius = i * 0.4;

                // Add some randomness to the spiral
                const jitter = (Math.random() - 0.5) * 20;

                const x = cx + Math.cos(angle) * (radius + jitter);
                const y = cy + Math.sin(angle) * (radius + jitter);

                ctx.beginPath();
                ctx.arc(x, y, 3 + Math.random() * 8, 0, Math.PI * 2);

                // Marble colors (Teal, Blue, Purple, White)
                const colors = ['#008080', '#4682B4', '#9370DB', '#E0FFFF', '#FFFFFF'];
                ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
                ctx.globalAlpha = 0.2 + Math.random() * 0.5;
                ctx.fill();
            }

            // Add grain/noise for texture
            for(let i = 0; i < 15000; i++) {
                ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.05})`;
                ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
