const arcStart = -arcAngle / 2;
const arcEnd = arcAngle / 2;

// ── Main Limb Arc (the brass plate) ──
function createLimbPlate() {
  const shape = new THREE.Shape();
  const segments = 128;

  // Outer arc
  for (let i = 0; i <= segments; i++) {
    const a = arcStart + (arcEnd - arcStart) * (i / segments);
    const x = outerRadius * Math.cos(a);
    const z = outerRadius * Math.sin(a);
    if (i === 0) shape.moveTo(x, z);
    else shape.lineTo(x, z);
  }

  // Inner arc (reverse)
  for (let i = segments; i >= 0; i--) {
    const a = arcStart + (arcEnd - arcStart) * (i / segments);
    const x = innerRadius * Math.cos(a);
    const z = innerRadius * Math.sin(a);
    shape.lineTo(x, z);
  }
  shape.closePath();

  const extrudeSettings = { depth: 0.15, bevelEnabled: true, bevelThickness: 0.03, bevelSize: 0.03, bevelSegments: 3 };
