        });
        const copperMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xb87333, 
            metalness: 0.7, 
            roughness: 0.4 
        });
        const darkMetalMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            metalness: 0.9, 
