            metalness: 0.0,
            roughness: 0.1,
            transmission: 0.9,
            thickness: 0.5
        });

        // --- Helper: Create Gear ---
        function createGear(radius, teeth, thickness, material) {
            const shape = new THREE.Shape();
            const innerRadius = radius * 0.8;
            const outerRadius = radius;
            const step = (Math.PI * 2) / teeth;

            for (let i = 0; i < teeth; i++) {
                const angle = i * step;
                // Tooth profile
                shape.lineTo(Math.cos(angle - step * 0.1) * outerRadius, Math.sin(angle - step * 0.1) * outerRadius);
                shape.lineTo(Math.cos(angle + step * 0.1) * outerRadius, Math.sin(angle + step * 0.1) * outerRadius);
                // Gap profile
                shape.lineTo(Math.cos(angle + step * 0.4) * innerRadius, Math.sin(angle + step * 0.4) * innerRadius);
                shape.lineTo(Math.cos(angle + step * 0.6) * innerRadius, Math.sin(angle + step * 0.6) * innerRadius);
            }

            // Center hole
            const holePath = new THREE.Path();
            holePath.absarc(0, 0, radius * 0.3, 0, Math.PI * 2, false);
            shape.holes.push(holePath);

            const extrudeSettings = { depth: thickness, bevelEnabled: true, bevelThickness: 0.05, bevelSize: 0.05, bevelSegments: 2 };
            const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            geometry.center(); // Center the geometry
