            ring.position.z = -0.5 - (i * 0.25);
            dragonflyGroup.add(ring);
        }

        // 2. Thorax
        const thoraxGeo = new THREE.SphereGeometry(0.35, 16, 16);
        const thorax = new THREE.Mesh(thoraxGeo, copperMaterial);
        thorax.position.z = 0.8;
        dragonflyGroup.add(thorax);

        // 3. Head
        const headGeo = new THREE.BoxGeometry(0.4, 0.3, 0.3);
        const head = new THREE.Mesh(headGeo, darkMetalMaterial);
        head.position.set(0, 0, 1.2);
        dragonflyGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, glassMaterial);
