        const wingGeo = new THREE.BoxGeometry(1.5, 0.02, 0.4);
        // Taper the wing slightly by modifying vertices (simple approach)
        const posAttribute = wingGeo.attributes.position;
        for (let i = 0; i < posAttribute.count; i++) {
            const x = posAttribute.getX(i);
            // Taper towards the tip (positive x)
            if (x > 0) {
                const y = posAttribute.getY(i);
                posAttribute.setY(i, y * (1 - x * 0.3));
            }
        }
        wingGeo.computeVertexNormals();

        const wingMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xaaddff, 
            metalness: 0.1, 
            roughness: 0.1, 
            transparent: true, 
            opacity: 0.6,
            side: THREE.DoubleSide
        });

        const wings = [];
        const wingPositions = [
            { x: 0.4, y: 0.1, z: 0.6, ry: 0.2 },   // Front Right
            { x: -0.4, y: 0.1, z: 0.6, ry: -0.2 }, // Front Left
            { x: 0.35, y: -0.1, z: 0.4, ry: 0.4 }, // Back Right
            { x: -0.35, y: -0.1, z: 0.4, ry: -0.4 } // Back Left
        ];

        wingPositions.forEach((pos, index) => {
            const wing = new THREE.Mesh(wingGeo, wingMaterial);
            wing.position.set(pos.x, pos.y, pos.z);
            wing.rotation.y = pos.ry;
            wing.rotation.x = -0.2; // Slight upward tilt
            dragonflyGroup.add(wing);
            wings.push(wing);
        });

        // 5. Gears (The "Mechanical" part)
        const gears = [];

        // Main drive gear on thorax
        const mainGear = createGear(0.25, 12, 0.1, brassMaterial);
        mainGear.position.set(0, 0.35, 0.8);
        mainGear.rotation.x = Math.PI / 2;
        dragonflyGroup.add(mainGear);
        gears.push({ mesh: mainGear, speed: 0.05 });

        // Secondary gears near wing joints
        const smallGearGeo = createGear(0.1, 8, 0.05, copperMaterial);

        const gear1 = smallGearGeo.clone();
        gear1.position.set(0.3, 0.2, 0.7);
        gear1.rotation.x = Math.PI / 2;
        dragonflyGroup.add(gear1);
        gears.push({ mesh: gear1, speed: -0.1 });

        const gear2 = smallGearGeo.clone();
        gear2.position.set(-0.3, 0.2, 0.7);
        gear2.rotation.x = Math.PI / 2;
        dragonflyGroup.add(gear2);
        gears.push({ mesh: gear2, speed: -0.1 });

        // Tail gears
        const tailGear = createGear(0.15, 10, 0.08, darkMetalMaterial);
        tailGear.position.set(0, 0, -1.5);
        tailGear.rotation.x = Math.PI / 2;
        dragonflyGroup.add(tailGear);
        gears.push({ mesh: tailGear, speed: 0.02 });

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate gears
            gears.forEach(g => {
                g.mesh.rotation.z += g.speed;
            });

            // Flap wings
            wings.forEach((wing, i) => {
                // Alternating flap pattern
                const offset = i % 2 === 0 ? 0 : Math.PI;
                wing.rotation.x = -0.2 + Math.sin(time * 15 + offset) * 0.3;
            });

            // Gentle hover movement
            dragonflyGroup.position.y = Math.sin(time * 2) * 0.2;
            dragonflyGroup.rotation.z = Math.sin(time * 1.5) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
