<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Glowing Mushroom Forest</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x020208);
scene.fog = new THREE.FogExp2(0x020208, 0.035);

const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 3, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post-Processing Bloom ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.5, 0.4, 0.2
);
composer.addPass(bloom);

// ── Ground ──
const groundGeo = new THREE.CircleGeometry(80, 64);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0a0a12, roughness: 0.95, metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.05;
scene.add(ground);

// ── Mushroom Colors ──
const colors = [
  0x00ffcc, 0xff00ff, 0x7b2fff, 0x00ff66,
  0xff6600, 0x00ccff, 0xff0066, 0x66ff00
];

// ── Mushroom Creation ──
function createMushroom(x, z) {
  const group = new THREE.Group();
  const color = colors[Math.floor(Math.random() * colors.length)];
  const scale = 0.4 + Math.random() * 1.2;

  // Stem
  const stemH = 0.5 + Math.random() * 1.5;
  const stemGeo = new THREE.CylinderGeometry(
    0.06 * scale, 0.1 * scale, stemH, 8
  );
  const stemMat = new THREE.MeshStandardMaterial({
    color: 0xddddcc, roughness: 0.8, emissive: color,
    emissiveIntensity: 0.05
  });
  const stem = new THREE.Mesh(stemGeo, stemMat);
  stem.position.y = stemH / 2;
  group.add(stem);

  // Cap
  const capGeo = new THREE.SphereGeometry(
    (0.3 + Math.random() * 0.3) * scale, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2
  );
  const capMat = new THREE.MeshStandardMaterial({
    color: color, roughness: 0.3, metalness: 0.2,
    emissive: color, emissiveIntensity: 1.5
  });
  const cap = new THREE.Mesh(capGeo, capMat);
  cap.position.y = stemH;
  group.add(cap);

  // Glow light
  const light = new THREE.PointLight(color, 2 * scale, 6 * scale, 2);
  light.position.y = stemH + 0.2;
  group.add(light);

  // Spots on cap
  for (let i = 0; i < 5; i++) {
    const spotGeo = new THREE.SphereGeometry(0.03 * scale, 6, 6);
    const spotMat = new THREE.MeshStandardMaterial({
      emissive: 0xffffff, emissiveIntensity: 2
    });
    const spot = new THREE.Mesh(spotGeo, spotMat);
    const angle = Math.random() * Math.PI * 2;
    const r = (Math.random() * 0.15) * scale;
    spot.position.set(
      Math.cos(angle) * r,
      stemH + 0.05 + Math.random() * 0.08,
      Math.sin(angle) * r
    );
    group.add(spot);
  }

  group.position.set(x, 0, z);
  group.rotation.y = Math.random() * Math.PI * 2;
  return group;
}

// Place mushrooms in clusters
const mushrooms = [];
for (let i = 0; i < 120; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = 2 + Math.random() * 30;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;
  const m = createMushroom(x, z);
  scene.add(m);
  mushrooms.push(m);
}

// ── Floating Spores ──
const sporeCount = 600;
const sporeGeo = new THREE.BufferGeometry();
const sporePos = new Float32Array(sporeCount * 3);
const sporeVel = [];
for (let i = 0; i < sporeCount; i++) {
  sporePos[i * 3] = (Math.random() - 0.5) * 50;
  sporePos[i * 3 + 1] = Math.random() * 8;
  sporePos[i * 3 + 2] = (Math.random() - 0.5) * 50;
  sporeVel.push({
    x: (Math.random() - 0.5) * 0.005,
    y: 0.002 + Math.random() * 0.008,
    z: (Math.random() - 0.5) * 0.005
  });
}
sporeGeo.setAttribute('position', new THREE.BufferAttribute(sporePos, 3));
const sporeMat = new THREE.PointsMaterial({
  color: 0xaaffcc, size: 0.08, transparent: true, opacity: 0.6,
  blending: THREE.AdditiveBlending, depthWrite: false
});
const spores = new THREE.Points(sporeGeo, sporeMat);
scene.add(spores);

// ── Ambient Light ──
scene.add(new THREE.AmbientLight(0x111122, 0.5));

// ── Camera Orbit ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle camera orbit
  camera.position.x = Math.sin(t * 0.1) * 14;
  camera.position.z = Math.cos(t * 0.1) * 14;
  camera.position.y = 3 + Math.sin(t * 0.15) * 1;
  camera.lookAt(0, 1.5, 0);

  // Animate spores
  const pos = spores.geometry.attributes.position.array;
  for (let i = 0; i < sporeCount; i++) {
    pos[i * 3] += sporeVel[i].x;
    pos[i * 3 + 1] += sporeVel[i].y;
    pos[i * 3 + 2] += sporeVel[i].z;
    if (pos[i * 3 + 1] > 9) pos[i * 3 + 1] = 0;
  }
  spores.geometry.attributes.position.needsUpdate = true;

  // Subtle mushroom pulse
  mushrooms.forEach((m, i) => {
    const pulse = 0.8 + Math.sin(t * 1.5 + i) * 0.2;
    m.children[1].material.emissiveIntensity = 1.2 * pulse;
    m.children[2].intensity = 2 * pulse;
  });

  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What this creates:**

- **120 procedural mushrooms** scattered across a dark forest floor with randomized sizes, heights, and colors (cyan, magenta, purple, green, orange, etc.)
- **Each mushroom** has a stem, a glowing dome cap, bright white spots on the cap, and its own `PointLight`
- **Unreal Bloom post-processing** makes everything glow beautifully
- **600 floating spore particles** drift upward with additive blending for a magical atmosphere
- **Exponential fog** fades distant mushrooms into the darkness
- **Gentle camera orbit** slowly circles the forest
- **Pulsing glow** — mushrooms subtly breathe with varying emissive intensity
- **Responsive** — handles window resizing

