function createCompassTexture(size = 2048) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const cx = size / 2, cy = size / 2, r = size / 2 - 20;

  // Background - dark antique brass
  const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  bg.addColorStop(0, '#c9a84c');
  bg.addColorStop(0.3, '#b8943a');
  bg.addColorStop(0.7, '#a67c2e');
  bg.addColorStop(1, '#8a6620');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, size, size);

  // Subtle radial brushed metal lines
  ctx.save();
  ctx.globalAlpha = 0.04;
  for (let a = 0; a < 360; a += 0.5) {
    const rad = a * Math.PI / 180;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(rad) * r, cy + Math.sin(rad) * r);
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
  ctx.restore();

  // Concentric rings
  ctx.lineWidth = 2;
  for (let i = 1; i <= 6; i++) {
    const ringR = r * (i / 7);
    ctx.beginPath();
    ctx.arc(cx, cy, ringR, 0, Math.PI * 2);
    ctx.strokeStyle = i === 6 ? 'rgba(60,40,10,0.7)' : 'rgba(60,40,10,0.25)';
    ctx.lineWidth = i === 6 ? 3 : 1;
    ctx.stroke();
  }

  // Outer ring fill
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.97, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(80,55,15,0.3)';
  ctx.fill();

  // Degree markings
  for (let deg = 0; deg < 360; deg += 1) {
    const rad = (deg - 90) * Math.PI / 180;
    const isCardinal = deg % 90 === 0;
    const isIntercard = deg % 45 === 0;
    const isMajor = deg % 10 === 0;
    const isMinor = deg % 5 === 0;

    let len, width, alpha;
    if (isCardinal) { len = 40; width = 3; alpha = 1; }
    else if (isIntercard) { len = 30; width = 2.5; alpha = 0.9; }
    else if (isMajor) { len = 22; width = 2; alpha = 0.7; }
    else if (isMinor) { len = 15; width = 1.5; alpha = 0.5; }
    else { len = 10; width = 1; alpha = 0.35; }

    const outerR = r * 0.93;
    const innerR = outerR - len;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(rad) * innerR, cy + Math.sin(rad) * innerR);
    ctx.lineTo(cx + Math.cos(rad) * outerR, cy + Math.sin(rad) * outerR);
    ctx.strokeStyle = `rgba(50,30,5,${alpha})`;
    ctx.lineWidth = width;
    ctx.stroke();
  }

  // Degree numbers (every 10°)
  ctx.fillStyle = 'rgba(40,25,5,0.85)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (let deg = 0; deg < 360; deg += 10) {
    if (deg % 45 === 0) continue;
    const rad = (deg - 90) * Math.PI / 180;
    const numR = r * 0.82;
    ctx.font = `${size * 0.022}px Georgia, serif`;
    ctx.fillText(deg.toString(), cx + Math.cos(rad) * numR, cy + Math.sin(rad) * numR);
  }

  // Cardinal & intercardinal letters
  const dirs = [
    { label: 'N', deg: 0, size: 0.09, bold: true },
    { label: 'NE', deg: 45, size: 0.045, bold: false },
    { label: 'E', deg: 90, size: 0.065, bold: true },
    { label: 'SE', deg: 135, size: 0.045, bold: false },
    { label: 'S', deg: 180, size: 0.065, bold: true },
    { label: 'SW', deg: 225, size: 0.045, bold: false },
    { label: 'W', deg: 270, size: 0.065, bold: true },
    { label: 'NW', deg: 315, size: 0.045, bold: false },
  ];

  dirs.forEach(d => {
    const rad = (d.deg - 90) * Math.PI / 180;
    const textR = r * (d.bold ? 0.68 : 0.72);
    const fontSize = size * d.size;
    ctx.font = `${d.bold ? 'bold ' : ''}${fontSize}px Georgia, "Times New Roman", serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Shadow / emboss effect
    ctx.fillStyle = 'rgba(180,150,60,0.5)';
    ctx.fillText(d.label, cx + Math.cos(rad) * textR + 2, cy + Math.sin(rad) * textR + 2);

    ctx.fillStyle = 'rgba(35,20,5,0.95)';
    ctx.fillText(d.label, cx + Math.cos(rad) * textR, cy + Math.sin(rad) * textR);

    // Highlight
    ctx.fillStyle = 'rgba(200,170,80,0.3)';
    ctx.fillText(d.label, cx + Math.cos(rad) * textR - 1, cy + Math.sin(rad) * textR - 1);
  });

  // Compass rose star
  ctx.save();
  for (let i = 0; i < 8; i++) {
    const angle = (i * 45) * Math.PI / 180;
    const isCardinal = i % 2 === 0;
    const outerLen = r * (isCardinal ? 0.55 : 0.35);
    const innerLen = r * 0.08;
    const halfW = r * (isCardinal ? 0.06 : 0.04);

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);

    // Shadow
    ctx.fillStyle = 'rgba(40,25,8,0.3)';
    ctx.beginPath();
    ctx.moveTo(0, -outerLen + 3);
    ctx.lineTo(halfW + 1, -innerLen + 3);
    ctx.lineTo(0, -innerLen * 0.3 + 3);
    ctx.lineTo(-halfW - 1, -innerLen + 3);
    ctx.closePath();
    ctx.fill();

    // Main pointer
    const grad = ctx.createLinearGradient(0, -outerLen, 0, -innerLen);
    grad.addColorStop(0, '#5a3d15');
    grad.addColorStop(1, '#3d2810');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(0, -outerLen);
    ctx.lineTo(halfW, -innerLen);
    ctx.lineTo(0, -innerLen * 0.3);
    ctx.lineTo(-halfW, -innerLen);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(200,160,60,0.4)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();

  // Center circle
  const centerGrad = ctx.createRadialGradient(cx - 10, cy - 10, 0, cx, cy, r * 0.07);
  centerGrad.addColorStop(0, '#d4b055');
  centerGrad.addColorStop(1, '#8a6620');
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.07, 0, Math.PI * 2);
  ctx.fillStyle = centerGrad;
  ctx.fill();
  ctx.strokeStyle = 'rgba(40,25,5,0.6)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Decorative outer bevel
  const bevelGrad = ctx.createRadialGradient(cx, cy, r * 0.85, cx, cy, r * 0.98);
  bevelGrad.addColorStop(0, 'rgba(180,140,50,0.5)');
  bevelGrad.addColorStop(0.5, 'rgba(100,70,20,0.3)');
  bevelGrad.addColorStop(1, 'rgba(60,40,10,0.6)');
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.98, 0, Math.PI * 2);
  ctx.arc(cx, cy, r * 0.85, 0, Math.PI * 2, true);
  ctx.fillStyle = bevelGrad;
  ctx.fill();

  // Vignette darkening at edges
  const vig = ctx.createRadialGradient(cx, cy, r * 0.6, cx, cy, r);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(0,0,0,0.25)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, size, size);

  return canvas;
}

