<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Lantern with Fireflies</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #0a0a12; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
    "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a12, 0.06);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.2, 5);
camera.lookAt(0, 0.5, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Lantern Body (lathe profile) ──
const profile = [];
const pts = [
  [0.0, -1.0], [0.35, -1.0], [0.6, -0.85], [0.72, -0.6],
  [0.75, -0.3], [0.76, 0.0], [0.75, 0.3], [0.72, 0.6],
  [0.6, 0.85], [0.35, 1.0], [0.0, 1.0]
];
pts.forEach(p => profile.push(new THREE.Vector2(p[0], p[1])));

const bodyGeo = new THREE.LatheGeometry(profile, 24);
const bodyMat = new THREE.MeshStandardMaterial({
  color: 0xfff0d0,
  emissive: 0xffaa33,
  emissiveIntensity: 0.6,
  transparent: true,
  opacity: 0.35,
  side: THREE.DoubleSide,
  roughness: 0.9,
  metalness: 0.0,
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
scene.add(body);

// ── Ribs (vertical lines) ──
const ribGeo = new THREE.CylinderGeometry(0.008, 0.008, 2.0, 6);
const ribMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1a, roughness: 0.8 });
for (let i = 0; i < 12; i++) {
  const angle = (i / 12) * Math.PI * 2;
  const rib = new THREE.Mesh(ribGeo, ribMat);
  rib.position.y = 0;
  rib.rotation.y = angle;
  rib.position.x = Math.sin(angle) * 0.68;
  rib.position.z = Math.cos(angle) * 0.68;
  // Tilt ribs slightly outward at top
  rib.rotation.z = 0;
  scene.add(rib);
}

// ── Top & Bottom Rings ──
const ringGeo = new THREE.TorusGeometry(0.36, 0.03, 8, 32);
const ringMat = new THREE.MeshStandardMaterial({ color: 0x2a1a0a, roughness: 0.5, metalness: 0.6 });
const topRing = new THREE.Mesh(ringGeo, ringMat);
topRing.position.y = 1.0;
topRing.rotation.x = Math.PI / 2;
scene.add(topRing);

const bottomRing = new THREE.Mesh(ringGeo, ringMat);
bottomRing.position.y = -1.0;
bottomRing.rotation.x = Math.PI / 2;
scene.add(bottomRing);

// ── Middle Band ──
const bandGeo = new THREE.TorusGeometry(0.76, 0.02, 8, 32);
const band = new THREE.Mesh(bandGeo, ringMat);
band.rotation.x = Math.PI / 2;
scene.add(band);

// ── Handle ──
const handleCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 1.0, 0),
  new THREE.Vector3(0, 1.5, 0),
  new THREE.Vector3(0, 1.8, 0.15),
  new THREE.Vector3(0, 1.8, 0.3),
]);
const handleGeo = new THREE.TubeGeometry(handleCurve, 16, 0.025, 8, false);
const handle = new THREE.Mesh(handleGeo, ringMat);
scene.add(handle);

// Mirror handle
const handleCurve2 = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 1.0, 0),
  new THREE.Vector3(0, 1.5, 0),
  new THREE.Vector3(0, 1.8, -0.15),
  new THREE.Vector3(0, 1.8, -0.3),
]);
const handle2 = new THREE.Mesh(new THREE.TubeGeometry(handleCurve2, 16, 0.025, 8, false), ringMat);
scene.add(handle2);

// ── Bottom Cap ──
const capGeo = new THREE.CylinderGeometry(0.06, 0.12, 0.15, 12);
const cap = new THREE.Mesh(capGeo, ringMat);
cap.position.y = -1.075;
scene.add(cap);

// ── Inner Glow Light ──
const glowLight = new THREE.PointLight(0xff9933, 3, 8, 1.5);
glowLight.position.set(0, 0, 0);
scene.add(glowLight);

const ambientLight = new THREE.AmbientLight(0x1a1a2e, 0.4);
scene.add(ambientLight);

// ── Fireflies ──
const fireflyCount = 18;
const fireflies = [];
const fireflyGeo = new THREE.SphereGeometry(0.025, 8, 8);

for (let i = 0; i < fireflyCount; i++) {
  const hue = 0.12 + Math.random() * 0.12; // warm yellow-green range
  const color = new THREE.Color().setHSL(hue, 1, 0.6);

  const mat = new THREE.MeshStandardMaterial({
    color: color,
    emissive: color,
    emissiveIntensity: 2.0,
    transparent: true,
    opacity: 0.9,
  });

  const mesh = new THREE.Mesh(fireflyGeo, mat);

  // Random position inside lantern
  const angle = Math.random() * Math.PI * 2;
  const r = Math.random() * 0.5;
  const y = (Math.random() - 0.5) * 1.6;
  mesh.position.set(Math.cos(angle) * r, y, Math.sin(angle) * r);

  // Small point light per firefly (only some, for performance)
  let light = null;
  if (i < 8) {
    light = new THREE.PointLight(color, 0.4, 1.5, 2);
    mesh.add(light);
  }

  scene.add(mesh);

  fireflies.push({
    mesh,
    light,
    basePos: mesh.position.clone(),
    phase: Math.random() * Math.PI * 2,
    speed: 0.3 + Math.random() * 0.5,
    radius: 0.05 + Math.random() * 0.2,
    flickerSpeed: 2 + Math.random() * 4,
    flickerPhase: Math.random() * Math.PI * 2,
    hue,
  });
}

// ── Outer Dust Particles ──
const dustCount = 300;
const dustGeo = new THREE.BufferGeometry();
const dustPos = new Float32Array(dustCount * 3);
for (let i = 0; i < dustCount; i++) {
  dustPos[i * 3] = (Math.random() - 0.5) * 20;
  dustPos[i * 3 + 1] = (Math.random() - 0.5) * 10;
  dustPos[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0xffcc88,
  size: 0.03,
  transparent: true,
  opacity: 0.3,
  sizeAttenuation: true,
});
const dust = new THREE.Points(dustGeo, dustMat);
scene.add(dust);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Lantern gentle sway
  body.rotation.y = Math.sin(t * 0.3) * 0.05;
  body.position.y = Math.sin(t * 0.5) * 0.03;

  // Glow flicker
  glowLight.intensity = 3 + Math.sin(t * 3) * 0.3 + Math.sin(t * 7) * 0.15;
  bodyMat.emissiveIntensity = 0.6 + Math.sin(t * 3) * 0.1 + Math.sin(t * 5) * 0.05;

  // Fireflies
  fireflies.forEach(f => {
    const { mesh, basePos, phase, speed, radius, flickerSpeed, flickerPhase } = f;

    // Organic floating motion
    mesh.position.x = basePos.x + Math.sin(t * speed + phase) * radius;
    mesh.position.y = basePos.y + Math.sin(t * speed * 0.7 + phase + 1) * radius * 0.6;
    mesh.position.z = basePos.z + Math.cos(t * speed * 0.8 + phase + 2) * radius;

    // Clamp inside lantern
    const dist = Math.sqrt(mesh.position.x ** 2 + mesh.position.z ** 2);
    if (dist > 0.65) {
      const scale = 0.65 / dist;
      mesh.position.x *= scale;
      mesh.position.z *= scale;
    }
    mesh.position.y = THREE.MathUtils.clamp(mesh.position.y, -0.9, 0.9);

    // Flicker
    const flicker = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(t * flickerSpeed + flickerPhase));
    mesh.material.emissiveIntensity = flicker * 2.5;
    mesh.material.opacity = flicker * 0.9;
    const s = 0.8 + flicker * 0.4;
    mesh.scale.setScalar(s);

    if (f.light) f.light.intensity = flicker * 0.5;
  });

  // Dust drift
  const positions = dust.geometry.attributes.position.array;
  for (let i = 0; i < dustCount; i++) {
    positions[i * 3 + 1] += Math.sin(t + i) * 0.0003;
  }
  dust.geometry.attributes.position.needsUpdate = true;
  dust.rotation.y = t * 0.01;

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
