<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Phoenix Rising</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
        #info {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: #ffaa00;
            font-family: 'Courier New', Courier, monospace;
            font-size: 14px;
            pointer-events: none;
            text-shadow: 0 0 5px #ff4400;
        }
    </style>
</head>
<body>
    <div id="info">✦ Phoenix Rising ✦</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // Texture Generation for Particles
        function createParticleTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 32;
            canvas.height = 32;
            const ctx = canvas.getContext('2d');
            const gradient = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
            gradient.addColorStop(0.2, 'rgba(255, 200, 50, 1)');
            gradient.addColorStop(0.5, 'rgba(255, 100, 0, 0.5)');
            gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, 32, 32);
            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        const particleTexture = createParticleTexture();

        // --- Phoenix Particle System ---
        const phoenixCount = 3000;
        const phoenixGeometry = new THREE.BufferGeometry();
        const phoenixPositions = new Float32Array(phoenixCount * 3);
        const phoenixColors = new Float32Array(phoenixCount * 3);
        const phoenixSizes = new Float32Array(phoenixCount);
        const phoenixVelocities = []; // Store velocity for animation

        const color1 = new THREE.Color(0xff2200); // Red
        const color2 = new THREE.Color(0xffaa00); // Orange
        const color3 = new THREE.Color(0xffff00); // Yellow

        // Helper to generate bird shape points
        function getPhoenixPoint() {
            const type = Math.random();
            let x, y, z;

            if (type < 0.3) {
                // Body
                x = (Math.random() - 0.5) * 0.6;
                y = (Math.random() - 0.5) * 1.5;
                z = (Math.random() - 0.5) * 0.6;
            } else if (type < 0.6) {
                // Left Wing
                const wingY = (Math.random() - 0.5) * 1.0;
                const wingX = Math.random() * 2.5 + 0.5;
                const wingZ = (Math.random() - 0.5) * 0.8;
                // Curve the wing up
                y = wingY + (wingX * 0.3); 
                x = -wingX;
                z = wingZ;
            } else if (type < 0.9) {
                // Right Wing
                const wingY = (Math.random() - 0.5) * 1.0;
                const wingX = Math.random() * 2.5 + 0.5;
                const wingZ = (Math.random() - 0.5) * 0.8;
                y = wingY + (wingX * 0.3);
                x = wingX;
                z = wingZ;
            } else {
                // Tail
                x = (Math.random() - 0.5) * 0.8;
                y = -Math.random() * 1.5 - 0.5;
                z = (Math.random() - 0.5) * 0.8;
            }
            return { x, y, z };
        }

        for (let i = 0; i < phoenixCount; i++) {
            const point = getPhoenixPoint();
            phoenixPositions[i * 3] = point.x;
            phoenixPositions[i * 3 + 1] = point.y;
            phoenixPositions[i * 3 + 2] = point.z;

            // Color gradient based on height
            const mixedColor = color1.clone().lerp(color2, Math.random());
            if (Math.random() > 0.8) mixedColor.lerp(color3, 0.5);

            phoenixColors[i * 3] = mixedColor.r;
            phoenixColors[i * 3 + 1] = mixedColor.g;
            phoenixColors[i * 3 + 2] = mixedColor.b;

            phoenixSizes[i] = Math.random() * 0.3 + 0.1;

            phoenixVelocities.push({
                x: (Math.random() - 0.5) * 0.01,
                y: (Math.random() * 0.02) + 0.01, // Rising
                z: (Math.random() - 0.5) * 0.01,
                originalY: point.y,
                phase: Math.random() * Math.PI * 2
            });
        }

        phoenixGeometry.setAttribute('position', new THREE.BufferAttribute(phoenixPositions, 3));
        phoenixGeometry.setAttribute('color', new THREE.BufferAttribute(phoenixColors, 3));
        phoenixGeometry.setAttribute('size', new THREE.BufferAttribute(phoenixSizes, 1));

        const phoenixMaterial = new THREE.PointsMaterial({
            size: 0.2,
            map: particleTexture,
            vertexColors: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            transparent: true,
            opacity: 0.8
        });

        const phoenix = new THREE.Points(phoenixGeometry, phoenixMaterial);
        scene.add(phoenix);

        // --- Flames Particle System (Background) ---
        const flameCount = 1500;
        const flameGeometry = new THREE.BufferGeometry();
        const flamePositions = new Float32Array(flameCount * 3);
        const flameColors = new Float32Array(flameCount * 3);
        const flameVelocities = [];

        for (let i = 0; i < flameCount; i++) {
            flamePositions[i * 3] = (Math.random() - 0.5) * 6; // Spread wide
            flamePositions[i * 3 + 1] = -5 + Math.random() * 2; // Start low
            flamePositions[i * 3 + 2] = (Math.random() - 0.5) * 4;

            const color = color1.clone().lerp(color2, Math.random());
            flameColors[i * 3] = color.r;
            flameColors[i * 3 + 1] = color.g;
            flameColors[i * 3 + 2] = color.b;

            flameVelocities.push({
                y: Math.random() * 0.05 + 0.02,
                x: (Math.random() - 0.5) * 0.02,
                z: (Math.random() - 0.5) * 0.02
            });
        }

        flameGeometry.setAttribute('position', new THREE.BufferAttribute(flamePositions, 3));
        flameGeometry.setAttribute('color', new THREE.BufferAttribute(flameColors, 3));

        const flameMaterial = new THREE.PointsMaterial({
            size: 0.4,
            map: particleTexture,
            vertexColors: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            transparent: true,
            opacity: 0.6
        });

        const flames = new THREE.Points(flameGeometry, flameMaterial);
        scene.add(flames);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Animate Phoenix
            const positions = phoenixGeometry.attributes.position.array;
            for (let i = 0; i < phoenixCount; i++) {
                const vel = phoenixVelocities[i];

                // Add some noise/wobble
                positions[i * 3] += Math.sin(time * 2 + vel.phase) * 0.005;
                positions[i * 3 + 1] += vel.y * 0.5; // Rise slowly
                positions[i * 3 + 2] += Math.cos(time * 2 + vel.phase) * 0.005;

                // Reset if too high (looping rise)
                if (positions[i * 3 + 1] > vel.originalY + 2) {
                    positions[i * 3 + 1] = vel.originalY - 2;
                }
            }
            phoenixGeometry.attributes.position.needsUpdate = true;

            // Rotate Phoenix slightly
            phoenix.rotation.y = Math.sin(time * 0.5) * 0.2;
            phoenix.rotation.z = Math.sin(time * 0.3) * 0.1;

            // Animate Flames
            const fPositions = flameGeometry.attributes.position.array;
            for (let i = 0; i < flameCount; i++) {
                const vel = flameVelocities[i];
                fPositions[i * 3] += vel.x;
                fPositions[i * 3 + 1] += vel.y;
                fPositions[i * 3 + 2] += vel.z;

                // Reset if too high
                if (fPositions[i * 3 + 1] > 5) {
                    fPositions[i * 3] = (Math.random() - 0.5) * 6;
                    fPositions[i * 3 + 1] = -5;
                    fPositions[i * 3 + 2] = (Math.random() - 0.5) * 4;
                }
            }
            flameGeometry.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
