        const beetle = new THREE.Group();

        // Abdomen
        const abdomenGeo = new THREE.CapsuleGeometry(1.5, 3, 4, 16);
        const abdomen = new THREE.Mesh(abdomenGeo, metalMaterial);
        abdomen.rotation.x = Math.PI / 2;
        abdomen.position.z = -1.5;
        abdomen.castShadow = true;
        beetle.add(abdomen);

        // Abdomen Segments (Ribs)
        for(let i=0; i<3; i++) {
            const ribGeo = new THREE.TorusGeometry(1.52, 0.1, 8, 16);
            const rib = new THREE.Mesh(ribGeo, darkMetalMaterial);
            rib.position.z = -0.5 - (i * 1);
            beetle.add(rib);
        }

        // Thorax
        const thoraxGeo = new THREE.BoxGeometry(2.5, 1.5, 2);
        const thorax = new THREE.Mesh(thoraxGeo, metalMaterial);
        thorax.position.z = 1.5;
        thorax.castShadow = true;
        beetle.add(thorax);

        // Head
        const headGeo = new THREE.SphereGeometry(1, 16, 16);
        const head = new THREE.Mesh(headGeo, darkMetalMaterial);
        head.scale.set(1, 0.8, 1.2);
        head.position.z = 3.2;
        head.castShadow = true;
        beetle.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.3, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, redGlowMaterial);
        leftEye.position.set(-0.6, 0.2, 4);
        beetle.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, redGlowMaterial);
        rightEye.position.set(0.6, 0.2, 4);
        beetle.add(rightEye);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.05, 0.02, 2, 8);
        const leftAntenna = new THREE.Mesh(antennaGeo, metalMaterial);
        leftAntenna.position.set(-0.8, 0.5, 4.5);
        leftAntenna.rotation.set(0.5, 0, -0.5);
        beetle.add(leftAntenna);

        const rightAntenna = new THREE.Mesh(antennaGeo, metalMaterial);
        rightAntenna.position.set(0.8, 0.5, 4.5);
        rightAntenna.rotation.set(0.5, 0, 0.5);
        beetle.add(rightAntenna);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.1, 0.05, 2.5, 8);
        const legPositions = [
            { x: -1.2, z: 2.5, rotZ: 0.5, rotX: 0.2 },
            { x: 1.2, z: 2.5, rotZ: -0.5, rotX: 0.2 },
            { x: -1.5, z: 0, rotZ: 0.8, rotX: 0 },
            { x: 1.5, z: 0, rotZ: -0.8, rotX: 0 },
            { x: -1.2, z: -2, rotZ: 0.5, rotX: -0.2 },
            { x: 1.2, z: -2, rotZ: -0.5, rotX: -0.2 },
        ];

        const legs = [];
        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, metalMaterial);
            leg.position.set(pos.x, -1, pos.z);
            leg.rotation.set(pos.rotX, 0, pos.rotZ);
            leg.castShadow = true;
            beetle.add(leg);
            legs.push(leg);
        });

        // Cybernetic Core (Glowing center)
        const coreGeo = new THREE.OctahedronGeometry(0.5, 0);
        const core = new THREE.Mesh(coreGeo, glowMaterial);
        core.position.set(0, 0, 1.5);
        beetle.add(core);

        scene.add(beetle);

        // Floor Grid
        const gridHelper = new THREE.GridHelper(50, 50, 0x00ffcc, 0x111111);
        gridHelper.position.y = -3;
        scene.add(gridHelper);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Hover effect
            beetle.position.y = Math.sin(time * 2) * 0.5;
            beetle.rotation.z = Math.sin(time * 1.5) * 0.05;
            beetle.rotation.x = Math.sin(time * 1.2) * 0.05;

            // Leg movement
            legs.forEach((leg, index) => {
                const offset = index * 1.5;
                leg.rotation.x += Math.sin(time * 10 + offset) * 0.002;
            });

            // Core pulse
            core.scale.setScalar(1 + Math.sin(time * 5) * 0.1);
            core.rotation.y += 0.05;

            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
