        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xffffff, 0.8);
        pointLight.position.set(-5, 2, -5);
        scene.add(pointLight);

        // Materials
        const silverMaterial = new THREE.MeshStandardMaterial({
            color: 0xcccccc,
            metalness: 0.9,
            roughness: 0.2,
        });

        const darkSilverMaterial = new THREE.MeshStandardMaterial({
            color: 0x888888,
            metalness: 0.8,
            roughness: 0.3,
        });

        const faceMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.5,
        });

        // Group for the whole watch
        const watchGroup = new THREE.Group();
        scene.add(watchGroup);

        // 1. Watch Body (Cylinder)
        const bodyGeometry = new THREE.CylinderGeometry(1.2, 1.2, 0.3, 64);
        const body = new THREE.Mesh(bodyGeometry, silverMaterial);
        body.rotation.x = Math.PI / 2; // Face forward
        body.castShadow = true;
        body.receiveShadow = true;
        watchGroup.add(body);

        // 2. Watch Face (Circle)
        const faceGeometry = new THREE.CircleGeometry(1.05, 64);
        const face = new THREE.Mesh(faceGeometry, faceMaterial);
        face.position.z = 0.16; // Slightly in front of body
        watchGroup.add(face);

        // 3. Watch Rim (Torus)
        const rimGeometry = new THREE.TorusGeometry(1.05, 0.05, 16, 100);
        const rim = new THREE.Mesh(rimGeometry, silverMaterial);
        rim.position.z = 0.15;
        watchGroup.add(rim);

        // 4. Hands
        const handMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.5, roughness: 0.5 });

        // Hour Hand
        const hourHandGeo = new THREE.BoxGeometry(0.1, 0.6, 0.05);
        const hourHand = new THREE.Mesh(hourHandGeo, handMaterial);
        hourHand.position.set(0, 0.2, 0.2);
        hourHand.rotation.z = -Math.PI / 6; // 1 o'clock
        watchGroup.add(hourHand);

        // Minute Hand
        const minuteHandGeo = new THREE.BoxGeometry(0.06, 0.9, 0.05);
        const minuteHand = new THREE.Mesh(minuteHandGeo, handMaterial);
        minuteHand.position.set(0, 0.3, 0.22);
        minuteHand.rotation.z = Math.PI / 3; // 10 o'clock
        watchGroup.add(minuteHand);

        // Center Pin
        const pinGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.1, 16);
        const pin = new THREE.Mesh(pinGeo, silverMaterial);
        pin.rotation.x = Math.PI / 2;
        pin.position.z = 0.25;
        watchGroup.add(pin);

        // 5. Crown / Loop
        const loopGeo = new THREE.TorusGeometry(0.2, 0.05, 16, 32, Math.PI);
        const loop = new THREE.Mesh(loopGeo, silverMaterial);
        loop.position.set(0, 1.3, 0);
        loop.rotation.z = Math.PI; // Open upwards
        watchGroup.add(loop);

        const crownGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.3, 16);
        const crown = new THREE.Mesh(crownGeo, silverMaterial);
        crown.position.set(0, 1.1, 0);
        watchGroup.add(crown);

        // 6. Wings
        function createWing(side) {
            const wingGroup = new THREE.Group();

            // Main wing shape using a custom shape
            const shape = new THREE.Shape();
            shape.moveTo(0, 0);
            shape.quadraticCurveTo(0.5, 0.5, 1.5, 1.5); // Top curve
            shape.quadraticCurveTo(1.0, 1.0, 0.5, 0.8); // Inner curve top
            shape.quadraticCurveTo(0.2, 0.5, 0, 0);     // Inner curve bottom

            const extrudeSettings = {
                steps: 1,
                depth: 0.05,
                bevelEnabled: true,
                bevelThickness: 0.02,
                bevelSize: 0.02,
                bevelSegments: 2
            };

            const wingGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            const wing = new THREE.Mesh(wingGeo, silverMaterial);

            wing.castShadow = true;
            wing.receiveShadow = true;

            // Position and rotate wing
            wing.position.set(side * 1.0, -0.5, -0.05);
            wing.rotation.z = side * 0.5; // Angle outwards
            wing.rotation.y = side * 0.2; // Slight twist

            // Scale if needed
            wing.scale.set(1.2, 1.2, 1);

            wingGroup.add(wing);
            return wingGroup;
        }

        const leftWing = createWing(-1);
        const rightWing = createWing(1);
        watchGroup.add(leftWing);
        watchGroup.add(rightWing);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle floating animation
            watchGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Gentle rotation
            watchGroup.rotation.y = Math.sin(time * 0.3) * 0.1;

            // Wing flapping (subtle)
            leftWing.rotation.z = -0.5 + Math.sin(time * 2) * 0.1;
            rightWing.rotation.z = 0.5 - Math.sin(time * 2) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
