    <div id="info">桜 — 兜 — 武士道</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 6);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeebb, 2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const rimLight = new THREE.SpotLight(0x4455ff, 5);
        rimLight.position.set(-5, 5, -5);
        rimLight.lookAt(0, 0, 0);
        scene.add(rimLight);

        // Materials
        const helmetMaterial = new THREE.MeshStandardMaterial({
            color: 0x1a1a1a,
            roughness: 0.3,
            metalness: 0.8,
        });

        const redAccentMaterial = new THREE.MeshStandardMaterial({
            color: 0x880000,
            roughness: 0.5,
            metalness: 0.2,
        });

        const goldAccentMaterial = new THREE.MeshStandardMaterial({
            color: 0xffd700,
            roughness: 0.2,
            metalness: 0.9,
        });

        // Samurai Helmet Construction (Kabuto)
        const helmetGroup = new THREE.Group();

        // 1. Dome (Hachi)
        const domeGeo = new THREE.SphereGeometry(1, 32, 32, 0, Math.PI * 2, 0, Math.PI / 2);
        const dome = new THREE.Mesh(domeGeo, helmetMaterial);
        dome.position.y = 0;
        dome.castShadow = true;
        helmetGroup.add(dome);

        // 2. Brim (Shikoro - simplified as a torus)
        const brimGeo = new THREE.TorusGeometry(1.1, 0.15, 16, 32);
        const brim = new THREE.Mesh(brimGeo, helmetMaterial);
        brim.rotation.x = Math.PI / 2;
        brim.position.y = 0;
        brim.castShadow = true;
        helmetGroup.add(brim);

        // 3. Neck Guard (Shikoro - layered plates)
        const neckGuardGroup = new THREE.Group();
        for(let i=0; i<3; i++) {
            const plateGeo = new THREE.CylinderGeometry(1.2 + (i*0.1), 1.3 + (i*0.1), 0.1, 32, 1, true);
            const plate = new THREE.Mesh(plateGeo, helmetMaterial);
            plate.position.y = -0.2 - (i * 0.15);
            plate.rotation.x = Math.PI / 2;
            plate.castShadow = true;
            neckGuardGroup.add(plate);
        }
        helmetGroup.add(neckGuardGroup);

        // 4. Horns (Kuwagata)
        const hornGeo = new THREE.ConeGeometry(0.1, 1.2, 8);

        const leftHorn = new THREE.Mesh(hornGeo, goldAccentMaterial);
        leftHorn.position.set(-0.4, 0.8, 0.5);
        leftHorn.rotation.z = 0.5;
        leftHorn.rotation.x = -0.2;
        leftHorn.castShadow = true;
        helmetGroup.add(leftHorn);

        const rightHorn = new THREE.Mesh(hornGeo, goldAccentMaterial);
        rightHorn.position.set(0.4, 0.8, 0.5);
        rightHorn.rotation.z = -0.5;
        rightHorn.rotation.x = -0.2;
        rightHorn.castShadow = true;
        helmetGroup.add(rightHorn);

        // 5. Face Mask (Mempo)
        const faceGeo = new THREE.BoxGeometry(0.8, 0.6, 0.4);
        const face = new THREE.Mesh(faceGeo, redAccentMaterial);
        face.position.set(0, -0.3, 0.6);
        face.castShadow = true;
        helmetGroup.add(face);

        // 6. Front Crest (Maedate)
        const crestGeo = new THREE.BoxGeometry(0.1, 0.6, 0.1);
        const crest = new THREE.Mesh(crestGeo, goldAccentMaterial);
        crest.position.set(0, 0.5, 0.9);
        helmetGroup.add(crest);

        scene.add(helmetGroup);

        // Cherry Blossoms (Particles)
        const petalCount = 200;
        const petalGeometry = new THREE.PlaneGeometry(0.1, 0.1);
        const petalMaterial = new THREE.MeshBasicMaterial({ 
            color: 0xffb7c5, 
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.8
        });

        const petals = new THREE.InstancedMesh(petalGeometry, petalMaterial, petalCount);
        const dummy = new THREE.Object3D();
        const petalData = [];

        for (let i = 0; i < petalCount; i++) {
            const x = (Math.random() - 0.5) * 15;
            const y = Math.random() * 10;
            const z = (Math.random() - 0.5) * 15;

            dummy.position.set(x, y, z);
            dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
            dummy.scale.setScalar(Math.random() * 0.5 + 0.5);
            dummy.updateMatrix();
            petals.setMatrixAt(i, dummy.matrix);

            petalData.push({
                velocity: Math.random() * 0.02 + 0.01,
                rotationSpeed: (Math.random() - 0.5) * 0.05,
                swayOffset: Math.random() * Math.PI * 2,
                swaySpeed: Math.random() * 0.02 + 0.01
            });
        }
        scene.add(petals);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate Helmet gently
            helmetGroup.rotation.y = Math.sin(time * 0.2) * 0.3;
            helmetGroup.position.y = Math.sin(time * 0.5) * 0.1;

            // Animate Petals
            for (let i = 0; i < petalCount; i++) {
                petals.getMatrixAt(i, dummy.matrix);
                dummy.matrix.decompose(dummy.position, dummy.rotation, dummy.scale);

                // Fall down
                dummy.position.y -= petalData[i].velocity;

                // Sway side to side
                dummy.position.x += Math.sin(time * 2 + petalData[i].swayOffset) * 0.005;

                // Rotate
                dummy.rotation.x += petalData[i].rotationSpeed;
                dummy.rotation.z += petalData[i].rotationSpeed;

                // Reset if too low
                if (dummy.position.y < -5) {
                    dummy.position.y = 8;
                    dummy.position.x = (Math.random() - 0.5) * 15;
                    dummy.position.z = (Math.random() - 0.5) * 15;
                }

                dummy.updateMatrix();
                petals.setMatrixAt(i, dummy.matrix);
            }
            petals.instanceMatrix.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
