        const grassGeometry = new THREE.CylinderGeometry(6, 5, 1.5, 32);
        const grassMaterial = new THREE.MeshStandardMaterial({ color: 0x4caf50, flatShading: true });
        const grass = new THREE.Mesh(grassGeometry, grassMaterial);
        grass.position.y = 0.75;
        grass.receiveShadow = true;
        grass.castShadow = true;
        islandGroup.add(grass);

        // Island Bottom (Dirt/Rocks)
        const dirtGeometry = new THREE.ConeGeometry(5, 8, 32, 1, true); // Open ended cone
        const dirtMaterial = new THREE.MeshStandardMaterial({ color: 0x5d4037, side: THREE.DoubleSide, flatShading: true });
        const dirt = new THREE.Mesh(dirtGeometry, dirtMaterial);
        dirt.rotation.x = Math.PI; // Flip upside down
        dirt.position.y = -3.25;
        dirt.castShadow = true;
        islandGroup.add(dirt);

        // Add some random rocks on top
        const rockGeo = new THREE.DodecahedronGeometry(0.5);
        const rockMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        for(let i=0; i<10; i++) {
            const rock = new THREE.Mesh(rockGeo, rockMat);
            const angle = Math.random() * Math.PI * 2;
            const radius = Math.random() * 4;
            rock.position.set(Math.cos(angle)*radius, 1.5, Math.sin(angle)*radius);
            rock.scale.setScalar(0.5 + Math.random());
            rock.rotation.set(Math.random(), Math.random(), Math.random());
            rock.castShadow = true;
            islandGroup.add(rock);
