            const angle = (i / waterfallCount) * Math.PI * 2;
            const radius = 5.5; // Slightly outside the dirt cone

            const streamGroup = new THREE.Group();

            // Create a few segments for the stream to make it look like falling water
            for(let j=0; j<3; j++) {
                const water = new THREE.Mesh(waterGeo, waterMat);
                water.position.y = -j * 2.5;
                streamGroup.add(water);
