            }
        }
    </script>
</head>
<body>
    <div id="info">Fountain of Flowing Light</div>
    <script type="module">
        import * as THREE from 'three';

        // Scene Setup
        const scene = new THREE.Scene();
        // Dark background to make the light pop
        scene.background = new THREE.Color(0x020205);
        scene.fog = new THREE.FogExp2(0x020205, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 4, 8);
        camera.lookAt(0, 2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // --- Fountain Particles ---
        const particleCount = 3000;
        const geometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const colors = new Float32Array(particleCount * 3);
        const sizes = new Float32Array(particleCount);

        // Particle data for animation
        const particleData = [];

        const color1 = new THREE.Color(0x00ffff); // Cyan
        const color2 = new THREE.Color(0xff00ff); // Magenta

        for (let i = 0; i < particleCount; i++) {
            // Initialize positions at the bottom (in the "pool")
            const angle = Math.random() * Math.PI * 2;
            const radius = Math.random() * 0.5;

            positions[i * 3] = Math.cos(angle) * radius;
            positions[i * 3 + 1] = Math.random() * 0.5; // Start low
            positions[i * 3 + 2] = Math.sin(angle) * radius;

            // Randomize color mix
            const mixedColor = color1.clone().lerp(color2, Math.random());
            colors[i * 3] = mixedColor.r;
            colors[i * 3 + 1] = mixedColor.g;
            colors[i * 3 + 2] = mixedColor.b;

            sizes[i] = Math.random() * 0.15 + 0.05;

            // Physics data
            particleData.push({
                velocity: Math.random() * 0.05 + 0.02, // Upward speed
                spread: Math.random() * 0.02, // How much it spreads out
                angle: angle,
                radius: radius,
                life: Math.random() // Offset animation start
            });
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
        geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

        // Custom Shader Material for glowing particles
        const material = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 }
            },
            vertexShader: `
                attribute float size;
                attribute vec3 color;
                varying vec3 vColor;
                void main() {
                    vColor = color;
                    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
                    gl_PointSize = size * (300.0 / -mvPosition.z);
                    gl_Position = projectionMatrix * mvPosition;
                }
            `,
            fragmentShader: `
                varying vec3 vColor;
                void main() {
                    // Create a soft circle
                    vec2 xy = gl_PointCoord - vec2(0.5);
                    float ll = length(xy);
                    if(ll > 0.5) discard;

                    // Soft glow falloff
                    float alpha = 1.0 - smoothstep(0.0, 0.5, ll);
                    gl_FragColor = vec4(vColor, alpha);
                }
            `,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        const particles = new THREE.Points(geometry, material);
        scene.add(particles);

        // --- Fountain Base (Glowing Ring) ---
        const baseGeo = new THREE.TorusGeometry(0.8, 0.1, 16, 100);
        const baseMat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.rotation.x = Math.PI / 2;
        base.position.y = 0.1;
        scene.add(base);

        // Inner glow disc
        const discGeo = new THREE.CircleGeometry(0.7, 32);
        const discMat = new THREE.MeshBasicMaterial({ 
            color: 0x00ffff, 
            transparent: true, 
            opacity: 0.3,
            side: THREE.DoubleSide
        });
        const disc = new THREE.Mesh(discGeo, discMat);
        disc.rotation.x = -Math.PI / 2;
        disc.position.y = 0.05;
        scene.add(disc);

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            material.uniforms.time.value = time;

            const posArray = particles.geometry.attributes.position.array;

            for (let i = 0; i < particleCount; i++) {
                const p = particleData[i];

                // Update Y position
                posArray[i * 3 + 1] += p.velocity;

                // Spread out as they go up (cone shape)
                const heightFactor = posArray[i * 3 + 1] / 6.0; // Normalize height roughly
                const currentRadius = p.radius + (heightFactor * 2.0);

                // Update X and Z based on angle and expanding radius
                posArray[i * 3] = Math.cos(p.angle) * currentRadius;
                posArray[i * 3 + 2] = Math.sin(p.angle) * currentRadius;

                // Reset particle if it goes too high
                if (posArray[i * 3 + 1] > 6.0) {
                    posArray[i * 3 + 1] = 0;
                    // Reset to center-ish
                    const newAngle = Math.random() * Math.PI * 2;
                    p.angle = newAngle;
                    p.radius = Math.random() * 0.2;
                    posArray[i * 3] = Math.cos(newAngle) * p.radius;
                    posArray[i * 3 + 2] = Math.sin(newAngle) * p.radius;
                }
            }

            particles.geometry.attributes.position.needsUpdate = true;

            // Rotate base slightly
            base.rotation.z = time * 0.2;
            disc.rotation.z = -time * 0.1;

            // Gentle camera sway
            camera.position.x = Math.sin(time * 0.1) * 2;
            camera.lookAt(0, 2, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
