        // Lighting
        const ambientLight = new THREE.AmbientLight(0x111122);
        scene.add(ambientLight);

        // Jellyfish Class
        class Jellyfish {
            constructor() {
                this.group = new THREE.Group();
                this.tentacles = [];
                this.speed = 0.5 + Math.random() * 0.5;
                this.phase = Math.random() * Math.PI * 2;
                this.color = new THREE.Color().setHSL(Math.random() * 0.2 + 0.5, 1, 0.5); // Blue/Purple/Cyan range

                this.createBell();
                this.createTentacles();

                // Random position
                this.group.position.set(
                    (Math.random() - 0.5) * 40,
                    (Math.random() - 0.5) * 20,
                    (Math.random() - 0.5) * 20
                );

                scene.add(this.group);
            }

            createBell() {
                // Main dome
                const geometry = new THREE.SphereGeometry(1, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
                const material = new THREE.MeshStandardMaterial({
                    color: this.color,
                    emissive: this.color,
                    emissiveIntensity: 0.8,
                    transparent: true,
                    opacity: 0.8,
                    roughness: 0.1,
                    metalness: 0.1,
                    side: THREE.DoubleSide
                });
                this.bell = new THREE.Mesh(geometry, material);
                this.bell.scale.y = 0.6; // Flatten slightly
                this.group.add(this.bell);

                // Inner glow light
                const light = new THREE.PointLight(this.color, 1, 5);
                light.position.y = 0.2;
                this.group.add(light);
            }

            createTentacles() {
                const numTentacles = 6;
                const points = [];

                for (let i = 0; i < numTentacles; i++) {
                    const angle = (i / numTentacles) * Math.PI * 2;
                    const radius = 0.6;

                    // Create curve points
                    const curvePoints = [];
                    for (let j = 0; j <= 10; j++) {
                        const t = j / 10;
                        const x = Math.cos(angle) * radius * (1 - t * 0.5);
                        const y = -t * 3; // Length
                        const z = Math.sin(angle) * radius * (1 - t * 0.5);
                        curvePoints.push(new THREE.Vector3(x, y, z));
                    }

                    const curve = new THREE.CatmullRomCurve3(curvePoints);
                    const tubeGeo = new THREE.TubeGeometry(curve, 20, 0.05, 8, false);
                    const tubeMat = new THREE.MeshBasicMaterial({ 
                        color: this.color,
                        transparent: true,
                        opacity: 0.6
                    });
                    const tentacle = new THREE.Mesh(tubeGeo, tubeMat);

                    this.tentacles.push({ mesh: tentacle, basePoints: curvePoints, offset: Math.random() * 10 });
                    this.group.add(tentacle);
                }
            }

            update(time) {
                // Bobbing motion
                this.group.position.y += Math.sin(time * this.speed + this.phase) * 0.02;

                // Pulsing bell
                const pulse = 1 + Math.sin(time * 2 + this.phase) * 0.1;
                this.bell.scale.set(pulse, 0.6 / pulse, pulse);

                // Animate tentacles
                this.tentacles.forEach((t, index) => {
                    const curve = new THREE.CatmullRomCurve3(t.mesh.geometry.parameters.path.points); // This is inefficient, better to regenerate geometry or use vertices

                    // Simple vertex manipulation for wave effect
                    const positions = t.mesh.geometry.attributes.position;
                    const count = positions.count;

                    // We need to regenerate the tube geometry for smooth animation or just move vertices. 
                    // For simplicity in this short script, let's just rotate the whole tentacle slightly or rely on the group movement.
                    // Actually, let's just wiggle the group rotation slightly to simulate swimming.
                });

                // Gentle rotation
                this.group.rotation.z = Math.sin(time * 0.5 + this.phase) * 0.1;
                this.group.rotation.x = Math.cos(time * 0.3 + this.phase) * 0.1;
            }
        }

        // Create Swarm
        const swarm = [];
        const jellyfishCount = 30;
        for (let i = 0; i < jellyfishCount; i++) {
            swarm.push(new Jellyfish());
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            swarm.forEach(jelly => jelly.update(time));

            // Gentle camera drift
            camera.position.x = Math.sin(time * 0.1) * 5;
            camera.position.y = 5 + Math.cos(time * 0.1) * 2;
            camera.lookAt(0, 0, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
