        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1);
        scene.add(ambientLight);

        const pointLight = new THREE.PointLight(0xffaa00, 2, 20);
        pointLight.position.set(2, 5, 2);
        scene.add(pointLight);

        const rimLight = new THREE.PointLight(0xff0000, 3, 15);
        rimLight.position.set(-5, 0, -5);
        scene.add(rimLight);

        // --- Create Phoenix Feather Quill ---
        const quillGroup = new THREE.Group();

        // 1. The Shaft (Cylinder)
        const shaftGeo = new THREE.CylinderGeometry(0.05, 0.02, 4, 8);
        const shaftMat = new THREE.MeshStandardMaterial({ 
            color: 0x8B4513, 
            roughness: 0.4,
            metalness: 0.1
        });
        const shaft = new THREE.Mesh(shaftGeo, shaftMat);
        shaft.position.y = -1; // Offset so pivot is near tip
        quillGroup.add(shaft);

        // 2. The Feather (Custom Shape Extruded)
        const featherShape = new THREE.Shape();
        featherShape.moveTo(0, 0);
        featherShape.quadraticCurveTo(0.8, 1.5, 0, 3.5); // Right side
        featherShape.quadraticCurveTo(-0.8, 1.5, 0, 0); // Left side

        const extrudeSettings = {
            steps: 2,
            depth: 0.05,
            bevelEnabled: true,
            bevelThickness: 0.02,
            bevelSize: 0.02,
            bevelSegments: 2
        };

        const featherGeo = new THREE.ExtrudeGeometry(featherShape, extrudeSettings);
        // Center the geometry roughly
        featherGeo.center();

        const featherMat = new THREE.MeshStandardMaterial({ 
            color: 0xff3300, 
            emissive: 0xff1100,
            emissiveIntensity: 0.2,
            roughness: 0.3,
            metalness: 0.2,
            side: THREE.DoubleSide
        });

        const feather = new THREE.Mesh(featherGeo, featherMat);
        feather.position.y = 1.5; // Attach to top of shaft
        feather.rotation.x = -Math.PI / 2; // Lay flat initially
        feather.rotation.z = Math.PI / 4; // Angle it
        quillGroup.add(feather);

        // 3. The Tip (Glowing point)
        const tipGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const tipMat = new THREE.MeshBasicMaterial({ color: 0xffffaa });
        const tip = new THREE.Mesh(tipGeo, tipMat);
        tip.position.y = -2; // Bottom of shaft
        quillGroup.add(tip);

        // Add a point light to the tip
        const tipLight = new THREE.PointLight(0xffaa00, 1, 3);
        tipLight.position.set(0, 0, 0);
        tip.add(tipLight);

        scene.add(quillGroup);

        // --- Writing Trail System ---
        const trailPoints = [];
        const maxTrailLength = 100;
        const trailGeometry = new THREE.BufferGeometry();
        // Pre-allocate vertices
        const positions = new Float32Array(maxTrailLength * 3);
        const colors = new Float32Array(maxTrailLength * 3);

        trailGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        trailGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const trailMaterial = new THREE.LineBasicMaterial({ 
            vertexColors: true,
            linewidth: 2, // Note: linewidth > 1 often doesn't work in WebGL on all browsers
            transparent: true,
            opacity: 0.8
        });

        const trailLine = new THREE.Line(trailGeometry, trailMaterial);
        scene.add(trailLine);

        // --- Animation Logic ---
        let time = 0;
        const clock = new THREE.Clock();

        function updateTrail(position) {
            trailPoints.push(position.clone());
            if (trailPoints.length > maxTrailLength) {
                trailPoints.shift();
            }

            const positionsAttr = trailGeometry.attributes.position;
            const colorsAttr = trailGeometry.attributes.color;

            for (let i = 0; i < maxTrailLength; i++) {
                if (i < trailPoints.length) {
                    const p = trailPoints[i];
                    positionsAttr.setXYZ(i, p.x, p.y, p.z);

                    // Fade color from bright yellow/white to red/orange
                    const t = i / trailPoints.length; // 0 is oldest, 1 is newest
                    const r = 1.0;
                    const g = t * 0.8; 
                    const b = t * 0.2;
                    colorsAttr.setXYZ(i, r, g, b);
                } else {
                    // Hide unused vertices
                    positionsAttr.setXYZ(i, 0, 0, 0);
                }
            }

            positionsAttr.needsUpdate = true;
            colorsAttr.needsUpdate = true;
            trailGeometry.setDrawRange(0, trailPoints.length);
        }

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // 1. Move Quill in a "Writing" Path (Figure 8 / Lissajous curve)
            const speed = 1.5;
            const x = Math.sin(time * speed) * 2;
            const y = Math.sin(time * speed * 2) * 1.5;
            const z = Math.cos(time * speed) * 1;

            quillGroup.position.set(x, y, z);

            // 2. Rotate Quill to follow movement tangent roughly
            // Simple rotation for visual flair
            quillGroup.rotation.z = Math.sin(time * speed) * 0.5;
            quillGroup.rotation.x = Math.cos(time * speed * 2) * 0.2;
            quillGroup.rotation.y = time * 0.5;

            // 3. Update Trail
            // We want the trail to come from the tip of the quill
            const tipWorldPos = new THREE.Vector3();
            tip.getWorldPosition(tipWorldPos);
            updateTrail(tipWorldPos);

            // 4. Pulse the tip light
            tipLight.intensity = 1 + Math.sin(time * 10) * 0.5;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
