        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        const redLight = new THREE.PointLight(0xff0000, 5, 10);
        redLight.position.set(0, 4, 2);
        scene.add(redLight);

        // Materials
        const metalMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.9,
            roughness: 0.3
        });

        const jointMaterial = new THREE.MeshStandardMaterial({
            color: 0x111111,
            metalness: 0.5,
            roughness: 0.7
        });

        const eyeMaterial = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            emissive: 0xff0000,
            emissiveIntensity: 2
        });

        // Spider Group
        const spider = new THREE.Group();
        scene.add(spider);

        // Body Parts
        const thoraxGeo = new THREE.BoxGeometry(2.5, 1.5, 3);
        const thorax = new THREE.Mesh(thoraxGeo, metalMaterial);
        thorax.position.y = 3;
        thorax.castShadow = true;
        spider.add(thorax);

        const abdomenGeo = new THREE.SphereGeometry(1.8, 32, 32);
        const abdomen = new THREE.Mesh(abdomenGeo, metalMaterial);
        abdomen.position.set(0, 3, -2);
        abdomen.scale.set(1, 0.8, 1.2);
        abdomen.castShadow = true;
        spider.add(abdomen);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.2, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        leftEye.position.set(-0.6, 3.5, 1.6);
        spider.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMaterial);
        rightEye.position.set(0.6, 3.5, 1.6);
        spider.add(rightEye);

        // Legs Construction
        function createLeg(side, index) {
            const legGroup = new THREE.Group();

            // Base position on the body
            const xOffset = side * 1.4;
            const zOffset = (index - 1.5) * 1.2;

            legGroup.position.set(xOffset, 3, zOffset);
            legGroup.rotation.y = side * (0.2 + index * 0.15);

            let currentY = 0;
            let currentZ = 0;
            let currentRotX = 0;

            // Create 3 segments per leg
            for (let i = 0; i < 3; i++) {
                // Joint
                const jointGeo = new THREE.SphereGeometry(0.25, 16, 16);
                const joint = new THREE.Mesh(jointGeo, jointMaterial);
                joint.position.set(0, currentY, currentZ);
                legGroup.add(joint);

                // Segment
                const length = 2.5 - (i * 0.3);
                const segmentGeo = new THREE.CylinderGeometry(0.15, 0.1, length, 12);
                const segment = new THREE.Mesh(segmentGeo, metalMaterial);

                segment.position.set(0, currentY - length / 2, currentZ);
                segment.rotation.x = -Math.PI / 3 - (i * 0.2); // Angle downwards
                segment.castShadow = true;
                legGroup.add(segment);

                // Update position for next segment
                currentY -= length * Math.cos(Math.PI / 3 + (i * 0.2));
                currentZ += length * Math.sin(Math.PI / 3 + (i * 0.2));
            }

            spider.add(legGroup);
        }

        // Create 8 legs (4 on each side)
        for (let i = 0; i < 4; i++) {
            createLeg(1, i);  // Right side
            createLeg(-1, i); // Left side
        }

        // Floor
        const floorGeo = new THREE.PlaneGeometry(100, 100);
        const floorMat = new THREE.MeshStandardMaterial({ 
            color: 0x111111, 
            roughness: 0.8,
            metalness: 0.2
        });
