<script type="module">
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x020510);
scene.fog = new THREE.FogExp2(0x020510, 0.018);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 500);
camera.position.set(12, 8, 18);
camera.lookAt(0, 4, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post Processing (Bloom) ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.6, 0.5, 0.2
);
composer.addPass(bloom);

// ── Mountain ──
function createMountain() {
  const geo = new THREE.ConeGeometry(14, 12, 8, 6);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const noise = (Math.sin(x * 2.3 + z * 1.7) * 0.6 +
                   Math.cos(x * 0.9 - z * 3.1) * 0.4 +
                   Math.sin(y * 1.5 + x * 0.7) * 0.3) * (1 + y * 0.15);
    pos.setX(i, x + noise * 1.5);
    pos.setZ(i, z + noise * 1.5);
    pos.setY(i, y + noise * 0.5);
  }
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({
    color: 0x1a1a2e,
    roughness: 0.95,
    metalness: 0.1,
    flatShading: true
  });
  return new THREE.Mesh(geo, mat);
}
const mountain = createMountain();
mountain.position.y = -2;
scene.add(mountain);

// ── Rocky Platform ──
const platGeo = new THREE.CylinderGeometry(2.5, 3.2, 0.8, 7);
const platMat = new THREE.MeshStandardMaterial({ color: 0x15152a, roughness: 0.9, flatShading: true });
