const pot = new THREE.Mesh(potGeo, potMat);
potGroup.add(pot);
const rimGeo = new THREE.TorusGeometry(1.1, 0.06, 8, 24);
const rimMat = new THREE.MeshStandardMaterial({ color: 0x4a3525, roughness: 0.6 });
const rim = new THREE.Mesh(rimGeo, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.35;
potGroup.add(rim);
potGroup.position.y = 4.8;
scene.add(potGroup);

// ── Bonsai Tree ──
const bonsaiGroup = new THREE.Group();

// Trunk (curved via multiple segments)
const trunkCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, 0.35, 0),
  new THREE.Vector3(0.1, 1.2, 0.1),
  new THREE.Vector3(-0.15, 2.2, -0.05),
  new THREE.Vector3(0.1, 3.2, 0.15),
  new THREE.Vector3(-0.05, 3.8, 0)
]);
const trunkGeo = new THREE.TubeGeometry(trunkCurve, 20, 0.12, 8, false);
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x3d2b1f, roughness: 0.85 });
bonsaiGroup.add(new THREE.Mesh(trunkGeo, trunkMat));

// Branches
const branches = [
  { start: 0.4, dir: [1, 0.3, 0.2], len: 1.2, rad: 0.05 },
  { start: 0.6, dir: [-1, 0.4, -0.1], len: 1.0, rad: 0.045 },
  { start: 0.75, dir: [0.8, 0.5, 0.5], len: 0.8, rad: 0.04 },
  { start: 0.5, dir: [-0.6, 0.3, 0.7], len: 0.9, rad: 0.04 },
];
branches.forEach(b => {
  const pt = trunkCurve.getPoint(b.start);
  const end = new THREE.Vector3(
    pt.x + b.dir[0] * b.len,
    pt.y + b.dir[1] * b.len,
    pt.z + b.dir[2] * b.len
  );
  const mid = pt.clone().lerp(end, 0.5);
  mid.x += (Math.random() - 0.5) * 0.2;
  mid.z += (Math.random() - 0.5) * 0.2;
  const curve = new THREE.CatmullRomCurve3([pt, mid, end]);
  const geo = new THREE.TubeGeometry(curve, 8, b.rad, 6, false);
  bonsaiGroup.add(new THREE.Mesh(geo, trunkMat));
});

// Glowing Foliage Clusters
const foliageColor = new THREE.Color(0x00ffaa);
const foliageMat = new THREE.MeshStandardMaterial({
  color: 0x00ffaa,
  emissive: 0x00ffaa,
  emissiveIntensity: 2.5,
  roughness: 0.4,
  transparent: true,
  opacity: 0.85
});

const foliagePositions = [
  [0.3, 3.0, 0.15, 0.7],
  [-0.4, 2.4, -0.1, 0.55],
  [0.8, 1.6, 0.3, 0.5],
  [-0.7, 1.8, 0.2, 0.45],
  [0.1, 3.7, 0.05, 0.5],
  [1.0, 2.0, 0.5, 0.4],
  [-0.5, 2.8, 0.15, 0.45],
  [0.5, 2.2, -0.3, 0.35],
  [-0.3, 3.3, -0.15, 0.4],
  [0.0, 3.5, 0.3, 0.35],
  [1.2, 1.2, 0.4, 0.3],
  [-0.9, 1.4, 0.1, 0.3],
];

const foliageMeshes = [];
foliagePositions.forEach(([x, y, z, r]) => {
  const geo = new THREE.IcosahedronGeometry(r, 2);
  // Perturb vertices for organic look
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    pos.setX(i, pos.getX(i) + (Math.random() - 0.5) * r * 0.4);
    pos.setY(i, pos.getY(i) + (Math.random() - 0.5) * r * 0.4);
    pos.setZ(i, pos.getZ(i) + (Math.random() - 0.5) * r * 0.4);
  }
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, foliageMat.clone());
  mesh.position.set(x, y + 0.35, z);
  mesh.userData.baseY = y + 0.35;
  mesh.userData.phase = Math.random() * Math.PI * 2;
  bonsaiGroup.add(mesh);
  foliageMeshes.push(mesh);
});

bonsaiGroup.position.y = 4.8;
scene.add(bonsaiGroup);

// ── Point Lights ──
const mainLight = new THREE.PointLight(0x00ffaa, 40, 25, 1.5);
mainLight.position.set(0, 7.5, 0);
scene.add(mainLight);

const fillLight = new THREE.PointLight(0x4488ff, 15, 20, 2);
fillLight.position.set(-4, 6, 3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff6644, 8, 15, 2);
rimLight.position.set(5, 3, -4);
scene.add(rimLight);

scene.add(new THREE.AmbientLight(0x111122, 0.5));

// ── Floating Particles ──
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const pPositions = new Float32Array(particleCount * 3);
const pSizes = new Float32Array(particleCount);
for (let i = 0; i < particleCount; i++) {
  pPositions[i * 3] = (Math.random() - 0.5) * 30;
  pPositions[i * 3 + 1] = Math.random() * 20 - 2;
  pPositions[i * 3 + 2] = (Math.random() - 0.5) * 30;
  pSizes[i] = Math.random() * 3 + 1;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(pPositions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(pSizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0x00ffaa,
  size: 0.08,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending,
  depthWrite: false
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Stars ──
const starCount = 800;
const starGeo = new THREE.BufferGeometry();
const sPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(Math.random() * 0.8 + 0.2);
  const r = 80 + Math.random() * 120;
  sPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  sPos[i * 3 + 1] = r * Math.cos(phi);
  sPos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}
starGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff, size: 0.3, transparent: true, opacity: 0.7
});
scene.add(new THREE.Points(starGeo, starMat));

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle camera orbit
  camera.position.x = 12 * Math.cos(t * 0.1);
  camera.position.z = 18 * Math.sin(t * 0.08 + 0.5);
  camera.position.y = 8 + Math.sin(t * 0.15) * 1.5;
  camera.lookAt(0, 5.5, 0);

  // Pulsing foliage
  foliageMeshes.forEach(m => {
    const pulse = 1 + Math.sin(t * 1.5 + m.userData.phase) * 0.15;
    m.material.emissiveIntensity = 2.5 * pulse;
    m.scale.setScalar(pulse * 0.95 + 0.05);
    m.position.y = m.userData.baseY + Math.sin(t * 0.8 + m.userData.phase) * 0.05;
  });

  // Light pulsing
  mainLight.intensity = 40 + Math.sin(t * 2) * 8;

  // Particle drift
  const pp = particles.geometry.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    let y = pp.getY(i);
    y += 0.005 + Math.sin(t + i) * 0.002;
    if (y > 18) y = -2;
    pp.setY(i, y);
    pp.setX(i, pp.getX(i) + Math.sin(t * 0.5 + i * 0.1) * 0.003);
  }
  pp.needsUpdate = true;

  composer.render();
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What This Creates

- **Mountain peak** — A procedurally displaced cone with flat shading for a rugged, low-poly look
- **Rocky platform & ceramic pot** — Sitting atop the peak as the bonsai's base
- **Bonsai tree** — A curved trunk (CatmullRom spline tube), 4 branches, and **12 organic foliage clusters** using perturbed icosahedrons
- **Glow effect** — Green emissive foliage (`0x00ffaa`) with pulsing intensity, amplified by **Unreal Bloom** post-processing
- **Atmosphere** — Floating luminous particles drifting upward, a starfield, fog, and three colored point lights (green fill, blue rim, warm accent)
- **Camera** — Gently orbits the scene for a cinematic feel

