<body>
    <div id="info">Clockwork Butterfly — Drag to Orbit · Scroll to Zoom</div>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 1.0;

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft white light
        scene.add(ambientLight);

        const mainLight = new THREE.DirectionalLight(0xffaa00, 3); // Warm gold light
        mainLight.position.set(5, 10, 7);
        mainLight.castShadow = true;
        mainLight.shadow.mapSize.width = 1024;
        mainLight.shadow.mapSize.height = 1024;
        scene.add(mainLight);

        const backLight = new THREE.PointLight(0x0044ff, 2, 20); // Cool blue rim light
        backLight.position.set(-5, 2, -5);
        scene.add(backLight);

        const spotLight = new THREE.SpotLight(0xffd700, 5, 20, Math.PI / 6, 0.5, 1);
        spotLight.position.set(0, 5, 0);
        spotLight.target.position.set(0, 0, 0);
        scene.add(spotLight);
        scene.add(spotLight.target);

        // --- Materials ---
        const goldMaterial = new THREE.MeshStandardMaterial({
            color: 0xd4af37,
            metalness: 0.9,
            roughness: 0.2,
        });

        const brassMaterial = new THREE.MeshStandardMaterial({
            color: 0xb5a642,
            metalness: 0.8,
            roughness: 0.3,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.7,
            roughness: 0.5,
        });

        const gemMaterial = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            emissive: 0x550000,
            metalness: 0.1,
            roughness: 0.1,
            transparent: true,
            opacity: 0.9
        });

        // --- Butterfly Construction ---
        const butterflyGroup = new THREE.Group();
        scene.add(butterflyGroup);

        // 1. Body
        const bodyGroup = new THREE.Group();
        butterflyGroup.add(bodyGroup);

        // Thorax/Abdomen
        const bodyGeo = new THREE.CylinderGeometry(0.15, 0.1, 2.5, 8);
        const bodyMesh = new THREE.Mesh(bodyGeo, goldMaterial);
        bodyMesh.rotation.x = Math.PI / 2;
        bodyMesh.castShadow = true;
        bodyGroup.add(bodyMesh);

        // Head
        const headGeo = new THREE.SphereGeometry(0.25, 16, 16);
        const headMesh = new THREE.Mesh(headGeo, brassMaterial);
        headMesh.position.z = 1.3;
        headMesh.castShadow = true;
        bodyGroup.add(headMesh);

        // Eyes (Gems)
        const eyeGeo = new THREE.SphereGeometry(0.08, 8, 8);
        const eyeL = new THREE.Mesh(eyeGeo, gemMaterial);
        eyeL.position.set(0.12, 0.1, 1.5);
        bodyGroup.add(eyeL);
        const eyeR = new THREE.Mesh(eyeGeo, gemMaterial);
        eyeR.position.set(-0.12, 0.1, 1.5);
        bodyGroup.add(eyeR);

        // Antennae
        const antennaCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, 0, 0),
            new THREE.Vector3(0.2, 0.5, 0.5),
            new THREE.Vector3(0.4, 0.8, 0.2)
        ]);
        const antennaGeo = new THREE.TubeGeometry(antennaCurve, 20, 0.02, 8, false);
        const antennaL = new THREE.Mesh(antennaGeo, goldMaterial);
        antennaL.position.set(0.1, 0.2, 1.4);
        bodyGroup.add(antennaL);

        const antennaR = new THREE.Mesh(antennaGeo, goldMaterial);
        antennaR.position.set(-0.1, 0.2, 1.4);
        antennaR.scale.x = -1; // Mirror
        bodyGroup.add(antennaR);

        // 2. Wings
        function createWing(side) {
            const wingGroup = new THREE.Group();
            // Pivot point adjustment
            wingGroup.position.set(side * 0.2, 0, 0);

            // Main Wing Shape (Upper)
            const wingShape = new THREE.Shape();
            wingShape.moveTo(0, 0);
            wingShape.bezierCurveTo(1, 1.5, 3, 2, 4, 0.5); // Top edge
            wingShape.bezierCurveTo(3.5, -0.5, 2, -1, 0, -0.5); // Bottom edge
            wingShape.lineTo(0, 0);

            const extrudeSettings = {
                depth: 0.05,
                bevelEnabled: true,
                bevelSegments: 2,
                steps: 2,
                bevelSize: 0.05,
                bevelThickness: 0.05
            };

            const wingGeo = new THREE.ExtrudeGeometry(wingShape, extrudeSettings);
            const wingMesh = new THREE.Mesh(wingGeo, goldMaterial);
            wingMesh.rotation.x = -Math.PI / 2; // Lay flat
            wingMesh.position.x = -0.1; // Offset slightly
            wingMesh.castShadow = true;
            wingGroup.add(wingMesh);

            // Lower Wing Shape
            const lowerWingShape = new THREE.Shape();
            lowerWingShape.moveTo(0, -0.5);
            lowerWingShape.bezierCurveTo(1, -1, 2.5, -2, 3, -1.5);
            lowerWingShape.bezierCurveTo(2, -0.5, 1, -0.2, 0, -0.2);

            const lowerWingGeo = new THREE.ExtrudeGeometry(lowerWingShape, extrudeSettings);
            const lowerWingMesh = new THREE.Mesh(lowerWingGeo, brassMaterial);
            lowerWingMesh.rotation.x = -Math.PI / 2;
            lowerWingMesh.position.x = -0.1;
            lowerWingMesh.castShadow = true;
            wingGroup.add(lowerWingMesh);

            // Gears on Wing
            const gearGeo = new THREE.TorusGeometry(0.6, 0.08, 8, 16);
            const gear1 = new THREE.Mesh(gearGeo, darkMetalMaterial);
            gear1.position.set(1.5, 0, 0.1);
            wingGroup.add(gear1);

            const gear2Geo = new THREE.TorusGeometry(0.4, 0.06, 8, 12);
            const gear2 = new THREE.Mesh(gear2Geo, goldMaterial);
            gear2.position.set(2.5, 0.5, 0.1);
            wingGroup.add(gear2);

            // Small gear on lower wing
            const gear3Geo = new THREE.TorusGeometry(0.3, 0.05, 8, 10);
            const gear3 = new THREE.Mesh(gear3Geo, brassMaterial);
            gear3.position.set(1.5, -1.2, 0.1);
            wingGroup.add(gear3);

            // Connecting Rods
            const rodGeo = new THREE.CylinderGeometry(0.03, 0.03, 1.5);
            const rod = new THREE.Mesh(rodGeo, darkMetalMaterial);
            rod.rotation.z = Math.PI / 2;
            rod.position.set(2, 0.2, 0.1);
            wingGroup.add(rod);

            return wingGroup;
        }

        const rightWing = createWing(1);
        const leftWing = createWing(-1);

        // Mirror the left wing geometry visually by scaling
        leftWing.scale.x = -1;

        butterflyGroup.add(rightWing);
        butterflyGroup.add(leftWing);

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const delta = clock.getDelta();

            // Hovering motion
            butterflyGroup.position.y = Math.sin(time * 1.5) * 0.2;
            butterflyGroup.rotation.z = Math.sin(time * 0.5) * 0.05;

            // Wing Flapping
            // Using a sine wave for flapping, but clamped or shaped to look like a flap
            const flapSpeed = 8;
            const flapAngle = Math.sin(time * flapSpeed) * 0.4;

            // Apply rotation around X axis for flapping
            rightWing.rotation.x = flapAngle;
            leftWing.rotation.x = flapAngle;

            // Gear Rotation
            // Rotate gears relative to the wing group
            rightWing.children[3].rotation.z += 0.05; // gear1
            rightWing.children[4].rotation.z -= 0.08; // gear2
            rightWing.children[5].rotation.z += 0.1;  // gear3

            leftWing.children[3].rotation.z -= 0.05; 
            leftWing.children[4].rotation.z += 0.08; 
            leftWing.children[5].rotation.z -= 0.1; 

            controls.update();
            renderer.render(scene, camera);
        }

