      const right = new THREE.Vector3().crossVectors(newDir, up).normalize();
      const newUp = new THREE.Vector3().crossVectors(right, newDir).normalize();

      const rotatedDir = new THREE.Vector3(
        newDir.x + right.x * Math.sin(angle) + newUp.x * Math.sin(verticalAngle),
        newDir.y + right.y * Math.sin(angle) + newUp.y * Math.sin(verticalAngle),
        newDir.z + right.z * Math.sin(angle) + newUp.z * Math.sin(verticalAngle)
      ).normalize();

      const newEnd = new THREE.Vector3().copy(end).addScaledVector(rotatedDir, branchLength);
      const newRadius = radius * (0.55 + Math.random() * 0.15);

      // Add randomness to direction
      newEnd.x += (Math.random() - 0.5) * 0.15 * (1 - depth / maxDepth);
      newEnd.y += Math.random() * 0.05;
      newEnd.z += (Math.random() - 0.5) * 0.15 * (1 - depth / maxDepth);

      createBranch(end, newEnd, newRadius, depth + 1, maxDepth);
    }
  }
}

function createLeafCluster(position, depth) {
  const numClusters = 3 + Math.floor(Math.random() * 4);
  for (let i = 0; i < numClusters; i++) {
    const size = 0.08 + Math.random() * 0.12;
