    // Deform for organic look
    const pos = geo.attributes.position;
    for (let j = 0; j < pos.count; j++) {
      const x = pos.getX(j);
      const y = pos.getY(j);
      const z = pos.getZ(j);
      const noise = 1 + (Math.random() - 0.5) * 0.4;
      pos.setXYZ(j, x * noise, y * noise * 0.7, z * noise);
    }
    geo.computeVertexNormals();

    const mat = leafMaterials[Math.floor(Math.random() * leafMaterials.length)];
    const mesh = new THREE.Mesh(geo, mat);

    const offset = new THREE.Vector3(
      (Math.random() - 0.5) * 0.3,
      (Math.random() - 0.5) * 0.2,
      (Math.random() - 0.5) * 0.3
    );
    mesh.position.copy(position).add(offset);
    mesh.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
    treeGroup.add(mesh);
  }
}

// ── Generate the tree ──
