        scene.add(backLight);

        const bottomLight = new THREE.PointLight(0x0000ff, 30, 15);
        bottomLight.position.set(0, -5, 2);
        scene.add(bottomLight);

        // Crystal Material
        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaccff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 2.0,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9,
            side: THREE.DoubleSide
        });

        // Skull Group
        const skullGroup = new THREE.Group();
        scene.add(skullGroup);

        // 1. Main Head (Faceted Icosahedron)
        const headGeo = new THREE.IcosahedronGeometry(1.8, 1);
        // Distort vertices slightly to make it look more organic/skull-like
        const posAttribute = headGeo.attributes.position;
        for (let i = 0; i < posAttribute.count; i++) {
            const x = posAttribute.getX(i);
            const y = posAttribute.getY(i);
            const z = posAttribute.getZ(i);

            // Flatten top slightly, widen cheeks
            let newY = y * 0.9;
            let newX = x;
            if (y < 0.5 && y > -0.5) newX *= 1.1; // Widen middle

            posAttribute.setY(i, newY);
            posAttribute.setX(i, newX);
        }
        headGeo.computeVertexNormals();
        const headMesh = new THREE.Mesh(headGeo, crystalMaterial);
        skullGroup.add(headMesh);

        // 2. Jaw (Boxy shape)
        const jawGeo = new THREE.BoxGeometry(1.4, 0.8, 1.2);
        const jawMesh = new THREE.Mesh(jawGeo, crystalMaterial);
        jawMesh.position.set(0, -1.2, 0.2);
        skullGroup.add(jawMesh);

        // 3. Eye Sockets (Dark spheres inside)
        const socketGeo = new THREE.SphereGeometry(0.35, 16, 16);
        const socketMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

        const leftEye = new THREE.Mesh(socketGeo, socketMat);
        leftEye.position.set(-0.6, 0.2, 1.4);
        skullGroup.add(leftEye);

        const rightEye = new THREE.Mesh(socketGeo, socketMat);
        rightEye.position.set(0.6, 0.2, 1.4);
        skullGroup.add(rightEye);

        // 4. Nose (Inverted pyramid)
        const noseGeo = new THREE.ConeGeometry(0.2, 0.6, 4);
        const noseMesh = new THREE.Mesh(noseGeo, crystalMaterial);
