        noseMesh.rotation.x = Math.PI; // Point down
        skullGroup.add(noseMesh);

        // Rune Texture Generator
        function createRuneTexture(runeChar) {
            const canvas = document.createElement('canvas');
            canvas.width = 64;
            canvas.height = 64;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = 'rgba(0,0,0,0)';
            ctx.fillRect(0, 0, 64, 64);

            ctx.font = 'bold 48px serif';
            ctx.fillStyle = '#ffffff';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowColor = '#00ffff';
            ctx.shadowBlur = 10;
            ctx.fillText(runeChar, 32, 32);

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        // Add Runes to the skull
        const runes = ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ', 'ᚱ', 'ᚲ', 'ᚷ', 'ᚹ'];
        const runeMaterial = new THREE.MeshBasicMaterial({ 
            transparent: true, 
            side: THREE.DoubleSide,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        // Helper to place runes roughly on the surface
        function addRune(char, x, y, z, rotY, rotZ) {
            const texture = createRuneTexture(char);
            const mat = runeMaterial.clone();
            mat.map = texture;

            const geo = new THREE.PlaneGeometry(0.4, 0.4);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            mesh.rotation.y = rotY;
            mesh.rotation.z = rotZ;
            skullGroup.add(mesh);
        }

        // Place runes on forehead, cheeks, jaw
        addRune('ᚠ', 0, 1.2, 1.6, 0, 0); // Forehead center
        addRune('ᚢ', -0.8, 0.5, 1.5, 0.5, 0.2); // Left cheek
        addRune('ᚦ', 0.8, 0.5, 1.5, -0.5, -0.2); // Right cheek
        addRune('ᚨ', 0, -1.5, 0.8, 0, 0); // Jaw center
        addRune('ᚱ', -0.5, -1.5, 0.8, 0, 0); // Jaw left
        addRune('ᚲ', 0.5, -1.5, 0.8, 0, 0); // Jaw right
        addRune('ᚷ', 0, 1.8, 0, -Math.PI/2, 0); // Top of head

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate skull slowly
            skullGroup.rotation.y = Math.sin(time * 0.5) * 0.5;
            skullGroup.rotation.z = Math.sin(time * 0.3) * 0.1;

            // Float effect
            skullGroup.position.y = Math.sin(time) * 0.2;

            // Pulse lights
            mainLight.intensity = 80 + Math.sin(time * 2) * 20;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
