<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Lantern of Constellations</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050505; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.z = 5;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lantern Group
        const lanternGroup = new THREE.Group();
        scene.add(lanternGroup);

        // Lantern Core (The Light Source)
        const coreGeometry = new THREE.SphereGeometry(0.3, 32, 32);
        const coreMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
        const core = new THREE.Mesh(coreGeometry, coreMaterial);
        lanternGroup.add(core);

        // Lantern Cage (Wireframe)
        const cageGeometry = new THREE.IcosahedronGeometry(0.8, 1);
        const cageMaterial = new THREE.MeshBasicMaterial({ 
            color: 0xffddaa, 
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });
        const cage = new THREE.Mesh(cageGeometry, cageMaterial);
        lanternGroup.add(cage);

        // Inner Glow
        const glowGeometry = new THREE.SphereGeometry(0.4, 32, 32);
        const glowMaterial = new THREE.MeshBasicMaterial({ 
            color: 0xffaa00, 
            transparent: true, 
            opacity: 0.2 
        });
        const glow = new THREE.Mesh(glowGeometry, glowMaterial);
        lanternGroup.add(glow);

        // Point Light
        const light = new THREE.PointLight(0xffaa00, 2, 10);
        lanternGroup.add(light);

        // Constellation Particles
        const particleCount = 400;
        const particlesGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const velocities = [];
        const lifetimes = new Float32Array(particleCount);

        for (let i = 0; i < particleCount; i++) {
            positions[i * 3] = 0;
            positions[i * 3 + 1] = 0;
            positions[i * 3 + 2] = 0;

            // Random velocity direction
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            const speed = 0.02 + Math.random() * 0.03;

            velocities.push({
                x: Math.sin(phi) * Math.cos(theta) * speed,
                y: Math.sin(phi) * Math.sin(theta) * speed,
                z: Math.cos(phi) * speed
            });

            lifetimes[i] = Math.random();
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        // Create a star texture programmatically
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const context = canvas.getContext('2d');
        const gradient = context.createRadialGradient(16, 16, 0, 16, 16, 16);
        gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
        gradient.addColorStop(0.2, 'rgba(255, 200, 100, 0.8)');
        gradient.addColorStop(0.5, 'rgba(255, 100, 50, 0.2)');
        gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
        context.fillStyle = gradient;
        context.fillRect(0, 0, 32, 32);

        const texture = new THREE.CanvasTexture(canvas);

        const particlesMaterial = new THREE.PointsMaterial({
            color: 0xffddaa,
            size: 0.15,
            map: texture,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        const particleSystem = new THREE.Points(particlesGeometry, particlesMaterial);
        lanternGroup.add(particleSystem);

        // Constellation Lines
        const linesMaterial = new THREE.LineBasicMaterial({ 
            color: 0xffaa00, 
            transparent: true, 
            opacity: 0.15 
        });
        const linesGeometry = new THREE.BufferGeometry();
        const lines = new THREE.LineSegments(linesGeometry, linesMaterial);
        lanternGroup.add(lines);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate lantern slightly
            lanternGroup.rotation.y = time * 0.1;
            lanternGroup.rotation.z = Math.sin(time * 0.5) * 0.1;

            // Pulse core
            const scale = 1 + Math.sin(time * 2) * 0.1;
            core.scale.set(scale, scale, scale);
            glow.scale.set(scale * 1.5, scale * 1.5, scale * 1.5);

            // Update Particles
            const posAttribute = particlesGeometry.getAttribute('position');
            const linePositions = [];

            for (let i = 0; i < particleCount; i++) {
                const i3 = i * 3;

                // Move particle
                posAttribute.array[i3] += velocities[i].x;
                posAttribute.array[i3 + 1] += velocities[i].y;
                posAttribute.array[i3 + 2] += velocities[i].z;

                // Reset if too far or lifetime expired
                const dist = Math.sqrt(
                    posAttribute.array[i3]**2 + 
                    posAttribute.array[i3+1]**2 + 
                    posAttribute.array[i3+2]**2
                );

                if (dist > 4 || lifetimes[i] > 1) {
                    posAttribute.array[i3] = 0;
                    posAttribute.array[i3 + 1] = 0;
                    posAttribute.array[i3 + 2] = 0;
                    lifetimes[i] = 0;

                    // Reset velocity
                    const theta = Math.random() * Math.PI * 2;
                    const phi = Math.acos(2 * Math.random() - 1);
                    const speed = 0.02 + Math.random() * 0.03;
                    velocities[i] = {
                        x: Math.sin(phi) * Math.cos(theta) * speed,
                        y: Math.sin(phi) * Math.sin(theta) * speed,
                        z: Math.cos(phi) * speed
                    };
                } else {
                    lifetimes[i] += 0.01;
                }
            }
            posAttribute.needsUpdate = true;

            // Update Lines (connect nearby particles)
            // Simple optimization: only check a subset or use a grid, but for 400 particles brute force is okay-ish
            // Let's just connect particles that are close to the center to look like a web
            for (let i = 0; i < particleCount; i++) {
                const i3 = i * 3;
                const x1 = posAttribute.array[i3];
                const y1 = posAttribute.array[i3 + 1];
                const z1 = posAttribute.array[i3 + 2];

                // Connect to core if close
                const distToCenter = Math.sqrt(x1*x1 + y1*y1 + z1*z1);
                if (distToCenter < 1.5) {
                     linePositions.push(0, 0, 0, x1, y1, z1);
                }
            }

            linesGeometry.setAttribute('position', new THREE.Float32BufferAttribute(linePositions, 3));

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
