        const earL = new THREE.Mesh(earGeo, spectralMaterial);
        earL.position.set(-0.3, 0.5, 0);
        headGroup.add(earL);
        const earR = new THREE.Mesh(earGeo, spectralMaterial);
        earR.position.set(0.3, 0.5, 0);
        headGroup.add(earR);

        wolfGroup.add(headGroup);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.2, 0.15, 2, 8);
        const legPositions = [
            [-0.5, 1, 1], [0.5, 1, 1],
            [-0.5, 1, -1], [0.5, 1, -1]
        ];
        legPositions.forEach(pos => {
            const leg = new THREE.Mesh(legGeo, spectralMaterial);
            leg.position.set(...pos);
            wolfGroup.add(leg);
        });

        // Tail
        const tailGeo = new THREE.CylinderGeometry(0.1, 0.3, 1.5, 8);
        const tail = new THREE.Mesh(tailGeo, spectralMaterial);
        tail.position.set(0, 2.8, -1.8);
