        scene.add(wolfGroup);

        // Moon
        const moonGeo = new THREE.SphereGeometry(4, 32, 32);
        const moonMat = new THREE.MeshBasicMaterial({ color: 0xdddddd });
        const moon = new THREE.Mesh(moonGeo, moonMat);
        moon.position.set(15, 15, -20);
        scene.add(moon);

        // Particles (Spirit Dust)
        const particlesGeo = new THREE.BufferGeometry();
        const particleCount = 500;
        const posArray = new Float32Array(particleCount * 3);
        for(let i = 0; i < particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 20;
        }
        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.05,
            color: 0x88ccff,
            transparent: true,
            opacity: 0.6
        });
        const particles = new THREE.Points(particlesGeo, particlesMat);
        scene.add(particles);

        // Animation State
        let isHowling = false;
        let howlTime = 0;
        let headTargetRotX = 0;

        // Interaction
        window.addEventListener('click', () => {
            isHowling = !isHowling;
            document.getElementById('info').style.opacity = isHowling ? '0' : '0.7';
        });

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            // Floating effect
            wolfGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Howling Animation
            if (isHowling) {
                headTargetRotX = -Math.PI / 3; // Tilt head up
                // Add a little shake
                headGroup.rotation.z = Math.sin(time * 20) * 0.05;
                // Emissive pulse
                spectralMaterial.emissiveIntensity = 0.5 + Math.sin(time * 10) * 0.3;
            } else {
                headTargetRotX = 0;
                headGroup.rotation.z = 0;
                spectralMaterial.emissiveIntensity = 0.5;
            }

            // Smooth head rotation
            headGroup.rotation.x += (headTargetRotX - headGroup.rotation.x) * 0.05;

            // Particle movement
            particles.rotation.y = time * 0.05;
            particles.position.y = Math.sin(time * 0.2) * 0.5;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
