    <div id="info">🎻 violin & vines 🌿</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a1a);
        scene.fog = new THREE.Fog(0x1a1a1a, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeebb, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0x44ff44, 5);
        spotLight.position.set(-5, 5, 5);
        spotLight.lookAt(0, 0, 0);
        scene.add(spotLight);

        // --- Violin Construction ---
        const violinGroup = new THREE.Group();
        scene.add(violinGroup);

        // Materials
        const woodMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x8B4513, 
            roughness: 0.4, 
            metalness: 0.1 
        });
        const darkWoodMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3e2723, 
            roughness: 0.5 
        });
        const stringMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xdddddd, 
            roughness: 0.2, 
            metalness: 0.8 
        });

        // 1. Violin Body (LatheGeometry)
        // Points defining the cross-section profile of a violin
        const points = [];
        const profile = [
            [0, -2.5], [0.8, -2.4], [1.5, -2.0], [2.2, -1.0], // Bottom bout
            [2.0, -0.5], [1.8, 0], [2.0, 0.5], [2.2, 1.0], // Middle
            [1.5, 1.5], [0.8, 2.0], [0.5, 2.3], [0, 2.4]   // Top bout
        ];

        profile.forEach(p => points.push(new THREE.Vector2(p[0], p[1])));

        const bodyGeo = new THREE.LatheGeometry(points, 32);
        const body = new THREE.Mesh(bodyGeo, woodMaterial);
        body.rotation.x = Math.PI / 2; // Lay it flat initially, then we rotate group
        body.castShadow = true;
        body.receiveShadow = true;
        violinGroup.add(body);

        // 2. Neck
        const neckGeo = new THREE.CylinderGeometry(0.3, 0.4, 3, 16);
        const neck = new THREE.Mesh(neckGeo, darkWoodMaterial);
        neck.position.set(0, 0, 3.5);
        neck.rotation.x = Math.PI / 2;
        neck.castShadow = true;
        violinGroup.add(neck);

        // 3. Scroll
        const scrollGeo = new THREE.TorusGeometry(0.35, 0.1, 16, 32, Math.PI);
        const scroll = new THREE.Mesh(scrollGeo, darkWoodMaterial);
        scroll.position.set(0, 0, 5.2);
        scroll.rotation.y = Math.PI / 2;
        violinGroup.add(scroll);

        const pegboxGeo = new THREE.BoxGeometry(0.8, 0.4, 1.5);
        const pegbox = new THREE.Mesh(pegboxGeo, darkWoodMaterial);
        pegbox.position.set(0, 0, 4.5);
        violinGroup.add(pegbox);

        // 4. Strings
        const stringGeo = new THREE.CylinderGeometry(0.01, 0.01, 8, 8);
        stringGeo.rotateX(Math.PI / 2);
        for(let i = -1; i <= 1; i++) {
            const string = new THREE.Mesh(stringGeo, stringMaterial);
            string.position.set(i * 0.15, 0, 1);
            violinGroup.add(string);
        }

        // 5. F-Holes (Simple black planes)
        const fHoleGeo = new THREE.PlaneGeometry(0.3, 1.2);
        const fHoleMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

        const fHole1 = new THREE.Mesh(fHoleGeo, fHoleMat);
        fHole1.position.set(0.8, 0.2, 0.01);
        fHole1.rotation.z = 0.2;
        violinGroup.add(fHole1);

        const fHole2 = new THREE.Mesh(fHoleGeo, fHoleMat);
        fHole2.position.set(-0.8, 0.2, 0.01);
        fHole2.rotation.z = -0.2;
        violinGroup.add(fHole2);

        // Rotate entire violin to stand up
        violinGroup.rotation.x = -Math.PI / 2;
        violinGroup.rotation.z = 0.1; // Slight tilt

        // --- Living Vines ---
        const vines = [];
        const vineMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x2e7d32, 
            roughness: 0.8 
        });
        const leafMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x66bb6a, 
            side: THREE.DoubleSide 
        });

        function createVine(startPos, controlPoints, endPos) {
            const curve = new THREE.CatmullRomCurve3([
                startPos,
                ...controlPoints,
                endPos
            ]);

            const tubeGeo = new THREE.TubeGeometry(curve, 20, 0.05, 8, false);
            const vineMesh = new THREE.Mesh(tubeGeo, vineMaterial);
            vineMesh.castShadow = true;
            scene.add(vineMesh);

            // Add leaves
            const leafGeo = new THREE.ConeGeometry(0.15, 0.4, 8);
            leafGeo.rotateX(Math.PI/2); // Point outwards

            const numLeaves = 8;
            const leaves = [];

            for(let i=0; i<numLeaves; i++) {
                const t = (i + 1) / (numLeaves + 1);
                const pos = curve.getPoint(t);
                const tangent = curve.getTangent(t);

                const leaf = new THREE.Mesh(leafGeo, leafMaterial);
                leaf.position.copy(pos);

                // Orient leaf roughly perpendicular to vine
                leaf.lookAt(pos.clone().add(tangent));
                leaf.rotateX(Math.random() * Math.PI);
                leaf.rotateZ(Math.random() * Math.PI);

                scene.add(leaf);
                leaves.push({ mesh: leaf, t: t, basePos: pos.clone() });
            }

            return { mesh: vineMesh, curve: curve, leaves: leaves, originalPoints: curve.points.map(p => p.clone()) };
        }

        // Create several vines wrapping around
        // Vine 1: Wrapping the body
        vines.push(createVine(
            new THREE.Vector3(0, -2, 0),
            [
                new THREE.Vector3(1.5, -1, 0.5),
                new THREE.Vector3(2.2, 0, -0.5),
                new THREE.Vector3(1.5, 1, 0.5),
                new THREE.Vector3(0.5, 2, 0)
            ],
            new THREE.Vector3(0, 3, 0)
        ));

        // Vine 2: Crossing the neck
        vines.push(createVine(
            new THREE.Vector3(-1, -1, 1),
            [
                new THREE.Vector3(-1.5, 0, 2),
                new THREE.Vector3(0, 1, 3),
                new THREE.Vector3(1, 2, 4)
            ],
            new THREE.Vector3(0, 4, 5)
        ));

        // Vine 3: Bottom wrap
        vines.push(createVine(
            new THREE.Vector3(0, -3, 0),
            [
                new THREE.Vector3(-2, -2.5, 0.5),
                new THREE.Vector3(-2.5, -1.5, -0.5),
                new THREE.Vector3(-1, -0.5, 0.5)
            ],
            new THREE.Vector3(0, 0, 1)
        ));

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate violin slowly
            violinGroup.rotation.y = Math.sin(time * 0.2) * 0.2;

            // Animate Vines (Living movement)
            vines.forEach((vine, index) => {
                // Wiggle the curve points slightly
                const pts = vine.curve.points;
                for(let i=0; i<pts.length; i++) {
                    const original = vine.originalPoints[i];
                    pts[i].x = original.x + Math.sin(time * 2 + i + index) * 0.05;
                    pts[i].y = original.y + Math.cos(time * 1.5 + i + index) * 0.05;
                    pts[i].z = original.z + Math.sin(time * 1 + i * 0.5) * 0.05;
                }
                vine.curve.points = pts;
                vine.mesh.geometry.dispose();
                vine.mesh.geometry = new THREE.TubeGeometry(vine.curve, 20, 0.05, 8, false);

                // Animate Leaves
                vine.leaves.forEach(leaf => {
                    const pos = vine.curve.getPoint(leaf.t);
                    leaf.mesh.position.copy(pos);

                    // Gentle rotation
                    leaf.mesh.rotation.z += 0.01;
                    leaf.mesh.rotation.x += 0.005;
                });
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
