        const stem = new THREE.Mesh(stemGeometry, crystalMaterial);
        stem.position.y = -1;
        roseGroup.add(stem);

        // Petals Function
        function createPetal(size, yOffset, rotationOffset) {
            // Using a cone geometry scaled to look like a petal
            const geometry = new THREE.ConeGeometry(size, size * 2, 4); 
            const petal = new THREE.Mesh(geometry, crystalMaterial);

            // Shape the petal
            petal.scale.set(1, 0.1, 1); // Flatten it
            petal.rotation.x = Math.PI / 2; // Lay flat

            // Position
            petal.position.y = yOffset;

            // Rotate around Y axis
            petal.rotation.y = rotationOffset;

            // Tilt slightly outward
            petal.rotation.x += 0.5; 

            return petal;
        }

        // Build the Rose Head
        const headGroup = new THREE.Group();
        headGroup.position.y = 1;
        roseGroup.add(headGroup);

        // Inner Bud
        const budGeo = new THREE.IcosahedronGeometry(0.3, 1);
        const bud = new THREE.Mesh(budGeo, crystalMaterial);
        headGroup.add(bud);

        // Layers of petals
        const layers = 5;
        for (let i = 0; i < layers; i++) {
            const numPetals = 5 + i * 2;
            const radius = 0.5 + i * 0.3;
            const height = 0.2 + i * 0.1;

            for (let j = 0; j < numPetals; j++) {
                const angle = (j / numPetals) * Math.PI * 2 + (i * 0.5); // Spiral offset

                // Create a custom petal shape using LatheGeometry or just scaled cones
                // Let's use a scaled sphere for a smoother "crystal" look
                const petalGeo = new THREE.SphereGeometry(0.4, 16, 16);
                const petal = new THREE.Mesh(petalGeo, crystalMaterial);

                petal.scale.set(1, 0.1, 1.5); // Elongate

                // Position in a circle
                petal.position.x = Math.cos(angle) * radius * 0.5;
                petal.position.z = Math.sin(angle) * radius * 0.5;
                petal.position.y = height;

                // Rotate to face outward
                petal.lookAt(0, height, 0);
                petal.rotateX(Math.PI / 2); // Face up initially
                petal.rotateX(-0.5 - (i * 0.1)); // Tilt down based on layer

                headGroup.add(petal);
            }
        }

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Blooming animation (scale up from 0 to 1 over first few seconds, then pulse)
            const bloomFactor = Math.min(1, time * 0.5); // Blooms over 2 seconds
            const pulse = 1 + Math.sin(time * 2) * 0.05; // Gentle pulse

            const scale = bloomFactor * pulse;
            roseGroup.scale.set(scale, scale, scale);

            // Slow rotation
            roseGroup.rotation.y = time * 0.2;

            // Camera subtle movement
            camera.position.x = Math.sin(time * 0.1) * 2;
            camera.lookAt(0, 1, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
