<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a1a);
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.04);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.5, 0);

// ── Lighting ──
scene.add(new THREE.AmbientLight(0x334466, 0.8));
const dirLight = new THREE.DirectionalLight(0xffeedd, 1.5);
dirLight.position.set(5, 8, 4);
scene.add(dirLight);
const rimLight = new THREE.PointLight(0x6644aa, 2, 15);
rimLight.position.set(-3, 3, -3);
scene.add(rimLight);

// ── Hat Materials ──
const hatMat = new THREE.MeshStandardMaterial({
  color: 0x1a1028,
  roughness: 0.7,
  metalness: 0.1,
});
const bandMat = new THREE.MeshStandardMaterial({
  color: 0x8b6914,
  roughness: 0.4,
  metalness: 0.6,
});
const brimMat = new THREE.MeshStandardMaterial({
  color: 0x15101f,
  roughness: 0.8,
  metalness: 0.05,
});

// ── Hat Cone (top) ──
const coneGeo = new THREE.ConeGeometry(1.2, 3.2, 32, 1, true);
const cone = new THREE.Mesh(coneGeo, hatMat);
cone.position.y = 2.6;

// Bend the cone slightly by offsetting top vertex
const pos = coneGeo.attributes.position;
const topIdx = coneGeo.index ? coneGeo.index.getX(0) : 0;
// Shift upper vertices inward for a curve
for (let i = 0; i < pos.count; i++) {
  const y = pos.getY(i);
  if (y > 0) {
    const factor = 0.3 * (y / 1.6);
    pos.setX(i, pos.getX(i) * (1 - factor * 0.3));
    pos.setZ(i, pos.getZ(i) * (1 - factor * 0.3));
    pos.setY(i, y + Math.sin(y * 1.2) * 0.15);
  }
}
coneGeo.computeVertexNormals();
scene.add(cone);

// ── Hat Brim (torus-like ring) ──
const brimGeo = new THREE.TorusGeometry(1.5, 0.15, 16, 64);
const brim = new THREE.Mesh(brimGeo, brimMat);
brim.rotation.x = Math.PI / 2;
brim.position.y = 1.0;
scene.add(brim);

// Outer brim disc
const brimDiscGeo = new THREE.RingGeometry(0.9, 1.65, 64, 4);
const brimDisc = new THREE.Mesh(brimDiscGeo, brimMat);
brimDisc.rotation.x = -Math.PI / 2;
brimDisc.position.y = 0.99;
scene.add(brimDisc);

// ── Gold Band ──
const bandGeo = new THREE.CylinderGeometry(0.92, 0.95, 0.25, 32, 1, true);
const band = new THREE.Mesh(bandGeo, bandMat);
band.position.y = 1.15;
scene.add(band);

// ── Buckle ──
const buckleGeo = new THREE.BoxGeometry(0.35, 0.22, 0.08);
const buckle = new THREE.Mesh(buckleGeo, bandMat);
buckle.position.set(0, 1.15, 0.95);
scene.add(buckle);

const buckleInnerGeo = new THREE.BoxGeometry(0.18, 0.1, 0.09);
const buckleInner = new THREE.Mesh(buckleInnerGeo, brimMat);
buckleInner.position.set(0, 1.15, 0.95);
scene.add(buckleInner);

// ── Stars ──
function createStarGeometry() {
  const shape = new THREE.Shape();
  const outerR = 0.12, innerR = 0.05;
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? outerR : innerR;
    const a = (i * Math.PI) / 5 - Math.PI / 2;
    i === 0 ? shape.moveTo(Math.cos(a) * r, Math.sin(a) * r) : shape.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  shape.closePath();
  return new THREE.ExtrudeGeometry(shape, { depth: 0.04, bevelEnabled: false });
}

const starMat = new THREE.MeshStandardMaterial({
  color: 0xffdd44,
  emissive: 0xffaa00,
  emissiveIntensity: 0.8,
  roughness: 0.3,
  metalness: 0.7,
});

const starGeo = createStarGeometry();
const starCount = 22;
const stars = [];

for (let i = 0; i < starCount; i++) {
  const star = new THREE.Mesh(starGeo, starMat);

  // Distribute along the cone surface
  const t = Math.random() * 0.85 + 0.08;       // height fraction (0=top, 1=base)
  const angle = Math.random() * Math.PI * 2;
  const radiusAtT = 1.2 * t;
  const yAtT = 2.6 - t * 3.2 + 0.5;

  star.position.set(
    Math.cos(angle) * radiusAtT,
    yAtT + Math.sin(yAtT * 1.2) * 0.15,
    Math.sin(angle) * radiusAtT
  );

  // Orient outward from center
  star.lookAt(0, star.position.y, 0);
  star.rotateX(Math.PI / 2);

  const s = 0.6 + Math.random() * 0.8;
  star.scale.set(s, s, s);
  star.userData = { phase: Math.random() * Math.PI * 2, speed: 0.5 + Math.random() * 1.5 };
  scene.add(star);
  stars.push(star);
}

// ── Floating Sparkles ──
const sparkleCount = 80;
const sparkleGeo = new THREE.BufferGeometry();
const sparklePositions = new Float32Array(sparkleCount * 3);
const sparkleSizes = new Float32Array(sparkleCount);

for (let i = 0; i < sparkleCount; i++) {
  sparklePositions[i * 3] = (Math.random() - 0.5) * 8;
  sparklePositions[i * 3 + 1] = Math.random() * 6;
  sparklePositions[i * 3 + 2] = (Math.random() - 0.5) * 8;
  sparkleSizes[i] = Math.random() * 3 + 1;
}
sparkleGeo.setAttribute('position', new THREE.BufferAttribute(sparklePositions, 3));
sparkleGeo.setAttribute('size', new THREE.BufferAttribute(sparkleSizes, 1));

const sparkleMat = new THREE.PointsMaterial({
  color: 0xccbbff,
  size: 0.06,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
});
const sparkles = new THREE.Points(sparkleGeo, sparkleMat);
scene.add(sparkles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle hat bob
  cone.position.y = 2.6 + Math.sin(t * 0.8) * 0.05;

  // Star twinkle
  stars.forEach(star => {
    const { phase, speed } = star.userData;
    star.material.emissiveIntensity = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(t * speed + phase));
    star.rotation.z = Math.sin(t * speed * 0.5 + phase) * 0.2;
  });

  // Float sparkles
  const sPos = sparkles.geometry.attributes.position;
  for (let i = 0; i < sparkleCount; i++) {
    sPos.setY(i, sPos.getY(i) + 0.003);
    if (sPos.getY(i) > 6) sPos.setY(i, 0);
  }
  sPos.needsUpdate = true;

  controls.update();
  renderer.render(scene, camera);
}
animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
