        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const mainLight = new THREE.PointLight(0xffaa00, 2, 20);
        mainLight.position.set(0, 0, 2);
        scene.add(mainLight);

        const backLight = new THREE.PointLight(0x00aaff, 1, 20);
        backLight.position.set(0, 0, -5);
        scene.add(backLight);

        // Moth Group
        const moth = new THREE.Group();
        scene.add(moth);

        // --- Stained Glass Wing Shader ---
        const wingVertexShader = `
            varying vec2 vUv;
            varying vec3 vPosition;
            void main() {
                vUv = uv;
                vPosition = position;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `;

        const wingFragmentShader = `
            uniform float uTime;
            uniform vec3 uColor1;
            uniform vec3 uColor2;
            uniform vec3 uColor3;
            uniform vec3 uColor4;
            uniform float uOpacity;
            varying vec2 vUv;
            varying vec3 vPosition;

            // Simple hash for pseudo-random colors
            float hash(vec2 p) {
                return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
            }

            void main() {
                // Create a grid pattern
                vec2 grid = fract(vUv * 8.0);
                float line = step(0.9, grid.x) + step(0.9, grid.y);

                // Determine color based on grid cell
                vec2 cell = floor(vUv * 8.0);
                float r = hash(cell);

                vec3 color;
                if (r < 0.25) color = uColor1;
                else if (r < 0.5) color = uColor2;
                else if (r < 0.75) color = uColor3;
                else color = uColor4;

                // Add some glow/pulse
                float glow = 0.8 + 0.2 * sin(uTime * 2.0 + r * 10.0);
                color *= glow;

                // Darken the grid lines (lead)
                vec3 finalColor = mix(color, vec3(0.05), line);

                // Edge fade for softness
                float dist = length(vUv - 0.5) * 2.0;
                float alpha = smoothstep(1.0, 0.8, dist) * uOpacity;

                gl_FragColor = vec4(finalColor, alpha);
            }
        `;

        function createWing(side) {
            // Create a wing shape using a custom geometry or modified plane
            // Let's use a PlaneGeometry and modify vertices to look like a wing
            const geometry = new THREE.PlaneGeometry(3, 4, 10, 10);
            const positions = geometry.attributes.position;

            for (let i = 0; i < positions.count; i++) {
                let x = positions.getX(i);
                let y = positions.getY(i);
                let z = positions.getZ(i);

                // Warp the plane into a wing shape
                // Taper towards the top
                let taper = 1.0 - Math.abs(y) * 0.2; 
                x *= taper;

                // Curve it slightly
                z += Math.sin(y * 0.5) * 0.5;

                // Mirror for left/right
                if (side === 'left') x *= -1;

                positions.setXYZ(i, x, y, z);
            }

            geometry.computeVertexNormals();

            const material = new THREE.ShaderMaterial({
                vertexShader: wingVertexShader,
                fragmentShader: wingFragmentShader,
                uniforms: {
                    uTime: { value: 0 },
                    uColor1: { value: new THREE.Color(0xff0055) }, // Red/Pink
                    uColor2: { value: new THREE.Color(0xffaa00) }, // Orange
                    uColor3: { value: new THREE.Color(0x00aaff) }, // Blue
                    uColor4: { value: new THREE.Color(0xaa00ff) }, // Purple
                    uOpacity: { value: 0.85 }
                },
                transparent: true,
                side: THREE.DoubleSide,
                depthWrite: false,
                blending: THREE.AdditiveBlending
            });

            const mesh = new THREE.Mesh(geometry, material);

            // Position wings
            mesh.position.x = side === 'left' ? -0.6 : 0.6;
            mesh.rotation.y = side === 'left' ? 0.2 : -0.2;

            return mesh;
        }

        const leftWing = createWing('left');
        const rightWing = createWing('right');
        moth.add(leftWing);
        moth.add(rightWing);

        // --- Moth Body ---
        const bodyGeo = new THREE.CapsuleGeometry(0.2, 1.5, 4, 8);
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.8,
            metalness: 0.2
        });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.rotation.z = Math.PI / 2; // Lay it horizontal
        moth.add(body);

        // Antennae
        const antennaCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, 0, 0.8),
            new THREE.Vector3(0.2, 0.2, 1.2),
            new THREE.Vector3(0.4, 0.1, 1.5)
        ]);
        const antennaGeo = new THREE.TubeGeometry(antennaCurve, 8, 0.02, 4, false);
        const antennaMat = new THREE.MeshBasicMaterial({ color: 0x111111 });

        const antennaL = new THREE.Mesh(antennaGeo, antennaMat);
        const antennaR = new THREE.Mesh(antennaGeo, antennaMat);
        antennaR.scale.x = -1; // Mirror
        moth.add(antennaL);
        moth.add(antennaR);

        // Inner Glow Light
        const innerLight = new THREE.PointLight(0xffaa00, 3, 5);
        innerLight.position.set(0, 0, 0);
        moth.add(innerLight);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Update shader uniforms
            leftWing.material.uniforms.uTime.value = time;
            rightWing.material.uniforms.uTime.value = time;

            // Flapping animation
            const flapSpeed = 10;
            const flapAngle = Math.sin(time * flapSpeed) * 0.3;

            leftWing.rotation.z = flapAngle;
            rightWing.rotation.z = -flapAngle;

            // Gentle floating
            moth.position.y = Math.sin(time * 0.5) * 0.5;
            moth.rotation.y = Math.sin(time * 0.2) * 0.2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
