        function resetParticle(i) {
            // Start at one of the two stacks
            const stackIndex = Math.random() > 0.5 ? 1 : 2;
            const xOffset = 2;
            const yOffset = 3;
            const zOffset = stackIndex === 1 ? 1 : -1;

            particlePositions[i*3] = xOffset + (Math.random() - 0.5) * 0.5;
            particlePositions[i*3+1] = yOffset + (Math.random() - 0.5) * 0.5;
            particlePositions[i*3+2] = zOffset + (Math.random() - 0.5) * 0.5;

            particleSpeeds[i] = 0.05 + Math.random() * 0.05;
            particleLifetimes[i] = 0;
