            for(let i=0; i<particleCount; i++) {
                particleLifetimes[i] += delta * 0.5; // Age

                // Move up and slightly back
                positions[i*3] -= delta * 2; // Move back (negative X)
                positions[i*3+1] += particleSpeeds[i]; // Move up
                positions[i*3+2] += (Math.random() - 0.5) * delta; // Drift Z

                // Reset if too high or old
                if (positions[i*3+1] > 10 || particleLifetimes[i] > 2) {
                    resetParticle(i);
                }
            }
            particleSystem.geometry.attributes.position.needsUpdate = true;

            controls.update();
            renderer.render(scene, camera);
        }

