</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// --- Scene setup ---
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a12, 0.015);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0, 12);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// --- Lights ---
scene.add(new THREE.AmbientLight(0x334466, 0.8));

const dirLight = new THREE.DirectionalLight(0xffeedd, 2.5);
dirLight.position.set(5, 8, 6);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x4488ff, 1.5, 20);
pointLight.position.set(-4, -3, 5);
scene.add(pointLight);

const rimLight = new THREE.PointLight(0xff8844, 1, 15);
rimLight.position.set(3, -2, -4);
scene.add(rimLight);

// --- Materials ---
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xd4a843, metalness: 0.9, roughness: 0.25
});
const darkGoldMat = new THREE.MeshStandardMaterial({
  color: 0x8b6914, metalness: 0.85, roughness: 0.35
});
const silverMat = new THREE.MeshStandardMaterial({
  color: 0xc0c0c0, metalness: 0.9, roughness: 0.2
});
const redMat = new THREE.MeshStandardMaterial({
  color: 0xcc2222, metalness: 0.7, roughness: 0.3
});
const darkMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e, metalness: 0.3, roughness: 0.6
});

// --- Compass Rose Group ---
const compass = new THREE.Group();
scene.add(compass);

// --- Helper: create a compass point (arrow shape) ---
function createCompassPoint(length, width, mat, segments = 1) {
  const shape = new THREE.Shape();
  shape.moveTo(0, length);
  shape.lineTo(width * 0.5, 0);
  shape.lineTo(width * 0.15, -width * 0.3);
  shape.lineTo(-width * 0.15, -width * 0.3);
  shape.lineTo(-width * 0.5, 0);
  shape.closePath();

  const extrudeSettings = { depth: 0.12, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.04, bevelSegments: segments };
  const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geom.center();
  const mesh = new THREE.Mesh(geom, mat);
  return mesh;
}

// --- 4 Cardinal points (N, S, E, W) ---
const cardinalLength = 3.2;
const cardinalWidth = 0.9;
for (let i = 0; i < 4; i++) {
  const angle = (i * Math.PI) / 2;
  const point = createCompassPoint(cardinalLength, cardinalWidth, i % 2 === 0 ? redMat : goldMat, 3);
  point.rotation.z = angle;
  point.position.z = 0.01;
  compass.add(point);
}

// --- 4 Intercardinal points (NE, NW, SE, SW) ---
const interLength = 2.0;
const interWidth = 0.6;
for (let i = 0; i < 4; i++) {
  const angle = (Math.PI / 4) + (i * Math.PI) / 2;
  const point = createCompassPoint(interLength, interWidth, darkGoldMat, 2);
  point.rotation.z = angle;
  point.position.z = -0.01;
  compass.add(point);
}

// --- Decorative rings ---
function createRing(radius, thickness, mat, tubeRadius = 0.06) {
  const curve = new THREE.EllipseCurve(0, 0, radius, radius, 0, 2 * Math.PI, false, 0);
  const points = curve.getPoints(80);
  const geomPoints = points.map(p => new THREE.Vector3(p.x, p.y, 0));
  const curve3 = new THREE.CatmullRomCurve3(geomPoints, true);
  const tubeGeom = new THREE.TubeGeometry(curve3, 80, tubeRadius, 8, true);
  return new THREE.Mesh(tubeGeom, mat);
}

compass.add(createRing(3.8, 0.1, silverMat, 0.05));
compass.add(createRing(3.4, 0.1, goldMat, 0.04));
compass.add(createRing(2.4, 0.1, darkGoldMat, 0.035));
compass.add(createRing(1.5, 0.1, silverMat, 0.03));

// --- Center piece ---
const centerGeom = new THREE.CylinderGeometry(0.35, 0.35, 0.3, 32);
const centerMesh = new THREE.Mesh(centerGeom, goldMat);
centerMesh.rotation.x = Math.PI / 2;
compass.add(centerMesh);

const centerInner = new THREE.Mesh(
  new THREE.CylinderGeometry(0.18, 0.18, 0.35, 32),
  redMat
);
centerInner.rotation.x = Math.PI / 2;
compass.add(centerInner);

// --- Tick marks around the ring ---
for (let i = 0; i < 32; i++) {
  const angle = (i * Math.PI) / 16;
  const isMajor = i % 4 === 0;
  const isMid = i % 2 === 0;
  const tickLen = isMajor ? 0.35 : isMid ? 0.2 : 0.1;
  const tickGeom = new THREE.BoxGeometry(0.04, tickLen, 0.05);
  const tickMat = isMajor ? goldMat : isMid ? silverMat : darkGoldMat;
  const tick = new THREE.Mesh(tickGeom, tickMat);
  const r = 3.6;
  tick.position.set(
    Math.cos(angle) * r,
    Math.sin(angle) * r,
    0
  );
  tick.rotation.z = -angle;
  compass.add(tick);
}

// --- Direction labels as sprite textures ---
function createLabel(text, x, y, fontSize = 32) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, 128, 128);
  ctx.font = `bold ${fontSize}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#d4a843';
  ctx.shadowColor = '#ff8800';
  ctx.shadowBlur = 8;
  ctx.fillText(text, 64, 64);

  const texture = new THREE.CanvasTexture(canvas);
  const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.position.set(x, y, 0.5);
  sprite.scale.set(0.8, 0.8, 1);
  return sprite;
}

const labelDist = 4.4;
compass.add(createLabel('N', 0, labelDist, 36));
compass.add(createLabel('S', 0, -labelDist, 36));
compass.add(createLabel('E', labelDist, 0, 36));
compass.add(createLabel('W', -labelDist, 0, 36));
compass.add(createLabel('NE', labelDist * 0.72, labelDist * 0.72, 26));
compass.add(createLabel('NW', -labelDist * 0.72, labelDist * 0.72, 26));
compass.add(createLabel('SE', labelDist * 0.72, -labelDist * 0.72, 26));
compass.add(createLabel('SW', -labelDist * 0.72, -labelDist * 0.72, 26));

// --- Tilt the compass slightly ---
compass.rotation.x = -0.15;
compass.rotation.z = 0.08;

// --- Particles (ambient stars) ---
const particleCount = 300;
const particleGeom = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 40;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 40;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30 - 5;
}
particleGeom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({ color: 0x8899cc, size: 0.05, transparent: true, opacity: 0.6 });
const particles = new THREE.Points(particleGeom, particleMat);
scene.add(particles);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle floating rotation
  compass.rotation.y = Math.sin(t * 0.3) * 0.15 + t * 0.05;

  // Gentle float up/down
  compass.position.y = Math.sin(t * 0.5) * 0.3;

  // Subtle breathing scale
  const s = 1 + Math.sin(t * 0.8) * 0.015;
  compass.scale.set(s, s, s);

  // Slow particle drift
  particles.rotation.y = t * 0.01;

  // Animate rim light
  rimLight.position.x = Math.cos(t * 0.4) * 5;
  rimLight.position.z = Math.sin(t * 0.4) * 5;

  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
