moonLight.shadow.camera.right = 15;
moonLight.shadow.camera.top = 15;
moonLight.shadow.camera.bottom = -15;
scene.add(moonLight);

const hemiLight = new THREE.HemisphereLight(0x446688, 0x112233, 0.6);
scene.add(hemiLight);

// ── Water ──
const waterGeo = new THREE.PlaneGeometry(200, 200, 128, 128);
const waterMat = new THREE.MeshStandardMaterial({
  color: 0x0a2a4a,
  metalness: 0.9,
  roughness: 0.15,
  transparent: true,
  opacity: 0.85,
});
const water = new THREE.Mesh(waterGeo, waterMat);
water.rotation.x = -Math.PI / 2;
water.position.y = -1.5;
water.receiveShadow = true;
scene.add(water);

// ── Rock ──
const rockGeo = new THREE.DodecahedronGeometry(2.2, 2);
const pos = rockGeo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
  const noise = 1 + (Math.sin(x * 3.7 + z * 2.1) * 0.3 + Math.cos(y * 2.3 + x * 1.8) * 0.25 + Math.sin(z * 5.1 + y * 4.3) * 0.15);
  const flatten = y < 0 ? 0.7 : 1.0;
  pos.setXYZ(i, x * noise, y * noise * flatten, z * noise);
}
rockGeo.computeVertexNormals();

const rockMat = new THREE.MeshStandardMaterial({
  color: 0x3a3a3a,
  roughness: 0.95,
  metalness: 0.05,
  flatShading: true,
});
const rock = new THREE.Mesh(rockGeo, rockMat);
rock.position.y = -0.3;
rock.castShadow = true;
rock.receiveShadow = true;
scene.add(rock);

// ── Lighthouse Group ──
const lighthouseGroup = new THREE.Group();
lighthouseGroup.position.y = 0.5;
scene.add(lighthouseGroup);

// Tower base (wider)
const towerMatWhite = new THREE.MeshStandardMaterial({ color: 0xf5f5f0, roughness: 0.7, metalness: 0.05 });
const towerMatRed = new THREE.MeshStandardMaterial({ color: 0xcc3333, roughness: 0.6, metalness: 0.05 });

function createTowerStripes() {
  const group = new THREE.Group();
  const segments = 8;
  const height = 5;
  const baseRadius = 1.0;
  const topRadius = 0.6;
  const segH = height / segments;

  for (let i = 0; i < segments; i++) {
    const t = i / segments;
    const rBottom = baseRadius + (topRadius - baseRadius) * t;
    const rTop = baseRadius + (topRadius - baseRadius) * ((i + 1) / segments);
    const geo = new THREE.CylinderGeometry(rTop, rBottom, segH + 0.02, 16);
    const mat = i % 2 === 0 ? towerMatWhite : towerMatRed;
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.y = i * segH + segH / 2;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    group.add(mesh);
  }
  return group;
}
lighthouseGroup.add(createTowerStripes());

// Gallery deck (railing)
const deckGeo = new THREE.CylinderGeometry(1.15, 1.15, 0.12, 24);
const deckMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.4, metalness: 0.6 });
const deck = new THREE.Mesh(deckGeo, deckMat);
deck.position.y = 5.06;
deck.castShadow = true;
lighthouseGroup.add(deck);

// Railing posts
for (let i = 0; i < 12; i++) {
  const angle = (i / 12) * Math.PI * 2;
  const postGeo = new THREE.CylinderGeometry(0.03, 0.03, 0.6, 6);
  const post = new THREE.Mesh(postGeo, deckMat);
  post.position.set(Math.cos(angle) * 1.1, 5.4, Math.sin(angle) * 1.1);
  lighthouseGroup.add(post);
}
// Railing ring
const railRingGeo = new THREE.TorusGeometry(1.1, 0.025, 6, 24);
const railRing = new THREE.Mesh(railRingGeo, deckMat);
railRing.position.y = 5.65;
railRing.rotation.x = Math.PI / 2;
lighthouseGroup.add(railRing);

// Lantern room
const lanternHeight = 1.2;
const lanternGeo = new THREE.CylinderGeometry(0.55, 0.65, lanternHeight, 16);
const lanternMat = new THREE.MeshStandardMaterial({
  color: 0x111111,
  roughness: 0.3,
  metalness: 0.7,
});
const lantern = new THREE.Mesh(lanternGeo, lanternMat);
lantern.position.y = 5.12 + lanternHeight / 2;
lantern.castShadow = true;
lighthouseGroup.add(lantern);

// Glass panels
const glassGeo = new THREE.CylinderGeometry(0.52, 0.62, lanternHeight * 0.75, 16, 1, true);
const glassMat = new THREE.MeshStandardMaterial({
  color: 0xffffcc,
  emissive: 0xffaa33,
  emissiveIntensity: 0.8,
  transparent: true,
  opacity: 0.6,
  roughness: 0.1,
  metalness: 0.0,
});
const glass = new THREE.Mesh(glassGeo, glassMat);
glass.position.y = 5.12 + lanternHeight * 0.5;
lighthouseGroup.add(glass);

// Dome roof
const domeGeo = new THREE.SphereGeometry(0.58, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2);
const domeMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.3, metalness: 0.7 });
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.position.y = 5.12 + lanternHeight;
dome.castShadow = true;
lighthouseGroup.add(dome);

// Ball on top
const ballGeo = new THREE.SphereGeometry(0.08, 12, 12);
const ball = new THREE.Mesh(ballGeo, domeMat);
ball.position.y = 5.12 + lanternHeight + 0.55;
lighthouseGroup.add(ball);

// ── Light Beam ──
const beamLight = new THREE.PointLight(0xffcc44, 3, 30, 1.5);
beamLight.position.y = 5.8;
beamLight.castShadow = false;
lighthouseGroup.add(beamLight);

// Volumetric beam (cone)
const beamGeo = new THREE.ConeGeometry(0.3, 8, 16, 1, true);
const beamMat = new THREE.MeshBasicMaterial({
  color: 0xffdd66,
  transparent: true,
  opacity: 0.08,
  side: THREE.DoubleSide,
  depthWrite: false,
});
const beam = new THREE.Mesh(beamGeo, beamMat);
beam.position.y = 9.8;
beam.rotation.x = Math.PI;
lighthouseGroup.add(beam);

// Second beam opposite
const beam2 = beam.clone();
beam2.rotation.z = Math.PI;
lighthouseGroup.add(beam2);

// ── Stars ──
const starsGeo = new THREE.BufferGeometry();
const starsCount = 600;
const starsPos = new Float32Array(starsCount * 3);
for (let i = 0; i < starsCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI * 0.45;
  const r = 80 + Math.random() * 20;
  starsPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  starsPos[i * 3 + 1] = r * Math.cos(phi) + 10;
  starsPos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}
starsGeo.setAttribute('position', new THREE.BufferAttribute(starsPos, 3));
const starsMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.3, sizeAttenuation: true });
scene.add(new THREE.Points(starsGeo, starsMat));

// ── Small waves / foam around rock ──
const foamGroup = new THREE.Group();
for (let i = 0; i < 30; i++) {
  const angle = Math.random() * Math.PI * 2;
  const dist = 2.0 + Math.random() * 1.5;
  const foamGeo = new THREE.SphereGeometry(0.08 + Math.random() * 0.12, 6, 6);
  const foamMat = new THREE.MeshStandardMaterial({
    color: 0xaaccee,
    emissive: 0x334466,
    emissiveIntensity: 0.2,
    transparent: true,
    opacity: 0.5 + Math.random() * 0.3,
    roughness: 0.2,
  });
  const foam = new THREE.Mesh(foamGeo, foamMat);
  foam.position.set(Math.cos(angle) * dist, -1.3 + Math.random() * 0.3, Math.sin(angle) * dist);
  foam.scale.y = 0.5;
  foamGroup.add(foam);
}
scene.add(foamGroup);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Bob the lighthouse + rock
  const bobY = Math.sin(t * 0.8) * 0.25;
  const bobRoll = Math.sin(t * 0.5) * 0.02;
  const bobPitch = Math.sin(t * 0.7 + 1) * 0.015;
  lighthouseGroup.position.y = 0.5 + bobY;
  lighthouseGroup.rotation.z = bobRoll;
  lighthouseGroup.rotation.x = bobPitch;

  // Rock bobs slightly less
  rock.position.y = -0.3 + bobY * 0.4;
  rock.rotation.z = bobRoll * 0.5;

  // Water wave animation
  const wPos = waterGeo.attributes.position;
  for (let i = 0; i < wPos.count; i++) {
    const x = wPos.getX(i);
    const y = wPos.getY(i);
    const z = Math.sin(x * 0.15 + t * 0.8) * 0.3 +
              Math.cos(y * 0.12 + t * 0.6) * 0.25 +
              Math.sin((x + y) * 0.08 + t * 1.1) * 0.15;
    wPos.setZ(i, z);
  }
  wPos.needsUpdate = true;
  waterGeo.computeVertexNormals();

  // Light beam rotation
  beam.rotation.y = t * 1.2;
  beam2.rotation.y = t * 1.2 + Math.PI;

  // Beam pulse
  beamMat.opacity = 0.06 + Math.sin(t * 3) * 0.03;
  beam2.material.opacity = beamMat.opacity;
  beamLight.intensity = 2.5 + Math.sin(t * 3) * 1.0;

  // Glass glow pulse
  glassMat.emissiveIntensity = 0.6 + Math.sin(t * 3) * 0.3;

  // Foam gentle animation
  foamGroup.children.forEach((f, i) => {
    f.position.y = f.position.y + Math.sin(t * 1.5 + i) * 0.001;
    f.material.opacity = 0.3 + Math.sin(t * 2 + i * 0.5) * 0.2;
  });

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
