    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Silver Harp of the Wind</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050510; }
        canvas { display: block; }
        #info {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: #aaa;
            font-family: sans-serif;
            pointer-events: none;
            text-shadow: 0 0 5px rgba(0,0,0,0.8);
        }
    </style>
</head>
<body>
    <div id="info">✦ The Silver Harp of the Wind ✦</div>
    <!-- Load Three.js from CDN -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <script>
        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510);
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // 2. Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x4444ff, 1, 20);
        pointLight.position.set(-5, 5, 5);
        scene.add(pointLight);

        // 3. Materials
        const silverMaterial = new THREE.MeshStandardMaterial({
            color: 0xcccccc,
            metalness: 0.9,
            roughness: 0.2,
        });

        const stringMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            metalness: 0.5,
            roughness: 0.5,
            emissive: 0x222222
        });

        // 4. Harp Construction
        const harpGroup = new THREE.Group();
        scene.add(harpGroup);

        // Base (Soundboard) - A curved shape
        const baseCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(-2.5, 0, 0),
            new THREE.Vector3(-2.5, 0.5, 0.5),
            new THREE.Vector3(0, 0.5, 0.5),
            new THREE.Vector3(2.5, 0.5, 0.5),
            new THREE.Vector3(2.5, 0, 0)
        ]);
        const baseGeo = new THREE.TubeGeometry(baseCurve, 20, 0.15, 8, false);
        const baseMesh = new THREE.Mesh(baseGeo, silverMaterial);
        baseMesh.castShadow = true;
        harpGroup.add(baseMesh);

        // Pillar
        const pillarGeo = new THREE.CylinderGeometry(0.15, 0.2, 5, 16);
        const pillarMesh = new THREE.Mesh(pillarGeo, silverMaterial);
        pillarMesh.position.set(-2.5, 2.5, 0.25);
        pillarMesh.castShadow = true;
        harpGroup.add(pillarMesh);

        // Neck (Curved top part)
        const neckCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(-2.5, 5, 0.25), // Top of pillar
            new THREE.Vector3(-1.5, 5.5, 0.25),
            new THREE.Vector3(0, 5.5, 0.25),
            new THREE.Vector3(2.5, 4.5, 0.25) // Top of base
        ]);
        const neckGeo = new THREE.TubeGeometry(neckCurve, 20, 0.12, 8, false);
        const neckMesh = new THREE.Mesh(neckGeo, silverMaterial);
        neckMesh.castShadow = true;
        harpGroup.add(neckMesh);

        // Strings
        const strings = [];
        const numStrings = 20;

        for (let i = 0; i < numStrings; i++) {
            const t = i / (numStrings - 1); // 0 to 1 along the curve

            // Calculate start point (on the neck curve)
            // We approximate the neck curve points for string attachment
            const neckPoint = neckCurve.getPoint(t);

            // Calculate end point (on the base)
            // The base goes from x=-2.5 to x=2.5 roughly
            const baseX = -2.5 + (t * 5); 
            const basePoint = new THREE.Vector3(baseX, 0.1, 0.25);

            const length = neckPoint.distanceTo(basePoint);
            const stringGeo = new THREE.CylinderGeometry(0.01, 0.01, length, 4);
            const stringMesh = new THREE.Mesh(stringGeo, stringMaterial);

            // Position string at midpoint
            const midPoint = new THREE.Vector3().addVectors(neckPoint, basePoint).multiplyScalar(0.5);
            stringMesh.position.copy(midPoint);

            // Orient string
            stringMesh.lookAt(neckPoint);
            stringMesh.rotateX(Math.PI / 2); // Cylinder is vertical by default, we need it to align with lookAt logic or just rotate

            // Store data for animation
            stringMesh.userData = {
                originalPos: midPoint.clone(),
                neckPoint: neckPoint,
                basePoint: basePoint,
                offset: Math.random() * Math.PI * 2,
                frequency: 2 + Math.random() * 3
            };

            harpGroup.add(stringMesh);
            strings.push(stringMesh);
        }

        // 5. Wind Particles
        const particleCount = 200;
        const particlesGeo = new THREE.BufferGeometry();
        const particlePositions = new Float32Array(particleCount * 3);
        const particleSpeeds = new Float32Array(particleCount);

        for(let i=0; i<particleCount; i++) {
            particlePositions[i*3] = (Math.random() - 0.5) * 20; // x
            particlePositions[i*3+1] = Math.random() * 10; // y
            particlePositions[i*3+2] = (Math.random() - 0.5) * 10; // z
            particleSpeeds[i] = 0.02 + Math.random() * 0.05;
        }

        particlesGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));

        const particleMat = new THREE.PointsMaterial({
            color: 0xaaccff,
            size: 0.05,
            transparent: true,
            opacity: 0.6
        });

        const windParticles = new THREE.Points(particlesGeo, particleMat);
        scene.add(windParticles);

        // 6. Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Animate Strings (Wind playing the harp)
            strings.forEach((str) => {
                const data = str.userData;
                // Vibrate the string slightly perpendicular to its length
                // Simple approximation: move X slightly based on sine wave
                const vibration = Math.sin(time * data.frequency + data.offset) * 0.05;

                // We modify the position slightly. 
                // Since the strings are oriented, moving X in local space is tricky.
                // Let's just wiggle the whole mesh slightly in world space X
                str.position.x = data.originalPos.x + vibration;

                // Add a slight rotation to simulate bending
                str.rotation.z = Math.sin(time * data.frequency + data.offset) * 0.05;
            });

            // Animate Wind Particles
            const positions = windParticles.geometry.attributes.position.array;
            for(let i=0; i<particleCount; i++) {
                positions[i*3] += particleSpeeds[i]; // Move right

                // Reset if out of bounds
                if(positions[i*3] > 10) {
                    positions[i*3] = -10;
                    positions[i*3+1] = Math.random() * 8;
                }
            }
            windParticles.geometry.attributes.position.needsUpdate = true;

            // Gentle camera sway
            camera.position.x = Math.sin(time * 0.2) * 0.5;
            camera.lookAt(0, 2, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
