</head>
<body>
    <div id="info">lanterns releasing paper cranes</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510);
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 20);
        camera.lookAt(0, 5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft white light
        scene.add(ambientLight);

        // Materials
        const lanternBodyMat = new THREE.MeshStandardMaterial({ 
            color: 0xffaa00, 
            emissive: 0xff6600, 
            emissiveIntensity: 0.8,
            roughness: 0.4,
            metalness: 0.1
        });
        const lanternFrameMat = new THREE.MeshStandardMaterial({ color: 0x331100 });
        const craneMat = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 0.8,
            side: THREE.DoubleSide
        });

        // Helper: Create Lantern
        function createLantern() {
            const group = new THREE.Group();

            // Main body (cylinder)
            const bodyGeo = new THREE.CylinderGeometry(0.8, 0.8, 1.5, 16);
            const body = new THREE.Mesh(bodyGeo, lanternBodyMat);
            group.add(body);

            // Top cap
            const topGeo = new THREE.CylinderGeometry(0.2, 0.8, 0.2, 16);
            const top = new THREE.Mesh(topGeo, lanternFrameMat);
            top.position.y = 0.85;
            group.add(top);

            // Bottom cap
            const bottomGeo = new THREE.CylinderGeometry(0.8, 0.2, 0.2, 16);
            const bottom = new THREE.Mesh(bottomGeo, lanternFrameMat);
            bottom.position.y = -0.85;
            group.add(bottom);

            // Handle
            const handleGeo = new THREE.TorusGeometry(0.3, 0.05, 8, 16, Math.PI);
            const handle = new THREE.Mesh(handleGeo, lanternFrameMat);
            handle.position.y = 1.0;
            handle.rotation.x = Math.PI;
            group.add(handle);

            // Light inside
            const light = new THREE.PointLight(0xffaa00, 2, 8);
            light.position.set(0, 0, 0);
            group.add(light);

            return group;
        }

        // Helper: Create Paper Crane
        function createCrane() {
            const group = new THREE.Group();

            // Body (simple cone)
            const bodyGeo = new THREE.ConeGeometry(0.15, 0.6, 4);
            const body = new THREE.Mesh(bodyGeo, craneMat);
            body.rotation.x = Math.PI / 2; // Point forward
            group.add(body);

            // Wings (flat planes)
            const wingGeo = new THREE.PlaneGeometry(0.8, 0.2);
            const wingLeft = new THREE.Mesh(wingGeo, craneMat);
            wingLeft.position.set(0, 0.1, 0);
            wingLeft.rotation.x = -0.2;
            group.add(wingLeft);

            const wingRight = new THREE.Mesh(wingGeo, craneMat);
            wingRight.position.set(0, -0.1, 0);
            wingRight.rotation.x = 0.2;
            group.add(wingRight);

            return group;
        }

        // Objects Arrays
        const lanterns = [];
        const cranes = [];

        // Spawn Lanterns
        function spawnLantern() {
            const lantern = createLantern();
            // Random start position at bottom
            lantern.position.set(
                (Math.random() - 0.5) * 15,
                -5,
                (Math.random() - 0.5) * 10
            );
            // Random rotation
            lantern.rotation.z = (Math.random() - 0.5) * 0.2;
            lantern.rotation.x = (Math.random() - 0.5) * 0.2;

            // Custom properties for animation
            lantern.userData = {
                speed: 0.02 + Math.random() * 0.03,
                wobbleSpeed: 1 + Math.random() * 2,
                wobbleAmp: 0.5 + Math.random() * 0.5,
                releaseTimer: Math.random() * 100 // Delay before releasing crane
            };

            scene.add(lantern);
            lanterns.push(lantern);
        }

        // Spawn Crane from Lantern
        function spawnCrane(lantern) {
            const crane = createCrane();
            crane.position.copy(lantern.position);
            crane.position.y += 1; // Start slightly above lantern

            // Random direction
            const angle = Math.random() * Math.PI * 2;
            const speed = 0.1 + Math.random() * 0.1;

            crane.userData = {
                velocity: new THREE.Vector3(Math.cos(angle) * speed, 0.05, Math.sin(angle) * speed),
                life: 0,
                maxLife: 200 + Math.random() * 200
            };

            scene.add(crane);
            cranes.push(crane);
        }

        // Initial Lanterns
        for(let i=0; i<5; i++) {
            spawnLantern();
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            // Update Lanterns
            for (let i = lanterns.length - 1; i >= 0; i--) {
                const l = lanterns[i];

                // Float up
                l.position.y += l.userData.speed;

                // Wobble
                l.position.x += Math.sin(time * l.userData.wobbleSpeed) * 0.01 * l.userData.wobbleAmp;
                l.rotation.z = Math.sin(time * l.userData.wobbleSpeed) * 0.1;

                // Release Crane logic
                l.userData.releaseTimer--;
                if (l.userData.releaseTimer <= 0) {
                    spawnCrane(l);
                    l.userData.releaseTimer = 100 + Math.random() * 200; // Reset timer
                }

                // Remove if too high
                if (l.position.y > 20) {
                    scene.remove(l);
                    lanterns.splice(i, 1);
                    // Spawn a new one to keep the scene alive
                    spawnLantern();
                }
            }

            // Update Cranes
            for (let i = cranes.length - 1; i >= 0; i--) {
                const c = cranes[i];

                // Move
                c.position.add(c.userData.velocity);

                // Rotate to face velocity
                c.lookAt(c.position.clone().add(c.userData.velocity));

                // Flap wings (scale Y oscillation)
                const flap = Math.sin(time * 15) * 0.2;
                c.children[1].rotation.x = -0.2 + flap; // Left wing
                c.children[2].rotation.x = 0.2 - flap;  // Right wing

                // Fade out / Remove
                c.userData.life++;
                if (c.userData.life > c.userData.maxLife) {
                    scene.remove(c);
                    cranes.splice(i, 1);
                }
            }

            // Camera gentle movement
            camera.position.x = Math.sin(time * 0.1) * 2;
            camera.lookAt(0, 5, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
