        const handleGeo = new THREE.CylinderGeometry(0.15, 0.15, 1.5, 8);
        const handleMat = new THREE.MeshStandardMaterial({ color: 0x3d2817, roughness: 0.8 }); // Wood color
        const handle = new THREE.Mesh(handleGeo, handleMat);
