        const guardGeo = new THREE.BoxGeometry(1.2, 0.2, 0.4);
        const guardMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.8, roughness: 0.2 });
        const guard = new THREE.Mesh(guardGeo, guardMat);
        guard.position.y = -0.75;
        guard.castShadow = true;
        swordGroup.add(guard);

