        // Using a cone for the blade shape
        const bladeGeo = new THREE.ConeGeometry(0.4, 4, 4); // 4 sides for a faceted look
        const bladeMat = new THREE.MeshPhysicalMaterial({
            color: 0xaaddff,
            metalness: 0.1,
            roughness: 0.1,
            transmission: 0.9, // Glass-like
            thickness: 1.5,
            ior: 1.5,
