renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// Lights
const ambient = new THREE.AmbientLight(0x1a2a4a, 0.5);
scene.add(ambient);

const moonLight = new THREE.DirectionalLight(0x6688aa, 0.8);
moonLight.position.set(20, 40, 10);
scene.add(moonLight);

const shipGlow = new THREE.PointLight(0x44aaff, 2, 30);
shipGlow.position.set(0, 5, 0);
scene.add(shipGlow);

const underGlow = new THREE.PointLight(0x2266cc, 1.5, 20);
underGlow.position.set(0, -2, 0);
scene.add(underGlow);

// Water
const waterGeo = new THREE.PlaneGeometry(400, 400, 128, 128);
const waterMat = new THREE.MeshPhongMaterial({
    color: 0x0a1a2a,
    transparent: true,
    opacity: 0.85,
    shininess: 100,
    specular: 0x224466,
    flatShading: true
});
const water = new THREE.Mesh(waterGeo, waterMat);
water.rotation.x = -Math.PI / 2;
water.position.y = -2;
scene.add(water);

// Ship group
const ship = new THREE.Group();

// Hull
const hullShape = new THREE.Shape();
hullShape.moveTo(-4, 0);
hullShape.lineTo(-3.5, 2);
hullShape.lineTo(3, 2.5);
hullShape.lineTo(4.5, 1.5);
hullShape.lineTo(5, 0);
hullShape.lineTo(-4, 0);

const hullGeo = new THREE.ExtrudeGeometry(hullShape, {
    depth: 10, bevelEnabled: true, bevelThickness: 0.3,
    bevelSize: 0.3, bevelSegments: 3
});
const hullMat = new THREE.MeshPhongMaterial({
    color: 0x1a1a2e,
    emissive: 0x0a0a1a,
    transparent: true,
    opacity: 0.75,
    shininess: 30
});
const hull = new THREE.Mesh(hullGeo, hullMat);
hull.rotation.x = -Math.PI / 2;
hull.position.set(-5, -1.5, -5);
ship.add(hull);

// Deck
const deckGeo = new THREE.BoxGeometry(9, 0.2, 3.5);
const deckMat = new THREE.MeshPhongMaterial({
    color: 0x1a1a2e,
    emissive: 0x0a0a2a,
    transparent: true,
    opacity: 0.7
});
const deck = new THREE.Mesh(deckGeo, deckMat);
deck.position.set(0, 2.1, 0);
ship.add(deck);

// Mast
const mastGeo = new THREE.CylinderGeometry(0.08, 0.12, 14, 8);
const mastMat = new THREE.MeshPhongMaterial({
    color: 0x2a2a3e,
    emissive: 0x111133,
    transparent: true,
    opacity: 0.8
});
const mast = new THREE.Mesh(mastGeo, mastMat);
mast.position.set(-0.5, 9, 0);
ship.add(mast);

// Sails
function createSail(w, h, x, y, z, ry) {
    const geo = new THREE.PlaneGeometry(w, h, 4, 6);
    const mat = new THREE.MeshPhongMaterial({
        color: 0x88aacc,
        emissive: 0x3366aa,
        emissiveIntensity: 0.6,
        transparent: true,
        opacity: 0.35,
        side: THREE.DoubleSide,
        shininess: 5
    });
    const sail = new THREE.Mesh(geo, mat);
    sail.position.set(x, y, z);
    sail.rotation.y = ry || 0;
    sail.userData.origY = y;
    return sail;
}

const sails = [];
sails.push(createSail(5, 6, 0.5, 10, 0, 0));
sails.push(createSail(4, 5, -1.5, 7, 0, 0.1));
sails.push(createSail(3.5, 4, 2, 7.5, 0, -0.1));
sails.forEach(s => ship.add(s));

// Ghostly spectral particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);
for (let i = 0; i < particleCount; i++) {
    positions[i * 3] = (Math.random() - 0.5) * 20;
    positions[i * 3 + 1] = Math.random() * 20 - 2;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 12;
    sizes[i] = Math.random() * 3 + 1;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
