    size: 0.15,
    transparent: true,
    opacity: 0.6,
    blending: THREE.AdditiveBlending,
    depthWrite: false
});
const particles = new THREE.Points(particleGeo, particleMat);
ship.add(particles);

// Fog sprites (floating orbs)
const orbGeo = new THREE.SphereGeometry(0.3, 8, 8);
const orbMat = new THREE.MeshBasicMaterial({
    color: 0x4488cc,
    transparent: true,
    opacity: 0.3,
    blending: THREE.AdditiveBlending
});
const orbs = [];
for (let i = 0; i < 15; i++) {
    const orb = new THREE.Mesh(orbGeo, orbMat.clone());
    orb.position.set(
        (Math.random() - 0.5) * 50,
        Math.random() * 15,
        (Math.random() - 0.5) * 30
    );
    orb.userData.speed = Math.random() * 0.5 + 0.2;
    orb.userData.offset = Math.random() * Math.PI * 2;
    orb.userData.baseY = orb.position.y;
    scene.add(orb);
    orbs.push(orb);
}

ship.position.y = 0;
scene.add(ship);

// Camera orbit
let mouseX = 0, mouseY = 0;
document.addEventListener('mousemove', e => {
    mouseX = (e.clientX / innerWidth - 0.5) * 2;
    mouseY = (e.clientY / innerHeight - 0.5) * 2;
});

window.addEventListener('resize', () => {
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
});

const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();

    // Water wave animation
    const pos = waterGeo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i);
        const y = pos.getY(i);
        const z = Math.sin(x * 0.15 + t * 0.8) * 0.4 +
                  Math.cos(y * 0.12 + t * 0.6) * 0.3 +
                  Math.sin((x + y) * 0.08 + t * 1.2) * 0.2;
        pos.setZ(i, z);
    }
    pos.needsUpdate = true;
    waterGeo.computeVertexNormals();

    // Ship rocking
    ship.position.y = Math.sin(t * 0.5) * 0.4;
    ship.rotation.z = Math.sin(t * 0.4) * 0.03;
    ship.rotation.x = Math.sin(t * 0.3) * 0.02;
    ship.rotation.y = Math.sin(t * 0.15) * 0.1;

    // Sail animation
    sails.forEach((sail, i) => {
        const verts = sail.geometry.attributes.position;
        for (let j = 0; j < verts.count; j++) {
            const x = verts.getX(j);
            const y = verts.getY(j);
            const wave = Math.sin(y * 0.5 + t * 2 + i) * 0.3;
            verts.setZ(j, wave);
        }
        verts.needsUpdate = true;
        sail.geometry.computeVertexNormals();
    });

    // Particles drift
    const pPos = particles.geometry.attributes.position;
    for (let i = 0; i < particleCount; i++) {
        let y = pPos.getY(i);
        y += 0.01;
        if (y > 18) y = -2;
        pPos.setY(i, y);
        pPos.setX(i, pPos.getX(i) + Math.sin(t + i) * 0.003);
    }
    pPos.needsUpdate = true;

    // Orbs float
    orbs.forEach(orb => {
        orb.position.y = orb.userData.baseY + Math.sin(t * orb.userData.speed + orb.userData.offset) * 2;
        orb.position.x += Math.sin(t * 0.2 + orb.userData.offset) * 0.01;
        orb.material.opacity = 0.15 + Math.sin(t * orb.userData.speed * 2) * 0.15;
    });

    // Ship glow pulse
    shipGlow.intensity = 2 + Math.sin(t * 1.5) * 0.8;
    underGlow.intensity = 1.5 + Math.sin(t * 1.2 + 1) * 0.5;

    // Camera
    camera.position.x += (mouseX * 5 - camera.position.x) * 0.02;
    camera.position.y += (8 - mouseY * 3 - camera.position.y) * 0.02;
    camera.lookAt(0, 3, 0);

    renderer.render(scene, camera);
}

animate();
</script>
</body>
</html>
```

This creates an atmospheric scene featuring:

- **Spectral ship** — built from extruded hull, deck, mast, and billowing sails with semi-transparent, emissive materials that glow ethereal blue
- **Animated fog** — `FogExp2` creates dense atmospheric depth, plus floating luminous orbs that drift and pulse
- **Ghostly particles** — 300 additive-blended particles rise around the ship like spirits
- **Animated water** — a 128×128 subdivided plane with vertex-displaced sine waves
- **Sail flutter** — sail vertices ripple in the wind each frame
- **Ship motion** — gentle rocking, pitching, and yawing
- **Interactive camera** — move your mouse to orbit around the ship
- **Pulsing lights** — blue point lights beneath and above the ship breathe with ghostly intensity

