</script>
<script type="module">
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x050510, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Bloom ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.8, 0.6, 0.2
);
composer.addPass(bloom);

// ── Dandelion Group ──
const dandelion = new THREE.Group();
scene.add(dandelion);

// ── Fibonacci Sphere for seed placement ──
const NUM_SEEDS = 320;
const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
const SEED_RADIUS = 1.6;

const seedPositions = [];
for (let i = 0; i < NUM_SEEDS; i++) {
  const y = 1 - (i / (NUM_SEEDS - 1)) * 2;       // -1 to 1
  const radiusAtY = Math.sqrt(1 - y * y);
  const theta = GOLDEN_ANGLE * i;
  const x = Math.cos(theta) * radiusAtY;
  const z = Math.sin(theta) * radiusAtY;
  seedPositions.push(new THREE.Vector3(x, y, z));
}

// ── Seed Geometry (pappus filaments + center) ──
const filamentMat = new THREE.MeshBasicMaterial({
  color: 0xffe8c0,
  transparent: true,
  opacity: 0.75,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});

const centerMat = new THREE.MeshBasicMaterial({
  color: 0xfff5e0,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});

const FILAMENT_COUNT = 8;
const FILAMENT_LENGTH = 0.55;

// Shared geometries
const filamentGeo = new THREE.CylinderGeometry(0.003, 0.001, FILAMENT_LENGTH, 3);
const centerGeo = new THREE.SphereGeometry(0.035, 6, 6);

for (let i = 0; i < NUM_SEEDS; i++) {
  const dir = seedPositions[i].clone();
  const pos = dir.clone().multiplyScalar(SEED_RADIUS);

  const seedGroup = new THREE.Group();
  seedGroup.position.copy(pos);

  // Center dot
  const center = new THREE.Mesh(centerGeo, centerMat.clone());
  seedGroup.add(center);

  // Filaments radiating outward
  const up = dir.clone().normalize();
  for (let f = 0; f < FILAMENT_COUNT; f++) {
    const angle = (f / FILAMENT_COUNT) * Math.PI * 2 + (Math.random() - 0.5) * 0.4;
    const spread = 0.25 + Math.random() * 0.2;

    const filament = new THREE.Mesh(filamentGeo, filamentMat.clone());
    filament.lookAt(up);
    filament.rotateX(Math.PI / 2);
    filament.rotateZ((Math.random() - 0.5) * spread);
    filament.rotateY(angle);
    filament.position.copy(up.clone().multiplyScalar(FILAMENT_LENGTH * 0.45));
    filament.userData.baseAngle = angle;
    filament.userData.spread = spread;
    seedGroup.add(filament);
  }

  // Slight random scale variation
  const s = 0.8 + Math.random() * 0.5;
  seedGroup.scale.setScalar(s);

  // Store data for animation
  seedGroup.userData = {
    basePos: pos.clone(),
    dir: dir.clone(),
    phase: Math.random() * Math.PI * 2,
    freq: 0.5 + Math.random() * 1.5,
    amp: 0.02 + Math.random() * 0.04,
    detached: false,
    detachTime: 0,
    driftVel: new THREE.Vector3(
      (Math.random() - 0.5) * 0.003,
      (Math.random() - 0.5) * 0.003 + 0.002,
      (Math.random() - 0.5) * 0.003
    ),
  };

  dandelion.add(seedGroup);
}

// ── Central stem ──
const stemGeo = new THREE.CylinderGeometry(0.02, 0.035, 2.5, 8);
const stemMat = new THREE.MeshBasicMaterial({
  color: 0x88aa66,
  transparent: true,
  opacity: 0.4,
  blending: THREE.AdditiveBlending,
});
const stem = new THREE.Mesh(stemGeo, stemMat);
stem.position.y = -1.25;
dandelion.add(stem);

// ── Ambient particles (floating spores) ──
const PARTICLE_COUNT = 200;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(PARTICLE_COUNT * 3);
const particleSizes = new Float32Array(PARTICLE_COUNT);
const particlePhases = [];

for (let i = 0; i < PARTICLE_COUNT; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 2 + Math.random() * 6;
  particlePositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  particlePositions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  particlePositions[i * 3 + 2] = r * Math.cos(phi);
  particleSizes[i] = Math.random() * 3 + 1;
  particlePhases.push(Math.random() * Math.PI * 2);
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(particleSizes, 1));

const particleMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0xffd080) },
  },
  vertexShader: `
    attribute float size;
    uniform float uTime;
    varying float vAlpha;
    void main() {
      vec3 p = position;
      p.y += sin(uTime * 0.3 + position.x * 2.0) * 0.15;
      p.x += cos(uTime * 0.2 + position.z * 1.5) * 0.1;
      vAlpha = 0.3 + 0.3 * sin(uTime + position.y * 3.0);
      vec4 mv = modelViewMatrix * vec4(p, 1.0);
      gl_PointSize = size * (200.0 / -mv.z);
      gl_Position = projectionMatrix * mv;
    }
  `,
  fragmentShader: `
    uniform vec3 uColor;
    varying float vAlpha;
    void main() {
      float d = length(gl_PointCoord - 0.5) * 2.0;
      float glow = exp(-d * 3.0);
      gl_FragColor = vec4(uColor, glow * vAlpha);
    }
  `,
  transparent: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Mouse interaction ──
const mouse = { x: 0, y: 0 };
window.addEventListener('mousemove', (e) => {
  mouse.x = (e.clientX / innerWidth - 0.5) * 2;
  mouse.y = (e.clientY / innerHeight - 0.5) * 2;
});

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const dt = clock.getDelta();

  // Gentle rotation
  dandelion.rotation.y = t * 0.15;
  dandelion.rotation.x = Math.sin(t * 0.1) * 0.1;

  // Camera follows mouse slightly
  camera.position.x += (mouse.x * 1.5 - camera.position.x) * 0.02;
  camera.position.y += (1.5 - mouse.y * 1.0 - camera.position.y) * 0.02;
  camera.lookAt(0, 0, 0);

  // Animate seeds (breathing / gentle sway)
  dandelion.children.forEach((child) => {
    if (!child.userData.dir) return;
    const ud = child.userData;

    if (!ud.detached) {
      // Breathing motion
      const breathe = Math.sin(t * ud.freq + ud.phase) * ud.amp;
      const sway = Math.sin(t * 0.5 + ud.phase) * 0.02;

      child.position.copy(ud.basePos);
      child.position.addScaledVector(ud.dir, breathe);
      child.rotation.x = sway;
      child.rotation.z = sway * 0.7;

      // Slowly detach some seeds over time
      if (t > 3 + ud.phase * 2 && !ud.detached) {
        ud.detached = true;
        ud.detachTime = t;
      }
    } else {
      // Drift away
      const elapsed = t - ud.detachTime;
      child.position.add(ud.driftVel);
      child.position.y += elapsed * 0.005;
      child.rotation.x += 0.01;
      child.rotation.z += 0.008;
      child.scale.multiplyScalar(0.999);

      // Reset if too far
      if (child.position.length() > 15) {
        const idx = seedPositions.indexOf(ud.dir);
        ud.detached = false;
        child.position.copy(ud.basePos);
        child.scale.setScalar(0.8 + Math.random() * 0.5);
      }
    }
  });

  // Update particles
  particleMat.uniforms.uTime.value = t;

  // Pulsing bloom
  bloom.strength = 1.6 + Math.sin(t * 0.8) * 0.3;

  composer.render();
}

animate();
</script>
</body>
</html>
