<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Jellyfish Lantern</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #000; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x020010, 0.035);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post Processing (Bloom) ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 1.5, 0.4, 0.85);
bloom.threshold = 0.1;
bloom.strength = 2.0;
bloom.radius = 0.8;
composer.addPass(bloom);

// ── Jellyfish Bell (Lathe) ──
const bellProfile = [];
for (let i = 0; i <= 20; i++) {
  const t = i / 20;
  const angle = t * Math.PI;
  const r = Math.sin(angle) * 1.8 * (1.0 - t * 0.15);
  const y = Math.cos(angle) * 1.2 + 1.2;
  bellProfile.push(new THREE.Vector2(r, y));
}
// Add rim flare
for (let i = 0; i <= 8; i++) {
  const t = i / 8;
  bellProfile.push(new THREE.Vector2(1.8 + t * 0.6, 1.2 - t * 0.3 - Math.sin(t * Math.PI) * 0.25));
}

const bellGeo = new THREE.LatheGeometry(bellProfile, 64);
const bellMat = new THREE.MeshPhysicalMaterial({
  color: 0xff6600,
  emissive: 0xff4400,
  emissiveIntensity: 0.6,
  transparent: true,
  opacity: 0.35,
  roughness: 0.1,
  metalness: 0.0,
  side: THREE.DoubleSide,
  transmission: 0.6,
  thickness: 0.5,
});
const bell = new THREE.Mesh(bellGeo, bellMat);
scene.add(bell);

// ── Inner Glow Sphere ──
const glowGeo = new THREE.SphereGeometry(1.0, 32, 32);
const glowMat = new THREE.MeshBasicMaterial({
  color: 0xff8833,
  transparent: true,
  opacity: 0.25,
});
const innerGlow = new THREE.Mesh(glowGeo, glowMat);
innerGlow.position.y = 1.4;
scene.add(innerGlow);

// ── Core Light ──
const coreLight = new THREE.PointLight(0xff6622, 15, 12, 1.5);
coreLight.position.y = 1.4;
scene.add(coreLight);

const coreLight2 = new THREE.PointLight(0xff3300, 8, 6, 2);
coreLight2.position.y = 1.0;
scene.add(coreLight2);

// ── Tentacles ──
const TENTACLE_COUNT = 18;
const tentacles = [];

function createTentacle(index) {
  const angle = (index / TENTACLE_COUNT) * Math.PI * 2;
  const radius = 1.5 + Math.random() * 0.3;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;
  const y = 0.9;

  const segments = 24;
  const points = [];
  const length = 2.5 + Math.random() * 2.0;

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    points.push(new THREE.Vector3(
      x + Math.sin(t * 2) * 0.1,
      y - t * length,
      z + Math.cos(t * 2) * 0.1
    ));
  }

  const curve = new THREE.CatmullRomCurve3(points);
  const tubeGeo = new THREE.TubeGeometry(curve, 32, 0.03 + Math.random() * 0.02, 8, false);

  const hue = 0.05 + Math.random() * 0.08;
  const color = new THREE.Color().setHSL(hue, 1.0, 0.5);
  const mat = new THREE.MeshPhysicalMaterial({
    color,
    emissive: color,
    emissiveIntensity: 0.8,
    transparent: true,
    opacity: 0.65,
    roughness: 0.2,
    transmission: 0.3,
    thickness: 0.3,
  });

  const mesh = new THREE.Mesh(tubeGeo, mat);
  mesh.userData = { angle, radius, baseY: y, length, phase: Math.random() * Math.PI * 2, speed: 0.6 + Math.random() * 0.4 };
  return mesh;
}

for (let i = 0; i < TENTACLE_COUNT; i++) {
  const t = createTentacle(i);
  tentacles.push(t);
  scene.add(t);
}

// ── Floating Particles ──
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 15;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
  sizes[i] = Math.random() * 3 + 1;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xff8844,
  size: 0.05,
  transparent: true,
  opacity: 0.4,
  blending: THREE.AdditiveBlending,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Ambient Light ──
scene.add(new THREE.AmbientLight(0x110505, 0.5));

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Bell bob
  bell.position.y = Math.sin(t * 0.8) * 0.3;
  innerGlow.position.y = 1.4 + Math.sin(t * 0.8) * 0.3;
  coreLight.position.y = 1.4 + Math.sin(t * 0.8) * 0.3;
  coreLight2.position.y = 1.0 + Math.sin(t * 0.8) * 0.3;

  // Pulse glow
  const pulse = 0.5 + Math.sin(t * 2) * 0.15;
  coreLight.intensity = 15 * pulse;
  coreLight2.intensity = 8 * pulse;
  glowMat.opacity = 0.2 + Math.sin(t * 2) * 0.08;
  bellMat.emissiveIntensity = 0.5 + Math.sin(t * 1.5) * 0.2;

  // Animate tentacles
  tentacles.forEach((tentacle, i) => {
    const { phase, speed, length, baseY } = tentacle.userData;
    const pos = tentacle.geometry.attributes.position;
    const segCount = pos.count;

    // Rebuild curve for animation
    const angle = tentacle.userData.angle;
    const radius = tentacle.userData.radius;
    const x0 = Math.cos(angle) * radius;
    const z0 = Math.sin(angle) * radius;
    const segments = 24;

    const newPoints = [];
    for (let i = 0; i <= segments; i++) {
      const tt = i / segments;
      const wave = Math.sin(t * speed + phase + tt * 3) * 0.2 * tt;
      const wave2 = Math.cos(t * speed * 0.7 + phase + tt * 2.5) * 0.15 * tt;
      newPoints.push(new THREE.Vector3(
        x0 + wave,
        baseY + Math.sin(t * 0.8) * 0.3 - tt * length,
        z0 + wave2
      ));
    }

    const curve = new THREE.CatmullRomCurve3(newPoints);
    const newGeo = new THREE.TubeGeometry(curve, 32, 0.03, 8, false);
    tentacle.geometry.dispose();
    tentacle.geometry = newGeo;
  });

  // Particles drift
  const pPos = particles.geometry.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    pPos.array[i * 3 + 1] += Math.sin(t + i) * 0.001;
    pPos.array[i * 3] += Math.cos(t * 0.5 + i * 0.1) * 0.0005;
  }
  pPos.needsUpdate = true;

  // Camera orbit
  camera.position.x = Math.sin(t * 0.15) * 3;
  camera.position.z = 8 + Math.cos(t * 0.15) * 2;
  camera.lookAt(0, 1.5, 0);

  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
