<body>
    <div id="info">⚙ Mechanical Hummingbird Feeder ⚙</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a1a);
        scene.fog = new THREE.Fog(0x1a1a1a, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffeeb1, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xff0000, 0.5, 10);
        pointLight.position.set(0, 0, 0);
        scene.add(pointLight);

        // Materials
        const metalMat = new THREE.MeshStandardMaterial({ 
            color: 0x888888, 
            metalness: 0.8, 
            roughness: 0.2 
        });
        const darkMetalMat = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            metalness: 0.9, 
            roughness: 0.4 
        });
        const glassMat = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.9,
            thickness: 0.5,
            transparent: true,
            opacity: 0.3
        });
        const nectarMat = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            emissive: 0x550000,
            roughness: 0.2
        });
        const copperMat = new THREE.MeshStandardMaterial({
            color: 0xb87333,
            metalness: 0.7,
            roughness: 0.3
        });

        // Group for the whole feeder
        const feederGroup = new THREE.Group();
        scene.add(feederGroup);

        // 1. Base
        const baseGeo = new THREE.CylinderGeometry(1.5, 1.8, 0.5, 32);
        const base = new THREE.Mesh(baseGeo, darkMetalMat);
        base.position.y = -1.5;
        base.castShadow = true;
        feederGroup.add(base);

        // 2. Reservoir (Glass)
        const reservoirGeo = new THREE.CylinderGeometry(1.2, 1.2, 3, 32, 1, true);
        const reservoir = new THREE.Mesh(reservoirGeo, glassMat);
        reservoir.position.y = 0;
        feederGroup.add(reservoir);

        // 3. Nectar (Liquid inside)
        const nectarGeo = new THREE.CylinderGeometry(1.1, 1.1, 2.5, 32);
        const nectar = new THREE.Mesh(nectarGeo, nectarMat);
        nectar.position.y = -0.2;
        feederGroup.add(nectar);

        // 4. Top Cap
        const capGeo = new THREE.CylinderGeometry(1.3, 1.2, 0.4, 32);
        const cap = new THREE.Mesh(capGeo, metalMat);
        cap.position.y = 1.7;
        cap.castShadow = true;
        feederGroup.add(cap);

        // 5. Mechanical Gears (External)
        const gearGroup = new THREE.Group();
        feederGroup.add(gearGroup);

        function createGear(radius, thickness, teeth) {
            const gearGeo = new THREE.CylinderGeometry(radius, radius, thickness, teeth * 2);
            // Modify vertices to look like teeth? Too complex for simple geo. 
            // Let's use a Torus for the rim and a cylinder for the body.
            const body = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.8, radius * 0.8, thickness, 16), copperMat);
            const rim = new THREE.Mesh(new THREE.TorusGeometry(radius, thickness/3, 8, teeth), copperMat);
            rim.rotation.x = Math.PI / 2;

            const group = new THREE.Group();
            group.add(body);
            group.add(rim);
            return group;
        }

        const gear1 = createGear(0.8, 0.3, 12);
        gear1.position.set(1.4, 0.5, 0);
        gear1.rotation.z = Math.PI / 2;
        gearGroup.add(gear1);

        const gear2 = createGear(0.5, 0.3, 8);
        gear2.position.set(2.0, 0.5, 0);
        gear2.rotation.z = Math.PI / 2;
        gearGroup.add(gear2);

        const gear3 = createGear(0.6, 0.3, 10);
        gear3.position.set(1.4, -0.2, 0);
        gear3.rotation.z = Math.PI / 2;
        gearGroup.add(gear3);

        // 6. Piston Mechanism (Internal/Visible through glass)
        const pistonGroup = new THREE.Group();
        feederGroup.add(pistonGroup);

        const pistonRodGeo = new THREE.CylinderGeometry(0.1, 0.1, 2.5, 16);
        const pistonRod = new THREE.Mesh(pistonRodGeo, metalMat);
        pistonRod.position.y = 0;
        pistonGroup.add(pistonRod);

        const pistonHeadGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.2, 16);
        const pistonHead = new THREE.Mesh(pistonHeadGeo, darkMetalMat);
        pistonHead.position.y = -1.0;
        pistonGroup.add(pistonHead);

        // 7. Feeding Ports (Nozzles)
        const nozzleGeo = new THREE.ConeGeometry(0.2, 0.6, 16);
        const nozzlePositions = [
            { x: 0, z: 1.2, rotX: 0 },
            { x: 0.85, z: 0.85, rotX: 0 },
            { x: -0.85, z: 0.85, rotX: 0 },
            { x: 0.85, z: -0.85, rotX: 0 },
            { x: -0.85, z: -0.85, rotX: 0 }
        ];

        const nozzles = [];
        nozzlePositions.forEach(pos => {
            const nozzle = new THREE.Mesh(nozzleGeo, copperMat);
            nozzle.position.set(pos.x, 0.5, pos.z);
            // Point outwards
            const angle = Math.atan2(pos.z, pos.x);
            nozzle.rotation.x = Math.PI / 2;
            nozzle.rotation.y = -angle;
            feederGroup.add(nozzle);
            nozzles.push(nozzle);
        });

        // 8. Decorative Pipes
        const pipeCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, -1.5, 1.5),
            new THREE.Vector3(0.5, -1.5, 2),
            new THREE.Vector3(1, -1, 2),
            new THREE.Vector3(1.4, 0.5, 0) // Connects to gear
        ]);
        const pipeGeo = new THREE.TubeGeometry(pipeCurve, 20, 0.05, 8, false);
        const pipe = new THREE.Mesh(pipeGeo, darkMetalMat);
        feederGroup.add(pipe);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate Gears
            gear1.rotation.y = time * 2;
            gear2.rotation.y = -time * 3.2; // Different speed/direction
            gear3.rotation.y = time * 2.6;

            // Move Piston
            const pistonY = Math.sin(time * 5) * 0.5;
            pistonGroup.position.y = pistonY;

            // Subtle hover for the whole feeder
            feederGroup.position.y = Math.sin(time * 0.5) * 0.1;
            feederGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
