<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Crystal Butterfly on a Leaf</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight1 = new THREE.PointLight(0x00ffff, 5, 20);
        pointLight1.position.set(-5, 2, 0);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xff00ff, 5, 20);
        pointLight2.position.set(5, 2, 0);
        scene.add(pointLight2);

        // Environment Map (Simple procedural one for reflections)
        const cubeRenderTarget = new THREE.WebGLCubeRenderTarget(256);
        const cubeCamera = new THREE.CubeCamera(0.1, 100, cubeRenderTarget);
        scene.add(cubeCamera);

        // Materials
        const leafMaterial = new THREE.MeshStandardMaterial({
            color: 0x2d5a27,
            roughness: 0.6,
            metalness: 0.1,
            side: THREE.DoubleSide
        });

        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 1.0,
            ior: 1.5,
            envMap: cubeRenderTarget.texture,
            envMapIntensity: 1.0,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9
        });

        // Leaf Geometry
        function createLeaf() {
            const shape = new THREE.Shape();
            shape.moveTo(0, 0);
            shape.bezierCurveTo(0.5, 1, 1, 2, 0, 3);
            shape.bezierCurveTo(-1, 2, -0.5, 1, 0, 0);

            const extrudeSettings = {
                steps: 2,
                depth: 0.05,
                bevelEnabled: true,
                bevelThickness: 0.02,
                bevelSize: 0.02,
                bevelSegments: 2
            };

            const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            geometry.center();
            geometry.rotateX(-Math.PI / 2); // Lay flat

            // Add some curvature
            const posAttribute = geometry.attributes.position;
            for (let i = 0; i < posAttribute.count; i++) {
                const x = posAttribute.getX(i);
                const y = posAttribute.getY(i); // This is actually Z in local space before rotation
                const z = posAttribute.getZ(i);

                // Curve the leaf slightly upwards
                const curve = Math.sin(x * 0.5) * 0.5;
                posAttribute.setZ(i, z + curve);
            }
            geometry.computeVertexNormals();

            const leaf = new THREE.Mesh(geometry, leafMaterial);
            leaf.scale.set(2, 2, 2);
            leaf.position.y = -0.5;
            return leaf;
        }

        // Butterfly Geometry
        function createButterfly() {
            const butterflyGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.CapsuleGeometry(0.1, 1.5, 4, 8);
            const body = new THREE.Mesh(bodyGeo, crystalMaterial);
            body.rotation.z = Math.PI / 2;
            butterflyGroup.add(body);

            // Antennae
            const antennaCurve = new THREE.CatmullRomCurve3([
                new THREE.Vector3(0, 0.7, 0),
                new THREE.Vector3(0.2, 1.2, 0.2),
                new THREE.Vector3(0.5, 1.5, 0)
            ]);
            const antennaGeo = new THREE.TubeGeometry(antennaCurve, 8, 0.02, 4, false);
            const antenna1 = new THREE.Mesh(antennaGeo, crystalMaterial);
            const antenna2 = antenna1.clone();
            antenna2.scale.x = -1; // Mirror
            butterflyGroup.add(antenna1);
            butterflyGroup.add(antenna2);

            // Wings
            function createWing(scaleX, scaleY, offsetX, offsetY, rotZ) {
                const wingShape = new THREE.Shape();
                wingShape.moveTo(0, 0);
                wingShape.bezierCurveTo(0.5, 0.5, 1.5, 0.5, 2, 0);
                wingShape.bezierCurveTo(1.5, -0.5, 0.5, -0.5, 0, 0);

                const wingGeo = new THREE.ExtrudeGeometry(wingShape, {
                    depth: 0.05,
                    bevelEnabled: true,
                    bevelThickness: 0.05,
                    bevelSize: 0.05,
                    bevelSegments: 2
                });

                const wing = new THREE.Mesh(wingGeo, crystalMaterial);
                wing.position.set(offsetX, offsetY, 0);
                wing.rotation.z = rotZ;
                wing.scale.set(scaleX, scaleY, 1);
                return wing;
            }

            // Upper Wings
            const upperLeft = createWing(1, 1, 0.2, 0.2, -0.2);
            const upperRight = createWing(1, 1, -0.2, 0.2, Math.PI + 0.2);

            // Lower Wings
            const lowerLeft = createWing(0.8, 0.8, 0.2, -0.3, -0.5);
            const lowerRight = createWing(0.8, 0.8, -0.2, -0.3, Math.PI + 0.5);

            butterflyGroup.add(upperLeft);
            butterflyGroup.add(upperRight);
            butterflyGroup.add(lowerLeft);
            butterflyGroup.add(lowerRight);

            return butterflyGroup;
        }

        const leaf = createLeaf();
        scene.add(leaf);

        const butterfly = createButterfly();
        butterfly.position.set(0, 0.5, 0);
        scene.add(butterfly);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle floating animation for butterfly
            butterfly.position.y = 0.5 + Math.sin(time * 1.5) * 0.1;
            butterfly.rotation.y = Math.sin(time * 0.5) * 0.1;

            // Wing flapping (subtle)
            butterfly.children.forEach((child, index) => {
                if (index > 2) { // Skip body and antennae
                    child.rotation.z += Math.sin(time * 10) * 0.002;
                }
            });

            // Update environment map occasionally for reflections
            if (Math.floor(time * 10) % 5 === 0) {
                butterfly.visible = false;
                cubeCamera.position.copy(butterfly.position);
                cubeCamera.update(renderer, scene);
                butterfly.visible = true;
            }

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
