        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x4444ff, 0.5);
        pointLight.position.set(-5, 5, -5);
        scene.add(pointLight);

        // Materials
        const whiteMat = new THREE.MeshStandardMaterial({ 
            color: 0xeeeeee, 
            roughness: 0.2, 
            metalness: 0.1 
        });
        const blackMat = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            roughness: 0.2, 
            metalness: 0.1 
        });
        const boardWhiteMat = new THREE.MeshStandardMaterial({ color: 0xe0e0e0 });
        const boardBlackMat = new THREE.MeshStandardMaterial({ color: 0x444444 });

        // Group for the whole board assembly
        const boardGroup = new THREE.Group();
        scene.add(boardGroup);

        // Create Chessboard
        const squareSize = 1;
        const boardSize = 8;
        const offset = (boardSize * squareSize) / 2 - squareSize / 2;

        for (let x = 0; x < boardSize; x++) {
            for (let z = 0; z < boardSize; z++) {
                const isWhite = (x + z) % 2 === 0;
                const geometry = new THREE.BoxGeometry(squareSize, 0.2, squareSize);
                const material = isWhite ? boardWhiteMat : boardBlackMat;
                const square = new THREE.Mesh(geometry, material);

                square.position.set(x * squareSize - offset, 0, z * squareSize - offset);
                square.receiveShadow = true;
                boardGroup.add(square);
            }
        }

        // Helper to create piece geometry
        function createPieceGeometry(type) {
            const group = new THREE.Group();
            const baseGeo = new THREE.CylinderGeometry(0.3, 0.35, 0.1, 32);
            const base = new THREE.Mesh(baseGeo);
            base.position.y = 0.05;
            base.castShadow = true;
            group.add(base);

            const stemGeo = new THREE.CylinderGeometry(0.15, 0.25, 0.4, 16);
            const stem = new THREE.Mesh(stemGeo);
            stem.position.y = 0.3;
            stem.castShadow = true;
            group.add(stem);

            let head;
            switch (type) {
                case 'pawn':
                    head = new THREE.Mesh(new THREE.SphereGeometry(0.2, 16, 16));
                    head.position.y = 0.6;
                    break;
                case 'rook':
                    head = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.3, 0.4));
                    head.position.y = 0.6;
                    break;
                case 'knight':
                    head = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.2, 0.4, 8));
                    head.position.y = 0.6;
                    head.rotation.z = 0.5;
                    break;
                case 'bishop':
                    head = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.4, 16));
                    head.position.y = 0.7;
                    break;
                case 'queen':
                    head = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16));
                    head.position.y = 0.7;
                    const crown = new THREE.Mesh(new THREE.TorusGeometry(0.15, 0.05, 8, 16));
                    crown.position.y = 0.85;
                    crown.rotation.x = Math.PI / 2;
                    group.add(crown);
                    break;
                case 'king':
                    head = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.5, 16));
                    head.position.y = 0.7;
                    const crossV = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.2, 0.05));
                    crossV.position.y = 1.05;
                    const crossH = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.05, 0.05));
                    crossH.position.y = 1.05;
                    group.add(crossV);
                    group.add(crossH);
                    break;
            }
            if (head) {
                head.castShadow = true;
                group.add(head);
            }
            return group;
        }

        // Place Pieces
        const pieces = [];
        const pieceOrder = ['rook', 'knight', 'bishop', 'queen', 'king', 'bishop', 'knight', 'rook'];

        function placePieces(row, colorMat, isFlipped) {
            for (let i = 0; i < 8; i++) {
                let type;
                if (row === 0 || row === 7) {
                    type = isFlipped ? pieceOrder[7 - i] : pieceOrder[i];
                } else {
                    type = 'pawn';
                }

                const pieceGroup = createPieceGeometry(type);
                pieceGroup.traverse(child => {
                    if (child.isMesh) {
                        child.material = colorMat;
                    }
                });

                // Position
                const x = i * squareSize - offset;
                const z = row * squareSize - offset;
                pieceGroup.position.set(x, 0.1, z);

                // Store initial data for animation
                pieceGroup.userData = {
                    initialY: 0.1,
                    phase: Math.random() * Math.PI * 2,
                    speed: 0.5 + Math.random() * 0.5,
                    rotSpeed: (Math.random() - 0.5) * 0.02
                };

                boardGroup.add(pieceGroup);
                pieces.push(pieceGroup);
            }
        }

        // Back row (Black)
        placePieces(0, blackMat, false);
        // Pawns (Black)
        placePieces(1, blackMat, false);

        // Pawns (White)
        placePieces(6, whiteMat, false);
        // Back row (White)
        placePieces(7, whiteMat, true);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Animate Board (Floating)
            boardGroup.position.y = Math.sin(time * 0.5) * 0.2;
            boardGroup.rotation.y = Math.sin(time * 0.1) * 0.05;

            // Animate Pieces (Living)
            pieces.forEach(piece => {
                const { initialY, phase, speed, rotSpeed } = piece.userData;

                // Bobbing up and down
                piece.position.y = initialY + Math.sin(time * speed + phase) * 0.15;

                // Slight rotation
                piece.rotation.y += rotSpeed;

                // Slight tilt
                piece.rotation.z = Math.sin(time * speed + phase) * 0.05;
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
