        camera.position.set(0, 2, 6);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x222222);
        scene.add(ambientLight);

        // --- Bonsai Construction ---
        const bonsaiGroup = new THREE.Group();
        scene.add(bonsaiGroup);

        // Pot
        const potGeometry = new THREE.CylinderGeometry(0.8, 0.6, 0.8, 16);
        const potMaterial = new THREE.MeshStandardMaterial({ color: 0x3d2817, roughness: 0.9 });
        const pot = new THREE.Mesh(potGeometry, potMaterial);
        pot.position.y = -0.4;
        bonsaiGroup.add(pot);

        // Trunk
        const trunkGeometry = new THREE.CylinderGeometry(0.1, 0.2, 2.5, 8);
        const trunkMaterial = new THREE.MeshStandardMaterial({ color: 0x4a3c31, roughness: 0.8 });
        const trunk = new THREE.Mesh(trunkGeometry, trunkMaterial);
        trunk.position.y = 1.25;
        bonsaiGroup.add(trunk);

        // Branches and Leaves
        const branchMaterial = new THREE.MeshStandardMaterial({ color: 0x4a3c31 });
        const leafMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ff00,
            emissive: 0x00ff00,
            emissiveIntensity: 0.8,
            roughness: 0.4
        });

        function createBranch(parent, height, angleX, angleZ, length) {
            const branchGeo = new THREE.CylinderGeometry(0.04, 0.08, length, 6);
            const branch = new THREE.Mesh(branchGeo, branchMaterial);
            branch.position.y = height;
            branch.rotation.x = angleX;
            branch.rotation.z = angleZ;
            parent.add(branch);

            // Leaf cluster at the end
            const leafGeo = new THREE.SphereGeometry(0.4, 8, 8);
            const leaf = new THREE.Mesh(leafGeo, leafMaterial);

            // Approximate end position
            const endY = height + (length/2) * Math.cos(angleX);
            const endX = (length/2) * Math.sin(angleX);
            const endZ = (length/2) * Math.sin(angleZ);

            leaf.position.set(endX, endY, endZ);
            leaf.scale.set(1 + Math.random()*0.5, 0.8 + Math.random()*0.4, 1 + Math.random()*0.5);
            parent.add(leaf);

            // Add a point light to each leaf cluster for the "glowing" effect
            const light = new THREE.PointLight(0x00ff00, 2, 4);
            light.position.copy(leaf.position);
            parent.add(light);
        }

        // Create a few branches to form the tree shape
        createBranch(bonsaiGroup, 2.5, 0.6, 0.6, 1.5);
        createBranch(bonsaiGroup, 2.2, -0.6, -0.6, 1.2);
        createBranch(bonsaiGroup, 2.8, 0.2, -0.8, 1.0);
        createBranch(bonsaiGroup, 1.8, 0.8, 0.2, 0.9);
        createBranch(bonsaiGroup, 2.0, -0.4, 0.8, 1.1);

        // --- Fireflies ---
        const fireflies = [];
        const fireflyGeometry = new THREE.SphereGeometry(0.05, 8, 8);
        const fireflyMaterial = new THREE.MeshBasicMaterial({ color: 0xffff00 });

        for (let i = 0; i < 40; i++) {
            const firefly = new THREE.Mesh(fireflyGeometry, fireflyMaterial);

            // Random position in a sphere around the tree
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos((Math.random() * 2) - 1);
            const r = 1.5 + Math.random() * 2.5;

            firefly.position.set(
                r * Math.sin(phi) * Math.cos(theta),
                Math.random() * 4, // Height variation
                r * Math.sin(phi) * Math.sin(theta)
            );

            // Store animation data
            firefly.userData = {
                speed: 0.5 + Math.random() * 1.5,
                offset: Math.random() * 100,
                radius: r,
                theta: theta,
                phi: phi
            };

            scene.add(firefly);
            fireflies.push(firefly);
        }

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle rotation of the bonsai
            bonsaiGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Animate fireflies
            fireflies.forEach(f => {
                // Orbit slightly
                f.userData.theta += 0.005 * f.userData.speed;

                // Bob up and down
                const bob = Math.sin(time * f.userData.speed + f.userData.offset) * 0.5;

                f.position.x = Math.cos(f.userData.theta) * f.userData.radius;
                f.position.z = Math.sin(f.userData.theta) * f.userData.radius;
                f.position.y += Math.sin(time * f.userData.speed) * 0.01;

                // Keep within bounds roughly
                if(f.position.y > 5) f.position.y = 0;
                if(f.position.y < 0) f.position.y = 5;
            });

            renderer.render(scene, camera);
        }

        animate();

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
