<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Floating Hourglass with Sand Turning into Stars</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050510; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.z = 8;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);
        const pointLight = new THREE.PointLight(0xffaa00, 2, 20);
        pointLight.position.set(0, 0, 5);
        scene.add(pointLight);

        // Hourglass Geometry
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x88ccff,
            transparent: true,
            opacity: 0.3,
            roughness: 0.1,
            metalness: 0.1,
            side: THREE.DoubleSide,
            transmission: 0.5,
            thickness: 0.5
        });

        // Top Cone (Inverted)
        const topConeGeo = new THREE.ConeGeometry(1.5, 3, 32, 1, true);
        const topCone = new THREE.Mesh(topConeGeo, glassMaterial);
        topCone.position.y = 1.5;
        topCone.rotation.x = Math.PI;
        scene.add(topCone);

        // Bottom Cone
        const bottomConeGeo = new THREE.ConeGeometry(1.5, 3, 32, 1, true);
        const bottomCone = new THREE.Mesh(bottomConeGeo, glassMaterial);
        bottomCone.position.y = -1.5;
        scene.add(bottomCone);

        // Rings
        const ringGeo = new THREE.TorusGeometry(1.6, 0.05, 16, 100);
        const ringMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.4, metalness: 0.6 });

        const topRing = new THREE.Mesh(ringGeo, ringMat);
        topRing.position.y = 3;
        scene.add(topRing);

        const bottomRing = new THREE.Mesh(ringGeo, ringMat);
        bottomRing.position.y = -3;
        scene.add(bottomRing);

        // Particle System (Sand/Stars)
        const particleCount = 800;
        const geometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const colors = new Float32Array(particleCount * 3);
        const sizes = new Float32Array(particleCount);

        // State: 0 = Sand (falling), 1 = Star (floating up)
        const states = new Uint8Array(particleCount); 
        const speeds = new Float32Array(particleCount);

        const sandColor = new THREE.Color(0xffaa00);
        const starColor = new THREE.Color(0xffffff);

        for (let i = 0; i < particleCount; i++) {
            // Initialize random positions within the top cone area
            resetParticle(i, true);
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
        geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

        // Create a simple star texture using canvas
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');

        // Draw a star shape
        ctx.fillStyle = 'white';
        ctx.beginPath();
        for (let i = 0; i < 5; i++) {
            ctx.lineTo(Math.cos((18 + i * 72) * Math.PI / 180) * 16,
                       -Math.sin((18 + i * 72) * Math.PI / 180) * 16);
            ctx.lineTo(Math.cos((54 + i * 72) * Math.PI / 180) * 6,
                       -Math.sin((54 + i * 72) * Math.PI / 180) * 6);
        }
        ctx.closePath();
        ctx.fill();

        const starTexture = new THREE.CanvasTexture(canvas);

        const material = new THREE.PointsMaterial({
            size: 0.15,
            vertexColors: true,
            map: starTexture,
            transparent: true,
            opacity: 0.9,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        const particles = new THREE.Points(geometry, material);
        scene.add(particles);

        function resetParticle(i, initial = false) {
            // Random position in the top cone
            const angle = Math.random() * Math.PI * 2;
            const radius = Math.random() * 0.8; // Keep it somewhat central
            const height = Math.random() * 2.5 + 0.5; // Top part of hourglass

            positions[i * 3] = Math.cos(angle) * radius;
            positions[i * 3 + 1] = height;
            positions[i * 3 + 2] = Math.sin(angle) * radius;

            states[i] = 0; // Sand
            speeds[i] = 0.02 + Math.random() * 0.03; // Falling speed

            colors[i * 3] = sandColor.r;
            colors[i * 3 + 1] = sandColor.g;
            colors[i * 3 + 2] = sandColor.b;

            sizes[i] = 0.1 + Math.random() * 0.1;
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = Date.now() * 0.001;

            // Floating animation for the whole hourglass
            const floatY = Math.sin(time * 0.5) * 0.2;
            topCone.position.y = 1.5 + floatY;
            bottomCone.position.y = -1.5 + floatY;
            topRing.position.y = 3 + floatY;
            bottomRing.position.y = -3 + floatY;
            particles.position.y = floatY;

            // Update particles
            for (let i = 0; i < particleCount; i++) {
                const y = positions[i * 3 + 1];

                if (states[i] === 0) {
                    // Sand State: Falling
                    positions[i * 3 + 1] -= speeds[i];

                    // Add slight random drift
                    positions[i * 3] += (Math.random() - 0.5) * 0.01;
                    positions[i * 3 + 2] += (Math.random() - 0.5) * 0.01;

                    // Check if hit bottom (approx y = -2.5 relative to center)
                    if (y < -2.5) {
                        states[i] = 1; // Turn into Star
                        speeds[i] = 0.02 + Math.random() * 0.02; // Rising speed
                        colors[i * 3] = starColor.r;
                        colors[i * 3 + 1] = starColor.g;
                        colors[i * 3 + 2] = starColor.b;
                        sizes[i] = 0.2 + Math.random() * 0.2; // Stars are bigger
                    }
                } else {
                    // Star State: Floating Up
                    positions[i * 3 + 1] += speeds[i];

                    // Twinkle effect
                    sizes[i] = 0.2 + Math.sin(time * 5 + i) * 0.1;

                    // Check if reached top
                    if (y > 3) {
                        resetParticle(i);
                    }
                }
            }

            geometry.attributes.position.needsUpdate = true;
            geometry.attributes.color.needsUpdate = true;
            geometry.attributes.size.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
