    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
        import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
        import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 15);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ReinhardToneMapping;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 0.5;

        // Post Processing (Bloom)
        const renderScene = new RenderPass(scene, camera);
        const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 1.5, 0.4, 0.85);
        bloomPass.threshold = 0;
        bloomPass.strength = 2.0; // High strength for "light" look
        bloomPass.radius = 0.5;

        const composer = new EffectComposer(renderer);
        composer.addPass(renderScene);
        composer.addPass(bloomPass);

        // Bridge Group
        const bridgeGroup = new THREE.Group();
        scene.add(bridgeGroup);

        // Create Bridge Curve
        const points = [];
        for (let i = -20; i <= 20; i += 0.5) {
            // Create a gentle wave/arch shape
            const y = Math.sin(i * 0.2) * 2 + Math.cos(i * 0.1) * 1;
            points.push(new THREE.Vector3(i, y, 0));
        }
        const curve = new THREE.CatmullRomCurve3(points);

        // Main Bridge Tube (The "Light")
        const tubeGeometry = new THREE.TubeGeometry(curve, 200, 0.15, 8, false);
        const tubeMaterial = new THREE.MeshBasicMaterial({ 
            color: 0x00ffff,
            transparent: true,
            opacity: 0.9
        });
        const bridgeMesh = new THREE.Mesh(tubeGeometry, tubeMaterial);
        bridgeGroup.add(bridgeMesh);

        // Outer Glow Tube (Thicker, more transparent)
        const glowGeometry = new THREE.TubeGeometry(curve, 200, 0.4, 8, false);
        const glowMaterial = new THREE.MeshBasicMaterial({ 
            color: 0x0088ff,
            transparent: true,
            opacity: 0.3,
            side: THREE.BackSide
        });
        const glowMesh = new THREE.Mesh(glowGeometry, glowMaterial);
        bridgeGroup.add(glowMesh);

        // Railings (Two thinner lines on sides)
        const railOffset = 0.8;
        const railPointsLeft = points.map(p => new THREE.Vector3(p.x, p.y + 1.5, -railOffset));
        const railPointsRight = points.map(p => new THREE.Vector3(p.x, p.y + 1.5, railOffset));

        const railCurveLeft = new THREE.CatmullRomCurve3(railPointsLeft);
        const railCurveRight = new THREE.CatmullRomCurve3(railPointsRight);

        const railGeo = new THREE.TubeGeometry(railCurveLeft, 200, 0.05, 4, false);
        const railMat = new THREE.MeshBasicMaterial({ color: 0xffffff });

        const railLeft = new THREE.Mesh(railGeo, railMat);
        const railRight = new THREE.Mesh(railGeo, railMat); // Reuse geometry, position will be handled by curve

        // Actually, need separate geometry for right rail because curve is different
        const railGeoRight = new THREE.TubeGeometry(railCurveRight, 200, 0.05, 4, false);
        const railRightMesh = new THREE.Mesh(railGeoRight, railMat);

        bridgeGroup.add(railLeft);
        bridgeGroup.add(railRightMesh);

        // Floating Particles
        const particlesGeometry = new THREE.BufferGeometry();
        const particlesCount = 1000;
        const posArray = new Float32Array(particlesCount * 3);

        for(let i = 0; i < particlesCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 60; // Spread wide
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMaterial = new THREE.PointsMaterial({
            size: 0.1,
            color: 0x00ffff,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });
        const particlesMesh = new THREE.Points(particlesGeometry, particlesMaterial);
        scene.add(particlesMesh);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Floating animation
            bridgeGroup.position.y = Math.sin(time * 0.5) * 0.5;

            // Subtle rotation
            bridgeGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Animate particles
            particlesMesh.rotation.y = time * 0.05;

            controls.update();
            composer.render();
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
