    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        // Environment for reflections
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const envMap = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
        scene.environment = envMap;

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.minDistance = 3;
        controls.maxDistance = 15;

        // --- The Egg ---
        const eggGroup = new THREE.Group();
        scene.add(eggGroup);

        // 1. Crystal Shell
        // Create an egg shape using LatheGeometry
        const points = [];
        for ( let i = 0; i < 20; i ++ ) {
            // Create a curve that looks like an egg
            const x = Math.sin( ( i / 19 ) * Math.PI ) * 1.5;
            const y = ( i / 19 ) * 3 - 1.5; 
            // Adjust curve to be pointier at top
            const adjustedY = y + Math.pow(Math.abs(y), 2) * 0.2;
            points.push( new THREE.Vector2( x, adjustedY ) );
        }

        const eggGeometry = new THREE.LatheGeometry( points, 64 );

        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 1.5,
            ior: 1.5,
            envMapIntensity: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9,
            side: THREE.DoubleSide
        });

        const eggMesh = new THREE.Mesh(eggGeometry, crystalMaterial);
        eggGroup.add(eggMesh);

        // 2. Inner Phoenix Glow (The "Soul")
        const coreGeometry = new THREE.SphereGeometry(0.6, 32, 32);
        const coreMaterial = new THREE.MeshStandardMaterial({
            color: 0xff4400,
            emissive: 0xff2200,
            emissiveIntensity: 2,
            roughness: 0.5,
            metalness: 0.5
        });
        const coreMesh = new THREE.Mesh(coreGeometry, coreMaterial);
        coreMesh.position.y = -0.2;
        eggGroup.add(coreMesh);

        // 3. Internal Particles (Embers)
        const particlesGeometry = new THREE.BufferGeometry();
        const particleCount = 100;
        const posArray = new Float32Array(particleCount * 3);

        for(let i = 0; i < particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 1.5;
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMaterial = new THREE.PointsMaterial({
            size: 0.05,
            color: 0xffaa00,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });
        const particlesMesh = new THREE.Points(particlesGeometry, particlesMaterial);
        eggGroup.add(particlesMesh);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        // Main light source (warm)
        const mainLight = new THREE.PointLight(0xffaa00, 50, 20);
        mainLight.position.set(2, 3, 4);
        scene.add(mainLight);

        // Rim light (cool blue for contrast)
        const rimLight = new THREE.PointLight(0x0044ff, 30, 20);
        rimLight.position.set(-3, 1, -4);
        scene.add(rimLight);

        // Bottom glow
        const bottomLight = new THREE.PointLight(0xff0000, 20, 10);
        bottomLight.position.set(0, -2, 0);
        scene.add(bottomLight);

        // --- Animation ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Float the egg
            eggGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Rotate the egg slowly
            eggGroup.rotation.y = time * 0.2;

            // Pulse the core
            const scale = 1 + Math.sin(time * 2) * 0.1;
            coreMesh.scale.set(scale, scale, scale);
            coreMaterial.emissiveIntensity = 1.5 + Math.sin(time * 3) * 0.5;

            // Rotate particles
            particlesMesh.rotation.y = -time * 0.1;
            particlesMesh.rotation.z = time * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', onWindowResize, false);
        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        animate();
    </script>
</body>
</html>
