        scene.add(islandGroup);

        // 1. Main Dirt Body (Inverted Cone/Cylinder shape)
        const islandGeo = new THREE.CylinderGeometry(6, 2, 6, 8, 4);
        const islandMesh = new THREE.Mesh(islandGeo, dirtMaterial);
        islandMesh.position.y = 0;
        islandMesh.castShadow = true;
        islandMesh.receiveShadow = true;
        islandGroup.add(islandMesh);

        // 2. Grass Top
        const grassGeo = new THREE.CylinderGeometry(6, 6, 0.5, 8);
        const grassMesh = new THREE.Mesh(grassGeo, grassMaterial);
        grassMesh.position.y = 3;
        grassMesh.receiveShadow = true;
        islandGroup.add(grassMesh);

        // 3. Hanging Rocks
        for (let i = 0; i < 5; i++) {
            const rockGeo = new THREE.DodecahedronGeometry(Math.random() * 1 + 0.5, 0);
            const rock = new THREE.Mesh(rockGeo, rockMaterial);
            const angle = (i / 5) * Math.PI * 2;
            const radius = 2 + Math.random() * 2;
            rock.position.set(
                Math.cos(angle) * radius,
                -2 - Math.random() * 2,
                Math.sin(angle) * radius
            );
            rock.rotation.set(Math.random(), Math.random(), Math.random());
            rock.castShadow = true;
            islandGroup.add(rock);
        }

        // Ancient Tree Group
        const treeGroup = new THREE.Group();
        treeGroup.position.y = 3.25; // Sit on top of grass
        islandGroup.add(treeGroup);

        // 1. Trunk
        const trunkGeo = new THREE.CylinderGeometry(0.5, 1.2, 6, 7);
        const trunk = new THREE.Mesh(trunkGeo, barkMaterial);
        trunk.position.y = 3;
        trunk.castShadow = true;
        treeGroup.add(trunk);

        // 2. Branches (Simple cylinders)
        const branchGeo = new THREE.CylinderGeometry(0.2, 0.4, 4, 5);

        const branch1 = new THREE.Mesh(branchGeo, barkMaterial);
        branch1.position.set(1.5, 5, 0);
        branch1.rotation.z = -Math.PI / 4;
        branch1.castShadow = true;
        treeGroup.add(branch1);

        const branch2 = new THREE.Mesh(branchGeo, barkMaterial);
        branch2.position.set(-1.2, 4.5, 1);
        branch2.rotation.z = Math.PI / 3;
        branch2.rotation.x = Math.PI / 6;
        branch2.castShadow = true;
        treeGroup.add(branch2);

        const branch3 = new THREE.Mesh(branchGeo, barkMaterial);
        branch3.position.set(0, 5.5, -1.5);
        branch3.rotation.x = -Math.PI / 4;
        branch3.castShadow = true;
        treeGroup.add(branch3);

        // 3. Canopy (Cluster of spheres/icosahedrons)
        const createLeafCluster = (x, y, z, scale, mat) => {
            const geo = new THREE.IcosahedronGeometry(scale, 1);
            // Deform geometry slightly for organic look
            const posAttribute = geo.attributes.position;
            for (let i = 0; i < posAttribute.count; i++) {
                const x = posAttribute.getX(i);
                const y = posAttribute.getY(i);
                const z = posAttribute.getZ(i);
                const noise = 1 + (Math.random() - 0.5) * 0.3;
                posAttribute.setXYZ(i, x * noise, y * noise, z * noise);
            }
            geo.computeVertexNormals();

            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            treeGroup.add(mesh);
        };

        // Main canopy
        createLeafCluster(0, 7, 0, 3.5, leafMaterial);
        createLeafCluster(2, 6.5, 1, 2.5, leafMaterialLight);
        createLeafCluster(-2, 6, -1, 2.8, leafMaterial);
        createLeafCluster(0, 8.5, -1, 2.2, leafMaterialLight);
        createLeafCluster(1, 5, 2, 2, leafMaterial);
        createLeafCluster(-1.5, 5.5, 1.5, 2.3, leafMaterial);

        // Floating Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle floating motion
            islandGroup.position.y = Math.sin(time * 0.5) * 0.5;
            islandGroup.rotation.y = Math.sin(time * 0.1) * 0.05;

            controls.update();
            renderer.render(scene, camera);
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
