            metalness: 0.9, 
            roughness: 0.4 
        });
        const gemMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xff0055,
            metalness: 0.1,
            roughness: 0.0,
            transmission: 0.6,
            thickness: 1.0,
            emissive: 0xff0055,
            emissiveIntensity: 0.5
        });

        // Beetle Group
        const beetle = new THREE.Group();
        scene.add(beetle);

        // Body (Thorax/Abdomen)
        const bodyGeo = new THREE.CapsuleGeometry(1, 2, 4, 8);
        const body = new THREE.Mesh(bodyGeo, brassMaterial);
        body.rotation.x = Math.PI / 2;
