            const leg = new THREE.Mesh(legGeo, darkMetalMaterial);
            leg.position.set(pos.x, -0.5, pos.z);
            leg.rotation.z = pos.rotZ;
            leg.rotation.x = pos.rotX;
            leg.castShadow = true;
            beetle.add(leg);
            legs.push(leg);
        });

        // The Gem
