<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Floating Violin Case</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #0a0a12; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.035);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 0.5, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Lights ──
const ambient = new THREE.AmbientLight(0x303050, 0.8);
scene.add(ambient);

const key = new THREE.DirectionalLight(0xffeedd, 2.5);
key.position.set(3, 5, 4);
scene.add(key);

const fill = new THREE.DirectionalLight(0x8888ff, 0.6);
fill.position.set(-4, 2, -2);
scene.add(fill);

const rim = new THREE.PointLight(0xff6633, 1.5, 12);
rim.position.set(-2, 1, -3);
scene.add(rim);

const spot = new THREE.SpotLight(0xffffff, 3, 15, Math.PI / 6, 0.5);
spot.position.set(0, 5, 2);
spot.target.position.set(0, 0, 0);
scene.add(spot);
scene.add(spot.target);

// ── Violin Case Shape ──
function createViolinShape() {
  const s = new THREE.Shape();
  // Start at bottom center, draw right half of violin silhouette
  s.moveTo(0, -1.8);
  // Bottom curve
  s.bezierCurveTo(0.6, -1.85, 0.85, -1.5, 0.8, -1.2);
  // Lower bout
  s.bezierCurveTo(0.9, -0.7, 0.85, -0.4, 0.55, -0.15);
  // Waist
  s.bezierCurveTo(0.35, 0.0, 0.35, 0.1, 0.45, 0.25);
  // Upper bout
  s.bezierCurveTo(0.75, 0.5, 0.85, 0.8, 0.75, 1.1);
  // Top curve
  s.bezierCurveTo(0.65, 1.35, 0.55, 1.55, 0.35, 1.65);
  // Scroll area
  s.bezierCurveTo(0.15, 1.72, 0.08, 1.78, 0, 1.8);
  // Left half (mirror)
  s.bezierCurveTo(-0.08, 1.78, -0.15, 1.72, -0.35, 1.65);
  s.bezierCurveTo(-0.55, 1.55, -0.65, 1.35, -0.75, 1.1);
  s.bezierCurveTo(-0.85, 0.8, -0.75, 0.5, -0.45, 0.25);
  s.bezierCurveTo(-0.35, 0.1, -0.35, 0.0, -0.55, -0.15);
  s.bezierCurveTo(-0.85, -0.4, -0.9, -0.7, -0.8, -1.2);
  s.bezierCurveTo(-0.85, -1.5, -0.6, -1.85, 0, -1.8);

  return s;
}

// ── Materials ──
const caseMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e,
  roughness: 0.35,
  metalness: 0.15,
});

const leatherMat = new THREE.MeshStandardMaterial({
  color: 0x2a1a0a,
  roughness: 0.8,
  metalness: 0.0,
});

const metalMat = new THREE.MeshStandardMaterial({
  color: 0xccbbaa,
  roughness: 0.2,
  metalness: 0.9,
});

const goldMat = new THREE.MeshStandardMaterial({
  color: 0xddaa44,
  roughness: 0.3,
  metalness: 0.8,
});

const darkMat = new THREE.MeshStandardMaterial({
  color: 0x111118,
  roughness: 0.9,
  metalness: 0.0,
});

// ── Case Group ──
const caseGroup = new THREE.Group();

const shape = createViolinShape();
const extrudeSettings = { depth: 0.35, bevelEnabled: true, bevelThickness: 0.06, bevelSize: 0.06, bevelSegments: 4 };

// Front and back panels
const caseGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
const caseMesh = new THREE.Mesh(caseGeo, caseMat);
caseMesh.rotation.x = Math.PI / 2;
caseGroup.add(caseMesh);

// ── Spine (back edge with leather wrap) ──
const spineGeo = new THREE.BoxGeometry(0.06, 3.6, 0.47);
const spine = new THREE.Mesh(spineGeo, leatherMat);
spine.position.set(-0.22, 0, 0);
caseGroup.add(spine);

// ── Latches ──
function createLatch(x, y) {
  const g = new THREE.Group();
  const baseGeo = new THREE.BoxGeometry(0.12, 0.28, 0.06);
  const base = new THREE.Mesh(baseGeo, metalMat);
  g.add(base);
  const loopGeo = new THREE.TorusGeometry(0.04, 0.012, 8, 12, Math.PI);
  const loop = new THREE.Mesh(loopGeo, goldMat);
  loop.position.set(0, 0.16, 0.02);
  loop.rotation.x = Math.PI;
  g.add(loop);
  const pinGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.15, 8);
  const pin = new THREE.Mesh(pinGeo, goldMat);
  pin.rotation.z = Math.PI / 2;
  pin.position.set(0, 0, 0.03);
  g.add(pin);
  g.position.set(x, y, 0.22);
  return g;
}

caseGroup.add(createLatch(-0.3, 0.6));
caseGroup.add(createLatch(-0.3, -0.6));

// ── Handle ──
const handleGroup = new THREE.Group();
const handleBarGeo = new THREE.CylinderGeometry(0.035, 0.035, 0.7, 12);
const handleBar = new THREE.Mesh(handleBarGeo, goldMat);
handleBar.rotation.z = Math.PI / 2;
handleGroup.add(handleBar);

// Handle attachment rings
for (const sx of [-1, 1]) {
  const ringGeo = new THREE.TorusGeometry(0.05, 0.015, 8, 16);
  const ring = new THREE.Mesh(ringGeo, goldMat);
  ring.position.set(sx * 0.35, 0, 0);
  ring.rotation.y = Math.PI / 2;
  handleGroup.add(ring);
}
// Handle base plate
const plateGeo = new THREE.BoxGeometry(0.8, 0.08, 0.12);
const plate = new THREE.Mesh(plateGeo, metalMat);
plate.position.set(0, -0.04, -0.04);
handleGroup.add(plate);

handleGroup.position.set(0, 0.5, -0.26);
caseGroup.add(handleGroup);

// ── End buttons (endpin and scroll) ──
// Endpin button (bottom)
const endPinGeo = new THREE.CylinderGeometry(0.1, 0.12, 0.08, 16);
const endPin = new THREE.Mesh(endPinGeo, metalMat);
endPin.rotation.x = Math.PI / 2;
endPin.position.set(0, -1.75, 0.2);
caseGroup.add(endPin);

// Scroll button (top)
const scrollGeo = new THREE.SphereGeometry(0.12, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2);
const scroll = new THREE.Mesh(scrollGeo, leatherMat);
scroll.rotation.x = -Math.PI / 2;
scroll.position.set(0, 1.78, 0.18);
caseGroup.add(scroll);

// ── Corner protectors ──
function createCornerProtector(px, py, pz) {
  const g = new THREE.BoxGeometry(0.15, 0.15, 0.48);
  const m = new THREE.Mesh(g, metalMat);
  m.position.set(px, py, pz);
  return m;
}
// Approximate corner positions
const corners = [
  [0.4, -1.5, 0], [-0.4, -1.5, 0],
  [0.4, 1.5, 0], [-0.4, 1.5, 0],
  [0.7, -0.9, 0], [-0.7, -0.9, 0],
  [0.7, 0.5, 0], [-0.7, 0.5, 0],
];
corners.forEach(([x, y, z]) => {
  const cp = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), metalMat);
  cp.position.set(x, y, z + 0.18);
  caseGroup.add(cp);
});

// ── Gold trim around edge ──
const trimShape = createViolinShape();
const trimPoints = trimShape.getPoints(60);
const trimCurve = new THREE.CatmullRomCurve3(trimPoints.map(p => new THREE.Vector3(p.x, p.y, 0.24)));
const trimGeo = new THREE.TubeGeometry(trimCurve, 120, 0.015, 8, false);
const trimMesh = new THREE.Mesh(trimGeo, goldMat);
caseGroup.add(trimMesh);

// Second trim on front face
const trimCurve2 = new THREE.CatmullRomCurve3(trimPoints.map(p => new THREE.Vector3(p.x, p.y, -0.12)));
const trimGeo2 = new THREE.TubeGeometry(trimCurve2, 120, 0.012, 8, false);
const trimMesh2 = new THREE.Mesh(trimGeo2, goldMat);
caseGroup.add(trimMesh2);

// ── Brand plate ──
const plateGeo2 = new THREE.BoxGeometry(0.3, 0.1, 0.01);
const plate2 = new THREE.Mesh(plateGeo2, goldMat);
plate2.position.set(0, 0.0, 0.23);
caseGroup.add(plate2);

// ── Position and scale ──
caseGroup.scale.set(1.2, 1.2, 1.2);
scene.add(caseGroup);

// ── Particles ──
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0x8888cc,
  size: 0.03,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Floating motion
  caseGroup.position.y = Math.sin(t * 0.8) * 0.2;
  caseGroup.rotation.y = Math.sin(t * 0.3) * 0.15;
  caseGroup.rotation.z = Math.sin(t * 0.5) * 0.03;
  caseGroup.rotation.x = Math.sin(t * 0.4) * 0.04;

  // Subtle scale pulse
  const s = 1.2 + Math.sin(t * 1.2) * 0.01;
  caseGroup.scale.set(s, s, s);

  // Particle drift
  particles.rotation.y = t * 0.02;
  particles.rotation.x = Math.sin(t * 0.01) * 0.1;

  // Light animation
  rim.position.x = Math.sin(t * 0.7) * 3;
  rim.position.z = Math.cos(t * 0.7) * 3;

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
