            emissive: 0x00aaff, // Blue glow
            emissiveIntensity: 1.5,
            roughness: 0.1,
            metalness: 0.0
        });

        // Mushroom Group
        const mushroomGroup = new THREE.Group();
        scene.add(mushroomGroup);

        // 1. Create Stem
        const stemGeometry = new THREE.CylinderGeometry(0.2, 0.35, 1.8, 16);
        const stem = new THREE.Mesh(stemGeometry, stemMaterial);
        stem.position.y = 0.9;
        mushroomGroup.add(stem);

        // 2. Create Cap
        const capGeometry = new THREE.SphereGeometry(1.0, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        const cap = new THREE.Mesh(capGeometry, capMaterial);
        cap.position.y = 1.8;
        mushroomGroup.add(cap);

        // 3. Create Bioluminescent Roots
        const rootsGroup = new THREE.Group();
        mushroomGroup.add(rootsGroup);

        function createRoot(startPos, endPos) {
            // Create a curve for the root
            const midPoint = new THREE.Vector3().lerpVectors(startPos, endPos, 0.5);
            midPoint.x += (Math.random() - 0.5) * 0.5;
            midPoint.z += (Math.random() - 0.5) * 0.5;

            const curve = new THREE.CatmullRomCurve3([startPos, midPoint, endPos]);
            const tubeGeometry = new THREE.TubeGeometry(curve, 20, 0.04, 8, false);
            const root = new THREE.Mesh(tubeGeometry, rootMaterial);
            rootsGroup.add(root);
        }

        // Generate roots radiating from the base
        const rootCount = 15;
        for (let i = 0; i < rootCount; i++) {
            const angle = (i / rootCount) * Math.PI * 2 + (Math.random() * 0.5);
            const radius = 0.35; // Base radius

            const startX = Math.cos(angle) * radius;
            const startZ = Math.sin(angle) * radius;
            const startY = 0;

            const endX = Math.cos(angle) * (1.5 + Math.random() * 1.5);
            const endZ = Math.sin(angle) * (1.5 + Math.random() * 1.5);
            const endY = -0.5 - Math.random() * 0.5; // Dig into ground

            createRoot(new THREE.Vector3(startX, startY, startZ), new THREE.Vector3(endX, endY, endZ));
        }

        // Lighting
        // Ambient light (very dim)
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Point light for the mushroom cap (Green glow)
        const capLight = new THREE.PointLight(0x00ffaa, 5, 10);
        capLight.position.set(0, 2, 0);
        scene.add(capLight);

        // Point light for the roots (Blue glow)
        const rootLight = new THREE.PointLight(0x00aaff, 4, 8);
        rootLight.position.set(0, -0.5, 0);
        scene.add(rootLight);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            mushroomGroup.rotation.y += 0.005;

            // Pulsing glow effect
            const time = Date.now() * 0.001;
            capLight.intensity = 5 + Math.sin(time) * 1.5;
            rootLight.intensity = 4 + Math.cos(time * 1.3) * 1.5;

            // Pulse emissive intensity slightly
            capMaterial.emissiveIntensity = 0.8 + Math.sin(time) * 0.2;
            rootMaterial.emissiveIntensity = 1.5 + Math.cos(time * 1.3) * 0.5;

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
