renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.2;
document.body.appendChild(renderer.domElement);

// Post-processing
const composer=new EffectComposer(renderer);
composer.addPass(new RenderPass(scene,camera));
const bloom=new UnrealBloomPass(new THREE.Vector2(innerWidth,innerHeight),1.5,0.4,0.85);
bloom.threshold=0.2;bloom.strength=1.8;bloom.radius=0.6;
composer.addPass(bloom);

// Materials
const glassMat=new THREE.MeshPhysicalMaterial({color:0x8899bb,transparent:true,opacity:0.12,roughness:0.05,metalness:0.1,transmission:0.9,thickness:0.3,side:THREE.DoubleSide});
const metalMat=new THREE.MeshStandardMaterial({color:0x3a3a4a,roughness:0.3,metalness:0.9});
const darkMetalMat=new THREE.MeshStandardMaterial({color:0x1a1a2a,roughness:0.5,metalness:0.8});

// Lantern body
const lanternGroup=new THREE.Group();
scene.add(lanternGroup);

// Glass cylinder
const glassGeo=new THREE.CylinderGeometry(1,1.1,3,32,1,true);
const glass=new THREE.Mesh(glassGeo,glassMat);
glass.position.y=0;
lanternGroup.add(glass);

// Glass panels (vertical ribs)
for(let i=0;i<8;i++){
  const a=i/8*Math.PI*2;
  const rib=new THREE.Mesh(new THREE.BoxGeometry(0.03,3,0.03),metalMat);
  rib.position.set(Math.cos(a)*1.05,0,Math.sin(a)*1.05);
  rib.rotation.y=-a;
  lanternGroup.add(rib);
}

// Top cap
const topCap=new THREE.Mesh(new THREE.CylinderGeometry(1.15,1.15,0.1,32),metalMat);
topCap.position.y=1.55;lanternGroup.add(topCap);
const topRing=new THREE.Mesh(new THREE.TorusGeometry(1.1,0.06,8,32),metalMat);
topRing.position.y=1.5;lanternGroup.add(topRing);

// Bottom cap
const botCap=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.15,0.12,32),metalMat);
botCap.position.y=-1.55;lanternGroup.add(botCap);
const botRing=new THREE.Mesh(new THREE.TorusGeometry(1.15,0.05,8,32),metalMat);
botRing.position.y=-1.5;lanternGroup.add(botRing);

// Decorative bands
const band1=new THREE.Mesh(new THREE.TorusGeometry(1.08,0.03,6,32),darkMetalMat);
band1.position.y=0.5;lanternGroup.add(band1);
const band2=new THREE.Mesh(new THREE.TorusGeometry(1.08,0.03,6,32),darkMetalMat);
band2.position.y=-0.5;lanternGroup.add(band2);

// Handle
const handleCurve=new THREE.CatmullRomCurve3([
  new THREE.Vector3(0,1.6,0),
  new THREE.Vector3(0.5,2.4,0),
  new THREE.Vector3(0,3.0,0),
  new THREE.Vector3(-0.5,2.4,0),
  new THREE.Vector3(0,1.6,0)
]);
const handleGeo=new THREE.TubeGeometry(handleCurve,20,0.04,8,true);
const handle=new THREE.Mesh(handleGeo,metalMat);
lanternGroup.add(handle);

// Handle attachment rings
const attRing1=new THREE.Mesh(new THREE.TorusGeometry(0.15,0.03,6,12),metalMat);
attRing1.position.set(0,1.55,0);attRing1.rotation.x=Math.PI/2;lanternGroup.add(attRing1);

// --- STORM INSIDE ---
const stormGroup=new THREE.Group();
lanternGroup.add(stormGroup);

// Clouds
const cloudGeo=new THREE.SphereGeometry(0.15,6,6);
const cloudMat=new THREE.MeshStandardMaterial({color:0x2a2a3a,roughness:1,transparent:true,opacity:0.7});
const clouds=[];
for(let i=0;i<60;i++){
  const c=new THREE.Mesh(cloudGeo,cloudMat.clone());
  const r=0.3+Math.random()*0.5;
  const theta=Math.random()*Math.PI*2;
  const phi=Math.random()*Math.PI*0.4;
  c.position.set(r*Math.sin(phi)*Math.cos(theta),0.8+Math.random()*0.6,r*Math.sin(phi)*Math.sin(theta));
  c.scale.setScalar(0.5+Math.random()*1.5);
  c.material.color.setHSL(0.65,0.15+Math.random()*0.1,0.1+Math.random()*0.15);
  stormGroup.add(c);
  clouds.push(c);
}

// Rain particles
const rainCount=800;
const rainGeo=new THREE.BufferGeometry();
const rainPos=new Float32Array(rainCount*3);
const rainVel=new Float32Array(rainCount);
const rainAlpha=new Float32Array(rainCount);
for(let i=0;i<rainCount;i++){
  rainPos[i*3]=(Math.random()-0.5)*1.6;
  rainPos[i*3+1]=Math.random()*3-1.5;
  rainPos[i*3+2]=(Math.random()-0.5)*1.6;
  rainVel[i]=1+Math.random()*2;
  rainAlpha[i]=Math.random();
}
rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));
const rainMat=new THREE.PointsMaterial({color:0xaabbdd,size:0.02,transparent:true,opacity:0.5,blending:THREE.AdditiveBlending,depthWrite:false});
const rain=new THREE.Points(rainGeo,rainMat);
stormGroup.add(rain);

// Lightning system
const lightningBolts=[];
const lightningMat=new THREE.LineBasicMaterial({color:0xddeeff,transparent:true,opacity:0,blending:THREE.AdditiveBlending});

function createBolt(start,branches=3){
  const points=[];
  let p=new THREE.Vector3(start.x,start.y,start.z);
  points.push(p.clone());
  const segs=8+Math.floor(Math.random()*6);
  for(let i=0;i<segs;i++){
    p.x+=(Math.random()-0.5)*0.3;
    p.y-=0.15+Math.random()*0.15;
    p.z+=(Math.random()-0.5)*0.3;
    p.x=Math.max(-0.8,Math.min(0.8,p.x));
    p.z=Math.max(-0.8,Math.min(0.8,p.z));
    points.push(p.clone());
    if(Math.random()<0.25&&branches>0){
      const branchPoints=[p.clone()];
      let bp=p.clone();
      for(let j=0;j<3+Math.floor(Math.random()*3);j++){
        bp.x+=(Math.random()-0.5)*0.2;
        bp.y-=0.1+Math.random()*0.1;
        bp.z+=(Math.random()-0.5)*0.2;
        branchPoints.push(bp.clone());
      }
      const bGeo=new THREE.BufferGeometry().setFromPoints(branchPoints);
      const bLine=new THREE.Line(bGeo,lightningMat.clone());
      stormGroup.add(bLine);
      lightningBolts.push(bLine);
    }
  }
  const geo=new THREE.BufferGeometry().setFromPoints(points);
  const line=new THREE.Line(geo,lightningMat.clone());
  stormGroup.add(line);
  lightningBolts.push(line);
  return line;
}

let lightningTimer=0;
let lightningIntensity=0;

// Inner light
const innerLight=new THREE.PointLight(0x8899cc,0,4);
innerLight.position.set(0,0,0);
stormGroup.add(innerLight);

const innerLight2=new THREE.PointLight(0x6677aa,0,3);
innerLight2.position.set(0.3,0.5,0.2);
stormGroup.add(innerLight2);

// Ambient
scene.add(new THREE.AmbientLight(0x111122,0.5));
const dirLight=new THREE.DirectionalLight(0x334466,0.3);
dirLight.position.set(2,5,3);
scene.add(dirLight);

// Ground reflection
const groundGeo=new THREE.CircleGeometry(3,32);
const groundMat=new THREE.MeshStandardMaterial({color:0x0a0a15,roughness:0.8,metalness:0.2});
const ground=new THREE.Mesh(groundGeo,groundMat);
ground.rotation.x=-Math.PI/2;ground.position.y=-2.2;
scene.add(ground);

// Sparkle particles around lantern
const sparkCount=200;
const sparkGeo=new THREE.BufferGeometry();
const sparkPos=new Float32Array(sparkCount*3);
const sparkVel=[];
for(let i=0;i<sparkCount;i++){
  sparkPos[i*3]=(Math.random()-0.5)*6;
  sparkPos[i*3+1]=Math.random()*4-1;
  sparkPos[i*3+2]=(Math.random()-0.5)*6;
  sparkVel.push({x:(Math.random()-0.5)*0.003,y:0.002+Math.random()*0.005,z:(Math.random()-0.5)*0.003});
}
sparkGeo.setAttribute('position',new THREE.BufferAttribute(sparkPos,3));
const sparkMat=new THREE.PointsMaterial({color:0x6688cc,size:0.03,transparent:true,opacity:0.3,blending:THREE.AdditiveBlending,depthWrite:false});
const sparks=new THREE.Points(sparkGeo,sparkMat);
scene.add(sparks);

// Animation
const clock=new THREE.Clock();

function animate(){
  requestAnimationFrame(animate);
  const t=clock.getElapsedTime();
  const dt=clock.getDelta();

  // Lightning
  lightningTimer-=0.016;
  if(lightningTimer<=0){
    lightningTimer=2+Math.random()*5;
    const boltStart=new THREE.Vector3((Math.random()-0.5)*0.5,1.2+Math.random()*0.3,(Math.random()-0.5)*0.5);
    createBolt(boltStart,2+Math.floor(Math.random()*3));
    lightningIntensity=1;
  }

  lightningIntensity*=0.92;
  const lFlash=Math.max(0,Math.sin(t*30)*lightningIntensity*0.5+lightningIntensity*0.8);
  innerLight.intensity=lFlash*3;
  innerLight2.intensity=lFlash*2;
  innerLight.color.setHSL(0.6+lightningIntensity*0.05,0.2,0.5+lightningIntensity*0.3);

  // Update lightning materials
  lightningBolts.forEach(b=>{
    b.material.opacity=lightningIntensity;
  });

  // Remove old bolts
  while(lightningBolts.length>15){
    const old=lightningBolts.shift();
    stormGroup.remove(old);old.geometry.dispose();old.material.dispose();
  }

  // Cloud animation
  clouds.forEach((c,i)=>{
    c.position.y+=Math.sin(t*0.5+i)*0.001;
    c.position.x+=Math.cos(t*0.3+i*0.7)*0.0005;
  });

  // Rain animation
  const rPos=rain.geometry.attributes.position.array;
  for(let i=0;i<rainCount;i++){
    rPos[i*3+1]-=rainVel[i]*0.016;
    rPos[i*3]+=(Math.random()-0.5)*0.002;
    if(rPos[i*3+1]<-1.4){
      rPos[i*3+1]=1.4;
      rPos[i*3]=(Math.random()-0.5)*1.6;
      rPos[i*3+2]=(Math.random()-0.5)*1.6;
    }
  }
  rain.geometry.attributes.position.needsUpdate=true;
  rainMat.opacity=0.3+lightningIntensity*0.5;

  // Sparks
  const sPos=sparks.geometry.attributes.position.array;
  for(let i=0;i<sparkCount;i++){
    sPos[i*3]+=sparkVel[i].x+Math.sin(t+i)*0.001;
    sPos[i*3+1]+=sparkVel[i].y;
    sPos[i*3+2]+=sparkVel[i].z+Math.cos(t+i)*0.001;
    if(sPos[i*3+1]>3){sPos[i*3+1]=-1;sPos[i*3]=(Math.random()-0.5)*6;sPos[i*3+2]=(Math.random()-0.5)*6;}
  }
  sparks.geometry.attributes.position.needsUpdate=true;
  sparkMat.opacity=0.15+lightningIntensity*0.3;

  // Gentle lantern sway
  lanternGroup.rotation.y=Math.sin(t*0.3)*0.1;
  lanternGroup.position.y=Math.sin(t*0.5)*0.05;

  composer.render();
}

animate();

window.addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
  composer.setSize(innerWidth,innerHeight);
