    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.z = 8;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Lighting (Crucial for the "Silver" look)
        const ambientLight = new THREE.AmbientLight(0x404040, 2); // Soft white light
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 5, 5);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x00ffff, 5, 20);
        pointLight.position.set(0, 0, 2);
        scene.add(pointLight);

        // --- The Portal ---
        const portalGroup = new THREE.Group();
        scene.add(portalGroup);

        // Outer Ring
        const ringGeo = new THREE.TorusGeometry(3, 0.15, 16, 100);
        const ringMat = new THREE.MeshStandardMaterial({ 
            color: 0x8800ff, 
            emissive: 0x4400aa,
            emissiveIntensity: 2,
            roughness: 0.2,
            metalness: 0.8
        });
        const ring = new THREE.Mesh(ringGeo, ringMat);
        portalGroup.add(ring);

        // Inner Swirl (Particles)
        const particlesGeo = new THREE.BufferGeometry();
        const particleCount = 1000;
        const posArray = new Float32Array(particleCount * 3);

        for(let i = 0; i < particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 5; // Spread
        }

        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.05,
            color: 0x00ffff,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });
        const particleSystem = new THREE.Points(particlesGeo, particlesMat);
        portalGroup.add(particleSystem);

        // --- The Silver Key ---
        const keyGroup = new THREE.Group();
        scene.add(keyGroup);

        const silverMat = new THREE.MeshStandardMaterial({
            color: 0xdddddd,
            metalness: 0.9,
            roughness: 0.1,
            envMapIntensity: 1
        });

        // Key Shaft
        const shaftGeo = new THREE.CylinderGeometry(0.08, 0.08, 2.5, 16);
        const shaft = new THREE.Mesh(shaftGeo, silverMat);
        shaft.rotation.x = Math.PI / 2;
        shaft.position.z = 0;
        keyGroup.add(shaft);

        // Key Head (Bow)
        const headGeo = new THREE.TorusGeometry(0.6, 0.1, 16, 32);
        const head = new THREE.Mesh(headGeo, silverMat);
        head.position.x = -1.2; // Offset to left
        keyGroup.add(head);

        // Key Teeth
        const toothGeo = new THREE.BoxGeometry(0.15, 0.4, 0.1);
        const tooth1 = new THREE.Mesh(toothGeo, silverMat);
        tooth1.position.set(1.0, 0, 0.15);
        keyGroup.add(tooth1);

        const tooth2 = new THREE.Mesh(toothGeo, silverMat);
        tooth2.position.set(1.0, 0, -0.15);
        keyGroup.add(tooth2);

        // Position Key
        keyGroup.position.set(4, 0, 0);
        keyGroup.rotation.y = -Math.PI / 2; // Face the portal

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Rotate Portal Particles
            particleSystem.rotation.z = time * 0.5;
            particleSystem.rotation.y = time * 0.2;

            // Animate Key "Unlocking"
            // Move key towards portal
            const targetX = 0;
            const currentX = keyGroup.position.x;

            // Simple easing movement
            if (currentX > 2.5) {
                keyGroup.position.x -= 0.02;
            }

            // Rotate key as if turning in a lock
            keyGroup.rotation.z = Math.sin(time * 2) * 0.2;

            // Pulse the portal light
            ringMat.emissiveIntensity = 2 + Math.sin(time * 3) * 0.5;
            pointLight.intensity = 5 + Math.sin(time * 5) * 2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
