<body>
<script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

    // Scene Setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x020205);
    scene.fog = new THREE.FogExp2(0x020205, 0.03);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 4, 8);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // Lighting (Moonlight)
    const ambientLight = new THREE.AmbientLight(0x111122, 0.5);
    scene.add(ambientLight);

    const moonLight = new THREE.DirectionalLight(0xaaccff, 3);
    moonLight.position.set(5, 10, 5);
    scene.add(moonLight);

    const fillLight = new THREE.PointLight(0x4466aa, 1, 20);
    fillLight.position.set(-5, 2, -5);
    scene.add(fillLight);

    // Crystal Material
    const crystalMaterial = new THREE.MeshPhysicalMaterial({
        color: 0xffffff,
        metalness: 0.1,
        roughness: 0.05,
        transmission: 0.9,
        thickness: 1.5,
        ior: 1.5,
        clearcoat: 1.0,
        clearcoatRoughness: 0.1,
        emissive: 0x223355,
        emissiveIntensity: 0.1
    });

    // Petal Geometry Generator
    function createPetalGeometry() {
        const points = [];
        // Create a profile curve for the petal
        for (let i = 0; i <= 10; i++) {
            const t = i / 10;
            // Width varies: 0 at base, max in middle, 0 at tip
            const width = Math.sin(t * Math.PI) * 0.6; 
            const height = t * 2.5;
            points.push(new THREE.Vector2(width, height));
        }
        const geometry = new THREE.LatheGeometry(points, 16);
        // Flatten the lathe to make it a petal shape
        geometry.scale(1, 1, 0.15); 
        return geometry;
    }

    const petalGeometry = createPetalGeometry();
    const lotusGroup = new THREE.Group();
    scene.add(lotusGroup);

    // Build Lotus Layers
    const layers = [
        { count: 5, radius: 0.1, y: 0.5, tilt: 0, scale: 0.8 },      // Inner bud
        { count: 8, radius: 0.4, y: 0.2, tilt: 15, scale: 1.0 },     // Inner petals
        { count: 12, radius: 0.7, y: -0.1, tilt: 30, scale: 1.2 },   // Middle petals
        { count: 16, radius: 1.1, y: -0.4, tilt: 45, scale: 1.4 }    // Outer petals
    ];

    layers.forEach(layer => {
        for (let i = 0; i < layer.count; i++) {
            const petal = new THREE.Mesh(petalGeometry, crystalMaterial);

            const angle = (i / layer.count) * Math.PI * 2;

            // Position
            petal.position.set(
                Math.cos(angle) * layer.radius,
                layer.y,
                Math.sin(angle) * layer.radius
            );

            // Rotation
            petal.rotation.y = -angle; // Face outward
            petal.rotation.x = -layer.tilt * (Math.PI / 180); // Tilt outward

            // Scale
            petal.scale.setScalar(layer.scale);

            lotusGroup.add(petal);
        }
    });

    // Central Crystal Bud
    const budGeo = new THREE.SphereGeometry(0.3, 32, 32);
    const bud = new THREE.Mesh(budGeo, crystalMaterial);
    bud.position.y = 0.8;
    bud.scale.y = 1.5;
    lotusGroup.add(bud);

