        function createRuneTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 64;
            canvas.height = 64;
            const ctx = canvas.getContext('2d');

            // Draw a glowing rune character
            ctx.font = 'bold 48px serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = '#ffffff';
            ctx.shadowColor = '#ffaa00';
            ctx.shadowBlur = 10;
            ctx.fillText('ᚠ', 32, 32); // Default char, will be replaced per instance if needed, but texture is shared for perf

            const texture = new THREE.CanvasTexture(canvas);
            return texture;
        }

        // Create a pool of rune meshes
        const runeMaterial = new THREE.MeshBasicMaterial({ 
            map: runeTexture, 
            transparent: true, 
            opacity: 0, 
            side: THREE.DoubleSide,
            depthWrite: false,
            blending: THREE.AdditiveBlending
        });

        for (let i = 0; i < 20; i++) {
            const geometry = new THREE.PlaneGeometry(0.3, 0.3);
            const mesh = new THREE.Mesh(geometry, runeMaterial.clone());

            // Randomize initial state
            mesh.userData = {
                velocity: 0.02 + Math.random() * 0.03,
                rotationSpeed: (Math.random() - 0.5) * 0.05,
                life: 0,
                maxLife: 100 + Math.random() * 100,
                active: false
            };

            scene.add(mesh);
            runes.push(mesh);
        }

        function spawnRune() {
            // Find an inactive rune
            const rune = runes.find(r => !r.userData.active);
            if (rune) {
                rune.userData.active = true;
                rune.userData.life = 0;
                rune.position.set(
                    (Math.random() - 0.5) * 0.2, 
                    1.3, // Start at flame height
                    (Math.random() - 0.5) * 0.2
                );
                rune.material.opacity = 0.8;
                rune.scale.setScalar(0.5 + Math.random() * 0.5);

                // Update texture to a random rune character
                const canvas = rune.material.map.image;
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0,0,64,64);
                const char = runeChars[Math.floor(Math.random() * runeChars.length)];
                ctx.fillText(char, 32, 32);
                rune.material.map.needsUpdate = true;
            }
        }

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const delta = clock.getDelta();

            // 1. Float the candle
            candleGroup.position.y = Math.sin(time * 0.5) * 0.2;
            candleGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // 2. Flicker the flame and light
            const flicker = Math.sin(time * 10) * 0.1 + Math.sin(time * 23) * 0.1;
            candleLight.intensity = 2 + flicker;
            flame.scale.setScalar(1 + flicker * 0.2);

            // 3. Manage Runes
            if (Math.random() < 0.1) spawnRune(); // Chance to spawn per frame

            runes.forEach(rune => {
                if (rune.userData.active) {
                    rune.userData.life++;
                    rune.position.y += rune.userData.velocity;
                    rune.rotation.z += rune.userData.rotationSpeed;

                    // Fade out
                    const lifeRatio = rune.userData.life / rune.userData.maxLife;
                    rune.material.opacity = (1 - lifeRatio) * 0.8;

                    // Reset if dead
                    if (rune.userData.life >= rune.userData.maxLife) {
                        rune.userData.active = false;
                        rune.material.opacity = 0;
                    }
                }
            });

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
