<script type="module">
import * as THREE from 'three';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050505);
scene.fog = new THREE.Fog(0x050505, 10, 50);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 2, 8);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0x404040, 2);
scene.add(ambientLight);

const mainLight = new THREE.DirectionalLight(0xffffff, 3);
mainLight.position.set(5, 10, 7);
scene.add(mainLight);

const rimLight = new THREE.PointLight(0x00ffff, 5, 20);
rimLight.position.set(-5, 2, -5);
scene.add(rimLight);

const warmLight = new THREE.PointLight(0xffaa00, 3, 15);
warmLight.position.set(5, -2, 5);
scene.add(warmLight);

// --- Texture Generation (Stained Glass) ---
function createStainedGlassTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');

    // Dark background for "lead" lines
    ctx.fillStyle = '#111111';
    ctx.fillRect(0, 0, 512, 512);

    const cols = 8;
    const rows = 8;
    const w = 512 / cols;
    const h = 512 / rows;

    for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
            // Random vibrant colors
            const hue = Math.random() * 360;
            ctx.fillStyle = `hsl(${hue}, 80%, 60%)`;
            // Draw slightly smaller rect to leave lead lines
            ctx.fillRect(i * w + 4, j * h + 4, w - 8, h - 8);
        }
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
}

const glassTexture = createStainedGlassTexture();

// --- Materials ---
const robotMaterial = new THREE.MeshStandardMaterial({
    color: 0x888888,
    metalness: 0.9,
    roughness: 0.2
});

const glassMaterial = new THREE.MeshStandardMaterial({
    map: glassTexture,
    color: 0xffffff,
    metalness: 0.1,
    roughness: 0.2,
    transparent: true,
    opacity: 0.85,
    side: THREE.DoubleSide
});

// --- Geometry Construction ---
const butterfly = new THREE.Group();
scene.add(butterfly);

const bodyGroup = new THREE.Group();
butterfly.add(bodyGroup);

// 1. Body Parts
// Abdomen
const abdomen = new THREE.Mesh(new THREE.CapsuleGeometry(0.2, 1.2, 4, 8), robotMaterial);
abdomen.rotation.x = Math.PI / 2;
abdomen.position.z = -0.6;
bodyGroup.add(abdomen);

// Thorax
const thorax = new THREE.Mesh(new THREE.SphereGeometry(0.4, 16, 16), robotMaterial);
thorax.position.z = 0.4;
bodyGroup.add(thorax);

// Head
const head = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), robotMaterial);
head.position.z = 0.9;
bodyGroup.add(head);

// Antennae
const antennaGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.2);
const antennaL = new THREE.Mesh(antennaGeo, robotMaterial);
antennaL.position.set(-0.15, 0.2, 1.1);
antennaL.rotation.z = 0.6;
antennaL.rotation.x = 0.2;
bodyGroup.add(antennaL);

const antennaR = new THREE.Mesh(antennaGeo, robotMaterial);
antennaR.position.set(0.15, 0.2, 1.1);
antennaR.rotation.z = -0.6;
antennaR.rotation.x = 0.2;
bodyGroup.add(antennaR);

// 2. Wings
const wings = [];

function createWingShape(isUpper) {
    const shape = new THREE.Shape();
    if (isUpper) {
        // Upper wing shape
        shape.moveTo(0, 0);
        shape.bezierCurveTo(2, 2.5, 4.5, 1.5, 3.5, -0.5);
        shape.bezierCurveTo(2.5, -0.5, 1, -0.2, 0, 0);
    } else {
        // Lower wing shape
        shape.moveTo(0, 0);
        shape.bezierCurveTo(1.5, -1, 2.5, -2.5, 1.5, -3.5);
        shape.bezierCurveTo(0.5, -2.5, 0.5, -1, 0, 0);
    }
    return shape;
}

function createWing(isUpper, isLeft) {
    const pivot = new THREE.Group();

    // Position pivot: Left/Right on X, Upper/Lower on Y
    const xPos = isLeft ? -0.4 : 0.4;
    const yPos = isUpper ? 0.1 : -0.3; 
    pivot.position.set(xPos, yPos, 0.4);
    bodyGroup.add(pivot);

    const shape = createWingShape(isUpper);
    const geometry = new THREE.ShapeGeometry(shape, 32);

    // Flip geometry for left wings
    if (isLeft) {
        geometry.scale(-1, 1, 1);
    }

    // Add 3D curve to the flat wing geometry
    const posAttribute = geometry.attributes.position;
    for (let i = 0; i < posAttribute.count; i++) {
        const x = posAttribute.getX(i);
        // Curve the wing downwards/outwards based on distance from body
        const z = -Math.abs(x) * 0.3; 
        posAttribute.setZ(i, z);
    }
    geometry.computeVertexNormals();

    const mesh = new THREE.Mesh(geometry, glassMaterial);
    pivot.add(mesh);

    wings.push({ pivot, isUpper, isLeft });
}

// Create 4 wings
createWing(true, true);  // Upper Left
createWing(true, false); // Upper Right
createWing(false, true); // Lower Left
createWing(false, false); // Lower Right

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);

    const time = clock.getElapsedTime();

    // Flapping Animation
    const flapSpeed = 6;
    const flapAngle = Math.sin(time * flapSpeed) * 0.6;

    wings.forEach(wing => {
        // Upper wings flap more than lower
        const angle = wing.isUpper ? flapAngle : flapAngle * 0.6;
        wing.pivot.rotation.z = angle;

        // Add slight roll for realism
        wing.pivot.rotation.x = Math.sin(time * flapSpeed + (wing.isLeft ? 0 : Math.PI)) * 0.1;
    });

    // Hovering Animation
    butterfly.position.y = Math.sin(time * 2) * 0.3;
    butterfly.rotation.y = Math.sin(time * 0.5) * 0.2;

    renderer.render(scene, camera);
}

animate();

// --- Resize Handler ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
