    <title>Lantern with Shooting Stars</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 5);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5); // Soft white light
        scene.add(ambientLight);

        // Lantern Construction
        const lanternGroup = new THREE.Group();
        scene.add(lanternGroup);

        // Lantern Body (Wireframe Box)
        const lanternGeo = new THREE.BoxGeometry(1, 1.5, 1);
        const lanternMat = new THREE.MeshBasicMaterial({ 
            color: 0xffaa00, 
            wireframe: true,
            transparent: true,
            opacity: 0.3
        });
        const lanternMesh = new THREE.Mesh(lanternGeo, lanternMat);
        lanternGroup.add(lanternMesh);

        // Lantern Inner Glow (Point Light + Sphere)
        const lightGeo = new THREE.SphereGeometry(0.2, 16, 16);
        const lightMat = new THREE.MeshBasicMaterial({ color: 0xffddaa });
        const lightMesh = new THREE.Mesh(lightGeo, lightMat);
        lanternGroup.add(lightMesh);

        const pointLight = new THREE.PointLight(0xffaa00, 2, 10);
        lanternGroup.add(pointLight);

        // Shooting Stars Particle System
        const starCount = 200;
        const starGeo = new THREE.BufferGeometry();
        const starPositions = new Float32Array(starCount * 3);
        const starVelocities = []; // Store velocity for each star
        const starLifetimes = new Float32Array(starCount); // 0 to 1

        for (let i = 0; i < starCount; i++) {
            // Initialize off-screen or reset
            resetStar(i);
        }

        starGeo.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));

        // Create a simple texture for the star (soft circle)
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const context = canvas.getContext('2d');
        const gradient = context.createRadialGradient(16, 16, 0, 16, 16, 16);
        gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
        gradient.addColorStop(0.2, 'rgba(255, 200, 100, 1)');
        gradient.addColorStop(0.5, 'rgba(255, 100, 0, 0.2)');
        gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
        context.fillStyle = gradient;
        context.fillRect(0, 0, 32, 32);
        const starTexture = new THREE.CanvasTexture(canvas);

        const starMat = new THREE.PointsMaterial({
            color: 0xffffff,
            size: 0.15,
            map: starTexture,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            sizeAttenuation: true
        });

        const stars = new THREE.Points(starGeo, starMat);
        scene.add(stars);

        function resetStar(i) {
            // Start near the lantern
            starPositions[i * 3] = (Math.random() - 0.5) * 0.5; // x
            starPositions[i * 3 + 1] = (Math.random() - 0.5) * 0.5; // y
            starPositions[i * 3 + 2] = (Math.random() - 0.5) * 0.5; // z

            // Velocity: Upwards and slightly outward
            starVelocities[i] = {
                x: (Math.random() - 0.5) * 0.05,
                y: 0.05 + Math.random() * 0.1, // Upward speed
                z: (Math.random() - 0.5) * 0.05
            };

            starLifetimes[i] = 1.0; // Full life
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            // Rotate lantern slightly
            lanternGroup.rotation.y = Math.sin(time * 0.5) * 0.2;
            lanternGroup.position.y = Math.sin(time * 1.5) * 0.2;

            // Flicker light
            pointLight.intensity = 2 + Math.sin(time * 10) * 0.2 + Math.random() * 0.1;

            // Update Stars
            const positions = stars.geometry.attributes.position.array;

            for (let i = 0; i < starCount; i++) {
                // Move star
                positions[i * 3] += starVelocities[i].x;
                positions[i * 3 + 1] += starVelocities[i].y;
                positions[i * 3 + 2] += starVelocities[i].z;

                // Decrease life
                starLifetimes[i] -= delta * 0.8; // Fade out speed

                // Reset if dead or too far
                if (starLifetimes[i] <= 0 || positions[i * 3 + 1] > 10) {
                    resetStar(i);
                }
            }

            stars.geometry.attributes.position.needsUpdate = true;

            // Optional: Fade opacity based on lifetime (requires custom shader or updating material opacity globally, 
            // but for simplicity, we just recycle them. To make them fade, we'd need a custom attribute for alpha).
            // Let's just keep them bright for the "shooting" effect.

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
