    <div id="info">⚙ MECHANICAL PHOENIX ⚙</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        scene.fog = new THREE.FogExp2(0x111111, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 12);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffaa00, 3);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xff4400, 5, 20);
        pointLight.position.set(0, 0, 2);
        scene.add(pointLight);

        // Materials
        const metalMaterial = new THREE.MeshStandardMaterial({
            color: 0x888888,
            metalness: 0.8,
            roughness: 0.2
        });

        const copperMaterial = new THREE.MeshStandardMaterial({
            color: 0xb87333,
            metalness: 0.7,
            roughness: 0.3
        });

        const glowMaterial = new THREE.MeshStandardMaterial({
            color: 0xff4400,
            emissive: 0xff2200,
            emissiveIntensity: 2,
            metalness: 0.5,
            roughness: 0.5
        });

        // Helper: Create a Gear
        function createGear(radius, teeth, thickness, material) {
            const gearGroup = new THREE.Group();

            // Rim
            const rimGeo = new THREE.TorusGeometry(radius, thickness * 0.4, 8, 16);
            const rim = new THREE.Mesh(rimGeo, material);
            gearGroup.add(rim);

            // Hub
            const hubGeo = new THREE.CylinderGeometry(radius * 0.3, radius * 0.3, thickness, 16);
            const hub = new THREE.Mesh(hubGeo, material);
            hub.rotation.x = Math.PI / 2;
            gearGroup.add(hub);

            // Teeth
            const toothGeo = new THREE.BoxGeometry(thickness * 0.8, thickness * 1.5, thickness);
            for (let i = 0; i < teeth; i++) {
                const angle = (i / teeth) * Math.PI * 2;
                const tooth = new THREE.Mesh(toothGeo, material);
                tooth.position.x = Math.cos(angle) * radius;
                tooth.position.y = Math.sin(angle) * radius;
                tooth.rotation.z = angle;
                gearGroup.add(tooth);
            }

            // Spokes
            const spokeGeo = new THREE.BoxGeometry(radius * 1.4, thickness * 0.3, thickness);
            for (let i = 0; i < 4; i++) {
                const spoke = new THREE.Mesh(spokeGeo, material);
                spoke.rotation.z = (i / 4) * Math.PI;
                gearGroup.add(spoke);
            }

            return gearGroup;
        }

        // Construct Phoenix
        const phoenixGroup = new THREE.Group();
        scene.add(phoenixGroup);

        // Body
        const bodyGeo = new THREE.CylinderGeometry(0.8, 1.2, 4, 8);
        const body = new THREE.Mesh(bodyGeo, metalMaterial);
        body.position.y = 0;
        phoenixGroup.add(body);

        // Head
        const headGeo = new THREE.SphereGeometry(0.7, 16, 16);
        const head = new THREE.Mesh(headGeo, copperMaterial);
        head.position.y = 2.5;
        phoenixGroup.add(head);

        // Beak
        const beakGeo = new THREE.ConeGeometry(0.2, 1.5, 8);
        const beak = new THREE.Mesh(beakGeo, glowMaterial);
        beak.position.set(0, 2.2, 0.8);
        beak.rotation.x = Math.PI / 2;
        phoenixGroup.add(beak);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.15, 8, 8);
        const leftEye = new THREE.Mesh(eyeGeo, glowMaterial);
        leftEye.position.set(-0.3, 2.6, 0.5);
        phoenixGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glowMaterial);
        rightEye.position.set(0.3, 2.6, 0.5);
        phoenixGroup.add(rightEye);

        // Tail Feathers (Mechanical)
        const tailGroup = new THREE.Group();
        phoenixGroup.add(tailGroup);

        for(let i=0; i<5; i++) {
            const featherGeo = new THREE.CylinderGeometry(0.1, 0.05, 3, 4);
            const feather = new THREE.Mesh(featherGeo, copperMaterial);
            feather.position.y = -3.5;
            feather.rotation.z = (i - 2) * 0.3;
            feather.rotation.x = 0.5;
            tailGroup.add(feather);
        }

        // Wings
        const leftWingGroup = new THREE.Group();
        const rightWingGroup = new THREE.Group();
        phoenixGroup.add(leftWingGroup);
        phoenixGroup.add(rightWingGroup);

        function buildWing(side) {
            const wingGroup = side === 'left' ? leftWingGroup : rightWingGroup;
            const xPos = side === 'left' ? -1.5 : 1.5;

            // Main arm bone
            const armGeo = new THREE.CylinderGeometry(0.2, 0.1, 4, 8);
            const arm = new THREE.Mesh(armGeo, metalMaterial);
            arm.position.set(xPos, 0.5, 0);
            arm.rotation.z = side === 'left' ? -Math.PI / 4 : Math.PI / 4;
            wingGroup.add(arm);

            // Gears on wing
            const gears = [];
            for(let i=0; i<4; i++) {
                const radius = 0.8 - (i * 0.15);
                const gear = createGear(radius, 8, 0.2, copperMaterial);

                // Position gears along the wing span
                const dist = 1.5 + (i * 0.8);
                const angle = side === 'left' ? -Math.PI / 3 - (i * 0.1) : Math.PI / 3 + (i * 0.1);

                gear.position.set(
                    xPos + Math.cos(angle) * dist * (side === 'left' ? -1 : 1), 
                    0.5 + Math.sin(angle) * dist * 0.5, 
                    0
                );

                // Rotate gears to face somewhat forward/up
                gear.rotation.y = side === 'left' ? 0.5 : -0.5;
                gear.rotation.z = side === 'left' ? -0.5 : 0.5;

                wingGroup.add(gear);
                gears.push(gear);
            }
            return gears;
        }

        const leftGears = buildWing('left');
        const rightGears = buildWing('right');

        // Particles (Embers)
        const particlesGeo = new THREE.BufferGeometry();
        const particleCount = 200;
        const posArray = new Float32Array(particleCount * 3);

        for(let i=0; i<particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 20;
        }

        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.1,
            color: 0xffaa00,
            transparent: true,
            opacity: 0.8
        });
        const particlesMesh = new THREE.Points(particlesGeo, particlesMat);
        scene.add(particlesMesh);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Hover effect
            phoenixGroup.position.y = Math.sin(time * 0.5) * 0.5;
            phoenixGroup.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Wing Flapping
            const flapAngle = Math.sin(time * 2) * 0.3;
            leftWingGroup.rotation.z = flapAngle;
            rightWingGroup.rotation.z = -flapAngle;

            // Gear Rotation
            leftGears.forEach((g, i) => {
                g.rotation.z += 0.02 * (i % 2 === 0 ? 1 : -1);
            });
            rightGears.forEach((g, i) => {
                g.rotation.z -= 0.02 * (i % 2 === 0 ? 1 : -1);
            });

            // Particle Animation
            particlesMesh.rotation.y = time * 0.1;
            const positions = particlesGeo.attributes.position.array;
            for(let i=1; i<particleCount*3; i+=3) {
                positions[i] += 0.02; // Move up
                if(positions[i] > 10) positions[i] = -10;
            }
            particlesGeo.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
