        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x00ffff, 3, 10);
        pointLight.position.set(0, 0, 0);
        scene.add(pointLight);

        // Teapot
        const teapotGeometry = new TeapotGeometry(1, 10, 10, 10, 10, 10, 10);
        const teapotMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.3, 
            metalness: 0.8,
            emissive: 0x110022,
            emissiveIntensity: 0.2
        });
        const teapot = new THREE.Mesh(teapotGeometry, teapotMaterial);
        teapot.rotation.y = Math.PI; // Face spout towards camera/right
        teapot.position.y = 1;
        scene.add(teapot);

        // Galaxies (Particles)
        const particleCount = 2000;
        const particlesGeometry = new THREE.BufferGeometry();
        const positions = new Float32Array(particleCount * 3);
        const colors = new Float32Array(particleCount * 3);
        const velocities = [];
        const lifetimes = new Float32Array(particleCount);

        const colorPalette = [
            new THREE.Color(0xff00ff), // Magenta
            new THREE.Color(0x00ffff), // Cyan
            new THREE.Color(0x8a2be2), // BlueViolet
            new THREE.Color(0xffd700)  // Gold
        ];

        for (let i = 0; i < particleCount; i++) {
            // Initialize off-screen
            positions[i * 3] = 0;
            positions[i * 3 + 1] = -100;
            positions[i * 3 + 2] = 0;

            const color = colorPalette[Math.floor(Math.random() * colorPalette.length)];
            colors[i * 3] = color.r;
            colors[i * 3 + 1] = color.g;
            colors[i * 3 + 2] = color.b;

            velocities.push({
                x: (Math.random() - 0.5) * 0.1,
                y: -Math.random() * 0.2 - 0.1,
                z: (Math.random() - 0.5) * 0.1
            });

            lifetimes[i] = Math.random();
        }

        particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        particlesGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const particlesMaterial = new THREE.PointsMaterial({
            size: 0.05,
            vertexColors: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            transparent: true,
            opacity: 0.8
        });

        const particleSystem = new THREE.Points(particlesGeometry, particlesMaterial);
        scene.add(particleSystem);

        // Spout Position Helper
        // The teapot geometry is complex, so we approximate the spout exit point relative to the teapot mesh
        // Based on standard Utah Teapot geometry, the spout is roughly at x=1.3, y=0.6, z=0 (local coords)
        // Since we rotated the teapot by PI, we need to adjust.
        const spoutOffset = new THREE.Vector3(-1.3, 0.6, 0); 

        function resetParticle(i) {
            // Get world position of spout
            const spoutWorldPos = new THREE.Vector3();
            spoutOffset.applyMatrix4(teapot.matrixWorld, spoutWorldPos);

            positions[i * 3] = spoutWorldPos.x + (Math.random() - 0.5) * 0.1;
            positions[i * 3 + 1] = spoutWorldPos.y + (Math.random() - 0.5) * 0.1;
            positions[i * 3 + 2] = spoutWorldPos.z + (Math.random() - 0.5) * 0.1;

            // Randomize velocity slightly for spread
            velocities[i].x = (Math.random() - 0.5) * 0.15;
            velocities[i].y = -Math.random() * 0.3 - 0.1; // Downward flow
            velocities[i].z = (Math.random() - 0.5) * 0.15;

            lifetimes[i] = 1.0;
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Float Teapot
            teapot.position.y = 1 + Math.sin(time) * 0.2;
            teapot.rotation.z = Math.sin(time * 0.5) * 0.05;
            teapot.updateMatrixWorld(); // Important for particle origin

            // Update Particles
            const posAttribute = particlesGeometry.getAttribute('position');

            for (let i = 0; i < particleCount; i++) {
                // Move particle
                positions[i * 3] += velocities[i].x;
                positions[i * 3 + 1] += velocities[i].y;
                positions[i * 3 + 2] += velocities[i].z;

                // Gravity effect on particles
                velocities[i].y -= 0.002;

                // Reset if too low or lifetime expired
                if (positions[i * 3 + 1] < -5 || lifetimes[i] <= 0) {
                    resetParticle(i);
                } else {
                    lifetimes[i] -= 0.01;
                }
            }

            posAttribute.needsUpdate = true;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
