            color: 0xffaa00,
            emissive: 0xffaa00,
            emissiveIntensity: 3,
            roughness: 0.2,
            metalness: 0.5
        });

        // Tree Generation
        const treeGroup = new THREE.Group();
        scene.add(treeGroup);

        function createBranch(parent, length, radius, depth) {
            if (depth === 0) {
                // Add Glowing Fruit
                const fruitGeo = new THREE.SphereGeometry(radius * 1.8, 16, 16);
                const fruit = new THREE.Mesh(fruitGeo, fruitMaterial);
                fruit.position.y = length * 0.8;
                parent.add(fruit);

                // Add a point light to the fruit for glow effect
                const light = new THREE.PointLight(0xffaa00, 5, 8);
                light.position.y = length * 0.8;
                parent.add(light);
                return;
            }

            // Create Branch
            const geometry = new THREE.CylinderGeometry(radius * 0.6, radius, length, 8);
            const branch = new THREE.Mesh(geometry, crystalMaterial);
            branch.position.y = length / 2;
            parent.add(branch);

            // Create Sub-branches
            const numBranches = 2;
            for (let i = 0; i < numBranches; i++) {
                const newLength = length * 0.75;
                const newRadius = radius * 0.7;

                const childGroup = new THREE.Group();
                childGroup.position.y = length;

                // Randomize angles slightly for organic look
                const angleZ = (i - 0.5) * 1.2 + (Math.random() - 0.5) * 0.3;
                const angleY = Math.random() * Math.PI * 2;

                childGroup.rotation.z = angleZ;
                childGroup.rotation.y = angleY;

                parent.add(childGroup);
                createBranch(childGroup, newLength, newRadius, depth - 1);
            }
        }

        // Initialize Tree
        const trunkGroup = new THREE.Group();
        trunkGroup.position.y = 0;
        treeGroup.add(trunkGroup);

        // Start recursion: parent, length, radius, depth
        createBranch(trunkGroup, 4, 0.4, 5);

