            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.0,
            transparent: true,
            opacity: 0.9
        });

        // Helper to create crystal parts
        function createCrystalPart(geometry) {
            const mesh = new THREE.Mesh(geometry, crystalMaterial);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Scorpion Construction
        const scorpionGroup = new THREE.Group();

        // 1. Body (Cephalothorax)
        const bodyGeo = new THREE.SphereGeometry(1, 32, 32);
        bodyGeo.scale(1, 0.6, 1.2);
        const body = createCrystalPart(bodyGeo);
        body.position.set(0, 0.6, 0);
        scorpionGroup.add(body);

        // 2. Abdomen (Mesosoma)
        const abdomenGroup = new THREE.Group();
        const segments = 6;
        for (let i = 0; i < segments; i++) {
            const size = 0.8 - (i * 0.1);
            const segGeo = new THREE.SphereGeometry(size, 16, 16);
            segGeo.scale(1, 0.7, 1.3);
            const seg = createCrystalPart(segGeo);
            seg.position.set(0, 0.6, -1.5 - (i * 0.9));
            abdomenGroup.add(seg);
