            { x: -1.1, z: -2.5, rotZ: -1.5, rotX: -0.1 },
        ];

        legPositions.forEach(pos => {
            const leg = createCrystalPart(legGeo);
            leg.position.set(pos.x, 0.3, pos.z);
            leg.rotation.z = pos.rotZ;
            leg.rotation.x = pos.rotX;
            scorpionGroup.add(leg);
        });

        // 5. Pincers (Chelicerae)
        const pincerBaseGeo = new THREE.CylinderGeometry(0.1, 0.15, 1, 8);
        const pincerClawGeo = new THREE.ConeGeometry(0.15, 0.8, 8);

        function createPincer(side) {
            const group = new THREE.Group();
            const base = createCrystalPart(pincerBaseGeo);
            base.rotation.z = side * 1.2;
            base.position.set(side * 0.8, 0.6, 1.2);

            const claw = createCrystalPart(pincerClawGeo);
            claw.position.set(side * 1.5, 0.8, 1.5);
            claw.rotation.z = side * 0.5;
            claw.rotation.x = Math.PI / 2;

            group.add(base);
            group.add(claw);
            return group;
        }

        scorpionGroup.add(createPincer(1));
        scorpionGroup.add(createPincer(-1));

        scene.add(scorpionGroup);

        // Ground (Dark Sand/Rock)
