const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 2000);
camera.position.set(0, 2, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post-Processing (Bloom) ──────────────────────────────────
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));

const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.6, 0.8, 0.2
);
composer.addPass(bloom);

// ── Starfield ────────────────────────────────────────────────
const starCount = 6000;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
const starSizes = new Float32Array(starCount);
const starColors = new Float32Array(starCount * 3);

for (let i = 0; i < starCount; i++) {
  const r = 200 + Math.random() * 800;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  starPos[i * 3]     = r * Math.sin(phi) * Math.cos(theta);
  starPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  starPos[i * 3 + 2] = r * Math.cos(phi);
  starSizes[i] = Math.random() * 2.5 + 0.5;
  const temp = Math.random();
  starColors[i * 3]     = 0.8 + temp * 0.2;
  starColors[i * 3 + 1] = 0.8 + temp * 0.15;
  starColors[i * 3 + 2] = 0.9 + temp * 0.1;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
starGeo.setAttribute('size', new THREE.BufferAttribute(starSizes, 1));
starGeo.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

const starMat = new THREE.ShaderMaterial({
  uniforms: { uTime: { value: 0 } },
  vertexShader: `
    attribute float size;
    attribute vec3 color;
    varying vec3 vColor;
    uniform float uTime;
    void main() {
      vColor = color;
      vec4 mv = modelViewMatrix * vec4(position, 1.0);
      gl_PointSize = size * (200.0 / -mv.z) * (0.8 + 0.2 * sin(uTime * 2.0 + position.x));
      gl_Position = projectionMatrix * mv;
    }
  `,
  fragmentShader: `
    varying vec3 vColor;
    void main() {
      float d = length(gl_PointCoord - 0.5) * 2.0;
      float alpha = 1.0 - smoothstep(0.0, 1.0, d);
      gl_FragColor = vec4(vColor, alpha * 0.9);
    }
  `,
  transparent: true,
  depthWrite: false,
  blending: THREE.AdditiveBlending,
});
scene.add(new THREE.Points(starGeo, starMat));

// ── Nautilus Shell Geometry ──────────────────────────────────
function createNautilusShell() {
  const group = new THREE.Group();

  // Logarithmic spiral parameters
  const a = 0.12;
  const b = 0.18;
  const totalTurns = 3.5;
  const maxTheta = totalTurns * Math.PI * 2;

  // Outer shell surface (volute)
  const shellResU = 120;
  const shellResV = 80;
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= shellResU; i++) {
    const u = i / shellResU;
    const theta = u * maxTheta;
    const r = a * Math.exp(b * theta);

    for (let j = 0; j <= shellResV; j++) {
      const v = j / shellResV;
      const phi = v * Math.PI * 2;

      // Cross-section: slightly flattened circle
      const crossR = r * 0.35 * (0.9 + 0.1 * Math.sin(phi));
      const x = r * Math.cos(theta);
      const y = r * Math.sin(theta);
      const z = 0;

      // Offset from spiral center
      const px = x + crossR * Math.cos(phi) * Math.cos(theta + Math.PI / 2);
      const py = y + crossR * Math.cos(phi) * Math.sin(theta + Math.PI / 2);
      const pz = crossR * Math.sin(phi) * 1.1;

      positions.push(px, py, pz);

      // Approximate normal
      const nx = Math.cos(phi) * Math.cos(theta + Math.PI / 2);
      const ny = Math.cos(phi) * Math.sin(theta + Math.PI / 2);
      const nz = Math.sin(phi) * 1.1;
      const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
      normals.push(nx / len, ny / len, nz / len);

      uvs.push(u, v);
    }
  }

  for (let i = 0; i < shellResU; i++) {
    for (let j = 0; j < shellResV; j++) {
      const a = i * (shellResV + 1) + j;
      const b = a + shellResV + 1;
      indices.push(a, b, a + 1);
      indices.push(b, b + 1, a + 1);
    }
  }

  const shellGeo = new THREE.BufferGeometry();
  shellGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  shellGeo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  shellGeo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  shellGeo.setIndex(indices);
  shellGeo.computeVertexNormals();

  // Chamber walls (septa)
  const chamberCount = Math.floor(totalTurns * 3);
  const chamberGroup = new THREE.Group();

  for (let c = 1; c <= chamberCount; c++) {
    const theta = (c / chamberCount) * maxTheta * 0.85;
    const r = a * Math.exp(b * theta);
    const cx = r * Math.cos(theta);
    const cy = r * Math.sin(theta);
    const crossR = r * 0.35;

    const ringGeo = new THREE.TorusGeometry(crossR * 0.95, 0.015, 6, 48);
    ringGeo.rotateY(theta + Math.PI / 2);
    const ringMat = new THREE.MeshStandardMaterial({
      color: 0xff9944,
      emissive: 0xff6622,
      emissiveIntensity: 0.6,
      metalness: 0.3,
      roughness: 0.4,
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.position.set(cx, cy, 0);
    chamberGroup.add(ring);
  }

  // Central spiral spine (glowing core)
  const spinePoints = [];
  const spineRes = 300;
  for (let i = 0; i <= spineRes; i++) {
    const t = i / spineRes;
    const theta = t * maxTheta;
    const r = a * Math.exp(b * theta);
    spinePoints.push(new THREE.Vector3(
      r * Math.cos(theta),
      r * Math.sin(theta),
      0
    ));
  }
  const spineCurve = new THREE.CatmullRomCurve3(spinePoints);
  const spineGeo = new THREE.TubeGeometry(spineCurve, 200, 0.04, 8, false);
  const spineMat = new THREE.MeshStandardMaterial({
    color: 0xffcc66,
    emissive: 0xffaa33,
    emissiveIntensity: 2.0,
    toneMapped: false,
  });
  group.add(new THREE.Mesh(spineGeo, spineMat));

  // Outer shell material
  const shellMat = new THREE.MeshStandardMaterial({
    color: 0xddaa55,
    emissive: 0xff8833,
    emissiveIntensity: 0.3,
    metalness: 0.6,
    roughness: 0.3,
    side: THREE.DoubleSide,
  });
  const shellMesh = new THREE.Mesh(shellGeo, shellMat);
  group.add(shellMesh);

  group.add(chamberGroup);

  // Inner glow core
  const coreGeo = new THREE.SphereGeometry(0.3, 32, 32);
  const coreMat = new THREE.MeshBasicMaterial({
    color: 0xffdd88,
    transparent: true,
    opacity: 0.9,
  });
  const core = new THREE.Mesh(coreGeo, coreMat);
  group.add(core);

  // Point light inside
  const innerLight = new THREE.PointLight(0xffaa44, 8, 12);
  group.add(innerLight);

  return group;
}

const shell = createNautilusShell();
shell.rotation.x = 0.3;
scene.add(shell);

// ── Ambient Light ────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0x222244, 0.5));
const dirLight = new THREE.DirectionalLight(0x6688cc, 0.4);
dirLight.position.set(5, 5, 5);
scene.add(dirLight);

// ── Floating Particles (dust) ────────────────────────────────
const dustCount = 200;
const dustGeo = new THREE.BufferGeometry();
const dustPos = new Float32Array(dustCount * 3);
for (let i = 0; i < dustCount; i++) {
  dustPos[i * 3]     = (Math.random() - 0.5) * 20;
  dustPos[i * 3 + 1] = (Math.random() - 0.5) * 20;
  dustPos[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0xffaa66,
  size: 0.05,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const dust = new THREE.Points(dustGeo, dustMat);
scene.add(dust);

// ── Animation ────────────────────────────────────────────────
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Shell floating motion
  shell.rotation.y = t * 0.15;
  shell.rotation.z = Math.sin(t * 0.1) * 0.15;
  shell.position.y = Math.sin(t * 0.4) * 0.5;
  shell.position.x = Math.sin(t * 0.25) * 0.3;

  // Dust drift
  dust.rotation.y = t * 0.02;
  dust.rotation.x = t * 0.01;

  // Star twinkle
  starMat.uniforms.uTime.value = t;

  // Camera gentle orbit
  camera.position.x = Math.sin(t * 0.08) * 3;
  camera.position.z = 8 + Math.cos(t * 0.08) * 1.5;
  camera.lookAt(0, 0, 0);

  composer.render();
}

animate();

// ── Resize ───────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What's in the scene

| Element | Details |
|---|---|
| **Nautilus shell** | Procedurally built from a **logarithmic spiral** (`r = a·e^(bθ)`) with a parametric surface, toroidal **chamber walls (septa)**, and a glowing **spinal curve** running through the center |
| **Glow effect** | `UnrealBloomPass` post-processing with high `emissiveIntensity` on the spine, core sphere, and chamber rings — the inner `PointLight` casts warm orange light |
| **Starfield** | 6,000 particles with a custom **twinkling shader** (additive blending, size variation per vertex) |
| **Floating dust** | 200 warm-toned particles drifting slowly around the shell |
| **Animation** | Gentle **bobbing** (`sin` waves on position), slow **Y-axis rotation**, and a subtle **camera orbit** |
| **Materials** | Shell uses `MeshStandardMaterial` with metalness/roughness; the core uses `MeshBasicMaterial` for maximum glow |

Open the file in any modern browser — no build step needed. The shell rotates and floats while the bloom gives it an ethereal, bioluminescent look against the starfield.

