        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x00ffff, 5, 10);
        pointLight.position.set(0, 2, 0);
        scene.add(pointLight);

        // Materials
        // Crystal material for the ant
        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaccff,
            metalness: 0.1,
            roughness: 0.1,
            transmission: 0.9, // Glass-like
            thickness: 1.5,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9
        });

        // Diamond material
        const diamondMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.0,
            roughness: 0.0,
            transmission: 1.0,
            thickness: 2.0,
            ior: 2.4, // Diamond IOR
            clearcoat: 1.0,
            clearcoatRoughness: 0.0,
            envMapIntensity: 1.0,
            transparent: true
        });

        // Helper to create ant parts
        function createPart(geometry, material, pos, rot) {
            const mesh = new THREE.Mesh(geometry, material);
            if (pos) mesh.position.set(pos[0], pos[1], pos[2]);
            if (rot) mesh.rotation.set(rot[0], rot[1], rot[2]);
            return mesh;
        }

        // Build the Ant
        const antGroup = new THREE.Group();

        // Abdomen
        const abdomenGeo = new THREE.SphereGeometry(0.4, 32, 32);
        abdomenGeo.scale(1, 0.8, 1.2);
        const abdomen = createPart(abdomenGeo, crystalMaterial, [0, 0, -0.6]);
        antGroup.add(abdomen);

        // Thorax
        const thoraxGeo = new THREE.SphereGeometry(0.3, 32, 32);
        const thorax = createPart(thoraxGeo, crystalMaterial, [0, 0, 0]);
        antGroup.add(thorax);

        // Head
        const headGeo = new THREE.SphereGeometry(0.25, 32, 32);
        const head = createPart(headGeo, crystalMaterial, [0, 0, 0.6]);
        antGroup.add(head);

        // Mandibles
        const mandibleGeo = new THREE.ConeGeometry(0.05, 0.3, 16);
        const leftMandible = createPart(mandibleGeo, crystalMaterial, [-0.1, 0, 0.9], [Math.PI/2, 0, 0.2]);
        const rightMandible = createPart(mandibleGeo, crystalMaterial, [0.1, 0, 0.9], [Math.PI/2, 0, -0.2]);
        antGroup.add(leftMandible);
        antGroup.add(rightMandible);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.02, 0.01, 0.6, 8);
        const leftAntenna = createPart(antennaGeo, crystalMaterial, [-0.15, 0.2, 0.8], [0, 0, -0.5]);
        const rightAntenna = createPart(antennaGeo, crystalMaterial, [0.15, 0.2, 0.8], [0, 0, 0.5]);
        antGroup.add(leftAntenna);
        antGroup.add(rightAntenna);

        // Legs
        const legGeo = new THREE.CylinderGeometry(0.03, 0.02, 0.8, 8);
        const legPositions = [
            // Front legs
            { pos: [-0.2, -0.1, 0.4], rot: [0, 0, 1.2] },
            { pos: [0.2, -0.1, 0.4], rot: [0, 0, -1.2] },
            // Middle legs
            { pos: [-0.25, -0.1, 0], rot: [0, 0, 0.8] },
            { pos: [0.25, -0.1, 0], rot: [0, 0, -0.8] },
            // Back legs
            { pos: [-0.2, -0.1, -0.4], rot: [0, 0, 0.4] },
            { pos: [0.2, -0.1, -0.4], rot: [0, 0, -0.4] },
        ];

        legPositions.forEach(lp => {
            const leg = createPart(legGeo, crystalMaterial, lp.pos, lp.rot);
            antGroup.add(leg);
        });

        // Build the Diamond
        const diamondGroup = new THREE.Group();
        const diamondGeo = new THREE.OctahedronGeometry(0.35, 0);
        const diamond = new THREE.Mesh(diamondGeo, diamondMaterial);
        diamondGroup.add(diamond);

        // Position diamond on the ant's back (thorax/abdomen area)
        diamondGroup.position.set(0, 0.4, -0.2);
        antGroup.add(diamondGroup);

        // Center the ant
        scene.add(antGroup);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Bobbing motion
            antGroup.position.y = Math.sin(time * 2) * 0.1;

            // Slight rotation
            antGroup.rotation.y = Math.sin(time * 0.5) * 0.2;

            // Diamond sparkle/rotation
            diamond.rotation.y = time * 2;
            diamond.rotation.z = Math.sin(time * 3) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
