        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0xff4400, 5, 20);
        pointLight.position.set(0, 2, 0);
        scene.add(pointLight);

        // Materials
        const metalMat = new THREE.MeshStandardMaterial({ 
            color: 0x888888, 
            metalness: 0.8, 
            roughness: 0.2 
        });
        const copperMat = new THREE.MeshStandardMaterial({ 
            color: 0xb87333, 
            metalness: 0.7, 
            roughness: 0.3 
        });
        const glowMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });

        // Helper to create a gear
        function createGear(radius, teeth, thickness) {
            const gearGroup = new THREE.Group();

            // Main body
            const bodyGeo = new THREE.CylinderGeometry(radius, radius, thickness, 32);
            const body = new THREE.Mesh(bodyGeo, metalMat);
            body.rotation.x = Math.PI / 2;
            gearGroup.add(body);

            // Teeth
            const toothGeo = new THREE.BoxGeometry(radius * 0.3, thickness * 1.2, radius * 0.2);
            for (let i = 0; i < teeth; i++) {
                const tooth = new THREE.Mesh(toothGeo, metalMat);
                const angle = (i / teeth) * Math.PI * 2;
                tooth.position.x = Math.cos(angle) * radius;
                tooth.position.z = Math.sin(angle) * radius;
                tooth.rotation.y = -angle;
                gearGroup.add(tooth);
            }

            // Center hole
            const holeGeo = new THREE.CylinderGeometry(radius * 0.3, radius * 0.3, thickness * 1.1, 16);
            const hole = new THREE.Mesh(holeGeo, new THREE.MeshBasicMaterial({ color: 0x000000 }));
            hole.rotation.x = Math.PI / 2;
            gearGroup.add(hole);

            return gearGroup;
        }

        // Create Gears Base
        const gearsGroup = new THREE.Group();
        scene.add(gearsGroup);

        const bigGear = createGear(3, 12, 1);
        bigGear.position.set(0, 0, 0);
        gearsGroup.add(bigGear);

        const smallGear1 = createGear(1.5, 8, 1);
        smallGear1.position.set(2.5, 0, 1);
        gearsGroup.add(smallGear1);

        const smallGear2 = createGear(1.5, 8, 1);
        smallGear2.position.set(-2.5, 0, 1);
        gearsGroup.add(smallGear2);

        const smallGear3 = createGear(1.5, 8, 1);
        smallGear3.position.set(0, 0, 2.5);
        gearsGroup.add(smallGear3);

        // Create Mechanical Phoenix
        const phoenixGroup = new THREE.Group();
        scene.add(phoenixGroup);
        phoenixGroup.position.y = 2; // Start slightly above gears

        // Body
        const bodyGeo = new THREE.ConeGeometry(1, 3, 8);
        const body = new THREE.Mesh(bodyGeo, copperMat);
        body.rotation.x = Math.PI / 2; // Point forward
        body.rotation.z = Math.PI; // Point up
        phoenixGroup.add(body);

        // Head
        const headGeo = new THREE.SphereGeometry(0.6, 16, 16);
        const head = new THREE.Mesh(headGeo, copperMat);
        head.position.y = 1.5;
        phoenixGroup.add(head);

        // Beak
        const beakGeo = new THREE.ConeGeometry(0.2, 1, 8);
        const beak = new THREE.Mesh(beakGeo, glowMat);
        beak.position.set(0, 1.5, 1);
        beak.rotation.x = Math.PI / 2;
        phoenixGroup.add(beak);

        // Wings (Left)
        const wingGroupL = new THREE.Group();
        wingGroupL.position.set(-0.5, 0.5, 0);
        phoenixGroup.add(wingGroupL);

        const wingGeoL = new THREE.BoxGeometry(0.2, 3, 4);
        const wingL = new THREE.Mesh(wingGeoL, metalMat);
        wingL.rotation.z = Math.PI / 4;
        wingL.position.set(0, 1, -1);
        wingGroupL.add(wingL);

        // Wings (Right)
        const wingGroupR = new THREE.Group();
        wingGroupR.position.set(0.5, 0.5, 0);
        phoenixGroup.add(wingGroupR);

        const wingGeoR = new THREE.BoxGeometry(0.2, 3, 4);
        const wingR = new THREE.Mesh(wingGeoR, metalMat);
        wingR.rotation.z = -Math.PI / 4;
        wingR.position.set(0, 1, -1);
        wingGroupR.add(wingR);

        // Tail Feathers (Mechanical)
        const tailGroup = new THREE.Group();
        phoenixGroup.add(tailGroup);

        for(let i=0; i<3; i++) {
            const featherGeo = new THREE.CylinderGeometry(0.1, 0.05, 2, 8);
            const feather = new THREE.Mesh(featherGeo, copperMat);
            feather.position.y = -1.5;
            feather.rotation.z = (i - 1) * 0.3;
            feather.rotation.x = 0.5;
            tailGroup.add(feather);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate Gears
            bigGear.rotation.y = time * 0.5;
            smallGear1.rotation.y = -time * 1.0;
            smallGear2.rotation.y = -time * 1.0;
            smallGear3.rotation.y = -time * 1.0;

            // Phoenix Rising Animation
            const riseHeight = Math.sin(time * 0.5) * 2 + 4; // Oscillate up and down
            phoenixGroup.position.y = riseHeight;

            // Slight rotation for dynamic feel
            phoenixGroup.rotation.y = Math.sin(time * 0.2) * 0.2;

            // Wing Flapping
            wingGroupL.rotation.z = Math.sin(time * 5) * 0.2;
            wingGroupR.rotation.z = -Math.sin(time * 5) * 0.2;

            // Camera follow slightly
            camera.position.y = riseHeight + 2;
            camera.lookAt(0, riseHeight, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
