        const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const eye = new THREE.Mesh(eyeGeo, eyeMat);
        eye.position.set(0.6, 0.3, 3.4);
        whaleLantern.add(eye);

        // 8. Lantern Ribs (Visual detail to make it look like a lantern)
        const ribGeo = new THREE.TorusGeometry(1.8, 0.05, 8, 32);
        const rib1 = new THREE.Mesh(ribGeo, frameMaterial);
        rib1.position.set(0, 0, 1);
        whaleLantern.add(rib1);

        const rib2 = new THREE.Mesh(ribGeo, frameMaterial);
        rib2.position.set(0, 0, -1);
        whaleLantern.add(rib2);

        // 9. Handle (Top of lantern)
        const handleGeo = new THREE.TorusGeometry(0.5, 0.05, 8, 32, Math.PI);
        const handle = new THREE.Mesh(handleGeo, frameMaterial);
        handle.position.set(0, 2.5, 0);
        handle.rotation.y = Math.PI / 2;
        whaleLantern.add(handle);

        const poleGeo = new THREE.CylinderGeometry(0.05, 0.05, 1, 8);
        const pole = new THREE.Mesh(poleGeo, frameMaterial);
        pole.position.set(0, 2, 0);
        whaleLantern.add(pole);

        // Internal Light Source
        const internalLight = new THREE.PointLight(0xffaa00, 100, 20);
        internalLight.position.set(0, 0, 0);
        whaleLantern.add(internalLight);

        scene.add(whaleLantern);

        // Particles (Stars/Dust)
        const particlesGeo = new THREE.BufferGeometry();
        const particlesCount = 500;
        const posArray = new Float32Array(particlesCount * 3);
        for(let i = 0; i < particlesCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 50;
        }
        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.05,
            color: 0xffffff,
            transparent: true,
            opacity: 0.8
        });
        const particlesMesh = new THREE.Points(particlesGeo, particlesMat);
        scene.add(particlesMesh);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Gentle floating motion
            whaleLantern.position.y = Math.sin(time * 0.5) * 0.5;
            whaleLantern.rotation.z = Math.sin(time * 0.3) * 0.05;
            whaleLantern.rotation.y = Math.sin(time * 0.2) * 0.1;

            // Flicker effect for the light
            internalLight.intensity = 100 + Math.sin(time * 10) * 5 + Math.sin(time * 23) * 2;

            // Rotate particles slowly
            particlesMesh.rotation.y = time * 0.05;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
