```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Glowing Wire Bonsai</title>
<style>
  * { margin: 0; padding: 0; }
  body { overflow: hidden; background: #000; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000811, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 3, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 2.5, 0);
controls.autoRotate = true;
controls.autoRotateSpeed = 0.5;

// ── Bloom ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.6, 0.8, 0.2
);
composer.addPass(bloom);

// ── Materials ──
const wireMat = new THREE.LineBasicMaterial({
  color: 0x00ffaa,
  transparent: true,
  opacity: 0.85,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});

const leafMat = new THREE.PointsMaterial({
  color: 0x88ffcc,
  size: 0.12,
  transparent: true,
  opacity: 0.9,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
  sizeAttenuation: true,
});

const potMat = new THREE.MeshStandardMaterial({
  color: 0x111111,
  emissive: 0x003322,
  emissiveIntensity: 0.3,
  roughness: 0.6,
  metalness: 0.4,
});

// ── Bonsai Generation ──
const group = new THREE.Group();
scene.add(group);

function branch(start, end, depth, maxDepth) {
  if (depth > maxDepth) return;

  // Curved segment via midpoint offset
  const mid = new THREE.Vector3().lerpVectors(start, end, 0.5);
  const offset = new THREE.Vector3(
    (Math.random() - 0.5) * 0.3 * (1 - depth / maxDepth),
    (Math.random() - 0.5) * 0.1,
    (Math.random() - 0.5) * 0.3 * (1 - depth / maxDepth)
  );
  mid.add(offset);

  const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
  const points = curve.getPoints(12);
  const geo = new THREE.BufferGeometry().setFromPoints(points);

  // Color shifts from warm trunk to cool tips
  const t = depth / maxDepth;
  const col = new THREE.Color().lerpColors(
    new THREE.Color(0xff6622),
    new THREE.Color(0x00ffaa),
    t
  );
  const mat = wireMat.clone();
  mat.color = col;
  mat.linewidth = Math.max(1, 3 - depth * 0.5);

  group.add(new THREE.Line(geo, mat));

  // Branch children
  if (depth < maxDepth) {
    const len = end.distanceTo(start);
    const count = depth < 2 ? 3 : 2;
    const spread = 0.6 + Math.random() * 0.4;

    for (let i = 0; i < count; i++) {
      const angle = new THREE.Vector3(
        (Math.random() - 0.5) * spread,
        0.3 + Math.random() * 0.5,
        (Math.random() - 0.5) * spread
      ).normalize();

      const newLen = len * (0.6 + Math.random() * 0.15);
      const newEnd = end.clone().add(angle.multiplyScalar(newLen));
      branch(end.clone(), newEnd, depth + 1, maxDepth);
    }
  }

  // Leaves at tips
  if (depth >= maxDepth - 1) {
    const count = 8 + Math.floor(Math.random() * 12);
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      positions[i * 3]     = end.x + (Math.random() - 0.5) * 0.6;
      positions[i * 3 + 1] = end.y + (Math.random() - 0.5) * 0.6;
      positions[i * 3 + 2] = end.z + (Math.random() - 0.5) * 0.6;
    }
    const leafGeo = new THREE.BufferGeometry();
    leafGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    group.add(new THREE.Points(leafGeo, leafMat));
  }
}

// Start trunk
const trunkBase = new THREE.Vector3(0, 0.5, 0);
const trunkTop = new THREE.Vector3(0.05, 2.2, 0.05);
branch(trunkBase, trunkTop, 0, 7);

// ── Pot ──
const potGeo = new THREE.CylinderGeometry(0.7, 0.5, 0.6, 24, 1, true);
const pot = new THREE.Mesh(potGeo, potMat);
pot.position.y = 0.3;
group.add(pot);

const potRim = new THREE.TorusGeometry(0.7, 0.04, 8, 32);
const rimMat = new THREE.MeshStandardMaterial({
  color: 0x00ffaa, emissive: 0x00ffaa, emissiveIntensity: 0.5
});
const rim = new THREE.Mesh(potRim, rimMat);
rim.rotation.x = Math.PI / 2;
rim.position.y = 0.6;
group.add(rim);

// Soil surface
const soilGeo = new THREE.CircleGeometry(0.68, 24);
const soilMat = new THREE.MeshStandardMaterial({ color: 0x0a0a0a });
const soil = new THREE.Mesh(soilGeo, soilMat);
soil.rotation.x = -Math.PI / 2;
soil.position.y = 0.58;
group.add(soil);

// ── Ground ring glow ──
const ringGeo = new THREE.RingGeometry(1.5, 1.55, 64);
const ringMat = new THREE.MeshBasicMaterial({
  color: 0x00ffaa, transparent: true, opacity: 0.3,
  blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
});
const ring = new THREE.Mesh(ringGeo, ringMat);
ring.rotation.x = -Math.PI / 2;
ring.position.y = 0.01;
scene.add(ring);

// ── Ambient particles ──
const dustCount = 200;
const dustPos = new Float32Array(dustCount * 3);
for (let i = 0; i < dustCount; i++) {
  dustPos[i * 3]     = (Math.random() - 0.5) * 12;
  dustPos[i * 3 + 1] = Math.random() * 8;
  dustPos[i * 3 + 2] = (Math.random() - 0.5) * 12;
}
const dustGeo = new THREE.BufferGeometry();
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0x00ffaa, size: 0.03, transparent: true, opacity: 0.5,
  blending: THREE.AdditiveBlending, depthWrite: false,
});
const dust = new THREE.Points(dustGeo, dustMat);
scene.add(dust);

// ── Lights ──
scene.add(new THREE.AmbientLight(0x002233, 0.5));
const pointLight = new THREE.PointLight(0x00ffaa, 2, 15);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// ── Animate ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Gentle sway
  group.rotation.y = Math.sin(t * 0.15) * 0.05;

  // Pulse glow
  const pulse = 1.4 + Math.sin(t * 2) * 0.3;
  bloom.strength = pulse;
  pointLight.intensity = 1.5 + Math.sin(t * 2) * 0.8;

  // Dust drift
  const dp = dust.geometry.attributes.position.array;
  for (let i = 0; i < dustCount; i++) {
    dp[i * 3 + 1] += Math.sin(t + i) * 0.0005;
    dp[i * 3]     += Math.cos(t * 0.5 + i * 0.1) * 0.0003;
  }
  dust.geometry.attributes.position.needsUpdate = true;

  controls.update();
  composer.render();
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's inside:**

| Feature | Details |
|---|---|
| **Recursive branching** | 7 levels of quadratic Bézier curves — warm orange trunk fades to cyan tips |
| **Wire aesthetic** | `LineBasicMaterial` with additive blending for that neon-wire look |
| **Bloom glow** | `UnrealBloomPass` post-processing with a gentle pulsing intensity |
| **Leaf clusters** | `Points` scattered at branch tips for a foliage canopy |
| **Pot** | Dark cylinder with a glowing cyan rim and soil disk |
| **Atmosphere** | Floating dust particles, exponential fog, ground ring |
| **Interaction** | `OrbitControls` with auto-rotate and damping |
| **Animation** | Subtle tree sway, pulsing glow, drifting particles |

