    (Math.random() - 0.5) * 1.4,
    2.2 + Math.random() * 0.8,
    (Math.random() - 0.5) * 1.4
  );
  cloud.scale.y = 0.6;
  stormGroup.add(cloud);
  clouds.push(cloud);
}

// --- Rain ---
const RAIN_COUNT = 400;
const rainGeo = new THREE.BufferGeometry();
const rainPositions = new Float32Array(RAIN_COUNT * 3);
const rainVelocities = new Float32Array(RAIN_COUNT);
const rainLengths = new Float32Array(RAIN_COUNT);

for (let i = 0; i < RAIN_COUNT; i++) {
  rainPositions[i * 3] = (Math.random() - 0.5) * 1.6;
  rainPositions[i * 3 + 1] = Math.random() * 3;
  rainPositions[i * 3 + 2] = (Math.random() - 0.5) * 1.6;
  rainVelocities[i] = 0.03 + Math.random() * 0.04;
  rainLengths[i] = 0.04 + Math.random() * 0.06;
}
rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPositions, 3));
const rainMat = new THREE.LineBasicMaterial({ color: 0x8899cc, transparent: true, opacity: 0.4 });
const rainLines = [];
for (let i = 0; i < RAIN_COUNT; i++) {
  const lineGeo = new THREE.BufferGeometry();
  lineGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const line = new THREE.Line(lineGeo, rainMat.clone());
  stormGroup.add(line);
  rainLines.push(line);
}

// --- Lightning ---
const lightningBolts = [];
const lightningMat = new THREE.LineBasicMaterial({ color: 0xddeeff, transparent: true, opacity: 0 });
const lightningGlowMat = new THREE.LineBasicMaterial({ color: 0x8888ff, transparent: true, opacity: 0 });

function generateLightningBolt(startX, startZ) {
  const points = [];
  let x = startX, y = 2.8, z = startZ;
  const segments = 8 + Math.floor(Math.random() * 8);
  points.push(new THREE.Vector3(x, y, z));
  for (let i = 0; i < segments; i++) {
    x += (Math.random() - 0.5) * 0.4;
    y -= 0.2 + Math.random() * 0.25;
    z += (Math.random() - 0.5) * 0.4;
    x = Math.max(-0.9, Math.min(0.9, x));
    z = Math.max(-0.9, Math.min(0.9, z));
    points.push(new THREE.Vector3(x, y, z));
    // branch
    if (Math.random() > 0.65 && i < segments - 2) {
      const branchPoints = [];
      let bx = x, by = y, bz = z;
      const bSegs = 2 + Math.floor(Math.random() * 3);
      branchPoints.push(new THREE.Vector3(bx, by, bz));
      for (let j = 0; j < bSegs; j++) {
        bx += (Math.random() - 0.5) * 0.3;
        by -= 0.15 + Math.random() * 0.2;
        bz += (Math.random() - 0.5) * 0.3;
        bx = Math.max(-0.85, Math.min(0.85, bx));
        bz = Math.max(-0.85, Math.min(0.85, bz));
        branchPoints.push(new THREE.Vector3(bx, by, bz));
      }
      const bGeo = new THREE.BufferGeometry().setFromPoints(branchPoints);
      const bLine = new THREE.Line(bGeo, lightningMat.clone());
      const bGlow = new THREE.Line(bGeo, lightningGlowMat.clone());
      stormGroup.add(bLine);
      stormGroup.add(bGlow);
      lightningBolts.push({ line: bLine, glow: bGlow, life: 0, active: false });
    }
  }
  const geo = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geo, lightningMat.clone());
  const glow = new THREE.Line(geo, lightningGlowMat.clone());
  stormGroup.add(line);
  stormGroup.add(glow);
  lightningBolts.push({ line, glow, life: 0, active: false });
}

// Pre-generate some bolts
for (let i = 0; i < 6; i++) {
  generateLightningBolt((Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8);
}

let lightningTimer = 0;
let nextLightning = 1 + Math.random() * 3;
let flashIntensity = 0;

// Lightning point light
const lightningLight = new THREE.PointLight(0xaabbff, 0, 8);
lightningLight.position.set(0, 2, 0);
stormGroup.add(lightningLight);

// Ambient
const ambient = new THREE.AmbientLight(0x111122, 0.5);
scene.add(ambient);

// Subtle warm backlight
const backLight = new THREE.DirectionalLight(0xff6622, 0.15);
backLight.position.set(0, 0, -3);
scene.add(backLight);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  // Gentle lantern sway
  lantern.rotation.y = Math.sin(t * 0.3) * 0.08;
  lantern.position.y = Math.sin(t * 0.5) * 0.05;

  // Flicker inner glow
  glowLight.intensity = 0.6 + Math.sin(t * 2) * 0.15 + Math.sin(t * 7) * 0.1;
  innerGlowMat.opacity = 0.12 + Math.sin(t * 2) * 0.05;
  innerGlow.scale.setScalar(0.8 + Math.sin(t * 1.5) * 0.15);

  // Update rain
  for (let i = 0; i < RAIN_COUNT; i++) {
    rainPositions[i * 3 + 1] -= rainVelocities[i];
    if (rainPositions[i * 3 + 1] < 0) {
      rainPositions[i * 3 + 1] = 3 + Math.random() * 0.5;
      rainPositions[i * 3] = (Math.random() - 0.5) * 1.6;
      rainPositions[i * 3 + 2] = (Math.random() - 0.5) * 1.6;
    }
    const px = rainPositions[i * 3], py = rainPositions[i * 3 + 1], pz = rainPositions[i * 3 + 2];
    const len = rainLengths[i];
    const pos = rainLines[i].geometry.attributes.position.array;
    pos[0] = px; pos[1] = py; pos[2] = pz;
    pos[3] = px; pos[4] = py - len; pos[5] = pz;
    rainLines[i].geometry.attributes.position.needsUpdate = true;
  }
  rainGeo.attributes.position.needsUpdate = true;

  // Cloud drift
  clouds.forEach((c, i) => {
    c.position.x += Math.sin(t * 0.2 + i) * 0.0003;
    c.position.z += Math.cos(t * 0.15 + i * 2) * 0.0003;
  });

  // Lightning
  lightningTimer += dt;
  if (lightningTimer > nextLightning && flashIntensity < 0.1) {
    flashIntensity = 1;
    nextLightning = lightningTimer + 1.5 + Math.random() * 4;
    // Activate random bolts
