        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Hourglass Group
        const hourglassGroup = new THREE.Group();

        // 1. The Glass Container (Lathe Geometry for smooth curves)
        const points = [];
        // Bottom rim
        points.push(new THREE.Vector2(0, -2));
        points.push(new THREE.Vector2(1.2, -2));
        // Bottom curve
        points.push(new THREE.Vector2(1.0, -1.5));
        points.push(new THREE.Vector2(0.2, 0)); // Neck
        // Top curve
        points.push(new THREE.Vector2(1.0, 1.5));
        points.push(new THREE.Vector2(1.2, 2));
        // Top rim
        points.push(new THREE.Vector2(0, 2));

        const glassGeometry = new THREE.LatheGeometry(points, 32);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.1,
            transmission: 0.9, // Glass-like transparency
            thickness: 1.0,
            transparent: true,
            opacity: 0.3,
            side: THREE.DoubleSide
        });
        const glassMesh = new THREE.Mesh(glassGeometry, glassMaterial);
        hourglassGroup.add(glassMesh);

        // 2. The "Liquid Light" (Glowing Sand)
        // We simulate the sand with two cones (top and bottom) that change size
        const sandMaterial = new THREE.MeshBasicMaterial({
            color: 0xffaa00, // Golden light
            transparent: true,
            opacity: 0.8
        });

        // Top Sand (draining)
        const topSandGeo = new THREE.ConeGeometry(1.0, 1.5, 32);
        const topSand = new THREE.Mesh(topSandGeo, sandMaterial);
        topSand.position.y = 0.75;
        topSand.rotation.x = Math.PI; // Invert
        hourglassGroup.add(topSand);

        // Bottom Sand (filling)
        const bottomSandGeo = new THREE.ConeGeometry(1.0, 1.5, 32);
        const bottomSand = new THREE.Mesh(bottomSandGeo, sandMaterial);
        bottomSand.position.y = -0.75;
        hourglassGroup.add(bottomSand);

        // Stream of light in the middle
        const streamGeo = new THREE.CylinderGeometry(0.02, 0.02, 2, 8);
        const streamMat = new THREE.MeshBasicMaterial({ color: 0xffddaa });
        const stream = new THREE.Mesh(streamGeo, streamMat);
        hourglassGroup.add(stream);

        // 3. Lighting
        // Ambient light for general visibility
        const ambientLight = new THREE.AmbientLight(0x404040, 2); 
        scene.add(ambientLight);

        // Point light inside the hourglass to make the "liquid" glow
        const innerLight = new THREE.PointLight(0xffaa00, 5, 10);
        innerLight.position.set(0, 0, 0);
        hourglassGroup.add(innerLight);

        // Rim light for the glass
        const rimLight = new THREE.DirectionalLight(0xffffff, 2);
        rimLight.position.set(5, 5, 5);
        scene.add(rimLight);

        scene.add(hourglassGroup);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Floating motion
            hourglassGroup.position.y = Math.sin(time * 0.5) * 0.5;
            hourglassGroup.rotation.y = Math.sin(time * 0.2) * 0.2;

            // Sand animation (simulating flow)
            const cycle = (Math.sin(time * 0.5) + 1) / 2; // 0 to 1

            // Top sand shrinks
            topSand.scale.set(1, 1 - cycle, 1);
            topSand.position.y = 0.75 - (cycle * 0.75);

            // Bottom sand grows
            bottomSand.scale.set(1, cycle, 1);
            bottomSand.position.y = -0.75 + (cycle * 0.75);

            // Stream flicker
            stream.scale.y = 0.8 + Math.random() * 0.2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
