            const x = Math.sin(time * speed) * 4;
            const z = Math.sin(time * speed * 2) * 2;
            const y = Math.sin(time * speed * 0.5) * 0.5;

            snailGroup.position.set(x, y, z);

            // Rotate snail to face direction of movement
            // Calculate next position for lookAt
            const nextTime = time + 0.1;
            const nextX = Math.sin(nextTime * speed) * 4;
            const nextZ = Math.sin(nextTime * speed * 2) * 2;
            const nextY = Math.sin(nextTime * speed * 0.5) * 0.5;

            snailGroup.lookAt(nextX, nextY, nextZ);

            // Update Point Light to follow snail
            pointLight.position.copy(snailGroup.position);
            pointLight.position.y += 1;

            // Update Trail
            history.push(snailGroup.position.clone());
            if (history.length > trailLength) {
                history.shift();
            }

            // Update BufferGeometry
            for (let i = 0; i < trailLength; i++) {
                if (i < history.length) {
                    const pos = history[i];
                    trailPositions[i * 3] = pos.x;
                    trailPositions[i * 3 + 1] = pos.y;
                    trailPositions[i * 3 + 2] = pos.z;

                    // Fade color from Cyan (head) to Purple (tail)
                    const alpha = i / history.length;
                    trailColors[i * 3] = 0.0;     // R
                    trailColors[i * 3 + 1] = alpha; // G (fades out)
                    trailColors[i * 3 + 2] = 1.0;   // B
                } else {
                    // Hide unused points
                    trailPositions[i * 3] = 0;
                    trailPositions[i * 3 + 1] = 0;
                    trailPositions[i * 3 + 2] = 0;
                }
            }

            trailGeometry.attributes.position.needsUpdate = true;
            trailGeometry.attributes.color.needsUpdate = true;
            trailGeometry.setDrawRange(0, history.length);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
