        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaddff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.9, // Glass-like
            thickness: 1.5,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.0
        });

        // Create segments
        for (let i = 0; i < segmentCount; i++) {
            const size = 0.4 - (i * 0.02); // Tapering slightly
            const geometry = new THREE.SphereGeometry(size, 16, 16);
            const segment = new THREE.Mesh(geometry, crystalMaterial);

            // Initial positions (will be updated in animation)
            segment.position.set(0, 7.5, 0);
            segments.push(segment);
            caterpillarGroup.add(segment);
        }

        // Eyes for the head (first segment)
        const eyeGeo = new THREE.SphereGeometry(0.1, 8, 8);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const eye1 = new THREE.Mesh(eyeGeo, eyeMat);
        const eye2 = new THREE.Mesh(eyeGeo, eyeMat);
        eye1.position.set(-0.2, 0.2, 0.3);
        eye2.position.set(0.2, 0.2, 0.3);
        segments[0].add(eye1);
        segments[0].add(eye2);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Animate Caterpillar walking on the mushroom cap
            // We want it to crawl along the surface of the sphere cap
            const radius = 3.5; // Cap radius
            const baseHeight = 4; // Cap base height

            // Path parameters
            const speed = 0.5;
            const angle = time * speed;

            // Create a wavy path on the sphere
            // We'll make it crawl in a circle around the top
            const crawlRadius = 2.0; // Distance from center of cap

            for (let i = 0; i < segmentCount; i++) {
                // Calculate position along the path
                // Add a phase offset for the body segments to create a wave
                const phaseOffset = i * 0.5; 
                const currentAngle = angle + phaseOffset;

                // X, Z position on the circle
                const x = Math.cos(currentAngle) * crawlRadius;
                const z = Math.sin(currentAngle) * crawlRadius;

                // Calculate Y position on the sphere surface
                // x^2 + z^2 + (y - baseHeight)^2 = radius^2
                // (y - baseHeight)^2 = radius^2 - (x^2 + z^2)
                // y = baseHeight + sqrt(radius^2 - (x^2 + z^2))

                const distSq = x*x + z*z;
                let y;
                if (distSq < radius * radius) {
                    y = baseHeight + Math.sqrt(radius * radius - distSq);
                } else {
                    y = baseHeight; // Fallback
                }

                segments[i].position.set(x, y, z);

                // Orient segment to face the direction of movement (tangent to circle)
                // Tangent vector is (-sin, 0, cos)
                const lookX = -Math.sin(currentAngle) * crawlRadius;
                const lookZ = Math.cos(currentAngle) * crawlRadius;

                // Look at the next point in the path
                const nextAngle = currentAngle + 0.1;
                const nextX = Math.cos(nextAngle) * crawlRadius;
                const nextZ = Math.sin(nextAngle) * crawlRadius;
                const nextDistSq = nextX*nextX + nextZ*nextZ;
                let nextY = baseHeight;
                if (nextDistSq < radius * radius) {
                    nextY = baseHeight + Math.sqrt(radius * radius - nextDistSq);
                }

                segments[i].lookAt(nextX, nextY, nextZ);

                // Add a little "breathing" or bobbing
                segments[i].position.y += Math.sin(time * 2 + i) * 0.05;
            }

            // Gentle camera rotation
            camera.position.x = Math.sin(time * 0.1) * 12;
            camera.position.z = Math.cos(time * 0.1) * 12;
            camera.lookAt(0, 3, 0);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
