        });
        const canopy = new THREE.Mesh(canopyGeometry, canopyMaterial);
        canopy.scale.y = 0.4; // Flatten it
        canopy.position.y = 1.5;
        umbrellaGroup.add(canopy);

        // Shaft
        const shaftGeometry = new THREE.CylinderGeometry(0.05, 0.05, 3, 8);
        const shaftMaterial = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const shaft = new THREE.Mesh(shaftGeometry, shaftMaterial);
        shaft.position.y = 0;
        umbrellaGroup.add(shaft);

        // Handle (simple curve approximation using a cylinder rotated)
        const handleGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 8);
        const handle = new THREE.Mesh(handleGeometry, shaftMaterial);
        handle.position.y = -1.4;
        handle.rotation.z = Math.PI / 2;
        umbrellaGroup.add(handle);

        // Hook
        const hookGeometry = new THREE.TorusGeometry(0.15, 0.03, 8, 16, Math.PI);
        const hook = new THREE.Mesh(hookGeometry, shaftMaterial);
        hook.position.set(0, -1.4, 0.4);
        hook.rotation.y = Math.PI / 2;
        umbrellaGroup.add(hook);

