            starPositions[i * 3] = (Math.random() - 0.5) * 15; // x
            starPositions[i * 3 + 1] = Math.random() * 10 + 2; // y (start above)
            starPositions[i * 3 + 2] = (Math.random() - 0.5) * 15; // z
            starSpeeds[i] = Math.random() * 0.05 + 0.02;
        }

        starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));

        // Create a simple star texture programmatically
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
