                    positions[i * 3] = (Math.random() - 0.5) * 15;
                    positions[i * 3 + 2] = (Math.random() - 0.5) * 15;
                }
            }
            stars.geometry.attributes.position.needsUpdate = true;

            renderer.render(scene, camera);
