        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffaa00, 1.5);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0xffffff, 2);
        spotLight.position.set(0, 10, 0);
        spotLight.angle = Math.PI / 6;
        spotLight.penumbra = 1;
        spotLight.castShadow = true;
        scene.add(spotLight);

        // Ground
        const planeGeometry = new THREE.PlaneGeometry(100, 100);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -0.5;
        plane.receiveShadow = true;
        scene.add(plane);

        // The Book
        const bookGroup = new THREE.Group();

        // Cover
        const coverGeo = new THREE.BoxGeometry(4, 0.2, 3);
        const coverMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.6 });
        const cover = new THREE.Mesh(coverGeo, coverMat);
        cover.position.y = 0;
        cover.castShadow = true;
        cover.receiveShadow = true;
        bookGroup.add(cover);

        // Pages (White block slightly smaller)
        const pagesGeo = new THREE.BoxGeometry(3.8, 0.15, 2.8);
        const pagesMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
        const pages = new THREE.Mesh(pagesGeo, pagesMat);
        pages.position.y = 0.05;
        pages.receiveShadow = true;
        bookGroup.add(pages);

        // Spine detail
        const spineGeo = new THREE.BoxGeometry(0.2, 0.25, 3);
        const spineMat = new THREE.MeshStandardMaterial({ color: 0x5D2906 });
        const spine = new THREE.Mesh(spineGeo, spineMat);
        spine.position.set(-2.1, 0, 0);
        bookGroup.add(spine);

        scene.add(bookGroup);

        // The Train
        const trainGroup = new THREE.Group();

        // Locomotive Body
        const locoGeo = new THREE.BoxGeometry(1.2, 1, 0.8);
        const locoMat = new THREE.MeshStandardMaterial({ color: 0xcc0000, metalness: 0.3, roughness: 0.4 });
        const loco = new THREE.Mesh(locoGeo, locoMat);
        loco.position.set(0, 0.7, 0);
        loco.castShadow = true;
        trainGroup.add(loco);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(0.8, 0.8, 0.7);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.set(-0.3, 1.4, 0);
        cabin.castShadow = true;
        trainGroup.add(cabin);

        // Chimney
        const chimneyGeo = new THREE.CylinderGeometry(0.15, 0.2, 0.6, 16);
        const chimneyMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const chimney = new THREE.Mesh(chimneyGeo, chimneyMat);
        chimney.position.set(0.4, 1.3, 0);
        chimney.castShadow = true;
        trainGroup.add(chimney);

        // Carriage
        const carriageGeo = new THREE.BoxGeometry(1.5, 0.8, 0.7);
        const carriageMat = new THREE.MeshStandardMaterial({ color: 0x0044cc, metalness: 0.2, roughness: 0.5 });
        const carriage = new THREE.Mesh(carriageGeo, carriageMat);
        carriage.position.set(-1.8, 0.6, 0);
        carriage.castShadow = true;
        trainGroup.add(carriage);

        // Wheels Helper
        function createWheel(x, z) {
            const wheelGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.1, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(x, 0.25, z);
            wheel.castShadow = true;
            return wheel;
        }

        // Add wheels to locomotive
        trainGroup.add(createWheel(0.4, 0.45));
        trainGroup.add(createWheel(0.4, -0.45));
        trainGroup.add(createWheel(-0.4, 0.45));
        trainGroup.add(createWheel(-0.4, -0.45));

        // Add wheels to carriage
        trainGroup.add(createWheel(-1.3, 0.45));
        trainGroup.add(createWheel(-1.3, -0.45));
        trainGroup.add(createWheel(-2.3, 0.45));
        trainGroup.add(createWheel(-2.3, -0.45));

        // Initial position: Hidden behind/inside the book
        trainGroup.position.set(0, 0.1, -2); 
        trainGroup.scale.set(0.1, 0.1, 0.1); // Start small
        scene.add(trainGroup);

        // Animation Variables
        let time = 0;
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // Animate Train Emerging
            // 1. Scale up from the book
            const scaleTarget = 1.0;
            const currentScale = Math.min(trainGroup.scale.x + delta * 0.5, scaleTarget);
            trainGroup.scale.set(currentScale, currentScale, currentScale);

            // 2. Move forward (Z axis)
            // Start at z=-2 (behind book), move to z=4 (in front)
            const zTarget = 6;
            const zStart = -2;
            // Simple easing
            const progress = Math.min((time * 0.5), 1); 
            trainGroup.position.z = zStart + (zTarget - zStart) * progress;

            // 3. Gentle bobbing
            trainGroup.position.y = 0.1 + Math.sin(time * 5) * 0.02;

            // 4. Rotate book slightly to look dynamic
            bookGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
