        const rimLight = new THREE.SpotLight(0x00ffff, 5);
        rimLight.position.set(-5, 5, -5);
        rimLight.lookAt(0,0,0);
        scene.add(rimLight);

        // Materials
        const metalMat = new THREE.MeshStandardMaterial({ 
            color: 0xaaaaaa, 
            metalness: 0.9, 
            roughness: 0.2 
        });
        const darkMetalMat = new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            metalness: 0.8, 
            roughness: 0.5 
        });
        const glowMat = new THREE.MeshStandardMaterial({ 
            color: 0x00ffff, 
            emissive: 0x00ffff, 
            emissiveIntensity: 2 
        });
        const jointMat = new THREE.MeshStandardMaterial({ 
            color: 0xffaa00, 
            metalness: 0.5, 
            roughness: 0.5 
        });

        // Butterfly Group
        const butterfly = new THREE.Group();
        scene.add(butterfly);

        // Body
        const bodyGroup = new THREE.Group();
        butterfly.add(bodyGroup);

        // Thorax/Abdomen
        const bodyGeo = new THREE.CylinderGeometry(0.15, 0.1, 2.5, 8);
        const bodyMesh = new THREE.Mesh(bodyGeo, metalMat);
        bodyMesh.rotation.x = Math.PI / 2;
        bodyMesh.castShadow = true;
        bodyGroup.add(bodyMesh);

        // Head
        const headGeo = new THREE.SphereGeometry(0.25, 16, 16);
        const headMesh = new THREE.Mesh(headGeo, darkMetalMat);
        headMesh.position.z = 1.3;
        headMesh.castShadow = true;
        bodyGroup.add(headMesh);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.5, 8);
        const antennaL = new THREE.Mesh(antennaGeo, metalMat);
        antennaL.position.set(-0.15, 0.4, 1.4);
        antennaL.rotation.z = Math.PI / 3;
        antennaL.rotation.x = Math.PI / 6;
        bodyGroup.add(antennaL);

        const antennaR = new THREE.Mesh(antennaGeo, metalMat);
        antennaR.position.set(0.15, 0.4, 1.4);
        antennaR.rotation.z = -Math.PI / 3;
        antennaR.rotation.x = Math.PI / 6;
        bodyGroup.add(antennaR);

        // Wings Construction
        function createWing(side) {
            const wingGroup = new THREE.Group();
            // Pivot point slightly outside body
            wingGroup.position.set(side * 0.2, 0, 0);

            // Main Upper Wing Plate
            const wingShape = new THREE.Shape();
            wingShape.moveTo(0, 0);
            wingShape.bezierCurveTo(1, 1.5, 2.5, 1.5, 3, 0);
            wingShape.bezierCurveTo(2.5, -0.5, 1, -0.5, 0, 0);

            const extrudeSettings = { depth: 0.05, bevelEnabled: true, bevelThickness: 0.05, bevelSize: 0.05, bevelSegments: 2 };
            const wingGeo = new THREE.ExtrudeGeometry(wingShape, extrudeSettings);
            const wingMesh = new THREE.Mesh(wingGeo, metalMat);
            wingMesh.rotation.x = -Math.PI / 2; // Lay flat
            wingMesh.position.set(side * 0.5, 0, 0); // Offset from pivot
            wingMesh.castShadow = true;
            wingGroup.add(wingMesh);

            // Mechanical Struts/Details
            const strutGeo = new THREE.CylinderGeometry(0.05, 0.05, 2, 8);
            const strut = new THREE.Mesh(strutGeo, darkMetalMat);
            strut.rotation.z = Math.PI / 2;
            strut.position.set(side * 1.5, 0, 0);
            wingGroup.add(strut);

            // Lower Wing Plate
            const lowerWingShape = new THREE.Shape();
            lowerWingShape.moveTo(0, 0);
            lowerWingShape.bezierCurveTo(1, -0.5, 2, -1.5, 2.5, -2);
            lowerWingShape.bezierCurveTo(1.5, -2, 0.5, -1, 0, 0);

            const lowerWingGeo = new THREE.ExtrudeGeometry(lowerWingShape, extrudeSettings);
            const lowerWingMesh = new THREE.Mesh(lowerWingGeo, darkMetalMat);
            lowerWingMesh.rotation.x = -Math.PI / 2;
            lowerWingMesh.position.set(side * 0.5, -0.2, 0);
            lowerWingMesh.castShadow = true;
            wingGroup.add(lowerWingMesh);

            // Glowing Core on Wing
            const coreGeo = new THREE.SphereGeometry(0.15, 16, 16);
            const core = new THREE.Mesh(coreGeo, glowMat);
            core.position.set(side * 1.5, 0, 0.05);
            wingGroup.add(core);

            // Joint at pivot
            const jointGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.3, 16);
            const joint = new THREE.Mesh(jointGeo, jointMat);
            joint.rotation.x = Math.PI / 2;
            wingGroup.add(joint);

            return wingGroup;
        }

        const leftWing = createWing(-1);
        const rightWing = createWing(1);
        butterfly.add(leftWing);
        butterfly.add(rightWing);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Wing Flapping
            // Using a sine wave for smooth oscillation
            const flapSpeed = 4;
            const flapAmplitude = 0.6; // Radians
            const flapAngle = Math.sin(time * flapSpeed) * flapAmplitude;

            leftWing.rotation.z = flapAngle;
            rightWing.rotation.z = -flapAngle;

            // Hovering motion
            butterfly.position.y = Math.sin(time * 1.5) * 0.3;
            butterfly.rotation.y = Math.sin(time * 0.5) * 0.2;
            butterfly.rotation.z = Math.sin(time * 0.8) * 0.05;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
