<body>
    <div id="info">✦ Crystal Raven ✦</div>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        // Environment for reflections (crucial for crystal look)
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        pmremGenerator.compileEquirectangularShader();
        const roomEnv = new RoomEnvironment();
        const envMap = pmremGenerator.fromScene(roomEnv).texture;
        scene.environment = envMap;
        roomEnv.dispose();

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.target.set(0, 1, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const spotLight = new THREE.SpotLight(0xffffff, 20);
        spotLight.position.set(5, 10, 5);
        spotLight.angle = Math.PI / 4;
        spotLight.penumbra = 0.5;
        scene.add(spotLight);

        const blueLight = new THREE.PointLight(0x4444ff, 5, 10);
        blueLight.position.set(-3, 2, 2);
        scene.add(blueLight);

        const purpleLight = new THREE.PointLight(0xff44ff, 5, 10);
        purpleLight.position.set(3, 2, -2);
        scene.add(purpleLight);

        // --- Materials ---

        // Bone Material
        const boneMaterial = new THREE.MeshStandardMaterial({
            color: 0xdddddd,
            roughness: 0.4,
            metalness: 0.1
        });

        // Crystal Material
        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x110022, // Dark purple base
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 2.0,
            ior: 2.33, // Diamond-like refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            envMapIntensity: 2.0,
            transparent: true,
            opacity: 0.9
        });

        // --- Geometry Construction ---

        const skullGroup = new THREE.Group();
        const ravenGroup = new THREE.Group();

        // 1. Build Skull
        function createSkull() {
            // Cranium
            const craniumGeo = new THREE.SphereGeometry(1.2, 32, 32);
            const cranium = new THREE.Mesh(craniumGeo, boneMaterial);
            cranium.scale.set(1, 1.1, 0.9);
            skullGroup.add(cranium);

            // Jaw
            const jawGeo = new THREE.BoxGeometry(1.4, 0.6, 0.8);
            const jaw = new THREE.Mesh(jawGeo, boneMaterial);
            jaw.position.set(0, -0.8, 0.2);
            jaw.rotation.x = 0.2;
            skullGroup.add(jaw);

            // Eye Sockets (Dark spheres slightly inside)
            const socketGeo = new THREE.SphereGeometry(0.35, 16, 16);
            const socketMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

            const leftSocket = new THREE.Mesh(socketGeo, socketMat);
            leftSocket.position.set(-0.5, 0.2, 0.8);
            skullGroup.add(leftSocket);

            const rightSocket = new THREE.Mesh(socketGeo, socketMat);
            rightSocket.position.set(0.5, 0.2, 0.8);
            skullGroup.add(rightSocket);

            // Nose Cavity
            const noseGeo = new THREE.ConeGeometry(0.2, 0.4, 4);
            const nose = new THREE.Mesh(noseGeo, socketMat);
            nose.position.set(0, -0.2, 1.0);
            nose.rotation.x = Math.PI; // Point down
            skullGroup.add(nose);

            // Teeth (Simple boxes)
            const toothGeo = new THREE.BoxGeometry(0.15, 0.2, 0.1);
            const toothMat = new THREE.MeshStandardMaterial({ color: 0xeeeeee });

            for(let i = -3; i <= 3; i++) {
                const tooth = new THREE.Mesh(toothGeo, toothMat);
                tooth.position.set(i * 0.18, -1.1, 0.5);
                skullGroup.add(tooth);
            }

            skullGroup.position.y = -0.5;
            scene.add(skullGroup);
        }

        // 2. Build Raven
        function createRaven() {
            // Body
            const bodyGeo = new THREE.SphereGeometry(0.6, 32, 32);
            const body = new THREE.Mesh(bodyGeo, crystalMaterial);
            body.scale.set(1, 0.8, 1.2);
            ravenGroup.add(body);

            // Head
            const headGeo = new THREE.SphereGeometry(0.35, 32, 32);
            const head = new THREE.Mesh(headGeo, crystalMaterial);
            head.position.set(0, 0.3, 0.6);
            ravenGroup.add(head);

            // Beak
            const beakGeo = new THREE.ConeGeometry(0.1, 0.6, 16);
            const beak = new THREE.Mesh(beakGeo, crystalMaterial);
            beak.position.set(0, 0.2, 1.0);
            beak.rotation.x = Math.PI / 2;
            ravenGroup.add(beak);

            // Wings
            const wingShape = new THREE.Shape();
            wingShape.moveTo(0, 0);
            wingShape.lineTo(1.5, 0.5);
            wingShape.lineTo(1.2, -0.2);
            wingShape.lineTo(0, -0.2);

            const wingGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.05, bevelEnabled: false });

            const leftWing = new THREE.Mesh(wingGeo, crystalMaterial);
            leftWing.position.set(0.5, 0.1, -0.2);
            leftWing.rotation.y = -0.2;
            leftWing.rotation.z = 0.2;
            ravenGroup.add(leftWing);

            const rightWing = new THREE.Mesh(wingGeo, crystalMaterial);
            rightWing.position.set(-0.5, 0.1, -0.2);
            rightWing.rotation.y = Math.PI + 0.2; // Flip
            rightWing.rotation.z = -0.2;
            ravenGroup.add(rightWing);

            // Tail
            const tailGeo = new THREE.ConeGeometry(0.4, 1.0, 4);
            const tail = new THREE.Mesh(tailGeo, crystalMaterial);
            tail.position.set(0, -0.2, -0.8);
            tail.rotation.x = -Math.PI / 4;
            ravenGroup.add(tail);

            // Position Raven on Skull
            ravenGroup.position.set(0, 1.2, 0);
            ravenGroup.rotation.y = Math.PI; // Face camera
            scene.add(ravenGroup);
        }

        createSkull();
        createRaven();

        // --- Animation ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Subtle floating for the raven
            ravenGroup.position.y = 1.2 + Math.sin(time * 0.5) * 0.1;

            // Wing flap (subtle)
            ravenGroup.children[3].rotation.z = 0.2 + Math.sin(time * 2) * 0.1; // Left wing
            ravenGroup.children[4].rotation.z = -0.2 - Math.sin(time * 2) * 0.1; // Right wing

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
