            transmission: 0.95, // Glass-like transparency
            thickness: 0.5,
            transparent: true,
            opacity: 0.3,
            side: THREE.DoubleSide
        });
        const jar = new THREE.Mesh(jarGeo, jarMat);
        jarGroup.add(jar);

        // Jar Lid
        const lidGeo = new THREE.CylinderGeometry(2.6, 2.6, 0.2, 32);
        const lidMat = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.8, roughness: 0.2 });
        const lid = new THREE.Mesh(lidGeo, lidMat);
        lid.position.y = 3;
        jarGroup.add(lid);

        // Jar Base (bottom)
        const baseGeo = new THREE.CylinderGeometry(2.5, 2.5, 0.1, 32);
        const base = new THREE.Mesh(baseGeo, jarMat);
        base.position.y = -3;
        jarGroup.add(base);

        scene.add(jarGroup);

        // 3. The Jellyfish
        const jellyfish = new THREE.Group();

        // Bell (Dome)
        const bellGeo = new THREE.SphereGeometry(1.2, 32, 32, 0, Math.PI * 2, 0, Math.PI / 2);
        const bellMat = new THREE.MeshStandardMaterial({
            color: 0x00ffff,
            emissive: 0x00aaaa,
            emissiveIntensity: 2,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide
        });
        const bell = new THREE.Mesh(bellGeo, bellMat);
        jellyfish.add(bell);

        // Tentacles
        const tentacleCount = 8;
        const tentacles = [];
        for(let i = 0; i < tentacleCount; i++) {
            const angle = (i / tentacleCount) * Math.PI * 2;
            const radius = 0.8;
            const startX = Math.cos(angle) * radius;
            const startZ = Math.sin(angle) * radius;

            // Create a wavy curve
            const points = [];
            for(let j = 0; j <= 10; j++) {
                points.push(new THREE.Vector3(
                    startX + Math.sin(j * 0.5) * 0.2, 
                    -j * 0.4, 
                    startZ + Math.cos(j * 0.5) * 0.2
                ));
            }
            const curve = new THREE.CatmullRomCurve3(points);
            const tubeGeo = new THREE.TubeGeometry(curve, 20, 0.04, 8, false);
            const tubeMat = new THREE.MeshStandardMaterial({
                color: 0x00ffff,
                emissive: 0x005555,
                emissiveIntensity: 1.5
            });
            const tube = new THREE.Mesh(tubeGeo, tubeMat);
            jellyfish.add(tube);
            tentacles.push({ mesh: tube, index: i });
        }

        jellyfish.position.y = 0;
        scene.add(jellyfish);

        // 4. Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1);
        scene.add(ambientLight);

        // The glow source inside the jellyfish
        const jellyLight = new THREE.PointLight(0x00ffff, 15, 10);
        jellyLight.position.set(0, 0, 0);
        jellyfish.add(jellyLight);

        // 5. Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Bobbing motion
            jellyfish.position.y = Math.sin(time) * 0.5;
            jellyfish.rotation.y = Math.sin(time * 0.5) * 0.2;

            // Pulse the bell slightly
            const scale = 1 + Math.sin(time * 2) * 0.05;
            bell.scale.set(scale, 1/scale, scale);

            // Wiggle tentacles
            tentacles.forEach((t, i) => {
                t.mesh.rotation.x = Math.sin(time * 3 + i) * 0.1;
                t.mesh.rotation.z = Math.cos(time * 3 + i) * 0.1;
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
