    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        scene.fog = new THREE.Fog(0x111111, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 15);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const pointLight = new THREE.PointLight(0x00ffff, 5, 20);
        pointLight.position.set(-5, 0, 5);
        scene.add(pointLight);

        // Ice Material
        const iceMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaddff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like transparency
            thickness: 1.5,
            ior: 1.31, // Refractive index of ice
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9
        });

        // Violin Construction
        const violinGroup = new THREE.Group();

        // 1. Body Shape
        const shape = new THREE.Shape();
        // Approximate violin body outline
        shape.moveTo(0, 3.5);
        shape.bezierCurveTo(2.5, 3.5, 3.5, 2, 3.5, 0);
        shape.bezierCurveTo(3.5, -2, 2.5, -3.5, 0, -3.5);
        shape.bezierCurveTo(-2.5, -3.5, -3.5, -2, -3.5, 0);
        shape.bezierCurveTo(-3.5, 2, -2.5, 3.5, 0, 3.5);

        const extrudeSettings = {
            steps: 2,
            depth: 0.8,
            bevelEnabled: true,
            bevelThickness: 0.2,
            bevelSize: 0.2,
            bevelSegments: 5
        };

        const bodyGeometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
        bodyGeometry.center(); // Center the geometry
        const bodyMesh = new THREE.Mesh(bodyGeometry, iceMaterial);
        bodyMesh.rotation.x = Math.PI / 2; // Lay flat
        violinGroup.add(bodyMesh);

        // 2. Neck
        const neckGeometry = new THREE.CylinderGeometry(0.3, 0.3, 6, 16);
        const neckMesh = new THREE.Mesh(neckGeometry, iceMaterial);
        neckMesh.position.set(0, 0, 4.5); // Position above body
        neckMesh.rotation.x = Math.PI / 2;
        violinGroup.add(neckMesh);

        // 3. Scroll (Top of neck)
        const scrollGeometry = new THREE.TorusGeometry(0.35, 0.1, 16, 32);
        const scrollMesh = new THREE.Mesh(scrollGeometry, iceMaterial);
        scrollMesh.position.set(0, 0, 7.5);
        violinGroup.add(scrollMesh);

        // 4. Fingerboard (Darker ice or just distinct)
        const fingerboardGeo = new THREE.BoxGeometry(0.6, 0.1, 4);
        const fingerboardMat = new THREE.MeshPhysicalMaterial({
            color: 0x88ccff,
            roughness: 0.2,
            transmission: 0.8,
            thickness: 0.5
        });
        const fingerboard = new THREE.Mesh(fingerboardGeo, fingerboardMat);
        fingerboard.position.set(0, 0.2, 5);
        violinGroup.add(fingerboard);

        // 5. Strings
        const stringMaterial = new THREE.LineBasicMaterial({ color: 0xffffff });
        for (let i = -1; i <= 1; i++) {
            const points = [];
            points.push(new THREE.Vector3(i * 0.2, 0, 7.5)); // Scroll
            points.push(new THREE.Vector3(i * 0.2, 0, 3.5)); // Body top
            const geometry = new THREE.BufferGeometry().setFromPoints(points);
            const line = new THREE.Line(geometry, stringMaterial);
            violinGroup.add(line);
        }

        // 6. Bridge
        const bridgeGeo = new THREE.BoxGeometry(1.5, 0.1, 0.2);
        const bridge = new THREE.Mesh(bridgeGeo, iceMaterial);
        bridge.position.set(0, 0.4, 2.5);
        violinGroup.add(bridge);

        scene.add(violinGroup);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Floating effect
            violinGroup.position.y = Math.sin(time) * 0.5;

            // Gentle rotation
            violinGroup.rotation.y = Math.sin(time * 0.5) * 0.2;
            violinGroup.rotation.z = Math.cos(time * 0.3) * 0.05;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
