```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dandelion Fireflies</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; background: #000; cursor: pointer; }
  canvas { display: block; }
  #hint {
    position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%);
    color: rgba(255,220,130,0.7); font-family: Georgia, serif;
    font-size: 14px; letter-spacing: 2px; pointer-events: none;
    animation: fadeHint 4s ease-in-out infinite;
  }
  @keyframes fadeHint { 0%,100%{ opacity:0.3 } 50%{ opacity:0.9 } }
</style>
</head>
<body>
<div id="hint">click anywhere to blow the seeds</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ── Scene Setup ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x050510, 0.025);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 2, 12);
camera.lookAt(0, 4, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Glow Texture (canvas-generated) ──
function makeGlowTexture(r, g, b) {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, `rgba(${r},${g},${b},1)`);
  grad.addColorStop(0.2, `rgba(${r},${g},${b},0.6)`);
  grad.addColorStop(0.5, `rgba(${r},${g},${b},0.15)`);
  grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}

const fireflyTex = makeGlowTexture(255, 230, 100);
const seedTex = makeGlowTexture(255, 200, 80);
const stemGlowTex = makeGlowTexture(180, 255, 120);

// ── Lighting ──
scene.add(new THREE.AmbientLight(0x111122, 0.5));

const dandelionLight = new THREE.PointLight(0xffcc44, 2, 25);
dandelionLight.position.set(0, 6, 0);
scene.add(dandelionLight);

// ── Stem ──
const stemCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, -2, 0),
  new THREE.Vector3(0.1, 0, 0.05),
  new THREE.Vector3(-0.05, 2, -0.02),
  new THREE.Vector3(0, 4.5, 0),
]);
const stemGeo = new THREE.TubeGeometry(stemCurve, 20, 0.06, 8, false);
const stemMat = new THREE.MeshStandardMaterial({
  color: 0x2a5a1a, emissive: 0x0a2a05, roughness: 0.8
});
scene.add(new THREE.Mesh(stemGeo, stemMat));

// ── Dandelion Head ──
const HEAD_Y = 4.5;
const NUM_SEEDS = 80;
const seeds = [];
const seedGroup = new THREE.Group();
seedGroup.position.y = HEAD_Y;
scene.add(seedGroup);

// Central core
const coreGeo = new THREE.SphereGeometry(0.15, 16, 16);
const coreMat = new THREE.MeshStandardMaterial({
  color: 0xffeeaa, emissive: 0xffcc44, emissiveIntensity: 0.8
});
const core = new THREE.Mesh(coreGeo, coreMat);
seedGroup.add(core);

// Pappus lines + seeds
for (let i = 0; i < NUM_SEEDS; i++) {
  const phi = Math.acos(2 * Math.random() - 1);
  const theta = Math.random() * Math.PI * 2;
  const r = 0.8 + Math.random() * 0.6;

  const dir = new THREE.Vector3(
    Math.sin(phi) * Math.cos(theta),
    Math.sin(phi) * Math.sin(theta),
    Math.cos(phi)
  );

  // Thin pappus line
  const lineLen = 0.5 + Math.random() * 0.4;
  const lineEnd = dir.clone().multiplyScalar(r + lineLen);
  const lineStart = dir.clone().multiplyScalar(r * 0.3);
  const lineGeo = new THREE.BufferGeometry().setFromPoints([lineStart, lineEnd]);
  const lineMat = new THREE.LineBasicMaterial({
    color: 0xffddaa, transparent: true, opacity: 0.5
  });
  const line = new THREE.Line(lineGeo, lineMat);
  seedGroup.add(line);

  // Seed sphere
  const seedGeo = new THREE.SphereGeometry(0.035, 6, 6);
  const seedMat = new THREE.MeshStandardMaterial({
    color: 0xffeebb, emissive: 0xffcc55, emissiveIntensity: 0.6,
    transparent: true, opacity: 0.9
  });
  const seedMesh = new THREE.Mesh(seedGeo, seedMat);
  seedMesh.position.copy(lineEnd);
  seedGroup.add(seedMesh);

  // Glow sprite
  const spriteMat = new THREE.SpriteMaterial({
    map: seedTex, color: 0xffdd88,
    transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending
  });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.set(0.25, 0.25, 1);
  seedMesh.add(sprite);

  seeds.push({
    mesh: seedMesh, sprite, line, lineMat, seedMat,
    attached: true,
    // firefly state
    pos: lineEnd.clone(),
    vel: new THREE.Vector3(),
    flickerSpeed: 1 + Math.random() * 3,
    flickerPhase: Math.random() * Math.PI * 2,
    driftFreq: 0.3 + Math.random() * 0.7,
    driftAmp: 0.5 + Math.random() * 1.5,
    driftPhase: Math.random() * Math.PI * 2,
    light: null,
    spriteLightMat: null,
    baseScale: 0.25,
  });
}

// ── Ground mist particles ──
const mistCount = 200;
const mistGeo = new THREE.BufferGeometry();
const mistPos = new Float32Array(mistCount * 3);
for (let i = 0; i < mistCount; i++) {
  mistPos[i*3]   = (Math.random() - 0.5) * 40;
  mistPos[i*3+1] = -1 + Math.random() * 2;
  mistPos[i*3+2] = (Math.random() - 0.5) * 40;
}
mistGeo.setAttribute('position', new THREE.BufferAttribute(mistPos, 3));
const mistMat = new THREE.PointsMaterial({
  color: 0x334422, size: 0.15, transparent: true, opacity: 0.3,
  blending: THREE.AdditiveBlending, depthWrite: false
});
scene.add(new THREE.Points(mistGeo, mistMat));

// ── Blowing state ──
let blowing = false;
let blowTime = 0;
let blowProgress = 0;

window.addEventListener('click', () => {
  if (!blowing) {
    blowing = true;
    blowTime = 0;
    document.getElementById('hint').style.display = 'none';
  }
});

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.getElapsedTime();

  // Gentle dandelion sway
  seedGroup.rotation.z = Math.sin(t * 0.3) * 0.03;
  seedGroup.rotation.x = Math.sin(t * 0.2) * 0.02;

  // Core pulse
  coreMat.emissiveIntensity = 0.6 + Math.sin(t * 1.5) * 0.2;
  dandelionLight.intensity = 1.5 + Math.sin(t * 1.5) * 0.5;

  // ── Blow logic ──
  if (blowing) {
    blowTime += dt;
    blowProgress = Math.min(blowTime / 3.0, 1);

    for (let i = 0; i < seeds.length; i++) {
      const s = seeds[i];
      if (!s.attached) continue;

      // Staggered detachment
      const stagger = Math.pow(Math.random(), 2);
      if (blowProgress > stagger * 0.6) {
        s.attached = false;

        // Launch velocity: outward + wind
        const launchDir = s.pos.clone().normalize();
        s.vel.copy(launchDir).multiplyScalar(1.5 + Math.random() * 2);
        s.vel.x += (Math.random() - 0.3) * 2;
        s.vel.y += Math.random() * 1;
        s.vel.z += (Math.random() - 0.3) * 2;

        // Hide line and seed mesh
        s.line.visible = false;
        s.mesh.visible = false;

        // Create firefly light
        s.light = new THREE.PointLight(0xffdd66, 0.6, 4);
        s.mesh.add(s.light);
        s.mesh.visible = true;

        // Upgrade sprite
        s.sprite.material.map = fireflyTex;
        s.sprite.material.color.set(0xffeeaa);
        s.sprite.material.opacity = 0.9;
        s.baseScale = 0.4 + Math.random() * 0.3;
      }
    }

    // Dim dandelion as seeds leave
    const attachedCount = seeds.filter(s => s.attached).length;
    const ratio = attachedCount / NUM_SEEDS;
    dandelionLight.intensity = 0.3 + ratio * 1.7;
    coreMat.emissiveIntensity = 0.1 + ratio * 0.7;
    seedGroup.scale.setScalar(0.3 + ratio * 0.7);
  }

  // ── Firefly animation ──
  for (const s of seeds) {
    if (s.attached) continue;

    // Organic drift
    s.vel.y += Math.sin(t * s.driftFreq + s.driftPhase) * s.driftAmp * dt * 0.5;
    s.vel.x += Math.cos(t * s.driftFreq * 0.7 + s.driftPhase) * s.driftAmp * dt * 0.3;
    s.vel.z += Math.sin(t * s.driftFreq * 0.5 + s.driftPhase * 1.3) * s.driftAmp * dt * 0.3;

    // Damping
    s.vel.multiplyScalar(0.995);

    // Gentle upward drift
    s.vel.y += 0.15 * dt;

    s.mesh.position.add(s.vel.clone().multiplyScalar(dt));

    // Flicker
    const flicker = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(t * s.flickerSpeed + s.flickerPhase));
    const flicker2 = 0.5 + 0.5 * Math.sin(t * s.flickerSpeed * 1.7 + s.flickerPhase * 2.1);
    const brightness = flicker * flicker2;

    s.sprite.material.opacity = brightness * 0.9;
    s.sprite.scale.setScalar(s.baseScale * (0.8 + brightness * 0.4));

    if (s.light) {
      s.light.intensity = brightness * 0.8;
    }

    // Wrap around if too far
    if (s.mesh.position.y > 30 || s.mesh.position.length() > 50) {
      s.mesh.position.set(
        (Math.random() - 0.5) * 20,
        -1 + Math.random() * 3,
        (Math.random() - 0.5) * 20
      );
      s.vel.set(
        (Math.random() - 0.5) * 2,
        0.5 + Math.random(),
        (Math.random() - 0.5) * 2
      );
    }
  }

  // Camera orbit
  const camAngle = t * 0.08;
  camera.position.x = Math.sin(camAngle) * 12;
  camera.position.z = Math.cos(camAngle) * 12;
  camera.position.y = 2 + Math.sin(t * 0.15) * 1.5;
  camera.lookAt(0, 4, 0);

  renderer.render(scene, camera);
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What you'll see:**

- 🌿 A **green dandelion stem** rising from a misty dark ground, topped with a **glowing golden puff** of ~80 seeds on delicate pappus filaments
- ✨ The dandelion head **gently sways** and **pulses** with warm light
- 💨 **Click anywhere** to "blow" — seeds detach in a staggered burst, launching outward with physics
- 🪲 Each seed **transforms into a firefly**: glowing sprite + point light with **realistic flickering** (dual-sine modulation), organic drift motion, and gentle upward floating
- 🔦 The dandelion dims as seeds leave, transferring its glow to the fireflies
- 📷 The camera **slowly orbits** the scene; fireflies that drift too far respawn near the ground

**Key techniques:**
- Canvas-generated radial glow textures for sprite-based bloom (no post-processing needed)
- `AdditiveBlending` for natural light accumulation
- `ACESFilmicToneMapping` for cinematic color

