    <div id="info">Crystal Rose — drag to orbit · scroll to zoom</div>

    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.03);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 4, 8);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.maxPolarAngle = Math.PI / 2 - 0.05; // Prevent going below ground

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 1);
        scene.add(ambientLight);

        const mainLight = new THREE.DirectionalLight(0xffffff, 2);
        mainLight.position.set(5, 10, 5);
        scene.add(mainLight);

        // Colored lights for crystal refraction effect
        const pointLight1 = new THREE.PointLight(0xff00ff, 100, 20);
        pointLight1.position.set(-3, 2, 3);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0x00ffff, 100, 20);
        pointLight2.position.set(3, 2, -3);
        scene.add(pointLight2);

        // --- Stone Base ---
        const stoneGroup = new THREE.Group();
        scene.add(stoneGroup);

        // Create a jagged rock base
        const stoneGeo = new THREE.IcosahedronGeometry(2.5, 2);
        const posAttr = stoneGeo.attributes.position;
        for (let i = 0; i < posAttr.count; i++) {
            const x = posAttr.getX(i);
            const y = posAttr.getY(i);
            const z = posAttr.getZ(i);

            // Flatten the bottom
            if (y < 0) {
                posAttr.setY(i, y * 0.3);
            }

            // Add noise
            const noise = (Math.random() - 0.5) * 0.4;
            posAttr.setX(i, x + noise);
            posAttr.setZ(i, z + noise);
        }
        stoneGeo.computeVertexNormals();

        const stoneMat = new THREE.MeshStandardMaterial({
            color: 0x2a2a2a,
            roughness: 0.9,
            metalness: 0.1,
            flatShading: true
        });
        const stone = new THREE.Mesh(stoneGeo, stoneMat);
        stone.position.y = -1.5;
        stoneGroup.add(stone);

        // --- Crystal Rose ---
        const roseGroup = new THREE.Group();
        scene.add(roseGroup);

        // Crystal Material
        const crystalMat = new THREE.MeshPhysicalMaterial({
            color: 0xff00aa,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 2.0,
            ior: 2.4, // Diamond-like index of refraction
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.9
        });

        // Stem
        const stemCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, -1.5, 0),
            new THREE.Vector3(0.3, -0.5, 0.2),
            new THREE.Vector3(-0.2, 0.5, -0.1),
            new THREE.Vector3(0, 1.5, 0)
        ]);
        const stemGeo = new THREE.TubeGeometry(stemCurve, 20, 0.08, 8, false);
        const stem = new THREE.Mesh(stemGeo, crystalMat);
        roseGroup.add(stem);

        // Petals Container
        const petalContainer = new THREE.Group();
        petalContainer.position.y = 1.5;
        roseGroup.add(petalContainer);

        function createPetalGeometry() {
            const shape = new THREE.Shape();
            shape.moveTo(0, 0);
            shape.bezierCurveTo(0.4, 0.4, 0.4, 1.2, 0, 1.8);
            shape.bezierCurveTo(-0.4, 1.2, -0.4, 0.4, 0, 0);

            const extrudeSettings = {
                steps: 1,
                depth: 0.02,
                bevelEnabled: true,
                bevelThickness: 0.01,
                bevelSize: 0.01,
                bevelSegments: 1
            };

            const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            geo.center();

            // Bend the petal
            const pos = geo.attributes.position;
            for(let i=0; i<pos.count; i++){
                const y = pos.getY(i);
                const z = pos.getZ(i);
                // Bend upwards based on height
                const bend = y * 0.8; 
                const newY = y * Math.cos(bend) - z * Math.sin(bend);
                const newZ = y * Math.sin(bend) + z * Math.cos(bend);
                pos.setY(i, newY);
                pos.setZ(i, newZ);
            }
            geo.computeVertexNormals();
            return geo;
        }

        const petalGeo = createPetalGeometry();
        const petals = [];

        // Generate petals in a spiral
        const layers = 5;
        const petalsPerLayer = 6;

        for (let i = 0; i < layers; i++) {
            const layerScale = 1.0 - (i * 0.12);
            const layerY = i * 0.15;
            const layerRotOffset = i * 0.6; // Spiral rotation

            for (let j = 0; j < petalsPerLayer; j++) {
                const angle = (j / petalsPerLayer) * Math.PI * 2 + layerRotOffset;
                const petal = new THREE.Mesh(petalGeo, crystalMat);

                petal.scale.setScalar(layerScale);
                petal.position.y = layerY;
                petal.rotation.y = angle;
                petal.rotation.x = -Math.PI / 3; // Initial closed angle

                // Store initial state for animation
                petal.userData = {
                    baseRotX: -Math.PI / 3,
                    openRotX: -Math.PI / 6, // Open angle
                    layerIndex: i
                };

                petalContainer.add(petal);
                petals.push(petal);
            }
        }

        // --- Animation ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Blooming Animation (0 to 1 over 3 seconds)
            const bloomDuration = 3.0;
            const rawBloom = Math.min(1, time / bloomDuration);
            // Ease out cubic
            const bloom = 1 - Math.pow(1 - rawBloom, 3);

            // Scale the whole rose up
            roseGroup.scale.setScalar(bloom);

            // Rotate petals to open
            petals.forEach((petal) => {
                const targetRotX = petal.userData.baseRotX + (petal.userData.openRotX - petal.userData.baseRotX) * bloom;
                petal.rotation.x = targetRotX;

                // Subtle floating movement
                petal.position.y += Math.sin(time * 2 + petal.userData.layerIndex) * 0.0005;
            });

            // Slow rotation of the whole rose
            roseGroup.rotation.y = time * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        animate();

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
