<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hot Air Balloon Lantern</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { overflow: hidden; background: #0a0a1a; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a0a1a, 0.012);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 4, 18);
camera.lookAt(0, 2, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Stars ──
const starGeo = new THREE.BufferGeometry();
const starCount = 1500;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++) {
  starPos[i] = (Math.random() - 0.5) * 200;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.15, sizeAttenuation: true });
scene.add(new THREE.Points(starGeo, starMat));

// ── Balloon Group ──
const balloon = new THREE.Group();
scene.add(balloon);

// ── Balloon Envelope (Lathe) ──
const profile = [];
const segments = 30;
for (let i = 0; i <= segments; i++) {
  const t = i / segments;
  const angle = Math.PI * t;
  // Hot air balloon shape: wide middle, pinched at top and bottom
  let r;
  if (t < 0.05) {
    r = Math.sin(angle * 5) * 0.15; // top pinch
  } else if (t > 0.85) {
    const bt = (t - 0.85) / 0.15;
    r = 2.2 * Math.cos(bt * Math.PI * 0.5) * 0.45;
  } else {
    const mt = (t - 0.05) / 0.8;
    r = 2.2 * Math.sin(mt * Math.PI) * (0.85 + 0.15 * Math.sin(mt * Math.PI));
  }
  const y = 5.5 - t * 6.5;
  profile.push(new THREE.Vector2(Math.max(r, 0.01), y));
}

const envelopeGeo = new THREE.LatheGeometry(profile, 32);
const envelopeMat = new THREE.MeshStandardMaterial({
  color: 0xdd4422,
  emissive: 0xff6633,
  emissiveIntensity: 0.6,
  roughness: 0.4,
  metalness: 0.1,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.92,
});
const envelope = new THREE.Mesh(envelopeGeo, envelopeMat);
balloon.add(envelope);

// ── Vertical Stripes on Envelope ──
const stripeCount = 12;
for (let i = 0; i < stripeCount; i++) {
  const angle = (i / stripeCount) * Math.PI * 2;
  const stripeGeo = new THREE.BufferGeometry();
  const stripePts = [];
  for (let j = 0; j <= 20; j++) {
    const t = j / 20;
    const y = 5.5 - t * 6.5;
    let r;
    if (t < 0.05) r = Math.sin(t * Math.PI * 5) * 0.15;
    else if (t > 0.85) {
      const bt = (t - 0.85) / 0.15;
      r = 2.2 * Math.cos(bt * Math.PI * 0.5) * 0.45;
    } else {
      const mt = (t - 0.05) / 0.8;
      r = 2.2 * Math.sin(mt * Math.PI) * (0.85 + 0.15 * Math.sin(mt * Math.PI));
    }
    stripePts.push(new THREE.Vector3(
      Math.cos(angle) * (r + 0.02),
      y,
      Math.sin(angle) * (r + 0.02)
    ));
  }
  stripeGeo.setFromPoints(stripePts);
  const stripeMat = new THREE.LineBasicMaterial({
    color: i % 2 === 0 ? 0xffaa44 : 0xffdd66,
    transparent: true,
    opacity: 0.7,
  });
  balloon.add(new THREE.Line(stripeGeo, stripeMat));
}

// ── Inner Glow Sphere ──
const glowGeo = new THREE.SphereGeometry(1.8, 16, 16);
const glowMat = new THREE.MeshBasicMaterial({
  color: 0xffaa44,
  transparent: true,
  opacity: 0.25,
});
const glow = new THREE.Mesh(glowGeo, glowMat);
glow.position.y = 2.5;
balloon.add(glow);

// ── Flame at Bottom of Envelope ──
const flameGeo = new THREE.SphereGeometry(0.35, 8, 8);
const flameMat = new THREE.MeshBasicMaterial({ color: 0xffcc44, transparent: true, opacity: 0.9 });
const flame = new THREE.Mesh(flameGeo, flameMat);
flame.position.y = -0.8;
flame.scale.set(1, 1.8, 1);
balloon.add(flame);

const flameInnerGeo = new THREE.SphereGeometry(0.2, 8, 8);
const flameInnerMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.95 });
const flameInner = new THREE.Mesh(flameInnerGeo, flameInnerMat);
flameInner.position.y = -0.75;
flameInner.scale.set(0.8, 1.5, 0.8);
balloon.add(flameInner);

// ── Ropes ──
const ropeMat = new THREE.LineBasicMaterial({ color: 0xccbb99 });
const basketTop = -1.5;
const basketCorners = [
  [-0.5, basketTop], [0.5, basketTop], [-0.5, basketTop], [0.5, basketTop]
];
for (let i = 0; i < 4; i++) {
  const angle = (i / 4) * Math.PI * 2 + Math.PI / 4;
  const pts = [
    new THREE.Vector3(Math.cos(angle) * 1.8, -0.8, Math.sin(angle) * 1.8),
    new THREE.Vector3(basketCorners[i][0], basketTop, Math.sin(angle) * 0.3),
  ];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  balloon.add(new THREE.Line(geo, ropeMat));
}

// ── Basket ──
const basketGeo = new THREE.CylinderGeometry(0.55, 0.45, 0.7, 8, 1, true);
const basketMat = new THREE.MeshStandardMaterial({
  color: 0x8B6914,
  roughness: 0.8,
  side: THREE.DoubleSide,
});
const basket = new THREE.Mesh(basketGeo, basketMat);
basket.position.y = basketTop - 0.35;
balloon.add(basket);

// Basket bottom
const basketBotGeo = new THREE.CircleGeometry(0.45, 8);
const basketBot = new THREE.Mesh(basketBotGeo, basketMat);
basketBot.rotation.x = -Math.PI / 2;
basketBot.position.y = basketTop - 0.7;
balloon.add(basketBot);

// ── Tiny Passengers ──
function createPassenger(color, x, z, headColor) {
  const group = new THREE.Group();

  // Body
  const bodyGeo = new THREE.CapsuleGeometry(0.12, 0.3, 4, 8);
  const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.6 });
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.position.y = 0.25;
  group.add(body);

  // Head
  const headGeo = new THREE.SphereGeometry(0.13, 8, 8);
  const headMat = new THREE.MeshStandardMaterial({ color: headColor || 0xffcc99, roughness: 0.5 });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.y = 0.52;
  group.add(head);

  // Tiny hat
  const hatGeo = new THREE.CylinderGeometry(0.1, 0.14, 0.08, 8);
  const hatMat = new THREE.MeshStandardMaterial({ color: 0x333366, roughness: 0.5 });
  const hat = new THREE.Mesh(hatGeo, hatMat);
  hat.position.y = 0.63;
  group.add(hat);
  const hatBrim = new THREE.Mesh(
    new THREE.CylinderGeometry(0.18, 0.18, 0.02, 8),
    hatMat
  );
  hatBrim.position.y = 0.59;
  group.add(hatBrim);

  group.position.set(x, basketTop - 0.7, z);
  return group;
}

const passengers = [
  createPassenger(0x2255aa, -0.2, -0.15, 0xffcc99),
  createPassenger(0xaa2255, 0.2, -0.1, 0xffcc99),
  createPassenger(0x22aa55, -0.15, 0.15, 0xeebb88),
  createPassenger(0xaa8822, 0.15, 0.18, 0xddaa77),
];
passengers.forEach(p => balloon.add(p));

// ── Lantern Light ──
const pointLight = new THREE.PointLight(0xff8833, 3, 25, 1.5);
pointLight.position.set(0, 2.5, 0);
balloon.add(pointLight);

const warmLight = new THREE.PointLight(0xffaa55, 1.5, 10);
warmLight.position.set(0, -0.5, 0);
balloon.add(warmLight);

scene.add(new THREE.AmbientLight(0x222244, 0.5));
scene.add(new THREE.DirectionalLight(0x4466aa, 0.3));

// ── Fire Particles ──
const particleCount = 80;
const particlesGeo = new THREE.BufferGeometry();
const pPositions = new Float32Array(particleCount * 3);
const pVelocities = [];
const pSizes = new Float32Array(particleCount);

function resetParticle(i) {
  pPositions[i * 3] = (Math.random() - 0.5) * 0.4;
  pPositions[i * 3 + 1] = -0.8;
  pPositions[i * 3 + 2] = (Math.random() - 0.5) * 0.4;
  pVelocities[i] = {
    x: (Math.random() - 0.5) * 0.01,
    y: 0.02 + Math.random() * 0.03,
    z: (Math.random() - 0.5) * 0.01,
    life: 0,
  };
  pSizes[i] = 0.05 + Math.random() * 0.1;
}

for (let i = 0; i < particleCount; i++) resetParticle(i);

particlesGeo.setAttribute('position', new THREE.BufferAttribute(pPositions, 3));
particlesGeo.setAttribute('size', new THREE.BufferAttribute(pSizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xffaa33,
  size: 0.12,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const fireParticles = new THREE.Points(particlesGeo, particleMat);
balloon.add(fireParticles);

// ── Ambient Sparkle Particles ──
const sparkleCount = 200;
const sparkleGeo = new THREE.BufferGeometry();
const sparklePos = new Float32Array(sparkleCount * 3);
const sparkleData = [];

for (let i = 0; i < sparkleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.random() * Math.PI;
  const r = 3 + Math.random() * 8;
  sparklePos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  sparklePos[i * 3 + 1] = (Math.random() - 0.3) * 15;
  sparklePos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  sparkleData.push({
    baseX: sparklePos[i * 3],
    baseY: sparklePos[i * 3 + 1],
    baseZ: sparklePos[i * 3 + 2],
    speed: 0.5 + Math.random() * 2,
    offset: Math.random() * Math.PI * 2,
  });
}

sparkleGeo.setAttribute('position', new THREE.BufferAttribute(sparklePos, 3));
const sparkleMat = new THREE.PointsMaterial({
  color: 0xffddaa,
  size: 0.08,
  transparent: true,
  opacity: 0.5,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const sparkles = new THREE.Points(sparkleGeo, sparkleMat);
scene.add(sparkles);

