<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Glowing Sword in Meteor</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
    <!-- Import Three.js from a CDN -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
            }
        }
    </script>
</head>
<body>
    <script type="module">
        import * as THREE from 'three';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050510); // Dark space background
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 6);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // 2. The Meteor
        const meteorGeometry = new THREE.IcosahedronGeometry(2.5, 1);

        // Distort vertices to make it look rocky/irregular
        const positionAttribute = meteorGeometry.attributes.position;
        const vertex = new THREE.Vector3();
        for (let i = 0; i < positionAttribute.count; i++) {
            vertex.fromBufferAttribute(positionAttribute, i);
            const noise = 1 + (Math.random() - 0.5) * 0.4; // Random variation
            vertex.multiplyScalar(noise);
            positionAttribute.setXYZ(i, vertex.x, vertex.y, vertex.z);
        }
        meteorGeometry.computeVertexNormals();

        const meteorMaterial = new THREE.MeshStandardMaterial({
            color: 0x4a4a4a,
            roughness: 0.9,
            metalness: 0.2,
            flatShading: true
        });
        const meteor = new THREE.Mesh(meteorGeometry, meteorMaterial);
        meteor.position.y = -1.5;
        scene.add(meteor);

        // 3. The Sword
        const swordGroup = new THREE.Group();
        // Position sword so the handle is buried in the meteor
        swordGroup.position.y = 0.5; 

        // Blade
        const bladeGeometry = new THREE.CylinderGeometry(0.05, 0.15, 3, 8);
        const bladeMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ffff,
            emissive: 0x00ffff,
            emissiveIntensity: 3, // Make it glow
            roughness: 0.1,
            metalness: 0.8
        });
        const blade = new THREE.Mesh(bladeGeometry, bladeMaterial);
        blade.position.y = 1.5; // Center of blade
        swordGroup.add(blade);

        // Handle
        const handleGeometry = new THREE.CylinderGeometry(0.08, 0.08, 0.8, 8);
        const handleMaterial = new THREE.MeshStandardMaterial({ color: 0x222222 });
        const handle = new THREE.Mesh(handleGeometry, handleMaterial);
        handle.position.y = -0.4;
        swordGroup.add(handle);

        // Guard (Crossguard)
        const guardGeometry = new THREE.BoxGeometry(0.8, 0.1, 0.2);
        const guardMaterial = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.9 });
        const guard = new THREE.Mesh(guardGeometry, guardMaterial);
        guard.position.y = 0;
        swordGroup.add(guard);

        scene.add(swordGroup);

        // 4. Lighting
        // Ambient light for base visibility
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Point light attached to the sword to create the "glowing" effect on surroundings
        const swordLight = new THREE.PointLight(0x00ffff, 5, 15);
        swordLight.position.set(0, 1, 0);
        swordGroup.add(swordLight);

        // Directional light to simulate moonlight/sunlight on the meteor
        const dirLight = new THREE.DirectionalLight(0xffffff, 0.5);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        // 5. Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Slowly rotate the meteor and sword together
            meteor.rotation.y += 0.005;
            swordGroup.rotation.y += 0.005;

            // Subtle floating effect
            const time = Date.now() * 0.001;
            swordGroup.position.y = 0.5 + Math.sin(time) * 0.1;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
