<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Silver Beetle & Pearl</title>
<style>
* { margin: 0; padding: 0; overflow: hidden; }
body { background: #111; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.164.0/build/three.module.js" } }
</script>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x111111, 0.025);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3, 6);
camera.lookAt(0, 0.5, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// Lighting
const ambient = new THREE.AmbientLight(0x404050, 0.8);
scene.add(ambient);
const dir = new THREE.DirectionalLight(0xffeedd, 2);
dir.position.set(5, 8, 3);
scene.add(dir);
const rim = new THREE.PointLight(0x8888ff, 1.5, 20);
rim.position.set(-3, 4, -2);
scene.add(rim);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.9 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.5;
scene.add(ground);

// --- BEETLE ---
const beetle = new THREE.Group();
const silver = new THREE.MeshStandardMaterial({
  color: 0xcccccc, metalness: 0.95, roughness: 0.15
});
const darkSilver = new THREE.MeshStandardMaterial({
  color: 0x888888, metalness: 0.9, roughness: 0.3
});

// Thorax
const thorax = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), silver);
thorax.scale.set(0.8, 0.7, 1.2);
thorax.position.set(0, 0.25, 0.15);
beetle.add(thorax);

// Abdomen (elytra body)
const abdomen = new THREE.Mesh(new THREE.SphereGeometry(0.35, 16, 16), silver);
abdomen.scale.set(0.85, 0.7, 1.4);
abdomen.position.set(0, 0.22, -0.35);
beetle.add(abdomen);

// Elytra seam (dark line down the back)
const seam = new THREE.Mesh(
  new THREE.BoxGeometry(0.03, 0.02, 0.8),
  darkSilver
);
seam.position.set(0, 0.55, -0.35);
beetle.add(seam);

// Head
const head = new THREE.Mesh(new THREE.SphereGeometry(0.15, 12, 12), silver);
head.scale.set(0.9, 0.7, 1);
head.position.set(0, 0.2, 0.55);
beetle.add(head);

// Mandibles
for (let side of [-1, 1]) {
  const mand = new THREE.Mesh(
    new THREE.ConeGeometry(0.03, 0.15, 6),
    darkSilver
  );
  mand.position.set(side * 0.06, 0.15, 0.7);
  mand.rotation.x = Math.PI / 3;
  beetle.add(mand);
}

// Legs
const legPositions = [
  { z: 0.35, angle: -0.4 },
  { z: -0.1, angle: -0.6 },
  { z: -0.55, angle: -0.5 },
];
const legs = [];
for (let side of [-1, 1]) {
  for (let lp of legPositions) {
    const leg = new THREE.Mesh(
      new THREE.CylinderGeometry(0.02, 0.015, 0.5, 6),
      silver
    );
    leg.position.set(side * 0.28, 0.05, lp.z);
    leg.rotation.z = side * (Math.PI / 2 - 0.3);
    leg.rotation.x = -0.5;
    beetle.add(leg);
    legs.push({ mesh: leg, baseAngle: lp.angle, side });
  }
}

// Antennae
for (let side of [-1, 1]) {
  const antenna = new THREE.Mesh(
    new THREE.CylinderGeometry(0.01, 0.008, 0.35, 4),
    silver
  );
  antenna.position.set(side * 0.1, 0.32, 0.65);
  antenna.rotation.z = side * 0.5;
  antenna.rotation.x = -0.3;
  beetle.add(antenna);
}

beetle.position.set(0, 0, 0);
scene.add(beetle);

// --- PEARL ---
const pearlMat = new THREE.MeshPhysicalMaterial({
  color: 0xfff8f0,
  metalness: 0.0,
  roughness: 0.1,
  clearcoat: 1.0,
  clearcoatRoughness: 0.05,
  iridescence: 1.0,
  iridescenceIOR: 1.5,
  iridescenceThicknessRange: [100, 800],
  sheen: 1.0,
  sheenRoughness: 0.3,
  sheenColor: new THREE.Color(0xffeecc),
});

const pearl = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), pearlMat);
pearl.position.set(0, 0.35, 1.0);
scene.add(pearl);

// Pearl glow
const glow = new THREE.PointLight(0xffeedd, 0.5, 3);
glow.position.copy(pearl.position);
scene.add(glow);

// --- ANIMATION ---
let t = 0;
const speed = 0.6;

function animate() {
  requestAnimationFrame(animate);
  t += 0.016;

  // Move beetle and pearl forward
  const moveZ = Math.sin(t * 0.3) * 2;
  beetle.position.z = moveZ;
  pearl.position.z = moveZ + 1.0;
  glow.position.z = pearl.position.z;

  // Gentle bob
  beetle.position.y = Math.sin(t * 3) * 0.03;
  pearl.position.y = 0.35 + Math.sin(t * 2 + 1) * 0.02;

  // Leg animation
  legs.forEach((l, i) => {
    const phase = (i % 3) * Math.PI * 0.66 + (l.side > 0 ? 0 : Math.PI);
    l.mesh.rotation.x = -0.5 + Math.sin(t * 5 + phase) * 0.4;
  });

  // Antenna twitch
  beetle.children.forEach(c => {
    if (c.geometry && c.geometry.parameters && c.geometry.parameters.radiusTop === 0.01) {
      c.rotation.x = -0.3 + Math.sin(t * 4 + c.position.x * 10) * 0.15;
    }
  });

  // Camera follow
  camera.position.z = beetle.position.z + 6;
  camera.position.x = Math.sin(t * 0.15) * 2;
  camera.lookAt(beetle.position.x, 0.3, beetle.position.z + 0.5);

  renderer.render(scene, camera);
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

**What's in the scene:**

- **Silver beetle** built from primitives — metallic spheres for the thorax, abdomen, and head, with a dark seam line down the elytra, thin cylinder legs (animated with a walking phase), mandibles, and twitching antennae.
- **Pearl** using `MeshPhysicalMaterial` with full iridescence, clearcoat, and sheen for that soft lustrous glow, plus a point light for subtle halo.
- **Animation** — the beetle walks forward with bobbing motion and leg cycles while pushing the pearl ahead; the camera gently orbits and follows.
- **Lighting** — warm directional, blue rim light, and fog for atmosphere.

