    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cloudtop Observatory</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050510; }
        canvas { display: block; }
        #info {
            position: absolute;
            bottom: 20px;
            width: 100%;
            text-align: center;
            color: #aaccff;
            font-family: sans-serif;
            font-size: 14px;
            pointer-events: none;
            text-shadow: 0 0 5px rgba(0,0,0,0.5);
        }
    </style>
</head>
<body>
    <div id="info">✦ Cloudtop Observatory ✦</div>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <script>
        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050510, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404060, 1.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0x4455ff, 0.5);
        backLight.position.set(-5, 0, -5);
        scene.add(backLight);

        // Group for the floating island
        const floatingGroup = new THREE.Group();
        scene.add(floatingGroup);

        // --- Create Cloud ---
        const cloudGroup = new THREE.Group();
        const cloudMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            flatShading: true,
            roughness: 0.8,
            metalness: 0.1
        });

        // Create a cluster of spheres to form a cloud
        const sphereGeo = new THREE.IcosahedronGeometry(1, 1); // Low poly look

        const cloudPositions = [
            { x: 0, y: 0, z: 0, s: 2.5 },
            { x: 1.5, y: 0.5, z: 0.5, s: 1.8 },
            { x: -1.5, y: 0.2, z: -0.5, s: 1.9 },
            { x: 0.5, y: 1.2, z: 0, s: 1.5 },
            { x: -0.5, y: 1.0, z: 0.5, s: 1.4 },
            { x: 0, y: -0.5, z: 1.5, s: 1.6 },
            { x: 0, y: -0.5, z: -1.5, s: 1.6 },
            { x: 2.5, y: -0.5, z: 0, s: 1.2 },
            { x: -2.5, y: -0.5, z: 0, s: 1.2 },
        ];

        cloudPositions.forEach(pos => {
            const mesh = new THREE.Mesh(sphereGeo, cloudMaterial);
            mesh.position.set(pos.x, pos.y, pos.z);
            mesh.scale.setScalar(pos.s);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            cloudGroup.add(mesh);
        });

        floatingGroup.add(cloudGroup);

        // --- Create Observatory ---
        const obsGroup = new THREE.Group();
        obsGroup.position.y = 1.8; // Sit on top of the cloud

        // Base Cylinder
        const baseGeo = new THREE.CylinderGeometry(1.2, 1.4, 0.8, 8);
        const baseMat = new THREE.MeshStandardMaterial({ color: 0xeeeeee, flatShading: true });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.castShadow = true;
        base.receiveShadow = true;
        obsGroup.add(base);

        // Dome
        const domeGeo = new THREE.SphereGeometry(1.2, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        const domeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, flatShading: true });
        const dome = new THREE.Mesh(domeGeo, domeMat);
        dome.position.y = 0.4;
        dome.castShadow = true;
        obsGroup.add(dome);

        // Telescope (Cylinder sticking out)
        const telescopeGeo = new THREE.CylinderGeometry(0.15, 0.15, 1.5, 8);
        const telescopeMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.5, roughness: 0.2 });
        const telescope = new THREE.Mesh(telescopeGeo, telescopeMat);
        telescope.position.set(0, 1.2, 0);
        telescope.rotation.x = Math.PI / 4; // Pointing up and forward
        telescope.castShadow = true;
        obsGroup.add(telescope);

        // Telescope Lens (Glowing)
        const lensGeo = new THREE.CircleGeometry(0.16, 16);
        const lensMat = new THREE.MeshBasicMaterial({ color: 0x00ffff, side: THREE.DoubleSide });
        const lens = new THREE.Mesh(lensGeo, lensMat);
        lens.position.set(0, 1.2, 0);
        lens.rotation.x = Math.PI / 4;
        // Offset lens to the end of the telescope
        const offset = 0.75;
        lens.position.x += Math.sin(Math.PI/4) * offset;
        lens.position.y += Math.cos(Math.PI/4) * offset;
        obsGroup.add(lens);

        // Slit in the dome (visual trick: just a dark box)
        const slitGeo = new THREE.BoxGeometry(0.4, 1.5, 0.1);
        const slitMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const slit = new THREE.Mesh(slitGeo, slitMat);
        slit.position.set(0, 0.8, 1.19); // Just inside the dome surface
        obsGroup.add(slit);

        floatingGroup.add(obsGroup);

        // --- Stars ---
        const starsGeo = new THREE.BufferGeometry();
        const starsCount = 1000;
        const posArray = new Float32Array(starsCount * 3);

        for(let i = 0; i < starsCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 100;
        }

        starsGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const starsMat = new THREE.PointsMaterial({
            size: 0.15,
            color: 0xffffff,
            transparent: true,
            opacity: 0.8
        });
        const stars = new THREE.Points(starsGeo, starsMat);
        scene.add(stars);

        // --- Animation ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Bobbing motion
            floatingGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Gentle rotation
            floatingGroup.rotation.y = Math.sin(time * 0.1) * 0.1;

            // Telescope tracking (slow rotation)
            telescope.rotation.z = Math.sin(time * 0.3) * 0.2;
            lens.rotation.z = Math.sin(time * 0.3) * 0.2;

            // Update lens position based on rotation
            const angle = Math.PI / 4 + telescope.rotation.z;
            const offset = 0.75;
            lens.position.x = Math.sin(angle) * offset;
            lens.position.y = 1.2 + Math.cos(angle) * offset;
            lens.rotation.x = angle;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
