        });

        // --- The Flower of Light ---
        const flowerGroup = new THREE.Group();
        scene.add(flowerGroup);

        // Stem
        const stemGeo = new THREE.CylinderGeometry(0.1, 0.1, 4, 8);
        const stem = new THREE.Mesh(stemGeo, stemMaterial);
        stem.position.y = -2;
        flowerGroup.add(stem);

        // Glowing Center
        const centerGeo = new THREE.SphereGeometry(0.4, 16, 16);
        const center = new THREE.Mesh(centerGeo, glowMaterial);
        flowerGroup.add(center);

        // Point light inside the flower
        const flowerLight = new THREE.PointLight(0xff00ff, 5, 10);
        flowerGroup.add(flowerLight);

        // Petals
        const petalGeo = new THREE.ConeGeometry(0.3, 1.5, 4);
        const petalMat = new THREE.MeshStandardMaterial({
            color: 0xffaa00,
            emissive: 0xff4400,
            emissiveIntensity: 0.5,
            side: THREE.DoubleSide
        });

        for (let i = 0; i < 8; i++) {
            const petal = new THREE.Mesh(petalGeo, petalMat);
            const angle = (i / 8) * Math.PI * 2;
            petal.position.set(Math.cos(angle) * 0.6, 0, Math.sin(angle) * 0.6);
            petal.rotation.x = Math.PI / 4;
            petal.rotation.z = angle;
            petal.lookAt(0, 0, 0); // Face center roughly
            petal.rotateX(Math.PI / 2); // Lay flat-ish
            flowerGroup.add(petal);
        }

        // --- The Mechanical Hummingbird ---
        const birdGroup = new THREE.Group();
        scene.add(birdGroup);

