        const bodyGeo = new THREE.CapsuleGeometry(0.3, 1.2, 4, 8);
        const body = new THREE.Mesh(bodyGeo, metalMaterial);
        body.rotation.z = Math.PI / 2; // Horizontal
        birdGroup.add(body);

