        const eyeGeo = new THREE.SphereGeometry(0.05, 8, 8);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const eye = new THREE.Mesh(eyeGeo, eyeMat);
        eye.position.set(0.9, 0.2, 0.2);
        birdGroup.add(eye);

        // Beak
        const beakGeo = new THREE.CylinderGeometry(0.02, 0.05, 1.5, 8);
        const beak = new THREE.Mesh(beakGeo, darkMetalMaterial);
        beak.rotation.z = -Math.PI / 2;
        beak.position.set(1.6, 0, 0);
        birdGroup.add(beak);

        // Tail
        const tailGroup = new THREE.Group();
        tailGroup.position.set(-0.8, 0, 0);
        birdGroup.add(tailGroup);

        for(let i=0; i<3; i++) {
            const tailFeatherGeo = new THREE.BoxGeometry(0.8, 0.05, 0.1);
            const feather = new THREE.Mesh(tailFeatherGeo, darkMetalMaterial);
            feather.position.set(-0.4, (i-1)*0.1, 0);
            feather.rotation.y = (i-1) * 0.2;
            tailGroup.add(feather);
        }

        // Wings (Pivot points)
        const wingPivotLeft = new THREE.Group();
        wingPivotLeft.position.set(0, 0.2, 0.3);
        birdGroup.add(wingPivotLeft);

        const wingPivotRight = new THREE.Group();
        wingPivotRight.position.set(0, 0.2, -0.3);
        birdGroup.add(wingPivotRight);

        const wingGeo = new THREE.BoxGeometry(0.8, 0.05, 0.6);
        const wingMat = new THREE.MeshStandardMaterial({ 
            color: 0xaaaaaa, 
            metalness: 0.5, 
            roughness: 0.5,
            transparent: true,
            opacity: 0.8
        });

        const leftWing = new THREE.Mesh(wingGeo, wingMat);
        leftWing.position.set(0.2, 0.4, 0); // Offset from pivot
        wingPivotLeft.add(leftWing);

        const rightWing = new THREE.Mesh(wingGeo, wingMat);
        rightWing.position.set(0.2, 0.4, 0);
        wingPivotRight.add(rightWing);

        // --- Animation Variables ---
        const clock = new THREE.Clock();
        let time = 0;

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // 1. Flower Animation (Pulsing)
            const pulse = 1 + Math.sin(time * 3) * 0.1;
            flowerGroup.scale.set(pulse, pulse, pulse);
            flowerLight.intensity = 5 + Math.sin(time * 5) * 2;

            // 2. Bird Hovering
            // Bobbing up and down
            birdGroup.position.y = 1.5 + Math.sin(time * 4) * 0.2;
            // Slight rotation to look at flower
            birdGroup.rotation.y = Math.sin(time * 2) * 0.1;
            birdGroup.rotation.z = Math.sin(time * 3) * 0.05;

            // 3. Wing Flapping (Fast)
            const flapSpeed = 40;
            const flapAngle = Math.sin(time * flapSpeed) * 0.5;

            wingPivotLeft.rotation.z = flapAngle;
            wingPivotRight.rotation.z = -flapAngle;

            // 4. Beak dipping into flower
            // Move bird closer/further slightly
            birdGroup.position.z = Math.sin(time * 1.5) * 0.5;

            // Rotate beak down when close
            if (birdGroup.position.z < 0) {
                beak.rotation.z = -Math.PI / 2 + 0.2;
            } else {
                beak.rotation.z = -Math.PI / 2;
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
