    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ReinhardToneMapping;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const pointLight = new THREE.PointLight(0x00ffff, 2, 20);
        pointLight.position.set(0, 3, 0);
        scene.add(pointLight);

        const spotLight = new THREE.SpotLight(0xffaa00, 5, 20, Math.PI / 6, 0.5, 1);
        spotLight.position.set(5, 10, 5);
        spotLight.target.position.set(0, 0, 0);
        scene.add(spotLight);
        scene.add(spotLight.target);

        // Materials
        const keyMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x8c7853, 
            roughness: 0.4, 
            metalness: 0.8 
        });

        const mushroomStemMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xeeeeee, 
            roughness: 0.2,
            emissive: 0x004444,
            emissiveIntensity: 0.2
        });

        const mushroomCapMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x00ffcc, 
            roughness: 0.1, 
            metalness: 0.1,
            emissive: 0x00ffaa,
            emissiveIntensity: 1.5,
            transparent: true,
            opacity: 0.9
        });

        // Group to hold everything
        const mainGroup = new THREE.Group();
        scene.add(mainGroup);

        // --- Build the Key ---
        const keyGroup = new THREE.Group();

        // Key Handle (Head)
        const handleGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.2, 16);
        const handle = new THREE.Mesh(handleGeo, keyMaterial);
        handle.rotation.x = Math.PI / 2;
        handle.position.z = -1.5;
        keyGroup.add(handle);

        // Key Ring
        const ringGeo = new THREE.TorusGeometry(0.8, 0.1, 8, 24);
        const ring = new THREE.Mesh(ringGeo, keyMaterial);
        ring.position.z = -1.5;
        keyGroup.add(ring);

        // Key Shaft
        const shaftGeo = new THREE.CylinderGeometry(0.1, 0.1, 3, 8);
        const shaft = new THREE.Mesh(shaftGeo, keyMaterial);
        shaft.rotation.x = Math.PI / 2;
        shaft.position.z = 0;
        keyGroup.add(shaft);

        // Key Teeth
        const toothGeo = new THREE.BoxGeometry(0.15, 0.4, 0.1);
        const tooth1 = new THREE.Mesh(toothGeo, keyMaterial);
        tooth1.position.set(0, -0.3, 1.2);
        keyGroup.add(tooth1);

        const tooth2 = new THREE.Mesh(toothGeo, keyMaterial);
        tooth2.position.set(0, -0.3, 0.8);
        keyGroup.add(tooth2);

        // Rotate key to lie flat-ish
        keyGroup.rotation.x = Math.PI / 2;
        keyGroup.rotation.z = Math.PI / 4;
        keyGroup.position.y = -1;
        mainGroup.add(keyGroup);

        // --- Build the Mushroom ---
        const mushroomGroup = new THREE.Group();

        // Stem
        const stemGeo = new THREE.CylinderGeometry(0.15, 0.25, 1.5, 8);
        const stem = new THREE.Mesh(stemGeo, mushroomStemMaterial);
        stem.position.y = 0.75;
        mushroomGroup.add(stem);

        // Cap
        const capGeo = new THREE.SphereGeometry(0.8, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        const cap = new THREE.Mesh(capGeo, mushroomCapMaterial);
        cap.position.y = 1.5;
