        // Spots on cap
        const spotGeo = new THREE.SphereGeometry(0.1, 8, 8);
        const spotMat = new THREE.MeshBasicMaterial({ color: 0xffffff });

        for(let i=0; i<5; i++) {
            const spot = new THREE.Mesh(spotGeo, spotMat);
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.random() * Math.PI / 3;
            const r = 0.75;
            spot.position.x = r * Math.sin(phi) * Math.cos(theta);
            spot.position.y = 1.5 + r * Math.cos(phi);
            spot.position.z = r * Math.sin(phi) * Math.sin(theta);
            mushroomGroup.add(spot);
        }

        // Position mushroom growing out of the key handle
        mushroomGroup.position.set(0, -0.5, -1.5);
        // Tilt it slightly to match key angle
        mushroomGroup.rotation.z = -Math.PI / 4; 
        mainGroup.add(mushroomGroup);

        // Particles
        const particlesGeo = new THREE.BufferGeometry();
        const particleCount = 100;
        const posArray = new Float32Array(particleCount * 3);

        for(let i=0; i<particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 10;
        }

        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.05,
            color: 0x00ffcc,
            transparent: true,
            opacity: 0.8
        });
        const particlesMesh = new THREE.Points(particlesGeo, particlesMat);
        scene.add(particlesMesh);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate the whole assembly slowly
            mainGroup.rotation.y = time * 0.2;

            // Pulse the mushroom glow
            mushroomCapMaterial.emissiveIntensity = 1.0 + Math.sin(time * 2) * 0.5;
            pointLight.intensity = 2 + Math.sin(time * 2) * 1;

            // Float particles
            particlesMesh.rotation.y = -time * 0.1;
            particlesMesh.position.y = Math.sin(time * 0.5) * 0.5;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
