            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9,
            side: THREE.DoubleSide
        });

        // Dolphin Construction
        const dolphinGroup = new THREE.Group();

        // Body (Tube along a curve)
        const bodyCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(-1.5, 0, 0),
            new THREE.Vector3(-0.5, 0.2, 0),
            new THREE.Vector3(0.5, 0.1, 0),
            new THREE.Vector3(1.2, -0.2, 0)
        ]);
        const bodyGeo = new THREE.TubeGeometry(bodyCurve, 20, 0.35, 12, false);
        const body = new THREE.Mesh(bodyGeo, crystalMaterial);
        dolphinGroup.add(body);

        // Head (Cone/Sphere blend)
        const headGeo = new THREE.SphereGeometry(0.35, 16, 16);
        headGeo.scale(1.5, 0.8, 0.8);
        const head = new THREE.Mesh(headGeo, crystalMaterial);
        head.position.set(-1.6, 0, 0);
        head.rotation.z = Math.PI / 2;
        dolphinGroup.add(head);

        // Snout
        const snoutGeo = new THREE.ConeGeometry(0.15, 0.6, 8);
        const snout = new THREE.Mesh(snoutGeo, crystalMaterial);
        snout.rotation.z = -Math.PI / 2;
        snout.position.set(-2.1, 0, 0);
        dolphinGroup.add(snout);

        // Tail (Plane)
        const tailGeo = new THREE.PlaneGeometry(0.8, 0.6);
        const tail = new THREE.Mesh(tailGeo, crystalMaterial);
        tail.position.set(1.4, 0, 0);
        dolphinGroup.add(tail);

        // Dorsal Fin
        const finGeo = new THREE.PlaneGeometry(0.5, 0.7);
        const fin = new THREE.Mesh(finGeo, crystalMaterial);
        fin.position.set(0, 0.4, 0);
        fin.rotation.x = Math.PI / 6;
        dolphinGroup.add(fin);

        // Side Fins
        const sideFinGeo = new THREE.PlaneGeometry(0.4, 0.3);
        const leftFin = new THREE.Mesh(sideFinGeo, crystalMaterial);
        leftFin.position.set(-0.5, -0.2, 0.3);
        leftFin.rotation.x = Math.PI / 4;
        leftFin.rotation.y = -Math.PI / 4;
        dolphinGroup.add(leftFin);

        const rightFin = new THREE.Mesh(sideFinGeo, crystalMaterial);
        rightFin.position.set(-0.5, -0.2, -0.3);
        rightFin.rotation.x = Math.PI / 4;
        rightFin.rotation.y = Math.PI / 4;
        dolphinGroup.add(rightFin);

        scene.add(dolphinGroup);

