        const rings = [];
        const ringGeo = new THREE.TorusGeometry(2.5, 0.05, 16, 100);
        const ringMat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const ringGlowMat = new THREE.MeshBasicMaterial({ color: 0x0088ff, transparent: true, opacity: 0.3 });

        for (let i = 0; i < 6; i++) {
            const ringGroup = new THREE.Group();

            const core = new THREE.Mesh(ringGeo, ringMat);
            ringGroup.add(core);

            const glow = new THREE.Mesh(new THREE.TorusGeometry(2.5, 0.2, 8, 50), ringGlowMat);
            ringGroup.add(glow);

            ringGroup.position.z = -i * 6;
            ringGroup.rotation.x = Math.PI / 2;
            scene.add(ringGroup);
            rings.push(ringGroup);
        }

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const time = clock.getElapsedTime();

            // Dolphin Leap Animation
            dolphinGroup.position.y = Math.sin(time * 2) * 1.5;
            dolphinGroup.rotation.z = Math.sin(time * 2) * 0.2;
            dolphinGroup.rotation.y = Math.sin(time * 0.5) * 0.3;

            // Move forward through rings
            dolphinGroup.position.z = (time * 3) % 30 - 15;

            // Animate Rings
            rings.forEach((ring, i) => {
                ring.rotation.z = time * 0.5 + i;
                ring.rotation.x = Math.PI / 2 + Math.sin(time + i) * 0.2;
            });

            renderer.render(scene, camera);
        }

        animate();

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
