<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// ── Scene ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000011, 0.04);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(4, 3, 6);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.2, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.06;

// ── Lights ──
scene.add(new THREE.AmbientLight(0x111122, 0.5));
const keyLight = new THREE.PointLight(0xffeedd, 2, 20);
keyLight.position.set(4, 5, 4);
scene.add(keyLight);
const rimLight = new THREE.PointLight(0x4488ff, 3, 15);
rimLight.position.set(-3, 3, -3);
scene.add(rimLight);

// ── Ground grid ──
const grid = new THREE.GridHelper(30, 60, 0x111133, 0x0a0a1a);
grid.position.y = 0.01;
scene.add(grid);

// ── Materials ──
const metalMat = new THREE.MeshStandardMaterial({
  color: 0x222233, metalness: 0.95, roughness: 0.15
});
const darkMat = new THREE.MeshStandardMaterial({
  color: 0x111118, metalness: 0.9, roughness: 0.3
});
const jointMat = new THREE.MeshStandardMaterial({
  color: 0x333344, metalness: 0.8, roughness: 0.4
});
const eyeMat = new THREE.MeshStandardMaterial({
  color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2
});
const noseMat = new THREE.MeshStandardMaterial({
  color: 0xff3366, emissive: 0xff2255, emissiveIntensity: 1.5
});

// ── Fox group ──
const fox = new THREE.Group();
scene.add(fox);

function box(w, h, d, mat, px, py, pz) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(px, py, pz);
  return m;
}

function cyl(rT, rB, h, seg, mat, px, py, pz) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rT, rB, h, seg), mat);
  m.position.set(px, py, pz);
  return m;
}

// Torso
const torso = box(0.8, 0.55, 1.4, metalMat, 0, 1.55, 0);
torso.rotation.x = 0.05;
fox.add(torso);

// Chest plate
fox.add(box(0.65, 0.45, 0.3, darkMat, 0, 1.55, 0.75));

// Belly
fox.add(box(0.5, 0.3, 1.0, darkMat, 0, 1.3, -0.1));

// Head
const head = box(0.55, 0.45, 0.65, metalMat, 0, 2.05, 0.95);
fox.add(head);

// Snout
const snout = box(0.3, 0.22, 0.45, darkMat, 0, 1.92, 1.4);
fox.add(snout);

// Lower jaw
fox.add(box(0.28, 0.1, 0.35, jointMat, 0, 1.78, 1.35));

// Nose tip
fox.add(box(0.12, 0.08, 0.08, noseMat, 0, 1.93, 1.63));

// Cheek plates
fox.add(box(0.12, 0.25, 0.3, darkMat, -0.33, 1.98, 1.05));
fox.add(box(0.12, 0.25, 0.3, darkMat, 0.33, 1.98, 1.05));

// Forehead ridge
fox.add(box(0.2, 0.08, 0.4, jointMat, 0, 2.3, 0.9));

// ── Ears ──
function makeEar(side) {
  const g = new THREE.Group();
  // Outer ear
  const earGeo = new THREE.ConeGeometry(0.12, 0.45, 4);
  const ear = new THREE.Mesh(earGeo, metalMat);
  ear.rotation.z = side * 0.15;
  ear.rotation.x = -0.1;
  ear.position.set(side * 0.2, 0.22, 0);
  g.add(ear);
  // Inner ear
  const inner = new THREE.Mesh(
    new THREE.ConeGeometry(0.07, 0.3, 4),
    new THREE.MeshStandardMaterial({ color: 0x220033, emissive: 0x440066, emissiveIntensity: 0.5 })
  );
  inner.rotation.z = side * 0.15;
  inner.rotation.x = -0.1;
  inner.position.set(side * 0.2, 0.2, 0.02);
  g.add(inner);
  g.position.set(side * 0.22, 2.28, 0.85);
  return g;
}
fox.add(makeEar(-1));
fox.add(makeEar(1));

// ── Eyes ──
function makeEye(side) {
  const g = new THREE.Group();
  const socket = box(0.18, 0.12, 0.08, darkMat, 0, 0, 0);
  g.add(socket);
  const lens = new THREE.Mesh(
    new THREE.SphereGeometry(0.055, 16, 16),
    eyeMat
  );
  lens.position.set(0, 0, 0.04);
  g.add(lens);
  // Pupil slit
