    new THREE.PlaneGeometry(0.012, 0.06),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  pupil.position.set(0, 0, 0.1);
  g.add(pupil);
  g.position.set(side * 0.16, 2.1, 1.28);
  return g;
}
fox.add(makeEye(-1));
fox.add(makeEye(1));

// ── Legs ──
function makeLeg(side, front) {
  const g = new THREE.Group();
  const x = side * 0.28;
  const z = front ? 0.5 : -0.5;
  // Upper leg
  g.add(cyl(0.06, 0.055, 0.45, 8, metalMat, x, 1.1, z));
  // Joint
  g.add(new THREE.Mesh(new THREE.SphereGeometry(0.065, 8, 8), jointMat).translateX(x).translateY(0.87).translateZ(z));
  // Lower leg
  g.add(cyl(0.05, 0.045, 0.4, 8, darkMat, x, 0.65, z));
  // Ankle joint
  g.add(new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 8), jointMat).translateX(x).translateY(0.44).translateZ(z));
  // Foot
  g.add(box(0.1, 0.06, 0.16, jointMat, x, 0.2, z));
  return g;
}
fox.add(makeLeg(-1, true));
fox.add(makeLeg(1, true));
fox.add(makeLeg(-1, false));
fox.add(makeLeg(1, false));

// ── Tail ──
const tailGroup = new THREE.Group();
fox.add(tailGroup);
const tailSegments = [];
const tailSegCount = 12;
for (let i = 0; i < tailSegCount; i++) {
  const t = i / tailSegCount;
  const r = 0.08 * (1 - t * 0.6);
  const seg = new THREE.Mesh(new THREE.SphereGeometry(r, 8, 8), i % 2 === 0 ? metalMat : darkMat);
  seg.position.set(
    Math.sin(t * Math.PI * 0.6) * 0.6,
    1.5 + t * 0.5,
    -0.7 - t * 1.2
  );
  tailGroup.add(seg);
  tailSegments.push(seg);
}
// Tail tip (bright)
const tailTip = new THREE.Mesh(
  new THREE.SphereGeometry(0.06, 8, 8),
  new THREE.MeshStandardMaterial({ color: 0xff4488, emissive: 0xff2266, emissiveIntensity: 1.5 })
);
tailTip.position.set(
  Math.sin(Math.PI * 0.6) * 0.6,
  1.5 + 0.5,
  -0.7 - 1.2
);
tailGroup.add(tailTip);

// ── Spine details ──
for (let i = 0; i < 6; i++) {
  fox.add(box(0.06, 0.06, 0.06, jointMat, 0, 1.85, -0.4 + i * 0.18));
}

// ── Fiber-Optic Fur ──
const furGroup = new THREE.Group();
fox.add(furGroup);

const fiberColors = [
  new THREE.Color(0x00ffff),
  new THREE.Color(0xff00ff),
  new THREE.Color(0x00ff88),
  new THREE.Color(0xff4400),
  new THREE.Color(0x4488ff),
  new THREE.Color(0xff0088),
  new THREE.Color(0x88ff00),
  new THREE.Color(0xffaa00),
];

const fibers = [];

function createFiber(point, normal, length) {
  const colorIdx = Math.floor(Math.random() * fiberColors.length);
  const baseColor = fiberColors[colorIdx].clone();

  const points = [];
  const segments = 6 + Math.floor(Math.random() * 4);
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const p = point.clone().add(normal.clone().multiplyScalar(t * length));
    // Add slight curve
    p.x += (Math.random() - 0.5) * 0.03 * t;
    p.y += (Math.random() - 0.5) * 0.02 * t;
    p.z += (Math.random() - 0.5) * 0.03 * t;
    points.push(p);
  }

  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = new THREE.LineBasicMaterial({
    color: baseColor,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });

  const line = new THREE.Line(geometry, material);
  furGroup.add(line);

  // Glow tip
  const tipGeo = new THREE.SphereGeometry(0.015, 6, 6);
  const tipMat = new THREE.MeshBasicMaterial({
    color: baseColor,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const tip = new THREE.Mesh(tipGeo, tipMat);
  tip.position.copy(points[points.length - 1]);
  furGroup.add(tip);

  fibers.push({
    line, material, tip, tipMat,
    baseColor: baseColor.clone(),
    phase: Math.random() * Math.PI * 2,
    speed: 0.5 + Math.random() * 2,
    pulseSpeed: 1 + Math.random() * 3,
    pulsePhase: Math.random() * Math.PI * 2,
  });
}

// Generate fur on body surfaces
function addFurPatch(center, size, count, normal) {
  for (let i = 0; i < count; i++) {
    const p = new THREE.Vector3(
      center.x + (Math.random() - 0.5) * size.x,
      center.y + (Math.random() - 0.5) * size.y,
      center.z + (Math.random() - 0.5) * size.z,
    );
    const n = normal.clone();
    n.x += (Math.random() - 0.5) * 0.3;
    n.y += (Math.random() - 0.5) * 0.3;
    n.z += (Math.random() - 0.5) * 0.3;
    n.normalize();
    createFiber(p, n, 0.15 + Math.random() * 0.25);
  }
}

