            hourglass.rotation.z = Math.cos(time * 0.3) * 0.05;

            // Rotate background stars slowly
            stars.rotation.y = time * 0.02;

            // Update particles
            const posAttr = particlesGeo.getAttribute('position');
            const colAttr = particlesGeo.getAttribute('color');

            for (let i = 0; i < particleCount; i++) {
                let y = posAttr.getY(i);
                let x = posAttr.getX(i);
                let z = posAttr.getZ(i);
                const vel = velocities[i];

                // Move
                y += vel.y;
                x += vel.x;
                z += vel.z;

                // Gravity acceleration effect near neck
                if (y < 0.5 && y > -0.5) {
                    vel.y -= 0.001; 
                }

                // Reset if below bottom
                if (y < -2.2) {
                    resetParticle(i);
                    y = posAttr.getY(i); // Get new y
                    x = posAttr.getX(i);
                    z = posAttr.getZ(i);
                }

                // Constrain to hourglass shape (simple approximation)
                // Top bulb radius ~1.5, Neck ~0.1, Bottom ~1.5
                let maxR = 0;
                if (y > 0) {
                    // Top bulb: y goes 2.5 -> 0
                    // Map y to 0..1
                    const t = (2.5 - y) / 2.5; 
                    // Radius function: wide at top, narrow at neck
                    maxR = 1.5 * Math.sin(t * Math.PI * 0.8); 
                    if (maxR < 0.1) maxR = 0.1;
                } else {
                    // Bottom bulb: y goes 0 -> -2.5
                    const t = (-y) / 2.5;
                    maxR = 1.5 * Math.sin(t * Math.PI * 0.8);
                    if (maxR < 0.1) maxR = 0.1;
                }

                const dist = Math.sqrt(x*x + z*z);
                if (dist > maxR) {
                    const angle = Math.atan2(z, x);
                    x = Math.cos(angle) * maxR * 0.9;
                    z = Math.sin(angle) * maxR * 0.9;
                }

                posAttr.setXYZ(i, x, y, z);

                // Color Transition: Sand (Orange) -> Stars (Blue/White)
                // y goes from ~2.0 (top) to ~-2.0 (bottom)
                // Let's say transition happens as they fall.
                const t = (y + 2.5) / 5.0; // 0 at bottom, 1 at top
                // We want top to be sand, bottom to be stars.
                // So mix factor should be 0 at top (sand), 1 at bottom (stars)?
                // Or maybe they turn into stars as they fall.
                const mix = 1 - t; // 0 at top, 1 at bottom

                // Add some twinkling
                const twinkle = Math.sin(time * 5 + vel.phase) * 0.2 + 0.8;

                const c = sandColor.clone().lerp(starColor, mix);
                c.multiplyScalar(twinkle); // Brightness variation

                colAttr.setXYZ(i, c.r, c.g, c.b);
            }

            posAttr.needsUpdate = true;
            colAttr.needsUpdate = true;

            renderer.render(scene, camera);
        }

