function createGalaxy(colors, arms, count, radius, spread) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const galaxyColors = new Float32Array(count * 3);
  const galaxySizes = new Float32Array(count);

  for (let i = 0; i < count; i++) {
    const armIndex = i % arms;
    const armAngle = (armIndex / arms) * Math.PI * 2;
    const dist = Math.pow(Math.random(), 0.5) * radius;
    const spinAngle = dist * 1.5 + armAngle;
    const randomOffset = (Math.random() - 0.5) * spread * (1.0 - dist / radius * 0.5);
    const randomOffsetZ = (Math.random() - 0.5) * spread * 0.3 * (1.0 - dist / radius * 0.3);

    positions[i * 3] = Math.cos(spinAngle) * dist + Math.cos(spinAngle + Math.PI/2) * randomOffset;
    positions[i * 3 + 1] = randomOffsetZ;
    positions[i * 3 + 2] = Math.sin(spinAngle) * dist + Math.sin(spinAngle + Math.PI/2) * randomOffset;

    const colorChoice = colors[Math.floor(Math.random() * colors.length)];
    galaxyColors[i * 3] = colorChoice.r;
    galaxyColors[i * 3 + 1] = colorChoice.g;
    galaxyColors[i * 3 + 2] = colorChoice.b;

    galaxySizes[i] = 0.5 + Math.random() * 2.0 * (1.0 - dist / radius);
  }

  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(galaxyColors, 3));
  geo.setAttribute('size', new THREE.BufferAttribute(galaxySizes, 1));

