            metalness: 0.1,
            side: THREE.DoubleSide,
            transmission: 0.95,
            thickness: 0.1
        });
        const glass = new THREE.Mesh(glassGeo, glassMat);
        lantern.add(glass);

        // 2. Lantern Metal Parts (Top and Bottom)
        const metalMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.3, metalness: 0.8 });

        const topGeo = new THREE.CylinderGeometry(1.1, 1, 0.2, 32);
        const topCap = new THREE.Mesh(topGeo, metalMat);
        topCap.position.y = 1.25;
        lantern.add(topCap);

        const bottomGeo = new THREE.CylinderGeometry(1, 1.1, 0.2, 32);
        const bottomCap = new THREE.Mesh(bottomGeo, metalMat);
        bottomCap.position.y = -1.25;
        lantern.add(bottomCap);

        // 3. Stormy Sea (Inside the lantern)
        const seaGeo = new THREE.PlaneGeometry(1.8, 1.8, 64, 64);

        // Shader for stormy waves
        const seaMat = new THREE.ShaderMaterial({
            uniforms: {
                uTime: { value: 0 },
                uColor: { value: new THREE.Color(0x001a33) },
                uFlash: { value: 0 }
            },
            vertexShader: `
                uniform float uTime;
                varying vec2 vUv;
                varying float vElevation;

                void main() {
                    vUv = uv;
                    vec3 pos = position;

                    // Chaotic waves
                    float wave1 = sin(pos.x * 5.0 + uTime * 3.0) * 0.05;
                    float wave2 = sin(pos.y * 4.0 + uTime * 2.5) * 0.05;
                    float wave3 = sin((pos.x + pos.y) * 8.0 + uTime * 4.0) * 0.02;

                    pos.z += wave1 + wave2 + wave3;
                    vElevation = pos.z;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 uColor;
                uniform float uFlash;
                varying vec2 vUv;
                varying float vElevation;

                void main() {
                    vec3 color = uColor;

                    // Foam on peaks
                    float foam = smoothstep(0.05, 0.1, vElevation);
                    color += vec3(0.1, 0.2, 0.3) * foam;

                    // Lightning flash overlay
                    color += vec3(0.8, 0.8, 1.0) * uFlash;

                    gl_FragColor = vec4(color, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

