        stormLight.position.set(0, 1, 0);
        lantern.add(stormLight);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const t = clock.getElapsedTime();
            seaMat.uniforms.uTime.value = t;

            // Random lightning flashes
            if (Math.random() > 0.98) {
                seaMat.uniforms.uFlash.value = 1.0;
                stormLight.intensity = 10;
            } else {
                seaMat.uniforms.uFlash.value *= 0.9;
                stormLight.intensity *= 0.9;
            }

            // Subtle lantern flicker
            lanternLight.intensity = 3 + Math.sin(t * 10) * 0.2;

            renderer.render(scene, camera);
        }

        animate();

        // Resize handler
