    <script>
        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 3, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Materials
        const woodMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3d2817, 
            roughness: 0.9 
        });

        const potMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x2a1a1a, 
            roughness: 0.8 
        });

        const lanternMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffaa00, 
            emissive: 0xffaa00, 
            emissiveIntensity: 2,
            roughness: 0.2
        });

        // Helper to create a branch
        function createBranch(length, radius, depth) {
            const geometry = new THREE.CylinderGeometry(radius * 0.7, radius, length, 8);
            const branch = new THREE.Mesh(geometry, woodMaterial);
            branch.position.y = length / 2;

            // Pivot point at the bottom
            const pivot = new THREE.Object3D();
            pivot.add(branch);

            if (depth > 0) {
                // Create sub-branches
                const numBranches = 2;
                for (let i = 0; i < numBranches; i++) {
                    const subBranch = createBranch(length * 0.7, radius * 0.7, depth - 1);
                    subBranch.position.y = length;

                    // Randomize angles slightly for organic look
                    const angle = (i === 0 ? -1 : 1) * (Math.PI / 4 + Math.random() * 0.2);
                    const twist = Math.random() * Math.PI * 2;

                    subBranch.rotation.z = angle;
                    subBranch.rotation.y = twist;

                    pivot.add(subBranch);
                }
            } else {
                // Create Lantern at the tip
                const lanternGeo = new THREE.SphereGeometry(0.3, 16, 16);
                const lantern = new THREE.Mesh(lanternGeo, lanternMaterial);
                lantern.position.y = length;

                // Add a point light to each lantern
                const light = new THREE.PointLight(0xffaa00, 1, 6);
                light.position.y = 0;
                lantern.add(light);

                pivot.add(lantern);
            }

            return pivot;
        }

        // Build the Bonsai
        const bonsaiGroup = new THREE.Group();

        // Pot
        const potGeo = new THREE.CylinderGeometry(1.5, 1, 1.5, 16);
        const pot = new THREE.Mesh(potGeo, potMaterial);
        pot.position.y = -0.75;
        bonsaiGroup.add(pot);

        // Main Trunk
        const trunk = createBranch(3, 0.4, 4); // Length 3, Radius 0.4, Depth 4
        trunk.position.y = 0;
        bonsaiGroup.add(trunk);

        scene.add(bonsaiGroup);

        // Ambient Light (very dim)
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation
            bonsaiGroup.rotation.y += 0.005;

            // Gentle floating/pulsing of lanterns (optional visual flair)
            const time = Date.now() * 0.001;
            bonsaiGroup.children.forEach(child => {
                if(child.children) {
                    child.children.forEach(sub => {
                        if(sub.children) {
                            sub.children.forEach(lantern => {
                                if(lantern.isMesh && lantern.material.emissive) {
                                    lantern.material.emissiveIntensity = 1.5 + Math.sin(time * 2 + Math.random()) * 0.5;
                                }
                            });
                        }
                    });
                }
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
