        const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // Cloud Construction
        const cloudGroup = new THREE.Group();
        const cloudMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xffffff, 
            roughness: 1, 
            flatShading: true 
        });

        const cloudGeometries = [
            new THREE.SphereGeometry(1, 16, 16),
            new THREE.SphereGeometry(1.3, 16, 16),
            new THREE.SphereGeometry(0.9, 16, 16)
        ];

        const cloudPositions = [
            [0, 0, 0], 
            [-1, 0.2, 0.5], 
            [1, 0.1, -0.5], 
            [0, 0.6, 0], 
            [-0.5, 0.5, 0.8],
            [0.5, 0.4, -0.8]
        ];

        cloudPositions.forEach(pos => {
            const geo = cloudGeometries[Math.floor(Math.random() * cloudGeometries.length)];
            const mesh = new THREE.Mesh(geo, cloudMaterial);
            mesh.position.set(...pos);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            cloudGroup.add(mesh);
        });

        // Flatten the bottom of the cloud slightly to look like a platform
        cloudGroup.scale.set(1.5, 0.8, 1.5);
        scene.add(cloudGroup);

        // Airship Construction
        const airshipGroup = new THREE.Group();

        // Main Body
        const bodyGeo = new THREE.CapsuleGeometry(0.6, 2.5, 4, 16);
        const bodyMat = new THREE.MeshStandardMaterial({ 
            color: 0x3366cc, 
            metalness: 0.7, 
            roughness: 0.2 
        });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.rotation.z = Math.PI / 2;
        body.castShadow = true;
        airshipGroup.add(body);

        // Tail Fin
        const tailGeo = new THREE.ConeGeometry(0.6, 1, 16);
        const tail = new THREE.Mesh(tailGeo, bodyMat);
        tail.rotation.z = -Math.PI / 2;
        tail.position.x = -1.8;
        airshipGroup.add(tail);

        // Vertical Stabilizer
        const stabGeo = new THREE.BoxGeometry(0.1, 0.8, 0.6);
        const stab = new THREE.Mesh(stabGeo, bodyMat);
        stab.position.set(-1.8, 0.4, 0);
        airshipGroup.add(stab);

        // Gondola
        const gondolaGeo = new THREE.BoxGeometry(0.8, 0.5, 0.8);
        const gondolaMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const gondola = new THREE.Mesh(gondolaGeo, gondolaMat);
        gondola.position.set(0, -1, 0);
        gondola.castShadow = true;
        airshipGroup.add(gondola);

        // Struts
        const strutGeo = new THREE.CylinderGeometry(0.03, 0.03, 1);
        const strut1 = new THREE.Mesh(strutGeo, gondolaMat);
        strut1.position.set(0.3, -0.5, 0);
        airshipGroup.add(strut1);
        const strut2 = new THREE.Mesh(strutGeo, gondolaMat);
        strut2.position.set(-0.3, -0.5, 0);
        airshipGroup.add(strut2);

        // Initial Position (High and to the right)
        airshipGroup.position.set(6, 4, 0);
        scene.add(airshipGroup);

        // Animation Loop
        let time = 0;
        const targetPos = new THREE.Vector3(0, 0.5, 0); // Docking spot on cloud

        function animate() {
            requestAnimationFrame(animate);
            time += 0.01;

            // Docking Logic: Move towards target
            const dx = targetPos.x - airshipGroup.position.x;
            const dy = targetPos.y - airshipGroup.position.y;
            const dz = targetPos.z - airshipGroup.position.z;

            airshipGroup.position.x += dx * 0.02;
            airshipGroup.position.y += dy * 0.02;
            airshipGroup.position.z += dz * 0.02;

            // Gentle bobbing and rotation
            airshipGroup.position.y += Math.sin(time * 2) * 0.005;
            airshipGroup.rotation.z = Math.sin(time) * 0.05;
            airshipGroup.rotation.y = Math.sin(time * 0.5) * 0.1;

            renderer.render(scene, camera);
        }

        animate();

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
