```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Jellyfish Lantern</title>
<style>
* { margin: 0; padding: 0; }
body { overflow: hidden; background: #000; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x020210, 0.035);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

// ── Post-processing (bloom for glow) ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.6, 0.8, 0.2
);
composer.addPass(bloom);

// ── Jellyfish Bell (Lathe profile) ──
const bellProfile = [];
const steps = 20;
for (let i = 0; i <= steps; i++) {
  const t = i / steps;
  const angle = t * Math.PI * 0.55;
  const r = Math.sin(angle) * 1.8 + Math.pow(t, 0.6) * 0.3;
  const y = Math.cos(angle) * 1.2 + 0.2;
  bellProfile.push(new THREE.Vector2(r, y));
}
// Close bottom slightly
bellProfile.push(new THREE.Vector2(0.15, -0.15));

const bellGeom = new THREE.LatheGeometry(bellProfile, 48);
bellGeom.computeVertexNormals();

const bellMat = new THREE.MeshPhysicalMaterial({
  color: 0x8844ff,
  emissive: 0x4422aa,
  emissiveIntensity: 0.6,
  transparent: true,
  opacity: 0.55,
  roughness: 0.1,
  metalness: 0.0,
  transmission: 0.6,
  thickness: 0.5,
  side: THREE.DoubleSide,
});

const bell = new THREE.Mesh(bellGeom, bellMat);
scene.add(bell);

// ── Inner glow core ──
const coreGeom = new THREE.SphereGeometry(0.5, 32, 32);
const coreMat = new THREE.MeshBasicMaterial({
  color: 0xcc88ff,
  transparent: true,
  opacity: 0.9,
});
const core = new THREE.Mesh(coreGeom, coreMat);
core.position.y = 0.1;
scene.add(core);

// ── Point light (pulses) ──
const lanternLight = new THREE.PointLight(0xaa66ff, 8, 15, 1.5);
lanternLight.position.y = 0.2;
scene.add(lanternLight);

const warmLight = new THREE.PointLight(0xff88cc, 3, 10, 2);
warmLight.position.y = 0.0;
scene.add(warmLight);

// ── Tentacles ──
const tentacleGroup = new THREE.Group();
scene.add(tentacleGroup);

function makeTentacleCurve(index) {
  const pts = [];
  const count = 30;
  const offset = (index / 6) * Math.PI * 2;
  const baseX = Math.cos(offset) * 0.6;
  const baseZ = Math.sin(offset) * 0.6;
  const length = 2.5 + Math.random() * 1.5;

  for (let i = 0; i <= count; i++) {
    const t = i / count;
    const x = baseX + Math.sin(t * 3.5 + index) * 0.15;
    const y = -0.15 - t * length;
    const z = baseZ + Math.cos(t * 2.8 + index * 0.7) * 0.12;
    pts.push(new THREE.Vector3(x, y, z));
  }
  return new THREE.CatmullRomCurve3(pts);
}

const tentacles = [];
const TENTACLE_COUNT = 18;

for (let i = 0; i < TENTACLE_COUNT; i++) {
  const curve = makeTentacleCurve(i);
  const tubeGeom = new THREE.TubeGeometry(curve, 24, 0.025, 6, false);
  const tubeMat = new THREE.MeshPhysicalMaterial({
    color: 0x9955ff,
    emissive: 0x5522cc,
    emissiveIntensity: 0.4,
    transparent: true,
    opacity: 0.5,
    roughness: 0.3,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(tubeGeom, tubeMat);
  tentacleGroup.add(mesh);
  tentacles.push({ mesh, curve, index: i, mat: tubeMat });
}

// ── Floating particles ──
const particleCount = 300;
const particleGeom = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 30;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
  sizes[i] = Math.random() * 3 + 1;
}
particleGeom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeom.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0x8866cc,
  size: 0.06,
  transparent: true,
  opacity: 0.4,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const particles = new THREE.Points(particleGeom, particleMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const pulse = Math.sin(t * 1.8) * 0.5 + 0.5; // 0..1 slow pulse
  const fastPulse = Math.sin(t * 4) * 0.5 + 0.5;

  // Bell breathing
  const breathe = 1 + pulse * 0.08;
  bell.scale.set(breathe, 1 + pulse * 0.12, breathe);

  // Core pulsing
  const coreScale = 0.8 + pulse * 0.4;
  core.scale.set(coreScale, coreScale, coreScale);
  coreMat.opacity = 0.5 + pulse * 0.5;

  // Light pulsing
  lanternLight.intensity = 4 + pulse * 8;
  lanternLight.color.setHSL(0.78 + pulse * 0.05, 0.8, 0.5 + pulse * 0.2);
  warmLight.intensity = 1 + fastPulse * 3;

  // Emissive pulse
  bellMat.emissiveIntensity = 0.3 + pulse * 0.7;
  bellMat.opacity = 0.35 + pulse * 0.25;

  // Tentacle sway
  tentacles.forEach(({ mat, index }) => {
    const sway = Math.sin(t * 1.2 + index * 0.5) * 0.03;
    mat.emissiveIntensity = 0.2 + pulse * 0.3 + sway;
    mat.opacity = 0.3 + pulse * 0.2;
  });

  // Gentle float
  bell.position.y = Math.sin(t * 0.5) * 0.3;
  core.position.y = 0.1 + Math.sin(t * 0.5) * 0.3;
  lanternLight.position.y = 0.2 + Math.sin(t * 0.5) * 0.3;
  warmLight.position.y = Math.sin(t * 0.5) * 0.3;
  tentacleGroup.position.y = Math.sin(t * 0.5) * 0.3;

  // Slow rotation
  tentacleGroup.rotation.y = t * 0.1;
  bell.rotation.y = t * 0.05;

  // Particles drift
  const posArr = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    posArr[i * 3 + 1] += Math.sin(t + i) * 0.001;
    posArr[i * 3] += Math.cos(t * 0.5 + i * 0.1) * 0.0005;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

## What's happening

| Feature | Detail |
|---|---|
| **Bell** | A `LatheGeometry` profile creates an organic dome shape with semi-transparent, physically-based glass-like material (`transmission`, `opacity`) |
| **Glow core** | A bright inner sphere + two `PointLight`s (purple + warm pink) simulate the lantern's light source |
| **Pulse** | A sine-driven `pulse` value modulates light intensity, emissive strength, bell scale ("breathing"), and core opacity every ~3.5 seconds |
| **Tentacles** | 18 `TubeGeometry` strands follow `CatmullRomCurve3` paths with sinusoidal offsets; they sway and glow in sync with the pulse |
| **Bloom** | `UnrealBloomPass` post-processing gives everything a soft neon halo |
| **Particles** | 300 additive-blended points drift slowly for ambient atmosphere |
| **Float** | The whole jellyfish gently bobs up/down and rotates |

