<body>
    <div id="info">✦ Floating Star Chandelier ✦</div>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 0, 15);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Chandelier Group
        const chandelierGroup = new THREE.Group();
        scene.add(chandelierGroup);

        // Materials
        const starMaterial = new THREE.MeshBasicMaterial({ color: 0xffd700 });
        const armMaterial = new THREE.MeshBasicMaterial({ color: 0x444444 });
        const glowMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 0.6 });

        // Helper to create a star shape
        function createStarGeometry(radius, depth) {
            const shape = new THREE.Shape();
            const outerRadius = radius;
            const innerRadius = radius / 2;
            const points = 5;

            for (let i = 0; i < points * 2; i++) {
                const r = (i % 2 === 0) ? outerRadius : innerRadius;
                const a = (i * Math.PI) / points - Math.PI / 2;
                const x = Math.cos(a) * r;
                const y = Math.sin(a) * r;
                if (i === 0) shape.moveTo(x, y);
                else shape.lineTo(x, y);
            }
            shape.closePath();

            const extrudeSettings = {
                steps: 1,
                depth: depth,
                bevelEnabled: true,
                bevelThickness: 0.1,
                bevelSize: 0.1,
                bevelSegments: 1
            };

            return new THREE.ExtrudeGeometry(shape, extrudeSettings);
        }

        const starGeo = createStarGeometry(0.3, 0.1);
        const smallStarGeo = createStarGeometry(0.15, 0.05);

        // Central Hub
        const hubGeo = new THREE.IcosahedronGeometry(1, 1);
        const hub = new THREE.Mesh(hubGeo, new THREE.MeshStandardMaterial({ 
            color: 0x222222, 
            roughness: 0.2, 
            metalness: 0.8,
            emissive: 0xffaa00,
            emissiveIntensity: 0.2
        }));
        chandelierGroup.add(hub);

        // Arms and Hanging Stars
        const numArms = 8;
        const armLength = 4;

        for (let i = 0; i < numArms; i++) {
            const angle = (i / numArms) * Math.PI * 2;
            const armGroup = new THREE.Group();

            // Arm structure
            const armGeo = new THREE.CylinderGeometry(0.05, 0.05, armLength, 8);
            const arm = new THREE.Mesh(armGeo, armMaterial);
            arm.rotation.z = Math.PI / 2;
            arm.position.x = armLength / 2;
            armGroup.add(arm);

            // End star
            const endStar = new THREE.Mesh(starGeo, starMaterial);
            endStar.position.x = armLength;
            endStar.rotation.z = Math.PI / 2;
            armGroup.add(endStar);

            // Hanging crystals/stars
            const numHanging = 3;
            for (let j = 0; j < numHanging; j++) {
                const hAngle = (j / numHanging) * Math.PI * 2;
                const hRadius = 0.5;
                const hLength = 1.5 + Math.random();

                const hGroup = new THREE.Group();
                hGroup.position.x = armLength;

                // Chain
                const chainGeo = new THREE.CylinderGeometry(0.02, 0.02, hLength, 4);
                const chain = new THREE.Mesh(chainGeo, armMaterial);
                chain.position.y = -hLength / 2;
                hGroup.add(chain);

                // Hanging Star
                const hStar = new THREE.Mesh(smallStarGeo, starMaterial);
                hStar.position.y = -hLength;
                hStar.rotation.x = Math.random() * Math.PI;
                hStar.rotation.y = Math.random() * Math.PI;
                hGroup.add(hStar);

                // Glow
                const glowGeo = new THREE.SphereGeometry(0.2, 8, 8);
                const glow = new THREE.Mesh(glowGeo, glowMaterial);
                glow.position.y = -hLength;
                hGroup.add(glow);

                armGroup.add(hGroup);
            }

            armGroup.rotation.y = angle;
            chandelierGroup.add(armGroup);
        }

        // Top Ring
        const ringGeo = new THREE.TorusGeometry(1.5, 0.1, 16, 100);
        const ring = new THREE.Mesh(ringGeo, armMaterial);
        ring.position.y = 1;
        chandelierGroup.add(ring);

        // Top Chain
        const topChainGeo = new THREE.CylinderGeometry(0.05, 0.05, 5, 8);
        const topChain = new THREE.Mesh(topChainGeo, armMaterial);
        topChain.position.y = 3.5;
        chandelierGroup.add(topChain);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040);
        scene.add(ambientLight);

        const pointLight = new THREE.PointLight(0xffaa00, 2, 20);
        pointLight.position.set(0, 0, 0);
        chandelierGroup.add(pointLight);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Floating motion
            chandelierGroup.position.y = Math.sin(time * 0.5) * 0.5;

            // Slow rotation
            chandelierGroup.rotation.y = time * 0.1;

            // Twinkle effect for stars
            starMaterial.opacity = 0.8 + Math.sin(time * 5) * 0.2;
            glowMaterial.opacity = 0.4 + Math.sin(time * 3) * 0.2;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
