        // Grid Helper
        const gridHelper = new THREE.GridHelper(100, 50, 0x444444, 0x222222);
        scene.add(gridHelper);

        // --- The Glowing Orb ---
        const orbGeometry = new THREE.SphereGeometry(0.8, 32, 32);
        const orbMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ffff,
            emissive: 0x00ffff,
            emissiveIntensity: 2,
            roughness: 0.1,
            metalness: 0.5
        });
        const orb = new THREE.Mesh(orbGeometry, orbMaterial);
        orb.castShadow = true;
        orb.position.set(0, 0.8, -2); // Start slightly ahead
        scene.add(orb);

        // Orb Light
        const orbLight = new THREE.PointLight(0x00ffff, 5, 10);
        orb.add(orbLight);

        // --- The Robotic Beetle ---
        const beetleGroup = new THREE.Group();
        scene.add(beetleGroup);

        // Materials
        const metalMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.3, metalness: 0.8 });
        const darkMetalMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5, metalness: 0.9 });
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });

        // Body (Thorax/Abdomen)
        const bodyGeo = new THREE.CapsuleGeometry(0.6, 1.5, 4, 8);
        const body = new THREE.Mesh(bodyGeo, metalMat);
        body.rotation.z = Math.PI / 2;
        body.position.y = 0.8;
        body.castShadow = true;
        beetleGroup.add(body);

