        const head = new THREE.Mesh(headGeo, darkMetalMat);
        head.position.set(0, 0.8, 1.2);
        head.castShadow = true;
        beetleGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.1, 8, 8);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.3, 0.9, 1.5);
        beetleGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.3, 0.9, 1.5);
        beetleGroup.add(rightEye);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.8);
        const leftAntenna = new THREE.Mesh(antennaGeo, darkMetalMat);
        leftAntenna.position.set(-0.2, 1.2, 1.4);
        leftAntenna.rotation.x = -Math.PI / 4;
        beetleGroup.add(leftAntenna);
        const rightAntenna = new THREE.Mesh(antennaGeo, darkMetalMat);
        rightAntenna.position.set(0.2, 1.2, 1.4);
        rightAntenna.rotation.x = -Math.PI / 4;
        beetleGroup.add(rightAntenna);

        // Legs
        const legs = [];
        const legGeo = new THREE.CylinderGeometry(0.05, 0.05, 1.2);

        function createLeg(x, z, angle) {
            const legGroup = new THREE.Group();
            legGroup.position.set(x, 0.8, z);

            const legMesh = new THREE.Mesh(legGeo, darkMetalMat);
            legMesh.position.y = -0.6; // Pivot at top
            legMesh.castShadow = true;

            legGroup.add(legMesh);
            beetleGroup.add(legGroup);
            legs.push(legGroup);
            return legGroup;
        }

        // Create 6 legs (3 pairs)
        // Front pair
        createLeg(-0.7, 0.5, 0);
        createLeg(0.7, 0.5, 0);
        // Middle pair
        createLeg(-0.8, 0, 0);
        createLeg(0.8, 0, 0);
        // Back pair
        createLeg(-0.7, -0.5, 0);
        createLeg(0.7, -0.5, 0);

        // Animation Variables
        let time = 0;
        const speed = 2.5;
        const walkCycleSpeed = 10;

        function animate() {
            requestAnimationFrame(animate);
            time += 0.01;

            // Move Beetle
            beetleGroup.position.z -= speed * 0.01;

            // Move Orb (rolling in front)
            orb.position.z = beetleGroup.position.z - 2.5;
            orb.rotation.x -= 0.1; // Rolling effect

            // Camera Follow
            camera.position.z = beetleGroup.position.z + 8;
            camera.position.x = Math.sin(time * 0.5) * 2; // Slight sway
            camera.lookAt(beetleGroup.position.x, 1, beetleGroup.position.z - 2);

            // Animate Legs
            legs.forEach((leg, index) => {
                // Offset phase for alternating legs
                const phase = index % 2 === 0 ? 0 : Math.PI; 
                const angle = Math.sin(time * walkCycleSpeed + phase) * 0.5;

                // Rotate legs around X axis (forward/back) and Z axis (outward/inward)
                leg.rotation.x = angle;
                leg.rotation.z = Math.cos(time * walkCycleSpeed + phase) * 0.2;
            });

            // Bob the body slightly
            beetleGroup.position.y = Math.abs(Math.sin(time * walkCycleSpeed)) * 0.05;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
