<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.z = 8;
        camera.position.y = 2;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const pointLight1 = new THREE.PointLight(0x00ffff, 50, 20);
        pointLight1.position.set(5, 5, 5);
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0xff00ff, 50, 20);
        pointLight2.position.set(-5, -5, 5);
        scene.add(pointLight2);

        const pointLight3 = new THREE.PointLight(0xffffff, 20, 20);
        pointLight3.position.set(0, 5, -5);
        scene.add(pointLight3);

        // Crystal Material
        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xaaccff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 1.5,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            transparent: true,
            opacity: 0.9,
            side: THREE.DoubleSide
        });

        // Octopus Group
        const octopus = new THREE.Group();
        scene.add(octopus);

        // Head (Icosahedron for faceted crystal look)
        const headGeometry = new THREE.IcosahedronGeometry(1.5, 1);
        const head = new THREE.Mesh(headGeometry, crystalMaterial);
        octopus.add(head);

        // Eyes (Simple dark spheres)
        const eyeGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.5, 0.2, 1.2);
        octopus.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.5, 0.2, 1.2);
        octopus.add(rightEye);

        // Tentacles
        const tentacleCount = 8;
        const tentacles = [];

        for (let i = 0; i < tentacleCount; i++) {
            const angle = (i / tentacleCount) * Math.PI * 2;

            // Create a curve for the tentacle
            const points = [];
            const segments = 10;
            for (let j = 0; j <= segments; j++) {
                const t = j / segments;
                // Start at bottom of head
                const startY = -1.2;
                // Curve downwards and outwards
                const x = Math.cos(angle) * (1 + t * 2);
                const z = Math.sin(angle) * (1 + t * 2);
                const y = startY - (t * 4) + Math.sin(t * Math.PI * 2) * 0.5; // Wavy motion
                points.push(new THREE.Vector3(x, y, z));
            }

            const curve = new THREE.CatmullRomCurve3(points);
            const geometry = new THREE.TubeGeometry(curve, 20, 0.15 - 0.1 * (i/tentacleCount), 8, false);
            const tentacle = new THREE.Mesh(geometry, crystalMaterial);

            // Store initial rotation for animation
            tentacle.userData = { 
                initialAngle: angle,
                offset: Math.random() * 100 
            };

            octopus.add(tentacle);
            tentacles.push(tentacle);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Float the whole octopus
            octopus.position.y = Math.sin(time * 0.5) * 0.5;
            octopus.rotation.y = Math.sin(time * 0.2) * 0.2;
            octopus.rotation.z = Math.cos(time * 0.3) * 0.1;

            // Animate tentacles slightly
            tentacles.forEach((tentacle, i) => {
                // Subtle rotation around local axis to simulate swimming
                tentacle.rotation.x = Math.sin(time * 2 + i) * 0.1;
                tentacle.rotation.z = Math.cos(time * 1.5 + i) * 0.1;
            });

            // Move lights slightly
            pointLight1.position.x = Math.sin(time * 0.7) * 5;
            pointLight1.position.z = Math.cos(time * 0.7) * 5;

            pointLight2.position.x = Math.cos(time * 0.5) * 5;
            pointLight2.position.z = Math.sin(time * 0.5) * 5;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
