        tooth2.position.set(2.8, -0.1, 0);
        tooth2.scale.set(0.8, 1, 1);
        keyGroup.add(tooth2);

        // Position Key relative to Portal
        keyGroup.position.set(0, 0, 2.5);
        keyGroup.rotation.y = -0.2;
        keyGroup.rotation.z = 0.1;

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate portal particles
            particles.rotation.z = time * 0.5;

            // Pulse portal light
            portalLight.intensity = 3 + Math.sin(time * 2) * 2;

            // Subtle key float
