</script>
<script type="module">
import * as THREE from 'three';

/* ── Scene ── */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050510);
scene.fog = new THREE.FogExp2(0x050510, 0.025);

const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 3, 12);
camera.lookAt(0, 2, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

/* ── Lantern ── */
const lanternGroup = new THREE.Group();
lanternGroup.position.set(0, 5, 0);
scene.add(lanternGroup);

// Body – translucent warm cylinder
const bodyGeo = new THREE.CylinderGeometry(0.8, 0.8, 2.2, 16, 1, true);
const bodyMat = new THREE.MeshStandardMaterial({
  color: 0xffcc66,
  emissive: 0xff9933,
  emissiveIntensity: 0.8,
  transparent: true,
  opacity: 0.55,
  side: THREE.DoubleSide,
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
lanternGroup.add(body);

// Inner glow sphere
const glowGeo = new THREE.SphereGeometry(0.55, 16, 16);
const glowMat = new THREE.MeshBasicMaterial({ color: 0xffeebb });
const glowSphere = new THREE.Mesh(glowGeo, glowMat);
lanternGroup.add(glowSphere);

// Top cap – cone
const topGeo = new THREE.ConeGeometry(0.85, 0.6, 16);
const topMat = new THREE.MeshStandardMaterial({ color: 0xcc4422, metalness: 0.3, roughness: 0.6 });
const topCap = new THREE.Mesh(topGeo, topMat);
topCap.position.y = 1.4;
lanternGroup.add(topCap);

// Bottom cap
const botGeo = new THREE.CylinderGeometry(0.6, 0.3, 0.15, 16);
const botCap = new THREE.Mesh(botGeo, topMat);
botCap.position.y = -1.15;
lanternGroup.add(botCap);

// Tassel string
const tasselGeo = new THREE.CylinderGeometry(0.015, 0.015, 1.8, 6);
const tasselMat = new THREE.MeshStandardMaterial({ color: 0xcc2200 });
const tassel = new THREE.Mesh(tasselGeo, tasselMat);
tassel.position.y = -2.05;
lanternGroup.add(tassel);

// Tassel fringe
const fringeGeo = new THREE.ConeGeometry(0.1, 0.35, 8);
const fringe = new THREE.Mesh(fringeGeo, tasselMat);
fringe.position.y = -3.0;
fringe.rotation.x = Math.PI;
lanternGroup.add(fringe);

// Point light
const lanternLight = new THREE.PointLight(0xffaa44, 3, 18, 1.5);
lanternLight.position.set(0, 0, 0);
lanternGroup.add(lanternLight);

// Rim rings
[1.05, -1.05].forEach(y => {
  const ringGeo = new THREE.TorusGeometry(0.82, 0.025, 8, 24);
  const ring = new THREE.Mesh(ringGeo, topMat);
  ring.position.y = y;
  lanternGroup.add(ring);
});

/* ── Paper Boat Geometry ── */
function createBoatGeometry() {
  // Origami-style boat: two folded planes meeting at a keel
  const shape = new THREE.Shape();
  shape.moveTo(-0.25, 0);
  shape.lineTo(0, 0.22);
  shape.lineTo(0.3, 0);
  shape.lineTo(0.25, -0.05);
  shape.lineTo(-0.2, -0.05);
  shape.lineTo(-0.25, 0);

  const extrudeSettings = { depth: 0.005, bevelEnabled: false };
  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.rotateX(Math.PI / 2);
  return geo;
}

const boatGeo = createBoatGeometry();
const boatColors = [0xf5f0e0, 0xfff8dc, 0xfaf0e6, 0xf0e6d2, 0xfffaf0];

const boats = [];

function spawnBoat() {
  const color = boatColors[Math.floor(Math.random() * boatColors.length)];
  const mat = new THREE.MeshStandardMaterial({
    color,
    emissive: 0xffaa44,
    emissiveIntensity: 0.15,
    roughness: 0.8,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(boatGeo, mat);

  // Start near the lantern base
  const angle = Math.random() * Math.PI * 2;
  const spread = Math.random() * 0.3;
  mesh.position.set(
    Math.cos(angle) * spread,
    lanternGroup.position.y - 1.8,
    Math.sin(angle) * spread
  );

  mesh.scale.setScalar(0.4 + Math.random() * 0.6);
  mesh.rotation.y = Math.random() * Math.PI * 2;

  scene.add(mesh);

  boats.push({
    mesh,
    vy: -0.15 - Math.random() * 0.15,
    vx: (Math.random() - 0.5) * 0.03,
    vz: (Math.random() - 0.5) * 0.03,
    rotSpeed: (Math.random() - 0.5) * 0.02,
    wobblePhase: Math.random() * Math.PI * 2,
    wobbleSpeed: 0.8 + Math.random() * 1.2,
    wobbleAmp: 0.01 + Math.random() * 0.02,
    life: 0,
    maxLife: 12 + Math.random() * 10,
  });
}

/* ── Floating embers / particles ── */
const emberCount = 80;
const emberGeo = new THREE.BufferGeometry();
const emberPositions = new Float32Array(emberCount * 3);
const emberSizes = new Float32Array(emberCount);
const emberData = [];

for (let i = 0; i < emberCount; i++) {
  resetEmber(i);
}

function resetEmber(i) {
  const angle = Math.random() * Math.PI * 2;
  const r = Math.random() * 1.5;
  emberPositions[i * 3] = Math.cos(angle) * r;
  emberPositions[i * 3 + 1] = lanternGroup.position.y + (Math.random() - 0.5) * 3;
  emberPositions[i * 3 + 2] = Math.sin(angle) * r;
  emberSizes[i] = Math.random() * 3 + 1;
  emberData.push({
    vy: 0.005 + Math.random() * 0.015,
    vx: (Math.random() - 0.5) * 0.005,
    vz: (Math.random() - 0.5) * 0.005,
  });
}

emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPositions, 3));
emberGeo.setAttribute('size', new THREE.BufferAttribute(emberSizes, 1));

const emberMat = new THREE.PointsMaterial({
  color: 0xffcc66,
  size: 0.08,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
  sizeAttenuation: true,
});
const embers = new THREE.Points(emberGeo, emberMat);
scene.add(embers);

/* ── Ground plane (subtle) ── */
const groundGeo = new THREE.PlaneGeometry(80, 80);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0a0a15,
  roughness: 1,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -5;
scene.add(ground);

/* ── Stars ── */
const starCount = 300;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  starPos[i * 3] = (Math.random() - 0.5) * 100;
  starPos[i * 3 + 1] = 10 + Math.random() * 60;
  starPos[i * 3 + 2] = (Math.random() - 0.5) * 100;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.15,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
});
scene.add(new THREE.Points(starGeo, starMat));

/* ── Spawn timer ── */
let spawnAccum = 0;
const spawnInterval = 0.4;

/* ── Animate ── */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  // Lantern bob
  lanternGroup.position.y = 5 + Math.sin(t * 0.8) * 0.25;
  lanternGroup.rotation.z = Math.sin(t * 0.5) * 0.03;

  // Light flicker
  lanternLight.intensity = 3 + Math.sin(t * 3.7) * 0.4 + Math.sin(t * 7.1) * 0.2;
  glowMat.color.setHSL(0.1, 0.6, 0.85 + Math.sin(t * 5) * 0.05);

  // Spawn boats
  spawnAccum += dt;
  while (spawnAccum >= spawnInterval) {
    spawnBoat();
    spawnAccum -= spawnInterval;
  }

  // Update boats
  for (let i = boats.length - 1; i >= 0; i--) {
    const b = boats[i];
    b.life += dt;

    b.mesh.position.y += b.vy * dt;
    b.mesh.position.x += b.vx * dt + Math.sin(t * b.wobbleSpeed + b.wobblePhase) * b.wobbleAmp;
    b.mesh.position.z += b.vz * dt + Math.cos(t * b.wobbleSpeed + b.wobblePhase) * b.wobbleAmp;
    b.mesh.rotation.y += b.rotSpeed;

    // Gentle tumble
    b.mesh.rotation.x = Math.sin(t * 0.7 + i) * 0.15;

    // Fade out near end of life
    if (b.life > b.maxLife - 3) {
      b.mesh.material.opacity = Math.max(0, (b.maxLife - b.life) / 3);
      b.mesh.material.transparent = true;
    }

    // Remove dead boats
    if (b.life >= b.maxLife || b.mesh.position.y < -6) {
      scene.remove(b.mesh);
      b.mesh.geometry.dispose();
      b.mesh.material.dispose();
      boats.splice(i, 1);
    }
  }

  // Update embers
  const ePos = embers.geometry.attributes.position.array;
  for (let i = 0; i < emberCount; i++) {
    ePos[i * 3] += emberData[i].vx + Math.sin(t * 0.5 + i) * 0.002;
    ePos[i * 3 + 1] += emberData[i].vy;
    ePos[i * 3 + 2] += emberData[i].vz + Math.cos(t * 0.3 + i) * 0.002;

    if (ePos[i * 3 + 1] > lanternGroup.position.y + 5) {
      resetEmber(i);
      ePos[i * 3] = lanternGroup.children[0]?.geometry?.parameters?.radiusTop
        ? (Math.random() - 0.5) * 1.5 : 0;
      ePos[i * 3 + 1] = lanternGroup.position.y - 1;
      ePos[i * 3 + 2] = (Math.random() - 0.5) * 1.5;
    }
  }
  embers.geometry.attributes.position.needsUpdate = true;

  // Gentle camera sway
  camera.position.x = Math.sin(t * 0.15) * 1.5;
  camera.lookAt(0, 3, 0);

  renderer.render(scene, camera);
}

animate();

/* ── Resize ── */
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
