                shape.absarc(0, 0, outerRadius, angle + step * 0.2, angle + step * 0.8, false);
                shape.lineTo(Math.cos(angle + step * 0.8) * innerRadius, Math.sin(angle + step * 0.8) * innerRadius);
                // Inner arc to next tooth
                shape.absarc(0, 0, innerRadius, angle + step * 0.8, nextAngle, false);
            }

            // Center hole
            const holePath = new THREE.Path();
            holePath.absarc(0, 0, innerRadius * 0.4, 0, Math.PI * 2, true);
            shape.holes.push(holePath);

            const extrudeSettings = {
                steps: 1,
                depth: thickness,
                bevelEnabled: true,
                bevelThickness: 0.05,
                bevelSize: 0.05,
                bevelSegments: 2
            };

