scene.add(shellLight);
const rimLight = new THREE.DirectionalLight(0x8844ff, 0.8);
rimLight.position.set(-5, 4, -3);
scene.add(rimLight);

// ── Nautilus Shell Geometry ──
function createNautilus() {
  const points = [];
  const turns = 3;
  const samples = 600;
  const a = 0.15;
  const b = 0.18;

  for (let i = 0; i <= samples; i++) {
    const t = (i / samples) * turns * Math.PI * 2;
    const r = a * Math.exp(b * t);
    const x = r * Math.cos(t);
    const z = r * Math.sin(t);
    const y = Math.sin(t * 0.5) * 0.15;
    points.push(new THREE.Vector3(x, y, z));
  }

  const curve = new THREE.CatmullRomCurve3(points);
  const radii = [];
  for (let i = 0; i <= samples; i++) {
    const t = (i / samples) * turns * Math.PI * 2;
    const r = a * Math.exp(b * t);
    const tubeR = 0.12 + r * 0.18;
    radii.push(tubeR);
  }

  // Build custom tube with varying radius
  const tubeSegments = samples;
  const radialSegments = 16;
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  const frame = new THREE.Tuple();
  const up = new THREE.Vector3(0, 1, 0);
  const tempVec = new THREE.Vector3();
  const tempNorm = new THREE.Vector3();

  for (let i = 0; i <= tubeSegments; i++) {
    const t = i / tubeSegments;
    const pos = curve.getPointAt(t);
    const radius = radii[i];

    curve.computeFrenetFrames(tubeSegments, false);
    const normal = curve.getNormalAt(t);
    const binormal = new THREE.Vector3();
    tempVec.copy(pos).add(normal);

    // Compute Frenet frame
    const tangent = curve.getTangentAt(t);
    const N = normal.clone();
    const B = new THREE.Vector3().crossVectors(tangent, N).normalize();
    const N2 = new THREE.Vector3().crossVectors(B, tangent).normalize();

    for (let j = 0; j <= radialSegments; j++) {
      const theta = (j / radialSegments) * Math.PI * 2;
      const cos = Math.cos(theta);
      const sin = Math.sin(theta);

      const nx = cos * N2.x + sin * B.x;
      const ny = cos * N2.y + sin * B.y;
      const nz = cos * N2.z + sin * B.z;

      positions.push(
        pos.x + nx * radius,
        pos.y + ny * radius,
        pos.z + nz * radius
      );
      normals.push(nx, ny, nz);
      uvs.push(j / radialSegments, t);
    }
  }

  for (let i = 0; i < tubeSegments; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * (radialSegments + 1) + j;
      const b2 = a + radialSegments + 1;
      indices.push(a, b2, a + 1);
      indices.push(b2, b2 + 1, a + 1);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  return geo;
}

const nautilusGeo = createNautilus();
const nautilusMat = new THREE.MeshStandardMaterial({
  color: 0x1a3a4a,
  emissive: 0x22aacc,
  emissiveIntensity: 0.8,
  metalness: 0.6,
  roughness: 0.25,
  transparent: true,
  opacity: 0.9,
});
const nautilus = new THREE.Mesh(nautilusGeo, nautilusMat);
nautilus.rotation.x = -Math.PI * 0.45;
nautilus.scale.setScalar(1.8);
scene.add(nautilus);

// Inner glow sphere
const glowGeo = new THREE.SphereGeometry(0.3, 32, 32);
const glowMat = new THREE.MeshBasicMaterial({
  color: 0x44eeff,
  transparent: true,
  opacity: 0.6,
});
const glowSphere = new THREE.Mesh(glowGeo, glowMat);
glowSphere.position.set(0, 0, 0);
nautilus.add(glowSphere);

// ── Water ──
const waterVert = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vElev;
  varying vec3 vWorldPos;

  void main() {
    vUv = uv;
    vec3 p = position;
    float wave1 = sin(p.x * 0.8 + uTime * 0.7) * cos(p.z * 0.6 + uTime * 0.5) * 0.3;
    float wave2 = sin(p.x * 1.5 + uTime * 1.1) * sin(p.z * 1.2 + uTime * 0.8) * 0.12;
    float wave3 = cos(p.z * 0.4 + uTime * 0.3) * sin(p.x * 0.3 - uTime * 0.2) * 0.2;
    p.y += wave1 + wave2 + wave3;
    vElev = p.y;
    vWorldPos = (modelMatrix * vec4(p, 1.0)).xyz;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
  }
`;

const waterFrag = `
  uniform float uTime;
  uniform vec3 uColor1;
  uniform vec3 uColor2;
  varying vec2 vUv;
  varying float vElev;
  varying vec3 vWorldPos;

  void main() {
    float mixFactor = (vElev + 0.5) * 0.5;
    vec3 color = mix(uColor1, uColor2, clamp(mixFactor, 0.0, 1.0));

    // Fresnel-like rim
    vec3 viewDir = normalize(cameraPosition - vWorldPos);
    float fresnel = pow(1.0 - abs(dot(viewDir, vec3(0.0, 1.0, 0.0))), 2.0);
    color += vec3(0.15, 0.4, 0.6) * fresnel * 0.5;

    // Subtle caustic-like pattern
    float caustic = sin(vUv.x * 20.0 + uTime * 2.0) * cos(vUv.y * 18.0 - uTime * 1.5);
    color += vec3(0.05, 0.15, 0.12) * caustic * 0.15;

    float alpha = 0.75 + fresnel * 0.2;
    gl_FragColor = vec4(color, alpha);
  }
`;

const waterGeo = new THREE.PlaneGeometry(80, 80, 256, 256);
waterGeo.rotateX(-Math.PI / 2);
const waterMat = new THREE.ShaderMaterial({
  vertexShader: waterVert,
  fragmentShader: waterFrag,
  uniforms: {
    uTime: { value: 0 },
    uColor1: { value: new THREE.Color(0x021a2e) },
    uColor2: { value: new THREE.Color(0x0a4a6a) },
  },
  transparent: true,
  side: THREE.DoubleSide,
});
const water = new THREE.Mesh(waterGeo, waterMat);
water.position.y = -2.5;
scene.add(water);

// ── Floating Particles ──
const particleCount = 300;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(particleCount * 3);
const pSizes = new Float32Array(particleCount);
for (let i = 0; i < particleCount; i++) {
  pPos[i * 3] = (Math.random() - 0.5) * 30;
  pPos[i * 3 + 1] = Math.random() * 12 - 2;
  pPos[i * 3 + 2] = (Math.random() - 0.5) * 30;
  pSizes[i] = Math.random() * 3 + 1;
}
pGeo.setAttribute('position', new THREE.Float32BufferAttribute(pPos, 3));
pGeo.setAttribute('size', new THREE.Float32BufferAttribute(pSizes, 1));

const pMat = new THREE.PointsMaterial({
  color: 0x44ccff,
  size: 0.06,
  transparent: true,
  opacity: 0.5,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
});
const particles = new THREE.Points(pGeo, pMat);
scene.add(particles);

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Float nautilus
  nautilus.position.y = Math.sin(t * 0.5) * 0.4 + 0.8;
  nautilus.rotation.z = Math.sin(t * 0.3) * 0.05;
  nautilus.rotation.y = t * 0.1;

  // Pulse glow
  nautilusMat.emissiveIntensity = 0.6 + Math.sin(t * 1.5) * 0.3;
  glowMat.opacity = 0.4 + Math.sin(t * 2) * 0.2;
  shellLight.intensity = 4 + Math.sin(t * 1.5) * 2;

  // Water
  waterMat.uniforms.uTime.value = t;

  // Particles drift
  particles.rotation.y = t * 0.02;
  const pp = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    pp[i * 3 + 1] += Math.sin(t + i) * 0.001;
  }
  particles.geometry.attributes.position.needsUpdate = true;

  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
