        scene.fog = new THREE.FogExp2(0x050510, 0.03);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 8, 18);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Hill Geometry (Mound)
        // CylinderGeometry(radiusTop, radiusBottom, height, radialSegments)
        const hillGeometry = new THREE.CylinderGeometry(2, 12, 6, 32);
        const hillMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x1a2b1a, 
            roughness: 0.9,
            flatShading: true
        });
        const hill = new THREE.Mesh(hillGeometry, hillMaterial);
        hill.position.y = -3; // Center the base at y=0 roughly
        scene.add(hill);

        // Mushroom City
        const mushrooms = [];
        const colors = [0x00ffaa, 0x00aaff, 0xaa00ff, 0xffaa00, 0xff0055];

        function createMushroom(x, z) {
            // Calculate height on the hill surface
            // Hill goes from y=-3 (r=12) to y=3 (r=2)
            // r(y) = 12 - (10/6)*(y+3) => r = 12 - 1.66(y+3)
            // dist = 12 - 1.66(y+3) => 1.66(y+3) = 12 - dist => y+3 = (12-dist)/1.66 => y = (12-dist)/1.66 - 3

            const dist = Math.sqrt(x*x + z*z);
            if (dist > 11) return; // Keep inside the hill base

            let y = (12 - dist) / 1.66 - 3;
            if (y > 3) y = 3; // Cap at top
            if (y < -3) y = -3;

            const group = new THREE.Group();
            group.position.set(x, y, z);

            // Stem
            const stemGeo = new THREE.CylinderGeometry(0.1, 0.2, 1, 8);
            const stemMat = new THREE.MeshStandardMaterial({ color: 0xdddddd });
            const stem = new THREE.Mesh(stemGeo, stemMat);
            stem.position.y = 0.5;
            group.add(stem);

            // Cap
            const capGeo = new THREE.SphereGeometry(0.4, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2);
            const color = colors[Math.floor(Math.random() * colors.length)];
            const capMat = new THREE.MeshStandardMaterial({ 
                color: color, 
                emissive: color, 
                emissiveIntensity: 2,
                roughness: 0.2
            });
            const cap = new THREE.Mesh(capGeo, capMat);
            cap.position.y = 1;
            group.add(cap);

            // Glow Light
            const light = new THREE.PointLight(color, 2, 4);
            light.position.y = 1.2;
            group.add(light);

            // Random scale and rotation
            const scale = 0.8 + Math.random() * 0.5;
            group.scale.set(scale, scale, scale);
            group.rotation.y = Math.random() * Math.PI * 2;

            scene.add(group);
            mushrooms.push(group);
        }

        // Generate City
        for (let i = 0; i < 40; i++) {
            const angle = Math.random() * Math.PI * 2;
            const radius = Math.random() * 10; // Spread across the hill
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle) * radius;
            createMushroom(x, z);
        }

        // Animation Loop
        function animate() {
            requestAnimationFrame(animate);

            // Gentle rotation of the whole city for effect
            scene.rotation.y += 0.002;

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
