        tail.position.set(0, -0.1, -0.8);
        tail.rotation.x = -0.5;
        hummingbird.add(tail);

        // Add some mechanical details (joints)
        const jointGeo = new THREE.TorusGeometry(0.15, 0.05, 8, 16);
        const leftJoint = new THREE.Mesh(jointGeo, darkMetalMaterial);
        leftJoint.position.set(0.3, 0.2, 0);
