        rightJoint.position.set(-0.3, 0.2, 0);
        rightJoint.rotation.y = Math.PI / 2;
        hummingbird.add(rightJoint);

        scene.add(hummingbird);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
