<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Lantern Galaxy</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050505; }
