    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.z = 4;
        camera.position.y = 0.5;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        document.body.appendChild(renderer.domElement);

        // --- The Lantern ---
        const lanternGroup = new THREE.Group();
        scene.add(lanternGroup);

        // Lantern Glass (Cylinder)
        const glassGeo = new THREE.CylinderGeometry(1.2, 1.2, 2.5, 32, 1, true);
        const glassMat = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.1,
            transmission: 0.9, // Glass-like
            thickness: 0.5,
            transparent: true,
            opacity: 0.3,
            side: THREE.DoubleSide
        });
        const glass = new THREE.Mesh(glassGeo, glassMat);
        lanternGroup.add(glass);

        // Lantern Frame (Wireframe Cylinder)
        const frameGeo = new THREE.CylinderGeometry(1.25, 1.25, 2.6, 12, 4, true);
        const frameMat = new THREE.MeshBasicMaterial({ color: 0x888888, wireframe: true, transparent: true, opacity: 0.5 });
        const frame = new THREE.Mesh(frameGeo, frameMat);
        lanternGroup.add(frame);

        // Lantern Top Cap
        const topGeo = new THREE.ConeGeometry(1.3, 0.5, 32);
        const metalMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.4, metalness: 0.8 });
        const topCap = new THREE.Mesh(topGeo, metalMat);
        topCap.position.y = 1.5;
        lanternGroup.add(topCap);

        // Lantern Bottom Cap
        const bottomGeo = new THREE.CylinderGeometry(1.3, 1.3, 0.1, 32);
        const bottomCap = new THREE.Mesh(bottomGeo, metalMat);
        bottomCap.position.y = -1.25;
        lanternGroup.add(bottomCap);

        // Handle
        const handleGeo = new THREE.TorusGeometry(0.8, 0.05, 16, 100, Math.PI);
        const handle = new THREE.Mesh(handleGeo, metalMat);
        handle.position.y = 2.0;
        lanternGroup.add(handle);

        // --- The Galaxy ---
        const galaxyGroup = new THREE.Group();
        lanternGroup.add(galaxyGroup);

        const parameters = {
            count: 5000,
            size: 0.015,
            radius: 1.0,
            branches: 3,
            spin: 1,
            randomness: 0.5,
            randomnessPower: 3,
            insideColor: '#ff6030',
            outsideColor: '#1b3984'
        };

        let geometry = null;
        let material = null;
        let points = null;

        const generateGalaxy = () => {
            if (points !== null) {
                geometry.dispose();
                material.dispose();
                galaxyGroup.remove(points);
            }

            geometry = new THREE.BufferGeometry();
            const positions = new Float32Array(parameters.count * 3);
            const colors = new Float32Array(parameters.count * 3);

            const colorInside = new THREE.Color(parameters.insideColor);
            const colorOutside = new THREE.Color(parameters.outsideColor);

            for (let i = 0; i < parameters.count; i++) {
                const i3 = i * 3;

                const radius = Math.random() * parameters.radius;
                const spinAngle = radius * parameters.spin;
                const branchAngle = (i % parameters.branches) / parameters.branches * Math.PI * 2;

                const randomX = Math.pow(Math.random(), parameters.randomnessPower) * (Math.random() < 0.5 ? 1 : -1) * parameters.randomness * radius;
                const randomY = Math.pow(Math.random(), parameters.randomnessPower) * (Math.random() < 0.5 ? 1 : -1) * parameters.randomness * radius * 0.5; // Flatter galaxy
                const randomZ = Math.pow(Math.random(), parameters.randomnessPower) * (Math.random() < 0.5 ? 1 : -1) * parameters.randomness * radius;

                positions[i3] = Math.cos(branchAngle + spinAngle) * radius + randomX;
                positions[i3 + 1] = randomY;
                positions[i3 + 2] = Math.sin(branchAngle + spinAngle) * radius + randomZ;

                const mixedColor = colorInside.clone();
                mixedColor.lerp(colorOutside, radius / parameters.radius);

                colors[i3] = mixedColor.r;
                colors[i3 + 1] = mixedColor.g;
                colors[i3 + 2] = mixedColor.b;
            }

            geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

            material = new THREE.PointsMaterial({
                size: parameters.size,
                sizeAttenuation: true,
                depthWrite: false,
                blending: THREE.AdditiveBlending,
                vertexColors: true
            });

            points = new THREE.Points(geometry, material);
            galaxyGroup.add(points);
        };

        generateGalaxy();

        // --- Lighting ---
        // The galaxy itself acts as a light source visually, but we add a point light for the lantern glass to react
        const galaxyLight = new THREE.PointLight(0xffaa00, 2, 5);
        galaxyGroup.add(galaxyLight);

        const ambientLight = new THREE.AmbientLight(0x404040, 0.5); // Soft white light
        scene.add(ambientLight);

        // --- Animation ---
        const clock = new THREE.Clock();

        const animate = () => {
            const elapsedTime = clock.getElapsedTime();

            // Rotate Galaxy
            galaxyGroup.rotation.y = elapsedTime * 0.1;

            // Subtle floating for the whole lantern
            lanternGroup.position.y = Math.sin(elapsedTime * 0.5) * 0.1;
            lanternGroup.rotation.y = Math.sin(elapsedTime * 0.2) * 0.1;

            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        };

        animate();

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
