<body>
    <div id="info">Mechanical Phoenix</div>

    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 1.0;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        const backLight = new THREE.DirectionalLight(0xffaa00, 2);
        backLight.position.set(-5, 5, -5);
        scene.add(backLight);

        // Materials
        const copperMaterial = new THREE.MeshStandardMaterial({
            color: 0xb87333,
            metalness: 0.9,
            roughness: 0.3,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x222222,
            metalness: 0.8,
            roughness: 0.5,
        });

        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.95,
            thickness: 0.5,
            ior: 1.5,
            clearcoat: 1,
            clearcoatRoughness: 0,
        });

        const glowMaterial = new THREE.MeshBasicMaterial({
            color: 0xffaa00,
            transparent: true,
            opacity: 0.8
        });

        // Phoenix Construction
        const phoenix = new THREE.Group();
        scene.add(phoenix);

        // 1. Body (Torso)
        const bodyGeo = new THREE.CylinderGeometry(0.8, 0.4, 3, 8);
        const body = new THREE.Mesh(bodyGeo, copperMaterial);
        body.rotation.x = Math.PI / 2;
        phoenix.add(body);

        // 2. Glass Core (Chest)
        const coreGeo = new THREE.SphereGeometry(0.6, 32, 32);
        const core = new THREE.Mesh(coreGeo, glassMaterial);
        core.position.set(0, 0, 0.5);
        phoenix.add(core);

        // Inner Glow
        const glowGeo = new THREE.SphereGeometry(0.3, 16, 16);
        const glow = new THREE.Mesh(glowGeo, glowMaterial);
        glow.position.set(0, 0, 0.5);
        phoenix.add(glow);

        // Core Light
        const coreLight = new THREE.PointLight(0xffaa00, 5, 5);
        coreLight.position.set(0, 0, 0.5);
        phoenix.add(coreLight);

        // 3. Head
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.5, 1.6);

        const headGeo = new THREE.SphereGeometry(0.4, 16, 16);
        const head = new THREE.Mesh(headGeo, copperMaterial);
        headGroup.add(head);

        const beakGeo = new THREE.ConeGeometry(0.1, 0.6, 8);
        const beak = new THREE.Mesh(beakGeo, copperMaterial);
        beak.rotation.x = Math.PI / 2;
        beak.position.set(0, -0.1, 0.5);
        headGroup.add(beak);

        // Eyes (Glass)
        const eyeGeo = new THREE.SphereGeometry(0.08, 16, 16);
        const leftEye = new THREE.Mesh(eyeGeo, glassMaterial);
        leftEye.position.set(0.2, 0.1, 0.2);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, glassMaterial);
        rightEye.position.set(-0.2, 0.1, 0.2);
        headGroup.add(rightEye);

        phoenix.add(headGroup);

        // 4. Wings
        function createWing(side) {
            const wingGroup = new THREE.Group();
            wingGroup.position.set(side * 0.8, 0, 0);

            // Main Spar
            const sparGeo = new THREE.BoxGeometry(0.1, 0.1, 3);
            const spar = new THREE.Mesh(sparGeo, darkMetalMaterial);
            spar.position.z = 1.5;
            wingGroup.add(spar);

            // Feathers (Mechanical Plates)
            for(let i=0; i<5; i++) {
                const featherGeo = new THREE.BoxGeometry(0.8, 0.05, 1.2);
                const feather = new THREE.Mesh(featherGeo, copperMaterial);
                feather.position.set(side * (0.5 + i * 0.1), 0, 1 + i * 0.6);
                feather.rotation.y = side * (0.2 + i * 0.1);
                feather.rotation.z = side * 0.2;
                wingGroup.add(feather);

                // Joints
                const jointGeo = new THREE.TorusGeometry(0.15, 0.05, 8, 16);
                const joint = new THREE.Mesh(jointGeo, darkMetalMaterial);
                joint.position.set(side * 0.5, 0, 1 + i * 0.6);
                joint.rotation.y = Math.PI / 2;
                wingGroup.add(joint);
            }

            return wingGroup;
        }

        const leftWing = createWing(-1);
        const rightWing = createWing(1);
        phoenix.add(leftWing);
        phoenix.add(rightWing);

        // 5. Tail
        const tailGroup = new THREE.Group();
        tailGroup.position.set(0, 0, -1.5);

        for(let i=0; i<3; i++) {
            const tailGeo = new THREE.ConeGeometry(0.2 - (i*0.05), 2, 8);
            const tailFeather = new THREE.Mesh(tailGeo, copperMaterial);
            tailFeather.rotation.x = -Math.PI / 2;
            tailFeather.position.set((i-1)*0.3, 0, -1 - (i*0.5));
            tailGroup.add(tailFeather);
        }
        phoenix.add(tailGroup);

        // 6. Mechanical Details (Gears/Pipes)
        const gearGeo = new THREE.TorusGeometry(0.3, 0.05, 8, 16);
        const gear1 = new THREE.Mesh(gearGeo, darkMetalMaterial);
        gear1.position.set(0.5, 0, 0);
        phoenix.add(gear1);

        const gear2 = new THREE.Mesh(gearGeo, darkMetalMaterial);
        gear2.position.set(-0.5, 0, 0);
        gear2.rotation.y = Math.PI / 4;
        phoenix.add(gear2);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Floating motion
            phoenix.position.y = Math.sin(time * 0.5) * 0.5;
            phoenix.rotation.z = Math.sin(time * 0.3) * 0.05;

            // Wing flapping
            leftWing.rotation.z = Math.sin(time * 2) * 0.2 + 0.2;
            rightWing.rotation.z = -(Math.sin(time * 2) * 0.2 + 0.2);

            // Head bobbing
            headGroup.rotation.x = Math.sin(time * 1.5) * 0.1;

            // Gear rotation
            gear1.rotation.z = time;
            gear2.rotation.z = -time;

            // Core pulsing
            coreLight.intensity = 5 + Math.sin(time * 5) * 2;
            glow.scale.setScalar(1 + Math.sin(time * 5) * 0.1);

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
