    neck.position.set(1.8, 3.8, 0);
    neck.rotation.z = -Math.PI / 3;
    stagGroup.add(neck);

    // Head
    const headGeo = new THREE.SphereGeometry(0.7, 16, 16);
    const head = new THREE.Mesh(headGeo, crystalMaterial);
    head.position.set(2.5, 4.8, 0);
    head.scale.set(1.3, 0.9, 0.9);
    stagGroup.add(head);

    // Antlers
    function createAntler(startPos, direction, length, radius) {
        const geo = new THREE.CylinderGeometry(radius * 0.5, radius, length, 6);
        const mesh = new THREE.Mesh(geo, crystalMaterial);
        mesh.position.copy(startPos);
        mesh.lookAt(startPos.clone().add(direction));
        mesh.rotateX(Math.PI / 2);
        return mesh;
    }

    // Main stems
    const leftStem = createAntler(new THREE.Vector3(2.5, 5.2, 0.4), new THREE.Vector3(0, 1, 0.5), 2.0, 0.12);
    const rightStem = createAntler(new THREE.Vector3(2.5, 5.2, -0.4), new THREE.Vector3(0, 1, -0.5), 2.0, 0.12);
    stagGroup.add(leftStem, rightStem);

    // Tines
    const tine1 = createAntler(new THREE.Vector3(2.5, 6.0, 0.6), new THREE.Vector3(0.5, 0.5, 0.5), 1.0, 0.08);
    const tine2 = createAntler(new THREE.Vector3(2.5, 6.0, -0.6), new THREE.Vector3(0.5, 0.5, -0.5), 1.0, 0.08);
    const tine3 = createAntler(new THREE.Vector3(2.5, 6.5, 0.8), new THREE.Vector3(0.2, 0.8, 0.2), 0.8, 0.06);
    const tine4 = createAntler(new THREE.Vector3(2.5, 6.5, -0.8), new THREE.Vector3(0.2, 0.8, -0.2), 0.8, 0.06);
    stagGroup.add(tine1, tine2, tine3, tine4);

    scene.add(stagGroup);

    // Animation
    const clock = new THREE.Clock();

    function animate() {
        requestAnimationFrame(animate);

        const time = clock.getElapsedTime();

        // Rotate stag slowly
        stagGroup.rotation.y = Math.sin(time * 0.2) * 0.5;

        // Bobbing motion
        stagGroup.position.y = Math.sin(time * 0.5) * 0.3;

        // Animate water vertices for waves
        const positionAttribute = waterGeometry.attributes.position;
        for ( let i = 0; i < positionAttribute.count; i ++ ) {
            const x = positionAttribute.getX( i );
            const y = positionAttribute.getY( i ); // This is actually Z in world space due to rotation
            // Simple sine wave
            const z = Math.sin( x * 0.5 + time ) * 0.5 + Math.cos( y * 0.5 + time ) * 0.5;
            positionAttribute.setZ( i, z );
        }
        positionAttribute.needsUpdate = true;
        waterGeometry.computeVertexNormals();

        renderer.render(scene, camera);
    }
    animate();

    // Resize handler
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
</script>
</body>
</html>
