```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Glowing Bonsai with Firefly Leaves</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #000; overflow: hidden; }
canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.163.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.163.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

// ── Scene Setup ──
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x020510);
scene.fog = new THREE.FogExp2(0x020510, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 3, 8);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxDistance = 15;
controls.minDistance = 3;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.4;

// ── Post Processing (Bloom) ──
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(
  new THREE.Vector2(innerWidth, innerHeight), 1.5, 0.4, 0.85
);
bloom.threshold = 0.1;
bloom.strength = 1.8;
bloom.radius = 0.6;
composer.addPass(bloom);

// ── Environment ──
const ambientLight = new THREE.AmbientLight(0x112233, 0.3);
scene.add(ambientLight);

// ── Materials ──
const trunkMat = new THREE.MeshStandardMaterial({
  color: 0x3a2518,
  roughness: 0.95,
  metalness: 0.0,
});

const potMat = new THREE.MeshStandardMaterial({
  color: 0x5a3a2a,
  roughness: 0.8,
  metalness: 0.1,
});

const soilMat = new THREE.MeshStandardMaterial({
  color: 0x1a0e08,
  roughness: 1.0,
});

const fireflyColors = [
  0x44ff88, 0x88ff44, 0xaaff22, 0x66ffaa,
  0x22ffcc, 0x88ff00, 0x00ffaa, 0xccff44,
  0x55ff77, 0x33ee99, 0xffcc00, 0x88ff66,
];

// ── Bonsai Pot ──
const potGeo = new THREE.CylinderGeometry(1.4, 1.1, 0.6, 32);
const pot = new THREE.Mesh(potGeo, potMat);
pot.position.y = 0.3;
scene.add(pot);

const potRim = new THREE.Mesh(
  new THREE.TorusGeometry(1.4, 0.06, 8, 32),
  potMat
);
potRim.rotation.x = Math.PI / 2;
potRim.position.y = 0.6;
scene.add(potRim);

const soilGeo = new THREE.CylinderGeometry(1.3, 1.3, 0.08, 32);
const soil = new THREE.Mesh(soilGeo, soilMat);
soil.position.y = 0.58;
scene.add(soil);

// ── Recursive Bonsai Builder ──
const fireflyMeshes = [];
const fireflyLights = [];
const branchEnds = [];

function createBranch(origin, direction, length, radius, depth) {
  if (depth <= 0 || radius < 0.015) return;

  const curve = new THREE.CatmullRomCurve3([
    origin.clone(),
    origin.clone().add(direction.clone().multiplyScalar(length * 0.45))
      .add(new THREE.Vector3(
        (Math.random() - 0.5) * length * 0.3,
        (Math.random() - 0.5) * length * 0.1,
        (Math.random() - 0.5) * length * 0.3
      )),
    origin.clone().add(direction.clone().multiplyScalar(length))
  ]);

  const tubeGeo = new THREE.TubeGeometry(curve, 8, radius, 6, false);
  const branch = new THREE.Mesh(tubeGeo, trunkMat);
  scene.add(branch);

  const endPos = curve.getPointAt(1);

  if (depth <= 2) {
    branchEnds.push(endPos.clone());
  }

  if (depth > 1) {
    const numBranches = depth > 3 ? 3 : 2;
    for (let i = 0; i < numBranches; i++) {
      const newDir = direction.clone();
      const angle = (Math.PI * 0.35 + Math.random() * 0.3) * (i % 2 === 0 ? 1 : -1);
      const axis = new THREE.Vector3(
        Math.random() - 0.5,
        Math.random() * 0.3,
        Math.random() - 0.5
      ).normalize();
      newDir.applyAxisAngle(axis, angle);
      newDir.y += 0.15;
      newDir.normalize();

      const newLength = length * (0.65 + Math.random() * 0.15);
      const newRadius = radius * (0.55 + Math.random() * 0.1);
      createBranch(endPos, newDir, newLength, newRadius, depth - 1);
    }
  }
}

// ── Build Tree ──
const trunkDir = new THREE.Vector3(0, 1, 0);
createBranch(
  new THREE.Vector3(0, 0.6, 0),
  trunkDir,
  2.2, 0.18, 6
);

// Add a secondary trunk for asymmetry
createBranch(
  new THREE.Vector3(0.1, 0.6, 0),
  new THREE.Vector3(0.15, 1, -0.05).normalize(),
  1.6, 0.1, 5
);

// ── Firefly Leaves ──
function createFirefly(position) {
  const cluster = 1 + Math.floor(Math.random() * 4);
  for (let i = 0; i < cluster; i++) {
    const size = 0.03 + Math.random() * 0.06;
    const geo = new THREE.SphereGeometry(size, 8, 8);
    const color = fireflyColors[Math.floor(Math.random() * fireflyColors.length)];
    const mat = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: new THREE.Color(color),
      emissiveIntensity: 0,
      transparent: true,
      opacity: 0.9,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position).add(
      new THREE.Vector3(
        (Math.random() - 0.5) * 0.4,
        (Math.random() - 0.5) * 0.3,
        (Math.random() - 0.5) * 0.4
      )
    );
    scene.add(mesh);

    const light = new THREE.PointLight(color, 0, 1.5, 2);
    light.position.copy(mesh.position);
    scene.add(light);

    fireflyMeshes.push({
      mesh,
      light,
      phase: Math.random() * Math.PI * 2,
      speed: 0.5 + Math.random() * 2.5,
      baseIntensity: 0.8 + Math.random() * 1.5,
      floatOffset: Math.random() * Math.PI * 2,
      floatSpeed: 0.3 + Math.random() * 0.7,
      floatRadius: 0.02 + Math.random() * 0.06,
      basePos: mesh.position.clone(),
    });
  }
}

branchEnds.forEach(pos => createFirefly(pos));

// ── Floating Ambient Fireflies ──
for (let i = 0; i < 40; i++) {
  const size = 0.01 + Math.random() * 0.025;
  const geo = new THREE.SphereGeometry(size, 6, 6);
  const color = fireflyColors[Math.floor(Math.random() * fireflyColors.length)];
  const mat = new THREE.MeshStandardMaterial({
    color: 0x000000,
    emissive: new THREE.Color(color),
    emissiveIntensity: 0,
    transparent: true,
    opacity: 0.7,
  });
  const mesh = new THREE.Mesh(geo, mat);
  const angle = Math.random() * Math.PI * 2;
  const r = 0.5 + Math.random() * 3.5;
  mesh.position.set(
    Math.cos(angle) * r,
    1 + Math.random() * 4,
    Math.sin(angle) * r
  );
  scene.add(mesh);

  fireflyMeshes.push({
    mesh,
    light: null,
    phase: Math.random() * Math.PI * 2,
    speed: 0.3 + Math.random() * 1.5,
    baseIntensity: 0.3 + Math.random() * 0.8,
    floatOffset: Math.random() * Math.PI * 2,
    floatSpeed: 0.2 + Math.random() * 0.5,
    floatRadius: 0.05 + Math.random() * 0.15,
    basePos: mesh.position.clone(),
    orbitRadius: r,
    orbitAngle: angle,
    orbitSpeed: (Math.random() - 0.5) * 0.15,
  });
}

// ── Ground Plane ──
const groundGeo = new THREE.CircleGeometry(8, 48);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x050a05,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = 0.01;
scene.add(ground);

// ── Moss Patches ──
for (let i = 0; i < 12; i++) {
  const mossGeo = new THREE.SphereGeometry(
    0.1 + Math.random() * 0.15, 6, 6
  );
  const mossMat = new THREE.MeshStandardMaterial({
    color: 0x1a3a1a,
    roughness: 1,
    emissive: 0x0a1a0a,
    emissiveIntensity: 0.1,
  });
  const moss = new THREE.Mesh(mossGeo, mossMat);
  const a = Math.random() * Math.PI * 2;
  const r = 0.3 + Math.random() * 1.0;
  moss.position.set(Math.cos(a) * r, 0.6, Math.sin(a) * r);
  moss.scale.y = 0.3;
  scene.add(moss);
}

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  fireflyMeshes.forEach(f => {
    // Pulsing glow
    const pulse = (Math.sin(t * f.speed + f.phase) * 0.5 + 0.5);
    const intensity = pulse * f.baseIntensity;
    f.mesh.material.emissiveIntensity = intensity;

    if (f.light) {
      f.light.intensity = intensity * 0.6;
    }

    // Gentle floating
    f.mesh.position.x = f.basePos.x +
      Math.sin(t * f.floatSpeed + f.floatOffset) * f.floatRadius;
    f.mesh.position.y = f.basePos.y +
      Math.sin(t * f.floatSpeed * 0.7 + f.floatOffset + 1) * f.floatRadius * 0.5;
    f.mesh.position.z = f.basePos.z +
      Math.cos(t * f.floatSpeed * 0.8 + f.floatOffset + 2) * f.floatRadius;

    // Orbital motion for ambient fireflies
    if (f.orbitSpeed !== undefined) {
      f.orbitAngle += f.orbitSpeed * 0.01;
      f.mesh.position.x = Math.cos(f.orbitAngle) * f.orbitRadius +
        Math.sin(t * f.floatSpeed + f.floatOffset) * f.floatRadius;
      f.mesh.position.z = Math.sin(f.orbitAngle) * f.orbitRadius +
        Math.cos(t * f.floatSpeed * 0.8 + f.floatOffset + 2) * f.floatRadius;
    }
  });

  controls.update();
  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
