bloom.strength = 1.4;
bloom.radius = 0.6;
composer.addPass(bloom);

// ── Lighting ──
const ambient = new THREE.AmbientLight(0x1a2a4a, 0.8);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffeedd, 2.5);
keyLight.position.set(5, 8, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x4488ff, 1.0);
fillLight.position.set(-5, 3, -5);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff6633, 2, 20);
rimLight.position.set(0, -3, -5);
scene.add(rimLight);

// ── Materials ──
const goldMat = new THREE.MeshStandardMaterial({
  color: 0xd4a843, metalness: 0.9, roughness: 0.15,
  emissive: 0x332200, emissiveIntensity: 0.3
});
const silverMat = new THREE.MeshStandardMaterial({
  color: 0xaabbcc, metalness: 0.85, roughness: 0.2,
  emissive: 0x112233, emissiveIntensity: 0.2
});
const rubyMat = new THREE.MeshStandardMaterial({
  color: 0xcc2233, metalness: 0.3, roughness: 0.1,
  emissive: 0x660011, emissiveIntensity: 0.8
});
const sapphireMat = new THREE.MeshStandardMaterial({
  color: 0x2244aa, metalness: 0.3, roughness: 0.1,
  emissive: 0x112266, emissiveIntensity: 0.8
});

// ── Compass Point Shape ──
function createPointShape(length, width) {
  const shape = new THREE.Shape();
  shape.moveTo(0, length);
  shape.lineTo(width * 0.15, 0);
  shape.lineTo(0, -length * 0.15);
  shape.lineTo(-width * 0.15, 0);
  shape.closePath();
  return shape;
}

function createLongPointShape(length, width) {
  const shape = new THREE.Shape();
  shape.moveTo(0, length);
  shape.quadraticCurveTo(width * 0.3, length * 0.5, width * 0.2, 0);
  shape.lineTo(0, -length * 0.2);
  shape.lineTo(-width * 0.2, 0);
  shape.quadraticCurveTo(-width * 0.3, length * 0.5, 0, length);
  shape.closePath();
  return shape;
}

const extrudeSettings = { depth: 0.08, bevelEnabled: true, bevelThickness: 0.03, bevelSize: 0.03, bevelSegments: 3 };

// ── Build Compass Group ──
const compassGroup = new THREE.Group();
scene.add(compassGroup);

// Central sphere
const centerGeo = new THREE.IcosahedronGeometry(0.35, 2);
const centerSphere = new THREE.Mesh(centerGeo, rubyMat);
compassGroup.add(centerSphere);

// Inner ring
const innerRingGeo = new THREE.TorusGeometry(0.55, 0.03, 16, 64);
const innerRing = new THREE.Mesh(innerRingGeo, goldMat);
compassGroup.add(innerRing);

// Outer ring
const outerRingGeo = new THREE.TorusGeometry(2.8, 0.04, 16, 128);
const outerRing = new THREE.Mesh(outerRingGeo, silverMat);
compassGroup.add(outerRing);

// Second decorative ring
const midRingGeo = new THREE.TorusGeometry(1.6, 0.025, 16, 96);
const midRing = new THREE.Mesh(midRingGeo, goldMat);
compassGroup.add(midRing);

// ── Cardinal Points (N, S, E, W) ──
const cardinalLength = 3.2;
const cardinalWidth = 0.7;
const cardinalShape = createLongPointShape(cardinalLength, cardinalWidth);

for (let i = 0; i < 4; i++) {
  const angle = (i * Math.PI) / 2;
  const geo = new THREE.ExtrudeGeometry(cardinalShape, extrudeSettings);
  geo.center();
  const mesh = new THREE.Mesh(geo, i % 2 === 0 ? goldMat : silverMat);
  mesh.rotation.z = angle;
  compassGroup.add(mesh);
}

// ── Ordinal Points (NE, SE, SW, NW) ──
const ordinalLength = 2.2;
const ordinalWidth = 0.5;
const ordinalShape = createPointShape(ordinalLength, ordinalWidth);

for (let i = 0; i < 4; i++) {
  const angle = (i * Math.PI) / 2 + Math.PI / 4;
  const geo = new THREE.ExtrudeGeometry(ordinalShape, extrudeSettings);
  geo.center();
  const mesh = new THREE.Mesh(geo, i % 2 === 0 ? silverMat : goldMat);
  mesh.rotation.z = angle;
  compassGroup.add(mesh);
}

// ── Sub-direction pointers (16 total) ──
const subLength = 1.4;
const subWidth = 0.3;
const subShape = createPointShape(subLength, subWidth);
const subMat = new THREE.MeshStandardMaterial({
  color: 0x8899aa, metalness: 0.7, roughness: 0.3,
  emissive: 0x223344, emissiveIntensity: 0.3
});

for (let i = 0; i < 8; i++) {
  const angle = (i * Math.PI) / 4 + Math.PI / 8;
  const geo = new THREE.ExtrudeGeometry(subShape, { ...extrudeSettings, depth: 0.05, bevelThickness: 0.02, bevelSize: 0.02 });
  geo.center();
  const mesh = new THREE.Mesh(geo, subMat);
  mesh.rotation.z = angle;
  compassGroup.add(mesh);
}

// ── Direction Labels as Small Spheres at Tips ──
const tipPositions = [];
const directions = ['N','NE','E','SE','S','SW','W','NW'];

for (let i = 0; i < 8; i++) {
  const angle = (i * Math.PI) / 4;
  const r = i % 2 === 0 ? cardinalLength * 0.7 : ordinalLength * 0.7;
  const x = Math.sin(angle) * r;
  const y = Math.cos(angle) * r;
  tipPositions.push(new THREE.Vector3(x, y, 0));

  const tipGeo = new THREE.SphereGeometry(i % 2 === 0 ? 0.08 : 0.06, 16, 16);
  const tipMat = i % 2 === 0 ? rubyMat : sapphireMat;
  const tip = new THREE.Mesh(tipGeo, tipMat);
  tip.position.set(x, y, 0);
  compassGroup.add(tip);
}

// ── Decorative Tick Marks on Outer Ring ──
for (let i = 0; i < 32; i++) {
  const angle = (i * Math.PI) / 16;
  const isMajor = i % 4 === 0;
  const isMinor = i % 2 === 0;
  const tickLen = isMajor ? 0.15 : isMinor ? 0.08 : 0.04;
  const tickW = isMajor ? 0.04 : 0.02;

  const tickShape = new THREE.Shape();
  tickShape.moveTo(0, tickLen);
  tickShape.lineTo(tickW, 0);
  tickShape.lineTo(-tickW, 0);
  tickShape.closePath();

  const tickGeo = new THREE.ExtrudeGeometry(tickShape, { depth: 0.03, bevelEnabled: false });
  const tick = new THREE.Mesh(tickGeo, isMajor ? goldMat : subMat);
  tick.rotation.z = angle;
  tick.position.set(0, 2.8, 0);
  compassGroup.add(tick);
}

// ── Floating Particles ──
const particleCount = 600;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 3 + Math.random() * 8;
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  positions[i * 3 + 2] = r * Math.cos(phi);
  sizes[i] = Math.random() * 2 + 0.5;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0x6688cc, size: 0.04, transparent: true, opacity: 0.6,
  blending: THREE.AdditiveBlending, sizeAttenuation: true
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// ── Starfield Background ──
const starCount = 1500;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount; i++) {
  const r = 20 + Math.random() * 30;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  starPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  starPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  starPos[i * 3 + 2] = r * Math.cos(phi);
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff, size: 0.06, transparent: true, opacity: 0.8
});
scene.add(new THREE.Points(starGeo, starMat));

// ── Animation ──
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Float up and down
  compassGroup.position.y = Math.sin(t * 0.5) * 0.3;

  // Gentle wobble
  compassGroup.rotation.x = Math.sin(t * 0.3) * 0.05;
  compassGroup.rotation.z = Math.cos(t * 0.2) * 0.03;

  // Slow Y rotation (the "all directions" spin)
  compassGroup.rotation.y = t * 0.15;

  // Pulse the center
  const pulse = 1 + Math.sin(t * 2) * 0.1;
  centerSphere.scale.setScalar(pulse);

  // Rotate rings at different speeds
  innerRing.rotation.z = t * 0.3;
  midRing.rotation.z = -t * 0.15;
  outerRing.rotation.z = t * 0.08;

  // Particles drift
  particles.rotation.y = t * 0.02;
  particles.rotation.x = t * 0.01;

  // Rim light orbit
  rimLight.position.x = Math.sin(t * 0.7) * 6;
  rimLight.position.z = Math.cos(t * 0.7) * 6;

  controls.update();
  composer.render();
}

animate();

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

