</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050510);
scene.fog = new THREE.FogExp2(0x050510, 0.035);

const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 4, 10);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 2, 0);

// --- Environment for reflections ---
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0x1a1a3a, 0.5);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffeedd, 3);
keyLight.position.set(5, 8, 5);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x4488ff, 1.5);
fillLight.position.set(-5, 3, -3);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xff4488, 1.5);
rimLight.position.set(0, -2, -5);
scene.add(rimLight);

const gemLight = new THREE.PointLight(0x8844ff, 8, 8);
gemLight.position.set(0, 2, 0);
scene.add(gemLight);

const gemLight2 = new THREE.PointLight(0x4488ff, 5, 6);
gemLight2.position.set(0, 1, 0);
scene.add(gemLight2);

// --- Crystal Material ---
function crystalMaterial(color, opacity = 0.35) {
  return new THREE.MeshPhysicalMaterial({
    color,
    metalness: 0.1,
    roughness: 0.05,
    transmission: 0.92,
    thickness: 1.5,
    ior: 2.4,
    clearcoat: 1.0,
    clearcoatRoughness: 0.0,
    envMapIntensity: 2.0,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    flatShading: true,
    attenuationColor: new THREE.Color(color).multiplyScalar(0.6),
    attenuationDistance: 2,
    specularIntensity: 1,
    specularColor: new THREE.Color(0xffffff),
  });
}

// --- Central Gem ---
function createGem() {
  const group = new THREE.Group();

  // Main gem body - elongated octahedron shape
  const gemGeo = new THREE.IcosahedronGeometry(1, 0);
  // Stretch vertices to make it more gem-like
  const pos = gemGeo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const y = pos.getY(i);
    pos.setY(i, y * 1.6);
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const len = Math.sqrt(x * x + z * z);
    if (len > 0.01) {
      const scale = 0.85 + 0.15 * Math.sin(Math.atan2(z, x) * 3);
      pos.setX(i, x * scale);
      pos.getZ(i, z * scale);
    }
  }
  gemGeo.computeVertexNormals();

  const gemMat = crystalMaterial(0x6644ff, 0.5);
  const gem = new THREE.Mesh(gemGeo, gemMat);
  gem.position.y = 2.2;
  group.add(gem);

  // Inner glow sphere
  const glowGeo = new THREE.IcosahedronGeometry(0.5, 1);
  const glowMat = new THREE.MeshBasicMaterial({
    color: 0x8866ff,
    transparent: true,
    opacity: 0.6,
  });
  const glow = new THREE.Mesh(glowGeo, glowMat);
  glow.position.y = 2.2;
  group.add(glow);

  // Gem pedestal / base
  const baseGeo = new THREE.CylinderGeometry(1.2, 1.5, 0.3, 6);
  const baseMat = crystalMaterial(0x332266, 0.6);
  const base = new THREE.Mesh(baseGeo, baseMat);
  base.position.y = 0.8;
  group.add(base);

  return group;
}

// --- Dragon ---
function createDragon() {
  const group = new THREE.Group();

  // Coiled body path - spiral around the gem
  const bodyPoints = [];
  const coils = 2.5;
  const segments = 80;
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const angle = t * Math.PI * 2 * coils;
    const radius = 2.8 + t * 1.2;
    const y = 0.5 + t * 5.5;
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    bodyPoints.push(new THREE.Vector3(x, y, z));
  }

  const bodyCurve = new THREE.CatmullRomCurve3(bodyPoints);

  // Body tube with varying radius
  const bodyRadii = [];
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const r = 0.35 + Math.sin(t * Math.PI) * 0.25;
    bodyRadii.push(r);
  }

  const bodyGeo = new THREE.TubeGeometry(bodyCurve, segments, 0.4, 5, false);
  // Flatten the tube to make it more dragon-like
  const bodyPos = bodyGeo.attributes.position;
  for (let i = 0; i < bodyPos.count; i++) {
    const x = bodyPos.getX(i);
    const y = bodyPos.getY(i);
    const z = bodyPos.getZ(i);
    bodyPos.setY(i, y * 0.6);
    bodyPos.setZ(i, z * 0.75);
  }
  bodyGeo.computeVertexNormals();

  const dragonMat = crystalMaterial(0x22aadd, 0.3);
  const body = new THREE.Mesh(bodyGeo, dragonMat);
  group.add(body);

  // Scales / facet rings along body
  for (let i = 0; i < 20; i++) {
    const t = i / 20;
    const pos = bodyCurve.getPointAt(t);
    const tangent = bodyCurve.getTangentAt(t);
    const normal = new THREE.Vector3(0, 1, 0);
    const binormal = new THREE.Vector3().crossVectors(tangent, normal).normalize();

    const scaleGeo = new THREE.OctahedronGeometry(0.25 + Math.sin(t * Math.PI) * 0.15, 0);
    const scale = new THREE.Mesh(scaleGeo, crystalMaterial(0x44bbdd, 0.25));
    scale.position.copy(pos);
    scale.position.y += 0.2;
    scale.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
    group.add(scale);
  }

  // --- Head ---
  const headGroup = new THREE.Group();

  // Main head shape
  const headGeo = new THREE.DodecahedronGeometry(0.7, 0);
  const headPos = headGeo.attributes.position;
  for (let i = 0; i < headPos.count; i++) {
    const x = headPos.getX(i);
    const y = headPos.getY(i);
    const z = headPos.getZ(i);
    // Elongate into snout shape
    if (z > 0) {
      headPos.setZ(i, z * 1.8);
      headPos.setX(i, x * 0.7);
    }
    headPos.setY(i, y * 0.8);
  }
  headGeo.computeVertexNormals();
  const head = new THREE.Mesh(headGeo, crystalMaterial(0x33ccdd, 0.3));
  headGroup.add(head);

  // Eyes
  const eyeGeo = new THREE.IcosahedronGeometry(0.12, 0);
  const eyeMat = new THREE.MeshPhysicalMaterial({
    color: 0xffdd44,
    emissive: 0xffaa00,
    emissiveIntensity: 2,
    roughness: 0.2,
    metalness: 0.8,
    flatShading: true,
  });
  const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
  leftEye.position.set(-0.35, 0.15, 0.5);
  headGroup.add(leftEye);
  const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
  rightEye.position.set(0.35, 0.15, 0.5);
  headGroup.add(rightEye);

  // Horns
  for (let side of [-1, 1]) {
    const hornGeo = new THREE.ConeGeometry(0.08, 0.8, 4);
    const horn = new THREE.Mesh(hornGeo, crystalMaterial(0x66eeff, 0.35));
    horn.position.set(side * 0.3, 0.6, -0.1);
    horn.rotation.z = side * -0.4;
    horn.rotation.x = -0.3;
    headGroup.add(horn);
  }

  // Position head at end of body
  const headPos3 = bodyCurve.getPointAt(1.0);
  const headTan = bodyCurve.getTangentAt(1.0);
  headGroup.position.copy(headPos3);
  headGroup.lookAt(headPos3.clone().add(headTan));
  headGroup.rotateX(Math.PI / 2);
  headGroup.position.y += 0.3;
  group.add(headGroup);

  // --- Wings ---
  for (let side of [-1, 1]) {
    const wingShape = new THREE.Shape();
    wingShape.moveTo(0, 0);
    wingShape.quadraticCurveTo(1.5, 2.5, 3.5, 1.5);
    wingShape.quadraticCurveTo(3.0, 1.0, 2.5, 0.5);
    wingShape.quadraticCurveTo(2.0, 1.5, 1.5, 1.0);
    wingShape.quadraticCurveTo(1.0, 1.5, 0.5, 1.0);
    wingShape.quadraticCurveTo(0.3, 0.5, 0, 0);

    const wingGeo = new THREE.ShapeGeometry(wingShape, 8);
    // Flatten and facet
    const wingPos = wingGeo.attributes.position;
    for (let i = 0; i < wingPos.count; i++) {
      wingPos.setY(i, wingPos.getY(i) * 0.3);
      wingPos.setZ(i, wingPos.getZ(i));
    }
    wingGeo.computeVertexNormals();

    const wingMat = crystalMaterial(0x22aacc, 0.2);
    const wing = new THREE.Mesh(wingGeo, wingMat);
    wing.position.set(side * 0.3, 3.5, 0);
    wing.rotation.y = side * 0.5;
    wing.rotation.x = -0.3;
    wing.scale.set(side, 1, 1);
    group.add(wing);

    // Wing membrane ribs
    const ribCount = 5;
    for (let r = 0; r < ribCount; r++) {
      const t = r / ribCount;
      const ribGeo = new THREE.CylinderGeometry(0.015, 0.015, 1.5 + t, 3);
      const rib = new THREE.Mesh(ribGeo, crystalMaterial(0x44ccdd, 0.3));
      rib.position.set(side * (0.5 + t * 1.5), 3.5 + t * 1.2, t * 1.5);
      rib.rotation.z = side * (0.5 + t * 0.8);
      group.add(rib);
    }
  }

