                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>
    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.target.set(0, 0, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 2);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 3);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        const spotLight = new THREE.SpotLight(0x00ffcc, 5);
        spotLight.position.set(-5, 5, 0);
        spotLight.lookAt(0, 0, 0);
        scene.add(spotLight);

        // Materials
        const metalMaterial = new THREE.MeshStandardMaterial({
            color: 0x2e8b57, // Sea green
            metalness: 0.8,
            roughness: 0.2,
        });

        const darkMetalMaterial = new THREE.MeshStandardMaterial({
            color: 0x1a1a1a,
            metalness: 0.9,
            roughness: 0.4,
        });

        const glassMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0,
            roughness: 0,
            transmission: 0.95, // Glass-like
            thickness: 0.5,
            ior: 1.5,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide
        });

        // --- The Leaf of Glass ---
        const leafGroup = new THREE.Group();

        // Create a curved plane for the leaf
        const leafGeo = new THREE.PlaneGeometry(6, 12, 20, 40);
        const posAttribute = leafGeo.attributes.position;
        for (let i = 0; i < posAttribute.count; i++) {
            const x = posAttribute.getX(i);
            const y = posAttribute.getY(i);
            // Curve it like a leaf
            const z = -Math.pow(Math.abs(x) / 3, 2) * 2 - Math.pow(y / 6, 2) * 1; 
            posAttribute.setZ(i, z);
        }
        leafGeo.computeVertexNormals();

        const leaf = new THREE.Mesh(leafGeo, glassMaterial);
        leaf.rotation.x = -Math.PI / 2;
        leaf.position.y = -0.5;
        leaf.receiveShadow = true;
        leafGroup.add(leaf);

        // Add a stem
        const stemGeo = new THREE.CylinderGeometry(0.1, 0.1, 4, 8);
        const stem = new THREE.Mesh(stemGeo, glassMaterial);
        stem.position.y = -2.5;
        stem.position.z = 0;
        leafGroup.add(stem);

        scene.add(leafGroup);

        // --- The Mechanical Mantis ---
        const mantisGroup = new THREE.Group();

        // Helper to create limb segments
        function createLimb(length, radius, material) {
            const geo = new THREE.CylinderGeometry(radius, radius * 0.8, length, 8);
            geo.translate(0, length / 2, 0);
            const mesh = new THREE.Mesh(geo, material);
            mesh.castShadow = true;
            return mesh;
        }

        function createJoint(radius, material) {
            const geo = new THREE.SphereGeometry(radius, 16, 16);
            const mesh = new THREE.Mesh(geo, material);
            mesh.castShadow = true;
            return mesh;
        }

        // Body Parts
        const abdomen = createLimb(2.5, 0.4, metalMaterial);
        abdomen.rotation.x = Math.PI / 2;
        abdomen.position.set(0, 0.5, -1.5);
        mantisGroup.add(abdomen);

        const thorax = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1.5), metalMaterial);
        thorax.position.set(0, 0.5, 0);
        thorax.castShadow = true;
        mantisGroup.add(thorax);

        const head = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.8, 0.8), metalMaterial);
        head.position.set(0, 1.2, 1.2);
        head.castShadow = true;
        mantisGroup.add(head);

        // Eyes
        const eyeGeo = new THREE.SphereGeometry(0.2, 16, 16);
        const eyeMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.5 });
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.4, 1.4, 1.5);
        mantisGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.4, 1.4, 1.5);
        mantisGroup.add(rightEye);

        // Antennae
        const antennaGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.5, 4);
        const leftAntenna = new THREE.Mesh(antennaGeo, darkMetalMaterial);
        leftAntenna.position.set(-0.2, 1.6, 1.6);
        leftAntenna.rotation.z = 0.5;
        leftAntenna.rotation.x = -0.5;
        mantisGroup.add(leftAntenna);
        const rightAntenna = new THREE.Mesh(antennaGeo, darkMetalMaterial);
        rightAntenna.position.set(0.2, 1.6, 1.6);
        rightAntenna.rotation.z = -0.5;
        rightAntenna.rotation.x = -0.5;
        mantisGroup.add(rightAntenna);

        // Legs Function
        function createLeg(isRaptorial = false) {
            const legGroup = new THREE.Group();

            if (isRaptorial) {
                // Raptorial Forelegs (The "praying" hands)
                const coxa = createLimb(0.5, 0.15, darkMetalMaterial);
                coxa.rotation.z = Math.PI / 2;
                legGroup.add(coxa);

                const femur = createLimb(1.5, 0.2, metalMaterial);
                femur.position.y = 0.5;
                femur.rotation.x = -Math.PI / 4;
                legGroup.add(femur);

                const tibia = createLimb(1.5, 0.15, metalMaterial);
                tibia.position.set(0, 1.5, -0.5); // Offset for joint
                tibia.rotation.x = Math.PI / 2; // Folded up
                legGroup.add(tibia);

                // Spikes on tibia
                for(let i=0; i<3; i++) {
                    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.3, 4), darkMetalMaterial);
                    spike.position.set(0, 0.3 + i*0.3, 0.15);
                    spike.rotation.x = Math.PI/2;
                    tibia.add(spike);
                }

                const tarsus = createLimb(0.5, 0.05, darkMetalMaterial);
                tarsus.position.set(0, 0, -1.5);
                tarsus.rotation.x = -Math.PI / 4;
                legGroup.add(tarsus);

                legGroup.position.set(0, 0.5, 0.5);
                legGroup.rotation.x = -Math.PI / 4; // Lift up
            } else {
                // Walking Legs
                const coxa = createLimb(0.5, 0.1, darkMetalMaterial);
                coxa.rotation.z = Math.PI / 2;
                legGroup.add(coxa);

                const femur = createLimb(1.2, 0.12, metalMaterial);
                femur.position.y = 0.5;
                femur.rotation.x = Math.PI / 4;
                legGroup.add(femur);

                const tibia = createLimb(1.2, 0.1, metalMaterial);
                tibia.position.set(0, 1.2, 0.5);
                tibia.rotation.x = -Math.PI / 4;
                legGroup.add(tibia);

                const tarsus = createLimb(0.6, 0.05, darkMetalMaterial);
                tarsus.position.set(0, 0, 1.2);
                tarsus.rotation.x = Math.PI / 4;
                legGroup.add(tarsus);
            }
            return legGroup;
        }

        // Add Legs
        // Front (Raptorial)
        const frontLegL = createLeg(true);
        frontLegL.position.set(-0.6, 0.5, 0.5);
        frontLegL.rotation.y = 0.2;
        mantisGroup.add(frontLegL);

        const frontLegR = createLeg(true);
        frontLegR.position.set(0.6, 0.5, 0.5);
        frontLegR.rotation.y = -0.2;
        mantisGroup.add(frontLegR);

        // Middle
        const midLegL = createLeg(false);
        midLegL.position.set(-0.6, 0.5, 0);
        midLegL.rotation.y = 0.5;
        mantisGroup.add(midLegL);

        const midLegR = createLeg(false);
        midLegR.position.set(0.6, 0.5, 0);
        midLegR.rotation.y = -0.5;
        mantisGroup.add(midLegR);

        // Back
        const backLegL = createLeg(false);
        backLegL.position.set(-0.6, 0.5, -0.5);
        backLegL.rotation.y = 0.8;
        mantisGroup.add(backLegL);

        const backLegR = createLeg(false);
        backLegR.position.set(0.6, 0.5, -0.5);
        backLegR.rotation.y = -0.8;
        mantisGroup.add(backLegR);

        // Position Mantis on Leaf
        mantisGroup.position.y = 0.2;
        mantisGroup.rotation.y = Math.PI; // Face camera
        scene.add(mantisGroup);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Subtle breathing/movement
            mantisGroup.position.y = 0.2 + Math.sin(time * 2) * 0.05;
            mantisGroup.rotation.z = Math.sin(time * 1.5) * 0.02;

            // Antenna twitch
            leftAntenna.rotation.z = 0.5 + Math.sin(time * 5) * 0.1;
            rightAntenna.rotation.z = -0.5 - Math.sin(time * 5) * 0.1;

            controls.update();
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
