<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Crystal Rose with Dew Drops</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #050505; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x020205);
        scene.fog = new THREE.FogExp2(0x020205, 0.02);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.2;
        document.body.appendChild(renderer.domElement);

        // Materials
        // Crystal Material for Rose
        const crystalMaterial = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 0.1,
            roughness: 0.05,
            transmission: 0.95, // Glass-like
            thickness: 1.5,
            ior: 1.5,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.5,
            side: THREE.DoubleSide
        });

        // Dew Drop Material (Glowing)
        const dewMaterial = new THREE.MeshPhysicalMaterial({
            color: 0x00ffff,
            emissive: 0x0088ff,
            emissiveIntensity: 2.0,
            roughness: 0.0,
            metalness: 0.0,
            transmission: 0.2,
            thickness: 0.5,
            clearcoat: 1.0
        });

        // Rose Group
        const roseGroup = new THREE.Group();
        scene.add(roseGroup);

        // Create Petals
        const petalGeo = new THREE.SphereGeometry(1, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
        // Flatten and shape the sphere to look like a petal
        petalGeo.scale(1, 0.1, 0.6); 

        const petalCount = 40;
        for (let i = 0; i < petalCount; i++) {
            const petal = new THREE.Mesh(petalGeo, crystalMaterial);

            // Fibonacci spiral arrangement for rose shape
            const angle = i * 137.5 * (Math.PI / 180); // Golden angle
            const r = 0.15 * Math.sqrt(i);

            petal.position.x = r * Math.cos(angle);
            petal.position.z = r * Math.sin(angle);
            petal.position.y = i * 0.05; // Stack upwards slightly

            // Orient petal outwards
            petal.rotation.y = -angle;
            petal.rotation.x = -0.5 - (i * 0.02); // Curl upwards

            // Scale petals based on position (outer petals larger)
            const scale = 0.5 + (i * 0.05);
            petal.scale.set(scale, scale, scale);

            roseGroup.add(petal);

            // Add Dew Drops
            if (i % 3 === 0 && i > 5) {
                const dropGeo = new THREE.SphereGeometry(0.08, 16, 16);
                const drop = new THREE.Mesh(dropGeo, dewMaterial);

                // Position drop on the petal surface
                drop.position.copy(petal.position);
                drop.position.y += 0.15 * scale; // Sit on top
                drop.position.x += (Math.random() - 0.5) * 0.2 * scale;
                drop.position.z += (Math.random() - 0.5) * 0.2 * scale;

                roseGroup.add(drop);
            }
        }

        // Stem
        const stemGeo = new THREE.CylinderGeometry(0.05, 0.08, 4, 16);
        const stemMat = new THREE.MeshStandardMaterial({ color: 0x224422, roughness: 0.8 });
        const stem = new THREE.Mesh(stemGeo, stemMat);
        stem.position.y = -2;
        roseGroup.add(stem);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 1);
        scene.add(ambientLight);

        // Main light source
        const mainLight = new THREE.PointLight(0xffffff, 100, 20);
        mainLight.position.set(2, 5, 2);
        scene.add(mainLight);

        // Colored rim lights for crystal refraction
        const light1 = new THREE.PointLight(0xff00ff, 50, 10);
        light1.position.set(-3, 2, -2);
        scene.add(light1);

        const light2 = new THREE.PointLight(0x00ffff, 50, 10);
        light2.position.set(3, 2, -2);
        scene.add(light2);

        // Animation
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Rotate the rose slowly
            roseGroup.rotation.y = time * 0.2;

            // Subtle floating motion
            roseGroup.position.y = Math.sin(time * 0.5) * 0.2;

            // Animate dew drops (pulsing light)
            roseGroup.children.forEach(child => {
                if (child.material === dewMaterial) {
                    child.material.emissiveIntensity = 1.5 + Math.sin(time * 3 + child.position.x * 10) * 0.5;
                }
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
