        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
        import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
        import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

        // Scene Setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x050505);
        scene.fog = new THREE.FogExp2(0x050505, 0.02);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 0, 12);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ReinhardToneMapping;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 1.0;

        // Nautilus Curve (Logarithmic Spiral)
        class NautilusCurve extends THREE.Curve {
            constructor(scale = 1) {
                super();
                this.scale = scale;
            }
            getPoint(t) {
                // t goes from 0 to 1
                // We want about 2.5 to 3 turns
                const angle = t * Math.PI * 6; 
                // Logarithmic spiral: r = a * e^(b*theta)
                const a = 0.1;
                const b = 0.15;
                const r = a * Math.exp(b * angle) * this.scale;

                const x = r * Math.cos(angle);
                const y = r * Math.sin(angle);
                // Add a slight Z curve to give it 3D volume/depth like a real shell
                const z = Math.sin(angle * 0.5) * 0.2; 

                return new THREE.Vector3(x, y, z);
            }
        }

        const curve = new NautilusCurve(1.5);

        // Create Tube Geometry
        // tubularSegments: 200, radius: 0.15, radialSegments: 12
        const tubeGeometry = new THREE.TubeGeometry(curve, 200, 0.15, 12, false);

        // Modify geometry to make the tube radius grow (like a shell)
        const positionAttribute = tubeGeometry.attributes.position;
        const vertex = new THREE.Vector3();
        const center = new THREE.Vector3();
        const radialSegments = 12;
        const tubularSegments = 200;

        for (let i = 0; i <= tubularSegments; i++) {
            // Get the center point of this ring on the curve
            const t = i / tubularSegments;
            center.copy(curve.getPoint(t));

            // Calculate a growth factor for this ring
            // Exponential growth to match the spiral
            const growthFactor = 1.0 + (Math.exp(0.5 * t * Math.PI * 6) - 1) * 0.05;

            for (let j = 0; j <= radialSegments; j++) {
                const index = (i * (radialSegments + 1) + j);

                vertex.fromBufferAttribute(positionAttribute, index);

                // Vector from center to vertex
                const dx = vertex.x - center.x;
                const dy = vertex.y - center.y;
                const dz = vertex.z - center.z;

                // Scale the vector
                vertex.x = center.x + dx * growthFactor;
                vertex.y = center.y + dy * growthFactor;
                vertex.z = center.z + dz * growthFactor;

                positionAttribute.setXYZ(index, vertex.x, vertex.y, vertex.z);
            }
        }

        tubeGeometry.attributes.position.needsUpdate = true;
        tubeGeometry.computeVertexNormals();

        // Material
        const material = new THREE.MeshStandardMaterial({
            color: 0xffaa00,
            emissive: 0xff4400,
            emissiveIntensity: 2.0,
            roughness: 0.2,
            metalness: 0.8,
        });

        const shell = new THREE.Mesh(tubeGeometry, material);
        scene.add(shell);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040);
        scene.add(ambientLight);

        const pointLight = new THREE.PointLight(0xffaa00, 50, 100);
        pointLight.position.set(0, 0, 5);
        scene.add(pointLight);

        // Post Processing (Bloom)
        const renderScene = new RenderPass(scene, camera);

        const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 1.5, 0.4, 0.85);
        bloomPass.threshold = 0.1;
        bloomPass.strength = 2.5; // High strength for the glowing look
        bloomPass.radius = 0.5;

        const composer = new EffectComposer(renderer);
        composer.addPass(renderScene);
        composer.addPass(bloomPass);

        // Animation
        function animate() {
            requestAnimationFrame(animate);

            // Slow spin
            shell.rotation.z += 0.002;
            shell.rotation.x = Math.sin(Date.now() * 0.001) * 0.1; // Slight wobble

            controls.update();
            composer.render();
        }

        // Resize Handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
