            // Add some noise
            vertex.x += (Math.random() - 0.5) * 0.5;
            vertex.y += (Math.random() - 0.5) * 0.5;
            vertex.z += (Math.random() - 0.5) * 0.5;
            positionAttribute.setXYZ(i, vertex.x, vertex.y, vertex.z);
        }
        rockGeometry.computeVertexNormals();

        const rockMaterial = new THREE.MeshStandardMaterial({
            color: 0x1a1a24,
            roughness: 0.9,
            flatShading: true
        });
        const rock = new THREE.Mesh(rockGeometry, rockMaterial);
        rock.castShadow = true;
        rock.receiveShadow = true;
        islandGroup.add(rock);

        // Grass/Dirt Top Layer
        const topGeo = new THREE.CylinderGeometry(3.5, 3.5, 0.2, 8);
        const topMat = new THREE.MeshStandardMaterial({ color: 0x0a1a0a, roughness: 1 });
        const topMesh = new THREE.Mesh(topGeo, topMat);
        topMesh.position.y = 1.8;
        topMesh.receiveShadow = true;
        islandGroup.add(topMesh);

        // Mushrooms
        const mushrooms = [];
        const mushroomColors = [0x00ffff, 0xff00ff, 0x8800ff, 0x00ff88];

        function createMushroom(x, z, scale) {
            const group = new THREE.Group();

            // Stem
            const stemGeo = new THREE.CylinderGeometry(0.1 * scale, 0.15 * scale, 1 * scale, 8);
            const stemMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.5 });
            const stem = new THREE.Mesh(stemGeo, stemMat);
            stem.position.y = 0.5 * scale;
            stem.castShadow = true;
            group.add(stem);

            // Cap
            const capGeo = new THREE.SphereGeometry(0.6 * scale, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2);
            const color = mushroomColors[Math.floor(Math.random() * mushroomColors.length)];
            const capMat = new THREE.MeshStandardMaterial({
                color: 0x111111,
                emissive: color,
                emissiveIntensity: 2,
                roughness: 0.2,
                metalness: 0.5
            });
            const cap = new THREE.Mesh(capGeo, capMat);
            cap.position.y = 1 * scale;
            cap.castShadow = true;
            group.add(cap);

            // Glow Light
            const light = new THREE.PointLight(color, 2 * scale, 8);
            light.position.y = 1.2 * scale;
            group.add(light);

            // Position on island
            group.position.set(x, 1.9, z);

            // Random rotation
            group.rotation.y = Math.random() * Math.PI * 2;

            // Random tilt
            group.rotation.z = (Math.random() - 0.5) * 0.2;
            group.rotation.x = (Math.random() - 0.5) * 0.2;

            islandGroup.add(group);
            mushrooms.push(group);
        }

        // Generate Mushroom Forest
        for (let i = 0; i < 40; i++) {
            const angle = Math.random() * Math.PI * 2;
            const radius = Math.random() * 2.5; // Keep within island radius
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle) * radius;
            const scale = 0.5 + Math.random() * 1.0;
            createMushroom(x, z, scale);
        }

        // Floating Particles (Spores)
        const particlesGeo = new THREE.BufferGeometry();
        const particleCount = 200;
        const posArray = new Float32Array(particleCount * 3);

        for(let i = 0; i < particleCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 20;
        }

        particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const particlesMat = new THREE.PointsMaterial({
            size: 0.05,
            color: 0x88ccff,
            transparent: true,
            opacity: 0.6,
            blending: THREE.AdditiveBlending
        });
        const particlesMesh = new THREE.Points(particlesGeo, particlesMat);
        scene.add(particlesMesh);

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Float the island
            islandGroup.position.y = Math.sin(time * 0.5) * 0.5;
            islandGroup.rotation.y = Math.sin(time * 0.1) * 0.1;

            // Animate particles
            particlesMesh.rotation.y = time * 0.05;
            particlesMesh.position.y = Math.sin(time * 0.2) * 0.2;

            // Pulse mushroom lights slightly
            mushrooms.forEach((m, i) => {
                const light = m.children[2]; // The point light
                if (light) {
                    light.intensity = 2 + Math.sin(time * 2 + i) * 0.5;
                }
            });

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
